#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 10

#define MCP3008_CH0 0

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up SPI channel
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_BITS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return 1;
    }

    // Set up MCP3008
    if (spiConfigure(spi_handle, SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_BITS) < 0) {
        fprintf(stderr, "Failed to configure MCP3008\n");
        return 1;
    }

    // Set up SIGINT and SIGTERM handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read raw ADC value
        uint16_t adc_value = spiRead(spi_handle, MCP3008_CH0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            return 1;
        }

        // Print timestamp and ADC value
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        printf("%02d:%02d:%02d - ADC value: %d\n", tm->tm_hour, tm->tm_min, tm->tm_sec, adc_value);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum) {
    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    // Exit
    exit(0);
}

void sigterm_handler(int signum) {
    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    // Exit
    exit(0);
}

