#include <string.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_KY026_D0 4
#define GPIO_MCP3008_CE0 8
#define MCP3008_CHANNEL 0
#define MCP3008_SPI_SPEED 1000000

#define CSV_FILE "flame_data.csv"

int main(void) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI device
    int spi_fd = pigpio_spi_open(GPIO_MCP3008_CE0, MCP3008_SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    // Open CSV file for writing
    FILE *csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return 1;
    }

    // Set up GPIO pin for KY026 D0
    if (gpioSetMode(GPIO_KY026_D0, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for KY026 D0\n");
        return 1;
    }

    // Set up SPI transfer
    pigpio_spi_transfer_t transfer;
    transfer.tx_buf = NULL;
    transfer.rx_buf = NULL;
    transfer.len = 0;

    // Main loop
    while (1) {
        // Read KY026 D0
        int flame_detected = gpioRead(GPIO_KY026_D0);

        // Read MCP3008 channel 0
        pigpio_spi_transfer(spi_fd, &transfer);
        uint16_t adc_value = transfer.rx_buf[0] << 8 | transfer.rx_buf[1];

        // Approximate temperature from ADC value
        float temperature = (adc_value / 1023.0) * 40.0;

        // Log timestamped CSV row
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(csv_file, "%s,%d,%f\n", timestamp, flame_detected, temperature);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(csv_file);
    pigpio_spi_close(spi_fd);
    gpioTerminate();

    return 0;
}

