#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <ads1115.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define TEMP_SENSOR_ADDR 0x48
#define TEMP_SENSOR_CHANNEL AIN0
#define TEMP_SENSOR_GAIN 4096
#define TEMP_SENSOR_SPS 128
#define TEMP_SENSOR_VREF 3.3
#define TEMP_SENSOR_VRANGE 20.0
#define TEMP_SENSOR_VMAX 80.0
#define TEMP_SENSOR_TMAX 60.0
#define TEMP_SENSOR_TMIN 20.0
#define TEMP_SENSOR_DEBOUNCE_MS 50
#define TEMP_SENSOR_DEBOUNCE_TICKS (TEMP_SENSOR_DEBOUNCE_MS * 1000 / TEMP_SENSOR_SPS)
#define BUZZER_DURATION_MS 2000

static volatile bool running = true;

static void handle_interrupt(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        // Flame detected
        printf("Flame detected!\n");
    }
}

static void handle_temperature(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        // Temperature above 60°C
        printf("Temperature above 60°C\n");
    }
}

static void handle_buzzer(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        // Buzzer on
        printf("Buzzer on\n");
    } else {
        // Buzzer off
        printf("Buzzer off\n");
    }
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up flame sensor
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for flame sensor\n");
        return 1;
    }
    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for flame sensor\n");
        return 1;
    }
    if (gpioSetISRFunc(FLAME_SENSOR_PIN, EITHER_EDGE, 0, handle_interrupt) < 0) {
        fprintf(stderr, "Failed to set ISR for flame sensor\n");
        return 1;
    }

    // Set up temperature sensor
    if (ads1115_init(TEMP_SENSOR_ADDR, TEMP_SENSOR_CHANNEL, TEMP_SENSOR_GAIN, TEMP_SENSOR_SPS, TEMP_SENSOR_VREF, TEMP_SENSOR_VRANGE, TEMP_SENSOR_VMAX, TEMP_SENSOR_TMAX, TEMP_SENSOR_TMIN) < 0) {
        fprintf(stderr, "Failed to initialize temperature sensor\n");
        return 1;
    }
    if (gpioSetISRFunc(TEMP_SENSOR_CHANNEL, EITHER_EDGE, 0, handle_temperature) < 0) {
        fprintf(stderr, "Failed to set ISR for temperature sensor\n");
        return 1;
    }

    // Set up buzzer
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for buzzer\n");
        return 1;
    }
    if (gpioSetISRFunc(BUZZER_PIN, EITHER_EDGE, 0, handle_buzzer) < 0) {
        fprintf(stderr, "Failed to set ISR for buzzer\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("fire_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Read flame sensor
        int flame_level = gpioRead(FLAME_SENSOR_PIN);
        if (flame_level < 0) {
            fprintf(stderr, "Failed to read flame sensor\n");
            continue;
        }

        // Read temperature sensor
        int temp_level = ads1115_read(TEMP_SENSOR_CHANNEL);
        if (temp_level < 0) {
            fprintf(stderr, "Failed to read temperature sensor\n");
            continue;
        }

        // Check for flame and temperature
        if (flame_level == 0 && temp_level > TEMP_SENSOR_TMAX) {
            // Flame and temperature detected
            printf("Flame and temperature detected!\n");
            fprintf(log_file, "%s\n", "Flame and temperature detected!");
            gpioWrite(BUZZER_PIN, 1);
            sleep(BUZZER_DURATION_MS);
            gpioWrite(BUZZER_PIN, 0);
        } else if (flame_level == 0) {
            // Flame detected
            printf("Flame detected!\n");
            fprintf(log_file, "%s\n", "Flame detected!");
        } else if (temp_level > TEMP_SENSOR_TMAX) {
            // Temperature above 60°C
            printf("Temperature above 60°C\n");
            fprintf(log_file, "%s\n", "Temperature above 60°C");
        }

        // Debounce flame sensor
        if (flame_level == 0) {
            uint32_t tick = gpioTick();
            while (gpioRead(FLAME_SENSOR_PIN) == 0 && gpioTick() - tick < TEMP_SENSOR_DEBOUNCE_TICKS) {
                sleep(1);
            }
        }
    }

    // Clean up
    gpioTerminate();
    fclose(log_file);

    return 0;
}

