#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod.h>
#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_DELAY 0
#define SPI_CS 0
#define SPI_CS_HIGH 1
#define SPI_CS_LOW 0

#define GPIO_CHIP "gpiochip4"
#define GPIO_FAN 18
#define GPIO_FAN_ON 1
#define GPIO_FAN_OFF 0

#define SENSOR_SENSITIVITY 100
#define SENSOR_THRESHOLD 5.0

int main(int argc, char *argv[]) {
    int spi_fd, gpio_fd, fan_fd;
    uint8_t rx[3];
    uint16_t adc_value;
    float current;
    char *gpio_chip = GPIO_CHIP;
    char *fan_pin = "18";
    char *spi_device = SPI_DEVICE;
    char *spi_speed = SPI_SPEED;
    char *spi_mode = SPI_MODE;
    char *spi_bits = SPI_BITS;
    char *spi_delay = SPI_DELAY;
    char *spi_cs = SPI_CS;
    char *spi_cs_high = SPI_CS_HIGH;
    char *spi_cs_low = SPI_CS_LOW;
    char *sensor_sensitivity = SENSOR_SENSITIVITY;
    char *sensor_threshold = SENSOR_THRESHOLD;

    // Open SPI device
    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, spi_mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_SPEED, spi_speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    // Set SPI bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, spi_bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }

    // Set SPI delay
    if (ioctl(spi_fd, SPI_IOC_WR_DELAY, spi_delay) < 0) {
        perror("Failed to set SPI delay");
        close(spi_fd);
        return 1;
    }

    // Set SPI chip select
    if (ioctl(spi_fd, SPI_IOC_WR_CS, spi_cs) < 0) {
        perror("Failed to set SPI chip select");
        close(spi_fd);
        return 1;
    }

    // Set SPI chip select high
    if (ioctl(spi_fd, SPI_IOC_WR_CS_HIGH, spi_cs_high) < 0) {
        perror("Failed to set SPI chip select high");
        close(spi_fd);
        return 1;
    }

    // Set SPI chip select low
    if (ioctl(spi_fd, SPI_IOC_WR_CS_LOW, spi_cs_low) < 0) {
        perror("Failed to set SPI chip select low");
        close(spi_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_fd = gpiod_open(gpio_chip, 0);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }

    // Open fan GPIO pin
    fan_fd = gpiod_open(fan_pin, 0);
    if (fan_fd < 0) {
        perror("Failed to open fan GPIO pin");
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set fan GPIO pin to low
    if (gpiod_set_value(fan_fd, GPIO_FAN_OFF) < 0) {
        perror("Failed to set fan GPIO pin to low");
        close(fan_fd);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set SPI transfer mode
    if (ioctl(spi_fd, SPI_IOC_WR_TRANSFER_MODE, SPI_MODE_0) < 0) {
        perror("Failed to set SPI transfer mode");
        close(fan_fd);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set SPI transfer speed
    if (ioctl(spi_fd, SPI_IOC_WR_TRANSFER_SPEED, SPI_SPEED) < 0) {
        perror("Failed to set SPI transfer speed");
        close(fan_fd);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set SPI transfer bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_TRANSFER_BITS_PER_WORD, SPI_BITS) < 0) {
        perror("Failed to set SPI transfer bits per word");
        close(fan_fd);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set SPI transfer delay
    if (ioctl(spi_fd, SPI_IOC_WR_TRANSFER_DELAY, SPI_DELAY) < 0) {
        perror("Failed to set SPI transfer delay");
        close(fan_fd);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set SPI transfer chip select
    if (ioctl(spi_fd, SPI_IOC_WR_TRANSFER_CS, SPI_CS) < 0) {
        perror("Failed to set SPI transfer chip select");
        close(fan_fd);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set SPI transfer chip select high
    if (ioctl(spi_fd, SPI_IOC_WR_TRANSFER_CS_HIGH, SPI_CS_HIGH) < 0) {
        perror("Failed to set SPI transfer chip select high");
        close(fan_fd);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set SPI transfer chip select low
    if (ioctl(spi_fd, SPI_IOC_WR_TRANSFER_CS_LOW, SPI_CS_LOW) < 0) {
        perror("Failed to set SPI transfer chip select low");
        close(fan_fd);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Read SPI data
    if (read(spi_fd, rx, 3) < 0) {
        perror("Failed to read SPI data");
        close(fan_fd);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Extract ADC value
    adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    // Convert ADC value to current
    current = adc_value * (SENSOR_SENSITIVITY / 1000.0);

    // Check if current exceeds threshold
    if (current > SENSOR_THRESHOLD) {
        // Turn on fan
        if (gpiod_set_value(fan_fd, GPIO_FAN_ON) < 0) {
            perror("Failed to turn on fan");
            close(fan_fd);
            close(gpio_fd);
            close(spi_fd);
            return 1;
        }
    } else {
        // Turn off fan
        if (gpiod_set_value(fan_fd, GPIO_FAN_OFF) < 0) {
            perror("Failed to turn off fan");
            close(fan_fd);
            close(gpio_fd);
            close(spi_fd);
            return 1;
        }
    }

    // Log current reading
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    char log_entry[50];
    sprintf(log_entry, "%s, %f\n", timestamp, current);
    FILE *log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(fan_fd);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }
    fprintf(log_file, log_entry);
    fclose(log_file);

    // Clean up resources
    close(fan_fd);
    close(gpio_fd);
    close(spi_fd);

    return 0;
}

