#define I2C_ADDR 0x58
#define CO_ADC_REG 0x00
#define NO2_ADC_REG 0x02
#define CO_PPM_THRESHOLD 25

int main(int argc, char *argv[]) {
    int i2c_fd;
    uint8_t co_adc_buf[2];
    uint8_t no2_adc_buf[2];
    uint16_t co_adc_val;
    uint16_t no2_adc_val;
    float co_ppm;
    float no2_ppm;
    FILE *co_log_file;
    FILE *alert_log_file;

    // Initialize I2C
    if ((i2c_fd = pigpio_i2c_open(I2C_ADDR)) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    // Initialize CO log file
    if ((co_log_file = fopen("co_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open CO log file\n");
        return 1;
    }

    // Initialize alert log file
    if ((alert_log_file = fopen("alert_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open alert log file\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        // Read CO ADC value
        if (pigpio_i2c_read(i2c_fd, CO_ADC_REG, co_adc_buf, 2) != 2) {
            fprintf(stderr, "Failed to read CO ADC value\n");
            return 1;
        }

        // Read NO2 ADC value
        if (pigpio_i2c_read(i2c_fd, NO2_ADC_REG, no2_adc_buf, 2) != 2) {
            fprintf(stderr, "Failed to read NO2 ADC value\n");
            return 1;
        }

        // Convert ADC values to PPM
        co_adc_val = (co_adc_buf[0] << 8) | co_adc_buf[1];
        no2_adc_val = (no2_adc_buf[0] << 8) | no2_adc_buf[1];
        co_ppm = co_adc_val * 1000.0 / 65535.0;
        no2_ppm = no2_adc_val * 1000.0 / 65535.0;

        // Log CO level
        fprintf(co_log_file, "%.2f\n", co_ppm);

        // Check for alert
        if (co_ppm > CO_PPM_THRESHOLD) {
            fprintf(alert_log_file, "CO level above threshold: %.2f\n", co_ppm);
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    pigpio_i2c_close(i2c_fd);
    fclose(co_log_file);
    fclose(alert_log_file);

    return 0;
}

void signal_handler(int signal) {
    // Clean up
    pigpio_i2c_close(i2c_fd);
    fclose(co_log_file);
    fclose(alert_log_file);

    exit(0);
}

