#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>
#include <unistd.h>

#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1
#define THRESHOLD 0.7
#define SAMPLE_RATE 1000
#define SAMPLE_WINDOW 100
#define LED_PIN 27

int main(int argc, char *argv[]) {
  // Initialize pigpio library
  if (pigpio_start(NULL, NULL) < 0) {
    fprintf(stderr, "Failed to initialize pigpio library\n");
    return 1;
  }

  // Initialize SPI bus
  if (spi_init(0) < 0) {
    fprintf(stderr, "Failed to initialize SPI bus\n");
    return 1;
  }

  // Set up MCP3008 ADC
  if (spi_set_mode(0, SPI_MODE_0) < 0) {
    fprintf(stderr, "Failed to set SPI mode\n");
    return 1;
  }
  if (spi_set_bits_per_word(0, 16) < 0) {
    fprintf(stderr, "Failed to set SPI bits per word\n");
    return 1;
  }
  if (spi_set_speed_hz(0, 1000000) < 0) {
    fprintf(stderr, "Failed to set SPI speed\n");
    return 1;
  }

  // Set up LED pin
  if (gpio_init(LED_PIN) < 0) {
    fprintf(stderr, "Failed to initialize LED pin\n");
    return 1;
  }
  if (gpio_set_mode(LED_PIN, GPIO_OUTPUT) < 0) {
    fprintf(stderr, "Failed to set LED pin mode\n");
    return 1;
  }

  // Open CSV file for logging
  FILE *fp = fopen("audio_events.csv", "w");
  if (fp == NULL) {
    fprintf(stderr, "Failed to open CSV file\n");
    return 1;
  }

  // Main loop
  while (1) {
    // Read samples from both microphones
    int16_t mic1_samples[SAMPLE_WINDOW];
    int16_t mic2_samples[SAMPLE_WINDOW];
    for (int i = 0; i < SAMPLE_WINDOW; i++) {
      mic1_samples[i] = spi_read_adc(MIC1_CHANNEL);
      mic2_samples[i] = spi_read_adc(MIC2_CHANNEL);
    }

    // Calculate RMS values for both microphones
    float mic1_rms = 0;
    float mic2_rms = 0;
    for (int i = 0; i < SAMPLE_WINDOW; i++) {
      mic1_rms += mic1_samples[i] * mic1_samples[i];
      mic2_rms += mic2_samples[i] * mic2_samples[i];
    }
    mic1_rms = sqrt(mic1_rms / SAMPLE_WINDOW);
    mic2_rms = sqrt(mic2_rms / SAMPLE_WINDOW);

    // Check if either microphone exceeds threshold
    if (mic1_rms > THRESHOLD || mic2_rms > THRESHOLD) {
      // Turn on LED
      gpio_write(LED_PIN, 1);
      // Log event to CSV file
      fprintf(fp, "%ld, %f, %f\n", time(NULL), mic1_rms, mic2_rms);
      // Wait for 500 ms
      usleep(500000);
      // Turn off LED
      gpio_write(LED_PIN, 0);
    }

    // Wait for 1 ms
    usleep(1000);
  }

  // Clean up
  fclose(fp);
  spi_close(0);
  gpio_close(LED_PIN);
  pigpio_stop();

  return 0;
}

