#define I2C_ADDR 0x29
#define I2C_BUS 1
#define ATIME_REG 0x01
#define CONTROL_REG 0x0F
#define ENABLE_REG 0x00
#define CLEAR_REG 0x14
#define RED_REG 0x15
#define GREEN_REG 0x16
#define BLUE_REG 0x17

#define ID_REG 0x12
#define ID_EXPECTED 0x44

#define ATIME_VAL 0xFF
#define CONTROL_VAL 0x01
#define ENABLE_VAL 0x01 | 0x02

#define CSV_FILE "color_log.csv"

int main(void) {
    int i2c_handle;
    int ret;
    uint8_t id;
    uint16_t clear, red, green, blue;
