    if (!sclk_line) {
        fprintf(stderr, "Failed to get SCLK line\n");
        return 1;
    }

    // Set up SPI mode
    struct spi_ioc_transfer spi_xfer;
    spi_xfer.tx_buf = (uint8_t *)&spi_xfer.tx_buf;
    spi_xfer.rx_buf = (uint8_t *)&spi_xfer.rx_buf;
    spi_xfer.len = 1;
    spi_xfer.speed_hz = 1000000;
    spi_xfer.bits_per_word = 8;
    spi_xfer.delay_usecs = 0;
    spi_xfer.cs_change = 0;
    spi_xfer.tx_nbits = 8;
    spi_xfer.rx_nbits = 8;
