        uint16_t moisture_ch1 = read_moisture(chip, cs_line, miso_line, mosi_line, sclk_line, MCP3008_ADDR, MCP3008_CH1);

        // Map raw ADC values to 0-100% moisture scale
        uint8_t moisture_percent_ch0 = (uint8_t)(((float)moisture_ch0 / 1023.0) * 100.0);
