    // Set chip-select line low
    gpiod_line_set_value(cs_line, 0);

    // Send address and channel to MCP3008
    uint8_t tx_buf[2] = {addr, channel};
    struct spi_ioc_transfer spi_xfer;
    spi_xfer.tx_buf = (uint8_t *)&tx_buf;
    spi_xfer.rx_buf = (uint8_t *)&spi_xfer.rx_buf;
    spi_xfer.len = 2;
    spi_xfer.speed_hz = 1000000;
    spi_xfer.bits_per_word = 8;
    spi_xfer.delay_usecs = 0;
    spi_xfer.cs_change = 0;
    spi_xfer.tx_nbits = 8;
    spi_xfer.rx_nbits = 8;
    spi_xfer.pad = 0;
    ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer);

    // Read 10-bit ADC value
    uint8_t rx_buf[2];
    spi_xfer.tx_buf = NULL;
    spi_xfer.rx_buf = (uint8_t *)&rx_buf;
    spi_xfer.len = 2;
    spi_xfer.speed_hz = 1000000;
    spi_xfer.bits_per_word = 8;
    spi_xfer.delay_usecs = 0;
    spi_xfer.cs_change = 0;
    spi_xfer.tx_nbits = 0;
    spi_xfer.rx_nbits = 16;
    spi_xfer.pad = 0;
    ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer);

    // Set chip-select line high
    gpiod_line_set_value(cs_line, 1);

    // Return 10-bit ADC value
    return (rx_buf[0] << 2) | (rx_buf[1] >> 6);
}

