 Here is the complete, compilable C code for the Raspberry Pi 4 Model B to interface with a Melexis MLX91211 Triaxis Current Sensor, logging current readings in Amperes to a comma-separated current_log.csv file, and simulating an overcurrent safety system for a DC motor.
```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod/libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define MCP3008_CHANNEL 0
#define MOTOR_SHUTDOWN_PIN 17
#define CURRENT_LOG_FILE "current_log.csv"
#define CURRENT_LOG_HEADER "timestamp,current_in_Amperes\n"

#define SENSITIVITY 0.1
#define OFFSET 0.05
#define MAX_CURRENT 10.0

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static void sigterm_handler(int signum) {
    running = 0;
}

static void init_gpio(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, MOTOR_SHUTDOWN_PIN);
    if (!line) {
        fprintf(stderr, "Error: unable to get GPIO line\n");
        exit(1);
    }

    gpiod_line_request_output(line, "motor_shutdown", 0);
    gpiod_line_set_value(line, 1);

    gpiod_chip_close(chip);
}

static void init_spi(void) {
    int fd;
    struct spi_ioc_transfer xfer;

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: unable to open SPI device\n");
        exit(1);
    }

    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = (unsigned long)NULL;
    xfer.rx_buf = (unsigned long)NULL;
    xfer.len = 0;
    xfer.delay_usecs = 0;
    xfer.speed_hz = 1000000;
    xfer.bits_per_word = 8;
    xfer.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        fprintf(stderr, "Error: unable to configure SPI device\n");
        exit(1);
    }

    close(fd);
}

static void read_current(double *current) {
    int fd;
    struct spi_ioc_transfer xfer;
    uint16_t adc_value;
    double voltage;

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error: unable to open SPI device\n");
        exit(1);
    }

    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = (unsigned long)NULL;
    xfer.rx_buf = (unsigned long)&adc_value;
    xfer.len = 2;
    xfer.delay_usecs = 0;
    xfer.speed_hz = 1000000;
    xfer.bits_per_word = 8;
    xfer.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
        fprintf(stderr, "Error: unable to read from SPI device\n");
        exit(1);
    }

    close(fd);

    voltage = (adc_value * 3.3) / 1023;
    *current = (voltage - OFFSET) / SENSITIVITY;
}

static void log_current(double current) {
    FILE *fp;
    char buf[100];
    time_t t;
    struct tm *tm;

    fp = fopen(CURRENT_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: unable to open current log file\n");
        exit(1);
    }

    time(&t);
    tm = localtime(&t);
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s,%.2f\n", buf, current);

    fclose(fp);
}

static void motor_shutdown(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, MOTOR_SHUTDOWN_PIN);
    if (!line) {
        fprintf(stderr, "Error: unable to get GPIO line\n");
        exit(1);
    }

    gpiod_line_set_value(line, 0);

    gpiod_chip_close(chip);
}

static void motor_start(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, MOTOR_SHUTDOWN_PIN);
    if (!line) {
        fprintf(stderr, "Error: unable to get GPIO line\n");
        exit(1);
    }

    gpiod_line_set_value(line, 1);

    gpiod_chip_close(chip);
}

int main(void) {
    double current;
    int retries = 0;

    init_gpio();
    init_spi();

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (running) {
        read_current(&current);
        log_current(current);

        if (current > MAX_CURRENT) {
            motor_shutdown();
            log_current(current);
            sleep(1);
            motor_start();
        }

        sleep(1);
    }

    return 0;
}
```
This code uses the `libgpiod` library to control the GPIO pins on the Raspberry Pi, and the `spidev` library to communicate with the MCP3008 ADC over hardware SPI. It reads the current sensor value every second, converts it to a voltage, and then to current using the sensitivity and offset values. If the current exceeds the maximum allowed value, it shuts down the motor and waits for 1 second before re-enabling it. The code also handles SIGINT and SIGTERM signals to gracefully shut down the program and release the GPIO lines.

