#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define REG_PRESSURE 0x00

#define PRESSURE_KPA_FACTOR 500.0

static FILE *log_file;
static int i2c_handle;

static void sigint_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
    if (i2c_handle) {
        pigpio_i2c_close(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main(void) {
    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open the log file
    log_file = fopen("pressure_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }
    fprintf(log_file, "timestamp,pressure_kPa\n");

    // Open the I2C bus
    i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR);
    if (!i2c_handle) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Main loop
    while (1) {
        // Read the pressure value
        uint16_t raw_value;
        int ret = pigpio_i2c_read(i2c_handle, REG_PRESSURE, &raw_value, 2);
        if (ret != 0) {
            fprintf(stderr, "Failed to read pressure value from register 0x%02x: %s\n", REG_PRESSURE, pigpio_error_string(ret));
            continue;
        }

        // Convert the pressure value to kPa
        double pressure_kPa = (raw_value / 65535.0) * PRESSURE_KPA_FACTOR;

        // Log the pressure value
        time_t now = time(NULL);
        struct tm *tm = gmtime(&now);
        fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02dZ,%f\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, pressure_kPa);
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fflush(log_file);
    fclose(log_file);
    pigpio_i2c_close(i2c_handle);
    gpioTerminate();

    return 0;
}

