#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define MCP3008_SPI_CHANNEL 0
#define MCP3008_SPI_SPEED 1000000
#define MCP3008_SPI_MODE 0
#define MCP3008_SINGLE_ENDED_CHANNEL 0
#define MCP3008_ZERO_PAD_BYTE 0
#define MLX91209_ZERO_CURRENT_MIDPOINT 1.65
#define MLX91209_SENSITIVITY 0.066
#define CURRENT_LOG_FILE "current_log.txt"
#define OVERCURRENT_THRESHOLD 10.0

int main(void) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open SPI handle
    int spi_handle = spiOpen(MCP3008_SPI_CHANNEL, MCP3008_SPI_SPEED, MCP3008_SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(CURRENT_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up safety monitor
    int safety_monitor_gpio = 27;
    gpioSetMode(safety_monitor_gpio, PI_OUTPUT);
    gpioWrite(safety_monitor_gpio, PI_LOW);

    // Main loop
    while (1) {
        // Read current from sensor
        uint8_t spi_tx_buf[3] = {0x01, MCP3008_SINGLE_ENDED_CHANNEL, MCP3008_ZERO_PAD_BYTE};
        uint8_t spi_rx_buf[3];
        if (spiTransfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) < 0) {
            fprintf(stderr, "Failed to transfer data over SPI\n");
            spiClose(spi_handle);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        // Extract 10-bit ADC reading
        uint16_t adc_reading = (spi_rx_buf[2] << 8) | spi_rx_buf[1];

        // Convert ADC reading to voltage
        float voltage = (float)adc_reading / 1024.0 * 3.3;

        // Convert voltage to current
        float current = voltage / MLX91209_SENSITIVITY;

        // Log current reading
        time_t current_time = time(NULL);
        fprintf(log_file, "%s, %f\n", ctime(&current_time), current);
        fflush(log_file);

        // Check for overcurrent
        if (current > OVERCURRENT_THRESHOLD) {
            gpioWrite(safety_monitor_gpio, PI_HIGH);
            fprintf(log_file, "OVERCURRENT\n");
            fflush(log_file);
            break;
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

