#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_BUS 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ALARM_GPIO 4
#define LOG_FILE "co_log.txt"

int main(void) {
    // Initialize the GPIO and SPI interfaces
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (spiOpen(SPI_BUS, SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up the alarm GPIO
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set alarm GPIO mode\n");
        spiClose(SPI_BUS);
        gpioTerminate();
        return 1;
    }

    // Set up the log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up the SPI transfer function
    spiTransfer transfer_func = spiGetTransferFunc(SPI_BUS, SPI_CHANNEL);
    if (transfer_func == NULL) {
        fprintf(stderr, "Failed to get SPI transfer function\n");
        fclose(log_file);
        spiClose(SPI_BUS);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the ADC value
        uint16_t adc_value;
        if (transfer_func(&adc_value, 1) < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            fclose(log_file);
            spiClose(SPI_BUS);
            gpioTerminate();
            return 1;
        }

        // Convert the ADC value to a voltage
        float voltage = (float)adc_value / 1024.0 * 3.3;

        // Check if the voltage exceeds the threshold
        if (voltage > 2.5) {
            // Turn on the alarm
            gpioWrite(ALARM_GPIO, PI_HIGH);
        } else {
            // Turn off the alarm
            gpioWrite(ALARM_GPIO, PI_LOW);
        }

        // Log the reading to the log file
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(log_file, "%s,Voltage: %.2f V\n", time_str, voltage);

        // Wait for 1 second before reading again
        sleep(1);
    }

    // Clean up on exit
    fclose(log_file);
    spiClose(SPI_BUS);
    gpioTerminate();

    return 0;
}

