#include <mcp3008.h>

#define METHANE_SENSOR_CHANNEL 0
#define METHANE_SENSOR_PPM_MIN 0
#define METHANE_SENSOR_PPM_MAX 5000
#define METHANE_SENSOR_PPM_RANGE (METHANE_SENSOR_PPM_MAX - METHANE_SENSOR_PPM_MIN)
#define METHANE_SENSOR_ADC_MIN 0
#define METHANE_SENSOR_ADC_MAX 1023
#define METHANE_SENSOR_ADC_RANGE (METHANE_SENSOR_ADC_MAX - METHANE_SENSOR_ADC_MIN)

#define METHANE_LOG_FILE "methane_log.txt"

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI bus 0
    int spi_handle = spiOpen(0, 1000000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI bus 0\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(METHANE_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up SPI transfer command
    uint8_t spi_cmd[3] = {0x01, 0x80, 0x00};

    // Main loop
    while (1) {
        // Read ADC value
        uint8_t rx[3];
        if (spiXfer(spi_handle, spi_cmd, rx, 3) < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

