#define MIN_PRESSURE 0
#define MAX_PRESSURE 100

int main(void) {
    // Initialize I2C bus
    if (pigpio_start(NULL, 1) < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        return 1;
    }

    // Initialize ADC
    ads1115_t adc;
    if (ads1115_init(&adc, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to initialize ADC\n");
        return 1;
    }

    // Set ADC gain to 1
    if (ads1115_set_gain(&adc, 1) < 0) {
        fprintf(stderr, "Failed to set ADC gain\n");
        return 1;
    }

    // Set ADC mode to single-shot
    if (ads1115_set_mode(&adc, ADS1115_MODE_SINGLE) < 0) {
        fprintf(stderr, "Failed to set ADC mode\n");
        return 1;
    }

    // Set ADC channel to AIN0
    if (ads1115_set_channel(&adc, AIN0) < 0) {
        fprintf(stderr, "Failed to set ADC channel\n");
        return 1;
    }

    // Open pressure log file
    FILE *fp = fopen("pressure_log.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open pressure log file\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        int16_t adc_value;
        if (ads1115_read(&adc, &adc_value) < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            return 1;
        }

        // Convert ADC value to voltage
        double voltage = (double)adc_value * 0.001;

        // Convert voltage to pressure
        double pressure = (voltage - VOLTAGE_OFFSET) * SENSITIVITY;

        // Check pressure range
        if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
            fprintf(stderr, "Invalid pressure range\n");
            return 1;
        }

        // Log pressure reading
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02dZ,%.3f\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, pressure);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(fp);
    ads1115_close(&adc);
    pigpio_stop();

    return 0;
}

