#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/spi/spidev.h>
#include <libgpiod/libgpiod.h>

#define TMP36_VREF 3.3
#define TMP36_RANGE 125
#define TMP36_MIN -40

#define MCP3208_CH0 0
#define MCP3208_CH1 1
#define MCP3208_CH2 2
#define MCP3208_CH3 3
#define MCP3208_CH4 4
#define MCP3208_CH5 5
#define MCP3208_CH6 6
#define MCP3208_CH7 7

#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED 1000000

#define GPIO_CHIP_4 4
#define GPIO_CS 8

#define LOG_FILE "temperature_log.csv"

int main(int argc, char *argv[]) {
    // Open the SPI device
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set the SPI mode, bits per word, and max speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED, &SPI_MAX_SPEED) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        return 1;
    }

    // Open the GPIO chip
    int gpio_fd = gpiod_open(GPIO_CHIP_4, GPIO_CS, GPIO_OUT);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }

    // Set the GPIO line to low
    if (gpiod_set_value(gpio_fd, 0) < 0) {
        perror("Failed to set GPIO line to low");
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Write the header to the log file if it's a new file
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }

    // Read the ADC value
    uint16_t adc_value;
    if (read(spi_fd, &adc_value, sizeof(adc_value)) < 0) {
        perror("Failed to read ADC value");
        close(log_file);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Convert the ADC value to a voltage
    float voltage = (float)adc_value * TMP36_VREF / 4095.0;

    // Convert the voltage to Celsius
    float temperature = (voltage - 0.5) / 0.01;

    // Check if the temperature is within the valid range
    if (temperature < TMP36_MIN || temperature > TMP36_RANGE) {
        fprintf(stderr, "Invalid temperature: %f\n", temperature);
        close(log_file);
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Log the temperature to the log file
    time_t timestamp = time(NULL);
    fprintf(log_file, "%ld,%.2f\n", timestamp, temperature);

    // Close the log file
    fclose(log_file);

    // Close the GPIO chip
    gpiod_close(gpio_fd);

    // Close the SPI device
    close(spi_fd);

    return 0;
}

