#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define ADXL335_CS_PIN 8
#define ADXL335_SPI_CHANNEL 0
#define ADXL335_SPI_SPEED 1000000
#define ADXL335_SPI_MODE 0
#define ADXL335_SPI_BITS 10
#define ADXL335_SPI_DELAY 0

#define ADXL335_X_CHANNEL 0
#define ADXL335_Y_CHANNEL 1
#define ADXL335_Z_CHANNEL 2

#define ADXL335_0G_POINT 1.65
#define ADXL335_SENSITIVITY 300

#define IMPACT_THRESHOLD 2.0

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("impact_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up SPI
    if (spiOpen(ADXL335_SPI_CHANNEL, ADXL335_SPI_SPEED, ADXL335_SPI_MODE, ADXL335_SPI_BITS, ADXL335_SPI_DELAY) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        return 1;
    }

    // Set up CS pin
    if (gpioSetMode(ADXL335_CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CS pin mode\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read X, Y, Z values from ADXL335
        uint16_t x_value = 0;
        uint16_t y_value = 0;
        uint16_t z_value = 0;
        if (spiXfer(ADXL335_SPI_CHANNEL, ADXL335_X_CHANNEL, &x_value, 1) < 0) {
            fprintf(stderr, "Failed to read X value\n");
            return 1;
        }
        if (spiXfer(ADXL335_SPI_CHANNEL, ADXL335_Y_CHANNEL, &y_value, 1) < 0) {
            fprintf(stderr, "Failed to read Y value\n");
            return 1;
        }
        if (spiXfer(ADXL335_SPI_CHANNEL, ADXL335_Z_CHANNEL, &z_value, 1) < 0) {
            fprintf(stderr, "Failed to read Z value\n");
            return 1;
        }

        // Compute acceleration magnitude
        float x_accel = (x_value - ADXL335_0G_POINT) / ADXL335_SENSITIVITY;
        float y_accel = (y_value - ADXL335_0G_POINT) / ADXL335_SENSITIVITY;
        float z_accel = (z_value - ADXL335_0G_POINT) / ADXL335_SENSITIVITY;
        float accel_mag = sqrt(x_accel * x_accel + y_accel * y_accel + z_accel * z_accel);

        // Check for impact
        if (accel_mag > IMPACT_THRESHOLD) {
            fprintf(log_file, "IMPACT DETECTED\n");
        }

        // Log values
        fprintf(log_file, "%ld, %d, %d, %d\n", time(NULL), x_value, y_value, z_value);

        // Wait for next sample
        usleep(10000);
    }

    // Clean up
    spiClose(ADXL335_SPI_CHANNEL);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

