#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define CMD_REG 0xC0
#define FIFO_REG 0xC1
#define DATA_REG 0xC1
#define DATA_LEN 4

#define HR_REG 0xC1
#define SPO2_REG 0xC2

#define HR_MASK 0xFF00
#define SPO2_MASK 0x00FF

#define HR_SHIFT 8
#define SPO2_SHIFT 0

#define HR_MAX 255
#define SPO2_MAX 100

#define ERROR_OK 0
#define ERROR_READ 1
#define ERROR_SENSOR 2

int i2c_handle;
FILE *log_file;

void sigint_handler(int signum) {
    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    pigpioTerminate();

    // Close log file
    fclose(log_file);

    // Exit program
    exit(0);
}

int main(void) {
    // Initialize pigpio
    if (pigpioInit() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C handle
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Write header row to log file
    fprintf(log_file, "timestamp,HR,SpO2,error\n");

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Write command to trigger measurement
        if (i2cWriteByte(i2c_handle, CMD_REG, 0x01) < 0) {
            fprintf(stderr, "Failed to write command register\n");
            return 1;
        }

        // Read FIFO or data registers
        uint8_t data[DATA_LEN];
        if (i2cReadBytes(i2c_handle, FIFO_REG, data, DATA_LEN) < 0) {
            fprintf(stderr, "Failed to read FIFO or data registers\n");
            return 1;
        }

        // Extract HR and SpO2 values from raw PPG samples
        uint16_t hr = (data[HR_REG] & HR_MASK) >> HR_SHIFT;
        uint16_t spo2 = (data[SPO2_REG] & SPO2_MASK) >> SPO2_SHIFT;

        // Check for errors
        if (hr > HR_MAX || spo2 > SPO2_MAX) {
            fprintf(stderr, "Invalid HR or SpO2 value\n");
            return 1;
        }

