#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <mcp3008.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define ADC_SCALE 3.3
#define FLOW_RANGE 5.0
#define FLOW_MIN 0.0
#define FLOW_MAX 5.0

int main(void) {
    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI channel 0
    int spi_fd = pigpio_spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        pigpio_stop();
        return 1;
    }

    // Open ADC channel 0
    int adc_fd = pigpio_adc_open(ADC_CHANNEL);
    if (adc_fd < 0) {
        fprintf(stderr, "Failed to open ADC channel %d\n", ADC_CHANNEL);
        pigpio_spi_close(spi_fd);
        pigpio_stop();
        return 1;
    }

    // Open file for logging
    FILE *fp = fopen("flow_log.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for logging\n");
        pigpio_adc_close(adc_fd);
        pigpio_spi_close(spi_fd);
        pigpio_stop();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read flow rate from ADC
        uint16_t adc_value = pigpio_adc_read(adc_fd);
        if (adc_value == 0 || adc_value == 0xFFFF) {
            fprintf(stderr, "Sensor not present or error reading ADC\n");
            continue;
        }

        // Convert ADC value to flow rate
        float flow_rate = (float)adc_value / ADC_SCALE * FLOW_RANGE;

        // Check flow rate range
        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            fprintf(stderr, "Flow rate out of range: %f\n", flow_rate);
            continue;
        }

        // Log flow rate
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%f", localtime(&now));
        fprintf(fp, "%s,%f\n", timestamp, flow_rate);
        fflush(fp);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(fp);
    pigpio_adc_close(adc_fd);
    pigpio_spi_close(spi_fd);
    pigpio_stop();

    return 0;
}

void sigint_handler(int signum) {
    fprintf(stderr, "Received SIGINT\n");
    pigpio_adc_close(adc_fd);
    pigpio_spi_close(spi_fd);
    pigpio_stop();
    exit(1);
}

void sigterm_handler(int signum) {
    fprintf(stderr, "Received SIGTERM\n");
    pigpio_adc_close(adc_fd);
    pigpio_spi_close(spi_fd);
    pigpio_stop();
    exit(1);
}

