#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x67
#define I2C_MEASURE_CMD 0x6845
#define I2C_READ_CMD 0x6846
#define I2C_WRITE_CMD 0x6847
#define I2C_CRC_CMD 0x6848

#define I2C_DEV_PATH "/dev/i2c-1"
#define CSV_FILE_PATH "environmental_data.csv"

#define TDK_CALIBRATION_FACTOR 1.0
#define TDK_CALIBRATION_OFFSET 0.0

#define SENSOR_ABSENT_ERROR -1
#define BUS_ERROR_ERROR -2

#define RETRY_DELAY 5

int main(void) {
    int i2c_fd;
    int csv_fd;
    int ret;
    uint8_t buf[6];
    uint16_t pressure;
    uint16_t temperature;
    uint8_t crc;
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data ioctl_data;
    struct timespec ts;

    // Open I2C device
    i2c_fd = open(I2C_DEV_PATH, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Open CSV file
    csv_fd = open(CSV_FILE_PATH, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (csv_fd < 0) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Set up I2C message
    msg.addr = I2C_ADDR;
    msg.flags = 0;
    msg.len = 1;
    msg.buf = &I2C_MEASURE_CMD;

    // Set up I2C read message
    ioctl_data.msgs = &msg;
    ioctl_data.nmsgs = 1;

    // Set up timestamp
    clock_gettime(CLOCK_REALTIME, &ts);

    // Loop forever
    while (1) {
        // Send measurement command
        ret = ioctl(i2c_fd, I2C_RDWR, &ioctl_data);
        if (ret < 0) {
            perror("Failed to send measurement command");
            goto error;
        }

        // Wait for conversion to finish
        sleep(1);

        // Read pressure and temperature
        ret = read(i2c_fd, buf, 6);
        if (ret < 0) {
            perror("Failed to read pressure and temperature");
            goto error;
        }

        // Extract pressure and temperature
        pressure = (buf[0] << 8) | buf[1];
        temperature = (buf[2] << 8) | buf[3];
        crc = buf[4];

        // Apply calibration formula
        pressure = (pressure * TDK_CALIBRATION_FACTOR) + TDK_CALIBRATION_OFFSET;
        temperature = (temperature * TDK_CALIBRATION_FACTOR) + TDK_CALIBRATION_OFFSET;

        // Log data to CSV file
        fprintf(csv_fd, "%ld,%d,%d,%d\n", ts.tv_sec, pressure, temperature, crc);

        // Display data on console
        printf("Timestamp: %ld\n", ts.tv_sec);
        printf("Pressure: %d Pa\n", pressure);
        printf("Temperature: %d °C\n", temperature);
        printf("CRC: %d\n", crc);

        // Wait for next measurement
        sleep(5);
    }

error:
    // Close I2C device
    close(i2c_fd);

    // Close CSV file
    close(csv_fd);

    return 0;
}

void sigint_handler(int signum) {
    printf("Received SIGINT\n");
    close(i2c_fd);
    close(csv_fd);
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM\n");
    close(i2c_fd);
    close(csv_fd);
    exit(0);
}

