#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <mcp3008.h>

#define SAMPLE_RATE 44100
#define BUFFER_SIZE 1024
#define CHANNELS 2
#define GAIN_MIN 0
#define GAIN_MAX 10

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    int gain = 5;
    if (argc > 1) {
        gain = atoi(argv[1]);
        if (gain < GAIN_MIN || gain > GAIN_MAX) {
            fprintf(stderr, "Invalid gain value: %d\n", gain);
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up SPI0
    if (spiOpen(0, 8, 0, 0, 0, 0, 0, 0) < 0) {
        fprintf(stderr, "Failed to open SPI0\n");
        return 1;
    }

    // Set up MCP3008
    if (mcp3008Init(0, 0, 0, 0, 0, 0, 0, 0) < 0) {
        fprintf(stderr, "Failed to initialize MCP3008\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Set up audio buffers
    uint16_t buffer[BUFFER_SIZE];
    uint16_t noise[BUFFER_SIZE];

    // Set up gain control
    uint16_t gain_factor = (gain * 256) / 10;

    // Main loop
    while (running) {
        // Read audio data from microphones
        if (mcp3008Read(0, buffer, BUFFER_SIZE) < 0) {
            fprintf(stderr, "Failed to read audio data from microphones\n");
            return 1;
        }

        // Read noise data from microphones
        if (mcp3008Read(0, noise, BUFFER_SIZE) < 0) {
            fprintf(stderr, "Failed to read noise data from microphones\n");
            return 1;
        }

        // Subtract noise from audio data
        for (int i = 0; i < BUFFER_SIZE; i++) {
            buffer[i] -= noise[i];
        }

        // Apply gain control
        for (int i = 0; i < BUFFER_SIZE; i++) {
            buffer[i] *= gain_factor;
        }

        // Output audio data to terminal
        for (int i = 0; i < BUFFER_SIZE; i++) {
            printf("%d,", buffer[i]);
        }
        printf("\n");
    }

    // Clean up
    mcp3008Close(0);
    spiClose(0);
    gpioTerminate();

    return 0;
}

