#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <spi/spidev.h>

#define BUZZER_PIN 18
#define ADC_CHANNEL 0
#define ADC_BITS 10
#define ADC_MAX_VALUE (1 << ADC_BITS) - 1
#define ADC_MIN_VALUE 0
#define ADC_VREF 3.3
#define ADC_SCALE (ADC_VREF / ADC_MAX_VALUE)
#define TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define SAMPLE_INTERVAL 500

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return 1;
    }

    // Open SPI device
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return 1;
    }

    // Set up SPI mode 0 (CPOL=0, CPHA=0) at 1 MHz
    struct spi_ioc_transfer spi_xfer;
    memset(&spi_xfer, 0, sizeof(spi_xfer));
    spi_xfer.bits_per_word = ADC_BITS;
    spi_xfer.speed_hz = 1000000;
    spi_xfer.delay_usecs = 0;
    spi_xfer.tx_nbits = 3;
    spi_xfer.rx_nbits = 3;
    spi_xfer.tx_buf = (unsigned long)malloc(spi_xfer.tx_nbits);
    spi_xfer.rx_buf = (unsigned long)malloc(spi_xfer.rx_nbits);
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer) < 0) {
        fprintf(stderr, "Error setting up SPI mode: %s\n", strerror(errno));
        return 1;
    }

    // Set up GPIO buzzer
    struct gpiod_chip *buzzer_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!buzzer_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }
    struct gpiod_line *buzzer_line = gpiod_chip_get_line(buzzer_chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        return 1;
    }
    gpiod_line_request_output(buzzer_line, "buzzer", 0);

    // Read ambient temperature
    float ambient_temp = 25.0;
    FILE *temp_file = fopen(TEMP_FILE, "r");
    if (temp_file) {
        fscanf(temp_file, "%f", &ambient_temp);
        fclose(temp_file);
    }

    // Main loop
    while (running) {
        // Read ADC value
        uint16_t adc_value = 0;
        int retries = 3;
        while (retries > 0) {
            if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer) < 0) {
                fprintf(stderr, "Error reading ADC value: %s\n", strerror(errno));
                retries--;
                continue;
            }
            adc_value = (spi_xfer.rx_buf[1] << 8) | spi_xfer.rx_buf[2];
            if (adc_value < ADC_MIN_VALUE || adc_value > ADC_MAX_VALUE) {
                fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
                retries--;
                continue;
            }
            break;
        }
        if (retries == 0) {
            fprintf(stderr, "Error reading ADC value: %s\n", strerror(errno));
            continue;
        }

        // Compute compensated voltage
        float voltage = adc_value * ADC_SCALE;
        float compensated_voltage = voltage + (ambient_temp - 25.0) * 0.001;

        // Detect flame
        int flame_detected = compensated_voltage > 1.0;

        // Log reading
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, %d, %f, %f, %f, %d\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec,
            adc_value, voltage, compensated_voltage, ambient_temp, flame_detected);

        // Update buzzer state
        gpiod_line_set_value(buzzer_line, flame_detected);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Clean up
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(buzzer_chip);
    free(spi_xfer.tx_buf);
    free(spi_xfer.rx_buf);
    close(spi_fd);
    fclose(log_file);

    return 0;
}

