#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_FLAGS 0
#define MCP3008_CHANNEL 0
#define LED_GPIO 17
#define WATER_LEVEL_THRESHOLD_HIGH 75
#define WATER_LEVEL_THRESHOLD_LOW 70

int main(void) {
    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI channel 0
    int spi_handle = pigpio_spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        pigpio_stop();
        return 1;
    }

    // Open JSON file for logging
    FILE *json_file = fopen("water_levels.json", "w");
    if (json_file == NULL) {
        fprintf(stderr, "Failed to open JSON file\n");
        pigpio_spi_close(spi_handle);
        pigpio_stop();
        return 1;
    }

    // Set up LED as output
    if (pigpio_gpio_mode_set(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED GPIO %d as output\n", LED_GPIO);
        fclose(json_file);
        pigpio_spi_close(spi_handle);
        pigpio_stop();
        return 1;
    }

    // Set up SIGINT and SIGTERM handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read water level from MCP3008
        uint8_t rx[3];
        if (pigpio_spi_xfer(spi_handle, 0x01, 0x80 | MCP3008_CHANNEL << 4, 0x00, rx, 3) < 0) {
            fprintf(stderr, "Failed to read from MCP3008\n");
            continue;
        }

        // Parse ADC value
        uint16_t adc_value = ((rx[1] & 0x03) << 8) | rx[2];
        float water_level = (float)adc_value / 1023.0 * 100.0;

        // Print water level to stdout
        printf("Water level: %.2f%%\n", water_level);

        // Log water level to JSON file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%FT%T.%LZ", gmtime(&now));
        fprintf(json_file, "{\"timestamp\":\"%s\",\"water_level\":%.2f}\n", timestamp, water_level);
        fflush(json_file);

        // Turn LED on or off based on water level
        if (water_level > WATER_LEVEL_THRESHOLD_HIGH) {
            pigpio_gpio_write(LED_GPIO, 1);
        } else if (water_level < WATER_LEVEL_THRESHOLD_LOW) {
            pigpio_gpio_write(LED_GPIO, 0);
        }

        // Sleep for 5 seconds
        gpioDelay(5000);
    }

    // Clean up on shutdown
    fclose(json_file);
    pigpio_spi_close(spi_handle);
    pigpio_stop();

    return 0;
}

void sigint_handler(int signum) {
    // Stop the main loop
    printf("Stopping main loop\n");
    return;
}

void sigterm_handler(int signum) {
    // Close the SPI handle
    pigpio_spi_close(spi_handle);

    // Turn off the LED
    pigpio_gpio_write(LED_GPIO, 0);

    // Terminate pigpio
    pigpio_stop();

    // Close the JSON file
    fclose(json_file);

    // Exit the program
    printf("Exiting program\n");
    exit(0);
}

