#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define AWM7300V_CHANNEL 0
#define MCP3008_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 10
#define SPI_DELAY 0
#define SPI_CS_PIN 24
#define SPI_SCLK_PIN 23
#define SPI_MOSI_PIN 19
#define SPI_MISO_PIN 21
#define FILE_NAME "airflow_log.csv"

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up SPI
    int spi_handle = spiOpen(SPI_SPEED, SPI_MODE, SPI_BITS, SPI_DELAY, SPI_CS_PIN, SPI_SCLK_PIN, SPI_MOSI_PIN, SPI_MISO_PIN);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        return 1;
    }

    // Set up file
    FILE *file = fopen(FILE_NAME, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file %s\n", FILE_NAME);
        return 1;
    }

    // Write CSV header if file is new
    if (file->size == 0) {
        fprintf(file, "timestamp,flow_rate\n");
    }

    // Main loop
    while (1) {
        // Read flow rate from sensor
        int flow_rate = spiRead(spi_handle, AWM7300V_CHANNEL);
        if (flow_rate < 0) {
            fprintf(stderr, "Failed to read flow rate from sensor\n");
            return 1;
        }

        // Convert flow rate to LPM
        int lpm = flow_rate * 60 / 1000;

        // Get current timestamp
        time_t timestamp = time(NULL);

        // Write timestamp and flow rate to file
        fprintf(file, "%s,%d\n", ctime(&timestamp), lpm);

        // Sleep for 100 milliseconds
        usleep(100000);
    }

    // Clean up
    spiClose(spi_handle);
    fclose(file);
    gpioTerminate();

    return 0;
}

