    while (1) {
        // Read flow rate from sensor
        int flow_rate = spiRead(spi_handle, AWM7300V_CHANNEL);
        if (flow_rate < 0) {
            fprintf(stderr, "Failed to read flow rate from sensor\n");
            return 1;
        }

        // Convert flow rate to LPM
        int lpm = flow_rate * 60 / 1000;

        // Get current timestamp
        time_t timestamp = time(NULL);

        // Write timestamp and flow rate to file
        fprintf(file, "%s,%d\n", ctime(&timestamp), lpm);

        // Sleep for 100 milliseconds
        usleep(100000);
    }

    // Clean up
    spiClose(spi_handle);
    fclose(file);
    gpioTerminate();

    return 0;
