            fprintf(pipe, "\n");
            fprintf(pipe, "Regards,\n");
            fprintf(pipe, "Your Raspberry Pi\n");
            pclose(pipe);
            if (pclose(pipe) != 0) {
                fprintf(stderr, "Failed to close pipe to msmtp\n");
            }
        }

        // Sleep for log frequency
        sleep(log_frequency);
    }

    // Clean up
    fclose(log_file);
    adcClose(adc_channel);
    spiClose(spi_channel);
    gpioTerminate();

    return 0;
}

