#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED 1000000
#define SPI_DELAY_USEC 1000

#define DRY_CALIBRATION_ADC 700
#define WET_CALIBRATION_ADC 300
#define MIN_MOISTURE_PERCENTAGE 0
#define MAX_MOISTURE_PERCENTAGE 100

int main(int argc, char *argv[]) {
    int spi_fd;
    uint8_t spi_tx_buf[3];
    uint8_t spi_rx_buf[3];
    uint16_t adc_reading;
    uint16_t moisture_percentage;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode and bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        return 1;
    }

    // Set SPI max speed
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED) < 0) {
        perror("Failed to set SPI max speed");
        return 1;
    }

    // Set SPI delay
    if (ioctl(spi_fd, SPI_IOC_WR_DELAY_USEC, &SPI_DELAY_USEC) < 0) {
        perror("Failed to set SPI delay");
        return 1;
    }

    // Set up SPI transfer buffers
    spi_tx_buf[0] = 0x01; // MCP3008 single-ended conversion command
    spi_tx_buf[1] = 0x00; // Channel 0 (ADC0)
    spi_tx_buf[2] = 0x00; // Dummy byte for 3-byte transfer

    // Set up signal handling to cleanly release SPI file descriptor
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        // Perform SPI transfer
        if (write(spi_fd, spi_tx_buf, 3) < 0) {
            perror("Failed to perform SPI transfer");
            return 1;
        }
        if (read(spi_fd, spi_rx_buf, 3) < 0) {
            perror("Failed to read SPI response");
            return 1;
        }

        // Extract ADC reading from SPI response
        adc_reading = (spi_rx_buf[1] << 8) | spi_rx_buf[2];

        // Calculate moisture percentage
        moisture_percentage = (adc_reading - DRY_CALIBRATION_ADC) * 100 / (WET_CALIBRATION_ADC - DRY_CALIBRATION_ADC);
        moisture_percentage = clamp(moisture_percentage, MIN_MOISTURE_PERCENTAGE, MAX_MOISTURE_PERCENTAGE);

        // Log raw ADC reading and moisture percentage to console
        printf("ADC reading: %d, Moisture percentage: %d%%\n", adc_reading, moisture_percentage);

        // Wait for next measurement
        sleep(5);
    }

    // Cleanly release SPI file descriptor
    close(spi_fd);

    return 0;
}

void signal_handler(int signal) {
    close(spi_fd);
    exit(0);
}

uint16_t clamp(uint16_t value, uint16_t min, uint16_t max) {
    if (value < min) {
        return min;
    } else if (value > max) {
        return max;
    } else {
        return value;
    }
}

