#include <linux/spi/spidev.h>
#include <libgpiod/libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_DELAY 0

#define MIN_ADC_VALUE 300
#define MAX_ADC_VALUE 700

int main(void) {
    // Open SPI device
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_SPEED, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    // Set SPI bits and delay
    if (ioctl(spi_fd, SPI_IOC_WR_BITS, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_DELAY, &SPI_DELAY) < 0) {
        perror("Failed to set SPI delay");
        close(spi_fd);
        return 1;
    }

    // Open GPIO lines
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }
    struct gpiod_line *ce0 = gpiod_chip_get_line(chip, 8);
    struct gpiod_line *sclk = gpiod_chip_get_line(chip, 11);
    struct gpiod_line *mosi = gpiod_chip_get_line(chip, 10);
    struct gpiod_line *miso = gpiod_chip_get_line(chip, 9);
    if (!ce0 || !sclk || !mosi || !miso) {
        perror("Failed to open GPIO lines");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Set GPIO lines to output
    if (gpiod_line_request_output(ce0, "ce0", 0) < 0) {
        perror("Failed to set GPIO line to output");
        gpiod_line_release(ce0);
        gpiod_line_release(sclk);
        gpiod_line_release(mosi);
        gpiod_line_release(miso);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }
    if (gpiod_line_request_output(sclk, "sclk", 0) < 0) {
        perror("Failed to set GPIO line to output");
        gpiod_line_release(ce0);
        gpiod_line_release(sclk);
        gpiod_line_release(mosi);
        gpiod_line_release(miso);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }
    if (gpiod_line_request_output(mosi, "mosi", 0) < 0) {
        perror("Failed to set GPIO line to output");
        gpiod_line_release(ce0);
        gpiod_line_release(sclk);
        gpiod_line_release(mosi);
        gpiod_line_release(miso);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }
    if (gpiod_line_request_output(miso, "miso", 0) < 0) {
        perror("Failed to set GPIO line to output");
        gpiod_line_release(ce0);
        gpiod_line_release(sclk);
        gpiod_line_release(mosi);
        gpiod_line_release(miso);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Set GPIO lines to high
    if (gpiod_line_set_value(ce0, 1) < 0) {
        perror("Failed to set GPIO line to high");
        gpiod_line_release(ce0);
        gpiod_line_release(sclk);
        gpiod_line_release(mosi);
        gpiod_line_release(miso);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }
    if (gpiod_line_set_value(sclk, 1) < 0) {
        perror("Failed to set GPIO line to high");
        gpiod_line_release(ce0);
        gpiod_line_release(sclk);
        gpiod_line_release(mosi);
        gpiod_line_release(miso);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }
    if (gpiod_line_set_value(mosi, 1) < 0) {
        perror("Failed to set GPIO line to high");
        gpiod_line_release(ce0);
        gpiod_line_release(sclk);
        gpiod_line_release(mosi);
        gpiod_line_release(miso);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }
    if (gpiod_line_set_value(miso, 1) < 0) {
        perror("Failed to set GPIO line to high");
        gpiod_line_release(ce0);
        gpiod_line_release(sclk);
        gpiod_line_release(mosi);
        gpiod_line_release(miso);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Read sensor data
    uint16_t adc_value;
    while (1) {
        // Set CE0 to low
        if (gpiod_line_set_value(ce0, 0) < 0) {
            perror("Failed to set GPIO line to low");
            gpiod_line_release(ce0);
            gpiod_line_release(sclk);
            gpiod_line_release(mosi);
            gpiod_line_release(miso);
            gpiod_chip_close(chip);
            close(spi_fd);
            return 1;
        }

        // Read ADC value
        if (read(spi_fd, &adc_value, sizeof(adc_value)) < 0) {
            perror("Failed to read ADC value");
            gpiod_line_release(ce0);
            gpiod_line_release(sclk);
            gpiod_line_release(mosi);
            gpiod_line_release(miso);
            gpiod_chip_close(chip);
            close(spi_fd);
            return 1;
        }

        // Set CE0 to high
        if (gpiod_line_set_value(ce0, 1) < 0) {
            perror("Failed to set GPIO line to high");
            gpiod_line_release(ce0);
            gpiod_line_release(sclk);
            gpiod_line_release(mosi);
            gpiod_line_release(miso);
            gpiod_chip_close(chip);
            close(spi_fd);
            return 1;
        }

        // Convert ADC value to moisture percentage
        int moisture_percentage = (adc_value - MIN_ADC_VALUE) * 100 / (MAX_ADC_VALUE - MIN_ADC_VALUE);

        // Log reading to console
        printf("Moisture percentage: %d%%\n", moisture_percentage);

        // Wait 5 seconds
        sleep(5);
    }

    // Clean up
    gpiod_line_release(ce0);
    gpiod_line_release(sclk);
    gpiod_line_release(mosi);
    gpiod_line_release(miso);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

