#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_CLOCK_SPEED 1000000
#define MCP3008_START_BIT 0x01
#define MCP3008_CONFIG_BYTE 0x60
#define MCP3008_DONT_CARE_BYTE 0x00
#define MCP3008_CHANNEL 0

int main() {
    int spi_fd;
    int ret;
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    uint16_t adc_value;
    uint8_t moisture_percentage;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Configure SPI mode, bits per word, and clock speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_CLOCK_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI clock speed");
        close(spi_fd);
        return 1;
    }

    // Set up SPI transfer
    tx_buf[0] = MCP3008_START_BIT;
    tx_buf[1] = MCP3008_CONFIG_BYTE;
    tx_buf[2] = MCP3008_DONT_CARE_BYTE;

    // Read ADC value
    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx_buf);
    if (ret < 0) {
        perror("Failed to transfer SPI message");
        close(spi_fd);
        return 1;
    }

    // Extract ADC value
    adc_value = (rx_buf[1] << 8) | rx_buf[2];

    // Calculate moisture percentage
    moisture_percentage = (adc_value * 100) / 1023;

    // Clamp moisture percentage to 0-100 range
    if (moisture_percentage > 100) {
        moisture_percentage = 100;
    } else if (moisture_percentage < 0) {
        moisture_percentage = 0;
    }

    // Log moisture percentage to console
    printf("Moisture percentage: %d%%\n", moisture_percentage);

    // Close SPI device
    close(spi_fd);

    return 0;
}

