#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

#define SPI_CE0 0
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CHANNEL 0
#define PUMP_GPIO 17
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define SAMPLE_INTERVAL 5
#define LOG_CAPACITY 20

typedef struct {
    uint32_t timestamp;
    uint16_t moisture_level;
    uint8_t pump_state;
} log_entry_t;

log_entry_t log_buffer[LOG_CAPACITY];
uint32_t log_index = 0;

void handle_sigint(int signal) {
    printf("Received SIGINT, stopping timer and turning off pump\n");
    pigpio_stop_timer(SPI_CE0);
    pigpio_write(PUMP_GPIO, 0);
    pigpio_close(SPI_CE0);
    pigpio_terminate();
    exit(0);
}

void handle_sigterm(int signal) {
    printf("Received SIGTERM, stopping timer and turning off pump\n");
    pigpio_stop_timer(SPI_CE0);
    pigpio_write(PUMP_GPIO, 0);
    pigpio_close(SPI_CE0);
    pigpio_terminate();
    exit(0);
}

void read_moisture_level(void) {
    uint8_t tx_buf[3] = {0x00, 0x00, 0x00};
    uint8_t rx_buf[3] = {0x00, 0x00, 0x00};
    uint16_t moisture_level = 0;

    // Read the moisture level from the sensor
    if (pigpio_spi_xfer(SPI_CE0, SPI_MOSI, SPI_MISO, SPI_SCLK, SPI_SPEED, SPI_MODE, SPI_CHANNEL, tx_buf, rx_buf, 3) != 0) {
        printf("Error reading moisture level\n");
        return;
    }

    // Convert the raw ADC value to a moisture level
    moisture_level = (rx_buf[1] << 8) | rx_buf[2];

    // Check if the moisture level is below the low threshold
    if (moisture_level < LOW_THRESHOLD) {
        // Turn on the pump
        pigpio_write(PUMP_GPIO, 1);
    } else if (moisture_level > HIGH_THRESHOLD) {
        // Turn off the pump
        pigpio_write(PUMP_GPIO, 0);
    }

    // Log the moisture level and pump state
    log_buffer[log_index].timestamp = time(NULL);
    log_buffer[log_index].moisture_level = moisture_level;
    log_buffer[log_index].pump_state = pigpio_read(PUMP_GPIO);
    log_index = (log_index + 1) % LOG_CAPACITY;
}

int main(void) {
    // Initialize pigpio
    if (pigpio_init() != 0) {
        printf("Error initializing pigpio\n");
        return 1;
    }

    // Open SPI bus 0, channel 0
    if (pigpio_spi_open(SPI_CE0, SPI_MOSI, SPI_MISO, SPI_SCLK, SPI_SPEED, SPI_MODE, SPI_CHANNEL) != 0) {
        printf("Error opening SPI bus\n");
        pigpio_terminate();
        return 1;
    }

    // Set up the pump GPIO as an output
    if (pigpio_gpio_mode(PUMP_GPIO, PI_OUTPUT) != 0) {
        printf("Error setting up pump GPIO\n");
        pigpio_close(SPI_CE0);
        pigpio_terminate();
        return 1;
    }

    // Set up the timer to sample the moisture level every 5 seconds
    if (pigpio_start_timer(SPI_CE0, SAMPLE_INTERVAL, read_moisture_level) != 0) {
        printf("Error setting up timer\n");
        pigpio_close(SPI_CE0);
        pigpio_terminate();
        return 1;
    }

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Run in an infinite loop until interrupted
    while (1) {
        sleep(1);
    }

    // Clean up on exit
    pigpio_stop_timer(SPI_CE0);
    pigpio_write(PUMP_GPIO, 0);
    pigpio_close(SPI_CE0);
    pigpio_terminate();

    return 0;
}

