#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define MAX30102_I2C_ADDR 0x57
#define MAX30102_PART_ID_REG 0xFF
#define MAX30102_MODE_CONFIG_REG 0x06
#define MAX30102_SPO2_CONFIG_REG 0x08
#define MAX30102_LED1_PA_REG 0x09
#define MAX30102_LED2_PA_REG 0x0A
#define MAX30102_FIFO_DATA_REG 0x07

#define MAX30102_MODE_CONFIG_RESET 0x40
#define MAX30102_MODE_CONFIG_SPO2 0x03
#define MAX30102_SPO2_CONFIG_100HZ 0x27
#define MAX30102_LED1_PA_100MA 0x24
#define MAX30102_LED2_PA_100MA 0x24

#define MAX30102_FIFO_DATA_SIZE 6

#define MAX30102_HEART_RATE_THRESHOLD 100
#define MAX30102_SPO2_THRESHOLD 95

#define MAX30102_LOG_FILE "health_log.txt"

int main(void) {
    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus 1
    int i2c_handle = pigpio_i2c_open(1, 0, 0, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        pigpio_stop();
        return 1;
    }

    // Verify sensor presence by reading Part ID register
    uint8_t part_id;
    if (pigpio_i2c_read_byte_data(i2c_handle, MAX30102_PART_ID_REG, &part_id) < 0) {
        fprintf(stderr, "Failed to read Part ID register\n");
        pigpio_i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }
    if (part_id != 0x15) {
        fprintf(stderr, "Invalid Part ID: 0x%02X\n", part_id);
        pigpio_i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    // Initialize sensor by resetting it, clearing interrupts, configuring SpO2 mode, and setting LED pulse amplitudes
    uint8_t mode_config = MAX30102_MODE_CONFIG_RESET;
    if (pigpio_i2c_write_byte_data(i2c_handle, MAX30102_MODE_CONFIG_REG, mode_config) < 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        pigpio_i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }
    mode_config = MAX30102_MODE_CONFIG_SPO2;
    if (pigpio_i2c_write_byte_data(i2c_handle, MAX30102_MODE_CONFIG_REG, mode_config) < 0) {
        fprintf(stderr, "Failed to configure SpO2 mode\n");
        pigpio_i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }
    uint8_t spo2_config = MAX30102_SPO2_CONFIG_100HZ;
    if (pigpio_i2c_write_byte_data(i2c_handle, MAX30102_SPO2_CONFIG_REG, spo2_config) < 0) {
        fprintf(stderr, "Failed to set SpO2 configuration\n");
        pigpio_i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }
    uint8_t led1_pa = MAX30102_LED1_PA_100MA;
    if (pigpio_i2c_write_byte_data(i2c_handle, MAX30102_LED1_PA_REG, led1_pa) < 0) {
        fprintf(stderr, "Failed to set LED1 pulse amplitude\n");
        pigpio_i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }
    uint8_t led2_pa = MAX30102_LED2_PA_100MA;
    if (pigpio_i2c_write_byte_data(i2c_handle, MAX30102_LED2_PA_REG, led2_pa) < 0) {
        fprintf(stderr, "Failed to set LED2 pulse amplitude\n");
        pigpio_i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(MAX30102_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pigpio_i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    // Main loop
    while (1) {
        // Read FIFO data register in 6-byte bursts
        uint8_t fifo_data[MAX30102_FIFO_DATA_SIZE];
        if (pigpio_i2c_read_byte_data(i2c_handle, MAX30102_FIFO_DATA_REG, fifo_data, MAX30102_FIFO_DATA_SIZE) < 0) {
            fprintf(stderr, "Failed to read FIFO data register\n");
            pigpio_i2c_close(i2c_handle);
            pigpio_stop();
            return 1;
        }

        // Compute SpO2 and heart rate using ratio-of-ratios method
        uint16_t red = (fifo_data[0] << 8) | fifo_data[1];
        uint16_t ir = (fifo_data[2] << 8) | fifo_data[3];
        float spo2 = (float)red / ir;
        float heart_rate = 60.0 * (float)ir / (float)MAX30102_FIFO_DATA_SIZE;

        // Log SpO2 and heart rate to log file
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02dZ, SpO2: %.2f, Heart Rate: %.2f\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, spo2, heart_rate);

        // Check for SpO2 and heart rate thresholds
        if (spo2 < MAX30102_SPO2_THRESHOLD || heart_rate > MAX30102_HEART_RATE_THRESHOLD) {
            fprintf(stderr, "SpO2: %.2f, Heart Rate: %.2f\n", spo2, heart_rate);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    pigpio_i2c_close(i2c_handle);
    pigpio_stop();

    return 0;
}

