    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI handle
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_CE0, SPI_BUS, SPI_MODE, SPI_SPEED);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        return 1;
    }

    // Set up SPI transfer
    uint8_t tx_buf[3] = {MCP3008_START_BIT, MCP3008_SINGLE_ENDED_CONFIG_BYTE, MCP3008_DUMMY_BYTE};
    uint8_t rx_buf[3];

    // Open CSV file
    FILE *csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return 1;
    }

