static void init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }
}

static void init_spi() {
    spi_handle = pigpio_spi_open(SPI_CHANNEL, SPI_CE_GPIO, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        exit(1);
    }
}

static void init_buzzer() {
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    buzzer_state = 0;
}

static void read_adc() {
    uint16_t adc_value;
    if (pigpio_spi_read(spi_handle, ADC_CHANNEL, &adc_value) < 0) {
        fprintf(stderr, "Failed to read ADC value\n");
        exit(1);
    }
    printf("ADC value: %d\n", adc_value);
}

static void control_buzzer() {
    if (adc_value < THRESHOLD) {
        if (buzzer_state == 1) {
            gpioWrite(BUZZER_GPIO, 0);
            buzzer_state = 0;
        }
    } else {
        if (buzzer_state == 0) {
            gpioWrite(BUZZER_GPIO, 1);
            buzzer_state = 1;
        }
    }
}

