    init_pigpio();
    init_spi();
    init_buzzer();

    signal(SIGINT, sigint_handler);

    while (1) {
        read_adc();
        control_buzzer();
        usleep(500000);
    }

    pigpio_spi_close(spi_handle);
    gpioTerminate();

