#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/i2c-dev.h>
#include <libgpiod/libgpiod.h>

#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_LO_THRESH 0x02
#define ADS1115_REG_HI_THRESH 0x03

#define RELAY_GPIO 17
#define REED_GPIO 27

#define BASELINE_SAMPLES 10
#define BASELINE_DELAY 50
#define POLL_DELAY 200
#define RELAY_DURATION 3000

#define LOG_FILE "/var/log/door_events.log"

int main(void) {
    // Initialize libgpiod
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Set up the relay and reed sensor lines
    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    struct gpiod_line *reed_line = gpiod_chip_get_line(chip, REED_GPIO);
    if (!relay_line || !reed_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        return 1;
    }

    // Set up the ADS1115 ADC
    int adc_fd = open("/dev/i2c-1", O_RDWR);
    if (adc_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    // Take baseline samples
    uint16_t baseline_sum = 0;
    for (int i = 0; i < BASELINE_SAMPLES; i++) {
        uint16_t value;
        if (read_adc(adc_fd, &value) < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            return 1;
        }
        baseline_sum += value;
        usleep(BASELINE_DELAY * 1000);
    }
    uint16_t baseline_avg = baseline_sum / BASELINE_SAMPLES;

    // Set the trigger threshold
    uint16_t threshold = baseline_avg * 0.8;
    if (write_adc_threshold(adc_fd, threshold) < 0) {
        fprintf(stderr, "Failed to set ADC threshold\n");
        return 1;
    }

    // Poll the ADC
    while (true) {
        uint16_t value;
        if (read_adc(adc_fd, &value) < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            return 1;
        }

        if (value < threshold) {
            // Activate the relay
            gpiod_line_set_value(relay_line, 1);
            usleep(RELAY_DURATION * 1000);
            gpiod_line_set_value(relay_line, 0);

            // Check if the door is open
            if (gpiod_line_get_value(reed_line) == 0) {
                fprintf(stderr, "Door opened\n");
            } else {
                fprintf(stderr, "Door not opened\n");
            }
        }

        usleep(POLL_DELAY * 1000);
    }

    // Clean up
    gpiod_line_release(relay_line);
    gpiod_line_release(reed_line);
    close(adc_fd);
    gpiod_chip_close(chip);

    return 0;
}

int read_adc(int fd, uint16_t *value) {
    uint8_t buf[2];
    if (ioctl(fd, I2C_RDWR, &buf) < 0) {
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int write_adc_threshold(int fd, uint16_t threshold) {
    uint8_t buf[2];
    buf[0] = (threshold >> 8) & 0xFF;
    buf[1] = threshold & 0xFF;
    if (ioctl(fd, I2C_RDWR, &buf) < 0) {
        return -1;
    }
    return 0;
}

