#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod.h>
#include <spidev.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_DELAY 0

#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25

#define CHANNEL 0

#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S"

int main(int argc, char *argv[]) {
    // Initialize libgpiod
    struct gpiod_chip *chip;
    struct gpiod_line *cs0, *cs1, *cs2;
    int ret;

    // Open SPI device
    int spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode and speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        return 1;
    }
    ret = ioctl(spi_fd, SPI_IOC_WR_SPEED, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        return 1;
    }

    // Initialize libgpiod lines for chip select
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }
    cs0 = gpiod_chip_get_line(chip, CS0_PIN);
    cs1 = gpiod_chip_get_line(chip, CS1_PIN);
    cs2 = gpiod_chip_get_line(chip, CS2_PIN);
    if (!cs0 || !cs1 || !cs2) {
        perror("Failed to get GPIO lines");
        return 1;
    }

    // Open file for logging
    FILE *fp = fopen("soil_moisture_log.csv", "w");
    if (!fp) {
        perror("Failed to open file");
        return 1;
    }

    // Write CSV header
    fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n");

    // Main loop
    while (1) {
        // Read sensor values
        uint16_t sensor1, sensor2, sensor3;
        ret = read_sensor(spi_fd, cs0, CHANNEL, &sensor1);
        if (ret < 0) {
            sensor1 = -1;
        }
        ret = read_sensor(spi_fd, cs1, CHANNEL, &sensor2);
        if (ret < 0) {
            sensor2 = -1;
        }
        ret = read_sensor(spi_fd, cs2, CHANNEL, &sensor3);
        if (ret < 0) {
            sensor3 = -1;
        }

        // Write to file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), TIMESTAMP_FORMAT, localtime(&now));
        fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    fclose(fp);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

int read_sensor(int spi_fd, struct gpiod_line *cs, int channel, uint16_t *value) {
    // Set chip select
    gpiod_line_set_value(cs, 0);

    // Send command
    uint8_t cmd[3] = {0x01, (0x08 | channel) << 4, 0x00};
    ret = write(spi_fd, cmd, sizeof(cmd));
    if (ret < 0) {
        perror("Failed to write SPI command");
        return -1;
    }

    // Read result
    uint8_t result[2];
    ret = read(spi_fd, result, sizeof(result));
    if (ret < 0) {
        perror("Failed to read SPI result");
        return -1;
    }

    // Get 10-bit result
    *value = (result[1] & 0x03) << 8 | result[2];

    // Clear chip select
    gpiod_line_set_value(cs, 1);

    return 0;
}

void sigint_handler(int signum) {
    // Clean up
    fclose(fp);
    gpiod_chip_close(chip);
    close(spi_fd);

    // Exit
    exit(0);
}

