        if (ret < 0) {
            sensor1 = -1;
        }
        ret = read_sensor(spi_fd, cs1, CHANNEL, &sensor2);
        if (ret < 0) {
            sensor2 = -1;
        }
        ret = read_sensor(spi_fd, cs2, CHANNEL, &sensor3);
        if (ret < 0) {
            sensor3 = -1;
        }

        // Write to file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), TIMESTAMP_FORMAT, localtime(&now));
        fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    fclose(fp);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

int read_sensor(int spi_fd, struct gpiod_line *cs, int channel, uint16_t *value) {
    // Set chip select
    gpiod_line_set_value(cs, 0);

    // Send command
    uint8_t cmd[3] = {0x01, (0x08 | channel) << 4, 0x00};
    ret = write(spi_fd, cmd, sizeof(cmd));
    if (ret < 0) {
        perror("Failed to write SPI command");
        return -1;
    }

    // Read result
    uint8_t result[2];
    ret = read(spi_fd, result, sizeof(result));
    if (ret < 0) {
        perror("Failed to read SPI result");
        return -1;
    }

    // Get 10-bit result
    *value = (result[1] & 0x03) << 8 | result[2];

    // Clear chip select
    gpiod_line_set_value(cs, 1);

    return 0;
}

void sigint_handler(int signum) {
    // Clean up
    fclose(fp);
    gpiod_chip_close(chip);
    close(spi_fd);

    // Exit
    exit(0);
}
