  int moisture = 0;
  int retries = 0;
  while (retries < MAX_RETRIES) {
    // Read MCP3008 SPI
    int adc_value = mcp3008_read(MCP3008_SPI_CHANNEL);
    if (adc_value < 0) {
      fprintf(stderr, "Failed to read MCP3008 SPI\n");
      retries++;
      continue;
    }

    // Map ADC value to moisture percentage
    moisture = (adc_value - 200) * 100 / (800 - 200);
    if (moisture < 0) {
      moisture = 0;
    } else if (moisture > 100) {
