  // Shut off pump
  pigpio_write(PUMP_GPIO, !PUMP_ACTIVE_HIGH);

  // Close SPI
  mcp3008_close();

  // Terminate pigpio
  pigpio_stop();

  // Exit cleanly
  exit(0);
