#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <pigpio.h>
#include <mcp3008.h>

#define SAMPLE_RATE 100 // Hz
#define EMA_ALPHA 0.1
#define THRESHOLD_MARGIN 0.2

#define ADC_CHANNEL 0
#define ADC_SPI_BUS 0
#define ADC_SPI_DEVICE 0

#define MCP3008_SPI_BUS 0
#define MCP3008_SPI_DEVICE 0

#define LOG_FILE "/var/log/sound_events.log"

int main(void) {
  // Initialize pigpio
  if (gpioInitialise() < 0) {
    fprintf(stderr, "Failed to initialize pigpio\n");
    return 1;
  }

  // Initialize MCP3008 SPI
  if (mcp3008_init(MCP3008_SPI_BUS, MCP3008_SPI_DEVICE) < 0) {
    fprintf(stderr, "Failed to initialize MCP3008 SPI\n");
    return 1;
  }

  // Initialize ADC SPI
  if (adc_init(ADC_SPI_BUS, ADC_SPI_DEVICE) < 0) {
    fprintf(stderr, "Failed to initialize ADC SPI\n");
    return 1;
  }

  // Set up SPI configuration
  spi_config_t spi_config;
  spi_config.mode = SPI_MODE_0;
  spi_config.bits = 8;
  spi_config.speed = 1000000;
  spi_config.delay = 0;

  // Set up ADC configuration
  adc_config_t adc_config;
  adc_config.channel = ADC_CHANNEL;
  adc_config.bits = 12;
  adc_config.speed = 1000000;
  adc_config.delay = 0;

  // Set up EMA
  double ema = 0;

  // Set up log file
  FILE *log_file = fopen(LOG_FILE, "a");
  if (log_file == NULL) {
    fprintf(stderr, "Failed to open log file\n");
    return 1;
  }

  // Main loop
  while (true) {
    // Read ADC value
    int16_t adc_value = adc_read(ADC_SPI_BUS, ADC_SPI_DEVICE, &adc_config);
    if (adc_value < 0) {
      fprintf(stderr, "Failed to read ADC value\n");
      return 1;
    }

    // Update EMA
    ema = (1 - EMA_ALPHA) * ema + EMA_ALPHA * adc_value;

    // Check for peak
    if (adc_value > ema * (1 + THRESHOLD_MARGIN)) {
      // Log peak
      time_t now = time(NULL);
      struct tm *tm = localtime(&now);
      fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02dZ %d\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, adc_value);
    }

    // Sleep for 10 ms
    usleep(10000);
  }

  // Clean up
  fclose(log_file);
  adc_close(ADC_SPI_BUS, ADC_SPI_DEVICE);
  mcp3008_close(MCP3008_SPI_BUS, MCP3008_SPI_DEVICE);
  gpioTerminate();

  return 0;
}

