#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod/libgpiod.h>

#define I2C_ADDR 0x48
#define I2C_BUS "/dev/i2c-1"
#define AIN0_CHANNEL 0

int main(void) {
    int i2c_fd;
    uint8_t control_byte = 0x00;
    uint8_t sample_value;

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Set control byte for single-ended mode on channel 0
    control_byte = 0x00;
    if (write(i2c_fd, &control_byte, 1) != 1) {
        perror("Failed to write control byte");
        close(i2c_fd);
        return 1;
    }

    // Perform a dummy read to discard the previous conversion result
    if (read(i2c_fd, &sample_value, 1) != 1) {
        perror("Failed to read sample value");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sigint_handler;
    sigint_handler.sa_handler = sigint_handler_func;
    sigint_handler.sa_flags = 0;
    sigemptyset(&sigint_handler.sa_mask);
    sigaction(SIGINT, &sigint_handler, NULL);

    // Main loop
    while (1) {
        // Read sample value
        if (read(i2c_fd, &sample_value, 1) != 1) {
            perror("Failed to read sample value");
            close(i2c_fd);
            return 1;
        }

        // Print sample value
        printf("Sample value: %d\n", sample_value);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    close(i2c_fd);

    return 0;
}

void sigint_handler_func(int signum) {
    close(i2c_fd);
    exit(0);
}

