    if (pigpio_start(NULL, NULL) < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    // Initialize I2C handle
    int i2c_handle = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C handle");
        return 1;
    }

    // Initialize ADC handle
    int adc_handle = ads1115_open(i2c_handle, AIN0);
    if (adc_handle < 0) {
        syslog(LOG_ERR, "Failed to open ADC handle");
        return 1;
    }

    // Set GPIO27 to output
    if (gpio_mode_set(GPIO27, GPIO_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO27 to output");
        return 1;
    }

    // Set GPIO27 to LOW
    if (gpio_write(GPIO27, 0) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO27 to LOW");
        return 1;
    }

    // Initialize circular buffer
    int buffer[BUFFER_SIZE];
    int buffer_index = 0;

    // Main loop
    while (1) {
        // Read voltage from ADC
        int voltage = ads1115_read(adc_handle);
        if (voltage < 0) {
            syslog(LOG_ERR, "Failed to read voltage from ADC");
            continue;
        }

        // Convert voltage to magnetic field strength
        int field = (voltage - SS49E_ZERO_FIELD) / SS49E_SENSITIVITY;

        // Add field to circular buffer
        buffer[buffer_index] = field;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Calculate rolling average
        int sum = 0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            sum += buffer[i];
        }
        int average = sum / BUFFER_SIZE;

        // Check for threshold exceeded
        if (average > THRESHOLD) {
            // Set GPIO27 to HIGH
            if (gpio_write(GPIO27, 1) < 0) {
                syslog(LOG_ERR, "Failed to set GPIO27 to HIGH");
                return 1;
            }
        }

        // Log readings and threshold events
        syslog(LOG_INFO, "Field: %d Gauss, Average: %d Gauss", field, average);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    ads1115_close(adc_handle);
    i2c_close(i2c_handle);
    pigpio_stop();
    return 0;
}
