static int spi_init(void) {
    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %s\n", SPI_CHANNEL, strerror(errno));
        return -1;
    }
    return 0;
}

static int adc_init(void) {
    adc_fd = mcp3008Open(SPI_CHANNEL, ADC_CHANNEL);
    if (adc_fd < 0) {
        fprintf(stderr, "Failed to open ADC channel %d: %s\n", ADC_CHANNEL, strerror(errno));
        return -1;
    }
    return 0;
}

static int pump_init(void) {
    pump_fd = gpioOpen(PUMP_GPIO, PUMP_RELAY);
    if (pump_fd < 0) {
        fprintf(stderr, "Failed to open GPIO %d: %s\n", PUMP_GPIO, strerror(errno));
        return -1;
    }
    return 0;
}

static void pump_on(void) {
    gpioWrite(pump_fd, 1);
}

static void pump_off(void) {
    gpioWrite(pump_fd, 0);
}

static int read_adc(void) {
    uint16_t value;
    if (mcp3008Read(adc_fd, &value) < 0) {
        fprintf(stderr, "Failed to read ADC value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

static void sigint_handler(int signum) {
    pump_off();
    gpioClose(pump_fd);
    mcp3008Close(adc_fd);
    spiClose(spi_fd);
    exit(0);
}

int main(void) {
    if (spi_init() < 0 || adc_init() < 0 || pump_init() < 0) {
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            log_event("Failed to read ADC value");
            continue;
        }
        if (adc_value < THRESHOLD) {
            pump_on();
            log_event("Watering started");
            sleep(WATERING_DURATION);
            pump_off();
            log_event("Watering finished");
        }
        sleep(WATERING_INTERVAL);
    }

    return 0;
}

