#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

#define ADC_CHANNEL 0
#define PWM_CHANNEL 1
#define PWM_FREQ 1000
#define PWM_RANGE 1023

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up SPI
    int spi_handle = spiOpen(0, 1000000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        return 1;
    }

    // Set up PWM
    int pwm_handle = pwmOpen(PWM_CHANNEL, PWM_FREQ, PWM_RANGE);
    if (pwm_handle < 0) {
        fprintf(stderr, "Failed to open PWM\n");
        return 1;
    }

    // Set up SIGINT/SIGTERM handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = adcRead(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            return 1;
        }

        // Update PWM duty cycle
        int pwm_duty = (adc_value * PWM_RANGE) / 1023;
        pwmSetDuty(pwm_handle, pwm_duty);

        // Print values
        printf("ADC: %d\n", adc_value);
        printf("PWM: %d\n", pwm_duty);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    pwmClose(pwm_handle);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum) {
    // Stop PWM
    pwmSetDuty(pwm_handle, 0);

    // Release pigpio resources
    pwmClose(pwm_handle);
    spiClose(spi_handle);
    gpioTerminate();

    // Exit
    exit(0);
}

