#include <signal.h>
#include <pigpio.h>
#include <ads1115.h>

#define I2C_ADDR 0x48
#define AIN0 0
#define PGA 4.096
#define THRESHOLD 100.0

static volatile bool running = true;

void sigint_handler(int signum) {
    running = false;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    double threshold = THRESHOLD;
    if (argc > 1) {
        threshold = atof(argv[1]);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Initialize I2C
    if (ads1115_init(I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to initialize ADS1115\n");
        return 1;
    }

    // Set up signal handler for SIGINT/SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Set up LED
    gpioSetMode(17, PI_OUTPUT);
    gpioWrite(17, PI_LOW);

    // Main loop
    while (running) {
        // Read magnetic field strength
        double field = ads1115_read(AIN0, PGA);
        if (field < 0) {
            fprintf(stderr, "Failed to read magnetic field strength\n");
            return 1;
        }

        // Output magnetic field strength to console
        printf("Magnetic field strength: %f Gauss\n", field);

        // Check if field exceeds threshold
        if (field > threshold) {
            // Blink LED rapidly
            gpioWrite(17, PI_HIGH);
            usleep(50000);
            gpioWrite(17, PI_LOW);
            usleep(50000);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up resources
    gpioWrite(17, PI_LOW);
    ads1115_close();
    gpioTerminate();

    return 0;
}

