#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS 10
#define SPI_SPEED 1000000
#define SPI_DELAY 500

int main(void) {
    int spi_fd;
    uint8_t spi_tx_buf[3];
    uint8_t spi_rx_buf[3];
    uint16_t raw_value;
    float voltage;

    // Open the SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set the SPI mode, bits, and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    // Set the SPI command
    spi_tx_buf[0] = 0x01;
    spi_tx_buf[1] = 0x00;
    spi_tx_buf[2] = 0x00;

    // Read the SPI response
    if (read(spi_fd, spi_rx_buf, 3) < 0) {
        perror("Failed to read SPI response");
        close(spi_fd);
        return 1;
    }

    // Extract the raw value from the response
    raw_value = (spi_rx_buf[1] << 8) | spi_rx_buf[2];

    // Calculate the voltage
    voltage = raw_value * 3.3 / 1024.0;

    // Print the raw value and voltage
    printf("Raw value: %d\n", raw_value);
    printf("Voltage: %.2f V\n", voltage);

    // Close the SPI device
    close(spi_fd);

    return 0;
}

