#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MCP3008_CHANNELS 3
#define MCP3008_RESOLUTION 1024
#define VREF 3.3

static int spi_handle;
static int pigpio_handle;

static void sigint_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    pigpio_stop(pigpio_handle);
    spi_close(spi_handle);
    exit(0);
}

int main(void) {
    // Initialize pigpio
    pigpio_handle = pigpio_start(NULL, NULL);
    if (pigpio_handle < 0) {
        printf("Failed to initialize pigpio: %s\n", pigpio_error(pigpio_handle));
        return 1;
    }

    // Open SPI device
    spi_handle = spi_open(0, 0, 0, 0, 0);
    if (spi_handle < 0) {
        printf("Failed to open SPI device: %s\n", spi_error(spi_handle));
        pigpio_stop(pigpio_handle);
        return 1;
    }

    // Set up SPI transfer
    spi_transfer_t transfer = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 0,
        .bits_per_word = 8,
        .speed_hz = 1000000,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .word_delay_usecs = 0
    };

    // Set up file for logging
    FILE *fp = fopen("sensor_data.csv", "w");
    if (fp == NULL) {
        printf("Failed to open file for logging: %s\n", strerror(errno));
        spi_close(spi_handle);
        pigpio_stop(pigpio_handle);
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (1) {
        // Read ADC values
        uint16_t adc_values[MCP3008_CHANNELS];
        for (int i = 0; i < MCP3008_CHANNELS; i++) {
            transfer.tx_buf = (uint8_t *)&i;
            transfer.rx_buf = (uint8_t *)&adc_values[i];
            transfer.len = 1;
            if (spi_transfer(spi_handle, &transfer) < 0) {
                printf("Failed to transfer data over SPI: %s\n", spi_error(spi_handle));
                fclose(fp);
                spi_close(spi_handle);
                pigpio_stop(pigpio_handle);
                return 1;
            }
        }

        // Convert ADC values to voltage
        float voltages[MCP3008_CHANNELS];
        for (int i = 0; i < MCP3008_CHANNELS; i++) {
            voltages[i] = (float)adc_values[i] * VREF / MCP3008_RESOLUTION;
        }

        // Log voltage values
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, voltages[0], voltages[1], voltages[2]);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    fclose(fp);
    spi_close(spi_handle);
    pigpio_stop(pigpio_handle);

    return 0;
}

