#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <libgpiod/libgpiod.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define MAX9814_ADC_CHANNEL 0
#define BH1750_I2C_ADDR 0x23
#define BH1750_CONT_HIGH_RES_MODE 0x11
#define BH1750_READ_TIMEOUT 180
#define LOG_INTERVAL 5

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    // Set up signal handler for SIGINT/SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C device for BH1750
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C address for BH1750
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Open SPI device for MAX9814
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        close(i2c_fd);
        return 1;
    }

    // Set SPI mode for MAX9814
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE_0) < 0) {
        perror("Failed to set SPI mode");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Set SPI speed for MAX9814
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000) < 0) {
        perror("Failed to set SPI speed");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Set SPI channel for MAX9814
    if (ioctl(spi_fd, SPI_IOC_WR_CHANNEL, MAX9814_ADC_CHANNEL) < 0) {
        perror("Failed to set SPI channel");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Open CSV file for logging
    FILE *csv_file = fopen("tamper_log.csv", "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Set up CSV file header
    fprintf(csv_file, "timestamp,sound_level_db,light_level_lux,error_code\n");

    // Main loop
    while (running) {
        // Read sound level from MAX9814
        uint16_t sound_level;
        if (read(spi_fd, &sound_level, sizeof(sound_level)) != sizeof(sound_level)) {
            perror("Failed to read sound level");
            fprintf(csv_file, "%ld,0,0,1\n", time(NULL));
            continue;
        }

        // Read light level from BH1750
        uint16_t light_level;
        if (i2c_smbus_read_word_data(i2c_fd, BH1750_CONT_HIGH_RES_MODE) != sizeof(light_level)) {
            perror("Failed to read light level");
            fprintf(csv_file, "%ld,0,0,2\n", time(NULL));
            continue;
        }

        // Log data to CSV file
        fprintf(csv_file, "%ld,%d,%d,0\n", time(NULL), sound_level, light_level);

        // Sleep for LOG_INTERVAL seconds
        sleep(LOG_INTERVAL);
    }

    // Close CSV file
    fclose(csv_file);

    // Close I2C and SPI devices
    close(i2c_fd);
    close(spi_fd);

    return 0;
}

