#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <libgpiod.h>
#include <mcp3008.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_DELAY 100

#define GPIO_RELAY 17
#define GPIO_SENSOR 26

#define PROXIMITY_THRESHOLD 20
#define DEBOUNCE_DELAY 1000

#define LOG_FILE "door_events.log"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%s: %s\n", timestamp, event);
    fclose(fp);
}

int main(void) {
    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    // Set up GPIO for relay and sensor
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }
    struct gpiod_line *relay = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (relay == NULL) {
        fprintf(stderr, "Error getting GPIO line for relay: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    struct gpiod_line *sensor = gpiod_chip_get_line(chip, GPIO_SENSOR);
    if (sensor == NULL) {
        fprintf(stderr, "Error getting GPIO line for sensor: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up SPI for ADC
    struct spi_device *spi = spi_open(SPI_DEVICE, SPI_SPEED, SPI_MODE, SPI_BITS);
    if (spi == NULL) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up ADC
    struct mcp3008_context *adc = mcp3008_init(spi);
    if (adc == NULL) {
        fprintf(stderr, "Error initializing ADC: %s\n", strerror(errno));
        spi_close(spi);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor value
        uint16_t value = mcp3008_read(adc, 0);
        if (value == -1) {
            fprintf(stderr, "Error reading ADC: %s\n", strerror(errno));
            continue;
        }

        // Check for proximity
        if (value < PROXIMITY_THRESHOLD) {
            // Activate relay
            gpiod_line_set_value(relay, 1);
            log_event("Proximity detected");

            // Debounce
            usleep(DEBOUNCE_DELAY * 1000);

            // Deactivate relay
            gpiod_line_set_value(relay, 0);
        }

        // Sleep for polling interval
        usleep(SPI_DELAY * 1000);
    }

    // Clean up
    mcp3008_close(adc);
    spi_close(spi);
    gpiod_line_close(relay);
    gpiod_line_close(sensor);
    gpiod_chip_close(chip);

    return 0;
}

