#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <mcp3008.h>

#define CH0 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 10
#define SPI_RETRIES 5
#define SPI_BACKOFF 1000000

#define SOIL_DATA_FILE "soil_data.txt"

int main(void) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Initialize SPI interface
    if (spiOpen(CH0, SPI_MODE, SPI_SPEED, SPI_BITS) < 0) {
        fprintf(stderr, "Failed to open SPI interface\n");
        return 1;
    }

    // Set up SPI command bytes for MCP3008
    uint8_t cmd[3] = {0x01, 0x80, 0x00};

    // Set up SPI read buffer
    uint8_t read_buf[3] = {0};

    // Set up SPI write buffer
    uint8_t write_buf[3] = {0};

    // Set up SPI retry mechanism
    int retries = SPI_RETRIES;
    int backoff = SPI_BACKOFF;

    // Open file for logging
    FILE *fp = fopen(SOIL_DATA_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for logging\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read soil moisture level
        int adc_value = 0;
        int ret = spiRead(CH0, cmd, read_buf, 3);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from SPI interface\n");
            if (retries-- > 0) {
                usleep(backoff);
                continue;
            } else {
                fprintf(stderr, "SPI failed persistently, skipping reading\n");
                break;
            }
        }

        // Extract 10-bit ADC value
        adc_value = (read_buf[1] << 2) | (read_buf[2] >> 6);

        // Validate ADC value
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        // Convert ADC value to moisture percentage
        int moisture_percentage = (adc_value * 100) / 1023;

        // Log reading with timestamp
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        fprintf(fp, "%s, %d\n", timestamp, moisture_percentage);

        // Wait for next reading
        sleep(5);
    }

    // Close file
    fclose(fp);

    // Release SPI resources
    spiClose(CH0);

    // Release pigpio resources
    gpioTerminate();

    return 0;
}

