#define PWM_DUTY_CYCLE 50
#define PWM_PERIOD 1000000
#define PWM_POLARITY 0
#define PWM_ENABLE 1
#define PWM_DISABLE 0

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED 1000000

#define GPIO_TRIG 23
#define GPIO_ECHO 24
#define GPIO_VOLUME 18

#define CALIBRATION_FILE "theremin_config.txt"

struct spi_ioc_transfer spi_transfer;
struct spi_device spi_device;
struct gpiod_line gpio_trig;
struct gpiod_line gpio_echo;
struct gpiod_line gpio_volume;

int spi_fd;
int gpio_fd;

int spi_transfer_data(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    spi_transfer.tx_buf = tx_buf;
    spi_transfer.rx_buf = rx_buf;
    spi_transfer.len = len;
    spi_transfer.speed_hz = SPI_MAX_SPEED;
    spi_transfer.bits_per_word = SPI_BITS_PER_WORD;
    spi_transfer.delay_usecs = 0;
    spi_transfer.cs_change = 0;
    spi_transfer.tx_nbits = 0;
    spi_transfer.rx_nbits = 0;
    spi_transfer.pad = 0;

    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer);
}

int gpio_set_value(int gpio, int value) {
    struct gpiod_line_request request;
    request.lineoffset = gpio;
    request.flags = GPIOD_LINE_REQUEST_OUTPUT;
    request.consumer = "theremin";
    request.event_handler = NULL;
    request.event_data = NULL;

    int ret = gpiod_line_request_set_value(gpio_fd, &request, value);
    if (ret < 0) {
        perror("gpiod_line_request_set_value");
        return ret;
    }

    return 0;
}

int gpio_get_value(int gpio) {
    struct gpiod_line_request request;
    request.lineoffset = gpio;
    request.flags = GPIOD_LINE_REQUEST_INPUT;
    request.consumer = "theremin";
    request.event_handler = NULL;
    request.event_data = NULL;

    int ret = gpiod_line_request_get_value(gpio_fd, &request);
    if (ret < 0) {
        perror("gpiod_line_request_get_value");
        return ret;
    }

    return ret;
}

