#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <mcp3008.h>

#define FAN_PIN 18
#define AQI_THRESHOLD 100
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_RETRIES 3
#define SPI_RETRY_DELAY 1000

int main(void) {
    // Initialize pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Initialize MCP3008 ADC
    if (mcp3008_init(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to initialize MCP3008 ADC\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up SIGINT/SIGTERM handler
    struct sigaction sigint_action;
    sigint_action.sa_handler = sigint_handler;
    sigemptyset(&sigint_action.sa_mask);
    sigint_action.sa_flags = 0;
    sigaction(SIGINT, &sigint_action, NULL);
    sigaction(SIGTERM, &sigint_action, NULL);

    // Main loop
    while (1) {
        // Read ADC value
        uint16_t adc_value = 0;
        int retries = SPI_RETRIES;
        while (retries > 0) {
            if (mcp3008_read(SPI_CHANNEL, &adc_value) < 0) {
                fprintf(stderr, "Failed to read ADC value\n");
                retries--;
                sleep(SPI_RETRY_DELAY);
            } else {
                break;
            }
        }
        if (retries == 0) {
            fprintf(stderr, "Failed to read ADC value after %d retries\n", SPI_RETRIES);
            return 1;
        }

        // Convert ADC value to AQI
        int aqi = (adc_value * 500) / 1023;

        // Control fan
        if (aqi > AQI_THRESHOLD) {
            pigpio_write(FAN_PIN, 1);
        } else {
            pigpio_write(FAN_PIN, 0);
        }

        // Log timestamp and AQI
        time_t now = time(NULL);
        fprintf(log_file, "%s, %d\n", ctime(&now), aqi);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    fclose(log_file);
    mcp3008_close();
    pigpio_stop();

    return 0;
}

void sigint_handler(int signum) {
    // Turn off fan
    pigpio_write(FAN_PIN, 0);

    // Close SPI and log file
    mcp3008_close();
    fclose(log_file);

    // Terminate pigpio
    pigpio_stop();

    // Exit program
    exit(0);
}

