#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod/libgpiod.h>
#include <spidev/spidev.h>

#define MCP3008_ADDR 0x68
#define MCP3008_CHANNEL 0
#define MCP3008_SINGLE_ENDED 0x80
#define MCP3008_SPI_CLOCK 1000000
#define MCP3008_SPI_MODE 0
#define MCP3008_SPI_BITS 8

#define PPM_CONSTANT 0.5
#define PPM_OFFSET 10.0

#define SPI_RETRY_COUNT 3
#define SPI_RETRY_DELAY 100

#define ALCOHOL_DETECTED_PPM 50
#define SOBER_PPM 20

#define ALCOHOL_DETECTED_MSG "Alcohol detected! Limit exceeded."
#define SOBER_MSG "Sobriety confirmed."
#define ALCOHOL_RANGE_MSG "Alcohol level within acceptable range."
#define SPI_ERROR_MSG "SPI transfer error."
#define SENSOR_ABSENT_MSG "Sensor absent."

int main(void) {
    // Initialize GPIO
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_request_output(line, "spi", 0);
    gpiod_line_set_value(line, 1);

    // Initialize SPI
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    struct spi_ioc_transfer spi_transfer = {
        .tx_buf = (uint8_t *)malloc(3),
        .rx_buf = (uint8_t *)malloc(3),
        .len = 3,
        .speed_hz = MCP3008_SPI_CLOCK,
        .bits_per_word = MCP3008_SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 8,
        .rx_nbits = 8,
        .pad = 0
    };

    // Set up SPI transfer
    spi_transfer.tx_buf[0] = 0x01;
    spi_transfer.tx_buf[1] = (MCP3008_CHANNEL << 4) | MCP3008_SINGLE_ENDED;
    spi_transfer.tx_buf[2] = 0x00;

    // Open log file
    FILE *log_file = fopen("alcohol_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handler for SIGINT/SIGTERM
    struct sigaction sigint_action = {
        .sa_handler = sigint_handler,
        .sa_flags = 0
    };
    sigaction(SIGINT, &sigint_action, NULL);
    sigaction(SIGTERM, &sigint_action, NULL);

    // Main loop
    while (1) {
        // Read ADC value
        int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer error\n");
            break;
        }

        uint16_t adc_value = ((spi_transfer.rx_buf[1] & 0x03) << 8) | spi_transfer.rx_buf[2];

        // Convert ADC value to PPM
        double ppm = (adc_value * PPM_CONSTANT) - PPM_OFFSET;

        // Classify reading
        char *msg;
        if (ppm > ALCOHOL_DETECTED_PPM) {
            msg = ALCOHOL_DETECTED_MSG;
        } else if (ppm < SOBER_PPM) {
            msg = SOBER_MSG;
        } else {
            msg = ALCOHOL_RANGE_MSG;
        }

        // Log reading
        fprintf(log_file, "%s: %f PPM\n", msg, ppm);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    close(spi_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

void sigint_handler(int signum) {
    // Clean up
    fclose(log_file);
    close(spi_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    exit(0);
}

