#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <pigpio.h>
#include <mcp3008.h>

#define SAMPLE_RATE 1000 // Hz
#define SAMPLE_PERIOD 1000000 / SAMPLE_RATE // us
#define CALIBRATION_TIME 5000000 // us
#define NOISE_THRESHOLD 10 // %
#define DEBOUNCE_TIME 10000 // us

#define LED_PIN 17
#define MCP3008_CS_PIN 8
#define MCP3008_MOSI_PIN 10
#define MCP3008_MISO_PIN 9
#define MCP3008_SCLK_PIN 11

int main(void) {
    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up MCP3008 SPI handle
    int spi_handle = spiOpen(MCP3008_CS_PIN, MCP3008_MOSI_PIN, MCP3008_MISO_PIN, MCP3008_SCLK_PIN);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        return 1;
    }

    // Set up GPIO pin for LED
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for LED\n");
        return 1;
    }

    // Calibrate for 5 seconds
    uint32_t calibration_start = pigpio_tick();
    uint32_t calibration_end = calibration_start + CALIBRATION_TIME;
    uint32_t calibration_samples = 0;
    uint32_t calibration_sum = 0;
    while (pigpio_tick() < calibration_end) {
        uint16_t sample = mcp3008_read(spi_handle);
        calibration_sum += sample;
        calibration_samples++;
    }
    uint32_t calibration_average = calibration_sum / calibration_samples;

    // Set noise threshold
    uint32_t noise_threshold = calibration_average * (1 + NOISE_THRESHOLD / 100.0);

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        uint16_t sample = mcp3008_read(spi_handle);
        if (sample > noise_threshold) {
            // Turn on LED
            gpioWrite(LED_PIN, PI_HIGH);

            // Debounce
            uint32_t debounce_start = pigpio_tick();
            uint32_t debounce_end = debounce_start + DEBOUNCE_TIME;
            while (pigpio_tick() < debounce_end) {
                if (gpioRead(LED_PIN) == PI_LOW) {
                    break;
                }
            }

            // Turn off LED
            gpioWrite(LED_PIN, PI_LOW);
        }

        // Sleep for sample period
        pigpio_sleep(SAMPLE_PERIOD);
    }

    // Cleanup
    spiClose(spi_handle);
    pigpio_stop();

    return 0;
}

void sigint_handler(int signum) {
    // Turn off LED
    gpioWrite(LED_PIN, PI_LOW);

    // Close SPI handle
    spiClose(spi_handle);

    // Stop pigpio
    pigpio_stop();

    // Exit
    exit(0);
}

