#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/spi/spidev.h>
#include <libgpiod/libgpiod.h>

#define MCP3008_SINGLE_ENDED_CH0_CMD 0x01
#define MCP3008_SINGLE_ENDED_CH0_CONFIG 0x08
#define MCP3008_SINGLE_ENDED_CH0_DUMMY 0x00

#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED 1000000

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NAME "gpio8"

#define AUDIO_LOG_FILE "audio_log.txt"

int main(void) {
    // Open the SPI device
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI mode, bits per word, and max speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Request the GPIO line
    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_NAME);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set the GPIO line as output
    if (gpiod_line_request_output(line, "cs", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open the audio log file
    FILE *audio_log = fopen(AUDIO_LOG_FILE, "w");
    if (!audio_log) {
        perror("Failed to open audio log file");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Set the sampling period
    struct timespec period = {.tv_sec = 0, .tv_nsec = 1000000};

    // Main loop
    while (1) {
        // Drive the CS line low
        gpiod_line_set_value(line, 0);

        // Send the MCP3008 single-ended channel-0 command
        uint8_t tx_buf[3] = {MCP3008_SINGLE_ENDED_CH0_CMD, MCP3008_SINGLE_ENDED_CH0_CONFIG, MCP3008_SINGLE_ENDED_CH0_DUMMY};
        uint8_t rx_buf[3];
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx_buf) < 0) {
            perror("Failed to send SPI message");
            gpiod_line_free(line);
            gpiod_chip_close(chip);
            close(spi_fd);
            fclose(audio_log);
            return EXIT_FAILURE;
        }

        // Parse the 10-bit result from rx_buf[1..2]
        uint16_t raw_adc_value = (rx_buf[1] << 8) | rx_buf[2];

        // Log the reading
        struct timespec timestamp;
        clock_gettime(CLOCK_MONOTONIC_RAW, &timestamp);
        fprintf(audio_log, "%ld|%u\n", timestamp.tv_nsec, raw_adc_value);
        fflush(audio_log);

        // Drive the CS line high
        gpiod_line_set_value(line, 1);

        // Sleep until the next sample deadline
        nanosleep(&period, NULL);
    }

    // Clean up on exit
    gpiod_line_free(line);
    gpiod_chip_close(chip);
    close(spi_fd);
    fclose(audio_log);

    return EXIT_SUCCESS;
}

