        return EXIT_FAILURE;
    }

    // Set the sampling period
    struct timespec period = {.tv_sec = 0, .tv_nsec = 1000000};

    // Main loop
    while (1) {
        // Drive the CS line low
        gpiod_line_set_value(line, 0);

        // Send the MCP3008 single-ended channel-0 command
        uint8_t tx_buf[3] = {MCP3008_SINGLE_ENDED_CH0_CMD, MCP3008_SINGLE_ENDED_CH0_CONFIG, MCP3008_SINGLE_ENDED_CH0_DUMMY};
        uint8_t rx_buf[3];
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx_buf) < 0) {
            perror("Failed to send SPI message");
            gpiod_line_free(line);
            gpiod_chip_close(chip);
            close(spi_fd);
            fclose(audio_log);
            return EXIT_FAILURE;
        }

        // Parse the 10-bit result from rx_buf[1..2]
        uint16_t raw_adc_value = (rx_buf[1] << 8) | rx_buf[2];

        // Log the reading
        struct timespec timestamp;
        clock_gettime(CLOCK_MONOTONIC_RAW, &timestamp);
        fprintf(audio_log, "%ld|%u\n", timestamp.tv_nsec, raw_adc_value);
        fflush(audio_log);

        // Drive the CS line high
        gpiod_line_set_value(line, 1);

        // Sleep until the next sample deadline
        nanosleep(&period, NULL);
    }

    // Clean up on exit
    gpiod_line_free(line);
    gpiod_chip_close(chip);
    close(spi_fd);
    fclose(audio_log);

    return EXIT_SUCCESS;
}
