#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <mcp3008.h>

#define ADXL335_SENSITIVITY 300 // mV/g
#define ADXL335_ZERO_BIAS 1500 // mV
#define ADC_REF_VOLTAGE 3300 // mV
#define ADC_RESOLUTION 10 // bits
#define ADC_CHANNELS 8

#define ADXL335_X_CHANNEL 0
#define ADXL335_Y_CHANNEL 1
#define ADXL335_Z_CHANNEL 2

#define ADC_CS_PIN 8
#define ADC_MOSI_PIN 10
#define ADC_MISO_PIN 9
#define ADC_SCLK_PIN 11

#define ADC_SPI_MODE 0
#define ADC_SPI_SPEED 1000000 // Hz

#define KALMAN_R 0.01 // process noise covariance
#define KALMAN_Q 0.01 // measurement noise covariance

#define SAMPLE_RATE 10 // Hz

// Kalman filter variables
float x_est = 0;
float x_est_cov = 0;
float y_est = 0;
float y_est_cov = 0;
float z_est = 0;
float z_est_cov = 0;

// SPI variables
int spi_fd;
struct spi_ioc_transfer spi_xfer;

// ADC variables
int adc_fd;
struct mcp3008_config adc_config;

// Signal handler
void sigint_handler(int signum) {
    printf("Received signal %d, terminating...\n", signum);
    // Clean up resources
    close(spi_fd);
    close(adc_fd);
    exit(0);
}

int main() {
    // Set up signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Set up SPI
    spi_fd = pigpio_spi_open(ADC_SPI_MODE, ADC_SPI_SPEED);
    if (spi_fd < 0) {
        printf("Failed to open SPI device: %s\n", strerror(errno));
        return 1;
    }

    // Set up ADC
    adc_fd = mcp3008_open(ADC_CS_PIN, ADC_MOSI_PIN, ADC_MISO_PIN, ADC_SCLK_PIN);
    if (adc_fd < 0) {
        printf("Failed to open ADC device: %s\n", strerror(errno));
        return 1;
    }

    // Set up ADC configuration
    adc_config.mode = MCP3008_MODE_SINGLE;
    adc_config.resolution = ADC_RESOLUTION;
    adc_config.channels = ADC_CHANNELS;
    adc_config.ref_voltage = ADC_REF_VOLTAGE;

    // Set up SPI transfer
    spi_xfer.tx_buf = (uint8_t *)malloc(sizeof(uint8_t) * 3);
    spi_xfer.rx_buf = (uint8_t *)malloc(sizeof(uint8_t) * 3);
    spi_xfer.len = 3;

    // Main loop
    while (1) {
        // Read acceleration values from ADXL335
        uint16_t x_raw = mcp3008_read(adc_fd, ADXL335_X_CHANNEL);
        uint16_t y_raw = mcp3008_read(adc_fd, ADXL335_Y_CHANNEL);
        uint16_t z_raw = mcp3008_read(adc_fd, ADXL335_Z_CHANNEL);

        // Scale acceleration values
        float x_scaled = (float)x_raw / ADXL335_SENSITIVITY;
        float y_scaled = (float)y_raw / ADXL335_SENSITIVITY;
        float z_scaled = (float)z_raw / ADXL335_SENSITIVITY;

        // Apply Kalman filter
        x_est = x_est + KALMAN_R * (x_scaled - x_est);
        x_est_cov = x_est_cov + KALMAN_Q;
        y_est = y_est + KALMAN_R * (y_scaled - y_est);
        y_est_cov = y_est_cov + KALMAN_Q;
        z_est = z_est + KALMAN_R * (z_scaled - z_est);
        z_est_cov = z_est_cov + KALMAN_Q;

        // Print filtered acceleration values
        printf("X: %f g, Y: %f g, Z: %f g\n", x_est, y_est, z_est);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up resources
    free(spi_xfer.tx_buf);
    free(spi_xfer.rx_buf);
    close(spi_fd);
    close(adc_fd);

    return 0;
}

