    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_line *sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (sensor1_line == NULL) {
        fprintf(stderr, "Error getting GPIO line for sensor 1: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_line *sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (sensor2_line == NULL) {
        fprintf(stderr, "Error getting GPIO line for sensor 2: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_line *sensor3_line = gpiod_chip_get_line(chip, SENSOR3_PIN);
    if (sensor3_line == NULL) {
        fprintf(stderr, "Error getting GPIO line for sensor 3: %s\n", strerror(errno));
        return 1;
    }

    // Set up the GPIO lines for input
    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0) {
        fprintf(stderr, "Error setting GPIO line for sensor 1 as input: %s\n", strerror(errno));
        return 1;
    }

    if (gpiod_line_request_input(sensor2_line, "sensor2") < 0) {
        fprintf(stderr, "Error setting GPIO line for sensor 2 as input: %s\n", strerror(errno));
        return 1;
    }

    if (gpiod_line_request_input(sensor3_line, "sensor3") < 0) {
        fprintf(stderr, "Error setting GPIO line for sensor 3 as input: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    while (running) {
        // Read the sensor values
        int sensor1_value = gpiod_line_get_value(sensor1_line);
        int sensor2_value = gpiod_line_get_value(sensor2_line);
        int sensor3_value = gpiod_line_get_value(sensor3_line);

        // Calculate the magnetic field strength
        double sensor1_mT = (sensor1_value - V_QUIESCENT) / SENSITIVITY;
        double sensor2_mT = (sensor2_value - V_QUIESCENT) / SENSITIVITY;
        double sensor3_mT = (sensor3_value - V_QUIESCENT) / SENSITIVITY;

        // Check for errors
        if (sensor1_mT < MIN_MAG_FIELD || sensor1_mT > MAX_MAG_FIELD) {
            fprintf(stderr, "Error: Sensor 1 magnetic field value out of range: %f\n", sensor1_mT);
            continue;
        }

        if (sensor2_mT < MIN_MAG_FIELD || sensor2_mT > MAX_MAG_FIELD) {
            fprintf(stderr, "Error: Sensor 2 magnetic field value out of range: %f\n", sensor2_mT);
            continue;
        }

        if (sensor3_mT < MIN_MAG_FIELD || sensor3_mT > MAX_MAG_FIELD) {
            fprintf(stderr, "Error: Sensor 3 magnetic field value out of range: %f\n", sensor3_mT);
            continue;
        }

        // Log the readings
        fprintf(log_file, "%f,%f,%f\n", sensor1_mT, sensor2_mT, sensor3_mT);
        fflush(log_file);

        // Sleep for 100 milliseconds
        usleep(100000);
    }

    // Clean up
    gpiod_line_release(sensor1_line);
    gpiod_line_release(sensor2_line);
    gpiod_line_release(sensor3_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}
