#define MCP3008_ADC_RANGE 1023
#define MCP3008_ADC_DRY 0
#define MCP3008_ADC_WET 30

#define WATER_PUMP_GPIO 17

#define WATERING_LOG_FILE "watering.log"

void handle_sigint(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    pigpio_stop();
    exit(0);
}

int main(void) {
    int adc_value;
    bool pump_on = false;
    FILE *log_file;

    // Initialize pigpio
    if (pigpio_start() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    // Set up SPI
    if (pigpio_spi_init(MCP3008_ADC_SPI_CE0, MCP3008_ADC_SPI_SPEED, MCP3008_ADC_SPI_MODE) < 0) {
        printf("Failed to initialize SPI\n");
        return 1;
    }

    // Set up GPIO
    if (pigpio_gpio_init(WATER_PUMP_GPIO) < 0) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);

    // Open log file
    log_file = fopen(WATERING_LOG_FILE, "a");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (true) {
        // Read ADC value
        adc_value = pigpio_spi_read(MCP3008_ADC_CHANNEL);
        if (adc_value < 0) {
            printf("Failed to read ADC value\n");
            continue;
        }

        // Check moisture level
        if (adc_value < MCP3008_ADC_DRY) {
            // Turn on pump
            if (!pump_on) {
                pump_on = true;
                pigpio_gpio_write(WATER_PUMP_GPIO, 1);
                fprintf(log_file, "Pump on at %s\n", ctime(&time(NULL)));
            }
        } else if (adc_value >= MCP3008_ADC_WET) {
            // Turn off pump
            if (pump_on) {
                pump_on = false;
                pigpio_gpio_write(WATER_PUMP_GPIO, 0);
                fprintf(log_file, "Pump off at %s\n", ctime(&time(NULL)));
            }
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up
    pigpio_stop();
    fclose(log_file);

    return 0;
}

