#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod/libgpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000

#define CHANNEL_0 0
#define CHANNEL_1 1
#define CHANNEL_2 2

#define DUMMY_BYTE 0x00

int main(void) {
    int spi_fd;
    int channel;
    uint8_t data[3];
    uint16_t value;
    FILE *csv_file;

    // Open SPI device
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    // Open CSV file
    csv_file = fopen("sensor_data.csv", "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(spi_fd);
        return 1;
    }

    // Read data from each channel
    for (channel = CHANNEL_0; channel <= CHANNEL_2; channel++) {
        // Send command to read channel
        data[0] = 0x01;
        data[1] = 0x80 | (channel << 4);
        data[2] = DUMMY_BYTE;
        if (write(spi_fd, data, 3) < 0) {
            perror("Failed to write to SPI device");
            close(spi_fd);
            fclose(csv_file);
            return 1;
        }

        // Read data from SPI device
        if (read(spi_fd, data, 3) < 0) {
            perror("Failed to read from SPI device");
            close(spi_fd);
            fclose(csv_file);
            return 1;
        }

        // Extract 10-bit value from data
        value = ((data[1] & 0x03) << 8) | data[2];

        // Write value to CSV file
        fprintf(csv_file, "%d, %d\n", channel, value);
    }

    // Close CSV file
    fclose(csv_file);

    // Close SPI device
    close(spi_fd);

    return 0;
}

