#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <mosquitto.h>
#include <cJSON.h>
#include <pigpio.h>

#define LED_PIN 17
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define MQTT_QOS 0

static bool gpio_initialized = false;
static bool led_state = false;

static void handle_sigint(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        // Disconnect MQTT
        mosquitto_disconnect(mosq);
        // Turn off the LED
        gpioWrite(LED_PIN, 0);
        // Release pigpio resources
        gpioTerminate();
        // Exit the program
        exit(0);
    }
}

static void handle_sigterm(int signal) {
    if (signal == SIGTERM) {
        printf("Received SIGTERM, shutting down...\n");
        // Disconnect MQTT
        mosquitto_disconnect(mosq);
        // Turn off the LED
        gpioWrite(LED_PIN, 0);
        // Release pigpio resources
        gpioTerminate();
        // Exit the program
        exit(0);
    }
}

static void handle_mqtt_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->topic == NULL || message->payload == NULL) {
        fprintf(stderr, "Error: Invalid MQTT message\n");
        return;
    }

    if (strcmp(message->topic, MQTT_TOPIC) != 0) {
        fprintf(stderr, "Error: Unexpected MQTT topic: %s\n", message->topic);
        return;
    }

    cJSON *json = cJSON_Parse(message->payload);
    if (json == NULL) {
        fprintf(stderr, "Error: Invalid JSON payload: %s\n", message->payload);
        return;
    }

    cJSON *led_state_json = cJSON_GetObjectItem(json, "led_state");
    if (led_state_json == NULL || !cJSON_IsBool(led_state_json)) {
        fprintf(stderr, "Error: Invalid JSON payload: %s\n", message->payload);
        cJSON_Delete(json);
        return;
    }

    led_state = led_state_json->valueint;
    gpioWrite(LED_PIN, led_state);

    cJSON_Delete(json);
}

static void handle_mqtt_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        fprintf(stderr, "Error: MQTT disconnected with error code %d\n", rc);
    }

    // Reconnect with exponential backoff
    mosquitto_reconnect(mosq);
}

int main(int argc, char *argv[]) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }
    gpio_initialized = true;

    // Set GPIO17 as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO17 as output\n");
        return 1;
    }

    // Turn off the LED on startup
    gpioWrite(LED_PIN, 0);

    // Initialize MQTT
    struct mosquitto *mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (mosq == NULL) {
        fprintf(stderr, "Error: Failed to create MQTT client\n");
        return 1;
    }

    // Set MQTT callbacks
    mosquitto_message_callback_set(mosq, handle_mqtt_message);
    mosquitto_disconnect_callback_set(mosq, handle_mqtt_disconnect);

    // Connect to MQTT broker
    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Failed to connect to MQTT broker\n");
        return 1;
    }

    // Subscribe to MQTT topic
    if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS) != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Failed to subscribe to MQTT topic\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Start MQTT loop
    mosquitto_loop_start(mosq);

    // Wait for signal or error
    while (true) {
        sleep(1);
    }

    // Clean up
    mosquitto_loop_stop(mosq, true);
    mosquitto_destroy(mosq);
    if (gpio_initialized) {
        gpioTerminate();
    }

    return 0;
}

