#include <string.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_PATH "/dev/gpiochip0"
#define GPIO_LINE_NUM 17
#define CONSUMER_LABEL "vibration-monitor"
#define LOG_FILE_PATH "/var/log/vibration_shutdown.log"

volatile sig_atomic_t stop_flag = 0;

void handle_signal(int signum) {
    stop_flag = 1;
}

int main(void) {
    // Open the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_path(GPIO_CHIP_PATH);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get the GPIO line
    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_NUM);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the line for falling-edge event detection
    if (gpiod_line_request_input(line, CONSUMER_LABEL) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (!stop_flag) {
        // Wait for a falling-edge event
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(line, &event) < 0) {
            perror("Failed to wait for GPIO line event");
            break;
        }

        // Read the event
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("Failed to read GPIO line event");
            break;
        }

        // Print the event to stdout
        printf("Vibration detected at %s\n", ctime(&event.timestamp));

        // Append a timestamped line to the log file
        FILE *fp = fopen(LOG_FILE_PATH, "a");
        if (!fp) {
            perror("Failed to open log file");
            break;
        }
        fprintf(fp, "%s\n", ctime(&event.timestamp));
        fclose(fp);

        // Shut down the system
        system("sudo shutdown -h now");
    }

    // Clean up
    gpiod_line_free(line);
    gpiod_chip_close(chip);

    return 0;
}

