#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define LM35_VREF 3.3
#define LM35_SCALE 10
#define MCP3008_SPI_START_BIT 0x01
#define MCP3008_SINGLE_ENDED_MODE_BIT 0x80
#define MCP3008_CHANNEL_0 0x80
#define MCP3008_DONT_CARE_BYTE 0x00
#define MCP3008_RESULT_MASK 0x03
#define MCP3008_RESULT_SHIFT 8
#define CIRCULAR_BUFFER_SIZE 120

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void sigterm_handler(int signum) {
    running = 0;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI device
    int spi_fd = pigpio_spi_open(0, 8, 11, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Set up circular buffer
    float circular_buffer[CIRCULAR_BUFFER_SIZE];
    int buffer_index = 0;

    // Main loop
    while (running) {
        // Read temperature
        uint8_t tx[3] = {MCP3008_SPI_START_BIT | MCP3008_SINGLE_ENDED_MODE_BIT | MCP3008_CHANNEL_0, MCP3008_DONT_CARE_BYTE, 0};
        uint8_t rx[3];
        if (pigpio_spi_xfer(spi_fd, tx, rx, 3) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }
        float temperature = (((rx[1] & MCP3008_RESULT_MASK) << MCP3008_RESULT_SHIFT) | rx[2]) * LM35_SCALE / LM35_VREF;

        // Log temperature
        printf("Temperature: %.2f °C\n", temperature);

        // Add temperature to circular buffer
        circular_buffer[buffer_index] = temperature;
        buffer_index = (buffer_index + 1) % CIRCULAR_BUFFER_SIZE;

        // Write circular buffer to file
        FILE *fp = fopen("temp_log.dat", "wb+");
        if (fp == NULL) {
            fprintf(stderr, "Failed to open file\n");
            continue;
        }
        fwrite(circular_buffer, sizeof(float), CIRCULAR_BUFFER_SIZE, fp);
        fclose(fp);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    pigpio_spi_close(spi_fd);
    gpioTerminate();

    return 0;
}

