int main(void) {
    // Initialize GPIO line for input with pull-down enabled
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!line) {
        fprintf(stderr, "Error: Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line, "flame_sensor") != 0) {
        fprintf(stderr, "Error: Failed to request GPIO line as input\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_set_pull(line, FLAME_SENSOR_PULL_DOWN) != 0) {
        fprintf(stderr, "Error: Failed to set pull-down on GPIO line\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file for writing
    FILE *log_file = fopen(FLAME_SENSOR_LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (true) {
        // Read GPIO line
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error: Failed to read GPIO line\n");
            gpiod_line_free(line);
            gpiod_chip_close(chip);
            fclose(log_file);
            return 1;
        }

