#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CS 0

#define ADC_CHANNELS 3
#define ADC_RESOLUTION 1023

#define MOISTURE_THRESHOLD 0.1

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI channel
    int spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_CS);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("soil_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC values
        uint16_t adc_values[ADC_CHANNELS];
        if (spiXfer(spi_fd, NULL, adc_values, ADC_CHANNELS) < 0) {
            fprintf(stderr, "Failed to read ADC values\n");
            continue;
        }

        // Convert ADC values to moisture percentages
        float moisture_percentages[ADC_CHANNELS];
        for (int i = 0; i < ADC_CHANNELS; i++) {
            float adc_value = adc_values[i];
            float moisture = (1.0 - (adc_value / ADC_RESOLUTION)) * 100.0;
            moisture_percentages[i] = moisture;
        }

        // Log readings
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(log_file, "%s", timestamp);
        for (int i = 0; i < ADC_CHANNELS; i++) {
            fprintf(log_file, ",%f", moisture_percentages[i]);
        }
        fprintf(log_file, "\n");

        // Sleep for 60 seconds
        gpioDelay(60000);
    }

    // Clean up
    fclose(log_file);
    spiClose(spi_fd);
    gpioTerminate();

    return 0;
}

