#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define THRESHOLD 500
#define DEBOUNCE_DELAY 10
#define LED_PIN 16

static int spi_fd;
static int adc_fd;
static int led_fd;

static void sigint_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    pigpio_stop(spi_fd);
    pigpio_stop(adc_fd);
    pigpio_stop(led_fd);
    exit(0);
}

int main(int argc, char **argv) {
    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI device
    spi_fd = pigpio_spi_open(0, 0, 1000000, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    // Open ADC device
    adc_fd = pigpio_adc_open(0, 0, 1000000, 0);
    if (adc_fd < 0) {
        fprintf(stderr, "Failed to open ADC device\n");
        return 1;
    }

    // Open LED device
    led_fd = pigpio_gpio_open(LED_PIN, 0);
    if (led_fd < 0) {
        fprintf(stderr, "Failed to open LED device\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read ADC value
        uint16_t adc_value = pigpio_adc_read(adc_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            return 1;
        }

        // Check if sound level exceeds threshold
        if (adc_value > THRESHOLD) {
            // Turn on LED
            pigpio_gpio_write(led_fd, 1);

            // Log timestamp to file
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
            FILE *fp = fopen("sound_events.log", "a");
            if (fp == NULL) {
                fprintf(stderr, "Failed to open file\n");
                return 1;
            }
            fprintf(fp, "%s\n", timestamp);
            fclose(fp);

            // Wait for debounce delay
            usleep(DEBOUNCE_DELAY * 1000);
        } else {
            // Turn off LED
            pigpio_gpio_write(led_fd, 0);
        }

        // Wait for next iteration
        usleep(10000);
    }

    // Clean up
    pigpio_stop(spi_fd);
    pigpio_stop(adc_fd);
    pigpio_stop(led_fd);
    return 0;
}

