    // Open ADC device
    adc_fd = pigpio_adc_open(0, 0, 1000000, 0);
    if (adc_fd < 0) {
        fprintf(stderr, "Failed to open ADC device\n");
        return 1;
    }

    // Open LED device
    led_fd = pigpio_gpio_open(LED_PIN, 0);
    if (led_fd < 0) {
        fprintf(stderr, "Failed to open LED device\n");
        return 1;
    }

