                pigpio_write(L298N_IN2, 0);
                pigpio_write(L298N_ENA, L298N_SPEED);
                usleep(3000000);
                window_state = MCP3008_WINDOW_OPEN;
            }
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Cleanup
