#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 16
#define MIC_PIN 26
#define THRESHOLD 700
#define DEBOUNCE_MS 50

static bool g_running = true;

static void sigint_handler(int signum) {
    g_running = false;
}

static void print_timestamp(void) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    printf("%02d:%02d:%02d ", tm->tm_hour, tm->tm_min, tm->tm_sec);
}

int main(void) {
    int ret;

    // Initialize pigpio
    if ((ret = pigpio_start(NULL, NULL)) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error(ret));
        return 1;
    }

    // Set up GPIO16 as an output for the LED
    if ((ret = pigpio_gpio_mode_set(LED_PIN, PI_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output: %s\n", LED_PIN, pigpio_error(ret));
        return 1;
    }

    // Set up GPIO26 as an input for the microphone
    if ((ret = pigpio_gpio_mode_set(MIC_PIN, PI_INPUT)) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %s\n", MIC_PIN, pigpio_error(ret));
        return 1;
    }

    // Set up the ADC to sample GPIO26
    if ((ret = pigpio_adc_init(MIC_PIN)) < 0) {
        fprintf(stderr, "Failed to initialize ADC: %s\n", pigpio_error(ret));
        return 1;
    }

    // Set up a SIGINT handler to cleanly shut down the program
    signal(SIGINT, sigint_handler);

    // Main loop
    while (g_running) {
        // Read the ADC value
        uint16_t adc_value = pigpio_adc_read(MIC_PIN);

        // Check if the value exceeds the threshold
        if (adc_value > THRESHOLD) {
            // Turn on the LED
            pigpio_gpio_write(LED_PIN, 1);

            // Print a timestamped detection message
            print_timestamp();
            printf("Clap detected!\n");

            // Wait for the debounce period
            usleep(DEBOUNCE_MS * 1000);

            // Turn off the LED
            pigpio_gpio_write(LED_PIN, 0);
        }
    }

    // Clean up
    pigpio_stop();

    return 0;
}

