#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod/libgpiod.h>

#define GPIO_PIN 17
#define A 26.0
#define B -6.0
#define THRESHOLD 200

static int gpio_fd;
static int log_fd;

static void handle_sigint(int signum) {
    if (gpio_fd >= 0) {
        close(gpio_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
    exit(0);
}

static void read_distance(void) {
    int value;
    double voltage;
    double distance;
    char timestamp[20];

    if (read(gpio_fd, &value, sizeof(value)) != sizeof(value)) {
        fprintf(stderr, "Error reading GPIO value\n");
        return;
    }

    voltage = value ? 3.3 : 0;
    distance = A / voltage + B;

    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    if (distance < THRESHOLD) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }

    if (log_fd >= 0) {
        dprintf(log_fd, "%s, %f\n", timestamp, distance);
    }
}

int main(void) {
    struct sigaction sa;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    gpio_fd = gpiod_line_fd(line);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error getting GPIO file descriptor\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_fd = open("distance_log.txt", O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Error opening log file\n");
        close(gpio_fd);
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        read_distance();
        sleep(1);
    }

    close(gpio_fd);
    close(log_fd);
    gpiod_line_free(line);
    gpiod_chip_close(chip);

    return 0;
}

