#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define SPI_DELAY 1000

#define PUMP_GPIO 17
#define PUMP_ON 1
#define PUMP_OFF 0

#define ADC_CHANNEL 0
#define ADC_CALIBRATION_DRY 800
#define ADC_CALIBRATION_WET 300

#define LOG_FILE "soil_moisture.log"

static int spi_fd;
static int pump_fd;
static int log_fd;

static void init_gpio(void) {
    // Initialize GPIO
    if (gpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    // Set up GPIO pins
    if (gpiod_export(PUMP_GPIO, GPIOD_OUT) < 0) {
        fprintf(stderr, "Failed to export GPIO pin %d\n", PUMP_GPIO);
        exit(1);
    }

    // Set up SPI
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device %s\n", SPI_DEVICE);
        exit(1);
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word\n");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_SPEED, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        exit(1);
    }

    // Set up log file
    if ((log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        exit(1);
    }
}

static void read_adc(void) {
    // Read ADC value
    uint16_t adc_value;
    if (read(spi_fd, &adc_value, sizeof(adc_value)) < 0) {
        fprintf(stderr, "Failed to read ADC value\n");
        exit(1);
    }

    // Calculate moisture percentage
    int moisture_percentage = (adc_value - ADC_CALIBRATION_DRY) * 100 / (ADC_CALIBRATION_WET - ADC_CALIBRATION_DRY);

    // Check if moisture level is below 30%
    if (moisture_percentage < 30) {
