#define SPI_MODE 0
#define SPI_BITS 8

#define GPIO_CHIP 0
#define GPIO_LINE 8

#define LOG_FILE "magnetic_log.txt"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static void sigterm_handler(int signum) {
    running = 0;
}

int main(void) {
    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGTERM, &sa, NULL);

    // Open the SPI device
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return 1;
    }

    // Set up the SPI mode and speed
    struct spi_ioc_transfer spi_transfer;
    memset(&spi_transfer, 0, sizeof(spi_transfer));
    spi_transfer.speed = SPI_SPEED;
    spi_transfer.mode = SPI_MODE;
    spi_transfer.bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
        perror("ioctl");
        close(spi_fd);
        return 1;
    }

    // Open the GPIO line
    int gpio_fd = gpiod_open(GPIO_CHIP, GPIO_LINE, GPIO_OUTPUT);
    if (gpio_fd < 0) {
        perror("gpiod_open");
        close(spi_fd);
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Read the ADC value
        uint16_t adc_value;
        if (read(spi_fd, &adc_value, sizeof(adc_value)) < 0) {
            perror("read");
            continue;
        }

        // Compute the magnetic field
        int32_t vout_mV = adc_value * MCP3008_VREF / 1023;
        int32_t b_mT = (vout_mV - DRV5055_A1_QUIESCENT) / DRV5055_A1_SENSITIVITY;

        // Print the magnetic field to the log file
        fprintf(log_file, "%ld,%.2f\n", time(NULL), b_mT / 100.0);

        // Sleep for 500 ms
        usleep(500000);
    }

    // Clean up
    fclose(log_file);
    close(gpio_fd);
    close(spi_fd);

    return 0;
}

