#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <mcp3008.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_DELAY 100

#define ADC_CHANNEL 0
#define ADC_BITS 10
#define ADC_VREF 3.3
#define ADC_SCALE 1023

#define LED_PIN 21
#define THRESHOLD 10.0

int main(void) {
    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Initialize SPI
    if (spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_BITS, SPI_DELAY) < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return 1;
    }

    // Initialize ADC
    if (mcp3008_init(ADC_CHANNEL, ADC_BITS, ADC_VREF, ADC_SCALE) < 0) {
        fprintf(stderr, "Failed to initialize ADC\n");
        return 1;
    }

    // Open file for logging
    FILE *fp = fopen("magnetic_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for logging\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read ADC value
        uint16_t adc_value = mcp3008_read(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            return 1;
        }

        // Convert ADC value to voltage
        float voltage = adc_value * ADC_VREF / ADC_SCALE;

        // Scale voltage to magnetic field strength
        float field_mT = (voltage - ADC_VREF / 2) * 1000 / 1.65;

        // Log field strength reading
        fprintf(fp, "%f\n", field_mT);

        // Check if field exceeds threshold
        if (field_mT > THRESHOLD) {
            // Turn on LED
            pigpio_write(LED_PIN, 1);
        } else {
            // Turn off LED
            pigpio_write(LED_PIN, 0);
        }

        // Delay for next reading
        usleep(SPI_DELAY * 1000);
    }

    // Cleanup
    fclose(fp);
    spi_close(SPI_CHANNEL);
    pigpio_stop();

    return 0;
}

void sigint_handler(int signum) {
    // Turn off LED
    pigpio_write(LED_PIN, 0);

    // Close SPI
    spi_close(SPI_CHANNEL);

    // Close pigpio
    pigpio_stop();

    // Exit program
    exit(0);
}

