#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define MCP3008_SPI_CHANNEL 0
#define MLX91211_SPI_CHANNEL 0
#define MLX91211_VDD_PIN 5
#define MLX91211_GND_PIN 6
#define MLX91211_SPI_SPEED 1000000
#define MLX91211_SPI_MODE 0
#define MLX91211_SPI_BITS 10
#define MLX91211_SPI_DELAY 100000

volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI0 at 1 MHz, mode 0
    if (spiOpen(0, MLX91211_SPI_SPEED, MLX91211_SPI_MODE, MLX91211_SPI_BITS) < 0) {
        fprintf(stderr, "Failed to open SPI0\n");
        gpioTerminate();
        return 1;
    }

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open log file
    FILE *log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(0);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!stop) {
        // Read MCP3008 channel 0
        uint8_t tx[3] = {0x01, 0x80 | (MCP3008_SPI_CHANNEL << 4), 0x00};
        uint8_t rx[3];
        if (spiXfer(0, tx, rx, 3) < 0) {
            fprintf(stderr, "Failed to read MCP3008 channel 0\n");
            continue;
        }

        // Compute 10-bit result
        uint16_t result = ((rx[1] & 0x03) << 8) | rx[2];

        // Convert to voltage
        float voltage = (float)result / 1023.0 * 5.0;

        // Convert to current
        float current = (voltage - 2.5) * (50.0 / 2.5);

        // Check for out-of-range voltage
        if (voltage < 0 || voltage > 5.0) {
            fprintf(stderr, "Voltage out of range: %f\n", voltage);
            continue;
        }

        // Print current and timestamp
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d %0.2f A\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec, current);
        fflush(log_file);

        // Delay
        gpioDelay(MLX91211_SPI_DELAY);
    }

    // Close log file
    fclose(log_file);

    // Close SPI0
    spiClose(0);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

