#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY 2

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        return 1;
    }

    // Request GPIO lines
    struct gpiod_line *sensor1_line = gpiod_line_request_input(chip, SENSOR1_GPIO);
    if (!sensor1_line) {
        fprintf(stderr, "Error: Failed to request GPIO line for sensor 1\n");
        gpiod_chip_close(chip);
        return 1;
    }
    struct gpiod_line *sensor2_line = gpiod_line_request_input(chip, SENSOR2_GPIO);
    if (!sensor2_line) {
        fprintf(stderr, "Error: Failed to request GPIO line for sensor 2\n");
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up debounce timer
    struct timespec debounce_timer;
    clock_gettime(CLOCK_MONOTONIC, &debounce_timer);
    debounce_timer.tv_nsec += DEBOUNCE_DELAY * 1000000;

    // Main loop
    while (running) {
        // Read sensor values
        bool sensor1_value = gpiod_line_get_value(sensor1_line);
        bool sensor2_value = gpiod_line_get_value(sensor2_line);

        // Debounce sensor values
        int debounce_count = 0;
        while (clock_gettime(CLOCK_MONOTONIC, &debounce_timer) < 0) {
            debounce_count++;
            if (debounce_count >= DEBOUNCE_SAMPLES) {
                break;
            }
            bool sensor1_value_debounced = gpiod_line_get_value(sensor1_line);
            bool sensor2_value_debounced = gpiod_line_get_value(sensor2_line);
            if (sensor1_value_debounced != sensor1_value || sensor2_value_debounced != sensor2_value) {
                sensor1_value = sensor1_value_debounced;
                sensor2_value = sensor2_value_debounced;
                debounce_count = 0;
            }
        }

        // Print sensor states
        printf("Sensor 1: %d\n", sensor1_value);
        printf("Sensor 2: %d\n", sensor2_value);

        // Check for alert
        if (sensor1_value && sensor2_value) {
            printf("ALERT: Both sensors detect object\n");
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Release GPIO lines
    gpiod_line_release(sensor1_line);
    gpiod_line_release(sensor2_line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

