#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t termination_flag = 0;

int read_mcp3008(int channel) {
    int rx_buf[3];
    int tx_buf[3];
    tx_buf[0] = 0x01;
    tx_buf[1] = 0x80 | (channel << 4);
    tx_buf[2] = 0x00;
    if (spi_xfer(SPI_CHANNEL, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }
    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

double calculate_moisture_level(int adc_value) {
    return 100.0 - ((adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
}

void log_data(double moisture_level) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    char line[50];
    snprintf(line, sizeof(line), "%s,%.2f\n", timestamp, moisture_level);
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open %s for writing\n", LOG_FILE);
        return;
    }
    fprintf(fp, "%s", line);
    fclose(fp);
}

void signal_handler(int signal) {
    termination_flag = 1;
}

void spi_setup(spi_config_t config) {
    if (spi_open(SPI_CHANNEL, config) != 0) {
        fprintf(stderr, "Error: Could not open SPI channel %d\n", SPI_CHANNEL);
        exit(1);
    }
}

int main(void) {
    if (pigpio_start(NULL, NULL) != 0) {
        fprintf(stderr, "Error: Could not start pigpio\n");
        exit(1);
    }

    spi_config_t config;
    config.baud = SPI_BAUD;
    config.mode = 0;
    config.bits = 8;
    config.lsb = 1;
    spi_setup(config);

    signal(SIGINT, signal_handler);

    while (!termination_flag) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Could not read MCP3008\n");
            continue;
        }
        double moisture_level = calculate_moisture_level(adc_value);
        log_data(moisture_level);
        printf("Moisture level: %.2f%%\n", moisture_level);
        sleep(READ_DELAY);
    }

    spi_close(SPI_CHANNEL);
    pigpio_stop();

    return 0;
}

