#define CAPTURE_DELAY 50
#define CAPTURE_WIDTH 1280
#define CAPTURE_HEIGHT 720
#define CAPTURE_FILENAME_FORMAT "/home/pi/security_cam/%Y-%m-%d_%H-%M-%S.jpg"

int main(int argc, char *argv[]) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set GPIO17 as input with pull-down resistor
    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 as input\n");
        return 1;
    }
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO17\n");
        return 1;
    }

    // Open syslog for logging
    openlog("security_cam", LOG_PID, LOG_USER);

    // Main loop
    while (1) {
        // Poll GPIO17 every 50 ms
        if (gpioRead(GPIO_PIN) < 0) {
            fprintf(stderr, "Failed to read GPIO17\n");
            return 1;
        }

        // Apply debounce delay
        usleep(DEBOUNCE_DELAY * 1000);

        // Re-read GPIO17 to confirm state
        if (gpioRead(GPIO_PIN) < 0) {
            fprintf(stderr, "Failed to read GPIO17\n");
            return 1;
        }

        // If state has changed, capture image
        if (gpioRead(GPIO_PIN) == 1) {
            // Construct output path
            char output_path[256];
            snprintf(output_path, sizeof(output_path), CAPTURE_FILENAME_FORMAT, time(NULL));

            // Check if target directory exists
            struct stat st = {0};
            if (stat(output_path, &st) < 0) {
                fprintf(stderr, "Failed to stat target directory\n");
                return 1;
            }

            // Execute libcamera-still
            char *args[] = {"libcamera-still", "-w", CAPTURE_WIDTH, "-h", CAPTURE_HEIGHT, "-o", output_path, NULL};
            int child_pid = fork();
            if (child_pid < 0) {
                fprintf(stderr, "Failed to fork\n");
                return 1;
            } else if (child_pid == 0) {
                // Child process
                execvp(args[0], args);
                fprintf(stderr, "Failed to execute libcamera-still\n");
                return 1;
            } else {
                // Parent process
                int child_status;
                waitpid(child_pid, &child_status, 0);
                if (child_status != 0) {
                    fprintf(stderr, "Failed to capture image\n");
                    return 1;
                }
            }

            // Log capture success
            syslog(LOG_INFO, "Captured image to %s", output_path);
        }

        // Sleep for 50 ms
        usleep(CAPTURE_DELAY * 1000);
    }

    // Release pigpio resources
    gpioTerminate();

    // Close syslog
    closelog();

    return 0;
}

