#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define CAMERA_WIDTH 640
#define CAMERA_HEIGHT 480
#define CAMERA_FPS 30
#define CAMERA_BUFFER_SIZE (CAMERA_WIDTH * CAMERA_HEIGHT * 1)

#define IMAGE_FILENAME_FORMAT "image_%04d.pgm"
#define IMAGE_FILENAME_LEN 12

int main(int argc, char *argv[]) {
    int camera_fd;
    struct v4l2_format format;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *buffer;
    int i, j;
    int frame_count = 0;
    char filename[IMAGE_FILENAME_LEN];

    // Open the camera device
    camera_fd = open("/dev/video0", O_RDWR);
    if (camera_fd < 0) {
        fprintf(stderr, "Error opening camera device: %s\n", strerror(errno));
        return 1;
    }

    // Set the camera format
    format.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    format.fmt.pix.width = CAMERA_WIDTH;
    format.fmt.pix.height = CAMERA_HEIGHT;
    format.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    format.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(camera_fd, VIDIOC_S_FMT, &format) < 0) {
        fprintf(stderr, "Error setting camera format: %s\n", strerror(errno));
        return 1;
    }

    // Request buffers
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(camera_fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return 1;
    }

    // Map the buffer
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (ioctl(camera_fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        return 1;
    }
    buffer = mmap(NULL, CAMERA_BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, camera_fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        return 1;
    }

    // Start streaming
    if (ioctl(camera_fd, VIDIOC_STREAMON, &buf.type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return 1;
    }

    // Capture frames
    while (1) {
        // Dequeue buffer
        if (ioctl(camera_fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) {
                // Timeout, try again
                continue;
            } else {
                fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
                return 1;
            }
        }

        // Save the frame
        snprintf(filename, IMAGE_FILENAME_LEN, IMAGE_FILENAME_FORMAT, frame_count);
        FILE *fp = fopen(filename, "wb");
        if (fp == NULL) {
            fprintf(stderr, "Error opening file: %s\n", strerror(errno));
            return 1;
        }
        fwrite(buffer, CAMERA_BUFFER_SIZE, 1, fp);
        fclose(fp);

        // Enqueue buffer
        if (ioctl(camera_fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "Error enqueuing buffer: %s\n", strerror(errno));
            return 1;
        }

        // Increment frame count
        frame_count++;
    }

    // Clean up
    if (munmap(buffer, CAMERA_BUFFER_SIZE) < 0) {
        fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
        return 1;
    }
    if (close(camera_fd) < 0) {
        fprintf(stderr, "Error closing camera device: %s\n", strerror(errno));
        return 1;
    }

    return 0;
}

