#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define FRAME_LOG_FILE "frame_log.txt"
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define FRAME_SIZE (FRAME_WIDTH * FRAME_HEIGHT * 3)

int main(int argc, char *argv[]) {
    int video_fd, log_fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *frame_buffer;
    fd_set fds;
    struct timeval tv;
    int ret;

    // Open video device
    video_fd = open(VIDEO_DEVICE, O_RDWR);
    if (video_fd < 0) {
        perror("Failed to open video device");
        return 1;
    }

    // Query device capabilities
    ret = ioctl(video_fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("Failed to query device capabilities");
        goto error;
    }

    // Set video format
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    ret = ioctl(video_fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        perror("Failed to set video format");
        goto error;
    }

    // Request buffers
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    ret = ioctl(video_fd, VIDIOC_REQBUFS, &req);
    if (ret < 0) {
        perror("Failed to request buffers");
        goto error;
    }

    // Map buffer
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    ret = ioctl(video_fd, VIDIOC_QUERYBUF, &buf);
    if (ret < 0) {
        perror("Failed to query buffer");
        goto error;
    }
    frame_buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, buf.m.offset);
    if (frame_buffer == MAP_FAILED) {
        perror("Failed to map buffer");
        goto error;
    }

    // Open log file
    log_fd = open(FRAME_LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        goto error;
    }

    // Set up select()
    FD_ZERO(&fds);
    FD_SET(video_fd, &fds);
    tv.tv_sec = 0;
    tv.tv_usec = 10000;

    while (1) {
        // Wait for frame
        ret = select(video_fd + 1, &fds, NULL, NULL, &tv);
        if (ret < 0) {
            perror("Failed to wait for frame");
            goto error;
        }
        if (ret == 0) {
            continue;
        }

        // Read frame
        ret = read(video_fd, frame_buffer, FRAME_SIZE);
        if (ret < 0) {
            perror("Failed to read frame");
            goto error;
        }

        // Log frame timestamp
        gettimeofday(&tv, NULL);
        ret = write(log_fd, &tv.tv_sec, sizeof(tv.tv_sec));
        if (ret < 0) {
            perror("Failed to write to log file");
            goto error;
        }
        ret = write(log_fd, &tv.tv_usec, sizeof(tv.tv_usec));
        if (ret < 0) {
            perror("Failed to write to log file");
            goto error;
        }
    }

error:
    // Clean up
    if (video_fd >= 0) {
        close(video_fd);
    }
    if (log_fd >= 0) {
        close(log_fd);
    }
    if (frame_buffer != MAP_FAILED) {
        munmap(frame_buffer, buf.length);
    }
    return 0;
}

