int main(int argc, char **argv) {
    // Open the camera device
    int fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open camera device");
        return 1;
    }

    // Query device capabilities
    struct v4l2_capability caps;
    if (ioctl(fd, VIDIOC_QUERYCAP, &caps) < 0) {
        perror("Failed to query device capabilities");
        return 1;
    }
    if (!(caps.capabilities & V4L2_CAP_VIDEO_CAPTURE) || !(caps.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support video capture and streaming\n");
        return 1;
    }

    // Request the format V4L2_PIX_FMT_MJPEG at 1920x1080 with V4L2_FIELD_NONE
    struct v4l2_format format = {
        .type = V4L2_BUF_TYPE_VIDEO_CAPTURE,
        .fmt.pix.width = 1920,
        .fmt.pix.height = 1080,
        .fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG,
        .fmt.pix.field = V4L2_FIELD_NONE,
    };
    if (ioctl(fd, VIDIOC_S_FMT, &format) < 0) {
        perror("Failed to set format");
        return 1;
    }

    // Request 4 MMAP buffers
    struct v4l2_requestbuffers req = {
        .count = BUFFER_COUNT,
        .type = V4L2_BUF_TYPE_VIDEO_CAPTURE,
        .memory = V4L2_MEMORY_MMAP,
    };
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        return 1;
    }

    // Query, mmap, and queue each buffer
    struct v4l2_buffer *buffers = calloc(BUFFER_COUNT, sizeof(struct v4l2_buffer));
    for (int i = 0; i < BUFFER_COUNT; i++) {
        buffers[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buffers[i].memory = V4L2_MEMORY_MMAP;
        if (ioctl(fd, VIDIOC_QUERYBUF, &buffers[i]) < 0) {
            perror("Failed to query buffer");
            return 1;
        }
        buffers[i].start = mmap(NULL, buffers[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buffers[i].m.offset);
        if (buffers[i].start == MAP_FAILED) {
            perror("Failed to mmap buffer");
            return 1;
        }
        if (ioctl(fd, VIDIOC_QBUF, &buffers[i]) < 0) {
            perror("Failed to queue buffer");
            return 1;
        }
    }

    // Start streaming
    if (ioctl(fd, VIDIOC_STREAMON, &format) < 0) {
        perror("Failed to start streaming");
        return 1;
    }

    // Dequeue a frame
    struct v4l2_buffer buf;
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Failed to dequeue buffer");
        return 1;
    }

    // Verify buf.bytesused > 0
    if (buf.bytesused == 0) {
        fprintf(stderr, "No data in buffer\n");
        return 1;
    }

    // Write the raw MJPEG bytes directly to disk
    FILE *fp = fopen(IMAGE_FILE, "wb");
    if (fp == NULL) {
        perror("Failed to open image file");
        return 1;
    }
    fwrite(buf.start, buf.bytesused, 1, fp);
    fclose(fp);

    // Clean up
    ioctl(fd, VIDIOC_STREAMOFF, 0);
    for (int i = 0; i < BUFFER_COUNT; i++) {
        munmap(buffers[i].start, buffers[i].length);
    }
    free(buffers);
    close(fd);

    return 0;
}

