#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define CAMERA_DEVICE "/dev/video0"

int main(int argc, char *argv[]) {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    struct v4l2_queryctrl queryctrl;

    // Open the camera device
    fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening camera device: %s\n", strerror(errno));
        return 1;
    }

    // Query camera capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "Error querying camera capabilities: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Enumerate supported frame sizes
    memset(&frmsize, 0, sizeof(frmsize));
    frmsize.index = 0;
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        printf("Frame size: %dx%d\n", frmsize.discrete.width, frmsize.discrete.height);
        frmsize.index++;
    }

    // Enumerate supported frame intervals
    memset(&frmival, 0, sizeof(frmival));
    frmival.index = 0;
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
        printf("Frame interval: %d/%d\n", frmival.discrete.numerator, frmival.discrete.denominator);
        frmival.index++;
    }

    // Check for autofocus support
    memset(&queryctrl, 0, sizeof(queryctrl));
    queryctrl.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) == -1) {
        fprintf(stderr, "Error querying focus control: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (queryctrl.flags & V4L2_CTRL_FLAG_DISABLED) {
        printf("Autofocus is not supported\n");
    } else {
        printf("Autofocus is supported\n");
    }

    // Close the camera device
    close(fd);

    return 0;
}

