#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

#define CENTER_POSITION 1500
#define MIN_POSITION 1000
#define MAX_POSITION 2000
#define POSITION_INCREMENT 10

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up internal pull-up resistors on all button pins
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set up PWM output on pan and tilt servos
    gpioServo(PAN_SERVO_PIN, CENTER_POSITION);
    gpioServo(TILT_SERVO_PIN, CENTER_POSITION);

    // Set up SIGINT/SIGTERM handler to cleanly stop PWM on both servo pins
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Print startup message
    printf("Pan-tilt system started on pins %d and %d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("Center position: %d\n", CENTER_POSITION);

    // Main loop
    while (1) {
        // Check if any button is pressed
        if (gpioRead(UP_BUTTON_PIN) == PI_LOW) {
            // Increment pan position
            int pan_position = gpioServo(PAN_SERVO_PIN, CENTER_POSITION + POSITION_INCREMENT);
            if (pan_position > MAX_POSITION) {
                pan_position = MAX_POSITION;
            }
            gpioServo(PAN_SERVO_PIN, pan_position);
        } else if (gpioRead(DOWN_BUTTON_PIN) == PI_LOW) {
            // Decrement pan position
            int pan_position = gpioServo(PAN_SERVO_PIN, CENTER_POSITION - POSITION_INCREMENT);
            if (pan_position < MIN_POSITION) {
                pan_position = MIN_POSITION;
            }
            gpioServo(PAN_SERVO_PIN, pan_position);
        } else if (gpioRead(LEFT_BUTTON_PIN) == PI_LOW) {
            // Increment tilt position
            int tilt_position = gpioServo(TILT_SERVO_PIN, CENTER_POSITION + POSITION_INCREMENT);
            if (tilt_position > MAX_POSITION) {
                tilt_position = MAX_POSITION;
            }
            gpioServo(TILT_SERVO_PIN, tilt_position);
        } else if (gpioRead(RIGHT_BUTTON_PIN) == PI_LOW) {
            // Decrement tilt position
            int tilt_position = gpioServo(TILT_SERVO_PIN, CENTER_POSITION - POSITION_INCREMENT);
            if (tilt_position < MIN_POSITION) {
                tilt_position = MIN_POSITION;
            }
            gpioServo(TILT_SERVO_PIN, tilt_position);
        }

        // Sleep for 50 ms
        usleep(50000);
    }

    // Clean up and exit
    gpioServo(PAN_SERVO_PIN, CENTER_POSITION);
    gpioServo(TILT_SERVO_PIN, CENTER_POSITION);
    gpioTerminate();
    return 0;
}

void sigint_handler(int signum) {
    // Stop PWM on both servo pins
    gpioServo(PAN_SERVO_PIN, CENTER_POSITION);
    gpioServo(TILT_SERVO_PIN, CENTER_POSITION);
    // Clean up and exit
    gpioTerminate();
    exit(0);
}

