    // Stop PWM on both servo pins
    gpioServo(PAN_SERVO_PIN, CENTER_POSITION);
    gpioServo(TILT_SERVO_PIN, CENTER_POSITION);
    // Clean up and exit
    gpioTerminate();
    exit(0);
}

