#define SERVER_PORT 8080

static int motion_pin;
static int motion_state;
static int motion_debounce_ms;
static int camera_resolution;
static int camera_quality;
static char *server_ip;
static int server_port;

static void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        gpioTerminate();
        curl_global_cleanup();
        exit(0);
    }
}

static void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    motion_pin = gpioGetPin(MOTION_PIN);
    if (motion_pin < 0) {
        fprintf(stderr, "Failed to get GPIO pin %d\n", MOTION_PIN);
        exit(1);
    }

    if (gpioSetMode(motion_pin, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin %d as input\n", MOTION_PIN);
        exit(1);
    }

    if (gpioSetPullUpDown(motion_pin, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set GPIO pin %d pull-down resistor\n", MOTION_PIN);
        exit(1);
    }
}

static void init_camera() {
    if (libcamera_still_init() < 0) {
        fprintf(stderr, "Failed to initialize camera\n");
        exit(1);
    }

    camera_resolution = CAMERA_RESOLUTION;
    camera_quality = CAMERA_QUALITY;
}

