#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod/libgpiod.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 50
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_QUALITY 85
#define IMAGE_TIMEOUT 2000

static int gpio_fd;
static int gpio_value;
static int gpio_event_fd;
static int gpio_event_value;
static int camera_fd;
static int camera_event_fd;
static int camera_event_value;

static void handle_gpio_event(int fd, short revents, void *arg) {
    if (revents & GPIOD_LINE_EVENT_RISING_EDGE) {
        gpio_value = 1;
    } else if (revents & GPIOD_LINE_EVENT_FALLING_EDGE) {
        gpio_value = 0;
    }
}

static void handle_camera_event(int fd, short revents, void *arg) {
    if (revents & GPIOD_LINE_EVENT_RISING_EDGE) {
        camera_value = 1;
    } else if (revents & GPIOD_LINE_EVENT_FALLING_EDGE) {
        camera_value = 0;
    }
}

static void handle_sigint(int signum) {
    printf("Received SIGINT, releasing GPIO resources and closing file descriptors\n");
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(gpio_fd);
    close(gpio_event_fd);
    close(camera_fd);
    close(camera_event_fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    // Set up GPIO chip and line
    gpiod_chip *gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        printf("Error opening GPIO chip\n");
        return 1;
    }
    gpiod_line *gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        printf("Error getting GPIO line\n");
        gpiod_chip_close(gpio_chip);
        return 1;
    }
    gpiod_line_request_input(gpio_line, "motion_capture");
    gpiod_line_set_debounce(gpio_line, DEBOUNCE_TIME);

    // Set up camera
    camera_fd = open("/dev/video0", O_RDWR);
    if (camera_fd < 0) {
        printf("Error opening camera\n");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }
    camera_event_fd = gpiod_line_event_get_fd(gpio_line);
    if (camera_event_fd < 0) {
        printf("Error getting camera event file descriptor\n");
        close(camera_fd);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Main loop
    while (1) {
        // Wait for GPIO event
        gpiod_line_event_wait(gpio_line, GPIOD_LINE_EVENT_RISING_EDGE | GPIOD_LINE_EVENT_FALLING_EDGE);
        gpiod_line_event_read(gpio_line, &gpio_event_value);
        if (gpio_event_value == 1) {
            // Motion detected, capture image
            char filename[20];
            time_t t = time(NULL);
            struct tm *tm = localtime(&t);
            strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S_%L.jpg", tm);
            char command[100];
            sprintf(command, "libcamera-still -o %s --width %d --height %d -q %d --timeout %d --nopreview", filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY, IMAGE_TIMEOUT);
            int ret = system(command);
            if (ret != 0) {
                printf("Error capturing image\n");
            } else {
                printf("Captured image %s\n", filename);
            }
        }
    }

    // Clean up
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(gpio_fd);
    close(gpio_event_fd);
    close(camera_fd);
    close(camera_event_fd);
    return 0;
}

