#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <linux/videodev2.h>

#define CAMERA_DEVICE "/dev/video0"
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define CROP_X 100
#define CROP_Y 50

int main(int argc, char *argv[]) {
    int fd, ret;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *data;
    FILE *fp;
    fd_set fds;
    struct timeval tv;

    // Open the camera device
    fd = open(CAMERA_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Check if the device is a V4L2 video capture device
    ret = ioctl(fd, VIDIOC_QUERYCAP, &cap);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a V4L2 video capture device\n");
        exit(EXIT_FAILURE);
    }

    // Negotiate format 640x480, V4L2_PIX_FMT_YUYV, V4L2_FIELD_NONE
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    ret = ioctl(fd, VIDIOC_S_FMT, &fmt);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    // Use memory-mapped streaming with one buffer
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    ret = ioctl(fd, VIDIOC_REQBUFS, &req);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    // Map the buffer
    ret = ioctl(fd, VIDIOC_QUERYBUF, &buf);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
    data = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (data == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    // Start streaming
    ret = ioctl(fd, VIDIOC_STREAMON, &buf.type);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    // Wait for the frame
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;
    ret = select(fd + 1, &fds, NULL, NULL, &tv);
    if (ret < 0) {
        perror("select");
        exit(EXIT_FAILURE);
    }
    if (ret == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        exit(EXIT_FAILURE);
    }

    // Dequeue the buffer
    ret = ioctl(fd, VIDIOC_DQBUF, &buf);
    if (ret < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    // Verify the captured width, height, and pixel format match the requested values
    if (buf.bytesused != 640 * 480 * 2) {
        fprintf(stderr, "Captured frame size does not match requested size\n");
        exit(EXIT_FAILURE);
    }
    if (buf.format.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Captured frame pixel format does not match requested pixel format\n");
        exit(EXIT_FAILURE);
    }

    // Crop the region starting at (100, 50) with size 200x150 from the YUYV frame
    // Copy complete 4-byte YUYV macroblocks (Y0, U, Y1, V) to avoid color corruption
    uint8_t *src = data;
    uint8_t *dst = malloc(CROP_WIDTH * CROP_HEIGHT * 2);
    for (int y = 0; y < CROP_HEIGHT; y++) {
        for (int x = 0; x < CROP_WIDTH; x++) {
            dst[y * CROP_WIDTH + x] = src[(y + CROP_Y) * 640 + x + CROP_X];
        }
    }

    // Save the cropped frame to cropped.yuv
    fp = fopen("cropped.yuv", "wb");
    if (fp == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    ret = fwrite(dst, CROP_WIDTH * CROP_HEIGHT * 2, 1, fp);
    if (ret < 0) {
        perror("fwrite");
        exit(EXIT_FAILURE);
    }
    fclose(fp);

    // Clean up
    munmap(data, buf.length);
    close(fd);
    free(dst);

    return 0;
}

