#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define PAN_GPIO 17
#define TILT_GPIO 18
#define PWM_FREQ 50
#define PWM_RANGE 180
#define PWM_NEUTRAL 90
#define PWM_MIN 500
#define PWM_MAX 2500

int main() {
    int pan_servo, tilt_servo;
    int pan_angle, tilt_angle;
    int pwm_width;
    char input;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up PWM for pan and tilt servos
    pan_servo = gpioPWM(PAN_GPIO, PWM_FREQ, PWM_RANGE);
    tilt_servo = gpioPWM(TILT_GPIO, PWM_FREQ, PWM_RANGE);

    // Set initial angles
    pan_angle = PWM_NEUTRAL;
    tilt_angle = PWM_NEUTRAL;

    // Set PWM widths
    pwm_width = (PWM_MAX - PWM_MIN) / PWM_RANGE;

    // Main loop
    while (1) {
        // Read input from stdin
        input = getchar();

        // Handle input
        switch (input) {
            case 'q':
                // Quit
                gpioPWM(pan_servo, 0, 0);
                gpioPWM(tilt_servo, 0, 0);
                gpioTerminate();
                return 0;
            case 'w':
                // Up
                pan_angle += 5;
                if (pan_angle > PWM_RANGE) {
                    pan_angle = PWM_RANGE;
                }
                gpioPWM(pan_servo, pan_angle, pwm_width);
                break;
            case 's':
                // Down
                pan_angle -= 5;
                if (pan_angle < 0) {
                    pan_angle = 0;
                }
                gpioPWM(pan_servo, pan_angle, pwm_width);
                break;
            case 'a':
                // Left
                tilt_angle += 5;
                if (tilt_angle > PWM_RANGE) {
                    tilt_angle = PWM_RANGE;
                }
                gpioPWM(tilt_servo, tilt_angle, pwm_width);
                break;
            case 'd':
                // Right
                tilt_angle -= 5;
                if (tilt_angle < 0) {
                    tilt_angle = 0;
                }
                gpioPWM(tilt_servo, tilt_angle, pwm_width);
                break;
            default:
                // Invalid input
                fprintf(stderr, "Invalid input: %c\n", input);
                break;
        }

        // Delay to prevent excessive CPU usage
        usleep(100000);
    }

    // Clean up
    gpioPWM(pan_servo, 0, 0);
    gpioPWM(tilt_servo, 0, 0);
    gpioTerminate();

    return 0;
}

