static void sigint_handler(int signum) {
    printf("Received SIGINT, releasing resources...\n");
    close(oled_fd);
    close(oled_i2c_fd);
    close(cpu_temp_fd);
    close(cpu_usage_fd);
    exit(0);
}

static void init_oled() {
    oled_fd = open("/dev/i2c-1", O_RDWR);
    if (oled_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    oled_i2c_fd = i2c_open(oled_fd, OLED_I2C_BUS, OLED_I2C_ADDR);
    if (oled_i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    oled_i2c_addr = i2c_get_addr(oled_i2c_fd);
    if (oled_i2c_addr < 0) {
        perror("Failed to get I2C address");
        exit(1);
    }

    if (i2c_set_addr(oled_i2c_fd, oled_i2c_addr) < 0) {
        perror("Failed to set I2C address");
        exit(1);
    }

    if (i2c_set_mode(oled_i2c_fd, I2C_MODE_WRITE) < 0) {
        perror("Failed to set I2C mode");
        exit(1);
    }

    if (i2c_set_speed(oled_i2c_fd, I2C_SPEED_FAST) < 0) {
        perror("Failed to set I2C speed");
        exit(1);
    }

    if (i2c_set_timeout(oled_i2c_fd, 1000) < 0) {
        perror("Failed to set I2C timeout");
        exit(1);
    }
}

static void init_cpu_temp() {
    cpu_temp_fd = open(CPU_TEMP_FILE, O_RDONLY);
    if (cpu_temp_fd < 0) {
        perror("Failed to open CPU temperature file");
        exit(1);
    }
}

static void init_cpu_usage() {
    cpu_usage_fd = open(CPU_USAGE_FILE, O_RDONLY);
    if (cpu_usage_fd < 0) {
        perror("Failed to open CPU usage file");
        exit(1);
    }
}

static void display_cpu_temp() {
    char temp_str[MAX_TEMP_STR_LEN];
    int temp;

    if (read(cpu_temp_fd, &temp, sizeof(temp)) < 0) {
        perror("Failed to read CPU temperature");
        return;
    }

    snprintf(temp_str, MAX_TEMP_STR_LEN, "CPU Temp: %d", temp);
    strcat(oled_display_str, temp_str);
}

static void display_cpu_usage() {
    char usage_str[MAX_USAGE_STR_LEN];
    int usage;

    if (read(cpu_usage_fd, &usage, sizeof(usage)) < 0) {
        perror("Failed to read CPU usage");
        return;
    }

    snprintf(usage_str, MAX_USAGE_STR_LEN, "CPU Usage: %d", usage);
    strcat(oled_display_str, usage_str);
}

static void display_oled() {
    if (i2c_write(oled_i2c_fd, oled_display_str, strlen(oled_display_str)) < 0) {
        perror("Failed to write to OLED display");
        return;
    }
}

int main() {
    signal(SIGINT, sigint_handler);

    init_oled();
    init_cpu_temp();
    init_cpu_usage();

    while (1) {
        display_cpu_temp();
        display_cpu_usage();
        display_oled();

        usleep(DISPLAY_UPDATE_INTERVAL);
    }

    return 0;
}

