#include <unistd.h>
#include <time.h>
#include <math.h>

#define GPIO_PIN 17
#define I2C_BUS 1
#define I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Function prototypes
void handle_sigint(int signal);
void handle_sigterm(int signal);
void init_gpio(void);
void init_i2c(void);
void read_pulses(void);
void calculate_flow_rate(void);
void update_lcd(void);

// Global variables
int gpio_handle;
int i2c_handle;
int pulses = 0;
int flow_rate = 0;
int volume = 0;

int main(void) {
    // Initialize GPIO and I2C
    init_gpio();
    init_i2c();

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Main loop
    while (true) {
        // Read pulses from sensor
        read_pulses();

        // Calculate flow rate
        calculate_flow_rate();

        // Update LCD display
        update_lcd();

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpioTerminate();
    i2cClose(i2c_handle);

    return 0;
}

void handle_sigint(int signal) {
    // Handle SIGINT signal
    printf("Received SIGINT signal, shutting down...\n");
    gpioTerminate();
    i2cClose(i2c_handle);
    exit(0);
}

void handle_sigterm(int signal) {
    // Handle SIGTERM signal
    printf("Received SIGTERM signal, shutting down...\n");
    gpioTerminate();
    i2cClose(i2c_handle);
    exit(0);
}

void init_gpio(void) {
    // Initialize GPIO
    gpio_handle = gpioInitialise();
    if (gpio_handle < 0) {
        printf("Failed to initialize GPIO\n");
        exit(1);
    }

    // Set up GPIO pin
    if (gpioSetMode(gpio_handle, GPIO_PIN, PI_INPUT) < 0) {
        printf("Failed to set GPIO pin mode\n");
        exit(1);
    }
}

void init_i2c(void) {
    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        printf("Failed to initialize I2C\n");
        exit(1);
    }
}

void read_pulses(void) {
    // Read pulses from sensor
    pulses = gpioRead(gpio_handle, GPIO_PIN);
    if (pulses < 0) {
        printf("Failed to read pulses from sensor\n");
        exit(1);
    }
}

void calculate_flow_rate(void) {
    // Calculate flow rate
    flow_rate = pulses * 450;
}

void update_lcd(void) {
    // Update LCD display
    char lcd_text[LCD_WIDTH * LCD_HEIGHT + 1];
    sprintf(lcd_text, "Flow rate: %d L/min", flow_rate);
    i2cWrite(i2c_handle, lcd_text, strlen(lcd_text));
}

