#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <wiringPiSPI.h>

#define LCD_ADDR 0x27
#define LCD_BUS 1
#define LCD_COLS 16
#define LCD_ROWS 2

#define AN_PIN 17
#define WV_PIN 0

#define WIND_SPEED_PER_PULSE 0.5
#define WIND_SPEED_SAMPLE_MS 500

#define WIND_VANE_MIN_DEG 0
#define WIND_VANE_MAX_DEG 359

#define ADC_MIN_VAL 0
#define ADC_MAX_VAL 1023

#define SPI_SPEED 1000000
#define SPI_MODE 0

#define I2C_SPEED 100000
#define I2C_MODE 0

#define SPI_DEV "/dev/spidev0.0"
#define I2C_DEV "/dev/i2c-1"

int main(int argc, char **argv) {
  // Initialize pigpio
  if (gpioInitialise() < 0) {
    fprintf(stderr, "Failed to initialize pigpio\n");
    return 1;
  }

  // Initialize I2C bus
  if (wiringPiI2CSetup(LCD_BUS) < 0) {
    fprintf(stderr, "Failed to initialize I2C bus\n");
    return 1;
  }

  // Initialize SPI bus
  if (wiringPiSPISetup(SPI_SPEED, SPI_MODE) < 0) {
    fprintf(stderr, "Failed to initialize SPI bus\n");
    return 1;
  }

  // Set up interrupt handler for anemometer
  if (gpioSetISRFunc(AN_PIN, RISING_EDGE, anemometer_isr, NULL) < 0) {
    fprintf(stderr, "Failed to set up interrupt handler for anemometer\n");
    return 1;
  }

  // Set up LCD
  if (lcdInit(LCD_ADDR, LCD_BUS, LCD_COLS, LCD_ROWS) < 0) {
    fprintf(stderr, "Failed to initialize LCD\n");
    return 1;
  }

  // Set up ADC
  if (adcInit(WV_PIN, ADC_MIN_VAL, ADC_MAX_VAL) < 0) {
    fprintf(stderr, "Failed to initialize ADC\n");
    return 1;
  }

  // Main loop
  while (true) {
    // Read anemometer pulses
    int an_pulses = gpioPulseIn(AN_PIN, RISING_EDGE, WIND_SPEED_SAMPLE_MS);

    // Compute wind speed
    float wind_speed = an_pulses * WIND_SPEED_PER_PULSE;

    // Read wind vane
    int wv_val = adcRead(WV_PIN);

    // Map wind vane value to degrees
    int wv_deg = map(wv_val, ADC_MIN_VAL, ADC_MAX_VAL, WIND_VANE_MIN_DEG, WIND_VANE_MAX_DEG);

