#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <lcd1602.h>

#define GPIO_PIN 17
#define CALIBRATION_FACTOR 7.5
#define SAMPLE_INTERVAL 1000
#define LCD_ADDRESS 0x27

static volatile bool running = true;

void sigint_handler(int signum) {
    running = false;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set GPIO pin mode
    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin mode\n");
        return 1;
    }

    // Set GPIO alert
    if (gpioSetAlertFunc(GPIO_PIN, GPIO_RISING_EDGE, NULL) < 0) {
        fprintf(stderr, "Failed to set GPIO alert\n");
        return 1;
    }

    // Open I2C bus
    if (i2cOpen(1, LCD_ADDRESS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Setup LCD1602 display
    if (lcd1602Init(1, LCD_ADDRESS, 0) < 0) {
        fprintf(stderr, "Failed to initialize LCD1602 display\n");
        return 1;
    }

    // Setup signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (running) {
        // Read GPIO pin
        int value = gpioRead(GPIO_PIN);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO pin\n");
            return 1;
        }

        // Calculate flow rate
        double flow_rate = value * CALIBRATION_FACTOR / SAMPLE_INTERVAL;

        // Display flow rate on LCD1602 display
        char buffer[16];
        snprintf(buffer, sizeof(buffer), "Flow Rate: %0.2f L/min", flow_rate);
        lcd1602Write(1, LCD_ADDRESS, 0, buffer);

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    gpioTerminate();
    i2cClose(1);
    lcd1602Terminate(1);

    return 0;
}

