#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define SCAN_DELAY 800

// GPIO pin numbers
#define ROW_PINS 17, 18, 27, 22, 23, 24, 25, 4
#define COL_PINS 5, 6, 12, 13, 19, 16, 26, 20

// Wave patterns
#define LEFT_TO_RIGHT 0
#define RIGHT_TO_LEFT 1

// GPIO context
struct gpiod_chip *chip;
struct gpiod_line *row_lines[NUM_ROWS];
struct gpiod_line *col_lines[NUM_COLS];

// Wave pattern
int wave_pattern = LEFT_TO_RIGHT;

// Scan delay
int scan_delay = SCAN_DELAY;

// Function to set GPIO lines to HIGH or LOW
void set_gpio(int pin, int value) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (line == NULL) {
        fprintf(stderr, "Error: Failed to get GPIO line for pin %d\n", pin);
        exit(1);
    }
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set GPIO line %d to %d\n", pin, value);
        exit(1);
    }
}

// Function to scan the LED matrix
void scan_matrix() {
    // Set all rows to LOW
    for (int i = 0; i < NUM_ROWS; i++) {
        set_gpio(ROW_PINS[i], 0);
    }

    // Set all columns to HIGH
    for (int i = 0; i < NUM_COLS; i++) {
        set_gpio(COL_PINS[i], 1);
    }

    // Scan the matrix
    for (int i = 0; i < NUM_ROWS; i++) {
        // Set the current row to HIGH
        set_gpio(ROW_PINS[i], 1);

        // Set the current column to LOW
        set_gpio(COL_PINS[i], 0);

        // Wait for the scan delay
        usleep(scan_delay);
    }
}

// Function to handle SIGINT signal
void sigint_handler(int signal) {
    // Release GPIO lines
    for (int i = 0; i < NUM_ROWS; i++) {
        gpiod_line_release(row_lines[i]);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        gpiod_line_release(col_lines[i]);
    }

    // Clean up
    gpiod_chip_close(chip);

    // Exit
    exit(0);
}

int main() {
    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        exit(1);
    }

    // Get GPIO lines
    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, ROW_PINS[i]);
        if (row_lines[i] == NULL) {
            fprintf(stderr, "Error: Failed to get GPIO line for row %d\n", i);
            exit(1);
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, COL_PINS[i]);
        if (col_lines[i] == NULL) {
            fprintf(stderr, "Error: Failed to get GPIO line for column %d\n", i);
            exit(1);
        }
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Scan the matrix
        scan_matrix();

        // Update wave pattern
        if (wave_pattern == LEFT_TO_RIGHT) {
            wave_pattern = RIGHT_TO_LEFT;
        } else {
            wave_pattern = LEFT_TO_RIGHT;
        }
    }

    // Clean up
    for (int i = 0; i < NUM_ROWS; i++) {
        gpiod_line_release(row_lines[i]);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        gpiod_line_release(col_lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

