#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define ROW_PINS 8
#define COL_PINS 8
#define DELAY_MS 150

static gpiod_chip *chip;
static gpiod_line *row_lines[ROW_PINS];
static gpiod_line *col_lines[COL_PINS];

void cleanup(int signum) {
    // Clean up GPIO lines
    for (int i = 0; i < ROW_PINS; i++) {
        gpiod_line_release(row_lines[i]);
    }
    for (int i = 0; i < COL_PINS; i++) {
        gpiod_line_release(col_lines[i]);
    }
    gpiod_chip_close(chip);
    exit(signum);
}

int main(int argc, char **argv) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request GPIO lines
    for (int i = 0; i < ROW_PINS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, i);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line for row %d\n", i);
            return 1;
        }
    }
    for (int i = 0; i < COL_PINS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, i + ROW_PINS);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line for column %d\n", i);
            return 1;
        }
    }

    // Set up signal handler for cleanup
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Set up GPIO lines for output
    for (int i = 0; i < ROW_PINS; i++) {
        gpiod_line_request_output(row_lines[i], "row", 0);
    }
    for (int i = 0; i < COL_PINS; i++) {
        gpiod_line_request_output(col_lines[i], "col", 0);
    }

    // Set up matrix
    for (int i = 0; i < ROW_PINS; i++) {
        gpiod_line_set_value(row_lines[i], 1);
    }
    for (int i = 0; i < COL_PINS; i++) {
        gpiod_line_set_value(col_lines[i], 0);
    }

    // Animate matrix
    while (1) {
        for (int i = 0; i < COL_PINS; i++) {
            // Set column cathode LOW and all row anodes HIGH
            gpiod_line_set_value(col_lines[i], 0);
            for (int j = 0; j < ROW_PINS; j++) {
                gpiod_line_set_value(row_lines[j], 1);
            }
            usleep(DELAY_MS * 1000);

            // Clear matrix
            for (int j = 0; j < ROW_PINS; j++) {
                gpiod_line_set_value(row_lines[j], 0);
            }
            for (int j = 0; j < COL_PINS; j++) {
                gpiod_line_set_value(col_lines[j], 1);
            }
        }
    }

    return 0;
}

