int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("depth_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Write CSV header row if file is new
    if (fseek(log_file, 0, SEEK_END) == 0) {
        fprintf(log_file, "timestamp,distance\n");
    }

    // Main loop
    while (1) {
        // Read distance register
        uint8_t reg_addr = DISTANCE_REG;
        uint8_t reg_data[2];
        if (i2cWrite(i2c_handle, &reg_addr, 1) < 0 || i2cRead(i2c_handle, reg_data, 2) < 0) {
            fprintf(stderr, "Failed to read distance register\n");
            fprintf(log_file, "%ld,%d\n", time(NULL), -1);
            continue;
        }

        // Convert distance to millimeters
        uint16_t distance = (reg_data[0] << 8) | reg_data[1];

        // Log distance reading
        fprintf(log_file, "%ld,%d\n", time(NULL), distance);

        // Sleep for sampling period
        usleep(SAMPLE_PERIOD * 1000);
    }

    // Close I2C handle and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

