#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_ADDR 0x60
#define PART_ID_REG 0x00
#define CMD_REG 0x18
#define MEASURE_RATE 0x01
#define CLEAR_IRQ 0x02

#define SAMPLE_RATE 500

int main(void) {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open the I2C bus
    int i2c_handle = i2cOpen(1, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify the PART ID register
    uint8_t part_id;
    if (i2cReadReg8(i2c_handle, PART_ID_REG, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART ID register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Invalid PART ID: 0x%02X\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    uint8_t cmd = MEASURE_RATE | CLEAR_IRQ;
    if (i2cWriteReg8(i2c_handle, CMD_REG, cmd) < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("biometric_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read the proximity and ambient light data
        uint16_t proximity, ambient;
        if (i2cReadReg16(i2c_handle, 0x04, &proximity) < 0 ||
            i2cReadReg16(i2c_handle, 0x06, &ambient) < 0) {
            fprintf(stderr, "Failed to read data\n");
            continue;
        }

        // Log the data
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02dT%02d:%02d:%02dZ, %d, %d\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec,
                proximity, ambient);

        // Sleep for the sample rate
        usleep(SAMPLE_RATE * 1000);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum) {
    // Close the I2C handle
    i2cClose(i2c_handle);

    // Flush and close the log file
    fflush(log_file);
    fclose(log_file);

    // Terminate the pigpio library
    gpioTerminate();

    // Exit the program
    exit(0);
}

