#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR_PIN 4
#define LED_PIN 17
#define POLL_INTERVAL 100

int main(void) {
    // Open the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            fprintf(stderr, "Error: unable to open GPIO chip\n");
            return 1;
        }
    }

    // Set up the sensor and LED lines
    struct gpiod_line *sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    struct gpiod_line *led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!sensor_line || !led_line) {
        fprintf(stderr, "Error: unable to get GPIO lines\n");
        return 1;
    }

    // Set the sensor line to input and the LED line to output
    gpiod_line_request_input(sensor_line, "sensor");
    gpiod_line_request_output(led_line, "led");

    // Set up the poll loop
    struct timespec poll_interval = {
        .tv_sec = POLL_INTERVAL / 1000,
        .tv_nsec = (POLL_INTERVAL % 1000) * 1000000
    };

    // Main loop
    while (1) {
        // Read the sensor value
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            fprintf(stderr, "Error: unable to read sensor value\n");
            return 1;
        }

        // If the sensor is triggered (i.e. an object is detected), blink the LED
        if (sensor_value == 0) {
            gpiod_line_set_value(led_line, 1);
            usleep(100000);
            gpiod_line_set_value(led_line, 0);

            // Log the event
            time_t now = time(NULL);
            struct tm *tm = gmtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);
            fprintf(stderr, "%s Object detected\n", timestamp);
        }

        // Sleep for the poll interval
        nanosleep(&poll_interval, NULL);
    }

    // Clean up
    gpiod_line_release(sensor_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return 0;
}

