#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60

#define PART_ID_REG 0x00
#define HW_KEY_REG 0x07
#define CH_LIST_REG 0x4F
#define COMMAND_REG 0x30
#define PS1_DATA_REG 0x18
#define ALS_VIS_DATA_REG 0x22

#define PS1_CHANNEL 0x01
#define ALS_VIS_CHANNEL 0x02

#define PS1_MEAS_RATE 0x01
#define ALS_VIS_MEAS_RATE 0x02

#define PS1_FORCE_MEAS 0x06
#define ALS_VIS_FORCE_MEAS 0x07

#define CSV_FILE "biometric_data.log"

int main(void) {
    // Initialize the I2C bus
    int i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", pigpio_i2c_error(i2c_handle));
        return 1;
    }

    // Verify the PART_ID register
    uint8_t part_id;
    if (pigpio_i2c_read(i2c_handle, PART_ID_REG, &part_id, 1) != 1) {
        fprintf(stderr, "Error reading PART_ID register: %s\n", pigpio_i2c_error(i2c_handle));
        return 1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Invalid PART_ID: 0x%02X\n", part_id);
        return 1;
    }

    // Write to the HW_KEY register
    uint8_t hw_key = 0x17;
    if (pigpio_i2c_write(i2c_handle, HW_KEY_REG, &hw_key, 1) != 1) {
        fprintf(stderr, "Error writing to HW_KEY register: %s\n", pigpio_i2c_error(i2c_handle));
        return 1;
    }

    // Enable the PS1 and ALS_VIS channels
    uint8_t ch_list = PS1_CHANNEL | ALS_VIS_CHANNEL;
    if (pigpio_i2c_write(i2c_handle, CH_LIST_REG, &ch_list, 1) != 1) {
        fprintf(stderr, "Error writing to CH_LIST register: %s\n", pigpio_i2c_error(i2c_handle));
        return 1;
    }

    // Configure the measurement rates
    uint8_t ps1_meas_rate = PS1_MEAS_RATE;
    uint8_t als_vis_meas_rate = ALS_VIS_MEAS_RATE;
    if (pigpio_i2c_write(i2c_handle, PS1_MEAS_RATE, &ps1_meas_rate, 1) != 1 ||
        pigpio_i2c_write(i2c_handle, ALS_VIS_MEAS_RATE, &als_vis_meas_rate, 1) != 1) {
        fprintf(stderr, "Error writing to measurement rate registers: %s\n", pigpio_i2c_error(i2c_handle));
        return 1;
    }

    // Use the COMMAND register to trigger measurements
    uint8_t command = PS1_FORCE_MEAS | ALS_VIS_FORCE_MEAS;
    if (pigpio_i2c_write(i2c_handle, COMMAND_REG, &command, 1) != 1) {
        fprintf(stderr, "Error writing to COMMAND register: %s\n", pigpio_i2c_error(i2c_handle));
        return 1;
    }

    // Open the CSV file for logging
    FILE *csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return 1;
    }

    // Set up the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Infinite loop to read and log data
    while (1) {
        // Read the PS1 data
        uint16_t ps1_data;
        if (pigpio_i2c_read(i2c_handle, PS1_DATA_REG, &ps1_data, 2) != 2) {
            fprintf(stderr, "Error reading PS1 data: %s\n", pigpio_i2c_error(i2c_handle));
            return 1;
        }

        // Read the ALS_VIS data
        uint16_t als_vis_data;
        if (pigpio_i2c_read(i2c_handle, ALS_VIS_DATA_REG, &als_vis_data, 2) != 2) {
            fprintf(stderr, "Error reading ALS_VIS data: %s\n", pigpio_i2c_error(i2c_handle));
            return 1;
        }

        // Log the data to the CSV file
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(csv_file, "%04d-%02d-%02dT%02d:%02d:%02d, %d, %d\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec,
                ps1_data, als_vis_data);
        fflush(csv_file);

        // Sleep for 1 second
        sleep(1);
    }

    // Close the I2C handle and CSV file
    pigpio_i2c_close(i2c_handle);
    fclose(csv_file);

    // Call gpioTerminate() for clean shutdown
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum) {
    // Close the I2C handle and CSV file
    pigpio_i2c_close(i2c_handle);
    fclose(csv_file);

    // Call gpioTerminate() for clean shutdown
    gpioTerminate();

    exit(0);
}

