#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define SENSOR_ID_REG 0x92
#define ENABLE_REG 0x80
#define ATIME_REG 0x81
#define WTIME_REG 0x83
#define PPULSE_REG 0x8E
#define CONTROL_REG 0xF1
#define CONFIG2_REG 0x90
#define RGB_DATA_REG 0x96
#define PROXIMITY_REG 0x9C

#define THRESHOLD 200

int main(void) {
    // Initialize pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus
    int i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Verify sensor ID
    uint8_t sensor_id;
    if (pigpio_i2c_read_byte(i2c_handle, SENSOR_ID_REG, &sensor_id) < 0) {
        fprintf(stderr, "Failed to read sensor ID\n");
        return 1;
    }
    if (sensor_id != 0xAB) {
        fprintf(stderr, "Invalid sensor ID: %02X\n", sensor_id);
        return 1;
    }

    // Configure sensor
    uint8_t enable = 0x03;
    uint8_t atime = 0xDB;
    uint8_t wtime = 0xF6;
    uint8_t ppulse = 0x87;
    uint8_t control = 0x03;
    uint8_t config2 = 0x01;
    if (pigpio_i2c_write_byte(i2c_handle, ENABLE_REG, enable) < 0 ||
        pigpio_i2c_write_byte(i2c_handle, ATIME_REG, atime) < 0 ||
        pigpio_i2c_write_byte(i2c_handle, WTIME_REG, wtime) < 0 ||
        pigpio_i2c_write_byte(i2c_handle, PPULSE_REG, ppulse) < 0 ||
        pigpio_i2c_write_byte(i2c_handle, CONTROL_REG, control) < 0 ||
        pigpio_i2c_write_byte(i2c_handle, CONFIG2_REG, config2) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        return 1;
    }

    // Open CSV file for logging
    FILE *csv_file = fopen("color_proximity_log.csv", "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read RGB data
        uint16_t r, g, b;
        if (pigpio_i2c_read_word(i2c_handle, RGB_DATA_REG, &r) < 0 ||
            pigpio_i2c_read_word(i2c_handle, RGB_DATA_REG + 2, &g) < 0 ||
            pigpio_i2c_read_word(i2c_handle, RGB_DATA_REG + 4, &b) < 0) {
            fprintf(stderr, "Failed to read RGB data\n");
            return 1;
        }

        // Read proximity data
        uint8_t proximity;
        if (pigpio_i2c_read_byte(i2c_handle, PROXIMITY_REG, &proximity) < 0) {
            fprintf(stderr, "Failed to read proximity data\n");
            return 1;
        }

        // Log data if proximity exceeds threshold
        if (proximity > THRESHOLD) {
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            fprintf(csv_file, "%04d-%02d-%02d %02d:%02d:%02d, %d, %d, %d, %d\n",
                    tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                    tm->tm_hour, tm->tm_min, tm->tm_sec,
                    r, g, b, proximity);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    fclose(csv_file);
    pigpio_i2c_close(i2c_handle);
    pigpio_stop();

    return 0;
}

void sigint_handler(int signum) {
    fprintf(stderr, "Received SIGINT\n");
    exit(1);
}

void sigterm_handler(int signum) {
    fprintf(stderr, "Received SIGTERM\n");
    exit(1);
}

