#include <linux/i2c.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_SLAVE_ADDR 0x5A
#define PART_ID_REG 0x00
#define MEAS_RATE0_REG 0x08
#define COMMAND_REG 0x47
#define PS_DATA0_REG 0x24
#define PS_DATA1_REG 0x25

#define BPM_TO_MS 60000

int main(void) {
    int fd;
    uint8_t part_id;
    uint8_t meas_rate;
    uint8_t command;
    uint16_t ps_data;
    uint16_t bpm;
    bool running = true;

    // Open I2C device
    fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
