#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <vl53l0x.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_PIN 17
#define TIMEOUT 100

#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B

#define DISTANCE_LOG "distance_log.txt"

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up GPIO pin 17 as input with pull-up
    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin mode\n");
        return 1;
    }
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO pin pull-up\n");
        return 1;
    }

    // Open I2C bus 1
    int i2c_handle = i2cOpen(I2C_BUS, 0, 0, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Verify sensor presence at 0x29
    uint8_t data[1];
    if (i2cReadDevice(i2c_handle, I2C_ADDR, data, 1) < 0) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return 1;
    }
    if (data[0] != 0xEE) {
        fprintf(stderr, "Sensor not present at 0x29\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(DISTANCE_LOG, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Wait for falling edge on GPIO pin 17
        if (gpioWaitForEdge(GPIO_PIN, PI_FALLING_EDGE, TIMEOUT) < 0) {
            fprintf(stderr, "Timeout waiting for GPIO edge\n");
            continue;
        }

        // Trigger single distance measurement
        if (i2cWriteByte(i2c_handle, I2C_ADDR, SYSRANGE_START) < 0) {
            fprintf(stderr, "Failed to write to I2C device\n");
            continue;
        }

        // Poll for result interrupt
        uint8_t result_interrupt_status;
        if (i2cReadByte(i2c_handle, I2C_ADDR, RESULT_INTERRUPT_STATUS, &result_interrupt_status) < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            continue;
        }
        if ((result_interrupt_status & 0x01) == 0) {
            fprintf(stderr, "Timeout waiting for result interrupt\n");
            continue;
        }

        // Read result block
        uint8_t result_block[14];
        if (i2cReadDevice(i2c_handle, I2C_ADDR, result_block, 14) < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            continue;
        }

        // Extract distance from result block
        uint16_t distance = (result_block[10] << 8) | result_block[11];

        // Clear interrupt
        if (i2cWriteByte(i2c_handle, I2C_ADDR, SYSTEM_INTERRUPT_CLEAR) < 0) {
            fprintf(stderr, "Failed to write to I2C device\n");
            continue;
        }

        // Log distance measurement
        time_t timestamp = time(NULL);
        fprintf(log_file, "%ld,%d\n", timestamp, distance);
    }

    // Close I2C handle and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Release pigpio resources
    pigpio_stop();

    return 0;
}

