#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x45
#define I2C_TIMEOUT 50
#define SAMPLE_INTERVAL 200

#define BUF_SIZE 32

static volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    int fd;
    int ret;
    uint16_t distance;
    char buf[BUF_SIZE];
    struct timespec ts;

    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    fd = pigpio_i2c_open(I2C_BUS, I2C_ADDR, I2C_TIMEOUT);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!stop) {
        // Trigger measurement
        ret = pigpio_i2c_write(fd, 0x00, 0x55, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to write to I2C bus\n");
            continue;
        }

        // Wait for measurement to complete
        usleep(I2C_TIMEOUT * 1000);

        // Read distance result
        ret = pigpio_i2c_read(fd, 0x00, &distance, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            continue;
        }

        // Convert distance to millimetres
        distance = (distance >> 2) * 10;

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);

        // Format timestamp
        strftime(buf, BUF_SIZE, "%F %T", &ts);

        // Log distance reading
        fprintf(stderr, "%s, %d\n", buf, distance);

        // Sleep for next sample
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Close I2C bus
    pigpio_i2c_close(fd);

    // Close pigpio
    pigpio_stop();

    return 0;
}

