    // Initialize GPIO pins
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set GPIO pins as inputs
    if (gpioSetMode(GPIO_PIN_17, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin %d as input\n", GPIO_PIN_17);
        return 1;
    }
    if (gpioSetMode(GPIO_PIN_18, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin %d as input\n", GPIO_PIN_18);
        return 1;
    }

    // Open file for logging
    FILE *fp = fopen("obstacle_log.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for logging\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (true) {
        // Read sensor values
        int val1 = gpioRead(GPIO_PIN_17);
        int val2 = gpioRead(GPIO_PIN_18);

        // Check for errors
        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "Failed to read sensor values\n");
            continue;
        }

        // Log values to file
        fprintf(fp, "%ld, %d, %d\n", time(NULL), val1, val2);

        // Sleep for POLL_INTERVAL milliseconds
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up on exit
    gpioTerminate();
    fclose(fp);

    return 0;
}

void sigint_handler(int signum) {
    // Clean up on SIGINT
    gpioTerminate();
    fclose(fp);

    exit(0);
