            pigpio_i2c_close(i2c_handle);
            fclose(log_file);
            pigpio_terminate();
            return 1;
        }

        // Read ambient light data
        while (retries < RETRY_COUNT) {
            if (pigpio_i2c_read(i2c_handle, AMBIENT_REG, &ambient_data, 2) == 0) {
                break;
            }
            retries++;
        }
