#include <pigpio.h>
#include <i2c.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define WHO_AM_I_REG 0x00
#define DISTANCE_REG 0x02
#define LED_GPIO 17

#define THRESHOLD 100

static volatile bool running = true;

void sigint_handler(int signum) {
    running = false;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    int threshold = atoi(argv[1]);

    if (threshold < 0) {
        fprintf(stderr, "Invalid threshold: %d\n", threshold);
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Initialize I2C handle
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
        return 1;
    }

    // Verify sensor ID
    uint8_t who_am_i;
    if (i2cReadReg8(i2c_handle, WHO_AM_I_REG, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read sensor ID\n");
        return 1;
    }
    if (who_am_i != 0x6A) {
        fprintf(stderr, "Invalid sensor ID: 0x%02X\n", who_am_i);
        return 1;
    }

    // Set up LED GPIO
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up LED GPIO\n");
        return 1;
    }

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (running) {
        // Read distance measurement
        uint16_t distance;
        if (i2cReadReg16(i2c_handle, DISTANCE_REG, &distance) < 0) {
            fprintf(stderr, "Failed to read distance measurement\n");
            return 1;
        }

        // Log distance measurement
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(stderr, "%s: Distance = %d mm\n", timestamp, distance);

        // Turn on LED if distance below threshold
        if (distance < threshold) {
            gpioWrite(LED_GPIO, PI_HIGH);
        } else {
            gpioWrite(LED_GPIO, PI_LOW);
        }

        // Sleep for 50 ms
        usleep(50000);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

