#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define SENSOR_ADDR 0x50
#define CMD_FRAME_LEN 4
#define RESP_FRAME_LEN 15
#define DIST_MM_OFFSET 11
#define DIST_MM_LEN 2
#define INTRUSION_THRESHOLD 1000
#define SAMPLE_COUNT 10
#define SAMPLE_DELAY 100

int main(void) {
    int fd;
    uint8_t cmd_frame[CMD_FRAME_LEN] = {0x50, 0x0A, 0x00, 0x01};
    uint8_t resp_frame[RESP_FRAME_LEN];
    uint16_t dist_mm;
    int i, j;
    double avg_dist;
    FILE *log_file;
    struct timespec ts;

    // Open I2C device
    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Open log file
    if ((log_file = fopen("intrusion_log.txt", "a")) == NULL) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Request distance measurement
        if (write(fd, cmd_frame, CMD_FRAME_LEN) != CMD_FRAME_LEN) {
            perror("Failed to write command frame");
            close(fd);
            fclose(log_file);
            return 1;
        }

        // Wait for response
        usleep(10000);

        // Read response frame
        if (read(fd, resp_frame, RESP_FRAME_LEN) != RESP_FRAME_LEN) {
            perror("Failed to read response frame");
            close(fd);
            fclose(log_file);
            return 1;
        }

        // Validate header
        if (resp_frame[0] != 0x50) {
            fprintf(stderr, "Invalid response header\n");
            continue;
        }

        // Extract distance
        dist_mm = (resp_frame[DIST_MM_OFFSET] << 8) | resp_frame[DIST_MM_OFFSET + 1];

        // Calculate average distance
        avg_dist = 0;
        for (i = 0; i < SAMPLE_COUNT; i++) {
            // Request distance measurement
            if (write(fd, cmd_frame, CMD_FRAME_LEN) != CMD_FRAME_LEN) {
                perror("Failed to write command frame");
                close(fd);
                fclose(log_file);
                return 1;
            }

            // Wait for response
            usleep(10000);

            // Read response frame
            if (read(fd, resp_frame, RESP_FRAME_LEN) != RESP_FRAME_LEN) {
                perror("Failed to read response frame");
                close(fd);
                fclose(log_file);
                return 1;
            }

            // Validate header
            if (resp_frame[0] != 0x50) {
                fprintf(stderr, "Invalid response header\n");
                continue;
            }

            // Extract distance
            dist_mm = (resp_frame[DIST_MM_OFFSET] << 8) | resp_frame[DIST_MM_OFFSET + 1];

            // Add to average
            avg_dist += dist_mm;
        }
        avg_dist /= SAMPLE_COUNT;

        // Check for intrusion
        if (avg_dist < INTRUSION_THRESHOLD) {
            // Log event
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%ld: Intrusion detected, average distance: %f mm\n", ts.tv_sec, ts.tv_nsec, avg_dist);
        }

        // Wait for next cycle
        usleep(SAMPLE_DELAY);
    }

    // Clean up
    close(fd);
    fclose(log_file);

    return 0;
}

