    uint8_t status;
    struct timespec timeout;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Open the I2C device
    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Verify the sensor is present
    if (i2cReadReg8(i2c_fd, MODEL_ID_REG, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID register: %s\n", strerror(errno));
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (model_id != 0xEE) {
        fprintf(stderr, "Invalid model ID: %02X\n", model_id);
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up the timeout
    timeout.tv_sec = TIMEOUT_MS / 1000;
    timeout.tv_nsec = (TIMEOUT_MS % 1000) * 1000000;

    // Start the ranging loop
    while (1) {
        // Write 0x01 to SYSRANGE_START to begin a measurement
        if (i2cWriteReg8(i2c_fd, SYSRANGE_START, 0x01) < 0) {
            fprintf(stderr, "Failed to write to SYSRANGE_START: %s\n", strerror(errno));
            continue;
        }

        // Poll RESULT_INTERRUPT_STATUS until bit 0 is set
        while (1) {
            if (i2cReadReg8(i2c_fd, RESULT_INTERRUPT_STATUS, &status) < 0) {
                fprintf(stderr, "Failed to read RESULT_INTERRUPT_STATUS: %s\n", strerror(errno));
                continue;
            }
            if (status & 0x01) {
                break;
            }
            nanosleep(&timeout, NULL);
        }

        // Read the 16-bit distance from RESULT_RANGE_STATUS
        if (i2cReadReg16(i2c_fd, RESULT_RANGE_STATUS, &distance) < 0) {
            fprintf(stderr, "Failed to read RESULT_RANGE_STATUS: %s\n", strerror(errno));
            continue;
        }

        // Clear the interrupt by writing 0x01 to SYSTEM_INTERRUPT_CLEAR
        if (i2cWriteReg8(i2c_fd, SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
            fprintf(stderr, "Failed to write to SYSTEM_INTERRUPT_CLEAR: %s\n", strerror(errno));
            continue;
        }

        // Print the reading to stdout
        printf("%s Distance: %d mm\n", ctime(&(time_t){time(NULL)}), distance);

        // Sleep for POLL_INTERVAL_MS
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

