#define SENSOR_ADDR 0x39
#define CONFIG_REG 0x18
#define IRQ_REG 0x25
#define PROX_LSB_REG 0x2A
#define PROX_MSB_REG 0x2B

int main(void) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus 1
    int i2c_fd = i2cOpen(1, 0, 0, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    uint8_t config = 0x01;
    if (i2cWrite(i2c_fd, SENSOR_ADDR, CONFIG_REG, &config, 1) < 0) {
        fprintf(stderr, "Failed to write to sensor\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Check if data is ready
        uint8_t irq_status;
        if (i2cRead(i2c_fd, SENSOR_ADDR, IRQ_REG, &irq_status, 1) < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        if (irq_status & 0x01) {
            // Read proximity data
            uint16_t prox_data;
            if (i2cRead(i2c_fd, SENSOR_ADDR, PROX_LSB_REG, &prox_data, 2) < 0) {
                fprintf(stderr, "Failed to read from sensor\n");
                i2cClose(i2c_fd);
                gpioTerminate();
                return 1;
            }

            // Print proximity data
            printf("Proximity data: %u\n", prox_data);
        }

        // Sleep for 500 ms
        usleep(500000);
    }

    // Clean up
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum) {
    // Clean up
    i2cClose(i2c_fd);
    gpioTerminate();

    // Exit
    exit(0);
}

