#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEV "/dev/i2c-1"
#define MLX75030_ADDR 0x4C
#define DISTANCE_REG 0x00
#define DISTANCE_FACTOR 0.125

int main(void) {
    int fd;
    uint8_t buf[2];
    uint16_t distance;

    // Open I2C device
    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set slave address
    if (ioctl(fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        perror("Failed to set slave address");
        close(fd);
        return 1;
    }

    // Verify device responds
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read from device");
        close(fd);
        return 1;
    }

    // Set up SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        // Read distance register
        if (read(fd, buf, 2) != 2) {
            fprintf(stderr, "Failed to read distance register\n");
            continue;
        }

        // Convert raw value to millimetres
        distance = (buf[0] << 8) | buf[1];
        distance *= DISTANCE_FACTOR;

        // Print distance
        printf("Distance: %d mm\n", distance);

        // Sleep for 500 ms
        usleep(500000);
    }

    // Close I2C device
    close(fd);

    return 0;
}

void sigint_handler(int signum) {
    close(fd);
    exit(0);
}

