#define OPT3101_REG_DISTANCE 0x00
#define OPT3101_REG_AMBIENT_LIGHT 0x01
#define OPT3101_REG_ERROR_FLAGS 0x02

#define I2C_BUS 1

int main(void) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up I2C bus
    if (gpioI2CSetup(I2C_BUS, 100000) < 0) {
        fprintf(stderr, "Failed to set up I2C bus\n");
        return 1;
    }

    // Set up signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read distance data
        uint16_t distance = read_distance();
        if (distance == 0) {
            fprintf(stderr, "Failed to read distance data\n");
            continue;
        }

        // Read ambient light data
        uint16_t ambient_light = read_ambient_light();
        if (ambient_light == 0) {
            fprintf(stderr, "Failed to read ambient light data\n");
            continue;
        }

        // Read error flags
        uint8_t error_flags = read_error_flags();
        if (error_flags != 0) {
            fprintf(stderr, "Error flags: 0x%02X\n", error_flags);
        }

        // Log data to console
        printf("Distance: %d mm, Ambient light: %d lux, Error flags: 0x%02X\n", distance, ambient_light, error_flags);

        // Sleep for 500 ms
        usleep(500000);
    }

    // Clean up resources
    gpioTerminate();

    return 0;
}

