    uint16_t distance = 0;

    // Read distance data from sensor
    if (gpioI2CReadReg16(I2C_BUS, OPT3101_I2C_ADDR, OPT3101_REG_DISTANCE, &distance) < 0) {
        return 0;
    }

    return distance;
}

