    uint16_t ambient_light = 0;

    // Read ambient light data from sensor
    if (gpioI2CReadReg16(I2C_BUS, OPT3101_I2C_ADDR, OPT3101_REG_AMBIENT_LIGHT, &ambient_light) < 0) {
        return 0;
