#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define RESISTOR_VALUE 1000
#define MAX_PULSE_DURATION 38000
#define TIMEOUT_MS 200

static volatile bool running = true;

void sigint_handler(int signal) {
    running = false;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", TRIG_PIN);
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", ECHO_PIN);
        return 1;
    }

    // Set up resistor in series on echo line
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO %d\n", ECHO_PIN);
        return 1;
    }

    // Set up signal handler for SIGINT/SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (running) {
        // Send trigger pulse
        if (gpioWrite(TRIG_PIN, PI_HIGH) < 0) {
            fprintf(stderr, "Failed to write to GPIO %d\n", TRIG_PIN);
            return 1;
        }
        gpioDelay(10);
        if (gpioWrite(TRIG_PIN, PI_LOW) < 0) {
            fprintf(stderr, "Failed to write to GPIO %d\n", TRIG_PIN);
            return 1;
        }

        // Wait for echo rising edge
        uint32_t rising_edge_tick = gpioTick();
        while (gpioRead(ECHO_PIN) == PI_LOW) {
            if (gpioTick() - rising_edge_tick > TIMEOUT_MS) {
                fprintf(stderr, "Echo rising edge timeout\n");
                return 1;
            }
        }

        // Wait for echo falling edge
        uint32_t falling_edge_tick = gpioTick();
        while (gpioRead(ECHO_PIN) == PI_HIGH) {
            if (gpioTick() - falling_edge_tick > TIMEOUT_MS) {
                fprintf(stderr, "Echo falling edge timeout\n");
                return 1;
            }
        }

        // Compute pulse duration
        uint32_t pulse_duration = gpioTick() - rising_edge_tick;
        if (pulse_duration <= 0 || pulse_duration > MAX_PULSE_DURATION) {
            fprintf(stderr, "Invalid pulse duration: %d\n", pulse_duration);
            return 1;
        }

        // Compute distance
        uint32_t distance = (pulse_duration * 0.0343) / 2;

        // Log reading
        printf("Distance: %d cm\n", distance);

        // Wait for next second
        gpioDelay(1000000 - gpioTick() % 1000000);
    }

    // Shut down gracefully
    gpioTerminate();

    return 0;
}

