#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define BUZZER_PIN 18
#define SENSOR_PIN 17
#define POLL_INTERVAL 100

static bool buzzer_state = false;
static bool sensor_state = false;
static bool sensor_prev_state = false;

static void handle_sigint(int signal) {
    printf("Received SIGINT, shutting down...\n");
    gpiod_line_release(BUZZER_PIN);
    gpiod_line_release(SENSOR_PIN);
    gpiod_chip_close(chip);
    exit(0);
}

static void handle_sigterm(int signal) {
    printf("Received SIGTERM, shutting down...\n");
    gpiod_line_release(BUZZER_PIN);
    gpiod_line_release(SENSOR_PIN);
    gpiod_chip_close(chip);
    exit(0);
}

static void handle_sensor_change(void) {
    if (sensor_state != sensor_prev_state) {
        if (sensor_state) {
            printf("Obstacle detected at %s\n", asctime(localtime(&time(NULL))));
            gpiod_line_set_value(BUZZER_PIN, 1);
        } else {
            printf("Obstacle removed at %s\n", asctime(localtime(&time(NULL))));
            gpiod_line_set_value(BUZZER_PIN, 0);
        }
        sensor_prev_state = sensor_state;
    }
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *buzzer_line;
    struct gpiod_line *sensor_line;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        printf("Failed to open GPIO chip\n");
        return 1;
    }

    // Request the buzzer and sensor lines
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        printf("Failed to get buzzer line\n");
        gpiod_chip_close(chip);
        return 1;
    }
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        printf("Failed to get sensor line\n");
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the buzzer and sensor lines to output
    gpiod_line_request_output(buzzer_line, "buzzer", 0);
    gpiod_line_request_output(sensor_line, "sensor", 0);

    // Set the buzzer to off
    gpiod_line_set_value(buzzer_line, 0);

    // Set the sensor to input
    gpiod_line_set_value(sensor_line, 0);

    // Register signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Poll the sensor every POLL_INTERVAL ms
    while (true) {
        // Read the sensor state
        sensor_state = gpiod_line_get_value(sensor_line);

        // Handle sensor state change
        handle_sensor_change();

        // Sleep for POLL_INTERVAL ms
        usleep(POLL_INTERVAL * 1000);
    }

    // Release the GPIO lines and close the chip
    gpiod_line_release(buzzer_line);
    gpiod_line_release(sensor_line);
    gpiod_chip_close(chip);

    return 0;
}

