#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x69
#define DISTANCE_REG 0x31
#define DISTANCE_LOW_REG 0x32
#define ALERT_PIN 17
#define ALERT_PIN_BCM 17
#define SAMPLE_INTERVAL 100

static volatile sig_atomic_t shutdown_requested = 0;

void handle_signal(int signum) {
    shutdown_requested = 1;
}

int main(void) {
    // Set up signal handler for SIGINT/SIGTERM
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up I2C bus
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Set up GPIO pin for alert
    if (gpioSetMode(ALERT_PIN_BCM, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin mode\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("distance_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (!shutdown_requested) {
        // Check for signal-requested shutdown
        if (shutdown_requested) {
            break;
        }

        // Read distance measurement
        uint16_t distance = 0;
        if (i2cReadWordData(i2c_handle, DISTANCE_REG) < 0) {
            fprintf(stderr, "Failed to read distance measurement\n");
            return 1;
        }
        distance = (distance << 8) | i2cReadByteData(i2c_handle, DISTANCE_LOW_REG);

        // Write log entry
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
        fprintf(log_file, "%s, %d\n", timestamp, distance);

        // Trigger alert if distance falls below 10.0 cm
        if (distance < 100) {
            gpioWrite(ALERT_PIN_BCM, PI_HIGH);
        }

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Clean up
    fclose(log_file);
    gpioWrite(ALERT_PIN_BCM, PI_LOW);
    gpioTerminate();
    i2cClose(i2c_handle);

    return 0;
}

