#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define VL53L1X_I2C_ADDR 0x29
#define VL53L1X_MODEL_ID_REG 0x010F
#define VL53L1X_SYSTEM_MODE_START_REG 0x007
#define VL53L1X_SYSRANGE_START_REG 0x000
#define VL53L1X_RESULT_INTERRUPT_STATUS_REG 0x013
#define VL53L1X_RESULT_RANGE_STATUS_REG 0x078
#define VL53L1X_SYSTEM_INTERRUPT_CLEAR_REG 0x014

#define DISTANCE_LOG_FILE "distance_log.csv"

#define STOP_THRESHOLD 300
#define APPROACH_THRESHOLD 600
#define SLOW_THRESHOLD 1200

int main(void) {
    // Initialize pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus 1
    int i2c_handle = pigpio_i2c_open(1, VL53L1X_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }

    // Check if sensor is present
    uint8_t model_id;
    if (pigpio_i2c_read_reg_u8(i2c_handle, VL53L1X_MODEL_ID_REG, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID register\n");
        return 1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Invalid model ID: %02X\n", model_id);
        return 1;
    }

    // Perform software reset
    if (pigpio_i2c_write_reg_u8(i2c_handle, VL53L1X_SYSTEM_MODE_START_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to write to SYSTEM_MODE_START register\n");
        return 1;
    }
    usleep(2000);

    // Start continuous back-to-back ranging
    if (pigpio_i2c_write_reg_u8(i2c_handle, VL53L1X_SYSRANGE_START_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to write to SYSRANGE_START register\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(DISTANCE_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Poll for data-ready
        uint8_t interrupt_status;
        if (pigpio_i2c_read_reg_u8(i2c_handle, VL53L1X_RESULT_INTERRUPT_STATUS_REG, &interrupt_status) < 0) {
            fprintf(stderr, "Failed to read RESULT_INTERRUPT_STATUS register\n");
            return 1;
        }
        if (interrupt_status & 0x01) {
            // Read distance
            uint16_t distance;
            if (pigpio_i2c_read_reg_u16(i2c_handle, VL53L1X_RESULT_RANGE_STATUS_REG, &distance) < 0) {
                fprintf(stderr, "Failed to read RESULT_RANGE_STATUS register\n");
                return 1;
            }

            // Clear interrupt
            if (pigpio_i2c_write_reg_u8(i2c_handle, VL53L1X_SYSTEM_INTERRUPT_CLEAR_REG, 0x01) < 0) {
                fprintf(stderr, "Failed to write to SYSTEM_INTERRUPT_CLEAR register\n");
                return 1;
            }

            // Print distance to log file
            time_t timestamp = time(NULL);
            fprintf(log_file, "%ld,%u\n", timestamp, distance);

            // Print parking guidance message
            if (distance < STOP_THRESHOLD) {
                printf("STOP\n");
            } else if (distance < APPROACH_THRESHOLD) {
                printf("APPROACH\n");
            } else if (distance < SLOW_THRESHOLD) {
                printf("SLOW\n");
            } else {
                printf("CLEAR\n");
            }
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    fclose(log_file);
    pigpio_i2c_close(i2c_handle);
    pigpio_stop();

    return 0;
}

void sigint_handler(int signum) {
    // Clean up
    fclose(log_file);
    pigpio_i2c_close(i2c_handle);
    pigpio_stop();

    exit(0);
}

void sigterm_handler(int signum) {
    // Clean up
    fclose(log_file);
    pigpio_i2c_close(i2c_handle);
    pigpio_stop();

    exit(0);
}

