#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x5A
#define MEASURE_CMD 0x08
#define DATA_READY_CMD 0x02
#define DATA_READ_CMD 0x03
#define DATA_SIZE 2

#define LOG_FILE "distance_log.csv"

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    int fd;
    uint8_t data[DATA_SIZE];
    uint16_t distance;
    char timestamp[20];
    FILE *log_file;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus
    fd = i2cOpen(I2C_BUS, 0, 0, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        return 1;
    }

    // Set up signal handler for SIGINT/SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (running) {
        // Write measurement command to sensor
        if (i2cWriteByte(fd, MLX75030_ADDR, MEASURE_CMD) < 0) {
            fprintf(stderr, "Failed to write measurement command to sensor\n");
            break;
        }

        // Wait for data ready
        if (i2cReadByte(fd, MLX75030_ADDR, DATA_READY_CMD) < 0) {
            fprintf(stderr, "Failed to read data ready command from sensor\n");
            break;
        }

        // Read distance data
        if (i2cRead(fd, MLX75030_ADDR, DATA_READ_CMD, data, DATA_SIZE) < 0) {
            fprintf(stderr, "Failed to read distance data from sensor\n");
            break;
        }

        // Convert distance data to centimeters
        distance = (data[0] << 8) | data[1];

        // Get current timestamp
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Write distance data to log file
        fprintf(log_file, "%s,%u\n", timestamp, distance);

        // Wait for next measurement
        usleep(100000);
    }

    // Clean up
    fclose(log_file);
    i2cClose(fd);
    gpioTerminate();

    return 0;
}

