#include <stdbool.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define DEBOUNCE_TIME 50

int main(void) {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_PIN);
        return 1;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_PIN);
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("proximity_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (true) {
        // Read the sensor values
        int sensor1_value = gpioRead(SENSOR1_PIN);
        int sensor2_value = gpioRead(SENSOR2_PIN);

        // Check for errors
        if (sensor1_value < 0 || sensor2_value < 0) {
            fprintf(stderr, "Failed to read sensor values\n");
            return 1;
        }

        // Check for state transitions
        if (sensor1_value == 0 && sensor2_value == 0) {
            // Both sensors detected an obstacle
            fprintf(log_file, "%s,1,DETECTED\n", get_timestamp());
            fprintf(log_file, "%s,2,DETECTED\n", get_timestamp());
        } else if (sensor1_value == 1 && sensor2_value == 1) {
            // Both sensors detected a clear path
            fprintf(log_file, "%s,1,CLEARED\n", get_timestamp());
            fprintf(log_file, "%s,2,CLEARED\n", get_timestamp());
        } else {
            // One sensor detected an obstacle, the other detected a clear path
            if (sensor1_value == 0) {
                fprintf(log_file, "%s,1,DETECTED\n", get_timestamp());
            } else {
                fprintf(log_file, "%s,1,CLEARED\n", get_timestamp());
            }
            if (sensor2_value == 0) {
                fprintf(log_file, "%s,2,DETECTED\n", get_timestamp());
            } else {
                fprintf(log_file, "%s,2,CLEARED\n", get_timestamp());
            }
        }

        // Debounce the sensors
        usleep(DEBOUNCE_TIME * 1000);
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();

    return 0;
}

char *get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    timestamp = asctime(timeinfo);

    return timestamp;
}

