#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x49
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09

#define TIMEOUT_MS 50
#define SAMPLING_MS 500

static int i2c_fd;
static FILE *csv_file;

static void cleanup(void) {
    close(i2c_fd);
    fclose(csv_file);
}

static void sigint_handler(int signum) {
    cleanup();
    exit(0);
}

static void register_read(uint8_t reg, uint8_t *data) {
    uint8_t buf[2];
    buf[0] = reg;
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return;
    }
    if (read(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return;
    }
    *data = buf[0];
}

static void register_write(uint8_t reg, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return;
    }
}

static void measure_distance(void) {
    uint8_t status;
    uint16_t distance;
    register_write(MEAS_TRIGGER, 0x01);
    while (1) {
        register_read(MEAS_STATUS, &status);
        if (status & 0x01) {
            break;
        }
        usleep(TIMEOUT_MS * 1000);
    }
    register_read(DIST_HIGH, &distance);
    register_read(DIST_LOW, &distance);
    distance = (distance << 8) | distance;
    fprintf(csv_file, "%s,%d\n", get_iso8601_timestamp(), distance);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        return 1;
    }
    csv_file = fopen("distance_log.csv", "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return 1;
    }

    while (1) {
        measure_distance();
        usleep(SAMPLING_MS * 1000);
    }

    cleanup();
    return 0;
}

