#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define REG_SOFT_RESET 0x7FFF
#define REG_START_RANGING 0x0009
#define REG_INTERRUPT_STATUS 0x0046
#define REG_DISTANCE_HIGH 0x0096
#define REG_DISTANCE_LOW 0x0097

#define INTERRUPT_BIT 0
#define DISTANCE_MAX 65535

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Soft reset
    uint8_t data = 0x00;
    if (i2cWriteByte(i2c_handle, REG_SOFT_RESET, data) < 0) {
        fprintf(stderr, "Failed to write to register 0x%04X\n", REG_SOFT_RESET);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    usleep(10000); // 10 ms

    // Start ranging
    data = 0x00;
    if (i2cWriteByte(i2c_handle, REG_START_RANGING, data) < 0) {
        fprintf(stderr, "Failed to write to register 0x%04X\n", REG_START_RANGING);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (true) {
        // Poll interrupt status
        uint8_t status = 0;
        if (i2cReadByte(i2c_handle, REG_INTERRUPT_STATUS, &status) < 0) {
            fprintf(stderr, "Failed to read from register 0x%04X\n", REG_INTERRUPT_STATUS);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Check interrupt bit
        if (status & (1 << INTERRUPT_BIT)) {
            // Read distance
            uint16_t distance = 0;
            if (i2cReadWord(i2c_handle, REG_DISTANCE_HIGH, &distance) < 0) {
                fprintf(stderr, "Failed to read from register 0x%04X\n", REG_DISTANCE_HIGH);
                i2cClose(i2c_handle);
                gpioTerminate();
                return 1;
            }

            // Print distance
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("Timestamp: %04d-%02d-%02d %02d:%02d:%02d.%06ld, Distance: %d mm\n",
                   ts.tm_year + 1900, ts.tm_mon + 1, ts.tm_mday,
                   ts.tm_hour, ts.tm_min, ts.tm_sec, ts.tm_nsec / 1000,
                   distance);
        }

        // Wait for next cycle
        usleep(500000); // 500 ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

void sigint_handler(int signum) {
    // Ctrl+C pressed
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int signum) {
    // SIGTERM received
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

