#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define VL53L1X_I2C_ADDR 0x29
#define VL53L1X_SOFT_RESET 0x0001
#define VL53L1X_I2C_SLAVE_DEVICE_ADDRESS 0x0001
#define VL53L1X_SYSTEM_MODE_START 0x0007
#define VL53L1X_RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM 0x0096

#define BUZZER_GPIO 22

int main(void)
{
    int i2c_fd;
    int buzzer_fd;
    uint8_t data[2];
    uint16_t distance;

    // Initialize I2C bus
    if ((i2c_fd = pigpio_i2c_open(1, VL53L1X_I2C_ADDR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Initialize buzzer
    if ((buzzer_fd = pigpio_gpio_open(BUZZER_GPIO)) < 0) {
        fprintf(stderr, "Failed to open buzzer: %s\n", strerror(errno));
        return 1;
    }

    // Configure sensor for continuous ranging mode
    data[0] = VL53L1X_SOFT_RESET;
    data[1] = 0x00;
    if (pigpio_i2c_write(i2c_fd, data, 2) < 0) {
        fprintf(stderr, "Failed to reset sensor: %s\n", strerror(errno));
        return 1;
    }

    data[0] = VL53L1X_I2C_SLAVE_DEVICE_ADDRESS;
    data[1] = 0x00;
    if (pigpio_i2c_write(i2c_fd, data, 2) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        return 1;
    }

    data[0] = VL53L1X_SYSTEM_MODE_START;
    data[1] = 0x00;
    if (pigpio_i2c_write(i2c_fd, data, 2) < 0) {
        fprintf(stderr, "Failed to start ranging mode: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    while (1) {
        // Read distance measurement
        data[0] = VL53L1X_RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM;
        if (pigpio_i2c_read(i2c_fd, data, 2) < 0) {
            fprintf(stderr, "Failed to read distance measurement: %s\n", strerror(errno));
            continue;
        }

        distance = (data[0] << 8) | data[1];

        // Check if distance is below 100 mm
        if (distance < 100) {
            // Activate buzzer
            pigpio_gpio_write(buzzer_fd, 1);
        } else {
            // Deactivate buzzer
            pigpio_gpio_write(buzzer_fd, 0);
        }

        // Wait 500 ms before next measurement
        usleep(500000);
    }

    // Clean up resources
    pigpio_i2c_close(i2c_fd);
    pigpio_gpio_close(buzzer_fd);

    return 0;
}

void sigint_handler(int signum)
{
    // Clean up resources
    pigpio_i2c_close(i2c_fd);
    pigpio_gpio_close(buzzer_fd);

    // Exit program
    exit(0);
}

