#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17
#define SPEED_OF_SOUND 343
#define TIMEOUT_MS 50
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define SERVO_MIN_ANGLE -90
#define SERVO_MAX_ANGLE 90
#define LOG_INTERVAL_MS 200

static volatile bool running = true;

void sigint_handler(int signum) {
    running = false;
}

void sigterm_handler(int signum) {
    running = false;
}

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", TRIG_PIN);
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", ECHO_PIN);
        return 1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", SERVO_PIN);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open log file
    FILE *log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Send trigger pulse
        gpioWrite(TRIG_PIN, PI_HIGH);
        usleep(10);
        gpioWrite(TRIG_PIN, PI_LOW);

        // Measure echo pulse width
        uint32_t start_time = gpioTick();
        while (gpioRead(ECHO_PIN) == PI_LOW) {
            if (gpioTick() - start_time > TIMEOUT_MS) {
                fprintf(stderr, "Echo pulse timed out\n");
                continue;
            }
        }
        uint32_t end_time = gpioTick();
        uint32_t pulse_width = end_time - start_time;

        // Calculate distance
        float distance = (float)pulse_width / SPEED_OF_SOUND * 100;

        // Map distance to servo angle
        int angle = (int)((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) + SERVO_MIN_ANGLE);

        // Set servo angle
        gpioWrite(SERVO_PIN, angle);

        // Log data
        fprintf(log_file, "%ld, %f, %d\n", time(NULL), distance, angle);

        // Sleep for log interval
        usleep(LOG_INTERVAL_MS * 1000);
    }

    // Clean up
    fclose(log_file);
    gpioWrite(SERVO_PIN, 0);
    gpioTerminate();

    return 0;
}

