#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <pigpio.h>
#include <pigpiod_if2.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define MODEL_ID_REG 0x010F
#define SOFT_RESET_REG 0x0000
#define TIMING_BUDGET_REG 0x0080
#define DATA_READY_REG 0x0089
#define DISTANCE_REG_LOW 0x0096
#define DISTANCE_REG_HIGH 0x0097
#define BUZZER_GPIO 23

#define MSG_QUEUE_NAME "distance_queue"
#define MSG_QUEUE_SIZE 10

int main(void) {
    // Initialize pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return 1;
    }

    // Check model ID
    uint8_t model_id;
    if (read_i2c_reg(i2c_fd, MODEL_ID_REG, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID\n");
        return 1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Invalid model ID: %02X\n", model_id);
        return 1;
    }

    // Perform software reset
    uint8_t reset_val = 0x00;
    if (write_i2c_reg(i2c_fd, SOFT_RESET_REG, reset_val) < 0) {
        fprintf(stderr, "Failed to perform software reset\n");
        return 1;
    }
    reset_val = 0x01;
    if (write_i2c_reg(i2c_fd, SOFT_RESET_REG, reset_val) < 0) {
        fprintf(stderr, "Failed to perform software reset\n");
        return 1;
    }

    // Configure timing budget
    uint8_t timing_budget = 0x32;
    if (write_i2c_reg(i2c_fd, TIMING_BUDGET_REG, timing_budget) < 0) {
        fprintf(stderr, "Failed to configure timing budget\n");
        return 1;
    }

    // Open message queue
    int msg_queue_fd = msgget(MSG_QUEUE_NAME, MSG_QUEUE_SIZE);
    if (msg_queue_fd < 0) {
        fprintf(stderr, "Failed to open message queue\n");
        return 1;
    }

    // Open GPIO for buzzer
    int buzzer_fd = gpio_open(BUZZER_GPIO, GPIO_OUTPUT);
    if (buzzer_fd < 0) {
        fprintf(stderr, "Failed to open GPIO for buzzer\n");
        return 1;
    }

    // Start ranging
    uint8_t start_val = 0x01;
    if (write_i2c_reg(i2c_fd, DATA_READY_REG, start_val) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        return 1;
    }

    // Poll data-ready bit every 50 ms
    while (1) {
        uint8_t data_ready;
        if (read_i2c_reg(i2c_fd, DATA_READY_REG, &data_ready) < 0) {
            fprintf(stderr, "Failed to read data-ready bit\n");
            return 1;
        }
        if (data_ready) {
            uint16_t distance;
            if (read_i2c_reg(i2c_fd, DISTANCE_REG_LOW, &distance) < 0) {
                fprintf(stderr, "Failed to read distance\n");
                return 1;
            }
            distance |= (uint16_t)read_i2c_reg(i2c_fd, DISTANCE_REG_HIGH) << 8;
            if (distance < 100) {
                // Activate buzzer
                gpio_write(buzzer_fd, 1);
            } else {
                // Deactivate buzzer
                gpio_write(buzzer_fd, 0);
            }
            // Log distance reading
            struct msgbuf msg;
            msg.mtype = 1;
            msg.mtext = (void *)&distance;
            msgsnd(msg_queue_fd, &msg, sizeof(msg), 0);
        }
        usleep(50000);
    }

    // Clean up resources
    close(i2c_fd);
    close(msg_queue_fd);
    gpio_close(buzzer_fd);
    pigpio_stop();

    return 0;
}

int read_i2c_reg(int fd, uint8_t reg, uint8_t *val) {
    uint8_t buf[2];
    buf[0] = reg;
    if (write(fd, buf, 1) < 0) {
        return -1;
    }
    if (read(fd, buf, 1) < 0) {
        return -1;
    }
    *val = buf[0];
    return 0;
}

int write_i2c_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = val;
    if (write(fd, buf, 2) < 0) {
        return -1;
    }
    return 0;
}

