#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22
#define SPEED_OF_SOUND 34300
#define TIMEOUT_US 10000
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400

static int gpio_handle;
static int trigger_pin;
static int echo_pin;
static int buzzer_pin;
static int distance;
static int buzzer_state;

static void handle_interrupt(int pin, int level, uint32_t tick) {
    if (pin == ECHO_PIN) {
        uint32_t pulse_width = gpioGetPulseWidth(pin, tick);
        distance = (pulse_width * SPEED_OF_SOUND) / 2;
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Invalid reading: %d cm\n", distance);
        } else {
            printf("Distance: %d cm\n", distance);
            if (distance < 30) {
                buzzer_state = 1;
            } else {
                buzzer_state = 0;
            }
        }
    }
}

static void handle_sigint(int signal) {
    gpioSetAlertFuncEx(gpio_handle, trigger_pin, 0, 0, 0);
    gpioSetAlertFuncEx(gpio_handle, echo_pin, 0, 0, 0);
    gpioSetAlertFuncEx(gpio_handle, buzzer_pin, 0, 0, 0);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 1) {
        printf("Usage: %s\n", argv[0]);
        return 1;
    }

    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    gpio_handle = gpioGetHandle();
    if (gpio_handle < 0) {
        printf("Failed to get GPIO handle\n");
        return 1;
    }

    trigger_pin = gpioGetPin(gpio_handle, TRIG_PIN);
    if (trigger_pin < 0) {
        printf("Failed to get trigger pin\n");
        return 1;
    }

    echo_pin = gpioGetPin(gpio_handle, ECHO_PIN);
    if (echo_pin < 0) {
        printf("Failed to get echo pin\n");
        return 1;
    }

    buzzer_pin = gpioGetPin(gpio_handle, BUZZER_PIN);
    if (buzzer_pin < 0) {
        printf("Failed to get buzzer pin\n");
        return 1;
    }

    if (gpioSetMode(gpio_handle, trigger_pin, PI_OUTPUT) < 0) {
        printf("Failed to set trigger pin mode\n");
        return 1;
    }

    if (gpioSetMode(gpio_handle, echo_pin, PI_INPUT) < 0) {
        printf("Failed to set echo pin mode\n");
        return 1;
    }

    if (gpioSetMode(gpio_handle, buzzer_pin, PI_OUTPUT) < 0) {
        printf("Failed to set buzzer pin mode\n");
        return 1;
    }

    if (gpioSetAlertFuncEx(gpio_handle, trigger_pin, 0, 0, 0) < 0) {
        printf("Failed to set trigger pin alert function\n");
        return 1;
    }

    if (gpioSetAlertFuncEx(gpio_handle, echo_pin, 0, 0, 0) < 0) {
        printf("Failed to set echo pin alert function\n");
        return 1;
    }

    if (gpioSetAlertFuncEx(gpio_handle, buzzer_pin, 0, 0, 0) < 0) {
        printf("Failed to set buzzer pin alert function\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        gpioWrite(gpio_handle, trigger_pin, 1);
        usleep(10);
        gpioWrite(gpio_handle, trigger_pin, 0);
        usleep(TIMEOUT_US);

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Sensor absent or invalid reading\n");
        } else {
            printf("Distance: %d cm\n", distance);
            if (distance < 30) {
                buzzer_state = 1;
            } else {
                buzzer_state = 0;
            }
        }

        gpioWrite(gpio_handle, buzzer_pin, buzzer_state);
        usleep(100000);
    }

    return 0;
}

