#define MQTT_CLIENT_ID "raspberrypi"
#define MQTT_TOPIC "gate"

#define MQTT_CMD_FORCE_OPEN "force_open"
#define MQTT_CMD_FORCE_CLOSE "force_close"
#define MQTT_CMD_STATUS_REQUEST "status_request"

#define MQTT_MSG_OPEN "open"
#define MQTT_MSG_CLOSE "close"
#define MQTT_MSG_ERROR "error"

#define MQTT_QOS 1
#define MQTT_RETAIN 0

#define MQTT_TIMEOUT 1000

#define LOG_FILE "gate_log.txt"

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void mqtt_callback(void *context, char *topic, int topic_len,
                          MQTTMessage *message) {
    if (strncmp(topic, MQTT_TOPIC, topic_len) == 0) {
        if (strncmp(message->payload, MQTT_CMD_FORCE_OPEN, message->payloadlen) == 0) {
            // Force open the gate
            sg90_set_angle(GPIO_SERVO, 0);
        } else if (strncmp(message->payload, MQTT_CMD_FORCE_CLOSE, message->payloadlen) == 0) {
            // Force close the gate
            sg90_set_angle(GPIO_SERVO, 180);
        } else if (strncmp(message->payload, MQTT_CMD_STATUS_REQUEST, message->payloadlen) == 0) {
            // Request the current status of the gate
            MQTTMessage response;
            response.payload = (char *) malloc(10);
            response.payloadlen = 10;
            if (sg90_get_angle(GPIO_SERVO) == 0) {
                strcpy(response.payload, MQTT_MSG_OPEN);
            } else {
                strcpy(response.payload, MQTT_MSG_CLOSE);
            }
            mqtt_publish(context, MQTT_TOPIC, response.payload, response.payloadlen, MQTT_QOS, MQTT_RETAIN);
            free(response.payload);
        }
    }
}

int main(int argc, char **argv) {
    // Set up signal handling
    signal(SIGINT, sigint_handler);

    // Set up I2C
    if (pigpio_start(NULL, 0) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up VL53L1X
    VL53L1X_Dev_t dev;
    dev.i2c_bus = I2C_BUS;
    dev.i2c_addr = I2C_ADDR;
    if (vl53l1x_init(&dev) < 0) {
        fprintf(stderr, "Failed to initialize VL53L1X\n");
        return 1;
    }

    // Set up SG90
    sg90_init(GPIO_SERVO);

    // Set up MQTT
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    conn_opts.username = MQTT_CLIENT_ID;
    conn_opts.password = NULL;
    if (MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTClient_PERSISTENCE_NONE, NULL) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client\n");
        return 1;
    }
    if (MQTTClient_setCallbacks(client, NULL, NULL, mqtt_callback, NULL) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to set MQTT callbacks\n");
        return 1;
    }
    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        return 1;
    }

    // Set up logging
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Read distance from VL53L1X
        uint16_t distance;
        if (vl53l1x_read_distance(&dev, &distance) < 0) {
            fprintf(stderr, "Failed to read distance from VL53L1X\n");
            return 1;
        }

        // Check if object is within threshold
        if (distance < GATE_THRESHOLD) {
            // Object detected, open the gate
            sg90_set_angle(GPIO_SERVO, 0);

            // Log event
            time_t now = time(NULL);
            char *timestamp = ctime(&now);
            fprintf(log_file, "%s: Object detected, gate opened\n", timestamp);
        } else {
            // Object not detected, close the gate
            sg90_set_angle(GPIO_SERVO, 180);

            // Log event
            time_t now = time(NULL);
            char *timestamp = ctime(&now);
            fprintf(log_file, "%s: Object not detected, gate closed\n", timestamp);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    MQTTClient_disconnect(client, 10000);
    MQTTClient_destroy(&client);
    fclose(log_file);
    sg90_cleanup(GPIO_SERVO);
    vl53l1x_cleanup(&dev);
    pigpio_stop(NULL);

    return 0;
}

