#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SPEED_OF_SOUND 0.0343
#define MIN_PULSE_WIDTH 100
#define MAX_PULSE_WIDTH 30000
#define TIMEOUT_MS 60
#define MEASUREMENT_INTERVAL_MS 200

static bool gpio_initialized = false;
static bool gpio_terminated = false;
static int gpio_fd = -1;
static int gpio_handle = -1;

static void handle_sigint(int signal) {
    if (gpio_initialized && !gpio_terminated) {
        gpioTerminate();
        gpio_terminated = true;
    }
    exit(0);
}

static void handle_sigterm(int signal) {
    if (gpio_initialized && !gpio_terminated) {
        gpioTerminate();
        gpio_terminated = true;
    }
    exit(0);
}

static void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }
    gpio_initialized = true;

    gpio_fd = gpioOpen(TRIG_PIN, OUTPUT);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO %d for output\n", TRIG_PIN);
        exit(1);
    }

    gpio_handle = gpioSetAlertFunc(ECHO_PIN, GPIO_ALERT_BOTH, echo_callback);
    if (gpio_handle < 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", ECHO_PIN);
        exit(1);
    }
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == GPIO_LEVEL_RISING) {
        rising_tick = tick;
    } else if (level == GPIO_LEVEL_FALLING) {
        falling_tick = tick;
        if (falling_tick - rising_tick < MIN_PULSE_WIDTH || falling_tick - rising_tick > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Invalid pulse width: %d\n", falling_tick - rising_tick);
            return;
        }
        double pulse_width = falling_tick - rising_tick;
        double distance = pulse_width * SPEED_OF_SOUND / 2;
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
        fprintf(stdout, "%s: Distance = %.2f cm\n", timestamp, distance);
        fprintf(log_file, "%s: Distance = %.2f cm\n", timestamp, distance);
        fflush(log_file);
    }
}

int main(int argc, char **argv) {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    init_gpio();

    FILE *log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(1);
    }

    while (true) {
        gpioWrite(gpio_fd, 1);
        usleep(10);
        gpioWrite(gpio_fd, 0);
        usleep(TIMEOUT_MS * 1000);
        if (falling_tick == 0) {
            fprintf(stderr, "Timeout\n");
            continue;
        }
        double pulse_width = falling_tick - rising_tick;
        double distance = pulse_width * SPEED_OF_SOUND / 2;
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
        fprintf(stdout, "%s: Distance = %.2f cm\n", timestamp, distance);
        fprintf(log_file, "%s: Distance = %.2f cm\n", timestamp, distance);
        fflush(log_file);
        usleep(MEASUREMENT_INTERVAL_MS * 1000);
    }

    gpioTerminate();
    fclose(log_file);
    return 0;
}

