#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <vl53l1x.h>
#include <servo.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24
#define SERVO_PIN 18
#define HYSTERESIS 5
#define MIN_DISTANCE 50
#define MAX_DISTANCE 60

#define LOG_FILE "parking_log.txt"

static volatile bool running = true;

void sigint_handler(int signum) {
    running = false;
}

void sigterm_handler(int signum) {
    running = false;
}

int main(int argc, char **argv) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Set up I2C bus
    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Set up VL53L1X sensor
    VL53L1X_Dev_t dev;
    if (VL53L1X_init(&dev, I2C_BUS, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to initialize VL53L1X sensor\n");
        return 1;
    }

    // Verify sensor model ID
    uint8_t model_id;
    if (VL53L1X_get_model_id(&dev, &model_id) < 0) {
        fprintf(stderr, "Failed to get VL53L1X model ID\n");
        return 1;
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Invalid VL53L1X model ID: %d\n", model_id);
        return 1;
    }

    // Set up servo motor
    Servo_t servo;
    if (servo_init(&servo, SERVO_PIN, 0, 180) < 0) {
        fprintf(stderr, "Failed to initialize servo motor\n");
        return 1;
    }

    // Set up shutdown pin
    if (gpioSetMode(SHUTDOWN_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set shutdown pin mode\n");
        return 1;
    }

    // Set up interrupt pin
    if (gpioSetMode(INTERRUPT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set interrupt pin mode\n");
        return 1;
    }

    // Set up logging
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Read distance from sensor
        uint16_t distance;
        if (VL53L1X_get_distance(&dev, &distance) < 0) {
            fprintf(stderr, "Failed to read distance from VL53L1X sensor\n");
            return 1;
        }

        // Check for shutdown
        if (gpioRead(SHUTDOWN_PIN) == PI_HIGH) {
            fprintf(stderr, "Shutdown signal received\n");
            return 1;
        }

        // Check for interrupt
        if (gpioRead(INTERRUPT_PIN) == PI_HIGH) {
            fprintf(stderr, "Interrupt signal received\n");
            return 1;
        }

        // Check distance
        if (distance < MIN_DISTANCE) {
            // Open gate
            servo_set_angle(&servo, 0);
            fprintf(log_file, "%ld, %d, open\n", time(NULL), distance);
        } else if (distance > MAX_DISTANCE) {
            // Close gate
            servo_set_angle(&servo, 180);
            fprintf(log_file, "%ld, %d, close\n", time(NULL), distance);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    servo_close(&servo);
    VL53L1X_close(&dev);
    i2cClose(I2C_BUS);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

