    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Failed to initialize VL53L1X\n");
        return 1;
    }

    // Configure timing budget
    if (vl53l1x_set_timing_budget(i2c_handle, TIMING_BUDGET) < 0) {
        fprintf(stderr, "Failed to set timing budget\n");
        return 1;
    }

    // Start ranging
    if (vl53l1x_start_ranging(i2c_handle) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        return 1;
    }

