        usleep(500000);

        // Read distance
        uint16_t distance = 0;
        if (vl53l1x_read_distance(i2c_handle, &distance) < 0) {
            fprintf(stderr, "Failed to read distance\n");
            return 1;
        }

        // Check if object is within threshold
        if (distance <= DISTANCE_THRESHOLD) {
            // Open gate
            gpioWrite(GPIO_OPEN, 1);
            gpioWrite(GPIO_CLOSE, 0);

            // Log event
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
            fprintf(log_file, "%s: Open\n", timestamp);
        } else {
            // Close gate
            gpioWrite(GPIO_OPEN, 0);
            gpioWrite(GPIO_CLOSE, 1);

            // Log event
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
            fprintf(log_file, "%s: Close\n", timestamp);
        }
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();
    i2cClose(i2c_handle);

    return 0;
}

