#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod/libgpiod.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x5A
#define ELE_COUNT 12
#define ELE_PATTERNS 4
#define ELE_PATTERN_LEN 4
#define ELE_PATTERN_MASK 0x0F
#define ELE_PATTERN_SHIFT 4
#define ELE_PATTERN_OFFSET 0x00
#define ELE_PATTERN_ON 0x01
#define ELE_PATTERN_OFF 0x00

#define GPIO_PIN_COUNT 4
#define GPIO_PIN_MASK 0x0F
#define GPIO_PIN_SHIFT 4
#define GPIO_PIN_OFFSET 0x00
#define GPIO_PIN_ON 0x01
#define GPIO_PIN_OFF 0x00

#define LOG_FILE "/var/log/proximity.log"

static int i2c_fd;
static int gpio_fd;
static int gpio_pin[GPIO_PIN_COUNT];
static int ele_pattern[ELE_COUNT][ELE_PATTERNS];

static void init_gpio(void) {
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    for (int i = 0; i < GPIO_PIN_COUNT; i++) {
        gpio_pin[i] = gpiod_get_line(gpio_fd, i);
        if (gpio_pin[i] < 0) {
            perror("Failed to get GPIO line");
            exit(1);
        }
    }
}

static void init_i2c(void) {
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }
}

static void init_ele_patterns(void) {
    for (int i = 0; i < ELE_COUNT; i++) {
        for (int j = 0; j < ELE_PATTERNS; j++) {
            ele_pattern[i][j] = (i * ELE_PATTERN_LEN) + j;
        }
    }
}

static void set_gpio_pattern(int pattern) {
    for (int i = 0; i < GPIO_PIN_COUNT; i++) {
        gpiod_set_value(gpio_pin[i], (pattern & (1 << i)) ? GPIO_PIN_ON : GPIO_PIN_OFF);
    }
}

static void set_ele_pattern(int ele, int pattern) {
    uint8_t reg_addr = 0x00;
    uint8_t reg_val = 0x00;

    reg_addr = (ele * ELE_PATTERN_LEN) + ELE_PATTERN_OFFSET;
    reg_val = (pattern & ELE_PATTERN_MASK) << ELE_PATTERN_SHIFT;

    if (i2c_smbus_write_byte_data(i2c_fd, reg_addr, reg_val) < 0) {
        perror("Failed to write I2C register");
        exit(1);
    }
}

static void read_touch_status(void) {
    uint8_t reg_addr = 0x00;
    uint8_t reg_val = 0x00;
    int ele_active = -1;

    reg_addr = 0x00;
    if (i2c_smbus_read_byte_data(i2c_fd, reg_addr, &reg_val) < 0) {
        perror("Failed to read I2C register");
        exit(1);
    }

    for (int i = 0; i < ELE_COUNT; i++) {
        if (reg_val & (1 << i)) {
            ele_active = i;
            break;
        }
    }

    if (ele_active >= 0) {
        set_gpio_pattern(ele_pattern[ele_active]);
    } else {
        set_gpio_pattern(0x00);
    }
}

static void handle_signal(int sig) {
    switch (sig) {
        case SIGINT:
        case SIGTERM:
            close(i2c_fd);
            close(gpio_fd);
            exit(0);
            break;
        default:
            break;
    }
}

int main(void) {
    init_gpio();
    init_i2c();
    init_ele_patterns();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        read_touch_status();
        usleep(50000);
    }

    return 0;
}

