#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <mpr121.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define ELECTRODE 0
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x05
#define LED_GPIO 27

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Initialize pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Initialize MPR121 sensor
    if (mpr121_init(I2C_BUS, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to initialize MPR121 sensor\n");
        return 1;
    }

    // Set touch and release thresholds
    if (mpr121_set_touch_threshold(ELECTRODE, TOUCH_THRESHOLD) < 0) {
        fprintf(stderr, "Failed to set touch threshold\n");
        return 1;
    }
    if (mpr121_set_release_threshold(ELECTRODE, RELEASE_THRESHOLD) < 0) {
        fprintf(stderr, "Failed to set release threshold\n");
        return 1;
    }

    // Configure MPR121 registers
    if (mpr121_set_ffi(ELECTRODE, 0) < 0) {
        fprintf(stderr, "Failed to set FFI\n");
        return 1;
    }
    if (mpr121_set_sfi(ELECTRODE, 0) < 0) {
        fprintf(stderr, "Failed to set SFI\n");
        return 1;
    }
    if (mpr121_set_esi(ELECTRODE, 0) < 0) {
        fprintf(stderr, "Failed to set ESI\n");
        return 1;
    }
    if (mpr121_set_debounce(ELECTRODE, 0) < 0) {
        fprintf(stderr, "Failed to set debounce\n");
        return 1;
    }
    if (mpr121_set_afe_config(ELECTRODE, 0) < 0) {
        fprintf(stderr, "Failed to set AFE config\n");
        return 1;
    }
    if (mpr121_set_baseline_filtering(ELECTRODE, 0) < 0) {
        fprintf(stderr, "Failed to set baseline filtering\n");
        return 1;
    }

    // Set up signal handler for SIGINT/SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (running) {
        // Read MPR121 sensor data
        uint16_t data = mpr121_read_data(ELECTRODE);
        if (data < 0) {
            fprintf(stderr, "Failed to read MPR121 sensor data\n");
            return 1;
        }

        // Check for proximity
        if (data & (1 << ELECTRODE)) {
            // Turn on LED
            pigpio_write(LED_GPIO, 1);

            // Log event
            time_t now = time(NULL);
            char *timestamp = ctime(&now);
            fprintf(stderr, "Proximity detected at %s\n", timestamp);

            // Wait for 1 second
            sleep(1);

            // Turn off LED
            pigpio_write(LED_GPIO, 0);
        }
    }

    // Clean up
    mpr121_close();
    pigpio_stop();

    return 0;
}

