#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define SPEED_OF_SOUND 343.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define TIMEOUT_MS 30

volatile sig_atomic_t sigint_flag = 0;

void sigint_handler(int signum) {
    sigint_flag = 1;
}

int main(void) {
    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open GPIO lines
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    struct gpiod_line *trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Error getting trigger line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    struct gpiod_line *echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Error getting echo line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up trigger line as output
    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        fprintf(stderr, "Error setting trigger line as output\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up echo line as input
    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        fprintf(stderr, "Error setting echo line as input\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up trigger sequence
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Error setting trigger line low\n");
        gpiod_chip_close(chip);
        return 1;
    }

    usleep(5000); // 5 microseconds

    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        fprintf(stderr, "Error setting trigger line high\n");
        gpiod_chip_close(chip);
        return 1;
    }

    usleep(10000); // 10 microseconds

    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        fprintf(stderr, "Error setting trigger line low\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Wait for echo rising edge
    struct gpiod_line_event event;
    if (gpiod_line_event_wait(echo_line, &event, TIMEOUT_MS) < 0) {
        fprintf(stderr, "Error waiting for echo rising edge\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Measure echo pulse width
    uint64_t pulse_us = event.timestamp_us;
    if (gpiod_line_event_wait(echo_line, &event, TIMEOUT_MS) < 0) {
        fprintf(stderr, "Error waiting for echo falling edge\n");
        gpiod_chip_close(chip);
        return 1;
    }

    pulse_us = event.timestamp_us - pulse_us;

    // Compute distance
    double distance = (pulse_us * 0.0343) / 2.0;

    // Check for valid distance
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Invalid distance: %f\n", distance);
        gpiod_chip_close(chip);
        return 1;
    }

    // Log distance
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);
    FILE *log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        gpiod_chip_close(chip);
        return 1;
    }

    fprintf(log_file, "%s, %f\n", timestamp, distance);
    fclose(log_file);

    // Clean up
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return 0;
}

