#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define TRIG_PULSE_US 10
#define ECHO_MIN_US 58
#define ECHO_MAX_US 25000

static FILE *log_file;

static void sigint_handler(int signum) {
    gpioSetISRFuncEx(ECHO_PIN, 0, 0, 0);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick;
    static uint32_t end_tick;

    if (level == 1) {
        start_tick = tick;
    } else {
        end_tick = tick;
        uint32_t pulse_us = (end_tick - start_tick) * 1000 / 1000;
        if (pulse_us > ECHO_MIN_US && pulse_us < ECHO_MAX_US) {
            double distance = pulse_us * 343 / 2e6;
            char buf[100];
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tm);
            fprintf(log_file, "%s, %f\n", buf, distance);
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if ((log_file = fopen("distance_log.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback) < 0) {
        fprintf(stderr, "Failed to set ISR callback\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        gpioWrite(TRIG_PIN, 1);
        usleep(TRIG_PULSE_US);
        gpioWrite(TRIG_PIN, 0);
        usleep(1000000 - TRIG_PULSE_US);
    }

    return 0;
}

