#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <i2c.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define XSHUT_PIN 27

#define REG_CONT_MODE 0x0018
#define REG_TIMEOUT 0x0019
#define REG_START_RANGING 0x0020
#define REG_DISTANCE 0x0014
#define REG_STATUS 0x0016

#define DISTANCE_MM 0x00
#define STATUS_OK 0x01

int main(void) {
    // Initialise pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        syslog(LOG_ERR, "Failed to initialise pigpio");
        return 1;
    }

    // Set GPIO27 as an output and set it high to enable the sensor
    if (gpio_mode_output(XSHUT_PIN) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO27 as an output");
        return 1;
    }
    if (gpio_write(XSHUT_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO27 high");
        return 1;
    }

    // Initialise the I2C device
    int i2c_handle = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        return 1;
    }

    // Configure the sensor
    uint8_t reg_val = 0;
    if (i2c_write(i2c_handle, REG_CONT_MODE, &reg_val, 1) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0018");
        return 1;
    }
    if (i2c_write(i2c_handle, REG_TIMEOUT, &reg_val, 1) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0019");
        return 1;
    }
    if (i2c_write(i2c_handle, REG_START_RANGING, &reg_val, 1) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0020");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Infinite loop to read the sensor data
    while (true) {
        // Read the distance and status registers
        uint8_t distance_bytes[2];
        uint8_t status_byte;
        if (i2c_read(i2c_handle, REG_DISTANCE, distance_bytes, 2) < 0) {
            syslog(LOG_ERR, "Failed to read from register 0x0014");
            continue;
        }
        if (i2c_read(i2c_handle, REG_STATUS, &status_byte, 1) < 0) {
            syslog(LOG_ERR, "Failed to read from register 0x0016");
            continue;
        }

        // Convert the distance to mm
        uint16_t distance = (distance_bytes[0] << 8) | distance_bytes[1];

        // Log the data to the systemd journal
        syslog(LOG_INFO, "Distance: %d mm, Status: %d", distance, status_byte);

        // Wait 100 ms before reading again
        usleep(100000);
    }

    // Clean up on exit
    i2c_close(i2c_handle);
    pigpio_stop();

    return 0;
}

void sigint_handler(int signal) {
    // Clean up on SIGINT
    i2c_close(i2c_handle);
    pigpio_stop();
    exit(0);
}

void sigterm_handler(int signal) {
    // Clean up on SIGTERM
    i2c_close(i2c_handle);
    pigpio_stop();
    exit(0);
}

