#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <pigpio.h>
#include <vl53l1x.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define LED_GPIO 17

#define BUFFER_SIZE 10

int main(void) {
    // Initialise pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        return 1;
    }

    // Initialise I2C handle
    int i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    // Initialise VL53L1X sensor
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Failed to initialise VL53L1X sensor\n");
        return 1;
    }

    // Set default configuration
    if (vl53l1x_set_default_config(i2c_handle) < 0) {
        fprintf(stderr, "Failed to set default configuration\n");
        return 1;
    }

    // Enable signal rate check
    if (vl53l1x_enable_signal_rate_check(i2c_handle) < 0) {
        fprintf(stderr, "Failed to enable signal rate check\n");
        return 1;
    }

    // Configure cross-talk compensation
    if (vl53l1x_configure_cross_talk_compensation(i2c_handle) < 0) {
        fprintf(stderr, "Failed to configure cross-talk compensation\n");
        return 1;
    }

    // Start ranging
    if (vl53l1x_start_ranging(i2c_handle) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        return 1;
    }

    // Set up circular buffer for distance measurements
    uint16_t buffer[BUFFER_SIZE];
    int buffer_index = 0;

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    while (1) {
        // Read distance measurement
        uint16_t distance = vl53l1x_read_distance(i2c_handle);
        if (distance < 0) {
            fprintf(stderr, "Failed to read distance measurement\n");
            continue;
        }

        // Store distance measurement in circular buffer
        buffer[buffer_index] = distance;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Check if any reading is below 200 mm
        int below_200 = 0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            if (buffer[i] < 200) {
                below_200 = 1;
                break;
            }
        }

        // Set LED state
        if (below_200) {
            pigpio_gpio_write(LED_GPIO, 1);
        } else {
            pigpio_gpio_write(LED_GPIO, 0);
        }

        // Sleep for 50 ms
        usleep(50000);
    }

    return 0;
}

void sigint_handler(int signum) {
    // Turn off LED
    pigpio_gpio_write(LED_GPIO, 0);

    // Close I2C handle
    pigpio_i2c_close(i2c_handle);

    // Terminate pigpio
    pigpio_stop();

    // Release all resources
    pigpio_cleanup();

    // Exit program
    exit(0);
}

