#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <i2c.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define PROXIMITY_THRESHOLD 1000

#define PROXIMITY_HIGH_REG 0x08
#define PROXIMITY_LOW_REG 0x09

#define PROXIMITY_LOG_FILE "proximity.log"

static volatile bool running = true;
static volatile bool interrupt_flag = false;

static void handle_interrupt(int gpio, int level, uint32_t tick) {
    interrupt_flag = true;
}

static void read_proximity(void) {
    uint16_t proximity_value;
    uint8_t high_byte, low_byte;

    if (i2c_read_register(I2C_BUS, I2C_ADDR, PROXIMITY_HIGH_REG, &high_byte) != 0) {
        fprintf(stderr, "Error reading high byte of proximity value\n");
        return;
    }

    if (i2c_read_register(I2C_BUS, I2C_ADDR, PROXIMITY_LOW_REG, &low_byte) != 0) {
        fprintf(stderr, "Error reading low byte of proximity value\n");
        return;
    }

    proximity_value = (high_byte << 8) | low_byte;

    if (proximity_value > PROXIMITY_THRESHOLD) {
        fprintf(stderr, "Proximity value exceeded threshold: %d\n", proximity_value);
    } else {
        fprintf(stderr, "Proximity value within threshold: %d\n", proximity_value);
    }
}

static void log_proximity(void) {
    time_t now;
    struct tm *tm;
    char timestamp[20];

    time(&now);
    tm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    FILE *log_file = fopen(PROXIMITY_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", PROXIMITY_LOG_FILE);
        return;
    }

    fprintf(log_file, "%s, %d, %s\n", timestamp, proximity_value, (proximity_value > PROXIMITY_THRESHOLD) ? "ALERT" : "SAFE");

    fclose(log_file);
}

static void cleanup(void) {
    i2c_close(I2C_BUS);
    fclose(PROXIMITY_LOG_FILE);
    pigpio_stop();
}

int main(int argc, char *argv[]) {
    int i2c_address = I2C_ADDR;
    int threshold = PROXIMITY_THRESHOLD;

    if (argc > 1) {
        if (strcmp(argv[1], "-a") == 0) {
            i2c_address = strtol(argv[2], NULL, 0);
        } else if (strcmp(argv[1], "-t") == 0) {
            threshold = strtol(argv[2], NULL, 0);
        }
    }

    if (pigpio_start() != 0) {
        fprintf(stderr, "Error starting pigpio\n");
        return 1;
    }

    if (i2c_open(I2C_BUS) != 0) {
        fprintf(stderr, "Error opening I2C bus %d\n", I2C_BUS);
        return 1;
    }

    if (gpio_set_mode(27, GPIO_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO 27 to input mode\n");
        return 1;
    }

    if (gpio_set_pull_up_down(27, GPIO_PULL_UP) != 0) {
        fprintf(stderr, "Error setting GPIO 27 pull-up\n");
        return 1;
    }

    if (gpio_set_interrupt(27, GPIO_RISING_EDGE, handle_interrupt) != 0) {
        fprintf(stderr, "Error setting GPIO 27 interrupt\n");
        return 1;
    }

    while (running) {
        if (interrupt_flag) {
            read_proximity();
            log_proximity();
            interrupt_flag = false;
        }
    }

    cleanup();

    return 0;
}

