    if ((pigpio_handle = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up PWM output on GPIO18
    if ((pwm_handle = gpioPWM(SPEAKER_PIN, PWM_FREQ, PWM_DUTY)) < 0) {
        fprintf(stderr, "Failed to set up PWM output on GPIO18\n");
        gpioTerminate();
        return 1;
    }

    // Set up trigger and echo pins
    if ((trigger_handle = gpioSetMode(TRIGGER_PIN, PI_OUTPUT)) < 0) {
