        gpioTerminate();
        return 1;
    }
    if ((echo_handle = gpioSetMode(ECHO_PIN, PI_INPUT)) < 0) {
        fprintf(stderr, "Failed to set up echo pin\n");
        gpioTerminate();
        return 1;
    }

