#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

#define MIN_FREQ 200
#define MAX_FREQ 2000
#define MIN_DIST 5
#define MAX_DIST 50

#define TIMEOUT_US 100000

static bool running = true;

void sigint_handler(int signum) {
    running = false;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0 || gpioSetMode(ECHO_PIN, PI_INPUT) < 0 || gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        return 1;
    }

    // Set trigger low initially
    gpioWrite(TRIG_PIN, PI_LOW);

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (running) {
        // Send a 10 us high pulse
        gpioWrite(TRIG_PIN, PI_HIGH);
        usleep(10);
        gpioWrite(TRIG_PIN, PI_LOW);

        // Measure echo pulse width
        uint32_t start_time = gpioTick();
        uint32_t end_time = 0;
        while (gpioRead(ECHO_PIN) == PI_LOW) {
            end_time = gpioTick();
            if (end_time - start_time > TIMEOUT_US) {
                fprintf(stderr, "Timeout\n");
                break;
            }
        }

        // Calculate distance
        uint32_t distance = (end_time - start_time) / 2;

        // Map distance to frequency
        uint32_t frequency = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST);
        frequency = (frequency < MIN_FREQ) ? MIN_FREQ : (frequency > MAX_FREQ) ? MAX_FREQ : frequency;

        // Set PWM frequency
        gpioHardwarePWM(BUZZER_PIN, frequency, 0);

        // Print distance and frequency
        printf("Distance: %u cm, Frequency: %u Hz\n", distance, frequency);

        // Delay for 10 ms
        usleep(10000);
    }

    // Clean up
    gpioTerminate();

    return 0;
}

