#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pigpio.h>
#include <signal.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define TRIG_PULSE_US 10
#define ECHO_TIMEOUT_MS 50
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400

static volatile bool running = true;

void sigint_handler(int signum) {
    running = false;
}

int main(void) {
    int pi;
    int trig_pin, echo_pin;
    int pulse_width;
    float distance;

    // Initialize pigpio
    if ((pi = pigpio_start(NULL, NULL)) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set trigger pin as output and echo pin as input
    if (pigpio_gpio_mode_set(pi, TRIG_PIN, PI_OUTPUT) < 0 ||
        pigpio_gpio_mode_set(pi, ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        pigpio_stop(pi);
        return 1;
    }

    // Set trigger pin to low
    if (pigpio_gpio_write(pi, TRIG_PIN, PI_LOW) < 0) {
        fprintf(stderr, "Failed to set trigger pin to low\n");
        pigpio_stop(pi);
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    while (running) {
        // Send trigger pulse
        if (pigpio_gpio_write(pi, TRIG_PIN, PI_HIGH) < 0) {
            fprintf(stderr, "Failed to set trigger pin to high\n");
            pigpio_stop(pi);
            return 1;
        }
        usleep(TRIG_PULSE_US);
        if (pigpio_gpio_write(pi, TRIG_PIN, PI_LOW) < 0) {
            fprintf(stderr, "Failed to set trigger pin to low\n");
            pigpio_stop(pi);
            return 1;
        }

        // Measure echo pulse width
        pulse_width = pigpio_gpio_pulse_in(pi, ECHO_PIN, PI_PULSE_IN_ECHO, ECHO_TIMEOUT_MS);
        if (pulse_width < 0) {
            fprintf(stderr, "Failed to measure echo pulse width\n");
            pigpio_stop(pi);
            return 1;
        }

        // Compute distance
        distance = (float)pulse_width / 2 / 29.1;

        // Check for invalid readings
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %.2f cm", distance);
            if (distance < 10) {
                printf(" (Too close!)");
            }
            printf("\n");
        }

        // Sleep for 500 ms
        usleep(500000);
    }

    // Clean up
    pigpio_stop(pi);

    return 0;
}

