#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CS_GPIO 8

#define REG_CONT_MEAS_MODE 0x01
#define REG_RANGE_MODE 0x02
#define REG_MEAS_TRIGGER 0x00
#define REG_DIST_LOW_BYTE 0x0C
#define REG_DIST_HIGH_BYTE 0x0D

#define RANGE_5M 0x00
#define RANGE_10M 0x01
#define RANGE_20M 0x02
#define RANGE_50M 0x03

#define MEAS_MODE_CONT 0x01
#define MEAS_MODE_SINGLE 0x00

#define SPI_READ_SIZE 2

int main(void) {
    // Initialise SPI
    int spi_handle = pigpio_spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_CS_GPIO);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI handle: %s\n", pigpio_error(spi_handle));
        return 1;
    }

    // Initialise sensor
    uint8_t init_data[3] = { REG_CONT_MEAS_MODE, MEAS_MODE_CONT, REG_RANGE_MODE, RANGE_5M, REG_MEAS_TRIGGER, MEAS_MODE_SINGLE };
    if (pigpio_spi_write(spi_handle, init_data, 3) < 0) {
        fprintf(stderr, "Error initialising sensor: %s\n", pigpio_error(spi_handle));
        pigpio_spi_close(spi_handle);
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        pigpio_spi_close(spi_handle);
        return 1;
    }

    // Set up SIGINT and SIGTERM handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Trigger measurement
        uint8_t trigger_data[1] = { REG_MEAS_TRIGGER };
        if (pigpio_spi_write(spi_handle, trigger_data, 1) < 0) {
            fprintf(stderr, "Error triggering measurement: %s\n", pigpio_error(spi_handle));
            continue;
        }

        // Read distance
        uint8_t read_data[SPI_READ_SIZE];
        if (pigpio_spi_read(spi_handle, read_data, SPI_READ_SIZE) < 0) {
            fprintf(stderr, "Error reading distance: %s\n", pigpio_error(spi_handle));
            continue;
        }

        // Calculate distance
        uint16_t distance = (read_data[0] << 8) | read_data[1];

        // Log distance
        time_t now = time(NULL);
        fprintf(log_file, "%ld, %d\n", now, distance);

        // Wait for next measurement
        usleep(100000);
    }

    // Clean up
    fclose(log_file);
    pigpio_spi_close(spi_handle);

    return 0;
}

void sigint_handler(int signum) {
    fprintf(stderr, "SIGINT received, closing SPI handle and releasing resources\n");
    pigpio_spi_close(spi_handle);
    exit(0);
}

void sigterm_handler(int signum) {
    fprintf(stderr, "SIGTERM received, closing SPI handle and releasing resources\n");
    pigpio_spi_close(spi_handle);
    exit(0);
}

