#include <linux/i2c-dev.h>

#define I2C_ADDR 0x60
#define REG_ALS_VISIBLE_LOW 0x22
#define REG_ALS_VISIBLE_HIGH 0x23

int main(void)
{
    int fd;
    uint8_t reg_addr;
    uint16_t als_visible;
    char timestamp[20];
    FILE *log_file;

    // Open the I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Open the log file
    log_file = fopen("proximity_log.csv", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    // Write the header row to the log file
    fprintf(log_file, "timestamp,als_visible\n");

    // Read the ALS visible light value every 5 seconds
    while (1) {
        // Read the low byte of the ALS visible light value
        reg_addr = REG_ALS_VISIBLE_LOW;
        if (write(fd, &reg_addr, 1) != 1) {
            perror("Failed to write register address");
            close(fd);
            fclose(log_file);
            return 1;
        }
        if (read(fd, &als_visible, 1) != 1) {
            perror("Failed to read ALS visible light value");
            close(fd);
            fclose(log_file);
            return 1;
        }

        // Read the high byte of the ALS visible light value
        reg_addr = REG_ALS_VISIBLE_HIGH;
        if (write(fd, &reg_addr, 1) != 1) {
            perror("Failed to write register address");
            close(fd);
            fclose(log_file);
            return 1;
        }
        if (read(fd, &als_visible, 1) != 1) {
            perror("Failed to read ALS visible light value");
