#define REG_ALS_LOW 0x22
#define REG_ALS_HIGH 0x23
#define REG_PS1_LOW 0x18
#define REG_PS1_HIGH 0x19
#define REG_RESET 0x30

#define RETRY_COUNT 3
#define RETRY_DELAY 10

int main(void) {
    int i2c_handle;
    int als_low, als_high, ps1_low, ps1_high;
    uint16_t als, ps1;
    char timestamp[20];
    FILE *log_file;

