    if ((i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR)) < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", pigpio_error(i2c_handle));
        return 1;
    }

    // Reset sensor
    if (pigpio_i2c_write(i2c_handle, REG_RESET, 0x01) < 0) {
        fprintf(stderr, "Error resetting sensor: %s\n", pigpio_error(i2c_handle));
        goto cleanup;
    }

    // Verify part ID
    if (pigpio_i2c_read(i2c_handle, REG_PART_ID, &als_low, &als_high) < 0) {
        fprintf(stderr, "Error reading part ID: %s\n", pigpio_error(i2c_handle));
        goto cleanup;
    }
    if (als_low != 0x41) {
        fprintf(stderr, "Invalid part ID: %02x\n", als_low);
        goto cleanup;
    }

    // Open log file
    if ((log_file = fopen("si1120_log.txt", "a")) == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        goto cleanup;
    }

    // Main loop
    while (1) {
        // Read ALS data
        for (int i = 0; i < RETRY_COUNT; i++) {
            if (pigpio_i2c_read(i2c_handle, REG_ALS_LOW, &als_low, &als_high) < 0) {
                fprintf(stderr, "Error reading ALS data: %s\n", pigpio_error(i2c_handle));
                continue;
            }
            als = (als_high << 8) | als_low;
            break;
        }

        // Read PS1 data
        for (int i = 0; i < RETRY_COUNT; i++) {
            if (pigpio_i2c_read(i2c_handle, REG_PS1_LOW, &ps1_low, &ps1_high) < 0) {
                fprintf(stderr, "Error reading PS1 data: %s\n", pigpio_error(i2c_handle));
                continue;
            }
            ps1 = (ps1_high << 8) | ps1_low;
            break;
        }

        // Log data
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s, ALS: %d, PS1: %d\n", timestamp, als, ps1);

        // Sleep for 500 ms
        usleep(500000);
    }

cleanup:
    // Close I2C bus
    pigpio_i2c_close(i2c_handle);

    // Close log file
    fclose(log_file);

    return 0;
}

