#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <time.h>

#define I2C_ADDR 0x39
#define PART_ID_REG 0x00
#define MEAS_RATE_REG 0x08
#define AMBIENT_LIGHT_REG 0x22
#define PROXIMITY_REG 0x24

#define LUX_CONV_FACTOR 0.1

int main(void) {
    int fd;
    uint8_t part_id;
    uint8_t meas_rate;
    uint16_t ambient_light;
    uint16_t proximity;
    char timestamp[20];
    FILE *log_file;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Verify part ID
    if (ioctl(fd, I2C_SMBUS, I2C_FUNC_SMBUS_READ_BYTE_DATA, I2C_ADDR, PART_ID_REG) != 0x40) {
        perror("Failed to verify part ID");
        close(fd);
        return 1;
    }

    // Configure measurement rate
    meas_rate = 0x07;
    if (ioctl(fd, I2C_SMBUS, I2C_FUNC_SMBUS_WRITE_BYTE_DATA, I2C_ADDR, MEAS_RATE_REG, meas_rate) != 0) {
        perror("Failed to configure measurement rate");
        close(fd);
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    // Set up SIGINT and SIGTERM handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read ambient light data
        if (ioctl(fd, I2C_SMBUS, I2C_FUNC_SMBUS_READ_WORD_DATA, I2C_ADDR, AMBIENT_LIGHT_REG) != 0) {
            perror("Failed to read ambient light data");
            close(fd);
            fclose(log_file);
            return 1;
        }
        ambient_light = (uint16_t)(((uint16_t)buf[0] << 8) | (uint16_t)buf[1]);

        // Read proximity data
        if (ioctl(fd, I2C_SMBUS, I2C_FUNC_SMBUS_READ_WORD_DATA, I2C_ADDR, PROXIMITY_REG) != 0) {
            perror("Failed to read proximity data");
            close(fd);
            fclose(log_file);
            return 1;
        }
        proximity = (uint16_t)(((uint16_t)buf[0] << 8) | (uint16_t)buf[1]);

        // Convert ambient light to lux
        lux = ambient_light * LUX_CONV_FACTOR;

        // Log data to file
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%L", localtime(&now));
        fprintf(log_file, "%s,%d,%d\n", timestamp, lux, proximity);

        // Print data to stdout
        printf("%s: Ambient light: %d lux, Proximity: %d\n", timestamp, lux, proximity);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close I2C device and log file
    close(fd);
    fclose(log_file);

    return 0;
}

void sigint_handler(int signum) {
    printf("Received SIGINT, closing I2C device and log file\n");
    close(fd);
    fclose(log_file);
    exit(0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM, closing I2C device and log file\n");
    close(fd);
    fclose(log_file);
    exit(0);
}

