#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pigpio.h>

#define I2C_ADDR 0x60
#define REG_HW_KEY 0x07
#define REG_MEAS_RATE 0x06
#define REG_NO_INT 0x1A
#define REG_ALS_VIS_IR_ADC_COUNTER 0x21
#define REG_ALS_VIS_ADC_GAIN 0x24
#define REG_PS_ADC_COUNTER 0x22
#define REG_PS_LED21 0x0C
#define REG_PS_LED3 0x0F
#define REG_PS_ADC_MISC 0x11
#define REG_PS_ADC_GAIN 0x0D
#define REG_COMMAND 0x80
#define REG_PS1_DATA0 0x16
#define REG_PS1_DATA1 0x17

#define MAX_RETRIES 3

int main(void)
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C handle
    int i2c_handle = i2cOpen(I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    // Initialize sensor
    uint8_t reg_vals[] = {
        0x03, // REG_HW_KEY
        0x02, // REG_MEAS_RATE
        0x00, // REG_NO_INT
        0x0B, // REG_ALS_VIS_IR_ADC_COUNTER
        0x00, // REG_ALS_VIS_ADC_GAIN
        0x49, // REG_PS_ADC_COUNTER
        0x03, // REG_PS_LED21
        0x0F, // REG_PS_LED3
        0x03, // REG_PS_ADC_MISC
        0x07, // REG_PS_ADC_GAIN
        0x03  // REG_COMMAND
    };
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cWriteByteData(i2c_handle, reg_vals, sizeof(reg_vals)) == 0) {
            fprintf(stderr, "Failed to initialize sensor\n");
            retries++;
        } else {
            break;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize sensor after %d retries\n", retries);
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up SIGINT and SIGTERM handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read proximity value
        uint8_t ps1_data0, ps1_data1;
        if (i2cReadByteData(i2c_handle, REG_PS1_DATA0, &ps1_data0) < 0) {
            fprintf(stderr, "Failed to read proximity value\n");
            return 1;
        }
        if (i2cReadByteData(i2c_handle, REG_PS1_DATA1, &ps1_data1) < 0) {
            fprintf(stderr, "Failed to read proximity value\n");
            return 1;
        }
        uint16_t proximity = (ps1_data1 << 8) | ps1_data0;

        // Append reading to log file
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(log_file, "%s, %u\n", timestamp, proximity);

        // Sleep for 2 ms
        usleep(2000);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum)
{
    // Close I2C handle
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    // Exit program
    exit(0);
}

void sigterm_handler(int signum)
{
    // Close I2C handle
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    // Exit program
    exit(0);
}

