    if (gpio_set_mode(echo_pin, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin as input\n");
        exit(1);
    }
    if (gpio_set_alert_func_ex(echo_pin, handle_interrupt) < 0) {
