            // set buzzer pin high
            gpio_write(buzzer_pin, 1);
        } else {
            // set buzzer pin low
            gpio_write(buzzer_pin, 0);
        }

        // wait for 1 second
        gpio_delay(1000);
    }

    // clean up
    gpio_write(buzzer_pin, 0);
    gpio_close(gpio_fd);
    return 0;
}

