#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

#define TRIG_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define MIN_DISTANCE 200
#define MAX_DISTANCE 20

#define MIN_ANGLE 500
#define MAX_ANGLE 2500

#define DELAY_MS 100

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", TRIG_PIN);
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", ECHO_PIN);
        return 1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", SERVO_PIN);
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        double distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Failed to measure distance\n");
            continue;
        }

        int angle = map_distance_to_angle(distance);
        if (angle < 0) {
            fprintf(stderr, "Failed to map distance to angle\n");
            continue;
        }

        if (gpioServo(SERVO_PIN, angle) < 0) {
            fprintf(stderr, "Failed to set servo angle\n");
            continue;
        }

        printf("Distance: %.2f cm, Angle: %d\n", distance, angle);

        gpioDelay(DELAY_MS);
    }

    gpioServo(SERVO_PIN, 0);
    pigpio_stop();

    return 0;
}

double measure_distance(void) {
    if (gpioWrite(TRIG_PIN, PI_HIGH) < 0) {
        fprintf(stderr, "Failed to set GPIO %d high\n", TRIG_PIN);
        return -1.0;
    }

    gpioDelay(10);

    if (gpioWrite(TRIG_PIN, PI_LOW) < 0) {
        fprintf(stderr, "Failed to set GPIO %d low\n", TRIG_PIN);
        return -1.0;
    }

    int echo_state = gpioRead(ECHO_PIN);
    if (echo_state < 0) {
        fprintf(stderr, "Failed to read GPIO %d\n", ECHO_PIN);
        return -1.0;
    }

    if (echo_state == PI_LOW) {
        return -1.0;
    }

    int echo_duration = gpioPulseIn(ECHO_PIN, PI_HIGH, 10000);
    if (echo_duration < 0) {
        fprintf(stderr, "Failed to measure echo duration\n");
        return -1.0;
    }

    double distance = (double)echo_duration / 58.0;
    return distance;
}

int map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return (int)(MIN_ANGLE + (MAX_ANGLE - MIN_ANGLE) * (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE));
    }
}

