#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <vl53l1x.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_PIN 18
#define TIMING_BUDGET 20000
#define DISTANCE_REG 0x10F
#define MODEL_ID_REG 0x010F
#define MODEL_ID 0xEA
#define CLOSED_PULSE_WIDTH 1000
#define OPEN_PULSE_WIDTH 2000
#define CLOSE_DISTANCE 200
#define OPEN_DISTANCE 250

static volatile bool running = true;

void sigint_handler(int signum) {
    running = false;
}

int main(void) {
    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Initialize I2C bus
    int i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Failed to initialize VL53L1X sensor\n");
        return 1;
    }

    // Verify model ID
    uint8_t model_id;
    if (vl53l1x_read_reg(i2c_handle, MODEL_ID_REG, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID\n");
        return 1;
    }
    if (model_id != MODEL_ID) {
        fprintf(stderr, "Invalid model ID: %02X\n", model_id);
        return 1;
    }

    // Set timing budget
    if (vl53l1x_set_timing_budget(i2c_handle, TIMING_BUDGET) < 0) {
        fprintf(stderr, "Failed to set timing budget\n");
        return 1;
    }

    // Start ranging
    if (vl53l1x_start_ranging(i2c_handle) < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("gate_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up servo actuator
    if (pigpio_set_mode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin mode\n");
        return 1;
    }
    if (pigpio_set_servo_pulsewidth(GPIO_PIN, CLOSED_PULSE_WIDTH) < 0) {
        fprintf(stderr, "Failed to set servo pulse width\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Read distance from sensor
        uint16_t distance;
        if (vl53l1x_read_reg(i2c_handle, DISTANCE_REG, &distance) < 0) {
            fprintf(stderr, "Failed to read distance\n");
            return 1;
        }

        // Check if object is close enough to open gate
        if (distance < CLOSE_DISTANCE) {
            // Open gate
            if (pigpio_set_servo_pulsewidth(GPIO_PIN, OPEN_PULSE_WIDTH) < 0) {
                fprintf(stderr, "Failed to set servo pulse width\n");
                return 1;
            }

            // Log open event
            fprintf(log_file, "Opened gate at %ld\n", time(NULL));
        }

        // Check if object is far enough to close gate
        if (distance > OPEN_DISTANCE) {
            // Close gate
            if (pigpio_set_servo_pulsewidth(GPIO_PIN, CLOSED_PULSE_WIDTH) < 0) {
                fprintf(stderr, "Failed to set servo pulse width\n");
                return 1;
            }

            // Log close event
            fprintf(log_file, "Closed gate at %ld\n", time(NULL));
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    fclose(log_file);
    pigpio_stop(i2c_handle);
    pigpio_stop(GPIO_PIN);
    pigpio_stop();

    return 0;
}

