#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMID_REG 0x02

#define T_OFFSET 46.85
#define H_OFFSET 6.0
#define T_SCALE 175.72
#define H_SCALE 125.0

int main(void) {
    int i2c_handle;
    int ret;
    uint8_t config_reg = 0x00;
    uint8_t temp_reg;
    uint8_t humid_reg;
    float temp;
    float humid;

    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        pigpio_stop();
        return 1;
    }

    // Write to CONFIG register to select internal temperature sensor and disable heater
    ret = pigpio_i2c_write(i2c_handle, &config_reg, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        pigpio_i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    // Wait for 10 ms for conversion
    usleep(10000);

    // Read temperature and humidity registers
    ret = pigpio_i2c_read(i2c_handle, &temp_reg, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to read temperature register\n");
        pigpio_i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    ret = pigpio_i2c_read(i2c_handle, &humid_reg, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to read humidity register\n");
        pigpio_i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    // Convert readings
    temp = (T_SCALE * temp_reg) / 65536.0 - T_OFFSET;
    humid = (H_SCALE * humid_reg) / 65536.0 - H_OFFSET;

    // Print readings to console
    printf("Temperature: %.2f°C\n", temp);
    printf("Humidity: %.2f%%\n", humid);

    // Close I2C handle and pigpio
    pigpio_i2c_close(i2c_handle);
    pigpio_stop();

    return 0;
}

void sigint_handler(int signum) {
    // Close I2C handle and pigpio on SIGINT
    pigpio_i2c_close(i2c_handle);
    pigpio_stop();
    exit(0);
}

int main(void) {
    // Register SIGINT handler
    signal(SIGINT, sigint_handler);

    // Run main program
    return main();
}

