#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define MPU6050_ADDR 0x68
#define WHO_AM_I_REG 0x75
#define PWR_MGMT_1_REG 0x6B
#define SMPLRT_DIV_REG 0x19
#define ACCEL_CONFIG_REG 0x1C
#define GYRO_CONFIG_REG 0x1B
#define ACCEL_XOUTH_REG 0x3B
#define ACCEL_XOUTL_REG 0x3C
#define ACCEL_YOUTH_REG 0x3D
#define ACCEL_YOUTL_REG 0x3E
#define ACCEL_ZOUTH_REG 0x3F
#define ACCEL_ZOUTL_REG 0x40
#define TEMP_OUTH_REG 0x41
#define TEMP_OUTL_REG 0x42
#define GYRO_XOUTH_REG 0x43
#define GYRO_XOUTL_REG 0x44
#define GYRO_YOUTH_REG 0x45
#define GYRO_YOUTL_REG 0x46
#define GYRO_ZOUTH_REG 0x47
#define GYRO_ZOUTL_REG 0x48

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus 1
    int i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor is present
    uint8_t who_am_i;
    if (i2cReadByteData(i2c_handle, WHO_AM_I_REG, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (who_am_i != MPU6050_ADDR) {
        fprintf(stderr, "Sensor not present\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Reset device
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1_REG, 0x80) < 0) {
        fprintf(stderr, "Failed to reset device\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for device to stabilize
    usleep(100000);

    // Clear sleep bit
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to clear sleep bit\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set sample-rate divider to 7 for 125 Hz output
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV_REG, 0x07) < 0) {
        fprintf(stderr, "Failed to set sample-rate divider\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure ACCEL_CONFIG for a ±2 g range and GYRO_CONFIG for a ±250 deg/s range
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure ACCEL_CONFIG\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure GYRO_CONFIG\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read 14-byte data block starting at register 0x3B
        uint8_t data[14];
        if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUTH_REG, data, 14) < 0) {
            fprintf(stderr, "Failed to read data block\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Parse big-endian int16 values
        int16_t accel_x = (data[0] << 8) | data[1];
        int16_t accel_y = (data[2] << 8) | data[3];
        int16_t accel_z = (data[4] << 8) | data[5];
        int16_t temp = (data[6] << 8) | data[7];
        int16_t gyro_x = (data[8] << 8) | data[9];
        int16_t gyro_y = (data[10] << 8) | data[11];
        int16_t gyro_z = (data[12] << 8) | data[13];

        // Print data to stdout
        printf("Accel X: %d, Accel Y: %d, Accel Z: %d, Temp: %d, Gyro X: %d, Gyro Y: %d, Gyro Z: %d\n", accel_x, accel_y, accel_z, temp, gyro_x, gyro_y, gyro_z);

        // Wait 100 ms
        usleep(100000);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

void signal_handler(int signal) {
    // Close I2C handle and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    // Print clean-shutdown message
    printf("Clean shutdown\n");

    // Exit program
    exit(0);
}

