#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <signal.h>

#define MLX90614_ADDR 0x5A
#define MLX90614_AMBIENT_REG 0x06
#define MLX90614_OBJECT_REG 0x07

#define I2C_DEV "/dev/i2c-1"
#define LOG_FILE "temperature_log.csv"

int main(void) {
    int i2c_fd;
    int ret;
    char buf[2];
    FILE *log_file;

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    ret = ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    while (1) {
        // Read ambient temperature
        ret = i2c_smbus_read_byte_data(i2c_fd, MLX90614_AMBIENT_REG);
        if (ret < 0) {
            perror("Failed to read ambient temperature");
            break;
        }
        buf[0] = ret;

        // Read object temperature
        ret = i2c_smbus_read_byte_data(i2c_fd, MLX90614_OBJECT_REG);
        if (ret < 0) {
            perror("Failed to read object temperature");
            break;
        }
        buf[1] = ret;

        // Write to log file
        fprintf(log_file, "%ld, %d, %d\n", time(NULL), buf[0], buf[1]);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    // Close log file
    fclose(log_file);

    return 0;
}

void sigint_handler(int signum) {
    // Close I2C device
    close(i2c_fd);

    // Close log file
    fclose(log_file);

    // Exit program
    exit(0);
}

