        fprintf(log_file, "%ld, %d, %d\n", time(NULL), buf[0], buf[1]);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    // Close log file
    fclose(log_file);

    return 0;
}

