#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_ADDR 0x25
#define SENSOR_CMD_CONT_MEAS 0x36
#define SENSOR_CMD_READ_DATA 0x08
#define SENSOR_DATA_LEN 9
#define SENSOR_CRC_POLY 0x31
#define SENSOR_CRC_INIT 0xFF

#define FILENAME "pressure_log.csv"

int main(void) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open file for logging
    FILE *fp = fopen(FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file %s for writing\n", FILENAME);
        return 1;
    }

    // Set up I2C bus
    int i2c_handle = i2cOpen(1, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Set up sensor for continuous measurement
    uint8_t cmd[2] = {SENSOR_CMD_CONT_MEAS, SENSOR_CMD_READ_DATA};
    if (i2cWrite(i2c_handle, cmd, 2) < 0) {
        fprintf(stderr, "Failed to send command to sensor\n");
        return 1;
    }

    // Wait for at least 1 ms for sensor to start measurement
    usleep(1000);

    // Read data frame
    uint8_t data[SENSOR_DATA_LEN];
    if (i2cRead(i2c_handle, data, SENSOR_DATA_LEN) < 0) {
        fprintf(stderr, "Failed to read data from sensor\n");
        return 1;
    }

    // Check CRC-8 checksum
    uint8_t crc = crc8(data, SENSOR_DATA_LEN - 1, SENSOR_CRC_POLY, SENSOR_CRC_INIT);
    if (crc != data[SENSOR_DATA_LEN - 1]) {
        fprintf(stderr, "Invalid CRC-8 checksum\n");
        return 1;
    }

    // Convert raw pressure and temperature
    int16_t pressure = (data[0] << 8) | data[1];
    int16_t temperature = (data[2] << 8) | data[3];

    // Log data to file
    time_t now = time(NULL);
    struct tm *tm = gmtime(&now);
    fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02dZ,%.2f,%.2f\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec,
            pressure / 100.0, temperature / 100.0);

    // Close file and I2C bus
    fclose(fp);
    i2cClose(i2c_handle);

    // Clean up pigpio library
    gpioTerminate();

    return 0;
}

