#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <time.h>

#define SHT40_ADDR 0x44
#define SHT40_CMD_HIGH_REP 0xFD
#define SHT40_TEMP_MSB_REG 0x00
#define SHT40_TEMP_LSB_REG 0x01
#define SHT40_HUM_MSB_REG 0x02
#define SHT40_HUM_LSB_REG 0x03
#define SHT40_CRC_REG 0x04

#define SHT40_TEMP_CALIBRATION -45
#define SHT40_TEMP_SCALE 175
#define SHT40_HUM_SCALE 100

#define SHT40_CRC_POLY 0x31
#define SHT40_CRC_INIT 0xFF

int main(void) {
    int fd;
    uint8_t buf[6];
    uint16_t temp, hum;
    uint8_t crc;
    int ret;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    ret = ioctl(fd, I2C_SLAVE, SHT40_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Set I2C frequency
    ret = ioctl(fd, I2C_SET_FREQ, 100000);
    if (ret < 0) {
        perror("Failed to set I2C frequency");
        close(fd);
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("sht40_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Send high-repeatability measurement command
        ret = write(fd, &SHT40_CMD_HIGH_REP, 1);
        if (ret < 0) {
            perror("Failed to send measurement command");
            close(fd);
            fclose(log_file);
            return 1;
        }

        // Wait for measurement to complete
        usleep(10000);

        // Read temperature and humidity data
        ret = read(fd, buf, 6);
        if (ret < 0) {
            perror("Failed to read temperature and humidity data");
            close(fd);
            fclose(log_file);
            return 1;
        }

        // Calculate temperature
        temp = (buf[0] << 8) | buf[1];
        temp = (temp * SHT40_TEMP_SCALE) / 65535 + SHT40_TEMP_CALIBRATION;

        // Calculate humidity
        hum = (buf[2] << 8) | buf[3];
        hum = hum * SHT40_HUM_SCALE / 65535;

        // Validate CRC
        crc = buf[4];
        if (crc != crc8(buf, 4, SHT40_CRC_POLY, SHT40_CRC_INIT)) {
            fprintf(stderr, "Invalid CRC\n");
            continue;
        }

        // Log temperature and humidity readings
        fprintf(log_file, "%ld, %d, %d\n", time(NULL), temp, hum);

        // Wait for next measurement
        sleep(5);
    }

    // Close I2C device
    close(fd);

    // Close log file
    fclose(log_file);

    return 0;
}

uint8_t crc8(uint8_t *data, int len, uint8_t poly, uint8_t init) {
    uint8_t crc = init;
    int i, j;

    for (i = 0; i < len; i++) {
        crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }

    return crc;
}

