    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    struct sigaction sigint_action;
    sigint_action.sa_handler = sigint_handler;
    sigemptyset(&sigint_action.sa_mask);
    sigint_action.sa_flags = 0;
    sigaction(SIGINT, &sigint_action, NULL);

    // Main loop
    while (!sig_flag) {
        // Send continuous measurement trigger command
        uint8_t cmd[2] = {0x21, 0x96};
        if (i2cWriteDevice(i2c_handle, cmd, 2) < 0) {
            fprintf(stderr, "Failed to write I2C command\n");
            i2cClose(i2c_handle);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        // Wait for measurement to be ready
        usleep(I2C_READ_DELAY);

        // Read measurement data
        uint8_t data[6];
        if (i2cReadDevice(i2c_handle, data, 6) < 0) {
            fprintf(stderr, "Failed to read I2C data\n");
            i2cClose(i2c_handle);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        // Convert raw pressure and temperature to Pa and °C
        uint16_t raw_pressure = (data[0] << 8) | data[1];
        uint16_t raw_temperature = (data[3] << 8) | data[4];
        float pressure_pa = raw_pressure / 60.0;
        float temperature_c = raw_temperature / 200.0;

        // Log measurement
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec,
                pressure_pa, temperature_c);
        fflush(log_file);

        // Wait for next measurement
        usleep(I2C_READ_DELAY);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}
