#define SENSOR_HUMID_CMD 0xF5
#define SENSOR_READ_DELAY 20
#define SENSOR_READ_RETRIES 5

#define TEMP_RAW_MIN 0
#define TEMP_RAW_MAX 65535
#define TEMP_RAW_RANGE (TEMP_RAW_MAX - TEMP_RAW_MIN)
#define TEMP_C_MIN (-46.85)
#define TEMP_C_MAX (175.72)
#define TEMP_C_RANGE (TEMP_C_MAX - TEMP_C_MIN)

#define HUMID_RAW_MIN 0
#define HUMID_RAW_MAX 65535
#define HUMID_RAW_RANGE (HUMID_RAW_MAX - HUMID_RAW_MIN)
#define HUMID_RH_MIN 0
#define HUMID_RH_MAX 100
#define HUMID_RH_RANGE (HUMID_RH_MAX - HUMID_RH_MIN)

int main(void) {
    int i2c_handle;
    int ret;
    uint16_t temp_raw, humid_raw;
    float temp_c, humid_rh;
    char *pigpio_err;
    FILE *fp;

    // Initialize pigpio
    if ((pigpio_err = pigpio_init()) != NULL) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_err);
        return 1;
    }

    // Open I2C bus 1
    if ((i2c_handle = pigpio_i2c_open(1, SENSOR_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", strerror(errno));
        pigpio_terminate();
        return 1;
    }

    // Open file for logging
    if ((fp = fopen("sensor_data.txt", "a")) == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        pigpio_i2c_close(i2c_handle);
        pigpio_terminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read temperature
        if ((ret = pigpio_i2c_write(i2c_handle, SENSOR_TEMP_CMD, 1)) < 0) {
            fprintf(stderr, "Failed to write temperature command: %s\n", strerror(errno));
            pigpio_i2c_close(i2c_handle);
            pigpio_terminate();
            return 1;
        }
        if ((ret = pigpio_i2c_read(i2c_handle, &temp_raw, 2)) < 0) {
            fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
            pigpio_i2c_close(i2c_handle);
            pigpio_terminate();
            return 1;
        }
        temp_c = (TEMP_C_RANGE * (temp_raw - TEMP_RAW_MIN)) / TEMP_RAW_RANGE + TEMP_C_MIN;

        // Read humidity
        if ((ret = pigpio_i2c_write(i2c_handle, SENSOR_HUMID_CMD, 1)) < 0) {
            fprintf(stderr, "Failed to write humidity command: %s\n", strerror(errno));
            pigpio_i2c_close(i2c_handle);
            pigpio_terminate();
            return 1;
        }
        if ((ret = pigpio_i2c_read(i2c_handle, &humid_raw, 2)) < 0) {
            fprintf(stderr, "Failed to read humidity: %s\n", strerror(errno));
            pigpio_i2c_close(i2c_handle);
            pigpio_terminate();
            return 1;
        }
        humid_rh = (HUMID_RH_RANGE * (humid_raw - HUMID_RAW_MIN)) / HUMID_RAW_RANGE + HUMID_RH_MIN;

        // Log data
        fprintf(fp, "%ld, %f, %f\n", time(NULL), temp_c, humid_rh);
        fflush(fp);

        // Print data to console
        printf("Temperature: %f C, Humidity: %f %%RH\n", temp_c, humid_rh);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    fclose(fp);
    pigpio_i2c_close(i2c_handle);
    pigpio_terminate();

    return 0;
}

void sigint_handler(int signum) {
    // Close I2C handle and terminate pigpio
    pigpio_i2c_close(i2c_handle);
    pigpio_terminate();

    // Close file
    fclose(fp);

    // Exit
    exit(0);
}

