#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define CMD_MEASURE_HIGH_REPEATABILITY 0x2C06
#define CMD_READ_DATA 0x00
#define CMD_READ_CRC 0x01
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF

#define TEMP_SCALE_FACTOR 175
#define TEMP_OFFSET -45

#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_FILE "error_log.txt"

int main(void) {
    // Initialize the pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open the I2C bus
    int i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Set up the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Send the single-shot high-repeatability measurement command
        if (pigpio_i2c_write(i2c_handle, CMD_MEASURE_HIGH_REPEATABILITY, 1) < 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            goto error;
        }

        // Wait for at least 15 ms for conversion
        usleep(15000);

        // Read the data and CRC bytes
        uint8_t data[3];
        if (pigpio_i2c_read(i2c_handle, CMD_READ_DATA, data, 3) < 0) {
            fprintf(stderr, "Failed to read data\n");
            goto error;
        }

        // Validate the CRC
        uint8_t crc = pigpio_crc8(data, 2, CRC_POLYNOMIAL, CRC_INITIAL);
        if (crc != data[2]) {
            fprintf(stderr, "CRC mismatch\n");
            goto error;
        }

        // Convert the raw value to degrees Celsius
        int16_t raw = (data[0] << 8) | data[1];
        float temp = TEMP_OFFSET + TEMP_SCALE_FACTOR * (raw / 65535.0);

        // Log the reading
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        char line[50];
        snprintf(line, sizeof(line), "%s,%.2f\n", timestamp, temp);
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            goto error;
        }
        fputs(line, log_file);
        fclose(log_file);

        // Wait for the next measurement
        sleep(5);
    }

error:
    // Close the I2C bus and release resources
    pigpio_i2c_close(i2c_handle);
    pigpio_stop();

    // Log the error
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    char line[50];
    snprintf(line, sizeof(line), "%s,Error: %s\n", timestamp, strerror(errno));
    FILE *error_file = fopen(ERROR_FILE, "a");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        return 1;
    }
    fputs(line, error_file);
    fclose(error_file);

    return 0;
}

void sigint_handler(int signum) {
    // Close the I2C bus and release resources
    pigpio_i2c_close(i2c_handle);
    pigpio_stop();

    // Log the shutdown
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    char line[50];
    snprintf(line, sizeof(line), "%s,Shutdown\n", timestamp);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    fputs(line, log_file);
    fclose(log_file);

    exit(0);
}

