    if (ioctl(fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("sht40_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Send high-repeatability measurement command
        if (write(fd, &SHT40_CMD_HIGH_REP, 1) != 1) {
            perror("Failed to send measurement command");
            close(fd);
            fclose(log_file);
            return 1;
        }

        // Wait at least 8.5 ms before reading
        usleep(8500);

        // Read 6 bytes of data
        if (read(fd, buf, 6) != 6) {
            perror("Failed to read data");
            close(fd);
            fclose(log_file);
            return 1;
        }

        // Validate CRC
        if (crc8(buf, 5, SHT40_CRC_POLY, SHT40_CRC_INIT) != buf[5]) {
