        hum = 100 * raw_hum / 65535;

        // Get current time
        t = time(NULL);
        tm = localtime(&t);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);

        // Log temperature and humidity
        fprintf(log_file, "%s, %f, %f\n", time_str, temp, hum);
    }

    // Close I2C device and log file
    close(fd);
    fclose(log_file);

    return 0;
}

