#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_HYST 2.0
#define HUMID_HYST 2.0
#define BUFFER_SIZE 60

int main(void) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C handle
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    // Set up fan GPIO
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set fan GPIO mode\n");
        return 1;
    }

    // Set up circular buffer for log
    struct log_entry {
        time_t timestamp;
        float temperature;
        float humidity;
    };
    struct log_entry log[BUFFER_SIZE];
    int log_index = 0;

    // Main loop
    while (1) {
        // Read temperature and humidity
        uint16_t raw_temp, raw_humid;
        if (i2cReadWordData(i2c_handle, 0xE3, &raw_temp) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            return 1;
        }
        if (i2cReadWordData(i2c_handle, 0xE5, &raw_humid) < 0) {
            fprintf(stderr, "Failed to read humidity\n");
            return 1;
        }

        // Convert raw values to temperature and humidity
        float temperature = 175.72 * raw_temp / 65536.0 - 46.85;
        float humidity = 125.0 * raw_humid / 65536.0 - 6.0;

        // Log temperature and humidity
        log[log_index].timestamp = time(NULL);
        log[log_index].temperature = temperature;
        log[log_index].humidity = humidity;
        log_index = (log_index + 1) % BUFFER_SIZE;

        // Print log entry
        printf("[%s] Temperature: %.1f °C, Humidity: %.1f %%\n", ctime(&log[log_index].timestamp), log[log_index].temperature, log[log_index].humidity);

        // Control fan
        if (temperature > TEMP_HYST) {
            gpioWrite(FAN_GPIO, PI_HIGH);
        } else if (temperature < TEMP_HYST - HUMID_HYST) {
            gpioWrite(FAN_GPIO, PI_LOW);
        }

        // Sleep for 2 seconds
        sleep(2);
    }

    // Clean up
    gpioTerminate();
    i2cClose(i2c_handle);
    return 0;
}

