#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define SCD40_START_PERIODIC_MEASUREMENT 0x21B1
#define SCD40_STOP_PERIODIC_MEASUREMENT 0x3F86
#define SCD40_DATA_READY_FLAG 0xE4B8
#define SCD40_DATA_READ 0xEC05
#define SCD40_CRC_POLYNOMIAL 0x31
#define SCD40_CRC_INIT 0xFF

#define SCD40_CO2_RAW_OFFSET -45
#define SCD40_CO2_RAW_SCALE 175
#define SCD40_TEMP_RAW_OFFSET 100
#define SCD40_TEMP_RAW_SCALE 175
#define SCD40_HUM_RAW_OFFSET 100
#define SCD40_HUM_RAW_SCALE 175

#define SCD40_DATA_SIZE 9
#define SCD40_DATA_BYTES 6
#define SCD40_CRC_BYTES 3

#define SCD40_LOG_FILE "air_quality.log"

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus 1
    int i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }

    // Send Start Periodic Measurement command
    if (i2cWriteByte(i2c_handle, SCD40_START_PERIODIC_MEASUREMENT) < 0) {
        fprintf(stderr, "Failed to send Start Periodic Measurement command\n");
        return 1;
    }

    // Wait at least 1 second before first read attempt
    sleep(1);

    // Poll data-ready flag
    uint8_t data_ready = 0;
    if (i2cReadByte(i2c_handle, SCD40_DATA_READY_FLAG, &data_ready) < 0) {
        fprintf(stderr, "Failed to poll data-ready flag\n");
        return 1;
    }

    // Read data once data-ready flag indicates data is ready
    uint8_t data[SCD40_DATA_SIZE];
    if (data_ready) {
        if (i2cReadBytes(i2c_handle, SCD40_DATA_READ, data, SCD40_DATA_SIZE) < 0) {
            fprintf(stderr, "Failed to read data\n");
            return 1;
        }

        // Verify CRC-8 checksum for each 2-byte word
        uint8_t crc = SCD40_CRC_INIT;
        for (int i = 0; i < SCD40_DATA_BYTES; i += 2) {
            uint16_t word = (data[i] << 8) | data[i + 1];
            crc = crc8(crc, word);
        }
        if (crc != data[SCD40_DATA_BYTES + 1]) {
            fprintf(stderr, "CRC-8 checksum failed\n");
            return 1;
        }

        // Convert CO2, temperature, and humidity
        uint16_t co2_raw = (data[0] << 8) | data[1];
        float co2_ppm = (float)co2_raw / (2^16 - 1) * SCD40_CO2_RAW_SCALE + SCD40_CO2_RAW_OFFSET;
        uint16_t temp_raw = (data[2] << 8) | data[3];
        float temp_c = (float)temp_raw / (2^16 - 1) * SCD40_TEMP_RAW_SCALE + SCD40_TEMP_RAW_OFFSET;
        uint16_t hum_raw = (data[4] << 8) | data[5];
        float hum_pct = (float)hum_raw / (2^16 - 1) * SCD40_HUM_RAW_SCALE + SCD40_HUM_RAW_OFFSET;

        // Log CO2, temperature, and humidity to file
        FILE *log_file = fopen(SCD40_LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return 1;
        }
        fprintf(log_file, "%ld,%.2f,%.2f,%.2f\n", time(NULL), co2_ppm, temp_c, hum_pct);
        fclose(log_file);
    }

    // Send Stop Periodic Measurement command
    if (i2cWriteByte(i2c_handle, SCD40_STOP_PERIODIC_MEASUREMENT) < 0) {
        fprintf(stderr, "Failed to send Stop Periodic Measurement command\n");
        return 1;
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

void sigint_handler(int signal) {
    // Send Stop Periodic Measurement command
    if (i2cWriteByte(i2c_handle, SCD40_STOP_PERIODIC_MEASUREMENT) < 0) {
        fprintf(stderr, "Failed to send Stop Periodic Measurement command\n");
        return 1;
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    fclose(log_file);

    // Exit cleanly
    exit(0);
}

