#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPi.h>

#define SCD40_I2C_ADDR 0x62
#define SCD40_START_PERIODIC_MEASUREMENT 0x21B1
#define SCD40_GET_DATA_READY_STATUS 0xE4B8
#define SCD40_READ_MEASUREMENT 0xEC05
#define SCD40_STOP_PERIODIC_MEASUREMENT 0x3F86

#define CIRCULAR_BUFFER_SIZE 20

struct SCD40_data {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
};

struct SCD40_data data_buffer[CIRCULAR_BUFFER_SIZE];
int data_buffer_index = 0;

void sigint_handler(int signum) {
    printf("Stopping SCD40 sensor...\n");
    pigpio_i2c_write(SCD40_I2C_ADDR, SCD40_STOP_PERIODIC_MEASUREMENT, 0);
    pigpio_i2c_close(SCD40_I2C_ADDR);
    wiringPi_digitalWrite(17, LOW);
    exit(0);
}

int main(void) {
    if (pigpio_start(NULL, NULL) < 0) {
        printf("Failed to start pigpio\n");
        return 1;
    }

    if (pigpio_i2c_open(SCD40_I2C_ADDR) < 0) {
        printf("Failed to open I2C bus\n");
        return 1;
    }

    if (pigpio_i2c_write(SCD40_I2C_ADDR, SCD40_START_PERIODIC_MEASUREMENT, 0) < 0) {
        printf("Failed to start periodic measurement\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        uint8_t data_ready_status;
        if (pigpio_i2c_read(SCD40_I2C_ADDR, SCD40_GET_DATA_READY_STATUS, &data_ready_status, 1) < 0) {
            printf("Failed to read data ready status\n");
            return 1;
        }

        if (data_ready_status & 0x01) {
            uint8_t data[9];
            if (pigpio_i2c_read(SCD40_I2C_ADDR, SCD40_READ_MEASUREMENT, data, 9) < 0) {
                printf("Failed to read measurement data\n");
                return 1;
            }

            uint16_t co2 = (data[0] << 8) | data[1];
            uint16_t temperature = (data[2] << 8) | data[3];
            uint16_t humidity = (data[4] << 8) | data[5];

            if (crc8_checksum(data, 6) != data[6]) {
                printf("Invalid CRC-8 checksum for CO2\n");
                continue;
            }

            if (crc8_checksum(data + 2, 4) != data[7]) {
                printf("Invalid CRC-8 checksum for temperature\n");
                continue;
            }

            if (crc8_checksum(data + 6, 2) != data[8]) {
                printf("Invalid CRC-8 checksum for humidity\n");
                continue;
            }

            data_buffer[data_buffer_index].co2 = co2;
            data_buffer[data_buffer_index].temperature = temperature;
            data_buffer[data_buffer_index].humidity = humidity;
            data_buffer_index = (data_buffer_index + 1) % CIRCULAR_BUFFER_SIZE;

            if (co2 > 1000) {
                wiringPi_digitalWrite(17, HIGH);
            } else {
                wiringPi_digitalWrite(17, LOW);
            }

            printf("CO2: %d ppm, Temperature: %d C, Humidity: %d %%\n", co2, temperature, humidity);
        }

        usleep(5000000);
    }

    return 0;
}

