#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define TMP05_PIN 4
#define TMP05_THRESHOLD 50000
#define TMP05_MIN_TEMP -40
#define TMP05_MAX_TEMP 150
#define TMP05_SAMPLE_RATE 5000000

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open temperature log file
    FILE *temperature_log = fopen("temperature_log.txt", "a");
    if (temperature_log == NULL) {
        fprintf(stderr, "Failed to open temperature log file\n");
        return 1;
    }

    // Set GPIO pin mode
    if (gpioSetMode(TMP05_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin mode\n");
        return 1;
    }

    // Set GPIO pin pull-up
    if (gpioSetPullUpDown(TMP05_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO pin pull-up\n");
        return 1;
    }

    // Set GPIO pin edge detection
    if (gpioSetAlertFunc(TMP05_PIN, PI_RISING_EDGE, NULL) < 0) {
        fprintf(stderr, "Failed to set GPIO pin edge detection\n");
        return 1;
    }

    // Set GPIO pin timeout
    if (gpioSetTimeout(TMP05_PIN, TMP05_THRESHOLD, PI_TIMEOUT_BLOCK) < 0) {
        fprintf(stderr, "Failed to set GPIO pin timeout\n");
        return 1;
    }

    // Set GPIO pin sample rate
    if (gpioSetSampleRate(TMP05_PIN, TMP05_SAMPLE_RATE) < 0) {
        fprintf(stderr, "Failed to set GPIO pin sample rate\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for rising edge
        if (gpioWaitForEdge(TMP05_PIN, PI_RISING_EDGE, TMP05_THRESHOLD) < 0) {
            fprintf(stderr, "Failed to wait for rising edge\n");
            return 1;
        }

        // Measure high pulse width
        uint32_t high_pulse_width = gpioTick();

        // Measure total cycle width
        uint32_t total_cycle_width = gpioTick();

        // Calculate temperature
        int temperature = 4215 - (2143 * high_pulse_width / total_cycle_width);

        // Check for valid temperature range
        if (temperature < TMP05_MIN_TEMP || temperature > TMP05_MAX_TEMP) {
            fprintf(stderr, "Temperature out of range\n");
            return 1;
        }

        // Log temperature reading
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
        fprintf(temperature_log, "%s, %d\n", timestamp, temperature);

        // Check for sensor stuck line condition
        if (total_cycle_width == 0) {
            fprintf(stderr, "Sensor stuck line condition detected\n");
            return 1;
        }
    }

    // Clean up
    gpioTerminate();
    fclose(temperature_log);

    return 0;
}

