#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SHT35_ADDR 0x44
#define SHT35_CMD_MEASURE_HIGH_REPEATABILITY 0x2400
#define SHT35_CMD_READ_MEASUREMENT 0xE000
#define SHT35_CRC_POLYNOMIAL 0x31
#define SHT35_CRC_INITIAL_VALUE 0xFF

#define SHT35_TEMP_MSB_OFFSET 0
#define SHT35_TEMP_LSB_OFFSET 1
#define SHT35_TEMP_CRC_OFFSET 2
#define SHT35_HUMIDITY_MSB_OFFSET 3
#define SHT35_HUMIDITY_LSB_OFFSET 4
#define SHT35_HUMIDITY_CRC_OFFSET 5

#define SHT35_TEMP_RAW_MIN 0x8000
#define SHT35_TEMP_RAW_MAX 0x7FFF
#define SHT35_HUMIDITY_RAW_MIN 0x0000
#define SHT35_HUMIDITY_RAW_MAX 0xFFFF

#define SHT35_TEMP_CONVERSION_FACTOR 175.0
#define SHT35_HUMIDITY_CONVERSION_FACTOR 100.0

#define SHT35_SAMPLING_PERIOD 5000

int main(void) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus 1
    int i2c_handle = i2cOpen(1, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Set up SIGINT/SIGTERM handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open file for logging
    FILE *fp = fopen("environment.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for logging\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if file is empty or does not exist
    if (fseek(fp, 0, SEEK_END) == 0 && ftell(fp) == 0) {
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
    }

    // Main loop
    while (1) {
        // Send measurement command
        uint8_t cmd[2] = {SHT35_CMD_MEASURE_HIGH_REPEATABILITY >> 8, SHT35_CMD_MEASURE_HIGH_REPEATABILITY & 0xFF};
        if (i2cWrite(i2c_handle, cmd, 2) < 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            continue;
        }

        // Wait at least 15 ms before reading measurement
        usleep(15000);

        // Read measurement
        uint8_t data[6];
        if (i2cRead(i2c_handle, data, 6) < 0) {
            fprintf(stderr, "Failed to read measurement\n");
            continue;
        }

        // Validate CRC-8 checksums
        if (!validate_crc8(data, SHT35_CRC_POLYNOMIAL, SHT35_CRC_INITIAL_VALUE)) {
            fprintf(stderr, "Invalid CRC-8 checksum\n");
            continue;
        }

        // Convert raw values to temperature and humidity
        int16_t temp_raw = (data[SHT35_TEMP_MSB_OFFSET] << 8) | data[SHT35_TEMP_LSB_OFFSET];
        int16_t humidity_raw = (data[SHT35_HUMIDITY_MSB_OFFSET] << 8) | data[SHT35_HUMIDITY_LSB_OFFSET];
        float temperature = -45 + SHT35_TEMP_CONVERSION_FACTOR * temp_raw / 65535;
        float humidity = SHT35_HUMIDITY_CONVERSION_FACTOR * humidity_raw / 65535;

        // Log measurement
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,%.2f,%.2f\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, temperature, humidity);

        // Sleep for sampling period
        usleep(SHT35_SAMPLING_PERIOD);
    }

    // Close file and I2C handle
    fclose(fp);
    i2cClose(i2c_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

// Validate CRC-8 checksum
int validate_crc8(uint8_t *data, uint8_t polynomial, uint8_t initial_value) {
    uint8_t crc = initial_value;
    for (int i = 0; i < 2; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc == data[2];
}

// SIGINT/SIGTERM handler
void sigint_handler(int signal) {
    // Close file and I2C handle
    fclose(fp);
    i2cClose(i2c_handle);

    // Terminate pigpio library
    gpioTerminate();

    // Exit program
    exit(0);
}

