        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
    }

    // Main loop
    while (1) {
        // Send measurement command
        uint8_t cmd[2] = {SHT35_CMD_MEASURE_HIGH_REPEATABILITY >> 8, SHT35_CMD_MEASURE_HIGH_REPEATABILITY & 0xFF};
        if (i2cWrite(i2c_handle, cmd, 2) < 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            continue;
        }

        // Wait at least 15 ms before reading measurement
        usleep(15000);

        // Read measurement
        uint8_t data[6];
        if (i2cRead(i2c_handle, data, 6) < 0) {
            fprintf(stderr, "Failed to read measurement\n");
            continue;
        }

        // Validate CRC-8 checksums
        if (!validate_crc8(data, SHT35_CRC_POLYNOMIAL, SHT35_CRC_INITIAL_VALUE)) {
            fprintf(stderr, "Invalid CRC-8 checksum\n");
            continue;
        }

        // Convert raw values to temperature and humidity
        int16_t temp_raw = (data[SHT35_TEMP_MSB_OFFSET] << 8) | data[SHT35_TEMP_LSB_OFFSET];
        int16_t humidity_raw = (data[SHT35_HUMIDITY_MSB_OFFSET] << 8) | data[SHT35_HUMIDITY_LSB_OFFSET];
        float temperature = -45 + SHT35_TEMP_CONVERSION_FACTOR * temp_raw / 65535;
        float humidity = SHT35_HUMIDITY_CONVERSION_FACTOR * humidity_raw / 65535;

        // Log measurement
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d,%.2f,%.2f\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, temperature, humidity);

        // Sleep for sampling period
        usleep(SHT35_SAMPLING_PERIOD);
    }

    // Close file and I2C handle
    fclose(fp);
    i2cClose(i2c_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

// Validate CRC-8 checksum
int validate_crc8(uint8_t *data, uint8_t polynomial, uint8_t initial_value) {
    uint8_t crc = initial_value;
    for (int i = 0; i < 2; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc == data[2];
}

// SIGINT/SIGTERM handler
void sigint_handler(int signal) {
    // Close file and I2C handle
    fclose(fp);
    i2cClose(i2c_handle);

    // Terminate pigpio library
    gpioTerminate();

    // Exit program
    exit(0);
}
