#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CONV_TIME 1000
#define SCALE_FACTOR 1000

#define CRC_POLY 0x31
#define CRC_INIT 0xFF

#define PRESSURE_MSB 0
#define PRESSURE_LSB 1
#define CRC_PRESSURE 2
#define TEMPERATURE_MSB 3
#define TEMPERATURE_LSB 4
#define CRC_TEMPERATURE 5
#define SCALE_FACTOR_1 6
#define SCALE_FACTOR_2 7
#define SCALE_FACTOR_3 8

#define PRESSURE_CMD 0x362F

int main(void) {
    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    int i2c_handle = i2c_open(I2C_BUS, 0, 0, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Set signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open file for logging
    FILE *fp = fopen("airflow.dat", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for logging\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Send command to start continuous measurement
        if (i2c_write(i2c_handle, I2C_ADDR, PRESSURE_CMD, 0) < 0) {
            fprintf(stderr, "Failed to send command to start continuous measurement\n");
            return 1;
        }

        // Wait for conversion time
        usleep(CONV_TIME);

        // Read 9 bytes from I2C bus
        uint8_t data[9];
        if (i2c_read(i2c_handle, I2C_ADDR, data, 9) < 0) {
            fprintf(stderr, "Failed to read data from I2C bus\n");
            return 1;
        }

        // Validate CRC-8 for pressure and temperature raw values
        if (crc8(data, 6, CRC_POLY, CRC_INIT) != data[CRC_PRESSURE]) {
            fprintf(stderr, "Invalid CRC-8 for pressure raw value\n");
            return 1;
        }
        if (crc8(data + 3, 3, CRC_POLY, CRC_INIT) != data[CRC_TEMPERATURE]) {
            fprintf(stderr, "Invalid CRC-8 for temperature raw value\n");
            return 1;
        }

        // Convert pressure and temperature
        float pressure = (data[PRESSURE_MSB] << 8) | data[PRESSURE_LSB];
        pressure /= SCALE_FACTOR;
        pressure -= 1000;
        float temperature = (data[TEMPERATURE_MSB] << 8) | data[TEMPERATURE_LSB];
        temperature /= 200.0;
        temperature -= 45.0;

        // Log pressure and temperature to file
        fwrite(&pressure, sizeof(float), 1, fp);
        fwrite(&temperature, sizeof(float), 1, fp);
    }

    // Close I2C bus
    i2c_close(i2c_handle);

    // Close file
    fclose(fp);

    // Terminate pigpio
    pigpio_stop();

    return 0;
}

void signal_handler(int signal) {
    // Close I2C bus
    i2c_close(i2c_handle);

    // Close file
    fclose(fp);

    // Terminate pigpio
    pigpio_stop();

    exit(0);
}

