#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CONV_TIME 45
#define SCALE_FACTOR 60.0

#define CRC_POLY 0x31
#define CRC_INIT 0xFF

#define LOG_FILE "pressure_log.txt"

int main(void) {
    // Initialize pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C handle
    int i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        pigpio_stop();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pigpio_i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Send continuous measurement command
        uint8_t cmd = 0x36;
        if (pigpio_i2c_write(i2c_handle, &cmd, 1) < 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            break;
        }

        // Wait for conversion time
        usleep(CONV_TIME * 1000);

        // Read 9 bytes (3 words plus 3 CRC bytes)
        uint8_t data[9];
        if (pigpio_i2c_read(i2c_handle, data, 9) < 0) {
            fprintf(stderr, "Failed to read data\n");
            break;
