        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_PIN);
        exit(1);
    }
    if (gpioPWM(FAN_PIN, FAN_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", FAN_PIN);
        exit(1);
    }
}

