    FILE *log_file = fopen(FLOW_LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", FLOW_LOG_FILE);
        exit(1);
    }
    fclose(log_file);
}

static void log_flow(uint16_t flow_reading) {
    FILE *log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", FLOW_LOG_FILE);
        return;
    }
