#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5D
#define WHO_AM_I_REG 0x0F
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Initialize the I2C bus
    int i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", pigpio_i2c_error(i2c_handle));
        return 1;
    }

    // Check the WHO_AM_I register
    uint8_t who_am_i;
    if (pigpio_i2c_read(i2c_handle, WHO_AM_I_REG, &who_am_i, 1) != 1) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", pigpio_i2c_error(i2c_handle));
        return 1;
    }
    if (who_am_i != 0xB1) {
        fprintf(stderr, "Invalid WHO_AM_I register value: 0x%02X\n", who_am_i);
        return 1;
    }

    // Configure the CTRL_REG1 register
    uint8_t ctrl_reg1 = 0xB0;
    if (pigpio_i2c_write(i2c_handle, CTRL_REG1, &ctrl_reg1, 1) != 1) {
        fprintf(stderr, "Error writing CTRL_REG1 register: %s\n", pigpio_i2c_error(i2c_handle));
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("environmental_data.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Set up the signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    while (running) {
        // Read the pressure and temperature
        int32_t pressure;
        int16_t temperature;
        if (pigpio_i2c_read(i2c_handle, PRESS_OUT_XL, &pressure, 3) != 3) {
            fprintf(stderr, "Error reading pressure: %s\n", pigpio_i2c_error(i2c_handle));
            continue;
        }
        if (pigpio_i2c_read(i2c_handle, TEMP_OUT_L, &temperature, 2) != 2) {
            fprintf(stderr, "Error reading temperature: %s\n", pigpio_i2c_error(i2c_handle));
            continue;
        }

        // Convert the pressure and temperature
        pressure /= 4096.0;
        temperature = 42.5 + temperature / 480.0;

        // Log the data
        time_t now = time(NULL);
        struct tm *tm = localtime_r(&now, &tm);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %f hPa, Temperature: %f °C\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec,
                pressure, temperature);
        fflush(log_file);

        // Delay for 1 second
        gpioDelay(1000);
    }

    // Clean up
    pigpio_i2c_close(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

