#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define STLM75_ADDR 0x48
#define STLM75_TEMP_REG 0x00
#define STLM75_TEMP_RES 9
#define STLM75_TEMP_MAX 28.0

#define LED_PIN 17

#define BUF_SIZE 10

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus 1
    int i2c_handle = i2cOpen(1, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Set up LED pin
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    // Set up circular buffer
    int buf[BUF_SIZE];
    int buf_idx = 0;

    // Main loop
    while (1) {
        // Read temperature
        uint16_t temp_raw = i2cReadWordData(i2c_handle, STLM75_TEMP_REG);
        if (temp_raw < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        // Swap bytes and convert to Celsius
        int16_t temp = (temp_raw >> 8) | (temp_raw << 8);
        temp = (temp >> 7) / 2;

        // Add to circular buffer
        buf[buf_idx] = temp;
        buf_idx = (buf_idx + 1) % BUF_SIZE;

        // Compute running average
        int sum = 0;
        for (int i = 0; i < BUF_SIZE; i++) {
            sum += buf[i];
        }
        int avg = sum / BUF_SIZE;

        // Turn on LED if average temperature exceeds 28.0 °C
        if (avg > STLM75_TEMP_MAX) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum) {
    // Turn off LED
    gpioWrite(LED_PIN, 0);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Exit program
    exit(0);
}

void sigterm_handler(int signum) {
    // Turn off LED
    gpioWrite(LED_PIN, 0);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Exit program
    exit(0);
}

