#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <pigpio.h>
#include <crc8.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CONT_MEAS_CMD 0x3615
#define CONV_TIME_MS 45
#define CRC_POLY 0x31
#define CRC_INIT 0xFF

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Send continuous measurement command
    uint8_t cmd[2] = {CONT_MEAS_CMD >> 8, CONT_MEAS_CMD & 0xFF};
    if (i2cWrite(i2c_handle, cmd, 2) < 0) {
        fprintf(stderr, "Failed to send continuous measurement command\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for conversion
    usleep(CONV_TIME_MS * 1000);

    // Read 9 bytes containing pressure, temperature, and scale factors
    uint8_t data[9];
    if (i2cRead(i2c_handle, data, 9) < 0) {
        fprintf(stderr, "Failed to read data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Validate CRC-8 on each 3-byte data word
    for (int i = 0; i < 3; i++) {
        uint8_t crc = crc8(data + i * 3, 3, CRC_POLY, CRC_INIT);
        if (crc != data[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on data word %d\n", i);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }
    }

    // Convert raw values using scale factors
    uint32_t pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    uint16_t temperature = (data[3] << 8) | data[4];
    float scale_factor_pressure = (data[5] << 8) | data[6];
    float scale_factor_temperature = (data[7] << 8) | data[8];
    float pressure_scaled = pressure / scale_factor_pressure;
    float temperature_scaled = temperature / 200.0;

    // Log results to stdout
    printf("Pressure: %f Pa, Temperature: %f C\n", pressure_scaled, temperature_scaled);

    // Close I2C handle and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

