#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x40
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define HUMIDITY_REG 0x01
#define DELAY_MS 20

int main(void) {
    int fd;
    uint8_t config_val = 0x00;
    uint16_t temp_raw, humidity_raw;
    float temp, humidity;

    // Open I2C device
    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set configuration register to enable combined temperature-and-humidity measurement
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }
    if (write(fd, &config_val, 1) < 0) {
        perror("Failed to write to configuration register");
        close(fd);
        return 1;
    }

    // Set up signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        // Write temperature register pointer to sensor
        if (write(fd, &TEMP_REG, 1) < 0) {
            perror("Failed to write temperature register pointer");
            continue;
        }

        // Wait for conversion to complete
        usleep(DELAY_MS * 1000);

        // Read 4 bytes (2 bytes temperature followed by 2 bytes humidity) in a single I2C read transaction
        if (read(fd, &temp_raw, 2) < 0) {
            perror("Failed to read temperature");
            continue;
        }
        if (read(fd, &humidity_raw, 2) < 0) {
            perror("Failed to read humidity");
            continue;
        }

        // Convert raw values to temperature and humidity
        temp = (temp_raw / 65536.0) * 165.0 - 40.0;
        humidity = (humidity_raw / 65536.0) * 100.0;

        // Print readings to console
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, humidity);

        // Wait for next reading
        sleep(5);
    }

    // Close I2C device
    close(fd);

    return 0;
}

void sigint_handler(int signum) {
    printf("Caught signal %d, exiting...\n", signum);
    close(fd);
    exit(0);
}

