        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = pigpio_i2c_open(I2C_BUS, I2C_SDA, I2C_SCL, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Set I2C slave address
    ret = pigpio_i2c_set_slave_address(i2c_fd, I2C_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return 1;
    }

    // Set I2C read timeout
    ret = pigpio_i2c_set_read_timeout(i2c_fd, 1000);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C read timeout\n");
        return 1;
    }

    // Set I2C write timeout
    ret = pigpio_i2c_set_write_timeout(i2c_fd, 1000);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C write timeout\n");
        return 1;
    }

    // Set signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        // Read temperature from sensor
        ret = pigpio_i2c_read(i2c_fd, data, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to read temperature from sensor\n");
            return 1;
        }

        // Convert temperature data to float
        temperature = (data[0] << 8) | data[1];
        temperature = temperature / 100.0;

        // Print temperature to console
        printf("Temperature: %.2f\n", temperature);

        // Sleep for TEMP_READ_INTERVAL seconds
        sleep(TEMP_READ_INTERVAL);
    }

    // Clean up resources
    pigpio_i2c_close(i2c_fd);
    pigpio_stop();

    return 0;
}

void signal_handler(int signal) {
    // Clean up resources
    pigpio_i2c_close(i2c_fd);
    pigpio_stop();

    // Exit program
    exit(0);
}
```
This code uses the pigpio library to communicate with the Si7051 sensor over I2C bus 1 (GPIO 2/3 for SDA/SCL) at its default 7-bit address 0x40. It reads the temperature data from the sensor every 5 seconds and prints it to the console. The code also implements robust error handling for I2C communication failures, including sensor-absent conditions, bus errors, and read/write timeouts, and ensures clean resource release on all exit paths, including graceful shutdown on SIGINT or SIGTERM.

