#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x63

#define CMD_READ_CALIBRATION 0x50
#define CMD_TRIGGER_MEASUREMENT 0x40
#define CMD_READ_MEASUREMENT 0x41

#define SCALE_FACTOR_LUT 0.000001
#define SCALE_FACTOR_H 0.000001
#define SCALE_FACTOR_P 0.000001

#define TEMPERATURE_OFFSET 0.0
#define PRESSURE_OFFSET 0.0

#define TEMPERATURE_SCALE 1.0
#define PRESSURE_SCALE 1.0

#define TIMEOUT 1000

int main(void) {
    int i2c_handle;
    int ret;
    uint8_t buf[6];
    uint8_t calibration[8];
    double temperature, pressure;
    char timestamp[20];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Read calibration coefficients
    ret = i2cRead(i2c_handle, CMD_READ_CALIBRATION, calibration, 8, TIMEOUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        return 1;
    }

    // Compute scaling factors
    SCALE_FACTOR_LUT = calibration[0] + calibration[1] * 256;
    SCALE_FACTOR_H = calibration[2] + calibration[3] * 256;
    SCALE_FACTOR_P = calibration[4] + calibration[5] * 256;

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Trigger measurement
        ret = i2cWrite(i2c_handle, CMD_TRIGGER_MEASUREMENT, NULL, 0, TIMEOUT);
        if (ret < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            return 1;
        }

        // Wait for measurement to complete
        usleep(7000);

        // Read measurement
        ret = i2cRead(i2c_handle, CMD_READ_MEASUREMENT, buf, 6, TIMEOUT);
        if (ret < 0) {
            fprintf(stderr, "Failed to read measurement\n");
            return 1;
        }

        // Check for sensor-absent condition
        if (buf[0] == 0xFF && buf[1] == 0xFF && buf[2] == 0xFF && buf[3] == 0xFF && buf[4] == 0xFF && buf[5] == 0xFF) {
            fprintf(stderr, "Sensor is absent\n");
            return 1;
        }

        // Convert raw values to Celsius and Pascals
        temperature = (buf[0] + buf[1] * 256) * SCALE_FACTOR_LUT + TEMPERATURE_OFFSET;
        pressure = (buf[2] + buf[3] * 256 + buf[4] * 65536 + buf[5] * 16777216) * SCALE_FACTOR_P + PRESSURE_OFFSET;

        // Log reading
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);

        // Wait for next measurement
        sleep(5);
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Clean up
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum) {
    // Close I2C bus
    i2cClose(i2c_handle);

    // Clean up
    gpioTerminate();

    exit(0);
}

void sigterm_handler(int signum) {
    // Close I2C bus
    i2cClose(i2c_handle);

    // Clean up
    gpioTerminate();

    exit(0);
}

