#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <time.h>

#define MLX90819_ADDR 0x60
#define MLX90819_MSB_REG 0xAA
#define MLX90819_LSB_REG 0xAB

#define I2C_DEV "/dev/i2c-1"

int main(void) {
    int fd;
    uint16_t raw_pressure;
    float pressure;
    struct timespec ts;

    // Open I2C device
    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Set I2C frequency
    if (ioctl(fd, I2C_SET_FREQ, 100000) < 0) {
        perror("Failed to set I2C frequency");
        close(fd);
        return 1;
    }

    // Set up SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Trigger measurement
        if (write(fd, MLX90819_MSB_REG, 1) < 0) {
            perror("Failed to trigger measurement");
            close(fd);
            return 1;
        }

        // Read raw pressure value
        if (read(fd, &raw_pressure, 2) < 0) {
            perror("Failed to read raw pressure value");
            close(fd);
            return 1;
        }

        // Convert raw value to kPa
        pressure = (float)raw_pressure * 0.1;

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);

        // Print pressure value and timestamp
        printf("%ld.%ld: %f kPa\n", ts.tv_sec, ts.tv_nsec, pressure);

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C device
    close(fd);

    return 0;
}

void sigint_handler(int signum) {
    printf("Received signal %d, exiting...\n", signum);
    exit(0);
}

