#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define PRESSURE_REG 0x00
#define SAFE_PRESSURE_MIN 200
#define SAFE_PRESSURE_MAX 250

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("pressure_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if file is new
    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }

    // Read pressure register every second
    while (1) {
        // Read pressure register
        uint16_t pressure_raw;
        if (i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, &pressure_raw, 2) != 2) {
            fprintf(stderr, "Failed to read pressure register\n");
            i2cClose(i2c_handle);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        // Convert raw pressure to kPa
        float pressure_kPa = pressure_raw * 0.01;

        // Check if pressure is within safe range
        if (pressure_kPa < SAFE_PRESSURE_MIN || pressure_kPa > SAFE_PRESSURE_MAX) {
            fprintf(stderr, "Warning: pressure outside safe range (%f kPa)\n", pressure_kPa);
        }

        // Write pressure to log file
        time_t timestamp = time(NULL);
        fprintf(log_file, "%ld,%.2f\n", timestamp, pressure_kPa);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

