#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x27
#define I2C_DELAY 40
#define LOG_FILE "environmental_data.log"
#define LOG_SIZE 1024 * 1024

int main(void) {
    int fd;
    int i2c_fd;
    int ret;
    uint8_t data[4];
    uint16_t raw_T, raw_H;
    float temperature, humidity;
    char timestamp[20];

    // Open the I2C bus
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDR, I2C_DELAY);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Open the log file
    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        perror("Failed to open log file");
        return 1;
    }

    // Set the log file size limit
    ret = ftruncate(fd, LOG_SIZE);
    if (ret < 0) {
        perror("Failed to set log file size limit");
        return 1;
    }

    // Main loop
    while (1) {
        // Trigger a measurement
        ret = i2c_write(i2c_fd, 0x00);
        if (ret < 0) {
            perror("Failed to trigger measurement");
            return 1;
        }

        // Wait for the measurement to complete
        usleep(I2C_DELAY * 1000);

        // Read the measurement data
        ret = i2c_read(i2c_fd, data, 4);
        if (ret < 0) {
            perror("Failed to read measurement data");
            return 1;
        }

        // Validate the sensor status bits
        if ((data[0] & 0xC0) != 0x00) {
            fprintf(stderr, "Invalid sensor status bits: 0x%02X\n", data[0]);
            return 1;
        }

        // Convert the raw values
        raw_T = (data[0] << 8) | data[1];
        raw_H = (data[2] << 8) | data[3];
        temperature = raw_T * 165.0 / 16383.0 - 40.0;
        humidity = raw_H * 100.0 / 16383.0;

        // Log the measurement
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
        fprintf(fd, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    i2c_close(i2c_fd);
    close(fd);

    return 0;
}

