#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define TICK_TIME 3
#define SYNC_PULSE_WIDTH 56
#define STATUS_NIBBLE_WIDTH 3
#define DATA_NIBBLE_WIDTH 3
#define CHECKSUM_NIBBLE_WIDTH 3
#define MIN_PULSE_WIDTH 12
#define MAX_PULSE_WIDTH 271
#define SCALE 0.001220703125
#define OFFSET -100000

#define SENT_SYNC_PULSE 0x01
#define SENT_STATUS_NIBBLE 0x02
#define SENT_DATA_NIBBLE 0x04
#define SENT_CHECKSUM_NIBBLE 0x08

#define SENT_STATUS_OK 0x00
#define SENT_STATUS_ERROR 0x01

#define SENT_CHECKSUM_ERROR 0x01

#define SENT_TIMEOUT 0x02
#define SENT_BUS_ERROR 0x04

#define SENT_LOG_FILE "pressure_log.txt"

typedef struct {
    uint8_t status;
    uint16_t data;
    uint8_t checksum;
} sent_data_t;

void sent_init(void) {
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
}

void sent_deinit(void) {
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
}

void sent_read(sent_data_t *data) {
    uint8_t sync_pulse = 0;
    uint8_t status_nibble = 0;
    uint16_t data_nibbles = 0;
    uint8_t checksum_nibble = 0;
    uint8_t checksum = 0;

    // Wait for synchronization pulse
    while (gpioRead(GPIO_PIN) == 0) {
        usleep(TICK_TIME);
    }

    // Read synchronization pulse
    while (gpioRead(GPIO_PIN) == 1) {
        usleep(TICK_TIME);
        sync_pulse++;
        if (sync_pulse >= SYNC_PULSE_WIDTH) {
            break;
        }
    }

    // Read status nibble
    while (gpioRead(GPIO_PIN) == 0) {
        usleep(TICK_TIME);
    }

    while (gpioRead(GPIO_PIN) == 1) {
        usleep(TICK_TIME);
        status_nibble++;
        if (status_nibble >= STATUS_NIBBLE_WIDTH) {
            break;
        }
    }

    // Read data nibbles
    while (gpioRead(GPIO_PIN) == 0) {
        usleep(TICK_TIME);
    }

    while (gpioRead(GPIO_PIN) == 1) {
        usleep(TICK_TIME);
        data_nibbles++;
        if (data_nibbles >= DATA_NIBBLE_WIDTH) {
            break;
        }
    }

    // Read checksum nibble
    while (gpioRead(GPIO_PIN) == 0) {
        usleep(TICK_TIME);
    }

    while (gpioRead(GPIO_PIN) == 1) {
        usleep(TICK_TIME);
        checksum_nibble++;
        if (checksum_nibble >= CHECKSUM_NIBBLE_WIDTH) {
            break;
        }
    }

    // Calculate checksum
    checksum = (sync_pulse + status_nibble + data_nibbles + checksum_nibble) % 16;

    // Check checksum
    if (checksum != checksum_nibble) {
        data->status = SENT_STATUS_ERROR;
        data->data = 0;
        data->checksum = 0;
        return;
    }

    // Check status
    if (status_nibble != SENT_STATUS_OK) {
        data->status = SENT_STATUS_ERROR;
        data->data = 0;
        data->checksum = 0;
        return;
    }

    // Check pulse width
    if (sync_pulse < MIN_PULSE_WIDTH || sync_pulse > MAX_PULSE_WIDTH) {
        data->status = SENT_BUS_ERROR;
        data->data = 0;
        data->checksum = 0;
        return;
    }

    // Convert data to pressure
    data->data = (data_nibbles << 4) | (data_nibbles >> 8);
    data->data = (data->data * SCALE) + OFFSET;

    // Set status and checksum
    data->status = SENT_STATUS_OK;
    data->checksum = checksum;
}

void sent_log(sent_data_t *data) {
    FILE *fp;
    char buf[128];
    time_t t;
    struct tm *tm;

    // Open log file
    fp = fopen(SENT_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    // Get current time
    t = time(NULL);
    tm = localtime(&t);

    // Format log message
    snprintf(buf, sizeof(buf), "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %d.%02d Pa\n",
             tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
             tm->tm_hour, tm->tm_min, tm->tm_sec,
             data->data / 100, data->data % 100);

    // Write log message to file
    fprintf(fp, buf);

    // Close log file
    fclose(fp);
}

void sent_error(sent_data_t *data) {
    fprintf(stderr, "Error reading pressure data: %s\n",
            data->status == SENT_STATUS_ERROR ? "status error" :
            data->status == SENT_BUS_ERROR ? "bus error" :
            data->status == SENT_TIMEOUT ? "timeout" : "unknown error");
}

int main(void) {
    sent_data_t data;

    // Initialize GPIO
    sent_init();

    // Read pressure data
    sent_read(&data);

    // Check for errors
    if (data.status != SENT_STATUS_OK) {
        sent_error(&data);
        return 1;
    }

    // Log pressure data
    sent_log(&data);

    // Deinitialize GPIO
    sent_deinit();

    return 0;
}

