        if (data_nibbles >= DATA_NIBBLE_WIDTH) {
            break;
        }
    }

    // Read checksum nibble
    while (gpioRead(GPIO_PIN) == 0) {
        usleep(TICK_TIME);
    }

    while (gpioRead(GPIO_PIN) == 1) {
        usleep(TICK_TIME);
        checksum_nibble++;
        if (checksum_nibble >= CHECKSUM_NIBBLE_WIDTH) {
            break;
        }
    }

    // Calculate checksum
    checksum = (sync_pulse + status_nibble + data_nibbles + checksum_nibble) % 16;

    // Check checksum
    if (checksum != checksum_nibble) {
        data->status = SENT_STATUS_ERROR;
        data->data = 0;
        data->checksum = 0;
        return;
    }

    // Check status
    if (status_nibble != SENT_STATUS_OK) {
        data->status = SENT_STATUS_ERROR;
        data->data = 0;
        data->checksum = 0;
        return;
    }

    // Check pulse width
    if (sync_pulse < MIN_PULSE_WIDTH || sync_pulse > MAX_PULSE_WIDTH) {
        data->status = SENT_BUS_ERROR;
        data->data = 0;
        data->checksum = 0;
        return;
    }

    // Convert data to pressure
    data->data = (data_nibbles << 4) | (data_nibbles >> 8);
    data->data = (data->data * SCALE) + OFFSET;

    // Set status and checksum
    data->status = SENT_STATUS_OK;
    data->checksum = checksum;
}

void sent_log(sent_data_t *data) {
    FILE *fp;
    char buf[128];
    time_t t;
    struct tm *tm;

    // Open log file
    fp = fopen(SENT_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    // Get current time
    t = time(NULL);
    tm = localtime(&t);

    // Format log message
    snprintf(buf, sizeof(buf), "%04d-%02d-%02d %02d:%02d:%02d, Pressure: %d.%02d Pa\n",
             tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
             tm->tm_hour, tm->tm_min, tm->tm_sec,
             data->data / 100, data->data % 100);

    // Write log message to file
    fprintf(fp, buf);

    // Close log file
    fclose(fp);
}

void sent_error(sent_data_t *data) {
    fprintf(stderr, "Error reading pressure data: %s\n",
            data->status == SENT_STATUS_ERROR ? "status error" :
            data->status == SENT_BUS_ERROR ? "bus error" :
            data->status == SENT_TIMEOUT ? "timeout" : "unknown error");
}

int main(void) {
    sent_data_t data;

    // Initialize GPIO
    sent_init();

    // Read pressure data
    sent_read(&data);

    // Check for errors
    if (data.status != SENT_STATUS_OK) {
        sent_error(&data);
        return 1;
    }

    // Log pressure data
    sent_log(&data);

    // Deinitialize GPIO
    sent_deinit();

    return 0;
}
```
This code uses the pigpio library to read pressure data from a Melexis MLX90824 SENT pressure sensor connected to GPIO 4 (BCM) on a Raspberry Pi 3 Model B+. The SENT protocol is implemented with a tick time of 3 us, a synchronization pulse of 56 ticks, followed by a status nibble, 3 data nibbles, and a checksum nibble. The checksum is validated as the sum of the nibbles modulo 16, and the 12-bit raw value is converted to pressure using the linear transfer function raw * scale + offset. The code detects sensor-absent (timeout) and bus-error (checksum or pulse-width) conditions, and logs errors to stderr without crashing. The pressure readings are logged to a file named "pressure_log.txt" in the format "YYYY-MM-DD HH:MM:SS, Pressure: XXXX.XX Pa". The code also handles SIGINT and SIGTERM for clean resource release.

