static void sigint_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    if (temp_file) {
        fclose(temp_file);
    }
    if (i2c_handle) {
        pigpio_i2c_close(i2c_handle);
    }
    exit(0);
}

int main(void) {
    // Set up signal handling
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open the I2C bus
    i2c_handle = pigpio_i2c_open(I2C_BUS);
    if (i2c_handle < 0) {
        printf("Failed to open I2C bus %d\n", I2C_BUS);
        return 1;
    }

    // Verify the device ID
    uint16_t device_id;
    if (pigpio_i2c_read_reg_word(i2c_handle, I2C_ADDR, DEVICE_ID_REG, &device_id) < 0) {
        printf("Failed to read device ID\n");
        return 1;
    }
    if (device_id != DEVICE_ID) {
        printf("Invalid device ID: 0x%04x\n", device_id);
        return 1;
    }

    // Open the temperature file
    temp_file = fopen(TEMP_FILE, "a");
    if (!temp_file) {
        printf("Failed to open temperature file\n");
        return 1;
    }

    // Read the temperature every 60 seconds
    while (1) {
        int16_t temp;
        if (pigpio_i2c_read_reg_word(i2c_handle, I2C_ADDR, TEMP_REG, &temp) < 0) {
            printf("Failed to read temperature\n");
            return 1;
        }
        float temperature = (float)temp / 128.0;
        fwrite(&temperature, sizeof(float), 1, temp_file);
        sleep(60);
    }

    return 0;
}

