#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SHT40_ADDR 0x44
#define SHT40_CMD_HIGH_PRECISION 0xFD
#define SHT40_TEMP_OFFSET -45
#define SHT40_TEMP_SCALE 175
#define SHT40_HUM_OFFSET -6
#define SHT40_HUM_SCALE 125

#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

int main(void) {
    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus 1
    int i2c_handle = pigpio_i2c_open(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        pigpio_stop();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open log file
    FILE *log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pigpio_i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    // Main loop
    while (1) {
        // Send high-precision measurement command
        uint8_t cmd = SHT40_CMD_HIGH_PRECISION;
        if (pigpio_i2c_write(i2c_handle, &cmd, 1) < 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            pigpio_i2c_close(i2c_handle);
            pigpio_stop();
            return 1;
        }

        // Wait for conversion
        usleep(8500);

        // Read 6 bytes: 2 bytes temperature, 1 CRC byte, 2 bytes humidity, 1 CRC byte
        uint8_t data[6];
        if (pigpio_i2c_read(i2c_handle, data, 6) < 0) {
            fprintf(stderr, "Failed to read data\n");
            pigpio_i2c_close(i2c_handle);
            pigpio_stop();
            return 1;
        }

        // Validate CRC-8 checksums
        uint8_t crc_temp = crc8(data, 2, CRC8_POLY, CRC8_INIT);
        uint8_t crc_hum = crc8(data + 3, 2, CRC8_POLY, CRC8_INIT);
        if (crc_temp != data[2] || crc_hum != data[5]) {
            fprintf(stderr, "Invalid CRC-8 checksum\n");
            pigpio_i2c_close(i2c_handle);
            pigpio_stop();
            return 1;
        }

        // Convert raw values
        int16_t raw_temp = (data[0] << 8) | data[1];
        int16_t raw_hum = (data[3] << 8) | data[4];
        float temperature = SHT40_TEMP_OFFSET + SHT40_TEMP_SCALE * (raw_temp / 65535.0);
        float humidity = SHT40_HUM_OFFSET + SHT40_HUM_SCALE * (raw_hum / 65535.0);

        // Log data
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%02d:%02d:%02d, %0.1f°C, %0.1f%%\n", tm->tm_hour, tm->tm_min, tm->tm_sec, temperature, humidity);
        fflush(log_file);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    fclose(log_file);
    pigpio_i2c_close(i2c_handle);
    pigpio_stop();

    return 0;
}

void sigint_handler(int signum) {
    // Close I2C handle
    pigpio_i2c_close(i2c_handle);

    // Terminate pigpio
    pigpio_stop();

    // Close log file
    fclose(log_file);

    // Exit
    exit(0);
}

