#define TMP117_TEMP_RES 0.0078125
#define BUFFER_SIZE 100

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(int argc, char **argv) {
    int i2c_handle;
    int ret;
    uint8_t buffer[BUFFER_SIZE];
    uint8_t temp_reg[2];
    float temp;
    FILE *fp;

    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C handle
    i2c_handle = pigpio_i2c_open(1, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    // Set up signal handler for SIGINT/SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open file for logging
    fp = fopen("temperature_log.dat", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for logging\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Read temperature register
        ret = pigpio_i2c_read(i2c_handle, TMP117_TEMP_REG, temp_reg, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to read temperature register\n");
            continue;
        }

        // Convert temperature
        temp = (temp_reg[0] << 8) | temp_reg[1];
        temp = temp * TMP117_TEMP_RES;

        // Add to buffer
        buffer[BUFFER_SIZE - 1] = temp;

        // Write buffer to file
        fwrite(buffer, sizeof(float), BUFFER_SIZE, fp);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Flush buffer to file
    fflush(fp);

    // Close file
    fclose(fp);

    // Close I2C handle
    pigpio_i2c_close(i2c_handle);

    // Close pigpio
    pigpio_stop();

    return 0;
}

