#define SHTC3_CMD_NORMAL_POWER 0x7866
#define SHTC3_CONV_TIME 12400
#define SHTC3_TEMP_MSB_REG 0x00
#define SHTC3_TEMP_LSB_REG 0x01
#define SHTC3_TEMP_CRC_REG 0x02
#define SHTC3_HUM_MSB_REG 0x03
#define SHTC3_HUM_LSB_REG 0x04
#define SHTC3_HUM_CRC_REG 0x05

#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

#define TEMP_MIN -40
#define TEMP_MAX 125
#define RH_MIN 0
#define RH_MAX 100

int main(void)
{
    int i2c_handle;
    int ret;
    uint8_t buf[6];
    uint16_t temp, hum;
    uint8_t crc;
    char log_file[256];
    FILE *fp;
    struct tm *tm;
    time_t t;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus 1
    i2c_handle = i2cOpen(1, 0, 0, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }

    // Set I2C clock stretching to disabled
    ret = i2cSetClockStretch(i2c_handle, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C clock stretching\n");
        return 1;
    }

    // Set I2C slave address to 0x70
    ret = i2cSetSlaveAddress(i2c_handle, SHTC3_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return 1;
    }

    // Set I2C frequency to 100 kHz
    ret = i2cSetFrequency(i2c_handle, 100000);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C frequency\n");
        return 1;
    }

    // Set I2C timeout to 1 second
    ret = i2cSetTimeout(i2c_handle, 1000);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C timeout\n");
        return 1;
    }

    // Set I2C retry count to 3
    ret = i2cSetRetryCount(i2c_handle, 3);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C retry count\n");
        return 1;
    }

    // Set I2C delay to 100 us
    ret = i2cSetDelay(i2c_handle, 100);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C delay\n");
        return 1;
    }

    // Set I2C pull-up to enabled
    ret = i2cSetPullup(i2c_handle, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C pull-up\n");
        return 1;
    }

    // Set I2C clock to 1.8 V
    ret = i2cSetClock(i2c_handle, 1800);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C clock\n");
        return 1;
    }

    // Set I2C data to 1.8 V
    ret = i2cSetData(i2c_handle, 1800);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C data\n");
        return 1;
    }

    // Set I2C mode to master
    ret = i2cSetMode(i2c_handle, I2C_MODE_MASTER);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C mode\n");
        return 1;
    }

    // Set I2C address to 0x70
    ret = i2cSetAddress(i2c_handle, SHTC3_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        return 1;
    }

    // Set I2C command to normal power
    ret = i2cSetCommand(i2c_handle, SHTC3_CMD_NORMAL_POWER);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C command\n");
