#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define I2C_SPEED 100000

#define FIELD_GAUSS_SCALE 0.1
#define TEMP_CELSIUS_SCALE 0.01
#define TEMP_OFFSET -25.0

#define LOG_FILE "mag_temp_log.csv"
#define LOG_HEADER "time,field_gauss,temp_celsius\n"

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    int i2c_handle;
    int ret;
    uint8_t reg_addr = 0x00;
    uint8_t reg_data[2];
    float field_gauss, temp_celsius;
    char log_line[100];
    FILE *log_file;

    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR, I2C_SPEED);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Write header row if file is new
    if (fseek(log_file, 0, SEEK_END) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, LOG_HEADER);
    }

    // Main loop
    while (running) {
        // Read sensor data
        ret = pigpio_i2c_read(i2c_handle, reg_addr, reg_data, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }

        // Convert raw values to field_gauss and temp_celsius
        field_gauss = reg_data[0] * FIELD_GAUSS_SCALE;
        temp_celsius = (reg_data[1] * TEMP_CELSIUS_SCALE) + TEMP_OFFSET;

        // Log data to file
        snprintf(log_line, sizeof(log_line), "%ld,%f,%f\n", time(NULL), field_gauss, temp_celsius);
        fprintf(log_file, log_line);

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C bus
    pigpio_i2c_close(i2c_handle);

    // Close log file
    fclose(log_file);

    // Close pigpio
    pigpio_stop();

    return 0;
}

