#define I2C_BUS 1
#define I2C_ADDR 0x49
#define FLOW_REG 0x00
#define TEMP_REG 0x02

#define SLPM_CONST 0.8
#define TEMP_CONST 80.0

#define FLOW_LOG "flow_log.txt"

int main(void) {
    // Initialize pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C handle
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(FLOW_LOG, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Read flow and temperature data
    uint16_t flow_raw, temp_raw;
    int ret = i2cReadDevice(i2c_handle, FLOW_REG, &flow_raw, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read flow data\n");
        return 1;
    }
    ret = i2cReadDevice(i2c_handle, TEMP_REG, &temp_raw, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read temperature data\n");
        return 1;
    }

    // Convert raw data to SLPM and Celsius
    float flow_slpm = ((flow_raw / 16384.0) - 0.1) / SLPM_CONST * 25.0;
    float temp_celsius = ((temp_raw / 4096.0) - 0.1) / TEMP_CONST - 40.0;

    // Log data to file
    fprintf(log_file, "%f %f\n", flow_slpm, temp_celsius);

    // Close I2C handle and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Clean up pigpio library
    pigpio_stop();

    return 0;
}

void handle_sigint(int signum) {
    // Close I2C handle and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Clean up pigpio library
    pigpio_stop();

    exit(0);
}

void handle_sigterm(int signum) {
    // Close I2C handle and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Clean up pigpio library
    pigpio_stop();

    exit(0);
}

