        fprintf(fp, "%s, %d, %d\n", timestamp, temperature, humidity);

        // Wait for next sample
        gpioDelay(2000);
    }

    // Clean up
    gpioTerminate();
    fclose(fp);

    return 0;
}

void signal_handler(int signal) {
    // Release GPIO resources
    gpioTerminate();

    // Close file handles
    fclose(fp);

    // Exit
    exit(0);
