#include <pigpio.h>

#define SHT31D_ADDR 0x44
#define SHT31D_CMD_MEASURE_SINGLE_SHOT 0x2C06
#define SHT31D_CMD_READ_STATUS 0xF32D
#define SHT31D_CMD_CLEAR_STATUS 0x3041
#define SHT31D_CMD_SOFT_RESET 0x30A2
#define SHT31D_CMD_HEATER_ENABLE 0x306D
#define SHT31D_CMD_HEATER_DISABLE 0x3066

#define SHT31D_TEMP_RAW_HIGH 0x00
#define SHT31D_TEMP_RAW_LOW 0x01
#define SHT31D_HUMIDITY_RAW_HIGH 0x03
#define SHT31D_HUMIDITY_RAW_LOW 0x04

#define SHT31D_CRC_POLYNOMIAL 0x31
#define SHT31D_CRC_INITIAL_VALUE 0xFF

#define SHT31D_TEMP_MIN -45
#define SHT31D_TEMP_MAX 175
#define SHT31D_HUMIDITY_MIN 0
#define SHT31D_HUMIDITY_MAX 100

#define SHT31D_RETRY_COUNT 3

int main(void) {
  // Initialize pigpio
  if (gpioInitialise() < 0) {
    fprintf(stderr, "Failed to initialize pigpio\n");
    return 1;
  }

  // Open I2C bus 1
  int i2c_handle = i2cOpen(1, 0, 0, 0);
  if (i2c_handle < 0) {
    fprintf(stderr, "Failed to open I2C bus 1\n");
    return 1;
  }

  // Open log file
  FILE *log_file = fopen("sht31d_data.log", "a");
  if (log_file == NULL) {
    fprintf(stderr, "Failed to open log file\n");
    return 1;
  }

  // Set up signal handlers
  signal(SIGINT, sigint_handler);
  signal(SIGTERM, sigterm_handler);

  // Main loop
  while (1) {
    // Send measurement command
    uint8_t cmd_buf[2] = {SHT31D_CMD_MEASURE_SINGLE_SHOT, 0x00};
    if (i2cWrite(i2c_handle, SHT31D_ADDR, cmd_buf, 2) < 0) {
      fprintf(stderr, "Failed to send measurement command\n");
      return 1;
    }

    // Wait at least 15 ms
    usleep(15000);

    // Read 6 bytes: 2 bytes temperature plus 1 CRC, and 2 bytes humidity plus 1 CRC
    uint8_t data_buf[6];
    if (i2cRead(i2c_handle, SHT31D_ADDR, data_buf, 6) < 0) {
      fprintf(stderr, "Failed to read data\n");
      return 1;
    }

    // Validate CRC-8
    uint8_t crc_temp = crc8(data_buf, 2, SHT31D_CRC_POLYNOMIAL, SHT31D_CRC_INITIAL_VALUE);
    uint8_t crc_humidity = crc8(data_buf + 3, 2, SHT31D_CRC_POLYNOMIAL, SHT31D_CRC_INITIAL_VALUE);
    if (crc_temp != data_buf[2] || crc_humidity != data_buf[5]) {
      fprintf(stderr, "CRC validation failed\n");
      return 1;
    }

    // Convert raw values
    int16_t temp_raw = (data_buf[0] << 8) | data_buf[1];
    int16_t humidity_raw = (data_buf[3] << 8) | data_buf[4];
    float temperature = SHT31D_TEMP_MIN + (SHT31D_TEMP_MAX - SHT31D_TEMP_MIN) * temp_raw / 65535;
    float humidity = SHT31D_HUMIDITY_MIN + (SHT31D_HUMIDITY_MAX - SHT31D_HUMIDITY_MIN) * humidity_raw / 65535;

    // Log data
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);

    // Wait 5 seconds
    sleep(5);
  }

  // Clean up
  i2cClose(i2c_handle);
  fclose(log_file);
  gpioTerminate();

  return 0;
}

// CRC-8 calculation
uint8_t crc8(uint8_t *data, size_t len, uint8_t polynomial, uint8_t initial_value) {
  uint8_t crc = initial_value;
  for (size_t i = 0; i < len; i++) {
    crc ^= data[i];
    for (int j = 0; j < 8; j++) {
      if (crc & 0x80) {
        crc = (crc << 1) ^ polynomial;
      } else {
        crc <<= 1;
      }
    }
  }
  return crc;
}

// Signal handlers
void sigint_handler(int signal) {
  // Close I2C handle
  i2cClose(i2c_handle);

  // Close log file
  fclose(log_file);

  // Terminate pigpio
  gpioTerminate();

  // Exit program
  exit(0);
}

void sigterm_handler(int signal) {
  // Close I2C handle
  i2cClose(i2c_handle);

  // Close log file
  fclose(log_file);

  // Terminate pigpio
  gpioTerminate();

  // Exit program
  exit(0);
}

