#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR_1 0x64
#define SENSOR_ADDR_2 0x65
#define DEVICE_ID_REG 0x00
#define RED_CHANNEL_REG 0x64
#define GREEN_CHANNEL_REG 0x66
#define BLUE_CHANNEL_REG 0x68

#define CCT_FORMULA(r, g, b) (((r * 255.0) - (g * 149.0) + (b * 31.0)) / 255.0)

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Set up signal handling
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Initialize pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus
    int i2c_handle = pigpio_i2c_open(I2C_BUS, 0, 0, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Open CSV file for logging
    FILE *csv_file = fopen("cct_log.csv", "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return 1;
    }

    // Write header to CSV file
    fprintf(csv_file, "Timestamp,Average_CCT\n");

    // Main loop
    while (running) {
        // Read device ID registers
        uint8_t device_id_1 = 0;
        uint8_t device_id_2 = 0;
        if (pigpio_i2c_read_byte_data(i2c_handle, SENSOR_ADDR_1, DEVICE_ID_REG, &device_id_1) < 0) {
            fprintf(stderr, "Failed to read device ID register from sensor 1\n");
            continue;
        }
        if (pigpio_i2c_read_byte_data(i2c_handle, SENSOR_ADDR_2, DEVICE_ID_REG, &device_id_2) < 0) {
            fprintf(stderr, "Failed to read device ID register from sensor 2\n");
            continue;
        }

        // Check device ID registers
        if (device_id_1 != 0x2A || device_id_2 != 0x2A) {
            fprintf(stderr, "Invalid device ID register value\n");
            continue;
        }

        // Read channel data registers
        uint16_t red_1 = 0;
        uint16_t green_1 = 0;
        uint16_t blue_1 = 0;
        uint16_t red_2 = 0;
        uint16_t green_2 = 0;
        uint16_t blue_2 = 0;
        if (pigpio_i2c_read_word_data(i2c_handle, SENSOR_ADDR_1, RED_CHANNEL_REG, &red_1) < 0) {
            fprintf(stderr, "Failed to read red channel data register from sensor 1\n");
            continue;
        }
        if (pigpio_i2c_read_word_data(i2c_handle, SENSOR_ADDR_1, GREEN_CHANNEL_REG, &green_1) < 0) {
            fprintf(stderr, "Failed to read green channel data register from sensor 1\n");
            continue;
        }
        if (pigpio_i2c_read_word_data(i2c_handle, SENSOR_ADDR_1, BLUE_CHANNEL_REG, &blue_1) < 0) {
            fprintf(stderr, "Failed to read blue channel data register from sensor 1\n");
            continue;
        }
        if (pigpio_i2c_read_word_data(i2c_handle, SENSOR_ADDR_2, RED_CHANNEL_REG, &red_2) < 0) {
            fprintf(stderr, "Failed to read red channel data register from sensor 2\n");
            continue;
        }
        if (pigpio_i2c_read_word_data(i2c_handle, SENSOR_ADDR_2, GREEN_CHANNEL_REG, &green_2) < 0) {
            fprintf(stderr, "Failed to read green channel data register from sensor 2\n");
            continue;
        }
        if (pigpio_i2c_read_word_data(i2c_handle, SENSOR_ADDR_2, BLUE_CHANNEL_REG, &blue_2) < 0) {
            fprintf(stderr, "Failed to read blue channel data register from sensor 2\n");
            continue;
        }

        // Compute CCT values
        double cct_1 = CCT_FORMULA(red_1, green_1, blue_1);
        double cct_2 = CCT_FORMULA(red_2, green_2, blue_2);

        // Log CCT values
        fprintf(csv_file, "%ld,%.2f\n", time(NULL), (cct_1 + cct_2) / 2.0);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    pigpio_i2c_close(i2c_handle);
    fclose(csv_file);
    pigpio_stop();

    return 0;
}

