#define PRESSURE_REG 0x0A2C
#define TEMPERATURE_REG 0x0A2E

#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define PMIN_KPA 0
#define PMAX_KPA 800

int main(void) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("pressure_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read pressure and temperature registers
        uint16_t pressure_raw, temperature_raw;
        if (i2cReadWord(i2c_handle, PRESSURE_REG, &pressure_raw) < 0) {
            fprintf(stderr, "Failed to read pressure register\n");
            continue;
