        if (i2cReadWord(i2c_handle, TEMPERATURE_REG, &temperature_raw) < 0) {
            fprintf(stderr, "Failed to read temperature register\n");
            continue;
        }

        // Convert pressure to kPa
        float pressure_kPa = (pressure_raw - OUTPUT_MIN) * (PMAX_KPA - PMIN_KPA) / (OUTPUT_MAX - OUTPUT_MIN);

        // Convert temperature to Celsius
        float temperature_C = temperature_raw * 0.01 - 40;

        // Log results
        time_t now = time(NULL);
