#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define TEMP_REG 0x00
#define TEMP_RES 0.5
#define TEMP_MIN 26.0
#define TEMP_MAX 28.0
#define FAN_GPIO 18

#define CIRC_BUF_SIZE 60

static volatile bool running = true;
static volatile bool fan_on = false;
static volatile bool i2c_open = false;
static volatile bool gpio_open = false;

static uint8_t circ_buf[CIRC_BUF_SIZE];
static uint8_t circ_buf_idx = 0;

static void sigint_handler(int signum) {
    running = false;
}

static void sigterm_handler(int signum) {
    running = false;
}

static void init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }
    gpio_open = true;
}

static void init_i2c() {
    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x\n", I2C_BUS, I2C_ADDR);
        exit(1);
    }
    i2c_open = true;
}

static void read_temp() {
    uint8_t data[2];
    if (i2cRead(I2C_BUS, I2C_ADDR, TEMP_REG, data, 2) < 0) {
        fprintf(stderr, "Failed to read temperature register 0x%02x\n", TEMP_REG);
        exit(1);
    }
    int16_t temp = (data[0] << 8) | data[1];
    temp = (temp >> 7) * TEMP_RES;
    circ_buf[circ_buf_idx] = temp;
    circ_buf_idx = (circ_buf_idx + 1) % CIRC_BUF_SIZE;
}

static void compute_avg() {
    int sum = 0;
    for (int i = 0; i < CIRC_BUF_SIZE; i++) {
        sum += circ_buf[i];
    }
    double avg = sum / CIRC_BUF_SIZE;
    printf("Average temperature: %.1f °C\n", avg);
}

static void control_fan() {
    if (avg > TEMP_MAX && !fan_on) {
        gpioWrite(FAN_GPIO, 1);
        fan_on = true;
    } else if (avg < TEMP_MIN && fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = false;
    }
}

int main() {
    init_pigpio();
    init_i2c();

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (running) {
        read_temp();
        compute_avg();
        control_fan();
        sleep(1);
    }

    if (i2c_open) {
        i2cClose(I2C_BUS);
    }
    if (gpio_open) {
        gpioTerminate();
    }

    return 0;
}

