#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONT_MEASURE 0x362F
#define CMD_READ_MEASURE 0x362E
#define CMD_CRC_POLY 0x31
#define CMD_CRC_INIT 0xFF
#define SCALE_FACTOR_PRESSURE 60
#define SCALE_FACTOR_TEMPERATURE 200
#define WARNING_THRESHOLD 5.0

int main(void) {
    // Initialize the I2C bus
    int i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the log file
    FILE *log_file = fopen("airflow.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Send the continuous measurement command
    uint8_t cmd_buf[2] = {CMD_CONT_MEASURE, 0x00};
    if (pigpio_i2c_write(i2c_handle, cmd_buf, 2) < 0) {
        fprintf(stderr, "Error sending continuous measurement command: %s\n", strerror(errno));
        return 1;
    }

    // Wait for the first measurement
    usleep(45000);

    // Read the measurement data
    uint8_t data_buf[9];
    if (pigpio_i2c_read(i2c_handle, data_buf, 9) < 0) {
        fprintf(stderr, "Error reading measurement data: %s\n", strerror(errno));
        return 1;
    }

    // Validate the CRC
    uint8_t crc = pigpio_crc8(data_buf, 8, CMD_CRC_POLY, CMD_CRC_INIT);
    if (crc != data_buf[8]) {
        fprintf(stderr, "CRC mismatch: expected %02X, got %02X\n", crc, data_buf[8]);
        return 1;
    }

    // Convert the raw pressure and temperature
    int16_t pressure = (int16_t)((data_buf[0] << 8) | data_buf[1]);
    int16_t temperature = (int16_t)((data_buf[2] << 8) | data_buf[3]);
    pressure = pressure * SCALE_FACTOR_PRESSURE;
    temperature = temperature * SCALE_FACTOR_TEMPERATURE;

    // Log the measurement data
    time_t timestamp = time(NULL);
    fprintf(log_file, "%ld,%.2f,%.2f\n", timestamp, pressure, temperature);

    // Check for warning threshold
    if (pressure > WARNING_THRESHOLD) {
        fprintf(stderr, "Warning: pressure exceeded threshold (%.2f Pa)\n", WARNING_THRESHOLD);
    }

    // Clean up
    pigpio_i2c_close(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

