#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x4A
#define LED_GPIO 17
#define LED_ON 1
#define LED_OFF 0
#define TEMP_REG 0x00
#define TEMP_MSB_REG 0x01
#define TEMP_LSB_REG 0x02
#define TEMP_HYST 2
#define TEMP_THRESH 28

int main(void) {
    int i2c_fd, gpio_fd, ret;
    uint8_t temp_msb, temp_lsb;
    int16_t temp;
    struct i2c_msg i2c_msg;
    struct gpiod_line *led_line;

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO device
    gpio_fd = open("/dev/gpiochip0", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line for LED
    led_line = gpiod_line_get(gpio_fd, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line for LED");
        close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    // Set GPIO line direction to output
    ret = gpiod_line_set_direction(led_line, GPIOD_LINE_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Failed to set GPIO line direction");
        gpiod_line_release(led_line);
        close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    // Set GPIO line value to low
    ret = gpiod_line_set_value(led_line, LED_OFF);
    if (ret < 0) {
        perror("Failed to set GPIO line value");
        gpiod_line_release(led_line);
        close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    // Read temperature from I2C
    i2c_msg.addr = I2C_ADDR;
    i2c_msg.flags = 0;
    i2c_msg.len = 2;
    i2c_msg.buf = &temp_msb;
    ret = i2c_transfer(i2c_fd, &i2c_msg, 1);
    if (ret < 0) {
        perror("Failed to read temperature from I2C");
        gpiod_line_release(led_line);
        close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    // Read temperature from I2C
    i2c_msg.addr = I2C_ADDR;
    i2c_msg.flags = 0;
    i2c_msg.len = 2;
    i2c_msg.buf = &temp_lsb;
    ret = i2c_transfer(i2c_fd, &i2c_msg, 1);
    if (ret < 0) {
        perror("Failed to read temperature from I2C");
        gpiod_line_release(led_line);
        close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    // Combine MSB and LSB
    temp = (temp_msb << 8) | temp_lsb;

    // Right-shift result by 4 bits
    temp >>= 4;

    // Convert to Celsius
    temp *= 0.0625;

    // Log temperature to stdout
    printf("Temperature: %.2f °C\n", temp);

    // Check temperature and set LED
    if (temp > TEMP_THRESH) {
        gpiod_line_set_value(led_line, LED_ON);
    } else if (temp < TEMP_THRESH - TEMP_HYST) {
        gpiod_line_set_value(led_line, LED_OFF);
    }

    // Close I2C and GPIO devices
    close(i2c_fd);
    close(gpio_fd);

    // Release GPIO line
    gpiod_line_release(led_line);

    return 0;
}

