#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SDA_PIN 2
#define SCL_PIN 3
#define I2C_ADDR 0x40
#define I2C_BUS 1

#define TEMP_CMD 0xF3
#define RH_CMD 0xF5
#define RH_READ_CMD 0xE0
#define TEMP_READ_CMD 0xE0

#define TEMP_CONV_FACTOR 175.72
#define TEMP_CONV_OFFSET -46.85
#define HUMIDITY_CONV_FACTOR 125
#define HUMIDITY_CONV_OFFSET -6

#define MAX_RETRIES 3

int main(void) {
    int i2c_handle;
    int ret;
    uint8_t buf[2];
    uint16_t raw_temp, raw_rh;
    float temp, humidity;
    char timestamp[20];

    // Initialize the I2C bus
    i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR, SDA_PIN, SCL_PIN);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Read the sensor ID or firmware revision
    ret = pigpio_i2c_read_device(i2c_handle, 0xFA, buf, 2);
    if (ret < 0) {
        fprintf(stderr, "Error reading sensor ID or firmware revision: %s\n", strerror(errno));
        return 1;
    }

    // Check if the sensor is present
    if (buf[0] != 0x15 || buf[1] != 0x20) {
        fprintf(stderr, "Sensor not present\n");
        return 1;
    }

    // Set up the signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Take a temperature measurement
        ret = pigpio_i2c_write_device(i2c_handle, TEMP_CMD, NULL, 0);
        if (ret < 0) {
            fprintf(stderr, "Error taking temperature measurement: %s\n", strerror(errno));
            continue;
        }

        // Wait for the measurement to complete
        usleep(20000);

        // Read the temperature measurement
        ret = pigpio_i2c_read_device(i2c_handle, TEMP_READ_CMD, buf, 2);
        if (ret < 0) {
            fprintf(stderr, "Error reading temperature measurement: %s\n", strerror(errno));
            continue;
        }

        // Convert the raw temperature value to Celsius
        raw_temp = (buf[0] << 8) | buf[1];
        temp = (TEMP_CONV_FACTOR * raw_temp / 65536) - TEMP_CONV_OFFSET;

        // Take a humidity measurement
        ret = pigpio_i2c_write_device(i2c_handle, RH_CMD, NULL, 0);
        if (ret < 0) {
            fprintf(stderr, "Error taking humidity measurement: %s\n", strerror(errno));
            continue;
        }

        // Wait for the measurement to complete
        usleep(20000);

        // Read the humidity measurement
        ret = pigpio_i2c_read_device(i2c_handle, RH_READ_CMD, buf, 2);
        if (ret < 0) {
            fprintf(stderr, "Error reading humidity measurement: %s\n", strerror(errno));
            continue;
        }

        // Convert the raw humidity value to percentage
        raw_rh = (buf[0] << 8) | buf[1];
        humidity = (HUMIDITY_CONV_FACTOR * raw_rh / 65536) - HUMIDITY_CONV_OFFSET;

        // Clamp the humidity value to 0-100%
        if (humidity < 0) {
            humidity = 0;
        } else if (humidity > 100) {
            humidity = 100;
        }

        // Log the reading
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
        fprintf(stdout, "%s,%f,%f\n", timestamp, temp, humidity);
        fflush(stdout);

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up
    pigpio_i2c_close(i2c_handle);
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum) {
    // Clean up
    pigpio_i2c_close(i2c_handle);
    gpioTerminate();

    exit(0);
}

void sigterm_handler(int signum) {
    // Clean up
    pigpio_i2c_close(i2c_handle);
    gpioTerminate();

    exit(0);
}

