#define HDC1080_ADDR 0x40
#define HDC1080_TEMP_REG 0x00
#define HDC1080_HUMID_REG 0x01
#define HDC1080_CONFIG_REG 0x02
#define HDC1080_TEMP_RES 14
#define HDC1080_HUMID_RES 14

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus 1
    int i2c_handle = i2cOpen(1, 0, 0, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }

    // Configure HDC1080 for 14-bit temperature and humidity resolution
    uint8_t config_reg = (HDC1080_TEMP_RES << 4) | HDC1080_HUMID_RES;
    if (i2cWriteByte(i2c_handle, HDC1080_ADDR, HDC1080_CONFIG_REG, config_reg) < 0) {
        fprintf(stderr, "Failed to configure HDC1080\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read temperature and humidity
        uint8_t temp_reg = HDC1080_TEMP_REG;
        uint8_t humid_reg = HDC1080_HUMID_REG;
        if (i2cWriteByte(i2c_handle, HDC1080_ADDR, HDC1080_TEMP_REG, temp_reg) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }
        if (i2cWriteByte(i2c_handle, HDC1080_ADDR, HDC1080_HUMID_REG, humid_reg) < 0) {
            fprintf(stderr, "Failed to read humidity\n");
            continue;
        }

        // Wait for conversion
        usleep(20000);

        // Read raw temperature and humidity values
        uint16_t raw_temp, raw_humid;
        if (i2cReadWord(i2c_handle, HDC1080_ADDR, HDC1080_TEMP_REG, &raw_temp) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }
        if (i2cReadWord(i2c_handle, HDC1080_ADDR, HDC1080_HUMID_REG, &raw_humid) < 0) {
            fprintf(stderr, "Failed to read humidity\n");
            continue;
        }

        // Convert raw values to temperature and humidity
        float temperature = (raw_temp / 65536.0) * 165.0 - 40.0;
        float humidity = (raw_humid / 65536.0) * 100.0;

        // Log reading
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        char log_entry[50];
        sprintf(log_entry, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        FILE *log_file = fopen("enviro_log.txt", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            continue;
        }
        fprintf(log_file, log_entry);
        fclose(log_file);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

