#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <time.h>

#define SENSOR_ADDR 0x44
#define SENSOR_CMD_MEASURE 0x2C
#define SENSOR_CMD_REPEATABILITY 0xE0
#define SENSOR_CRC_POLY 0x31
#define SENSOR_CRC_INIT 0xFF
#define SENSOR_CRC_XOR 0x00
#define SENSOR_TEMP_MIN -45
#define SENSOR_TEMP_MAX 175
#define SENSOR_TEMP_RANGE 65535
#define SENSOR_TEMP_RESOLUTION 0.01

int main(void) {
    int fd;
    int ret;
    uint8_t cmd[2];
    uint8_t data[3];
    uint8_t crc;
    float temp;
    char timestamp[20];
    FILE *logfile;

    // Open the I2C adapter
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C adapter");
        return 1;
    }

    // Set the slave address
    ret = ioctl(fd, I2C_SLAVE, SENSOR_ADDR);
    if (ret < 0) {
        perror("Failed to set slave address");
        close(fd);
        return 1;
    }

    // Open the log file
    logfile = fopen("temperature_log.txt", "a");
    if (logfile == NULL) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    // Set the signal handler for SIGINT/SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Infinite loop to read temperature every 5 seconds
    while (1) {
        // Send the measurement command
        cmd[0] = SENSOR_CMD_MEASURE;
        cmd[1] = SENSOR_CMD_REPEATABILITY;
        ret = write(fd, cmd, 2);
        if (ret < 0) {
            perror("Failed to send measurement command");
            continue;
        }

        // Wait for conversion
        usleep(10000);

        // Read the data
        ret = read(fd, data, 3);
        if (ret < 0) {
            perror("Failed to read data");
            continue;
        }

        // Validate the CRC
        crc = data[2];
        for (int i = 0; i < 2; i++) {
            crc = crc ^ data[i];
        }
        if (crc != SENSOR_CRC_XOR) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        // Convert the raw ticks to Celsius
        temp = (float)((data[0] << 8) | data[1]) / SENSOR_TEMP_RANGE * SENSOR_TEMP_RESOLUTION;

        // Log the temperature
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));
        fprintf(logfile, "%s,%.2f\n", timestamp, temp);

        // Wait for 5 seconds
        sleep(5);
    }

    // Close the file descriptor and log file
    close(fd);
    fclose(logfile);

    return 0;
}

void sigint_handler(int signum) {
    // Close the file descriptor and log file
    close(fd);
    fclose(logfile);

    // Exit the program
    exit(0);
}

