#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <i2c.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONT_MEASURE 0x3615
#define CMD_READ_PRESSURE 0x3615
#define CMD_READ_TEMPERATURE 0x3615
#define CMD_READ_SCALE_FACTOR 0x3615
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

#define PRESSURE_CSV_HEADER "timestamp,pressure_Pa,temperature_C\n"

void handle_sigint(int signal) {
    // Close the I2C handle
    i2cClose(I2C_BUS);

    // Flush and close the log file
    fflush(log_file);
    fclose(log_file);

    // Call gpioTerminate()
    gpioTerminate();

    // Exit the program
    exit(0);
}

int main(void) {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Open the I2C bus
    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("hvac_pressure_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Write the CSV header to the log file
    fprintf(log_file, PRESSURE_CSV_HEADER);

    // Set up the signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Main loop
    while (1) {
        // Send the continuous-measurement command
        if (i2cWrite(I2C_BUS, I2C_ADDR, CMD_CONT_MEASURE, 1) < 0) {
            fprintf(stderr, "Failed to send continuous-measurement command\n");
            return 1;
        }

        // Wait at least 50 ms
        usleep(50000);

        // Read the pressure, temperature, and scale factor
        uint8_t data[9];
        if (i2cRead(I2C_BUS, I2C_ADDR, data, 9) < 0) {
            fprintf(stderr, "Failed to read pressure, temperature, and scale factor\n");
            return 1;
        }

        // Validate the CRC-8
        uint8_t crc = 0xFF;
        for (int i = 0; i < 8; i++) {
            crc = crc8_update(crc, data[i]);
        }
        if (crc != data[8]) {
            fprintf(stderr, "Invalid CRC-8\n");
            return 1;
        }

        // Convert the raw pressure and temperature
        uint16_t pressure = (data[0] << 8) | data[1];
        uint16_t temperature = (data[2] << 8) | data[3];
        float scale_factor = (data[4] << 16) | (data[5] << 8) | data[6];
        float pressure_pa = pressure / scale_factor;
        float temperature_c = temperature / 200.0;

        // Log the valid reading
        fprintf(log_file, "%ld,%.2f,%.2f\n", time(NULL), pressure_pa, temperature_c);
    }

    // Close the I2C handle
    i2cClose(I2C_BUS);

    // Flush and close the log file
    fflush(log_file);
    fclose(log_file);

    // Call gpioTerminate()
    gpioTerminate();

    return 0;
}

