#define SCD40_I2C_ADDR 0x62
#define SCD40_START_PERIODIC_MEASUREMENT 0x21B1
#define SCD40_READ_MEASUREMENT 0xE000
#define SCD40_STOP_PERIODIC_MEASUREMENT 0x3F86
#define SCD40_CRC_POLYNOMIAL 0x31
#define SCD40_CRC_INITIAL_VALUE 0xFF
#define SCD40_BUFFER_CAPACITY 100
#define SCD40_LOG_FILE "/var/log/scd40_data/scd40_data.csv"
#define SCD40_ERROR_FILE "/var/log/scd40_error.log"

typedef struct {
    uint32_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} scd40_data_t;

volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void* logging_thread(void* arg) {
    while (running) {
        // Wait for 60 seconds
        sleep(60);

        // Write the buffer to a CSV file
        FILE* fp = fopen(SCD40_LOG_FILE, "a");
        if (fp == NULL) {
            fprintf(stderr, "Error opening file %s: %s\n", SCD40_LOG_FILE, strerror(errno));
            continue;
        }

        // Write the header row
        fprintf(fp, "timestamp,co2,temperature,humidity\n");

        // Write the buffer data
        for (int i = 0; i < SCD40_BUFFER_CAPACITY; i++) {
            scd40_data_t data = buffer[i];
            fprintf(fp, "%u,%u,%f,%f\n", data.timestamp, data.co2, data.temperature, data.humidity);
        }

        fclose(fp);
    }

    return NULL;
}

int main(void) {
    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Open the I2C bus
    int i2c_handle = pigpio_i2c_open(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Start the periodic measurement
    if (pigpio_i2c_write(i2c_handle, SCD40_START_PERIODIC_MEASUREMENT, NULL, 0) < 0) {
        fprintf(stderr, "Error starting periodic measurement: %s\n", strerror(errno));
        return 1;
    }

    // Wait for at least 1 second
    sleep(1);

    // Create a thread for logging
    pthread_t logging_thread_id;
    if (pthread_create(&logging_thread_id, NULL, logging_thread, NULL) != 0) {
        fprintf(stderr, "Error creating logging thread: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    while (running) {
        // Read the measurement
        uint8_t data[9];
        if (pigpio_i2c_read(i2c_handle, SCD40_READ_MEASUREMENT, data, 9) < 0) {
            fprintf(stderr, "Error reading measurement: %s\n", strerror(errno));
            continue;
        }

        // Validate the CRC-8
        uint8_t crc = data[0];
        for (int i = 1; i < 7; i++) {
            crc = pigpio_crc8_update(crc, data[i]);
        }
        if (crc != data[7]) {
            fprintf(stderr, "Error validating CRC-8: %s\n", strerror(errno));
            continue;
        }

        // Convert the values
        scd40_data_t data_struct;
        data_struct.timestamp = time(NULL);
        data_struct.co2 = (data[1] << 8) | data[2];
        data_struct.temperature = -45 + 175 * (data[3] << 8) | data[4] / 65535;
        data_struct.humidity = 100 * (data[5] << 8) | data[6] / 65535;

        // Add the data to the buffer
        pthread_mutex_lock(&buffer_mutex);
        buffer[buffer_index] = data_struct;
        buffer_index = (buffer_index + 1) % SCD40_BUFFER_CAPACITY;
        pthread_mutex_unlock(&buffer_mutex);
    }

    // Stop the periodic measurement
    if (pigpio_i2c_write(i2c_handle, SCD40_STOP_PERIODIC_MEASUREMENT, NULL, 0) < 0) {
        fprintf(stderr, "Error stopping periodic measurement: %s\n", strerror(errno));
        return 1;
    }

    // Join the logging thread
    pthread_join(logging_thread_id, NULL);

    // Flush any remaining buffer data to a final CSV file
    FILE* fp = fopen(SCD40_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", SCD40_LOG_FILE, strerror(errno));
        return 1;
    }

    // Write the header row
    fprintf(fp, "timestamp,co2,temperature,humidity\n");

    // Write the buffer data
    for (int i = 0; i < SCD40_BUFFER_CAPACITY; i++) {
        scd40_data_t data = buffer[i];
        fprintf(fp, "%u,%u,%f,%f\n", data.timestamp, data.co2, data.temperature, data.humidity);
    }

    fclose(fp);

    // Close the I2C handle
    pigpio_i2c_close(i2c_handle);

    // Terminate pigpio
    pigpio_stop(NULL);

    return 0;
}

