#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONT_MEASURE 0x362F
#define CMD_READ_DATA 0x362F
#define CMD_CRC_8 0x31
#define CMD_CRC_INIT 0xFF

#define PRESSURE_PA_SCALE 1000
#define TEMP_SCALE 65535

#define LOG_FILE "sdp810_log.txt"

int main(void) {
    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C handle
    int i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        pigpio_stop();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pigpio_i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sigint_handler;
    sigint_handler.sa_handler = sigint_handler_func;
    sigint_handler.sa_flags = 0;
    sigemptyset(&sigint_handler.sa_mask);
    sigaction(SIGINT, &sigint_handler, NULL);

    // Main loop
    while (true) {
        // Send continuous measurement command
        if (pigpio_i2c_write(i2c_handle, CMD_CONT_MEASURE, 1) < 0) {
            fprintf(stderr, "Failed to send continuous measurement command\n");
            continue;
        }

        // Wait at least 45 ms
        usleep(45000);

        // Read 9 bytes: 2 bytes differential pressure plus CRC, 2 bytes temperature plus CRC, and 2 bytes scale factor plus CRC
        uint8_t data[9];
        if (pigpio_i2c_read(i2c_handle, data, 9) < 0) {
            fprintf(stderr, "Failed to read data\n");
            continue;
        }

        // Validate CRC-8
        uint8_t crc = CMD_CRC_INIT;
        for (int i = 0; i < 7; i++) {
            crc = pigpio_crc8_update(crc, data[i]);
        }
        if (crc != data[7]) {
            fprintf(stderr, "CRC-8 failed for differential pressure\n");
            continue;
        }
        crc = CMD_CRC_INIT;
        for (int i = 0; i < 7; i++) {
            crc = pigpio_crc8_update(crc, data[i + 2]);
        }
        if (crc != data[9]) {
            fprintf(stderr, "CRC-8 failed for temperature\n");
            continue;
        }
        crc = CMD_CRC_INIT;
        for (int i = 0; i < 7; i++) {
            crc = pigpio_crc8_update(crc, data[i + 4]);
        }
        if (crc != data[11]) {
            fprintf(stderr, "CRC-8 failed for scale factor\n");
            continue;
        }

        // Convert pressure and temperature
        int16_t raw_pressure = (data[0] << 8) | data[1];
        int16_t raw_temp = (data[2] << 8) | data[3];
        int16_t scale_factor = (data[4] << 8) | data[5];
        double pressure_Pa = raw_pressure * scale_factor / PRESSURE_PA_SCALE;
        double temperature_C = -45 + 175 * raw_temp / TEMP_SCALE;

        // Log data
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, pressure_Pa, temperature_C);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    pigpio_i2c_close(i2c_handle);
    pigpio_stop();

    return 0;
}

void sigint_handler_func(int signum) {
    // Close I2C handle
    pigpio_i2c_close(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    pigpio_stop();

    // Exit cleanly
    exit(0);
}

