            crc = pigpio_crc8_update(crc, data[i + 4]);
        }
        if (crc != data[11]) {
            fprintf(stderr, "CRC-8 failed for scale factor\n");
            continue;
        }

        // Convert pressure and temperature
        int16_t raw_pressure = (data[0] << 8) | data[1];
        int16_t raw_temp = (data[2] << 8) | data[3];
        int16_t scale_factor = (data[4] << 8) | data[5];
        double pressure_Pa = raw_pressure * scale_factor / PRESSURE_PA_SCALE;
        double temperature_C = -45 + 175 * raw_temp / TEMP_SCALE;

        // Log data
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, pressure_Pa, temperature_C);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    pigpio_i2c_close(i2c_handle);
    pigpio_stop();

    return 0;
}

void sigint_handler_func(int signum) {
    // Close I2C handle
    pigpio_i2c_close(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    pigpio_stop();

    // Exit cleanly
    exit(0);
}
