#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define CALIB_COEFF_REG 0x05
#define CALIB_COEFF_LEN 4
#define MEASURE_REG 0x00
#define MEASURE_LEN 6
#define SAMPLE_INTERVAL 5000

#define ICP10110_WHO_AM_I 0x08
#define ICP10110_CALIB_COEFF_LEN 4
#define ICP10110_MEASURE_LEN 6

#define PRESSURE_REG 0x00
#define TEMPERATURE_REG 0x01

#define PRESSURE_SCALE 1000
#define TEMPERATURE_SCALE 100

#define ICP10110_PRESSURE_FORMULA(p, t) (p * PRESSURE_SCALE / (1 - (t / TEMPERATURE_SCALE)))
#define ICP10110_TEMPERATURE_FORMULA(p, t) (t * TEMPERATURE_SCALE / (1 - (p / PRESSURE_SCALE)))

int main(void) {
    int i2c_handle;
    int i2c_error;
    uint8_t who_am_i;
    uint8_t calib_coeff[ICP10110_CALIB_COEFF_LEN];
    uint8_t measure[ICP10110_MEASURE_LEN];
    uint16_t pressure;
    uint16_t temperature;
    FILE *fp;
    char timestamp[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, I2C_SLAVE);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Verify sensor identity
    i2c_error = i2cReadI2CBlockData(i2c_handle, WHO_AM_I_REG, &who_am_i, 1);
    if (i2c_error < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return 1;
    }
    if (who_am_i != ICP10110_WHO_AM_I) {
        fprintf(stderr, "Invalid sensor identity\n");
        return 1;
    }

    // Read calibration coefficients
    i2c_error = i2cReadI2CBlockData(i2c_handle, CALIB_COEFF_REG, calib_coeff, CALIB_COEFF_LEN);
    if (i2c_error < 0) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        return 1;
    }

    // Open file for logging
    fp = fopen("environmental_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for logging\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Trigger measurement
        i2c_error = i2cWriteI2CBlockData(i2c_handle, MEASURE_REG, 0x00, 1);
        if (i2c_error < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue;
        }

        // Wait for measurement to complete
        usleep(10000);

        // Read pressure and temperature data
        i2c_error = i2cReadI2CBlockData(i2c_handle, MEASURE_REG, measure, MEASURE_LEN);
        if (i2c_error < 0) {
            fprintf(stderr, "Failed to read pressure and temperature data\n");
            continue;
        }

        // Convert pressure and temperature data
        pressure = (measure[0] << 8) | measure[1];
        temperature = (measure[2] << 8) | measure[3];
        pressure = ICP10110_PRESSURE_FORMULA(pressure, temperature);
        temperature = ICP10110_TEMPERATURE_FORMULA(pressure, temperature);

        // Log data
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));
        fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
        fflush(fp);

        // Print data to stdout
        printf("Pressure: %.2f hPa, Temperature: %.2f °C\n", pressure, temperature);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum) {
    printf("Received SIGINT, exiting...\n");
    exit(0);
}

