#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x63
#define OTP_ADDR 0x66
#define CMD_MEASURE 0x4011
#define CMD_CALIBRATE 0x4012
#define CMD_READ_PRESSURE 0x4021
#define CMD_READ_TEMPERATURE 0x4022
#define CMD_READ_CRC 0x4023

#define LED_GPIO 17
#define LED_ON 1
#define LED_OFF 0
#define LED_BLINK_NORMAL 500
#define LED_BLINK_WARNING 100

#define PRESSURE_MIN 95000

int main(void) {
    int i2c_fd, otp_fd, led_fd;
    uint8_t buf[6];
    uint16_t pressure, temperature;
    uint16_t crc;
    uint8_t calibration[4];

    // Open I2C device
    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Open OTP memory
    if ((otp_fd = open(OTP_ADDR, O_RDONLY)) < 0) {
        perror("Failed to open OTP memory");
        return 1;
    }

    // Read calibration coefficients
    if (read(otp_fd, calibration, 4) != 4) {
        perror("Failed to read calibration coefficients");
        return 1;
    }

    // Close OTP memory
    close(otp_fd);

    // Open LED GPIO
    if ((led_fd = gpiod_open(LED_GPIO, GPIOD_OUTPUT)) < 0) {
        perror("Failed to open LED GPIO");
        return 1;
    }

    // Set LED to off
    gpiod_set_value(led_fd, LED_OFF);

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Trigger measurement
    if (write(i2c_fd, &CMD_MEASURE, 1) != 1) {
        perror("Failed to trigger measurement");
        return 1;
    }

    // Wait for measurement to complete
    usleep(20000);

    // Read pressure, temperature, and CRC
    if (read(i2c_fd, buf, 6) != 6) {
        perror("Failed to read pressure, temperature, and CRC");
        return 1;
    }

    // Verify CRC
    crc = (buf[4] << 8) | buf[5];
    if (crc != (buf[0] ^ buf[1] ^ buf[2] ^ buf[3])) {
        perror("CRC mismatch");
        return 1;
    }

    // Convert pressure and temperature
    pressure = (buf[0] << 8) | buf[1];
    temperature = (buf[2] << 8) | buf[3];

    // Calculate pressure in Pascals
    pressure = (pressure - calibration[0]) * calibration[1] + calibration[2];

    // Calculate temperature in Celsius
    temperature = (temperature - calibration[3]) * calibration[4] + calibration[5];

    // Print pressure and temperature
    printf("Pressure: %d Pa\n", pressure);
    printf("Temperature: %d C\n", temperature);

    // Check for high altitude
    if (pressure < PRESSURE_MIN) {
        // Blink LED at 5 Hz
        gpiod_set_value(led_fd, LED_ON);
        usleep(LED_BLINK_WARNING);
        gpiod_set_value(led_fd, LED_OFF);
        usleep(LED_BLINK_WARNING);
    } else {
        // Blink LED at 1 Hz
        gpiod_set_value(led_fd, LED_ON);
        usleep(LED_BLINK_NORMAL);
        gpiod_set_value(led_fd, LED_OFF);
        usleep(LED_BLINK_NORMAL);
    }

    // Close I2C device
    close(i2c_fd);

    // Close LED GPIO
    gpiod_close(led_fd);

    return 0;
}

