#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define MLX90614_ADDR 0x5A
#define MLX90614_AMBIENT_TEMP_REG 0x06
#define MLX90614_OBJECT_TEMP_REG 0x07

#define FAN_GPIO 18
#define FAN_ON_TEMP 30
#define FAN_OFF_TEMP 28

int main(void) {
    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus 1
    int i2c_handle = pigpio_i2c_open(1, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }

    // Set up signal handler for SIGINT/SIGTERM
    struct sigaction sigint_action;
    sigint_action.sa_handler = sigint_handler;
    sigemptyset(&sigint_action.sa_mask);
    sigint_action.sa_flags = 0;
    sigaction(SIGINT, &sigint_action, NULL);
    sigaction(SIGTERM, &sigint_action, NULL);

    // Set up GPIO for fan control
    if (pigpio_gpio_export(FAN_GPIO) < 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", FAN_GPIO);
        return 1;
    }
    if (pigpio_gpio_set_mode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", FAN_GPIO);
        return 1;
    }

    // Main loop
    while (1) {
        // Read ambient temperature
        uint16_t ambient_temp = 0;
        if (pigpio_i2c_read_word_data(i2c_handle, MLX90614_AMBIENT_TEMP_REG, &ambient_temp) < 0) {
            fprintf(stderr, "Failed to read ambient temperature\n");
            return 1;
        }

        // Read object temperature
        uint16_t object_temp = 0;
        if (pigpio_i2c_read_word_data(i2c_handle, MLX90614_OBJECT_TEMP_REG, &object_temp) < 0) {
            fprintf(stderr, "Failed to read object temperature\n");
            return 1;
        }

        // Convert raw temperature values to Celsius
        float ambient_celsius = ambient_temp * 0.02 - 273.15;
        float object_celsius = object_temp * 0.02 - 273.15;

        // Log temperature readings
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        fprintf(stderr, "%s Ambient temperature: %.2f°C Object temperature: %.2f°C\n", timestamp, ambient_celsius, object_celsius);

        // Control fan based on object temperature
        if (object_celsius > FAN_ON_TEMP) {
            pigpio_gpio_write(FAN_GPIO, 1);
        } else if (object_celsius < FAN_OFF_TEMP) {
            pigpio_gpio_write(FAN_GPIO, 0);
        }

        // Sleep for 2 seconds
        sleep(2);
    }

    // Clean up
    pigpio_i2c_close(i2c_handle);
    pigpio_gpio_unexport(FAN_GPIO);
    pigpio_stop();

    return 0;
}

void sigint_handler(int signum) {
    // Clean up
    pigpio_i2c_close(i2c_handle);
    pigpio_gpio_unexport(FAN_GPIO);
    pigpio_stop();

    // Exit
    exit(0);
}

