#define SENSOR_ADDR 0x44
#define SENSOR_CMD 0xFD
#define SENSOR_DATA_LEN 6
#define SENSOR_RETRY_COUNT 3

#define HTTP_PORT 8080
#define HTTP_BUF_LEN 1024

