    exit(0);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM, cleaning up...\n");
    close(http_sock);
    pigpio_stop(gpio_handle);
    exit(0);
}

void init_gpio() {
    gpio_handle = pigpio_start(NULL, NULL);
    if (gpio_handle < 0) {
        printf("Failed to initialize GPIO\n");
        exit(1);
    }
}

