    i2c_handle = pigpio_i2c_open(gpio_handle, 1, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        printf("Failed to initialize I2C\n");
        exit(1);
    }
}

void init_http() {
    http_sock = socket(AF_INET, SOCK_STREAM, 0);
    if (http_sock < 0) {
        printf("Failed to create HTTP socket\n");
        exit(1);
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(HTTP_PORT);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(http_sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        printf("Failed to bind HTTP socket\n");
        exit(1);
    }

    if (listen(http_sock, 1) < 0) {
        printf("Failed to listen on HTTP socket\n");
        exit(1);
    }
}

