        if (pigpio_i2c_write(i2c_handle, cmd, 1) < 0) {
            printf("Failed to write I2C command\n");
            continue;
        }

        usleep(10000); // wait at least 10 ms

        if (pigpio_i2c_read(i2c_handle, data, SENSOR_DATA_LEN) < 0) {
            printf("Failed to read I2C data\n");
            continue;
        }

        uint16_t raw_T = (data[0] << 8) | data[1];
        uint16_t raw_RH = (data[3] << 8) | data[4];

