#define TMP102_ADDR 0x48
#define TMP102_REG_TEMP 0x00

int main(void)
{
    int i2c_handle;
    int16_t temp_raw;
    float temp_c;
    char timestamp[20];
    FILE *fp;

    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus 1
    i2c_handle = pigpio_i2c_open(1, TMP102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }

    // Open temperature log file
    fp = fopen("temperature_log.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open temperature log file\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    while (1) {
        // Read temperature from TMP102
        if (pigpio_i2c_read(i2c_handle, TMP102_REG_TEMP, 2, (uint8_t *)&temp_raw) < 0) {
            fprintf(stderr, "Failed to read temperature from TMP102\n");
            continue;
        }

        // Convert temperature to Celsius
        temp_c = (float)temp_raw / 16.0;

        // Get timestamp
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Log temperature to file
        fprintf(fp, "%s,%.2f\n", timestamp, temp_c);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close I2C bus
    pigpio_i2c_close(i2c_handle);

    // Close temperature log file
    fclose(fp);

    // Terminate pigpio
    pigpio_stop();

    return 0;
}

void sigint_handler(int signum)
{
    // Close I2C bus
    pigpio_i2c_close(i2c_handle);

    // Close temperature log file
    fclose(fp);

    // Terminate pigpio
    pigpio_stop();

    exit(0);
}

