#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define MEASUREMENT_CONFIG 0x0E
#define CONFIG 0x0F
#define TEMP_HIGH 0x00
#define TEMP_LOW 0x01
#define HUMIDITY_HIGH 0x02
#define HUMIDITY_LOW 0x03

volatile sig_atomic_t running = true;

void sigint_handler(int signum) {
    running = false;
}

int main(void) {
    int i2c_handle;
    uint8_t measurement_config;
    uint8_t config;
    uint16_t temp_raw;
    uint16_t humidity_raw;
    float temperature;
    float humidity;
    int retries = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        // Trigger a one-shot temperature and humidity measurement
        if (i2cWriteByte(i2c_handle, MEASUREMENT_CONFIG, 0x01) < 0) {
            fprintf(stderr, "Failed to write to MEASUREMENT_CONFIG register\n");
            return 1;
        }

        // Wait for measurement to complete or time out
        while (retries < 10) {
            if (i2cReadByte(i2c_handle, MEASUREMENT_CONFIG, &measurement_config) < 0) {
                fprintf(stderr, "Failed to read from MEASUREMENT_CONFIG register\n");
                return 1;
            }

            if ((measurement_config & 0x01) == 0) {
                break;
            }

            retries++;
            usleep(50000);
        }

        if (retries == 10) {
            fprintf(stderr, "Timed out waiting for measurement completion\n");
            return 1;
        }

        // Read temperature and humidity
        if (i2cReadWord(i2c_handle, TEMP_HIGH, &temp_raw) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            return 1;
        }

        if (i2cReadWord(i2c_handle, HUMIDITY_HIGH, &humidity_raw) < 0) {
            fprintf(stderr, "Failed to read humidity\n");
            return 1;
        }

        // Convert temperature and humidity
        temperature = (float)temp_raw / 65536.0 * 165.0 - 40.0;
        humidity = (float)humidity_raw / 65536.0 * 100.0;

        // Print results
        printf("Temperature: %.2f°C\n", temperature);
        printf("Humidity: %.2f%%\n", humidity);

        // Wait for next measurement
        sleep(5);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

