    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, 0, 0, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Continuously read differential pressure and temperature
    while (1) {
        // Send continuous measurement command
        cmd_buf[0] = CMD_CONT_MEASURE;
        if (i2cWrite(i2c_handle, I2C_ADDR, cmd_buf, 1) < 0) {
            fprintf(stderr, "Failed to send continuous measurement command\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Wait for measurement to complete
        usleep(45000);

        // Read pressure and temperature data
        cmd_buf[0] = CMD_READ_PRESSURE;
        if (i2cWrite(i2c_handle, I2C_ADDR, cmd_buf, 1) < 0) {
            fprintf(stderr, "Failed to send read pressure command\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }
        if (i2cRead(i2c_handle, I2C_ADDR, data_buf, 6) < 0) {
            fprintf(stderr, "Failed to read pressure and temperature data\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Check CRC-8 checksums
        crc = crc8(data_buf, 4, CRC_POLY, CRC_INIT);
        if (crc != data_buf[4]) {
            fprintf(stderr, "CRC-8 checksum failed for pressure data\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }
        crc = crc8(data_buf + 2, 4, CRC_POLY, CRC_INIT);
        if (crc != data_buf[6]) {
            fprintf(stderr, "CRC-8 checksum failed for temperature data\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Extract pressure and temperature values
        pressure = (data_buf[0] << 8) | data_buf[1];
        temperature = (data_buf[2] << 8) | data_buf[3];

        // Log raw values
        printf("Pressure: %d Pa, Temperature: %d C\n", pressure, temperature);

        // Wait for next measurement
        usleep(500000);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}
