#include <pigpio.h>

#define SENSOR_PATH "/sys/bus/w1/devices/28-000007712345/w1_slave"
#define RELAY_PIN 17
#define PWM_PIN 18
#define SETPOINT 20
#define KP 0.5
#define KI 0.01
#define KD 0.001

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki>\n", argv[0]);
        return 1;
    }
    SETPOINT = atoi(argv[1]);
    KP = atof(argv[2]);
    KI = atof(argv[3]);

    // Initialize GPIO
    gpiod_chip_t *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }
    gpiod_line_t *relay = gpiod_chip_get_line(chip, RELAY_PIN);
    gpiod_line_t *pwm = gpiod_chip_get_line(chip, PWM_PIN);
    if (!relay || !pwm) {
        fprintf(stderr, "Error getting GPIO lines\n");
        return 1;
    }
    gpiod_line_request_output(relay, "relay", 0);
    gpiod_line_request_output(pwm, "pwm", 0);

    // Initialize PWM
    pigpio_t *pi = pigpio_start(NULL, NULL);
    if (!pi) {
        fprintf(stderr, "Error starting PIGPIO\n");
        return 1;
    }
    pigpio_set_mode(pi, PWM_PIN, PI_OUTPUT);
    pigpio_set_PWM_range(pi, PWM_PIN, 100);
    pigpio_set_PWM_frequency(pi, PWM_PIN, 1000);

    // Initialize sensor
    int fd = open(SENSOR_PATH, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening sensor\n");
        return 1;
    }

    // Initialize log file
    FILE *log = fopen("greenhouse.log", "w");
    if (!log) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read temperature
        char buf[100];
        if (read(fd, buf, sizeof(buf)) < 0) {
            fprintf(stderr, "Error reading sensor\n");
            return 1;
        }
        char *crc = strstr(buf, "crc=");
        if (!crc) {
            fprintf(stderr, "Error validating CRC\n");
            return 1;
        }
        float temperature = atof(crc + 4);

        // Calculate PID output
        float error = SETPOINT - temperature;
        float integral = 0;
        float derivative = 0;
        float output = KP * error + KI * integral + KD * derivative;

        // Set PWM duty cycle
        pigpio_set_PWM_dutycycle(pi, PWM_PIN, output);

        // Log data
        fprintf(log, "%ld, %f, %f, %f, %f\n", time(NULL), temperature, SETPOINT, output, pigpio_get_PWM_dutycycle(pi, PWM_PIN));

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    pigpio_stop(pi);
    gpiod_line_release(relay);
    gpiod_line_release(pwm);
    gpiod_chip_close(chip);
    fclose(log);

    return 0;
}

