#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <i2c.h>

#define AHT20_ADDR 0x38
#define AHT20_CMD_INIT 0xBE
#define AHT20_CMD_MEASURE 0xAC
#define AHT20_CMD_TRIGGER 0x33
#define AHT20_CMD_STATUS 0x71
#define AHT20_CMD_DATA 0xE0
#define AHT20_CMD_CALIBRATE 0xE1
#define AHT20_CMD_RESET 0xBA
#define AHT20_CMD_STANDBY 0x00

#define GPIO_RELAY 17
#define GPIO_RELAY_ACTIVE_HIGH 1

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR AHT20_ADDR
#define I2C_RETRIES 3
#define I2C_DELAY 10

#define HUMIDITY_THRESHOLD_HIGH 60
#define HUMIDITY_THRESHOLD_LOW 55

#define LOG_FILE "/var/log/aht20.log"

int main(int argc, char *argv[]) {
    // Initialize the GPIO line for the relay
    int gpio_fd = gpiod_open(GPIO_RELAY, GPIO_RELAY_ACTIVE_HIGH);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error opening GPIO line: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the I2C bus
    int i2c_fd = i2c_open(I2C_DEV, I2C_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the AHT20 sensor
    uint8_t init_cmd[] = {AHT20_CMD_INIT, 0x08, 0x00};
    if (i2c_write(i2c_fd, init_cmd, sizeof(init_cmd)) < 0) {
        fprintf(stderr, "Error initializing AHT20 sensor: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Main loop
    while (1) {
        // Trigger a measurement
        uint8_t measure_cmd[] = {AHT20_CMD_MEASURE, AHT20_CMD_TRIGGER, 0x00};
        if (i2c_write(i2c_fd, measure_cmd, sizeof(measure_cmd)) < 0) {
            fprintf(stderr, "Error triggering measurement: %s\n", strerror(errno));
            return 1;
        }

        // Wait for the measurement to complete
        usleep(80000);

        // Read the status byte
        uint8_t status_byte;
        if (i2c_read(i2c_fd, &status_byte, 1) < 0) {
            fprintf(stderr, "Error reading status byte: %s\n", strerror(errno));
            return 1;
        }

        // Check if the sensor is calibrated and not busy
        if ((status_byte & 0x80) == 0x80 && (status_byte & 0x01) == 0x00) {
            // Read the humidity data
            uint8_t data_cmd[] = {AHT20_CMD_DATA, 0x00, 0x00, 0x00, 0x00, 0x00};
            if (i2c_write(i2c_fd, data_cmd, sizeof(data_cmd)) < 0) {
                fprintf(stderr, "Error reading humidity data: %s\n", strerror(errno));
                return 1;
            }

            // Read the humidity data
            uint8_t humidity_data[6];
            if (i2c_read(i2c_fd, humidity_data, sizeof(humidity_data)) < 0) {
                fprintf(stderr, "Error reading humidity data: %s\n", strerror(errno));
                return 1;
            }

            // Calculate the humidity
            uint16_t humidity = (humidity_data[0] << 12) | (humidity_data[1] << 4) | (humidity_data[2] >> 4);

            // Check if the humidity is above the threshold
            if (humidity > HUMIDITY_THRESHOLD_HIGH) {
                // Turn on the relay
                gpiod_set_value(gpio_fd, 1);
            } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
                // Turn off the relay
                gpiod_set_value(gpio_fd, 0);
            }

            // Log the reading
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            fprintf(stderr, "%02d:%02d:%02d - Humidity: %d%%\n", tm->tm_hour, tm->tm_min, tm->tm_sec, humidity);
        } else {
            // Sensor is not calibrated or busy, retry
            fprintf(stderr, "Sensor not calibrated or busy, retrying...\n");
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    gpiod_close(gpio_fd);
    i2c_close(i2c_fd);

    return 0;
}

void handle_sigint(int signum) {
    // Release the GPIO line
    gpiod_set_value(gpio_fd, 0);

    // Close the I2C file descriptor
    i2c_close(i2c_fd);

    // Exit with code 0
    exit(0);
}

void handle_sigterm(int signum) {
    // Release the GPIO line
    gpiod_set_value(gpio_fd, 0);

    // Close the I2C file descriptor
    i2c_close(i2c_fd);

    // Exit with code 0
    exit(0);
}

