#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <syslog.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define I2C_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"
#define HTTP_HOST "api.example.com"
#define HTTP_PORT 80
#define HTTP_PATH "/humidity"

int main(int argc, char *argv[]) {
    int i2c_fd, http_fd;
    char buf[1024];
    struct i2c_msg i2c_msg;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct sockaddr_in http_addr;
    struct hostent *host;
    int ret;

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }

    // Open HTTP socket
    http_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (http_fd < 0) {
        perror("Failed to open HTTP socket");
        exit(1);
    }

    // Set HTTP host and port
    host = gethostbyname(HTTP_HOST);
    if (host == NULL) {
        perror("Failed to resolve HTTP host");
        exit(1);
    }
    memset(&http_addr, 0, sizeof(http_addr));
    http_addr.sin_family = AF_INET;
    http_addr.sin_port = htons(HTTP_PORT);
    http_addr.sin_addr = *((struct in_addr *)host->h_addr);

    // Connect to HTTP server
    if (connect(http_fd, (struct sockaddr *)&http_addr, sizeof(http_addr)) < 0) {
        perror("Failed to connect to HTTP server");
        exit(1);
    }

    // Set up I2C read message
    i2c_msg.addr = I2C_ADDR;
    i2c_msg.flags = I2C_M_RD;
    i2c_msg.len = 2;
    i2c_msg.buf = buf;

    // Set up I2C read/write data
    i2c_data.msgs = &i2c_msg;
    i2c_data.nmsgs = 1;

    // Read relative humidity from sensor
    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to read from I2C device");
        exit(1);
    }

    // Convert relative humidity to JSON
    snprintf(buf, sizeof(buf), "{\"humidity\":%d}", buf[0] << 8 | buf[1]);

    // Send JSON to HTTP server
    if (send(http_fd, buf, strlen(buf), 0) < 0) {
        perror("Failed to send JSON to HTTP server");
        exit(1);
    }

    // Close I2C and HTTP devices
    close(i2c_fd);
    close(http_fd);

    return 0;
}

