    http_addr.sin_addr = *((struct in_addr *)host->h_addr);

    // Connect to HTTP server
    if (connect(http_fd, (struct sockaddr *)&http_addr, sizeof(http_addr)) < 0) {
        perror("Failed to connect to HTTP server");
        exit(1);
    }

    // Set up I2C read message
    i2c_msg.addr = I2C_ADDR;
    i2c_msg.flags = I2C_M_RD;
    i2c_msg.len = 2;
    i2c_msg.buf = buf;

    // Set up I2C read/write data
    i2c_data.msgs = &i2c_msg;
    i2c_data.nmsgs = 1;

    // Read relative humidity from sensor
    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to read from I2C device");
        exit(1);
    }

    // Convert relative humidity to JSON
    snprintf(buf, sizeof(buf), "{\"humidity\":%d}", buf[0] << 8 | buf[1]);

    // Send JSON to HTTP server
    if (send(http_fd, buf, strlen(buf), 0) < 0) {
        perror("Failed to send JSON to HTTP server");
        exit(1);
    }

    // Close I2C and HTTP devices
    close(i2c_fd);
    close(http_fd);

    return 0;
}
