#define AHT20_TEMPERATURE_REG 0x01
#define PIR_GPIO_CHIP 4
#define PIR_GPIO_LINE 17
#define LOG_FILE_PATH "/var/log/sensor_data.csv"
#define LOG_FILE_HEADER "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n"

int main(void) {
    // Initialize GPIO chip and line
    struct gpiod_chip *chip = gpiod_chip_open_by_number(PIR_GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip %d\n", PIR_GPIO_CHIP);
        return 1;
    }
    struct gpiod_line *line = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error: Failed to get GPIO line %d\n", PIR_GPIO_LINE);
        gpiod_chip_close(chip);
        return 1;
    }
    gpiod_line_request_input(line, "PIR sensor");

    // Initialize I2C interface
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C interface\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize TMP117 sensor
    uint8_t tmp117_data[2];
    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_I2C_ADDR) < 0) {
