            fclose(log_file);
            close(i2c_fd);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }
        tmp117_temp = (tmp117_data[0] << 8) | tmp117_data[1];

        // Read AHT20 sensor
        if (ioctl(i2c_fd, I2C_SLAVE, AHT20_I2C_ADDR) < 0) {
