}

static void motor_stop(void) {
    gpiod_line_set_value(GPIO_MOTOR_ENABLE, MOTOR_STOP);
    gpiod_line_set_value(GPIO_MOTOR_IN1, MOTOR_STOP);
    gpiod_line_set_value(GPIO_MOTOR_IN2, MOTOR_STOP);
