#define RED_CHANNEL 17
#define GREEN_CHANNEL 22
#define BLUE_CHANNEL 27

#define MIN_PWM 0
#define MAX_PWM 255

#define CPU_LOAD_FILE "/proc/stat"
#define CPU_LOAD_SAMPLE_INTERVAL 500 // ms

#define GREEN_COLOR 0, 255, 0
#define YELLOW_COLOR 255, 255, 0
#define RED_COLOR 255, 0, 0

int main(int argc, char **argv) {
  // Initialize pigpio
  if (gpioInitialise() < 0) {
    fprintf(stderr, "Failed to initialize pigpio\n");
    return 1;
  }

  // Set up GPIO pins for RGB LED
  if (gpioSetMode(RED_CHANNEL, PI_OUTPUT) < 0 ||
      gpioSetMode(GREEN_CHANNEL, PI_OUTPUT) < 0 ||
      gpioSetMode(BLUE_CHANNEL, PI_OUTPUT) < 0) {
    fprintf(stderr, "Failed to set GPIO mode for RGB LED\n");
    return 1;
  }

  // Set up PWM for RGB LED
  if (gpioPWM(RED_CHANNEL, MIN_PWM) < 0 ||
      gpioPWM(GREEN_CHANNEL, MIN_PWM) < 0 ||
      gpioPWM(BLUE_CHANNEL, MIN_PWM) < 0) {
    fprintf(stderr, "Failed to set PWM for RGB LED\n");
    return 1;
  }

  // Set up signal handlers for SIGINT and SIGTERM
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Main loop
  while (1) {
    // Read CPU load from /proc/stat
    FILE *fp = fopen(CPU_LOAD_FILE, "r");
    if (fp == NULL) {
      fprintf(stderr, "Failed to open %s\n", CPU_LOAD_FILE);
      return 1;
    }

    char line[1024];
    if (fgets(line, sizeof(line), fp) == NULL) {
      fprintf(stderr, "Failed to read from %s\n", CPU_LOAD_FILE);
      return 1;
    }

    fclose(fp);

    // Parse CPU load from line
    int cpu_load = atoi(line);

    // Map CPU load to color
    int red, green, blue;
    if (cpu_load == 0) {
      red = 0;
      green = 255;
      blue = 0;
    } else if (cpu_load <= 50) {
      red = 255;
      green = 255;
      blue = 0;
    } else {
      red = 255;
      green = 0;
      blue = 0;
    }

    // Set PWM values for RGB LED
    gpioPWM(RED_CHANNEL, red);
    gpioPWM(GREEN_CHANNEL, green);
    gpioPWM(BLUE_CHANNEL, blue);

    // Sleep for CPU_LOAD_SAMPLE_INTERVAL ms
    usleep(CPU_LOAD_SAMPLE_INTERVAL * 1000);
  }

  // Clean up
  gpioTerminate();

  return 0;
}

void signal_handler(int signal) {
  // Turn off RGB LED
  gpioPWM(RED_CHANNEL, MIN_PWM);
  gpioPWM(GREEN_CHANNEL, MIN_PWM);
  gpioPWM(BLUE_CHANNEL, MIN_PWM);

  // Clean up
  gpioTerminate();

  exit(0);
}

