#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <pigpio.h>
#include <max31855.h>

#define FAN_PWM_GPIO 18
#define FAN_PWM_FREQ 1000
#define FAN_PWM_RANGE 255

#define MAX31855_SPI_CHANNEL 0
#define MAX31855_SPI_SPEED 500000
#define MAX31855_SPI_MODE 0

#define MAX31855_REG_TEMP 0x00
#define MAX31855_REG_CONFIG 0x01
#define MAX31855_REG_HYST 0x02
#define MAX31855_REG_LIMIT 0x03

#define MAX31855_FAULT_OC 0x01
#define MAX31855_FAULT_SCG 0x02
#define MAX31855_FAULT_SCV 0x04

#define MAX31855_TEMP_RESOLUTION 0.25

#define BUFFER_SIZE 20

typedef struct {
    uint32_t timestamp;
    int16_t temperature;
    uint8_t duty_cycle;
} buffer_entry_t;

buffer_entry_t buffer[BUFFER_SIZE];

void init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }
}

void init_spi() {
    if (spiOpen(MAX31855_SPI_CHANNEL, MAX31855_SPI_SPEED, MAX31855_SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", MAX31855_SPI_CHANNEL);
        exit(1);
    }
}

void init_fan() {
    if (gpioPWM(FAN_PWM_GPIO, FAN_PWM_FREQ, FAN_PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to initialize fan PWM on GPIO %d\n", FAN_PWM_GPIO);
        exit(1);
    }
}

void read_max31855() {
    uint8_t data[4];
    if (spiXfer(MAX31855_SPI_CHANNEL, data, 4) < 0) {
        fprintf(stderr, "Failed to read from MAX31855\n");
        return;
    }

    int16_t temperature = (data[0] << 8) | data[1];
    uint8_t fault = data[2];

    if (fault & (MAX31855_FAULT_OC | MAX31855_FAULT_SCG | MAX31855_FAULT_SCV)) {
        fprintf(stderr, "MAX31855 fault detected: %02x\n", fault);
        return;
    }

    buffer_entry_t entry;
    entry.timestamp = time(NULL);
    entry.temperature = temperature;
    entry.duty_cycle = 0;

    if (temperature < 25) {
        entry.duty_cycle = 0;
    } else if (temperature < 40) {
        entry.duty_cycle = (temperature - 25) * 50 / 15;
    } else if (temperature < 60) {
        entry.duty_cycle = 50 + (temperature - 40) * 150 / 20;
    } else {
        entry.duty_cycle = 200;
    }

    buffer[buffer_index++] = entry;
    if (buffer_index == BUFFER_SIZE) {
        buffer_index = 0;
    }
}

void set_fan_duty_cycle(uint8_t duty_cycle) {
    if (gpioPWM(FAN_PWM_GPIO, FAN_PWM_FREQ, duty_cycle) < 0) {
        fprintf(stderr, "Failed to set fan PWM duty cycle to %d\n", duty_cycle);
    }
}

void print_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        buffer_entry_t entry = buffer[i];
        printf("%ld\t%d\t%d\n", entry.timestamp, entry.temperature, entry.duty_cycle);
    }
}

void sigint_handler(int signal) {
    if (signal == SIGINT) {
        gpioPWM(FAN_PWM_GPIO, 0);
        spiClose(MAX31855_SPI_CHANNEL);
        print_buffer();
        gpioTerminate();
        exit(0);
    }
}

int main() {
    init_pigpio();
    init_spi();
    init_fan();

    signal(SIGINT, sigint_handler);

    while (1) {
        read_max31855();
        set_fan_duty_cycle(buffer[buffer_index].duty_cycle);
        sleep(1);
    }

    return 0;
}

