#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <bmp180.h>

#define I2C_BUS 1
#define I2C_ADDR 0x77
#define GPIO_PIN 2
#define OSS 3

#define LOG_FILE "altitude_log.txt"

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void log_data(FILE *file, uint32_t timestamp, float temperature, float pressure) {
    fprintf(file, "%u,%f,%f\n", timestamp, temperature, pressure);
}

int main(void) {
    // Initialize the pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up the GPIO pin for interrupts
    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO pull-up\n");
        return 1;
    }
    if (gpioSetISRFunc(GPIO_PIN, EITHER_EDGE, 0, NULL) < 0) {
        fprintf(stderr, "Failed to set GPIO ISR\n");
        return 1;
    }

    // Set up the I2C bus
    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Set up the BMP180 sensor
    if (bmp180Init() < 0) {
        fprintf(stderr, "Failed to initialize BMP180\n");
        return 1;
    }
    if (bmp180SetOversampling(OSS) < 0) {
        fprintf(stderr, "Failed to set BMP180 oversampling\n");
        return 1;
    }

    // Open the log file
    FILE *file = fopen(LOG_FILE, "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (running) {
        // Wait for the GPIO interrupt
        gpioWaitForInterrupt(GPIO_PIN, PI_TIMEOUT_BLOCK);

        // Read the temperature and pressure from the BMP180
