#define MAX31865_ADDR 0x00
#define MAX31865_RTD_REG 0x00
#define MAX31865_FAULT_REG 0x01
#define MAX31865_BIAS_REG 0x02
#define MAX31865_CONFIG_REG 0x03

#define MAX31865_RTD_MODE 0x00
#define MAX31865_BIAS_ENABLE 0x01
#define MAX31865_FAULT_STATUS 0x02

#define SPI_SPEED 1000000
#define SPI_DELAY 1000

#define LOG_FILE "rtd_log.csv"

void sigint_handler(int signum) {
    printf("Shutting down...\n");
    exit(0);
}

int main(void) {
    // Set up signal handling
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Set up SPI device
    int spi_fd = spidev_open(0, 0);
    if (spi_fd < 0) {
        perror("spidev_open");
        exit(1);
    }

    // Set up chip-select line
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(1);
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        perror("gpiod_chip_get_line");
        exit(1);
    }

    gpiod_line_request_output(line, "rtd", 0);

    // Set up log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        exit(1);
    }

    // Set up SPI transfer
    struct spi_ioc_transfer transfer = {
        .tx_buf = (uint8_t *)malloc(4),
        .rx_buf = (uint8_t *)malloc(4),
        .len = 4,
        .speed_hz = SPI_SPEED,
        .delay_usecs = SPI_DELAY,
        .bits_per_word = 8,
    };

    // Set up MAX31865 configuration
    uint8_t config = MAX31865_RTD_MODE | MAX31865_BIAS_ENABLE;
    transfer.tx_buf[0] = MAX31865_CONFIG_REG;
    transfer.tx_buf[1] = config;
    transfer.tx_buf[2] = 0;
    transfer.tx_buf[3] = 0;

    // Set up SPI transfer
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("ioctl");
        exit(1);
    }

    // Main loop
    while (1) {
        // Read RTD registers
        transfer.tx_buf[0] = MAX31865_RTD_REG;
        transfer.tx_buf[1] = 0;
        transfer.tx_buf[2] = 0;
        transfer.tx_buf[3] = 0;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
            perror("ioctl");
            exit(1);
        }

        uint16_t rtd_data = (transfer.rx_buf[1] << 8) | transfer.rx_buf[2];
        uint16_t fault_status = transfer.rx_buf[3];

        // Check fault status
        if (fault_status & MAX31865_FAULT_STATUS) {
            fprintf(stderr, "Fault detected!\n");
            continue;
        }

        // Calculate temperature
        double rtd_resistance = (double)rtd_data / 32768.0;
        double rtd_temp = 1000.0 * (1.0 / (1.0 / 100.0 + rtd_resistance / 10000.0));

        // Log temperature
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%02d:%02d:%02d,%.2f\n", tm->tm_hour, tm->tm_min, tm->tm_sec, rtd_temp);

        // Wait for next measurement
        sleep(5);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    spidev_close(spi_fd);
    fclose(log_file);

    return 0;
}

