#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <string.h>

#define BME280_I2C_ADDR 0x76
#define BME280_CHIP_ID 0x60
#define BME280_TEMP_REG 0xFA
#define BME280_HUM_REG 0xFD
#define BME280_PRESS_REG 0xF7

#define I2C_BUS 1
#define I2C_DEV "/dev/i2c-1"

#define CSV_FILE "bme280_log.csv"

int main(int argc, char *argv[]) {
    int fd, i2c_fd;
    char buf[16];
    char timestamp[20];
    float temperature, humidity, pressure;

    // Open the I2C bus
    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Check the BME280 chip ID
    if (read(i2c_fd, buf, 1) != 1) {
        perror("Failed to read BME280 chip ID");
        return 1;
    }
    if (buf[0] != BME280_CHIP_ID) {
        fprintf(stderr, "Invalid BME280 chip ID: 0x%02X\n", buf[0]);
        return 1;
    }

    // Open the CSV file
    if ((fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        perror("Failed to open CSV file");
        return 1;
    }

    // Write the CSV header
    fprintf(fd, "timestamp,temperature_C,humidity_percent,pressure_hPa\n");

    // Main loop
    while (1) {
        // Read the temperature, humidity, and pressure
        if (read(i2c_fd, buf, 3) != 3) {
            perror("Failed to read BME280 data");
            return 1;
        }
        temperature = (buf[0] << 16) | (buf[1] << 8) | buf[2];
        temperature /= 100.0;

        if (read(i2c_fd, buf, 3) != 3) {
            perror("Failed to read BME280 data");
            return 1;
        }
        humidity = (buf[0] << 16) | (buf[1] << 8) | buf[2];
        humidity /= 100.0;

        if (read(i2c_fd, buf, 3) != 3) {
            perror("Failed to read BME280 data");
            return 1;
        }
        pressure = (buf[0] << 16) | (buf[1] << 8) | buf[2];
        pressure /= 100.0;

        // Get the current timestamp
        time_t t = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&t));

        // Write the data to the CSV file
        fprintf(fd, "%s,%f,%f,%f\n", timestamp, temperature, humidity, pressure);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close the file descriptors
    close(fd);
    close(i2c_fd);

    return 0;
}

