#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CALIB_COEFF 0xAA
#define BMP180_REG_CTRL 0xF4
#define BMP180_REG_PRESS 0xF6
#define BMP180_REG_TEMP 0xFA

#define BUF_SIZE 60
#define TIMEOUT 50

#define ALERT_THRESHOLD 5

struct bmp180_calib_coeff {
    uint16_t ac1;
    uint16_t ac2;
    uint16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
};

struct bmp180_data {
    uint32_t timestamp;
    int32_t pressure;
    int32_t temperature;
};

struct bmp180_data buf[BUF_SIZE];
int buf_idx = 0;

void bmp180_init(void) {
    int i2c_handle;
    struct bmp180_calib_coeff coeff;

    // Open I2C bus 1
    i2c_handle = i2cOpen(1, 0, 0, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1\n");
        exit(1);
    }

    // Read calibration coefficients
    if (i2cReadByteData(i2c_handle, BMP180_REG_CALIB_COEFF, (uint8_t *)&coeff, sizeof(coeff)) < 0) {
        fprintf(stderr, "Error reading calibration coefficients\n");
        exit(1);
    }

    // Write control register to enable oversampling
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CTRL, 0x34) < 0) {
        fprintf(stderr, "Error writing control register\n");
        exit(1);
    }

    // Wait for 5 ms for pressure conversion
    usleep(5000);

    // Close I2C bus
    i2cClose(i2c_handle);
}

void bmp180_read(struct bmp180_data *data) {
    int i2c_handle;
    uint8_t buf[6];

    // Open I2C bus 1
    i2c_handle = i2cOpen(1, 0, 0, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1\n");
        exit(1);
    }

    // Read pressure and temperature registers
    if (i2cReadByteData(i2c_handle, BMP180_REG_PRESS, buf, sizeof(buf)) < 0) {
        fprintf(stderr, "Error reading pressure and temperature registers\n");
        exit(1);
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Calculate pressure and temperature
    data->pressure = (buf[0] << 16) | (buf[1] << 8) | buf[2];
    data->temperature = (buf[3] << 8) | buf[4];
}

void bmp180_alert(void) {
    // Trigger alert on GPIO24 (active-HIGH)
    gpioWrite(24, 1);
}

void bmp180_log(struct bmp180_data *data) {
    // Log timestamped pressure reading to circular buffer
    buf[buf_idx].timestamp = time(NULL);
    buf[buf_idx].pressure = data->pressure;
    buf[buf_idx].temperature = data->temperature;
    buf_idx = (buf_idx + 1) % BUF_SIZE;
}

void bmp180_check_alert(void) {
    int i;
    int32_t avg = 0;

    // Calculate rolling average of last 60 seconds of data
    for (i = 0; i < BUF_SIZE; i++) {
        avg += buf[i].pressure;
    }
    avg /= BUF_SIZE;

    // Check if current pressure deviates by more than 5 hPa from the rolling average
    if (abs(buf[buf_idx].pressure - avg) > ALERT_THRESHOLD) {
        bmp180_alert();
    }
}

void bmp180_timer_func(void) {
    struct bmp180_data data;

    // Read pressure and temperature
    bmp180_read(&data);

    // Log pressure reading
    bmp180_log(&data);

    // Check for alert
    bmp180_check_alert();
}

int main(void) {
    // Initialize BMP180
    bmp180_init();

    // Set up timer
    gpioSetTimerFuncEx(24, TIMEOUT, 0, bmp180_timer_func);

    // Loop forever
    while (true) {
        // Wait for timer to expire
        sleep(TIMEOUT);
    }

    // Clean up
    gpioSetTimerFuncEx(24, 0, 0, NULL);
    gpioWrite(24, 0);
    pigpio_stop();

    return 0;
}

