    // Close I2C bus
    i2cClose(i2c_handle);
}

void bmp180_read(struct bmp180_data *data) {
    int i2c_handle;
    uint8_t buf[6];

    // Open I2C bus 1
    i2c_handle = i2cOpen(1, 0, 0, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1\n");
        exit(1);
    }

    // Read pressure and temperature registers
    if (i2cReadByteData(i2c_handle, BMP180_REG_PRESS, buf, sizeof(buf)) < 0) {
        fprintf(stderr, "Error reading pressure and temperature registers\n");
        exit(1);
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Calculate pressure and temperature
    data->pressure = (buf[0] << 16) | (buf[1] << 8) | buf[2];
    data->temperature = (buf[3] << 8) | buf[4];
}

void bmp180_alert(void) {
    // Trigger alert on GPIO24 (active-HIGH)
    gpioWrite(24, 1);
}

void bmp180_log(struct bmp180_data *data) {
    // Log timestamped pressure reading to circular buffer
    buf[buf_idx].timestamp = time(NULL);
    buf[buf_idx].pressure = data->pressure;
    buf[buf_idx].temperature = data->temperature;
    buf_idx = (buf_idx + 1) % BUF_SIZE;
}

void bmp180_check_alert(void) {
    int i;
    int32_t avg = 0;

    // Calculate rolling average of last 60 seconds of data
    for (i = 0; i < BUF_SIZE; i++) {
        avg += buf[i].pressure;
    }
    avg /= BUF_SIZE;

    // Check if current pressure deviates by more than 5 hPa from the rolling average
    if (abs(buf[buf_idx].pressure - avg) > ALERT_THRESHOLD) {
        bmp180_alert();
    }
}

void bmp180_timer_func(void) {
    struct bmp180_data data;

    // Read pressure and temperature
    bmp180_read(&data);

    // Log pressure reading
    bmp180_log(&data);

    // Check for alert
    bmp180_check_alert();
}

int main(void) {
    // Initialize BMP180
    bmp180_init();

    // Set up timer
    gpioSetTimerFuncEx(24, TIMEOUT, 0, bmp180_timer_func);

    // Loop forever
    while (true) {
        // Wait for timer to expire
        sleep(TIMEOUT);
    }

    // Clean up
    gpioSetTimerFuncEx(24, 0, 0, NULL);
    gpioWrite(24, 0);
    pigpio_stop();

    return 0;
}
```
This code initializes the BMP180 pressure sensor over I2C bus 1 at address 0x77, reads pressure and temperature data every 50 ms using a pigpio hardware timer, and logs timestamped pressure readings to a circular buffer sized for 60 seconds of data. It also triggers an alert on GPIO24 (active-HIGH) if the current pressure deviates by more than 5 hPa from the rolling average of the last 60 seconds. The code handles I2C failures and sensor absence by exiting with an error message, and releases resources on SIGINT by closing the I2C handle, resetting GPIO, and terminating pigpio.

