        return 1;
    }

    // Set up fan GPIO
    fan_fd = pigpio_gpio_export(pigpio_fd, FAN_GPIO);
    if (fan_fd < 0) {
        printf("Failed to export fan GPIO\n");
        pigpio_stop(pigpio_fd);
        return 1;
    }
