        pigpio_stop(pigpio_fd);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Main loop
    while (1) {
        // Read temperature
        char temp_str[10];
        if (read(temp_fd, temp_str, sizeof(temp_str)) < 0) {
            printf("Failed to read temperature\n");
            continue;
        }
        int temp = atoi(temp_str);

        // Calculate fan duty
        int duty = (temp - TEMP_MIN) * (FAN_DUTY_MAX - FAN_DUTY_MIN) / (TEMP_MAX - TEMP_MIN) + FAN_DUTY_MIN;

        // Set fan duty
        set_fan_duty(duty);

        // Log temperature and duty cycle
        char log_str[100];
        sprintf(log_str, "%ld, %d, %d\n", time(NULL), temp, duty);
        if (write(fan_fd, log_str, strlen(log_str)) < 0) {
            printf("Failed to write to log file\n");
        }

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    pigpio_stop(pigpio_fd);
    close(fan_fd);
    close(temp_fd);
    return 0;
}

