#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <libgpiod.h>
#include <i2c.h>

#define LM75_ADDR 0x48
#define LM75_TEMP_REG 0x00
#define LM75_TEMP_SHIFT 5
#define LM75_TEMP_MAX 28.0

#define BUFFER_SIZE 60

struct data_t {
    int16_t temperature;
    uint64_t timestamp;
};

struct data_buffer_t {
    struct data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    pthread_mutex_t mutex;
};

void* data_acquisition_thread(void* arg) {
    struct data_buffer_t* buffer = (struct data_buffer_t*)arg;
    int fd = i2c_open(1, LM75_ADDR, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return NULL;
    }

    while (true) {
        pthread_mutex_lock(&buffer->mutex);
        if (buffer->head == buffer->tail) {
            // Buffer is full, discard oldest sample
            buffer->head = (buffer->head + 1) % BUFFER_SIZE;
        }

        struct data_t* sample = &buffer->buffer[buffer->head];
        sample->timestamp = get_timestamp();

        if (i2c_read(fd, LM75_TEMP_REG, 2, (uint8_t*)&sample->temperature) != 2) {
            fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
            pthread_mutex_unlock(&buffer->mutex);
            continue;
        }

        sample->temperature = (sample->temperature >> LM75_TEMP_SHIFT) / 256.0;
        buffer->head = (buffer->head + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&buffer->mutex);

        sleep(1);
    }

    i2c_close(fd);
    return NULL;
}

int main() {
    struct data_buffer_t buffer;
    buffer.head = 0;
    buffer.tail = 0;
    pthread_mutex_init(&buffer.mutex, NULL);

    pthread_t thread;
    if (pthread_create(&thread, NULL, data_acquisition_thread, &buffer) != 0) {
        fprintf(stderr, "Error creating data acquisition thread: %s\n", strerror(errno));
        return 1;
    }

    int gpio_fd = gpiod_open(18, "output");
    if (gpio_fd < 0) {
        fprintf(stderr, "Error opening GPIO 18: %s\n", strerror(errno));
        return 1;
    }

    while (true) {
        pthread_mutex_lock(&buffer.mutex);
        if (buffer.head == buffer.tail) {
            // Buffer is empty, wait for new sample
            pthread_mutex_unlock(&buffer.mutex);
            sleep(1);
            continue;
        }

        struct data_t* sample = &buffer.buffer[buffer.tail];
        if (sample->temperature > LM75_TEMP_MAX) {
            gpiod_set_value(gpio_fd, 1);
        } else {
            gpiod_set_value(gpio_fd, 0);
        }

        buffer.tail = (buffer.tail + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&buffer.mutex);
    }

    gpiod_close(gpio_fd);
    pthread_mutex_destroy(&buffer.mutex);
    return 0;
}

