static double kd;

static double rtd_resistance;
static double rtd_temperature;

static int spi_read(int reg, int *data) {
    int ret = 0;
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    tx_buf[0] = reg;
    tx_buf[1] = 0;

    ret = spi_transfer(spi_fd, tx_buf, rx_buf, 2);
    if (ret < 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];

    return 0;
}

static int spi_write(int reg, int data) {
    int ret = 0;
    uint8_t tx_buf[2];

    tx_buf[0] = reg;
    tx_buf[1] = data;

    ret = spi_transfer(spi_fd, tx_buf, NULL, 2);
    if (ret < 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return 0;
}

static int init_spi(void) {
    int ret = 0;

    spi_fd = spi_open(SPI_CE0, SPI_SPI_MODE, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: Failed to open SPI device\n");
        return -1;
    }

    ret = spi_write(MAX31865_CONFIG_REG, 0xC1);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to write to MAX31865 configuration register\n");
        return -1;
    }

    return 0;
}

static int init_pwm(void) {
    int ret = 0;

    pwm_fd = pwm_open(18, PWM_FREQUENCY, PWM_RANGE);
    if (pwm_fd < 0) {
        fprintf(stderr, "Error: Failed to open PWM device\n");
        return -1;
    }

    return 0;
}

static int init_gpio(void) {
    int ret = 0;

    gpio_fd = gpio_open(18, GPIO_OUTPUT);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error: Failed to open GPIO device\n");
        return -1;
    }

    return 0;
}

static int read_rtd(void) {
    int ret = 0;
    int rtd_code = 0;

    ret = spi_read(MAX31865_RTD_MSB_REG, &rtd_code);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to read RTD code\n");
        return -1;
    }

    rtd_resistance = (rtd_code / 32768.0) * RTD_REF_RESISTANCE;
    rtd_temperature = (rtd_resistance - RTD_NOMINAL_RESISTANCE) / RTD_NOMINAL_RESISTANCE;

    return 0;
}

static int check_faults(void) {
    int ret = 0;
    int fault_reg = 0;

    ret = spi_read(MAX31865_FAULT_REG, &fault_reg);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to read fault register\n");
        return -1;
    }

    if (fault_reg & MAX31865_FAULT_OPEN) {
        fprintf(stderr, "Error: Open fault detected\n");
        return -1;
    }

    if (fault_reg & MAX31865_FAULT_OVERVOLTAGE) {
        fprintf(stderr, "Error: Over-voltage fault detected\n");
        return -1;
    }

    if (fault_reg & MAX31865_FAULT_UNDERVOLTAGE) {
        fprintf(stderr, "Error: Under-voltage fault detected\n");
        return -1;
    }

    return 0;
}

static int pid_control(void) {
    int ret = 0;
    double error = 0.0;
    double pwm_duty = 0.0;

    ret = read_rtd();
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to read RTD temperature\n");
        return -1;
    }

    error = target_temp - rtd_temperature;
    pwm_duty = kp * error + ki * error * error + kd * error * error * error;

    if (pwm_duty < 0.0) {
        pwm_duty = 0.0;
    } else if (pwm_duty > 100.0) {
        pwm_duty = 100.0;
    }

    ret = pwm_write(pwm_fd, pwm_duty);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to write PWM duty cycle\n");
        return -1;
    }

    return 0;
}

static void sigint_handler(int signum) {
    fprintf(stderr, "Received SIGINT\n");

    pwm_write(pwm_fd, 0.0);

    spi_close(spi_fd);
    pwm_close(pwm_fd);
    gpio_close(gpio_fd);

    exit(0);
}

static void sigterm_handler(int signum) {
    fprintf(stderr, "Received SIGTERM\n");

    pwm_write(pwm_fd, 0.0);

    spi_close(spi_fd);
    pwm_close(pwm_fd);
    gpio_close(gpio_fd);

    exit(0);
}

int main(int argc, char *argv[]) {
    int ret = 0;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <config_file>\n", argv[0]);
        return -1;
    }

    ret = init_spi();
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to initialize SPI\n");
        return -1;
    }

    ret = init_pwm();
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to initialize PWM\n");
        return -1;
    }

    ret = init_gpio();
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to initialize GPIO\n");
        return -1;
    }

    ret = read_config(argv[1]);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to read configuration file\n");
        return -1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        ret = check_faults();
        if (ret < 0) {
            fprintf(stderr, "Error: Fault detected\n");
            break;
        }

        ret = pid_control();
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to perform PID control\n");
            break;
        }

        usleep(100000);
    }

    pwm_write(pwm_fd, 0.0);

    spi_close(spi_fd);
    pwm_close(pwm_fd);
    gpio_close(gpio_fd);

    return 0;
}
```
This code uses the pigpio library to control the GPIO, PWM, and SPI peripherals on the Raspberry Pi. It initializes the SPI interface to communicate with the MAX31865 RTD-to-digital converter, and the PWM interface to control the logic-level MOSFET that drives the resistive heater. It also initializes the GPIO interface to read the temperature from the PT100 RTD using the MAX31865.

The code reads the target temperature and PID gains from a JSON configuration file at startup, using defaults if the file is missing. It then enters a loop that checks for faults, reads the RTD temperature, and performs a PID control loop to regulate the heater output. If any fault is detected, the heater output is immediately turned off and the program exits with an error.

The code also handles SIGINT and SIGTERM signals gracefully, turning off the heater and closing the SPI, PWM, and GPIO interfaces before exiting cleanly.

