#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <pigpio.h>
#include <bmp180.h>

#define I2C_BUS 1
#define I2C_ADDR 0x77
#define FAN_GPIO 18
#define TEMP_THRESHOLD 30

#define CALIBRATION_REG 0xAA
#define CALIBRATION_SIZE 11

#define SAMPLE_INTERVAL 500

#define BUFFER_SIZE 60

typedef struct {
    uint32_t timestamp;
    float temperature;
    float pressure;
} reading_t;

reading_t buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

void timer_callback(int32_t id, void *userdata) {
    reading_t reading;
    int32_t i2c_handle;
    uint8_t data[CALIBRATION_SIZE];
    uint8_t reg = CALIBRATION_REG;
    uint8_t size = CALIBRATION_SIZE;
    int32_t ret;

    // Open I2C handle
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        printf("Error opening I2C handle: %s\n", strerror(i2c_handle));
        return;
    }

    // Read calibration data
    ret = i2cRead(i2c_handle, &reg, 1, data, size);
    if (ret < 0) {
        printf("Error reading calibration data: %s\n", strerror(ret));
        i2cClose(i2c_handle);
        return;
    }

    // Compute true temperature and pressure
    reading.temperature = bmp180_compute_temperature(data);
    reading.pressure = bmp180_compute_pressure(data);

    // Add reading to buffer
    buffer[buffer_head].timestamp = time(NULL);
    buffer[buffer_head].temperature = reading.temperature;
    buffer[buffer_head].pressure = reading.pressure;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;

    // Check temperature threshold
    if (reading.temperature > TEMP_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1);
    } else {
        gpioWrite(FAN_GPIO, 0);
    }

    // Close I2C handle
    i2cClose(i2c_handle);
}

void sigint_handler(int signal) {
    gpioWrite(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main(void) {
    int32_t i2c_handle;
    uint8_t data[CALIBRATION_SIZE];
    uint8_t reg = CALIBRATION_REG;
    uint8_t size = CALIBRATION_SIZE;
    int32_t ret;

    // Initialize GPIO and I2C
    gpioInit();
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        printf("Error opening I2C handle: %s\n", strerror(i2c_handle));
        return 1;
    }

    // Read calibration data
    ret = i2cRead(i2c_handle, &reg, 1, data, size);
    if (ret < 0) {
        printf("Error reading calibration data: %s\n", strerror(ret));
        i2cClose(i2c_handle);
        return 1;
    }

    // Set up timer
    pigpio_timer_t timer;
    timer.callback = timer_callback;
    timer.userdata = NULL;
    timer.period = SAMPLE_INTERVAL;
    timer.id = pigpio_timer_add(timer);
    if (timer.id < 0) {
        printf("Error setting up timer: %s\n", strerror(timer.id));
        i2cClose(i2c_handle);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (true) {
        // Print new readings
        while (buffer_head != buffer_tail) {
            printf("Timestamp: %u\n", buffer[buffer_tail].timestamp);
            printf("Temperature: %.2f°C\n", buffer[buffer_tail].temperature);
            printf("Pressure: %.2f Pa\n", buffer[buffer_tail].pressure);
            buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    pigpio_timer_del(timer.id);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

