#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <bmp180.h>

#define I2C_ADDR 0x77
#define GPIO_PIN 27
#define DEBOUNCE_MS 200
#define LOG_FILE "pressure_log.txt"
#define LOG_INTERVAL 2000

static bool logging_enabled = false;
static bool debouncing = false;
static uint32_t last_press_time = 0;
static uint32_t last_log_time = 0;
static int i2c_handle = -1;
static int gpio_handle = -1;

static void handle_sigint(int signal) {
    printf("Received SIGINT, cleaning up...\n");
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (gpio_handle != -1) {
        gpio_close(gpio_handle);
    }
    exit(0);
}

static void handle_sigterm(int signal) {
    printf("Received SIGTERM, cleaning up...\n");
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (gpio_handle != -1) {
        gpio_close(gpio_handle);
    }
    exit(0);
}

static void handle_gpio_interrupt(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        if (debouncing) {
            return;
        }
        debouncing = true;
        last_press_time = tick;
    } else {
        if (tick - last_press_time < DEBOUNCE_MS) {
            return;
        }
        debouncing = false;
        if (logging_enabled) {
            logging_enabled = false;
            printf("Logging disabled\n");
        } else {
            logging_enabled = true;
            printf("Logging enabled\n");
        }
    }
}

static void log_pressure(void) {
    uint8_t raw_data[3];
    int16_t ut, up;
    int32_t x1, x2, x3, b3, b6, p;
    float temp, pressure;

    if (i2c_read(i2c_handle, I2C_ADDR, 0xF7, raw_data, 3) != 3) {
        printf("Error reading from I2C\n");
        return;
    }

    ut = (int16_t)((raw_data[0] << 8) | raw_data[1]);
    up = (int16_t)((raw_data[2] << 8) | raw_data[3]);

    x1 = (int32_t)((ut - ac6) * ac5) >> 15;
    x2 = (int32_t)(mc << 11) / (x1 + md);
    b5 = x1 + x2;

    b6 = b5 - 4000;
    x1 = (int32_t)(b2 * (b6 * b6) >> 12) >> 11;
    x2 = (int32_t)(ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((int32_t)ac1 * 4 + x3) << oss) + 2;

    x1 = (int32_t)(ac3 * b6) >> 13;
    x2 = (int32_t)(b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = (ac4 * (uint32_t)(x3 + 32768)) >> 15;

    b7 = ((uint32_t)up - b3) * (50000 >> oss);
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    temp = (float)p / 100;
    pressure = (float)p / 1000;

    printf("Temperature: %.2f C\n", temp);
    printf("Pressure: %.2f mbar\n", pressure);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        printf("Error opening log file\n");
        return;
    }

    fprintf(fp, "%ld,%.2f,%.2f\n", time(NULL), temp, pressure);
    fclose(fp);
}

int main(void) {
    if (pigpio_start(NULL, NULL) < 0) {
        printf("Error starting pigpio\n");
        return 1;
    }

    i2c_handle = i2c_open(1, 0, 0, 0, 0);
    if (i2c_handle < 0) {
        printf("Error opening I2C\n");
        return 1;
    }

    gpio_handle = gpio_open(GPIO_PIN, GPIO_INPUT, GPIO_PULL_UP, GPIO_EDGE_FALLING, handle_gpio_interrupt);
    if (gpio_handle < 0) {
        printf("Error opening GPIO\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    while (true) {
        if (logging_enabled) {
            log_pressure();
        }
        if (time(NULL) - last_log_time > LOG_INTERVAL) {
            log_pressure();
            last_log_time = time(NULL);
        }
        sleep(1);
    }

    return 0;
}

