#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <max31855.h>

#define MAX31855_CS 8
#define MAX31855_MISO 9
#define MAX31855_MOSI 10
#define MAX31855_SCLK 11
#define HEATER_GPIO 17
#define MAX_DUTY_CYCLE 80
#define TARGET_TEMP 25.0

static volatile bool running = true;

void sigint_handler(int signum) {
    running = false;
}

void sigterm_handler(int signum) {
    running = false;
}

int main(int argc, char **argv) {
    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up SPI
    if (spi_open(0, MAX31855_CS, MAX31855_MISO, MAX31855_MOSI, MAX31855_SCLK) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        return 1;
    }

    // Set up MAX31855
    if (max31855_init(0, MAX31855_CS) < 0) {
        fprintf(stderr, "Failed to initialize MAX31855\n");
        return 1;
    }

    // Set up heater
    if (gpio_init(HEATER_GPIO) < 0) {
        fprintf(stderr, "Failed to initialize heater GPIO\n");
        return 1;
    }

    // Set up log file
    FILE *log_file = fopen("heater_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (running) {
        // Read temperature from MAX31855
        double temp;
        if (max31855_read_temp(0, &temp) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        // Calculate PWM duty cycle
        double error = temp - TARGET_TEMP;
        double duty_cycle = MAX_DUTY_CYCLE * (1 - error / TARGET_TEMP);

        // Set heater duty cycle
        if (gpio_write(HEATER_GPIO, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set heater duty cycle\n");
            continue;
        }

        // Log temperature and PWM duty cycle
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%FT%T", localtime(&now));
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temp, duty_cycle);
    }

    // Clean up
    fclose(log_file);
    gpio_close(HEATER_GPIO);
    max31855_close(0);
    spi_close(0);
    pigpio_stop();

    return 0;
}

