#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27

#define RED_DUTY 255
#define GREEN_DUTY 255
#define BLUE_DUTY 255

#define THRESHOLD_BLUE 40000
#define THRESHOLD_GREEN 59999

volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    gpioPWM(RED_PIN, RED_DUTY);
    gpioPWM(GREEN_PIN, GREEN_DUTY);
    gpioPWM(BLUE_PIN, BLUE_DUTY);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        FILE *temp_file = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
        if (temp_file == NULL) {
            fprintf(stderr, "Failed to open temperature file\n");
            continue;
        }

        int temp;
        if (fscanf(temp_file, "%d", &temp) != 1) {
            fprintf(stderr, "Failed to read temperature\n");
            fclose(temp_file);
            continue;
        }

        fclose(temp_file);

        if (temp < THRESHOLD_BLUE) {
            gpioPWM(RED_PIN, RED_DUTY);
            gpioPWM(GREEN_PIN, GREEN_DUTY);
            gpioPWM(BLUE_PIN, BLUE_DUTY);
        } else if (temp < THRESHOLD_GREEN) {
            gpioPWM(RED_PIN, RED_DUTY);
            gpioPWM(GREEN_PIN, GREEN_DUTY);
            gpioPWM(BLUE_PIN, BLUE_DUTY);
        } else {
            gpioPWM(RED_PIN, RED_DUTY);
            gpioPWM(GREEN_PIN, GREEN_DUTY);
            gpioPWM(BLUE_PIN, BLUE_DUTY);
        }

        printf("Temperature: %d m°C\n", temp);
        printf("RGB values: %d, %d, %d\n", RED_DUTY, GREEN_DUTY, BLUE_DUTY);

        sleep(0.5);
    }

    gpioPWM(RED_PIN, RED_DUTY);
    gpioPWM(GREEN_PIN, GREEN_DUTY);
    gpioPWM(BLUE_PIN, BLUE_DUTY);

    gpioTerminate();

    return 0;
}

