#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_PIN 4
#define DHT22_START_LOW_MS 1
#define DHT22_RESPONSE_BITS 40
#define DHT22_CHECKSUM_BITS 8
#define DHT22_RETRIES 3

#define HTTP_POST_URL "http://yourserver.com/api/humidity"

static int dht22_read(int pin, int *humidity, int *temperature) {
    int response[DHT22_RESPONSE_BITS];
    int checksum[DHT22_CHECKSUM_BITS];
    int i, j;

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    // Set the GPIO pin to output mode
    if (gpioSetMode(pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin %d to output mode\n", pin);
        return -1;
    }

    // Send the start signal
    if (gpioWrite(pin, PI_LOW) < 0) {
        fprintf(stderr, "Failed to write to GPIO pin %d\n", pin);
        return -1;
    }
    usleep(DHT22_START_LOW_MS * 1000);

    // Read the response
    for (i = 0; i < DHT22_RESPONSE_BITS; i++) {
        if (gpioRead(pin) < 0) {
            fprintf(stderr, "Failed to read from GPIO pin %d\n", pin);
            return -1;
        }
        response[i] = gpioRead(pin);
    }

    // Calculate the checksum
    for (i = 0; i < DHT22_CHECKSUM_BITS; i++) {
        checksum[i] = response[i] ^ response[i + 1];
    }

    // Validate the checksum
    for (i = 0; i < DHT22_CHECKSUM_BITS; i++) {
        if (checksum[i] != response[i + DHT22_RESPONSE_BITS - DHT22_CHECKSUM_BITS]) {
            fprintf(stderr, "Checksum mismatch\n");
            return -1;
        }
    }

    // Extract the humidity and temperature values
    *humidity = (response[0] << 8) | response[1];
    *temperature = (response[2] << 8) | response[3];

    return 0;
}

static int http_post(int humidity, int temperature) {
    CURL *curl;
    CURLcode res;
    char payload[1024];
    int retries = 0;

    // Initialize the curl library
    curl_global_init(CURL_GLOBAL_DEFAULT);

    // Create a new curl handle
    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to create curl handle\n");
        return -1;
    }

    // Set the URL and HTTP method
    curl_easy_setopt(curl, CURLOPT_URL, HTTP_POST_URL);
    curl_easy_setopt(curl, CURLOPT_POST, 1);

    // Set the payload
    snprintf(payload, sizeof(payload), "{\"humidity\": %d, \"temperature\": %d}", humidity, temperature);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, payload);

    // Set the HTTP headers
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    // Perform the HTTP request
    do {
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Failed to perform HTTP request: %s\n", curl_easy_strerror(res));
            retries++;
            if (retries >= DHT22_RETRIES) {
                return -1;
            }
            sleep(1);
        }
    } while (res != CURLE_OK);

    // Clean up
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    curl_global_cleanup();

    return 0;
}

static void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        // Clean up
        gpioTerminate();
        exit(0);
    }
}

int main(void) {
    int humidity, temperature;
    int retries = 0;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    // Set the GPIO pin to output mode
    if (gpioSetMode(DHT22_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin %d to output mode\n", DHT22_PIN);
        return -1;
    }

    // Read the humidity and temperature values
    do {
        if (dht22_read(DHT22_PIN, &humidity, &temperature) < 0) {
            fprintf(stderr, "Failed to read from DHT22 sensor\n");
            retries++;
            if (retries >= DHT22_RETRIES) {
                return -1;
            }
            sleep(1);
        }
    } while (retries < DHT22_RETRIES);

    // Post the readings to the server
    if (http_post(humidity, temperature) < 0) {
        fprintf(stderr, "Failed to post readings to server\n");
        return -1;
    }

    // Clean up
    gpioTerminate();

    return 0;
}

