static void init_bmp180(void) {
    int i2c_handle;
    int ret;

    // Open I2C bus
    i2c_handle = pigpio_i2c_open(1, BMP180_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", pigpio_error(i2c_handle));
        exit(1);
    }

    // Read calibration coefficients
    BMP180_CALIB_REG_TYPE calib_regs[BMP180_CALIB_REG_COUNT];
    ret = pigpio_i2c_read(i2c_handle, BMP180_CALIB_REG_START, calib_regs, BMP180_CALIB_REG_COUNT * BMP180_CALIB_REG_SIZE);
    if (ret < 0) {
        fprintf(stderr, "Error reading calibration coefficients: %s\n", pigpio_error(ret));
        exit(1);
    }

    // Validate calibration coefficients
    if (calib_regs[0] == 0 || calib_regs[1] == 0 || calib_regs[2] == 0) {
        fprintf(stderr, "Invalid calibration coefficients\n");
        exit(1);
    }

    // Close I2C bus
    pigpio_i2c_close(i2c_handle);
}

static void read_bmp180(void) {
    int i2c_handle;
    int ret;
    uint16_t raw_pressure;
    uint16_t raw_temperature;
    uint32_t pressure;
