    i2c_handle = pigpio_i2c_open(1, BMP180_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", pigpio_error(i2c_handle));
        exit(1);
    }

    // Read raw pressure and temperature
    ret = pigpio_i2c_read(i2c_handle, BMP180_CALIB_REG_START, &raw_pressure, 2);
    if (ret < 0) {
        fprintf(stderr, "Error reading raw pressure: %s\n", pigpio_error(ret));
        exit(1);
    }
    ret = pigpio_i2c_read(i2c_handle, BMP180_CALIB_REG_START + 2, &raw_temperature, 2);
    if (ret < 0) {
        fprintf(stderr, "Error reading raw temperature: %s\n", pigpio_error(ret));
        exit(1);
    }

    // Close I2C bus
    pigpio_i2c_close(i2c_handle);

