    read_bmp180();

    // Convert raw pressure and temperature to hPa and degC
    pressure = (raw_pressure * 30) / 1000;
    temperature = (raw_temperature * 10) / 1000;

    // Write to log file
    fprintf(log_file, "%s, %u, %u\n", time_str, pressure, temperature);

    // Close log file
    fclose(log_file);
}

int main(void) {
    int ret;

    // Initialize pigpio
    ret = pigpio_start(NULL, NULL);
    if (ret < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", pigpio_error(ret));
        exit(1);
    }

    // Initialize BMP180
    init_bmp180();

    // Set up button interrupt
    ret = pigpio_set_glitch_filter(BUTTON_GPIO, BUTTON_DEBOUNCE_US, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting glitch filter: %s\n", pigpio_error(ret));
        exit(1);
    }
    ret = pigpio_set_pull_up_down(BUTTON_GPIO, BUTTON_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Error setting pull-up/pull-down: %s\n", pigpio_error(ret));
        exit(1);
    }
    ret = pigpio_callback_ex(BUTTON_GPIO, EITHER_EDGE, button_isr);
    if (ret < 0) {
        fprintf(stderr, "Error setting up button interrupt: %s\n", pigpio_error(ret));
        exit(1);
    }

    // Main loop
    while (true) {
        if (logging_enabled) {
            log_bmp180();
        } else {
            printf("Logging disabled\n");
        }
        sleep(2);
    }

    // Clean up
    pigpio_stop();

    return 0;
}

