#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_PIN 4
#define DHT22_PULL_TIME 1000
#define DHT22_PULSE_TIME 20000
#define DHT22_RESPONSE_TIMEOUT 40000
#define DHT22_RETRY_COUNT 3
#define DHT22_RETRY_DELAY 2000
#define SERVER_URL "http://your-server.com/api/humidity"

static int gpio_fd;
static CURL *curl;
static char *server_url;

static void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpioTerminate();
        curl_global_cleanup();
        exit(0);
    }
}

static void init_gpio() {
    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        exit(1);
    }
}

static void init_curl() {
    curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "Failed to initialize cURL");
        exit(1);
    }
}

static void read_dht22() {
    int i, j;
    int data[5];
    int checksum;
    int response;

    // Pull the data line low for at least 1 ms
    gpioWrite(gpio_fd, DHT22_PIN, 0);
    usleep(DHT22_PULL_TIME);

    // Pulse the data line high for 20-40 µs
    gpioWrite(gpio_fd, DHT22_PIN, 1);
    usleep(DHT22_PULSE_TIME);

    // Read the 40-bit response
    for (i = 0; i < 5; i++) {
        data[i] = 0;
        for (j = 0; j < 8; j++) {
            data[i] <<= 1;
            data[i] |= gpioRead(gpio_fd, DHT22_PIN);
            usleep(1);
        }
    }

    // Calculate the checksum
    checksum = data[0] + data[1] + data[2] + data[3];
    if (checksum != data[4]) {
        syslog(LOG_ERR, "Checksum failure");
        return;
    }

    // Extract the humidity and temperature values
    int humidity = data[0] * 256 + data[1];
    int temperature = data[2] * 256 + data[3];

    // POST the humidity reading to the server
    char url[100];
    snprintf(url, sizeof(url), "%s?humidity=%d&temperature=%d", server_url, humidity, temperature);
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, "Content-Type: application/json");
    curl_easy_perform(curl);
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <url>]\n", argv[0]);
                exit(1);
        }
    }

    // Initialize GPIO and cURL
    init_gpio();
    init_curl();

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        read_dht22();
        sleep(10);
    }

    // Clean up on exit
    gpioTerminate();
    curl_global_cleanup();
    return 0;
}

