#include <sys/stat.h>
#include <fcntl.h>

#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define FAN_MAX_STATE_FILE "/sys/class/thermal/cooling_device0/max_state"
#define FAN_SPEED_MAP {0, 1, 2, 3}
#define FAN_SPEED_MAP_SIZE 4
#define FAN_SPEED_CHANGE_LOG_FILE "/var/log/fan_control.log"

int fan_state = 0;
int fan_max_state = 0;

void handle_sigint(int signal) {
    fan_state = 0;
    write_fan_state(fan_state);
    log_shutdown();
    exit(0);
}

void handle_sigterm(int signal) {
    fan_state = 0;
    write_fan_state(fan_state);
    log_shutdown();
    exit(0);
}

void write_fan_state(int state) {
    int fd = open(FAN_STATE_FILE, O_WRONLY);
    if (fd < 0) {
        perror("Error opening fan state file");
        exit(1);
    }

    char buf[10];
    sprintf(buf, "%d", state);
    if (write(fd, buf, strlen(buf)) < 0) {
        perror("Error writing fan state");
        exit(1);
    }

    close(fd);
}

void log_shutdown() {
    int fd = open(FAN_SPEED_CHANGE_LOG_FILE, O_WRONLY | O_APPEND);
    if (fd < 0) {
        perror("Error opening fan speed change log file");
        exit(1);
    }

    char buf[100];
    sprintf(buf, "Shutting down fan at %s", ctime(&time(NULL)));
    if (write(fd, buf, strlen(buf)) < 0) {
        perror("Error writing to fan speed change log file");
        exit(1);
    }

    close(fd);
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    int fd = open(FAN_MAX_STATE_FILE, O_RDONLY);
    if (fd < 0) {
        perror("Error opening fan max state file");
        exit(1);
    }

    char buf[10];
    if (read(fd, buf, sizeof(buf)) < 0) {
        perror("Error reading fan max state");
        exit(1);
    }

    fan_max_state = atoi(buf);
    close(fd);

    while (1) {
        int fd = open(CPU_TEMP_FILE, O_RDONLY);
        if (fd < 0) {
            perror("Error opening CPU temp file");
            exit(1);
        }

        char buf[10];
        if (read(fd, buf, sizeof(buf)) < 0) {
            perror("Error reading CPU temp");
            exit(1);
        }

        int cpu_temp = atoi(buf);
        close(fd);

        int new_fan_state = 0;
        if (cpu_temp < 45) {
            new_fan_state = 0;
        } else if (cpu_temp < 55) {
            new_fan_state = 1;
        } else if (cpu_temp < 65) {
            new_fan_state = 2;
        } else {
            new_fan_state = 3;
        }

        if (new_fan_state != fan_state) {
            fan_state = new_fan_state;
            write_fan_state(fan_state);

            int fd = open(FAN_SPEED_CHANGE_LOG_FILE, O_WRONLY | O_APPEND);
            if (fd < 0) {
                perror("Error opening fan speed change log file");
                exit(1);
            }

            char buf[100];
            sprintf(buf, "Fan speed changed to %d at %s", fan_state, ctime(&time(NULL)));
            if (write(fd, buf, strlen(buf)) < 0) {
                perror("Error writing to fan speed change log file");
                exit(1);
            }

            close(fd);
        }

        sleep(5);
    }

    return 0;
}

