#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define FAN_PIN 18
#define FAN_FREQ 25000
#define MIN_TEMP 40
#define MAX_TEMP 70
#define LOG_FILE "cooling_log.csv"

void sigint_handler(int signum) {
    printf("Shutting down...\n");
    pigpio_stop(FAN_PIN);
    fclose(log_file);
    exit(0);
}

int main() {
    int pigpio_handle;
    FILE *log_file;
    int temp;
    int duty_cycle;
    time_t timestamp;

    // Initialize pigpio
    if ((pigpio_handle = pigpio_start()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up PWM
    if (pigpio_set_mode(pigpio_handle, FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM mode\n");
        return 1;
    }
    if (pigpio_set_PWM_frequency(pigpio_handle, FAN_PIN, FAN_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return 1;
    }

    // Set up logging
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }
    fprintf(log_file, "timestamp,temp,duty_cycle\n");

    // Set up signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        // Read temperature
        if (fscanf(fopen("/sys/class/thermal/thermal_zone0/temp", "r"), "%d", &temp) != 1) {
            fprintf(stderr, "Failed to read temperature\n");
            return 1;
        }

        // Calculate duty cycle
        if (temp < MIN_TEMP) {
            duty_cycle = 0;
        } else if (temp > MAX_TEMP) {
            duty_cycle = 100;
        } else {
            duty_cycle = (temp - MIN_TEMP) * 100 / (MAX_TEMP - MIN_TEMP);
        }

        // Set PWM duty cycle
        if (pigpio_set_PWM_dutycycle(pigpio_handle, FAN_PIN, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            return 1;
        }

        // Log data
        timestamp = time(NULL);
        fprintf(log_file, "%ld,%d,%d\n", timestamp, temp, duty_cycle);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    pigpio_stop(FAN_PIN);
    fclose(log_file);

    return 0;
}

