#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR_SLF3S_1300F 0x08
#define I2C_ADDR_SLF3S_1300F_2 0x09
#define I2C_ADDR_SF06_MULTIPLEXER 0x08

#define CMD_SLF3S_1300F_CONTINUOUS_MEASUREMENT 0x3608
#define CMD_SLF3S_1300F_STOP_MEASUREMENT 0x3609

#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

#define FLOW_RATE_CONVERSION_FACTOR 0.01

#define LOG_FILE "flow_log.txt"

#define MAX_RETRIES 3

static int i2c_handle;
static int i2c_handle_2;

static int read_sensor(int i2c_handle, uint8_t addr, uint8_t cmd, uint8_t *data, uint8_t len) {
    uint8_t crc = CRC_INIT;
    uint8_t crc_read;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (pi_i2c_write(i2c_handle, addr, &cmd, 1) != 0) {
            fprintf(stderr, "Error writing to I2C bus\n");
            return -1;
        }

        if (pi_i2c_read(i2c_handle, addr, data, len) != 0) {
            fprintf(stderr, "Error reading from I2C bus\n");
            return -1;
        }

        crc_read = data[len - 1];
        for (int i = 0; i < len - 1; i++) {
            crc = crc_table[crc ^ data[i]];
        }

        if (crc == crc_read) {
            return 0;
        }

        retries++;
    }

    return -1;
}

static void sigint_handler(int signum) {
    if (i2c_handle != 0) {
        pi_i2c_close(i2c_handle);
    }

    if (i2c_handle_2 != 0) {
        pi_i2c_close(i2c_handle_2);
    }

    exit(0);
}

int main(int argc, char *argv[]) {
    uint8_t data[3];
    uint8_t data_2[3];
    uint8_t crc;
    uint8_t crc_read;
    int retries = 0;

    if (argc != 1) {
        fprintf(stderr, "Usage: %s\n", argv[0]);
        return 1;
    }

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Error setting signal handler\n");
        return 1;
    }

    if (signal(SIGTERM, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Error setting signal handler\n");
        return 1;
    }

    if ((i2c_handle = pi_i2c_open(I2C_BUS, I2C_ADDR_SF06_MULTIPLEXER)) == 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        return 1;
    }

    if ((i2c_handle_2 = pi_i2c_open(I2C_BUS, I2C_ADDR_SF06_MULTIPLEXER)) == 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        return 1;
    }

    while (1) {
        if (read_sensor(i2c_handle, I2C_ADDR_SLF3S_1300F, CMD_SLF3S_1300F_CONTINUOUS_MEASUREMENT, data, 3) != 0) {
            fprintf(stderr, "Error reading from sensor 1\n");
            continue;
        }

        if (read_sensor(i2c_handle_2, I2C_ADDR_SLF3S_1300F_2, CMD_SLF3S_1300F_CONTINUOUS_MEASUREMENT, data_2, 3) != 0) {
            fprintf(stderr, "Error reading from sensor 2\n");
            continue;
        }

        crc = CRC_INIT;
        crc_read = data[2];
        for (int i = 0; i < 2; i++) {
            crc = crc_table[crc ^ data[i]];
        }

        if (crc != crc_read) {
            fprintf(stderr, "CRC check failed for sensor 1\n");
            continue;
        }

        crc = CRC_INIT;
        crc_read = data_2[2];
        for (int i = 0; i < 2; i++) {
            crc = crc_table[crc ^ data_2[i]];
        }

        if (crc != crc_read) {
            fprintf(stderr, "CRC check failed for sensor 2\n");
            continue;
        }

        float flow_rate_1 = (data[0] << 8) | data[1];
        float flow_rate_2 = (data_2[0] << 8) | data_2[1];

        flow_rate_1 *= FLOW_RATE_CONVERSION_FACTOR;
        flow_rate_2 *= FLOW_RATE_CONVERSION_FACTOR;

        time_t t = time(NULL);
        struct tm *tm = localtime(&t);

        char buf[100];
        snprintf(buf, sizeof(buf), "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, flow_rate_1, flow_rate_2);

        FILE *fp = fopen(LOG_FILE, "a");
        if (fp == NULL) {
            fprintf(stderr, "Error opening log file\n");
            continue;
        }

        fprintf(fp, "%s", buf);
        fclose(fp);
    }

    return 0;
}

