#define GPIO_A 17
#define GPIO_B 18

#define STATE_A 0
#define STATE_B 1
#define STATE_AB 2
#define STATE_BA 3

#define PULSES_PER_REV 360

int main(void) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set internal pull-up resistors on GPIO pins
    gpioSetPullUpDown(GPIO_A, PI_PUD_UP);
    gpioSetPullUpDown(GPIO_B, PI_PUD_UP);

    // Set GPIO pins as inputs
    gpioSetMode(GPIO_A, PI_INPUT);
    gpioSetMode(GPIO_B, PI_INPUT);

    // Initialize state machine
    int state = STATE_A;
    int count = 0;
    int position = 0;

    // Open file for logging
    FILE *fp = fopen("encoder_log.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for logging\n");
        return 1;
    }

    // Main loop
    while (true) {
        // Read GPIO pins
        int a = gpioRead(GPIO_A);
        int b = gpioRead(GPIO_B);

        // Update state machine
        switch (state) {
            case STATE_A:
                if (a == 0 && b == 1) {
                    state = STATE_B;
                } else if (a == 1 && b == 0) {
                    state = STATE_AB;
                }
                break;
            case STATE_B:
                if (a == 1 && b == 0) {
                    state = STATE_A;
                } else if (a == 0 && b == 1) {
                    state = STATE_BA;
                }
                break;
            case STATE_AB:
                if (a == 0 && b == 1) {
                    state = STATE_B;
                } else if (a == 1 && b == 0) {
                    state = STATE_A;
                }
                break;
            case STATE_BA:
                if (a == 1 && b == 0) {
                    state = STATE_A;
                } else if (a == 0 && b == 1) {
                    state = STATE_B;
                }
                break;
        }

        // Increment count and position
        if (state == STATE_A || state == STATE_B) {
            count++;
            position = (count * 360) / PULSES_PER_REV;
        }

        // Log state change
        fprintf(fp, "%ld, %d, %d\n", time(NULL), state, position);

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up
    gpioTerminate();
    fclose(fp);

    return 0;
}

