#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define FIFO_DATA_REG 0x60
#define LED_GPIO 17
#define THRESHOLD 2000

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO line for LED
    struct gpiod_line *led_line = gpiod_line_open(LED_GPIO, "led", GPIOD_OUT);
    if (!led_line) {
        perror("Failed to open GPIO line for LED");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("adpd144ri_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_close(led_line);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Read FIFO data register
        uint8_t buf[2];
        if (i2c_smbus_read_i2c_block_data(i2c_fd, FIFO_DATA_REG, 2, buf) < 0) {
            perror("Failed to read FIFO data register");
            continue;
        }

        // Extract red and IR channel data
        uint16_t red = (buf[0] << 8) | buf[1];
        uint16_t ir = (buf[2] << 8) | buf[3];

        // Check if IR reading exceeds threshold
        if (ir > THRESHOLD) {
            // Trigger LED
            gpiod_line_set_value(led_line, 1);
        } else {
            // Turn off LED
            gpiod_line_set_value(led_line, 0);
        }

        // Log data to file
        fprintf(log_file, "%ld,%u,%u\n", time(NULL), red, ir);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_close(led_line);
    close(i2c_fd);

    return 0;
}

