#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>

#define GPIO_PIN 18
#define RPM_LOG_FILE "rpm_log.txt"

static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static uint32_t pulse_count = 0;

void handle_interrupt(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        pigpio_stop(0);
        fclose(rpm_log_file);
        pthread_mutex_destroy(&pulse_mutex);
        exit(0);
    }
}

int main(int argc, char *argv[]) {
    int gpio_handle;
    FILE *rpm_log_file;

    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if ((gpio_handle = pigpio_gpio(GPIO_PIN)) < 0) {
        fprintf(stderr, "Failed to get GPIO handle for pin %d\n", GPIO_PIN);
        return 1;
    }

    if (pigpio_set_mode(gpio_handle, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        return 1;
    }

    if (pigpio_set_pull_up_down(gpio_handle, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set GPIO %d pull-down\n", GPIO_PIN);
        return 1;
    }

    if (pigpio_callback_ex(gpio_handle, handle_interrupt) < 0) {
        fprintf(stderr, "Failed to register ISR for GPIO %d\n", GPIO_PIN);
        return 1;
    }

    if ((rpm_log_file = fopen(RPM_LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open RPM log file\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        pthread_mutex_lock(&pulse_mutex);
        uint32_t count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        if (count > 0) {
            double rpm = (count * 60.0) / 1000000.0;
            fprintf(rpm_log_file, "%.2f RPM\n", rpm);
            fflush(rpm_log_file);
        } else {
            fprintf(rpm_log_file, "0.00 RPM\n");
            fflush(rpm_log_file);
        }

        sleep(1);
    }

    return 0;
}

