#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_ADDR 0x39
#define PART_ID_REG 0x00
#define FIFO_DATA_REG 0x01
#define IR_CHANNEL 0x02
#define RED_CHANNEL 0x03
#define THRESHOLD 2000

int main(void) {
    // Open I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO line for LED
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }
    struct gpiod_line *line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    gpiod_line_request_output(line, "adpd144ri", 0);

    // Read PART_ID register to verify sensor is present
    uint8_t part_id;
    if (read(i2c_fd, &part_id, 1) != 1) {
        perror("Failed to read PART_ID register");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    if (part_id != 0x44) {
        fprintf(stderr, "Invalid PART_ID: 0x%02x\n", part_id);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("adpd144ri_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (1) {
        // Read FIFO data registers
        uint8_t fifo_data[4];
        if (read(i2c_fd, fifo_data, 4) != 4) {
            perror("Failed to read FIFO data registers");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            close(i2c_fd);
            fclose(log_file);
            return 1;
        }

        // Extract red and IR channel data
        uint16_t red = (fifo_data[RED_CHANNEL] << 8) | fifo_data[RED_CHANNEL + 1];
        uint16_t ir = (fifo_data[IR_CHANNEL] << 8) | fifo_data[IR_CHANNEL + 1];

        // Log data to file
        fprintf(log_file, "%ld,%d,%d\n", time(NULL), red, ir);

        // Trigger LED if IR reading exceeds threshold
        if (ir > THRESHOLD) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up on exit
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

void sigint_handler(int signum) {
    // Clean up on signal
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    fclose(log_file);

    // Exit program
    exit(0);
}

