#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define MAX9814_OUT_PIN 17
#define MAX9814_GAIN_PIN 18
#define MAX9814_GAIN_60DB 0
#define MAX9814_GAIN_90DB 1
#define MAX9814_GAIN_120DB 2
#define MAX9814_GAIN_150DB 3

#define SAMPLE_INTERVAL 10
#define LOG_FILE "audio_log.txt"

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Initialize libgpiod
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        return 1;
    }

    // Set up GPIO pins
    struct gpiod_line *out_line = gpiod_chip_get_line(chip, MAX9814_OUT_PIN);
    struct gpiod_line *gain_line = gpiod_chip_get_line(chip, MAX9814_GAIN_PIN);
    if (!out_line || !gain_line) {
        fprintf(stderr, "Error: Failed to get GPIO lines\n");
        return 1;
    }

    // Set GPIO direction
    if (gpiod_line_request_input(out_line, "max9814-out") != 0) {
        fprintf(stderr, "Error: Failed to set GPIO direction\n");
        return 1;
    }

    // Set GPIO value
    if (gpiod_line_set_value(gain_line, MAX9814_GAIN_60DB) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO value\n");
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        return 1;
    }

    // Print startup message
    fprintf(log_file, "Starting audio logging\n");

    // Main loop
    while (running) {
        // Read GPIO value
        int value = gpiod_line_get_value(out_line);
        if (value < 0) {
            fprintf(stderr, "Error: Failed to read GPIO value\n");
            return 1;
        }

        // Check for rising edge
        if (value == 1) {
            // Get current time
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);

            // Log peak sound event
            fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d LEVEL 1\n",
                    ts.tm_year + 1900, ts.tm_mon + 1, ts.tm_mday,
                    ts.tm_hour, ts.tm_min, ts.tm_sec);
        }

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(out_line);
    gpiod_line_release(gain_line);
    gpiod_chip_close(chip);

    return 0;
}

