#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x36
#define CMD_START_CONTINUOUS_MEASUREMENT 0x3608
#define CMD_READ_RAW_FLOW_VALUE 0x3609
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

#define FLOW_RATE_CONVERSION_FACTOR 1000.0

int main(void) {
    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    int i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Initialize the sensor
    uint8_t cmd[2] = {CMD_START_CONTINUOUS_MEASUREMENT};
    if (pigpio_i2c_write(i2c_handle, cmd, 2) < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read raw flow value
        uint8_t raw_flow_value[3];
        if (pigpio_i2c_read(i2c_handle, raw_flow_value, 3) < 0) {
            fprintf(stderr, "Failed to read raw flow value\n");
            continue;
        }

        // Validate CRC
        uint8_t crc = pigpio_crc8(raw_flow_value, 2, CRC_POLYNOMIAL, CRC_INITIAL_VALUE);
        if (crc != raw_flow_value[2]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        // Convert raw flow value to flow rate
        int16_t flow_value = (raw_flow_value[0] << 8) | raw_flow_value[1];
        float flow_rate = flow_value / FLOW_RATE_CONVERSION_FACTOR;

        // Log flow rate
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(log_file, "%s,%.2f\n", time_str, flow_rate);
        fflush(log_file);

        // Sleep for 1000 ms
        usleep(1000000);
    }

    // Clean up
    pigpio_i2c_close(i2c_handle);
    fclose(log_file);
    pigpio_stop();

    return 0;
}

