#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x70
#define REG_STATE 0x00
#define REG_TVOC 0x01
#define REG_ECO2 0x05

#define TVOC_BYTES 2
#define ECO2_BYTES 2

#define IAQ_MIN 0
#define IAQ_MAX 100

int main(void) {
    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    int i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("air_quality_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Read sensor state
    uint8_t state[7];
    if (pigpio_i2c_read(i2c_handle, REG_STATE, state, 7) < 0) {
        fprintf(stderr, "Failed to read sensor state\n");
        return 1;
    }

    // Extract TVOC and eCO2 values
    uint16_t tvoc = (state[REG_TVOC] << 8) | state[REG_TVOC + 1];
    uint16_t eco2 = (state[REG_ECO2] << 8) | state[REG_ECO2 + 1];

    // Compute IAQ index
    float iaq = clamp(100 - (tvoc / 10.0) - ((eco2 - 400) / 50.0), IAQ_MIN, IAQ_MAX);

    // Log IAQ, TVOC, and eCO2 values
    fprintf(log_file, "%s, %d, %d, %f\n", ctime(&time(NULL)), tvoc, eco2, iaq);

    // Close I2C bus and log file
    pigpio_i2c_close(i2c_handle);
    fclose(log_file);

    // Handle SIGINT gracefully
    signal(SIGINT, sigint_handler);

    return 0;
}

void sigint_handler(int signal) {
    // Close I2C bus and log file
    pigpio_i2c_close(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    pigpio_stop();

    // Exit program
    exit(0);
}

float clamp(float value, float min, float max) {
    return value < min ? min : value > max ? max : value;
}

