#define TTP223_TAMPER_LINE 17
#define TTP223_TAMPER_CONSUMER "ttp223_tamper"
#define TTP223_TAMPER_POLL_INTERVAL 100
#define TTP223_TAMPER_DEBOUNCE_TIME 5

static volatile sig_atomic_t running = 1;

static void handle_signal(int signum) {
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    int ret;

    // Open gpiochip0 by name
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Request the line as input with the consumer label "ttp223_tamper"
    line = gpiod_chip_get_line(chip, TTP223_TAMPER_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", TTP223_TAMPER_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, TTP223_TAMPER_CONSUMER);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", TTP223_TAMPER_LINE, strerror(errno));
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Poll the line every 100 ms
    while (running) {
        ret = gpiod_line_get_value(line, &ts);
        if (ret < 0) {
            fprintf(stderr, "Failed to get line value: %s\n", strerror(errno));
            break;
        }

        if (ts.tv_sec >= TTP223_TAMPER_DEBOUNCE_TIME) {
            printf("Intrusion alert!\n");
            ts.tv_sec = 0;
        }

        usleep(TTP223_TAMPER_POLL_INTERVAL * 1000);
    }

    // Clean up
    gpiod_line_free(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

