#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>

#define SAMPLE_RATE 48000
#define BUFFER_SIZE 1024
#define CHANNELS 2
#define BITS_PER_SAMPLE 16
#define BYTES_PER_SAMPLE 2

static volatile sig_atomic_t stop = 0;

static void sigint_handler(int signum) {
    stop = 1;
}

int main(int argc, char **argv) {
    // Set up signal handling
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    // Set up GPIO for L/R select pin
    gpiod_chip_t *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }
    gpiod_line_t *line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }
    gpiod_line_request_output(line, "inmp441", 0);

    // Set up ALSA for I2S
    snd_pcm_t *handle;
    snd_pcm_hw_params_t *params;
    snd_pcm_hw_params_alloca(&params);
    snd_pcm_hw_params_any(handle, params);
    snd_pcm_hw_params_set_access(handle, params, SND_PCM_ACCESS_RW_INTERLEAVED);
    snd_pcm_hw_params_set_format(handle, params, SND_PCM_FORMAT_S16_LE);
    snd_pcm_hw_params_set_rate(handle, params, SAMPLE_RATE, 0);
    snd_pcm_hw_params_set_channels(handle, params, CHANNELS);
    snd_pcm_hw_params(handle, params);

    // Set up buffer for I2S data
    uint8_t *buffer = malloc(BUFFER_SIZE * BYTES_PER_SAMPLE * CHANNELS);
    if (!buffer) {
        fprintf(stderr, "Failed to allocate buffer\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up file for PCM data
    FILE *fp = fopen("audio_capture.pcm", "wb");
    if (!fp) {
        fprintf(stderr, "Failed to open file\n");
        free(buffer);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Start capture
    while (!stop) {
        // Read I2S data
        ssize_t bytes_read = snd_pcm_readi(handle, buffer, BUFFER_SIZE);
        if (bytes_read < 0) {
            fprintf(stderr, "Failed to read I2S data\n");
            break;
        }

