#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define GPIO_TRIGGER 23
#define GPIO_DATA_READY 24
#define HEADER_MAGIC 0x52444144
#define HEADER_SIZE 12
#define FRAME_SIZE 32768
#define FRAME_COUNT 64
#define FRAME_PERIOD 100

typedef struct {
    uint32_t magic;
    uint64_t timestamp;
    uint32_t start_freq;
    uint32_t end_freq;
    uint32_t chirps;
    uint32_t samples;
    uint32_t frame_period;
} header_t;

void handle_sigint(int signal) {
    printf("Received signal %d, closing SPI and GPIO\n", signal);
    gpioTerminate();
    close(spi_fd);
    close(file_fd);
    exit(0);
}

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI0.0 at 1 MHz mode 0
    int spi_fd = pigpio_spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI0.0\n");
        return 1;
    }

    // Open a binary log file
    int file_fd = open("log.bin", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (file_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Write a header to the log file
    header_t header = {
        .magic = HEADER_MAGIC,
        .timestamp = time(NULL),
        .start_freq = 77000000,
        .end_freq = 79000000,
        .chirps = 64,
        .samples = 256,
        .frame_period = 100
    };
    if (write(file_fd, &header, HEADER_SIZE) != HEADER_SIZE) {
        fprintf(stderr, "Failed to write header to log file\n");
        return 1;
    }

    // Set up GPIO trigger and data ready interrupts
    if (gpioSetMode(GPIO_TRIGGER, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_TRIGGER);
        return 1;
    }
    if (gpioSetMode(GPIO_DATA_READY, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_DATA_READY);
        return 1;
    }
    if (gpioSetISRFunc(GPIO_DATA_READY, PI_FALLING_EDGE, NULL, NULL) < 0) {
        fprintf(stderr, "Failed to set GPIO %d ISR function\n", GPIO_DATA_READY);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Main loop
    uint32_t frame_count = 0;
    while (1) {
        // Assert GPIO trigger to request a frame
        if (gpioWrite(GPIO_TRIGGER, PI_HIGH) < 0) {
            fprintf(stderr, "Failed to write to GPIO %d\n", GPIO_TRIGGER);
            return 1;
        }

        // Wait for data ready interrupt
        if (gpioWaitForInterrupt(GPIO_DATA_READY, PI_FALLING_EDGE, 1000) < 0) {
            fprintf(stderr, "Failed to wait for data ready interrupt\n");
            return 1;
        }

        // Read 32768 bytes of heatmap data via SPI full-duplex transfer
        uint8_t *data = malloc(FRAME_SIZE);
        if (data == NULL) {
            fprintf(stderr, "Failed to allocate memory for frame data\n");
            return 1;
        }
        if (pigpio_spi_xfer(spi_fd, data, FRAME_SIZE) != FRAME_SIZE) {
            fprintf(stderr, "Failed to read frame data\n");
            return 1;
        }

        // Log the frame with a per-frame timestamp and frame number
        uint64_t timestamp = time(NULL);
        header_t frame_header = {
            .magic = HEADER_MAGIC,
            .timestamp = timestamp,
            .frame_number = frame_count
        };
        if (write(file_fd, &frame_header, HEADER_SIZE) != HEADER_SIZE) {
            fprintf(stderr, "Failed to write frame header to log file\n");
            return 1;
        }
        if (write(file_fd, data, FRAME_SIZE) != FRAME_SIZE) {
            fprintf(stderr, "Failed to write frame data to log file\n");
            return 1;
        }

        // Increment frame count
        frame_count++;

        // Free memory
        free(data);
    }

    // Close SPI and GPIO
    gpioTerminate();
    close(spi_fd);
    close(file_fd);

    return 0;
}

