#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NAME "gpio20"
#define POLL_INTERVAL 100

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    int ret;

    // Set up signal handling
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP_NAME);
        return 1;
    }

    // Open the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE_NAME);
    if (!line) {
        fprintf(stderr, "Error opening GPIO line %s\n", GPIO_LINE_NAME);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up the GPIO line as an input
    ret = gpiod_line_request_input(line, "flame_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting input on GPIO line %s\n", GPIO_LINE_NAME);
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Poll the GPIO line every POLL_INTERVAL milliseconds
    while (running) {
        // Read the GPIO line
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            fprintf(stderr, "Error reading GPIO line %s\n", GPIO_LINE_NAME);
            gpiod_line_close(line);
            gpiod_chip_close(chip);
            fclose(log_file);
            return 1;
        }

        // Check if the flame is detected
        if (ret == 1) {
            // Get the current time
            clock_gettime(CLOCK_REALTIME, &ts);

            // Log the flame detection
            fprintf(log_file, "%ld.%ld: Flame detected\n", ts.tv_sec, ts.tv_nsec);
        }

        // Sleep for POLL_INTERVAL milliseconds
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    gpiod_line_close(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

