#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

#define OPT3001_ADDR 0x44
#define OPT3001_REG_RESULT 0x00
#define OPT3001_REG_CONFIG 0x01
#define OPT3001_REG_LOW_LIMIT 0x02
#define OPT3001_REG_HIGH_LIMIT 0x03

#define OPT3001_CFG_CONT_CONV 0x8000
#define OPT3001_CFG_AUTO_RANGE 0x4000
#define OPT3001_CFG_CTIME_100MS 0x0000

#define OPT3001_LUX_SCALE 0.01

int main(void) {
    // Initialize pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus 1
    int i2c_handle = pigpio_i2c_open(1, 0, 0, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }

    // Set up OPT3001 sensor
    uint16_t config = OPT3001_CFG_CONT_CONV | OPT3001_CFG_AUTO_RANGE | OPT3001_CFG_CTIME_100MS;
    if (pigpio_i2c_write_reg_16(i2c_handle, OPT3001_ADDR, OPT3001_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Failed to configure OPT3001 sensor\n");
        return 1;
    }

    // Open file for logging
    FILE *fp = fopen("light_data.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for logging\n");
        return 1;
    }

    // Set up signal handler for clean shutdown
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (1) {
        // Read result register
        uint16_t result = pigpio_i2c_read_reg_16(i2c_handle, OPT3001_ADDR, OPT3001_REG_RESULT);
        if (result < 0) {
            fprintf(stderr, "Failed to read result register\n");
            return 1;
        }

        // Unpack exponent and mantissa
        int exponent = (result >> 12) & 0x0F;
        int mantissa = result & 0x0FFF;

        // Compute lux
        double lux = OPT3001_LUX_SCALE * pow(2, exponent) * mantissa;

        // Log reading
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
        fprintf(fp, "%s,%.2f\n", timestamp, lux);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    fclose(fp);
    pigpio_i2c_close(i2c_handle);
    pigpio_stop();

    return 0;
}

void sigint_handler(int signum) {
    // Clean up
    fclose(fp);
    pigpio_i2c_close(i2c_handle);
    pigpio_stop();

    exit(0);
}

