#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NAME "gpio17"
#define GPIO_LINE_BIAS GPIOD_LINE_BIAS_PULL_UP
#define GPIO_LINE_DIRECTION GPIOD_LINE_DIRECTION_INPUT

volatile sig_atomic_t sigint_flag = 0;

void sigint_handler(int signum) {
    sigint_flag = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_config config;
    struct gpiod_line_settings settings;
    struct gpiod_line_request_config request_config;
    struct gpiod_line_request *request;
    int value;
    char timestamp[20];

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP_NAME);
        return 1;
    }

    // Set up the GPIO line configuration
    config.name = GPIO_LINE_NAME;
    config.bias = GPIO_LINE_BIAS;
    config.direction = GPIO_LINE_DIRECTION;

    // Set up the GPIO line settings
    settings.name = GPIO_LINE_NAME;
    settings.bias = GPIO_LINE_BIAS;
    settings.direction = GPIO_LINE_DIRECTION;

    // Set up the GPIO line request configuration
    request_config.name = GPIO_LINE_NAME;
    request_config.bias = GPIO_LINE_BIAS;
    request_config.direction = GPIO_LINE_DIRECTION;

    // Request the GPIO line
    request = gpiod_chip_request_lines(chip, &request_config, 1);
    if (!request) {
        fprintf(stderr, "Error requesting GPIO line %s\n", GPIO_LINE_NAME);
        gpiod_chip_close(chip);
        return 1;
    }

    // Get the GPIO line
    line = gpiod_line_request_get_value(request, 0);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %s\n", GPIO_LINE_NAME);
        gpiod_line_request_release(request);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!sigint_flag) {
        // Read the GPIO line value
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line %s\n", GPIO_LINE_NAME);
            gpiod_line_request_release(request);
            gpiod_chip_close(chip);
            return 1;
        }

        // Print the flame detection status to the console
        if (value == 0) {
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time(NULL));
            printf("%s: Flame Detected: YES\n", timestamp);
        } else {
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time(NULL));
            printf("%s: Flame Detected: NO\n", timestamp);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpiod_line_request_release(request);
    gpiod_chip_close(chip);

    return 0;
}

