#include <signal.h>
#include <pigpio.h>

#define LEFT_GPIO 17
#define CENTER_GPIO 18
#define RIGHT_GPIO 27

void handle_sigint(int signal) {
    printf("Received SIGINT, shutting down...\n");
    gpioTerminate();
    exit(0);
}

void handle_sigterm(int signal) {
    printf("Received SIGTERM, shutting down...\n");
    gpioTerminate();
    exit(0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    if (gpioSetMode(LEFT_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", LEFT_GPIO);
        gpioTerminate();
        exit(1);
    }

    if (gpioSetMode(CENTER_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", CENTER_GPIO);
        gpioTerminate();
        exit(1);
    }

    if (gpioSetMode(RIGHT_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", RIGHT_GPIO);
        gpioTerminate();
        exit(1);
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    while (1) {
        int left = gpioRead(LEFT_GPIO);
        int center = gpioRead(CENTER_GPIO);
        int right = gpioRead(RIGHT_GPIO);

        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);

        usleep(50000);
    }

    gpioTerminate();
    return 0;
}

