#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define NUM_CHANNELS 8

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_CHANNELS];
    int i;

    // Set up signal handler for SIGINT
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Request lines for each channel
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            fprintf(stderr, "Error requesting line %d\n", i);
            goto error;
        }
    }

    // Set up line configuration
    for (i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_request_output(lines[i], "touch", 0);
        if (gpiod_line_request_output(lines[i], "touch", 0) < 0) {
            fprintf(stderr, "Error setting line %d as output\n", i);
            goto error;
        }
    }

    // Main loop
    while (running) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Error reading line %d\n", i);
                goto error;
            }
            printf("Channel %d: %d\n", i, value);
        }
        usleep(100000);
    }

error:
    // Release resources
    for (i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

