    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    for (i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(gpio_channels[i], PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", gpio_channels[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPullUpDown(gpio_channels[i], PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Failed to set pull-down resistor for GPIO %d\n", gpio_channels[i]);
            gpioTerminate();
            return 1;
        }
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            gpio_states[i] = gpioRead(gpio_channels[i]);
        }
        printf("[+%d ms] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               gpioTick(),
               gpio_states[0],
               gpio_states[1],
               gpio_states[2],
               gpio_states[3],
               gpio_states[4],
               gpio_states[5],
               gpio_states[6],
               gpio_states[7]);
        gpioDelay(100000);
    }

    gpioTerminate();
    return 0;
