#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL 50

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open the gpiochip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: unable to open gpiochip\n");
        return 1;
    }

    // Request lines
    struct gpiod_line *lines[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: unable to get line %d\n", i);
            return 1;
        }

        // Configure line as input with bias disabled
        if (gpiod_line_request_input(lines[i], "touch_sensor") != 0) {
            fprintf(stderr, "Error: unable to request input for line %d\n", i);
            return 1;
        }
    }

    // Poll all channels every POLL_INTERVAL ms
    while (running) {
        // Get current time
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        // Read all channels
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Error: unable to read value for line %d\n", i);
                return 1;
            }

            // Log binary state of channel to console
            printf("%s, %d\n", asctime(gmtime(&ts.tv_sec)), value);
        }

        // Sleep for POLL_INTERVAL ms
        usleep(POLL_INTERVAL * 1000);
    }

    // Release resources
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

