#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TILT_PIN 4
#define TILT_PULL_UP 1
#define POLL_INTERVAL 100

void sigint_handler(int signum) {
    printf("Exiting...\n");
    gpioTerminate();
    exit(0);
}

int main(void) {
    int gpio_handle;
    int tilt_state;
    struct timespec ts;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(1);
    }

    // Setup GPIO pin
    gpio_handle = gpioSetMode(TILT_PIN, PI_INPUT);
    if (gpio_handle < 0) {
        fprintf(stderr, "Failed to set GPIO pin mode\n");
        gpioTerminate();
        exit(1);
    }

    // Setup pull-up resistor
    if (gpioSetPullUpDown(gpio_handle, TILT_PULL_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioTerminate();
        exit(1);
    }

    // Setup SIGINT handler
    signal(SIGINT, sigint_handler);

    // Print startup banner
    printf("Starting tilt sensor polling...\n");

    // Poll sensor every 100 ms
    while (1) {
        // Read GPIO pin
        tilt_state = gpioRead(gpio_handle);
        if (tilt_state < 0) {
            fprintf(stderr, "Failed to read GPIO pin\n");
            gpioTerminate();
            exit(1);
        }

        // Print timestamped message
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%ld: %s\n", ts.tv_sec, ts.tv_nsec, tilt_state ? "Not Tilted" : "Tilted");

        // Flush stdout
        fflush(stdout);

        // Sleep for 100 ms
        usleep(POLL_INTERVAL * 1000);
    }

    // Cleanup
    gpioTerminate();

    return 0;
}

