#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60

#define HW_KEY_REG 0x17
#define CHLIST_REG 0x01
#define ALS_FORCE_CMD 0x06

#define UV_INDEX_REG 0x07
#define ALS_VIS_REG 0x08

#define PART_ID_REG 0x00
#define PART_ID_EXP 0x45

#define CSV_FILE "uv_als_log.csv"

int main(void) {
    int fd;
    uint8_t buf[2];
    uint16_t uv_index, als_visible;
    time_t t;
    struct tm *tm;
    char timestamp[20];

    // Initialize the I2C bus
    if ((fd = pigpio_i2c_open(I2C_BUS, I2C_ADDR)) < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Verify the sensor's PART ID
    if (pigpio_i2c_read(fd, PART_ID_REG, buf, 1) != 1) {
        fprintf(stderr, "Error reading PART ID: %s\n", strerror(errno));
        goto cleanup;
    }
    if (buf[0] != PART_ID_EXP) {
        fprintf(stderr, "Invalid PART ID: 0x%02x\n", buf[0]);
        goto cleanup;
    }

    // Write 0x17 to the HW_KEY register
    if (pigpio_i2c_write(fd, HW_KEY_REG, 0x17) != 1) {
        fprintf(stderr, "Error writing to HW_KEY register: %s\n", strerror(errno));
        goto cleanup;
    }

    // Configure the CHLIST register to enable UV and ALS_VIS
    if (pigpio_i2c_write(fd, CHLIST_REG, 0x01) != 1) {
        fprintf(stderr, "Error writing to CHLIST register: %s\n", strerror(errno));
        goto cleanup;
    }

    // Use the ALS_FORCE command to trigger measurements
    if (pigpio_i2c_write(fd, ALS_FORCE_CMD, 0x06) != 1) {
        fprintf(stderr, "Error writing to ALS_FORCE command: %s\n", strerror(errno));
        goto cleanup;
    }

    // Open the CSV file for writing
    if ((fd = fopen(CSV_FILE, "w")) == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        goto cleanup;
    }

    // Continuously read UV index and Visible ALS data
    while (1) {
        // Read the UV index
        if (pigpio_i2c_read(fd, UV_INDEX_REG, buf, 2) != 2) {
            fprintf(stderr, "Error reading UV index: %s\n", strerror(errno));
            goto cleanup;
        }
        uv_index = (buf[0] << 8) | buf[1];

        // Read the Visible ALS data
        if (pigpio_i2c_read(fd, ALS_VIS_REG, buf, 2) != 2) {
            fprintf(stderr, "Error reading Visible ALS data: %s\n", strerror(errno));
            goto cleanup;
        }
        als_visible = (buf[0] << 8) | buf[1];

        // Print the readings to the console
        printf("UV index: %d, Visible ALS: %d\n", uv_index, als_visible);

        // Log the readings to the CSV file
        t = time(NULL);
        tm = localtime(&t);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(fd, "%s, %d, %d\n", timestamp, uv_index, als_visible);

        // Sleep for 1 second
        sleep(1);
    }

cleanup:
    // Close the I2C bus
    pigpio_i2c_close(fd);

    // Close the CSV file
    fclose(fd);

    return 0;
}

