#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR_0 0x36
#define I2C_ADDR_1 0x37
#define I2C_CMD_REG 0x08
#define I2C_DATA_REG 0x00
#define I2C_DATA_LEN 9
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define SCALE_FACTOR 0.036
#define ALARM_GPIO 17
#define LOG_FILE "flow_log.txt"

int main(void) {
    // Initialize GPIO
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }
    struct gpiod_line *line = gpiod_chip_get_line(chip, ALARM_GPIO);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }
    gpiod_line_request_output(line, "alarm", 0);

    // Initialize I2C
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR_0) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize log file
    FILE *log = fopen(LOG_FILE, "w");
    if (!log) {
        perror("Failed to open log file");
        close(fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read flow rates from both sensors
        uint8_t data[I2C_DATA_LEN];
        if (read(fd, data, I2C_DATA_LEN) != I2C_DATA_LEN) {
            perror("Failed to read I2C data");
            continue;
        }

        // Validate CRC
        uint8_t crc = data[0];
        for (int i = 1; i < I2C_DATA_LEN - 1; i++) {
            crc = crc8_update(crc, data[i]);
        }
        if (crc != data[I2C_DATA_LEN - 1]) {
            fprintf(stderr, "CRC failure\n");
            continue;
        }

        // Convert raw flow value to ml/min
        int16_t flow_0 = (data[1] << 8) | data[2];
        int16_t flow_1 = (data[4] << 8) | data[5];
        double flow_0_ml = flow_0 * SCALE_FACTOR;
        double flow_1_ml = flow_1 * SCALE_FACTOR;

        // Calculate average flow rate
        double avg_flow = (flow_0_ml + flow_1_ml) / 2;

        // Log average flow rate
        fprintf(log, "%.2f\n", avg_flow);

        // Drive alarm
        if (avg_flow < 0.5) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        // Wait for next cycle
        sleep(1);
    }

    // Clean shutdown
    fclose(log);
    close(fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

