#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100

typedef struct {
    uint32_t timestamp;
    bool reading;
} buffer_entry_t;

buffer_entry_t buffer[BUFFER_SIZE];
int buffer_index = 0;

void handle_sigint(int signal) {
    printf("Received SIGINT, printing buffer contents:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%d: %s\n", buffer[i].timestamp, buffer[i].reading ? "OBSTACLE DETECTED" : "NO OBSTACLE");
    }
    pigpio_stop(0);
    exit(0);
}

int main(void) {
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (pigpio_gpio_mode_set(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        return 1;
    }

    if (pigpio_gpio_pull_up(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to enable pull-up resistor on GPIO %d\n", GPIO_PIN);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (true) {
        uint32_t timestamp = time(NULL);
        bool reading = pigpio_gpio_read(GPIO_PIN);
        buffer[buffer_index].timestamp = timestamp;
        buffer[buffer_index].reading = reading;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (reading == 0) {
            printf("OBSTACLE DETECTED at %s\n", ctime(&timestamp));
        }
        sleep(50);
    }

    return 0;
}

