#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <signal.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x55
#define MODE_CONTROL 0x1D
#define OPERATING_STATUS 0x1B
#define ACCEL_X_LSB 0x2A
#define ACCEL_X_MSB 0x2B
#define ACCEL_Y_LSB 0x2C
#define ACCEL_Y_MSB 0x2D
#define ACCEL_Z_LSB 0x2E
#define ACCEL_Z_MSB 0x2F
#define SCALE_FACTOR 0.0009765625

#define CSV_HEADER "timestamp,x,y,z\n"

int main(void) {
    int i2c_fd, csv_fd;
    uint8_t mode_control, operating_status;
    int16_t accel_x, accel_y, accel_z;
    char timestamp[20];

    // Open I2C device
    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    mode_control = 0x10;
    if (write(i2c_fd, &mode_control, 1) != 1) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        return 1;
    }

    // Wait for sensor to become active
    if (read(i2c_fd, &operating_status, 1) != 1) {
        perror("Failed to read from I2C device");
        close(i2c_fd);
        return 1;
    }
    if (!(operating_status & 0x01)) {
        fprintf(stderr, "Sensor did not become active within 1 second\n");
        close(i2c_fd);
        return 1;
    }

    // Open CSV file
    if ((csv_fd = open("fan_health.csv", O_WRONLY | O_APPEND | O_CREAT, 0644)) < 0) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    // Write CSV header
    if (write(csv_fd, CSV_HEADER, strlen(CSV_HEADER)) != strlen(CSV_HEADER)) {
        perror("Failed to write CSV header");
        close(i2c_fd);
        close(csv_fd);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read acceleration data
        if (read(i2c_fd, &accel_x, 2) != 2) {
            perror("Failed to read from I2C device");
            close(i2c_fd);
            close(csv_fd);
            return 1;
        }
        if (read(i2c_fd, &accel_y, 2) != 2) {
            perror("Failed to read from I2C device");
            close(i2c_fd);
            close(csv_fd);
            return 1;
        }
        if (read(i2c_fd, &accel_z, 2) != 2) {
            perror("Failed to read from I2C device");
            close(i2c_fd);
            close(csv_fd);
            return 1;
        }

        // Convert raw values to g
        accel_x = (int16_t)((accel_x << 8) | accel_x) * SCALE_FACTOR;
        accel_y = (int16_t)((accel_y << 8) | accel_y) * SCALE_FACTOR;
        accel_z = (int16_t)((accel_z << 8) | accel_z) * SCALE_FACTOR;

        // Get timestamp
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));

        // Write to CSV file
        char csv_row[100];
        sprintf(csv_row, "%s,%d,%d,%d\n", timestamp, accel_x, accel_y, accel_z);
        if (write(csv_fd, csv_row, strlen(csv_row)) != strlen(csv_row)) {
            perror("Failed to write to CSV file");
            close(i2c_fd);
            close(csv_fd);
            return 1;
        }

        // Sleep for 500 ms
        usleep(500000);
    }

    // Clean up
    close(i2c_fd);
    close(csv_fd);

    return 0;
}

void sigint_handler(int sig) {
    close(i2c_fd);
    close(csv_fd);
    exit(0);
}

void sigterm_handler(int sig) {
    close(i2c_fd);
    close(csv_fd);
    exit(0);
}

