#include <signal.h>
#include <pigpio.h>

#define SENSOR1_GPIO 23
#define SENSOR2_GPIO 24
#define LED_GPIO 25

#define SENSOR_THRESHOLD 10

int main(int argc, char **argv) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_GPIO);
        return 1;
    }
    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_GPIO);
        return 1;
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_value = gpioRead(SENSOR1_GPIO);
        int sensor2_value = gpioRead(SENSOR2_GPIO);

        // Check for obstacle
        if (sensor1_value == 0 || sensor2_value == 0) {
            // Turn LED on
            gpioWrite(LED_GPIO, 1);
        } else {
            // Turn LED off
            gpioWrite(LED_GPIO, 0);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    gpioTerminate();

    return 0;
}

void signal_handler(int signal) {
    // Clean up
    gpioTerminate();

    // Exit
    exit(0);
}

