#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define STALL_TIME 2

int main(void) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up GPIO pins for sensor inputs
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR1_PIN);
        return 1;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR2_PIN);
        return 1;
    }

    // Open file for logging stall events
    FILE *log_file = fopen("stall_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (true) {
        // Read sensor values
        int sensor1_value = gpioRead(SENSOR1_PIN);
        int sensor2_value = gpioRead(SENSOR2_PIN);

        // Check for stall
        if (sensor1_value == 0 && sensor2_value == 0) {
            // Check if stall has already been logged
            if (check_stall_log(log_file, SENSOR1_PIN, SENSOR2_PIN)) {
                // Log stall event
                log_stall_event(log_file, SENSOR1_PIN, SENSOR2_PIN);
            }
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    gpioTerminate();
    fclose(log_file);

    return 0;
}

// Check if stall has already been logged
bool check_stall_log(FILE *log_file, int sensor1_pin, int sensor2_pin) {
    // Seek to end of file
    fseek(log_file, 0, SEEK_END);

    // Read last line of file
    char line[100];
    fgets(line, 100, log_file);

    // Check if last line contains sensor values
    if (strstr(line, sensor1_pin) && strstr(line, sensor2_pin)) {
        return true;
    }

    return false;
}

// Log stall event
void log_stall_event(FILE *log_file, int sensor1_pin, int sensor2_pin) {
    // Get current timestamp
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);

    // Format timestamp
    char timestamp[100];
    strftime(timestamp, 100, "%Y-%m-%d %H:%M:%S", tm);

    // Log stall event
    fprintf(log_file, "%s: Stall detected on sensors %d and %d\n", timestamp, sensor1_pin, sensor2_pin);
}

