    // Read last line of file
    char line[100];
    fgets(line, 100, log_file);

    // Check if last line contains sensor values
    if (strstr(line, sensor1_pin) && strstr(line, sensor2_pin)) {
        return true;
    }

    return false;
}

// Log stall event
void log_stall_event(FILE *log_file, int sensor1_pin, int sensor2_pin) {
    // Get current timestamp
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);

    // Format timestamp
    char timestamp[100];
    strftime(timestamp, 100, "%Y-%m-%d %H:%M:%S", tm);

    // Log stall event
    fprintf(log_file, "%s: Stall detected on sensors %d and %d\n", timestamp, sensor1_pin, sensor2_pin);
}
