    // Initialize the I2C bus
    int i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", pigpio_i2c_error(i2c_handle));
        return 1;
    }

    // Verify the device ID register
    uint8_t device_id;
    if (pigpio_i2c_read(i2c_handle, 0x00, &device_id, 1) != 1) {
        fprintf(stderr, "Error reading device ID register: %s\n", pigpio_i2c_error(i2c_handle));
        return 1;
    }
    if (device_id != 0x8D) {
        fprintf(stderr, "Invalid device ID: %02X\n", device_id);
        return 1;
    }

    // Configure the sensor for continuous-conversion mode with all three axes enabled and a 50 mT range
    uint8_t config_reg = 0x00;
    if (pigpio_i2c_write(i2c_handle, 0x01, &config_reg, 1) != 1) {
        fprintf(stderr, "Error writing configuration register: %s\n", pigpio_i2c_error(i2c_handle));
        return 1;
    }

    // Open the output file
    FILE *output_file = fopen("magnetic_log.csv", "a");
    if (output_file == NULL) {
        fprintf(stderr, "Error opening output file: %s\n", strerror(errno));
        return 1;
    }

    // Write the CSV header row if the file is newly created
    if (fseek(output_file, 0, SEEK_END) == 0 && ftell(output_file) == 0) {
        fprintf(output_file, "timestamp,x,y,z\n");
    }

    // Set up the SIGINT/SIGTERM handler
    struct sigaction sigint_action;
    sigint_action.sa_handler = sigint_handler;
    sigint_action.sa_flags = 0;
    sigemptyset(&sigint_action.sa_mask);
    sigaction(SIGINT, &sigint_action, NULL);

    // Run an infinite loop until interrupted by Ctrl+C
    while (1) {
        // Read the X, Y, and Z magnetic field readings
        uint16_t x, y, z;
        if (pigpio_i2c_read(i2c_handle, 0x02, &x, 2) != 2 || pigpio_i2c_read(i2c_handle, 0x04, &y, 2) != 2 || pigpio_i2c_read(i2c_handle, 0x06, &z, 2) != 2) {
            fprintf(stderr, "Error reading magnetic field readings: %s\n", pigpio_i2c_error(i2c_handle));
            return 1;
        }

        // Convert the raw 16-bit two's-complement values to mT using the appropriate LSB scale factor for the 50 mT range
        double x_mt = (double)x * LSB_SCALE_FACTOR;
        double y_mt = (double)y * LSB_SCALE_FACTOR;
        double z_mt = (double)z * LSB_SCALE_FACTOR;

        // Log the magnetic field readings with ISO-8601 timestamps to the output file
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(output_file, "%04d-%02d-%02dT%02d:%02d:%02d.%03d,%.3f,%.3f,%.3f\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, tm->tm_usec / 1000, x_mt, y_mt, z_mt);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up resources on exit
    pigpio_i2c_close(i2c_handle);
    fclose(output_file);
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum) {
    // Clean up resources on SIGINT/SIGTERM
    pigpio_i2c_close(i2c_handle);
    fclose(output_file);
    gpioTerminate();

    // Exit the program
    exit(0);
}

