#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 23
#define POLL_INTERVAL 2000
#define REINIT_INTERVAL 60000

static int gpio_fd;
static int gpio_pin;
static int gpio_value;

static void init_gpio() {
    gpio_fd = pigpio_start(NULL, NULL);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }

    gpio_pin = pigpio_gpio(gpio_fd, GPIO_PIN);
    if (gpio_pin < 0) {
        fprintf(stderr, "Failed to get GPIO pin\n");
        exit(1);
    }

    gpio_value = pigpio_read(gpio_fd, gpio_pin);
    if (gpio_value < 0) {
        fprintf(stderr, "Failed to read GPIO value\n");
        exit(1);
    }
}

static void handle_gpio_read_failure() {
    fprintf(stderr, "GPIO read failure, reinitializing in %d seconds\n", REINIT_INTERVAL / 1000);
    sleep(REINIT_INTERVAL);
    init_gpio();
}

static void handle_sigint() {
    fprintf(stderr, "Received SIGINT, cleaning up\n");
    pigpio_stop(gpio_fd);
    exit(0);
}

static void handle_sigterm() {
    fprintf(stderr, "Received SIGTERM, cleaning up\n");
    pigpio_stop(gpio_fd);
    exit(0);
}

int main() {
    init_gpio();

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    while (1) {
        gpio_value = pigpio_read(gpio_fd, gpio_pin);
        if (gpio_value < 0) {
            handle_gpio_read_failure();
            continue;
        }

        if (gpio_value == 1) {
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

            fprintf(stdout, "%s ALERT: Water detected\n", timestamp);
            fprintf(stdout, "flood_log.txt", "%s ALERT: Water detected\n", timestamp);
        }

        sleep(POLL_INTERVAL);
    }

    pigpio_stop(gpio_fd);
    return 0;
}

