#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define PIN 7
#define PULSE_WINDOW 1000
#define RPM_LOG "rpm_log.txt"

static volatile uint32_t pulse_count = 0;
static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void sigterm_handler(int signum) {
    running = false;
}

static void timer_callback(int32_t pi, uint32_t user_gpio, uint32_t level, uint32_t tick) {
    if (level == 1) {
        atomic_add(&pulse_count, 1);
    }
}

int main(int argc, char *argv[]) {
    int32_t pi;
    int32_t gpio;
    int32_t result;
    FILE *log_file;
    struct timespec ts;
    struct tm *tm;
    char time_str[20];
    uint32_t rpm;

    // Initialize pigpio
    pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error(pi));
        return 1;
    }

    // Set up GPIO pin
    gpio = pigpio_gpio(pi, PIN);
    result = pigpio_set_mode(pi, gpio, PI_INPUT);
    if (result < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", pigpio_error(result));
        return 1;
    }
    result = pigpio_set_pull_up_down(pi, gpio, PI_PUD_UP);
    if (result < 0) {
        fprintf(stderr, "Failed to set pull-up/pull-down: %s\n", pigpio_error(result));
        return 1;
    }

    // Set up timer
    result = pigpio_set_timer_func(pi, PULSE_WINDOW, timer_callback);
    if (result < 0) {
        fprintf(stderr, "Failed to set timer: %s\n", pigpio_error(result));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open log file
    log_file = fopen(RPM_LOG, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    while (running) {
        // Wait for 1 second
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += 1;
        pigpio_wait_for_interrupt(pi, PIN, PI_TIME_RELATIVE, &ts);

        // Compute RPM
        rpm = (pulse_count * 60) / PULSE_WINDOW;
        pulse_count = 0;

        // Log RPM
        tm = localtime(&ts.tv_sec);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(log_file, "%s %u\n", time_str, rpm);
        fflush(log_file);

        // Print RPM to stdout
        printf("%u\n", rpm);
    }

    // Clean up
    pigpio_set_timer_func(pi, PULSE_WINDOW, NULL);
    pigpio_stop(pi);
    fclose(log_file);

    return 0;
}

