            direction = CW;
        } else {
            direction = CCW;
        }
    } else if (gpio == SENSOR_B) {
        if (level == PULL_UP) {
            direction = CCW;
        } else {
            direction = CW;
        }
    }
    pthread_mutex_unlock(&mutex);
    pthread_cond_signal(&cond);
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetPullUpDown(SENSOR_A, PULL_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on Sensor A\n");
        return 1;
    }

    if (gpioSetPullUpDown(SENSOR_B, PULL_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on Sensor B\n");
        return 1;
    }

    if (gpioSetAlertFunc(SENSOR_A, gpio_alert_func) < 0) {
        fprintf(stderr, "Failed to set alert function on Sensor A\n");
        return 1;
    }

    if (gpioSetAlertFunc(SENSOR_B, gpio_alert_func) < 0) {
        fprintf(stderr, "Failed to set alert function on Sensor B\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    FILE *fp = fopen("rotation_log.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (running) {
        pthread_mutex_lock(&mutex);
        while (direction == 0) {
            pthread_cond_wait(&cond, &mutex);
        }
        pthread_mutex_unlock(&mutex);

        char *direction_str = (direction == CW) ? "CW" : "CCW";
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%L", tm);
        fprintf(fp, "%s %s\n", timestamp, direction_str);
        fflush(fp);

        direction = 0;
    }

    fclose(fp);
    gpioTerminate();

    return 0;
}
