#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_CHIP_LINE_NAME "gpiochip0-line23"
#define GPIO_LED_LINE_NAME "gpiochip0-line18"
#define POLL_INTERVAL 50

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(int argc, char **argv) {
    // Open the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Request the touch sensor line
    struct gpiod_line *touch_line = gpiod_chip_get_line(chip, GPIO_CHIP_LINE_NAME);
    if (!touch_line) {
        fprintf(stderr, "Error requesting touch sensor line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the LED line
    struct gpiod_line *led_line = gpiod_chip_get_line(chip, GPIO_LED_LINE_NAME);
    if (!led_line) {
        fprintf(stderr, "Error requesting LED line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Set up the LED line as an output
    gpiod_line_request_output(led_line, "led", 0);

    // Set up the touch sensor line as an input
    gpiod_line_request_input(touch_line, "touch");

    // Set up the syslog
    openlog("touch_sensor", LOG_PID, LOG_USER);

    // Main loop
    while (running) {
        // Read the touch sensor line
        int touch_value = gpiod_line_get_value(touch_line);
        if (touch_value < 0) {
            syslog(LOG_ERR, "Error reading touch sensor line");
            continue;
        }

        // Set the LED line based on the touch sensor value
        gpiod_line_set_value(led_line, touch_value);

        // Log the touch event
        syslog(LOG_INFO, "Touch sensor value: %d", touch_value);

        // Sleep for the poll interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    gpiod_line_release(touch_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    closelog();

    return 0;
}

