#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define LED_PIN 18
#define TOUCH_PIN 17
#define DEBOUNCE_TIME 50

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(int argc, char **argv) {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line, *touch_line;
    struct gpiod_line_request *led_request, *touch_request;
    struct gpiod_line_event event;
    int ret;

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: failed to open GPIO chip\n");
        return 1;
    }

    // Request lines for LED and touch sensor
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!led_line || !touch_line) {
        fprintf(stderr, "Error: failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up LED line as output and drive it LOW
    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: failed to set LED line as output\n");
        gpiod_line_release(led_line);
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return 1;
    }
    led_request = gpiod_line_request_output(led_line, "led", 0);

    // Set up touch sensor line as input
    ret = gpiod_line_request_input(touch_line, "touch");
    if (ret < 0) {
        fprintf(stderr, "Error: failed to set touch sensor line as input\n");
        gpiod_line_release(led_line);
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return 1;
    }
    touch_request = gpiod_line_request_input(touch_line, "touch");

    // Wait for touch events
    while (running) {
        ret = gpiod_line_event_wait(touch_line, &event);
        if (ret < 0) {
            fprintf(stderr, "Error: failed to wait for touch event\n");
            continue;
        }

        // Check for rising edge
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Toggle LED
            ret = gpiod_line_set_value(led_line, !gpiod_line_get_value(led_line));
            if (ret < 0) {
                fprintf(stderr, "Error: failed to set LED value\n");
                continue;
            }

            // Debounce
            usleep(DEBOUNCE_TIME * 1000);
        }
    }

    // Clean up
    gpiod_line_release(led_line);
    gpiod_line_release(touch_line);
    gpiod_chip_close(chip);

    return 0;
}

