#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN_1 27
#define LED_PIN_2 22
#define TOUCH_PIN_1 4
#define TOUCH_PIN_2 17
#define POLL_INTERVAL 50
#define LOG_BUFFER_SIZE 100

struct log_entry {
    uint8_t sensor_pin;
    uint64_t timestamp;
    bool state;
};

struct log_entry log_buffer[LOG_BUFFER_SIZE];
uint8_t log_index = 0;
uint8_t overflow_count = 0;

void handle_sigint(int signal) {
    printf("Received SIGINT, shutting down...\n");
    gpioWrite(LED_PIN_1, 0);
    gpioWrite(LED_PIN_2, 0);
    gpioTerminate();
    exit(0);
}

void handle_sigterm(int signal) {
    printf("Received SIGTERM, shutting down...\n");
    gpioWrite(LED_PIN_1, 0);
    gpioWrite(LED_PIN_2, 0);
    gpioTerminate();
    exit(0);
}

void log_event(uint8_t sensor_pin, bool state) {
    struct log_entry entry;
    entry.sensor_pin = sensor_pin;
    entry.timestamp = time(NULL);
    entry.state = state;
    log_buffer[log_index] = entry;
    log_index = (log_index + 1) % LOG_BUFFER_SIZE;
    if (log_index == 0) {
        overflow_count++;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN_1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED 1 mode\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN_2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED 2 mode\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_PIN_1, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set touch 1 mode\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_PIN_2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set touch 2 mode\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    while (true) {
        bool touch_1 = gpioRead(TOUCH_PIN_1);
        bool touch_2 = gpioRead(TOUCH_PIN_2);

        if (touch_1) {
            gpioWrite(LED_PIN_1, 1);
            log_event(TOUCH_PIN_1, true);
        } else {
            gpioWrite(LED_PIN_1, 0);
            log_event(TOUCH_PIN_1, false);
        }

        if (touch_2) {
            gpioWrite(LED_PIN_2, 1);
            log_event(TOUCH_PIN_2, true);
        } else {
            gpioWrite(LED_PIN_2, 0);
            log_event(TOUCH_PIN_2, false);
        }

        usleep(POLL_INTERVAL * 1000);
    }

    gpioTerminate();

    for (int i = 0; i < LOG_BUFFER_SIZE; i++) {
        struct log_entry entry = log_buffer[i];
        printf("%d %llu %d\n", entry.sensor_pin, entry.timestamp, entry.state);
    }

    printf("Overflow count: %d\n", overflow_count);

    return 0;
}

