#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_RAIN_SENSOR 17
#define POLL_INTERVAL 500

static int gpio_handle;
static FILE *log_file;

static void handle_sigint(int signal) {
    printf("Received SIGINT, shutting down...\n");
    pigpio_stop(gpio_handle);
    fclose(log_file);
    exit(0);
}

static void handle_sigterm(int signal) {
    printf("Received SIGTERM, shutting down...\n");
    pigpio_stop(gpio_handle);
    fclose(log_file);
    exit(0);
}

int main(int argc, char **argv) {
    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Initialize pigpio
    gpio_handle = pigpio_start(NULL, NULL);
    if (gpio_handle < 0) {
        printf("Failed to initialize pigpio: %s\n", pigpio_error(gpio_handle));
        return 1;
    }

    // Set up GPIO pin
    if (pigpio_gpio_mode_set(gpio_handle, GPIO_RAIN_SENSOR, PI_INPUT) < 0) {
        printf("Failed to set GPIO mode: %s\n", pigpio_error(gpio_handle));
        pigpio_stop(gpio_handle);
        return 1;
    }
    if (pigpio_gpio_pull_up(gpio_handle, GPIO_RAIN_SENSOR) < 0) {
        printf("Failed to enable pull-up resistor: %s\n", pigpio_error(gpio_handle));
        pigpio_stop(gpio_handle);
        return 1;
    }

    // Open log file
    log_file = fopen("/var/log/rain_events.log", "a");
    if (log_file == NULL) {
        printf("Failed to open log file: %s\n", strerror(errno));
        pigpio_stop(gpio_handle);
        return 1;
    }

    // Poll GPIO pin
    while (1) {
        int value = pigpio_gpio_read(gpio_handle, GPIO_RAIN_SENSOR);
        if (value < 0) {
            printf("Failed to read GPIO value: %s\n", pigpio_error(gpio_handle));
            pigpio_stop(gpio_handle);
            fclose(log_file);
            return 1;
        }

        if (value == 0) {
            // Rain detected
            time_t now = time(NULL);
            char *timestamp = ctime(&now);
            fprintf(log_file, "%s Rain Detected\n", timestamp);
        } else {
            // No rain
            fprintf(log_file, "No Rain\n");
        }

        // Sleep for POLL_INTERVAL ms
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    pigpio_stop(gpio_handle);
    fclose(log_file);
    return 0;
}

