#define SENSOR_ADDR 0x28
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04

#define I2C_BUS 1

int main(void) {
    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    int i2c_handle = pigpio_i2c_open(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        pigpio_stop();
        return 1;
    }

    // Verify sensor is present
    uint8_t part_id;
    if (pigpio_i2c_read_byte(i2c_handle, PART_ID_REG, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        pigpio_i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }
    if (part_id != 0x28) {
        fprintf(stderr, "Invalid PART_ID: 0x%02X\n", part_id);
        pigpio_i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    // Configure sensor for continuous measurement
    uint8_t config = 0x01;
    if (pigpio_i2c_write_byte(i2c_handle, CONFIG_REG, config) < 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        pigpio_i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pigpio_i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sigint_handler;
    sigint_handler.sa_handler = sigint_handler_func;
    sigint_handler.sa_flags = 0;
    sigemptyset(&sigint_handler.sa_mask);
    if (sigaction(SIGINT, &sigint_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        fclose(log_file);
        pigpio_i2c_close(i2c_handle);
        pigpio_stop();
        return 1;
    }

    // Main loop
    while (1) {
        // Read heart rate data
        uint8_t heart_rate;
        if (pigpio_i2c_read_byte(i2c_handle, HEART_RATE_REG, &heart_rate) < 0) {
            fprintf(stderr, "Failed to read HEART_RATE register\n");
            continue;
        }

        // Read SpO2 data
        uint8_t spo2;
        if (pigpio_i2c_read_byte(i2c_handle, SPO2_REG, &spo2) < 0) {
            fprintf(stderr, "Failed to read SPO2 register\n");
            continue;
        }

        // Log data
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d, Heart Rate: %d BPM, SpO2: %d%%\n",
                tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                tm->tm_hour, tm->tm_min, tm->tm_sec,
                heart_rate, spo2);
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    pigpio_i2c_close(i2c_handle);
    pigpio_stop();

    return 0;
}

void sigint_handler_func(int signum) {
    // Close log file
    fclose(log_file);

    // Close I2C handle
    pigpio_i2c_close(i2c_handle);

    // Stop pigpio
    pigpio_stop();

    // Exit
    exit(0);
}

