int main(int argc, char *argv[]) {
  // Initialize pigpio
  if (gpioInitialise() < 0) {
    fprintf(stderr, "Failed to initialize pigpio\n");
    return 1;
  }

  // Set up GPIO pins
  if (gpioSetMode(SENSOR_1, PI_INPUT) < 0) {
    fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1);
    return 1;
  }
  if (gpioSetMode(SENSOR_2, PI_INPUT) < 0) {
    fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2);
    return 1;
  }
  if (gpioSetMode(ALARM, PI_OUTPUT) < 0) {
    fprintf(stderr, "Failed to set GPIO %d as output\n", ALARM);
    return 1;
  }

  // Set up alarm
  if (gpioWrite(ALARM, PI_LOW) < 0) {
    fprintf(stderr, "Failed to set GPIO %d to LOW\n", ALARM);
    return 1;
  }

  // Open log file
  FILE *log_file = fopen("bridge_integrity.log", "w");
  if (log_file == NULL) {
    fprintf(stderr, "Failed to open log file\n");
    return 1;
  }

  // Set up signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Main loop
  while (1) {
    // Read sensor values
    int sensor_1 = gpioRead(SENSOR_1);
    int sensor_2 = gpioRead(SENSOR_2);

    // Check for tilt
    if (sensor_1 == PI_HIGH || sensor_2 == PI_HIGH) {
      // Tilt detected, activate alarm
      if (gpioWrite(ALARM, PI_HIGH) < 0) {
        fprintf(stderr, "Failed to activate alarm\n");
        return 1;
      }

      // Log tilt-start event
      time_t now = time(NULL);
      char timestamp[20];
      strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
      fprintf(log_file, "%s: Tilt-start\n", timestamp);

      // Wait for tilt to end
      while (sensor_1 == PI_HIGH || sensor_2 == PI_HIGH) {
        gpioDelay(100);
        sensor_1 = gpioRead(SENSOR_1);
        sensor_2 = gpioRead(SENSOR_2);
      }

      // Tilt has ended, deactivate alarm
      if (gpioWrite(ALARM, PI_LOW) < 0) {
        fprintf(stderr, "Failed to deactivate alarm\n");
        return 1;
      }

      // Log tilt-end event
      now = time(NULL);
      strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
      fprintf(log_file, "%s: Tilt-end\n", timestamp);
    }

    // Check for threshold exceeded
    if (sensor_1 == PI_HIGH && sensor_2 == PI_HIGH) {
      // Threshold exceeded, log event
      time_t now = time(NULL);
      char timestamp[20];
      strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
      fprintf(log_file, "%s: Threshold-exceeded\n", timestamp);
    }

    // Wait for next iteration
    gpioDelay(100);
  }

  // Clean up
  fclose(log_file);
  gpioTerminate();

  return 0;
}

void signal_handler(int signal) {
  // Deactivate alarm
  if (gpioWrite(ALARM, PI_LOW) < 0) {
    fprintf(stderr, "Failed to deactivate alarm\n");
    return;
  }

  // Close log file
  fclose(log_file);

  // Terminate pigpio
  gpioTerminate();

  // Exit program
  exit(0);
}

