#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define CTRL1_REG 0x1F
#define ACCEL_X_REG 0x28
#define ACCEL_Y_REG 0x29
#define ACCEL_Z_REG 0x2A
#define THRESHOLD 500
#define LED_PIN 17

int main(void) {
    int i2c_handle;
    int retries = 3;
    int retry_count = 0;
    int16_t x, y, z;
    float magnitude;
    char timestamp[20];
    FILE *log_file;

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Initialize the sensor by clearing the power-down bit in CTRL1
    if (i2cWriteByte(i2c_handle, CTRL1_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CTRL1 register\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up the LED pin as an output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read the acceleration registers
        if (i2cReadBlock(i2c_handle, ACCEL_X_REG, 6, (uint8_t *)&x) < 0) {
            fprintf(stderr, "Failed to read acceleration registers\n");
            retry_count++;
            if (retry_count > retries) {
                fprintf(stderr, "Too many retries, exiting\n");
                return 1;
            }
            continue;
        }

        // Compute the Euclidean vibration magnitude
        magnitude = sqrt(x * x + y * y + z * z);

        // Check if the magnitude exceeds the threshold
        if (magnitude > THRESHOLD) {
