    int retries = 3;
    int retry_count = 0;
    int16_t x, y, z;
    float magnitude;
    char timestamp[20];
    FILE *log_file;

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Initialize the sensor by clearing the power-down bit in CTRL1
    if (i2cWriteByte(i2c_handle, CTRL1_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CTRL1 register\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up the LED pin as an output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read the acceleration registers
        if (i2cReadBlock(i2c_handle, ACCEL_X_REG, 6, (uint8_t *)&x) < 0) {
            fprintf(stderr, "Failed to read acceleration registers\n");
            retry_count++;
            if (retry_count > retries) {
                fprintf(stderr, "Too many retries, exiting\n");
                return 1;
            }
            continue;
        }

        // Compute the Euclidean vibration magnitude
        magnitude = sqrt(x * x + y * y + z * z);

        // Check if the magnitude exceeds the threshold
        if (magnitude > THRESHOLD) {
            // Turn on the LED
            if (gpioWrite(LED_PIN, PI_HIGH) < 0) {
                fprintf(stderr, "Failed to turn on LED\n");
                return 1;
            }

            // Log the event
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));
            fprintf(log_file, "%s,%.2f\n", timestamp, magnitude);

            // Wait for 1 second
            sleep(1);

            // Turn off the LED
            if (gpioWrite(LED_PIN, PI_LOW) < 0) {
                fprintf(stderr, "Failed to turn off LED\n");
                return 1;
            }
        }

        // Wait for 100 ms
        usleep(100000);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

