            fprintf(stderr, "Error: Failed to request GPIO line %d as input\n", SENSOR_PINS[i]);
            return 1;
        }
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (running) {
        int i;
        int any_obstacle = 0;

        for (i = 0; i < 4; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Error: Failed to read GPIO line %d\n", SENSOR_PINS[i]);
                return 1;
            }

            if (value == 0) {
                any_obstacle = 1;
                break;
            }
