#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define SENSOR_PINS {2, 3, 4, 17, 27}
#define DEBOUNCE_MS 50

static volatile sig_atomic_t sig_flag = 0;

static void sigint_handler(int signum) {
    sig_flag = 1;
}

static void sigterm_handler(int signum) {
    sig_flag = 1;
}

static void setup_signals(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);
}

static void log_startup(void) {
    openlog("flame_monitor", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "Starting flame monitor");
}

static void log_read_error(int sensor_id, int pin, int error) {
    syslog(LOG_ERR, "Error reading sensor %d (GPIO %d): %s", sensor_id, pin, strerror(error));
}

static void log_shutdown(void) {
    syslog(LOG_INFO, "Shutting down flame monitor");
    closelog();
}

static void monitor_sensors(void) {
    gpiod_chip_t *chip;
    gpiod_line_t *lines[NUM_SENSORS];
    int i, j;
    bool flame_detected;
    char timestamp[32];
    char event_line[128];

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_startup();
        syslog(LOG_ERR, "Error opening GPIO chip: %s", strerror(errno));
        return;
    }

    // Request lines for all sensors
    for (i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, SENSOR_PINS[i]);
        if (!lines[i]) {
            log_startup();
            syslog(LOG_ERR, "Error getting line for sensor %d (GPIO %d): %s", i, SENSOR_PINS[i], strerror(errno));
            return;
        }
        if (gpiod_line_request_input(lines[i], "flame_monitor") != 0) {
            log_startup();
            syslog(LOG_ERR, "Error requesting input for sensor %d (GPIO %d): %s", i, SENSOR_PINS[i], strerror(errno));
            return;
        }
    }

    // Main monitoring loop
    while (!sig_flag) {
        for (i = 0; i < NUM_SENSORS; i++) {
            // Read the sensor value
            flame_detected = gpiod_line_get_value(lines[i]);
            if (flame_detected < 0) {
                log_read_error(i, SENSOR_PINS[i], flame_detected);
                continue;
            }

            // Debounce the sensor value
            for (j = 0; j < DEBOUNCE_MS; j++) {
                usleep(1000);
                if (gpiod_line_get_value(lines[i]) != flame_detected) {
                    flame_detected = -1;
                    break;
                }
            }

            // If a flame was detected, log the event
            if (flame_detected) {
                time_t now = time(NULL);
                strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
                snprintf(event_line, sizeof(event_line), "%s - Sensor ID: %d (GPIO %d) - Flame Detected", timestamp, i, SENSOR_PINS[i]);
                FILE *fp = fopen("/var/log/flame_events.log", "a");
                if (fp) {
                    flock(fp, LOCK_EX);
                    fprintf(fp, "%s\n", event_line);
                    fflush(fp);
                    flock(fp, LOCK_UN);
                    fclose(fp);
                } else {
                    log_read_error(i, SENSOR_PINS[i], errno);
                }
            }
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Release all requested lines
    for (i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_release(lines[i]);
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);

    // Log shutdown message
    log_shutdown();
}

int main(void) {
    setup_signals();
    log_startup();
    monitor_sensors();
    return 0;
}

