#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <wiringPi.h>

#define I2C_BUS 1
#define I2C_ADDR 0x10
#define ALS_REG 0x04
#define CONFIG_REG 0x00
#define CONFIG_VAL 0x0000
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define LED_GPIO 18

int main(void) {
    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = i2c_open(I2C_BUS, 0, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Configure sensor
    uint16_t config_val = htole16(CONFIG_VAL);
    if (i2c_write(i2c_fd, I2C_ADDR, CONFIG_REG, &config_val, sizeof(config_val)) < 0) {
        fprintf(stderr, "Failed to write to config register\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("grow_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up PWM
    if (pwmSetMode(PWM_MODE_MS) < 0) {
        fprintf(stderr, "Failed to set PWM mode\n");
        return 1;
    }
    if (pwmSetRange(PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        return 1;
    }
    if (pwmSetClock(PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM clock\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read ALS value
        uint16_t als_val;
        if (i2c_read(i2c_fd, I2C_ADDR, ALS_REG, &als_val, sizeof(als_val)) < 0) {
            fprintf(stderr, "Failed to read ALS value\n");
            return 1;
        }
        als_val = letoh16(als_val);

        // Convert to lux
        float lux = als_val * 0.0576;

        // Set PWM duty cycle
        int duty_cycle;
        if (lux < 100) {
            duty_cycle = 100;
        } else if (lux < 500) {
            duty_cycle = 75;
        } else if (lux < 1000) {
            duty_cycle = 50;
        } else {
            duty_cycle = 25;
        }
        if (pwmWrite(LED_GPIO, duty_cycle) < 0) {
            fprintf(stderr, "Failed to write to PWM\n");
            return 1;
        }

        // Log sample
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s, %f, %d, %d\n", timestamp, lux, duty_cycle, 0);
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    i2c_close(i2c_fd);
    pigpio_stop();

    return 0;
}

