#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define LED_PIN 17
#define TOUCH_PINS 8
#define TOUCH_PIN_BASE 2
#define DEBOUNCE_TIME 50

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO pins
    for (int i = 0; i < TOUCH_PINS; i++) {
        if (gpioSetMode(TOUCH_PIN_BASE + i, PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_PIN_BASE + i);
            return 1;
        }
        if (gpioSetPullUpDown(TOUCH_PIN_BASE + i, PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Failed to set pull-down resistor for GPIO %d\n", TOUCH_PIN_BASE + i);
            return 1;
        }
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read touch inputs
        int touch_states[TOUCH_PINS];
        for (int i = 0; i < TOUCH_PINS; i++) {
            touch_states[i] = gpioRead(TOUCH_PIN_BASE + i);
        }

        // Debounce touch inputs
        for (int i = 0; i < TOUCH_PINS; i++) {
            if (touch_states[i] == 1) {
                // Wait for debounce time
                usleep(DEBOUNCE_TIME * 1000);

                // Check if touch is still detected
                if (gpioRead(TOUCH_PIN_BASE + i) == 1) {
                    // Log touch event
                    time_t now = time(NULL);
                    struct tm *tm = localtime(&now);
                    char time_str[20];
                    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);
                    char touch_str[20];
                    sprintf(touch_str, "Touched on channel %d", i + 1);
                    char log_str[50];
                    sprintf(log_str, "%s - %s", time_str, touch_str);
                    FILE *fp = fopen("touch_log.txt", "a");
                    if (fp == NULL) {
                        fprintf(stderr, "Failed to open touch_log.txt for writing\n");
                        return 1;
                    }
                    fprintf(fp, "%s\n", log_str);
                    fclose(fp);

                    // Turn LED on
                    gpioWrite(LED_PIN, 1);
                }
            }
        }

        // Check if all touch inputs are released
        int all_released = 1;
        for (int i = 0; i < TOUCH_PINS; i++) {
            if (touch_states[i] == 1) {
                all_released = 0;
                break;
            }
        }
        if (all_released) {
            // Turn LED off
