#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define OPT3001_ADDR 0x44
#define OPT3001_CFG_REG 0x01
#define OPT3001_RES_REG 0x00

#define OPT3001_CFG_WORD 0xC810

#define LUX_MULTIPLIER 0.01
#define LUX_EXPONENT_SHIFT 12

#define LOG_FILE "light_data.txt"

int main(void) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus 1
    int i2c_handle = i2cOpen(1, 0, 0, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Set up SIGINT handler for clean shutdown
    signal(SIGINT, sigint_handler);

    // Configure OPT3001 sensor
    uint16_t cfg_word = OPT3001_CFG_WORD;
    if (i2cWriteWordData(i2c_handle, OPT3001_ADDR, OPT3001_CFG_REG, cfg_word) < 0) {
        fprintf(stderr, "Failed to write configuration word to OPT3001\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for at least 100 ms for first conversion
    usleep(100000);

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read result register
        uint16_t res_word = i2cReadWordData(i2c_handle, OPT3001_ADDR, OPT3001_RES_REG);
        if (res_word < 0) {
            fprintf(stderr, "Failed to read result register from OPT3001\n");
            continue;
        }

        // Byte-swap result word
        res_word = (res_word << 8) | (res_word >> 8);

        // Extract exponent and mantissa
        int exponent = (res_word >> LUX_EXPONENT_SHIFT) & 0xF;
        int mantissa = res_word & 0xFFF;

        // Compute lux value
        double lux = mantissa * LUX_MULTIPLIER * pow(2, exponent);

        // Print lux value to stdout
        printf("%.2f\n", lux);

        // Log lux value to file
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(log_file, "%s, %.2f\n", time_str, lux);

        // Wait for next iteration
        usleep(1000000);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum) {
    // Close I2C handle and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    // Flush and close log file
    fflush(log_file);
    fclose(log_file);

    // Exit gracefully
    exit(0);
}

