#include <stdbool.h>
#include <time.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define ALERT_PIN 17
#define POLL_INTERVAL 500

static bool gpio_initialized = false;
static bool log_file_opened = false;
static bool sensor_reading_failed = false;

static void cleanup(void) {
    if (gpio_initialized) {
        gpioTerminate();
    }
    if (log_file_opened) {
        fclose(log_file);
    }
}

static void signal_handler(int signal) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    signal(SIGINT, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }
    gpio_initialized = true;

    FILE *log_file = fopen("fire_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }
    log_file_opened = true;

    while (true) {
        int sensor_value = gpioRead(FLAME_SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor value\n");
            sensor_reading_failed = true;
            continue;
        }

        if (sensor_value == 0) {
            gpioWrite(ALERT_PIN, 1);
            sleep(1);
            gpioWrite(ALERT_PIN, 0);
        }

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        fprintf(log_file, "%02d:%02d:%02d - %s\n", tm->tm_hour, tm->tm_min, tm->tm_sec, sensor_value ? "No flame" : "Flame detected");

        sleep(POLL_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

