#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 4
#define DEBOUNCE_INTERVAL 50

static int gpio_chip;
static int gpio_line;
static FILE *log_file;

static void handle_sigint(int signum) {
    printf("Received SIGINT, releasing GPIO line and closing log file\n");
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    fclose(log_file);
    exit(0);
}

static void handle_sigterm(int signum) {
    printf("Received SIGTERM, releasing GPIO line and closing log file\n");
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    fclose(log_file);
    exit(0);
}

int main(int argc, char *argv[]) {
    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Open the GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (gpio_chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        fclose(log_file);
        return 1;
    }

    // Request the GPIO line
    gpio_line = gpiod_line_request(gpio_chip, GPIO_PIN, "touch_sensor", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (gpio_line == NULL) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        return 1;
    }

    // Set the GPIO line to pull-down bias
    if (gpiod_line_set_bias(gpio_line, GPIOD_LINE_BIAS_PULL_DOWN) < 0) {
        fprintf(stderr, "Error setting GPIO line bias: %s\n", strerror(errno));
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        fclose(log_file);
        return 1;
    }

    // Poll the GPIO line with a debounce interval
    while (1) {
        int value = gpiod_line_get_value(gpio_line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
            gpiod_line_release(gpio_line);
            gpiod_chip_close(gpio_chip);
            fclose(log_file);
            return 1;
        }

        if (value == 1) {
            // Touch detected
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char time_str[20];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);
            fprintf(log_file, "%s: Touch Detected\n", time_str);
            fflush(log_file);
        } else {
            // Touch released
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char time_str[20];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);
            fprintf(log_file, "%s: Touch Released\n", time_str);
            fflush(log_file);
        }

        usleep(DEBOUNCE_INTERVAL * 1000);
    }

    // Clean up on exit
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    fclose(log_file);
    return 0;
}

