#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x08
#define CMD_START_CONTINUOUS 0x3608
#define CMD_READ_RAW 0x3609
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define FLOW_RANGE_MIN 0.0
#define FLOW_RANGE_MAX 100.0

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("cooling_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Write header row if file is new
    if (fseek(log_file, 0, SEEK_END) == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }

    // Start continuous measurement
    if (i2cWrite(i2c_handle, CMD_START_CONTINUOUS, 2) < 0) {
        fprintf(stderr, "Failed to start continuous measurement\n");
        return 1;
    }

    // Wait at least 2 ms before first read
    usleep(2000);

    // Read raw flow value and CRC
    uint8_t raw_flow[3];
    if (i2cRead(i2c_handle, CMD_READ_RAW, raw_flow, 3) < 0) {
        fprintf(stderr, "Failed to read raw flow value\n");
        return 1;
    }

    // Validate CRC
    uint8_t crc = crc8(raw_flow, 2, CRC_POLY, CRC_INIT);
    if (crc != raw_flow[2]) {
        fprintf(stderr, "CRC failure\n");
        return 1;
    }

    // Convert raw value to ml/min
    int16_t raw_flow_value = (raw_flow[0] << 8) | raw_flow[1];
    float flow_rate = raw_flow_value / 90.0;

    // Validate flow rate range
    if (flow_rate < FLOW_RANGE_MIN || flow_rate > FLOW_RANGE_MAX) {
        fprintf(stderr, "Invalid flow rate\n");
        return 1;
    }

    // Log flow rate, raw sensor flags, and status
    time_t timestamp = time(NULL);
    fprintf(log_file, "%ld,%.2f,OK\n", timestamp, flow_rate);

    // Close I2C handle and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

