static void handle_sigint(int signal) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    // Set up signal handler for SIGINT
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = handle_sigint;
    sigaction(SIGINT, &action, NULL);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_errmsg(errno));
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    lines[0] = gpiod_chip_get_line(chip, LEFT_LINE);
    lines[1] = gpiod_chip_get_line(chip, MIDDLE_LINE);
    lines[2] = gpiod_chip_get_line(chip, RIGHT_LINE);
    if (!lines[0] || !lines[1] || !lines[2]) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", gpiod_errmsg(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up GPIO lines for input
    if (gpiod_line_request_input(lines[0], "left_line") < 0 ||
        gpiod_line_request_input(lines[1], "middle_line") < 0 ||
        gpiod_line_request_input(lines[2], "right_line") < 0) {
        fprintf(stderr, "Failed to set up GPIO lines for input: %s\n", gpiod_errmsg(errno));
        gpiod_line_release(lines[0]);
        gpiod_line_release(lines[1]);
        gpiod_line_release(lines[2]);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    FILE *log_file = fopen("path_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(lines[0]);
        gpiod_line_release(lines[1]);
        gpiod_line_release(lines[2]);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Poll GPIO lines every POLL_INTERVAL ms
    while (true) {
        // Read GPIO lines
        int left_value = gpiod_line_get_value(lines[0]);
        int middle_value = gpiod_line_get_value(lines[1]);
        int right_value = gpiod_line_get_value(lines[2]);
        if (left_value < 0 || middle_value < 0 || right_value < 0) {
            fprintf(stderr, "Failed to read GPIO lines: %s\n", gpiod_errmsg(errno));
            break;
        }

        // Write to log file
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%FT%T", localtime(&now));
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left_value, middle_value, right_value);

        // Sleep for POLL_INTERVAL ms
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    cleanup();
    fclose(log_file);

    return EXIT_SUCCESS;
}

