#include <libgpiod.h>

#define LED_PIN 24
#define TOUCH_PIN 23
#define LOG_FILE "touch_log.txt"

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    FILE *log_file;
    char timestamp[20];
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error: unable to open GPIO chip\n");
        return 1;
    }

    // Request lines
    line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!line) {
        fprintf(stderr, "Error: unable to request line %d\n", TOUCH_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set line direction and request event
    ret = gpiod_line_request_input(line, "touch_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error: unable to request input on line %d\n", TOUCH_PIN);
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: unable to open log file %s\n", LOG_FILE);
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (running) {
        // Wait for event
        ret = gpiod_line_event_wait(line, &event, 1000);
        if (ret < 0) {
            fprintf(stderr, "Error: unable to wait for event on line %d\n", TOUCH_PIN);
            continue;
        }

        // Check event type
        if (event.event_type == GPIOD_LINE_EVENT_RISING) {
            // Toggle LED
            ret = gpiod_line_set_value(line, 1);
            if (ret < 0) {
                fprintf(stderr, "Error: unable to set value on line %d\n", LED_PIN);
                continue;
            }

            // Log event
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%FT%T", localtime(&now));
            fprintf(log_file, "%s, %d\n", timestamp, event.event_type);
        }
    }

    // Clean up
    fclose(log_file);
    gpiod_line_free(line);
    gpiod_chip_close(chip);

    return 0;
}

