int main(void) {
    // Open the chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open chip: %s\n", strerror(errno));
        return 1;
    }

    // Open the flame sensor line
    flame_sensor_fd = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_fd) {
        fprintf(stderr, "Failed to open flame sensor line: %s\n", strerror(errno));
        return 1;
    }

    // Open the buzzer line
    buzzer_fd = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_fd) {
        fprintf(stderr, "Failed to open buzzer line: %s\n", strerror(errno));
        return 1;
    }

    // Request the flame sensor line as an input
    if (gpiod_line_request_input(flame_sensor_fd, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request flame sensor line: %s\n", strerror(errno));
        return 1;
    }

    // Request the buzzer line as an output
    if (gpiod_line_request_output(buzzer_fd, "buzzer") < 0) {
        fprintf(stderr, "Failed to request buzzer line: %s\n", strerror(errno));
        return 1;
    }

    // Open the log file
    log_fd = fopen("alert_log.txt", "w");
    if (!log_fd) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Log the system started message
    fprintf(log_fd, "System started\n");

    // Set up the signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Poll the flame sensor every 500 ms
    while (1) {
        // Read the flame sensor value
        int value = gpiod_line_get_value(flame_sensor_fd);
        if (value < 0) {
            fprintf(stderr, "Failed to read flame sensor value: %s\n", strerror(errno));
            return 1;
        }

        // If the flame sensor is active, log the event and activate the buzzer
        if (value == 0) {
            // Log the event
            fprintf(log_fd, "Flame detected at %s\n", ctime(&time(NULL)));

            // Activate the buzzer
            gpiod_line_set_value(buzzer_fd, 1);

            // Sleep for 2 seconds
            usleep(BUZZER_ACTIVATION_DURATION * 1000);

            // Deactivate the buzzer
            gpiod_line_set_value(buzzer_fd, 0);
        }

        // Sleep for 500 ms
        usleep(POLL_INTERVAL * 1000);
    }

    // Log the system stopped message
    fprintf(log_fd, "System stopped\n");

    // Close the log file
    fclose(log_fd);

    // Release the lines
    gpiod_line_release(flame_sensor_fd);
    gpiod_line_release(buzzer_fd);

    // Close the chip
    gpiod_chip_close(chip);

    // Exit cleanly
    return 0;
}
