#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_INPUT 4
#define GPIO_OUTPUT 17
#define DEBOUNCE_TIME 200

int main(void) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set GPIO4 as input and GPIO17 as output
    if (gpioSetMode(GPIO_INPUT, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO4 as input\n");
        return 1;
    }
    if (gpioSetMode(GPIO_OUTPUT, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 as output\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (true) {
        // Read GPIO4
        int value = gpioRead(GPIO_INPUT);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO4\n");
            return 1;
        }

        // Check for rising edge
        if (value == 1 && !debounce) {
            // Toggle LED
            gpioWrite(GPIO_OUTPUT, !gpioRead(GPIO_OUTPUT));

            // Append timestamp to log file
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));
            fprintf(log_file, "%s\n", timestamp);

            // Debounce
            debounce = true;
            gpioDelay(DEBOUNCE_TIME);
            debounce = false;
        }

        // Sleep for 10 ms
        gpioDelay(10);
    }

    // Clean up
    gpioTerminate();
    fclose(log_file);

    return 0;
}

// Signal handler
void signal_handler(int signal) {
    // Turn off LED
    gpioWrite(GPIO_OUTPUT, 0);

    // Close log file
    fclose(log_file);

    // Terminate pigpio library
    gpioTerminate();

    // Exit
    exit(0);
}

