#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_ADDR 0x4A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define LED_CURRENT_REG 0x3F
#define AVERAGING_REG 0x04
#define ENABLE_REG 0x01
#define HEART_RATE_REG 0x2A

#define BPM_MIN 30
#define BPM_MAX 220
#define MOVING_AVG_SIZE 5

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus 1
    int i2c_handle = i2cOpen(1, 0, 0, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }

    // Verify sensor presence and correctness
    uint8_t part_id, hw_rev;
    if (i2cReadByteData(i2c_handle, SENSOR_ADDR, PART_ID_REG, &part_id) < 0 ||
        i2cReadByteData(i2c_handle, SENSOR_ADDR, HW_REV_REG, &hw_rev) < 0 ||
        part_id != 0x02 || hw_rev != 0x01) {
        fprintf(stderr, "Sensor not present or incorrect\n");
        return 1;
    }

    // Configure sensor
    uint8_t led_current = 0x3F;
    uint8_t averaging = 0x04;
    uint8_t enable = 0x01;
    if (i2cWriteByteData(i2c_handle, SENSOR_ADDR, LED_CURRENT_REG, led_current) < 0 ||
        i2cWriteByteData(i2c_handle, SENSOR_ADDR, AVERAGING_REG, averaging) < 0 ||
        i2cWriteByteData(i2c_handle, SENSOR_ADDR, ENABLE_REG, enable) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read heart rate
        uint16_t raw_heart_rate;
        if (i2cReadWordData(i2c_handle, SENSOR_ADDR, HEART_RATE_REG, &raw_heart_rate) < 0) {
            fprintf(stderr, "Failed to read heart rate\n");
            continue;
        }

        // Convert raw heart rate to BPM
        int bpm = raw_heart_rate * 0.5;

        // Apply moving average
        static int moving_avg[MOVING_AVG_SIZE];
        static int moving_avg_index = 0;
        moving_avg[moving_avg_index] = bpm;
        moving_avg_index = (moving_avg_index + 1) % MOVING_AVG_SIZE;
        int filtered_bpm = 0;
        for (int i = 0; i < MOVING_AVG_SIZE; i++) {
            filtered_bpm += moving_avg[i];
        }
        filtered_bpm /= MOVING_AVG_SIZE;

        // Validate BPM range
        if (filtered_bpm < BPM_MIN || filtered_bpm > BPM_MAX) {
            fprintf(stderr, "Invalid BPM range\n");
            continue;
        }

        // Log heart rate
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%d\n", timestamp, filtered_bpm);
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

void sigint_handler(int signal) {
    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    exit(0);
}

