    struct gpiod_line_request_config config = {
        .consumer = "touch_counter",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN,
    };
    struct gpiod_line *lines[TTP226_CHANNELS];
    for (int i = 0; i < TTP226_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            fprintf(stderr, "Error: Failed to get line %d: %s\n", i, strerror(errno));
            goto error;
        }
        if (gpiod_line_request_config(lines[i], &config) < 0) {
            fprintf(stderr, "Error: Failed to configure line %d: %s\n", i, strerror(errno));
            goto error;
        }
    }

    // Stabilization delay
    usleep(STABILIZATION_DELAY * 1000);

    // Set up signal handlers
    struct sigaction sa = {
        .sa_handler = handle_signal,
        .sa_flags = 0,
    };
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

