    while (running) {
        // Read sensor lines
        int values[TTP226_CHANNELS];
        for (int i = 0; i < TTP226_CHANNELS; i++) {
            values[i] = gpiod_line_get_value(lines[i]);
            if (values[i] < 0) {
                fprintf(stderr, "Error: Failed to read line %d: %s\n", i, strerror(errno));
                continue;
            }
        }

        // Detect rising edges
        for (int i = 0; i < TTP226_CHANNELS; i++) {
            if (values[i] && !values[i - 1]) {
                // Increment counter and update outputs
                int counter = (counter + 1) % 256;
                for (int j = 0; j < OUTPUT_PINS; j++) {
                    gpiod_line_set_value(lines[j], (counter >> j) & 1);
