                fprintf(stderr, "Touch on channel %d | Counter: %d\n", i, counter);
                fprintf(stderr, "%s, Channel: %d, Counter: %d\n", timestamp, i, counter);
            }
        }

        // Sleep for 10 ms
        usleep(10 * 1000);
    }

    // Clean up
    for (int i = 0; i < TTP226_CHANNELS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;

