#define GPIO_PIN_17 17
#define GPIO_PIN_18 18
#define GPIO_PIN_27 27
#define GPIO_PIN_22 22

static gpiod_chip_t *chip;
static gpiod_line_t *lines[GPIO_PINS];
static FILE *csv_file;

static void handle_sigint(int signum) {
    printf("Received SIGINT, shutting down...\n");
    gpiod_chip_close(chip);
    fclose(csv_file);
    exit(0);
}

static void handle_sigterm(int signum) {
    printf("Received SIGTERM, shutting down...\n");
    gpiod_chip_close(chip);
    fclose(csv_file);
    exit(0);
}

int main(int argc, char *argv[]) {
    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Open the CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request the GPIO lines
    for (int i = 0; i < GPIO_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", i, strerror(errno));
            return 1;
        }
    }

    // Set the GPIO lines to input mode
    for (int i = 0; i < GPIO_PINS; i++) {
        if (gpiod_line_request_input(lines[i]) != 0) {
            fprintf(stderr, "Error setting GPIO line %d to input mode: %s\n", i, strerror(errno));
            return 1;
        }
    }

    // Write the header row
    fprintf(csv_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");

    // Poll the sensors every 100 ms
    while (1) {
        // Get the current time
        time_t now = time(NULL);

        // Read the sensor values
        int sensor_values[GPIO_PINS];
        for (int i = 0; i < GPIO_PINS; i++) {
            sensor_values[i] = gpiod_line_get_value(lines[i]);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error reading GPIO line %d: %s\n", i, strerror(errno));
                return 1;
            }
        }

        // Write the sensor values to the CSV file
        fprintf(csv_file, "%ld,%d,%d,%d,%d\n", now, sensor_values[0], sensor_values[1], sensor_values[2], sensor_values[3]);

        // Flush the file to ensure data is not lost on abrupt termination
        fflush(csv_file);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close the CSV file and release the GPIO resources
    fclose(csv_file);
    gpiod_chip_close(chip);

    return 0;
}

