#include <stdbool.h>
#include <stdint.h>
#include <signal.h>
#include <pigpio.h>

#define MIC_PIN 4
#define LED_PIN 17
#define SAMPLE_PERIOD 125
#define LED_ON_DURATION 100

volatile sig_atomic_t running = true;

void sigint_handler(int signum) {
    running = false;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", MIC_PIN);
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        uint32_t mic_value = gpioRead(MIC_PIN);
        if (mic_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", MIC_PIN);
            continue;
        }

        if (mic_value == 1) {
            uint32_t timestamp = gpioTick();
            printf("%u\n", timestamp);

            if (gpioWrite(LED_PIN, 1) < 0) {
                fprintf(stderr, "Failed to write to GPIO %d\n", LED_PIN);
                continue;
            }

            gpioDelay(LED_ON_DURATION);

            if (gpioWrite(LED_PIN, 0) < 0) {
                fprintf(stderr, "Failed to write to GPIO %d\n", LED_PIN);
                continue;
            }
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    gpioTerminate();

    return 0;
}

