#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define ALS_VISIBLE_LSB 0x24
#define ALS_VISIBLE_MSB 0x25

int main(void) {
    int fd;
    uint16_t als_visible;
    uint8_t lsb, msb;

    // Open the I2C bus
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Read the ALS visible data registers
    if (read(fd, &lsb, 1) != 1) {
        perror("Failed to read ALS visible LSB");
        close(fd);
        return 1;
    }
    if (read(fd, &msb, 1) != 1) {
        perror("Failed to read ALS visible MSB");
        close(fd);
        return 1;
    }

    // Combine the LSB and MSB into a 16-bit value
    als_visible = (lsb << 8) | msb;

    // Log the raw sensor value to the console
    printf("ALS visible: %u\n", als_visible);

    // Close the I2C bus
    close(fd);

    return 0;
}

