#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define TP1 5
#define TP2 6
#define TP3 13
#define TP4 19
#define TP5 26
#define TP6 12
#define TP7 16
#define TP8 20

#define NUM_CHANNELS 8

static bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

int main(void) {
    // Open gpiochip0
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening gpiochip0\n");
        return 1;
    }

    // Request all 8 lines as inputs
    struct gpiod_line *lines[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            fprintf(stderr, "Error requesting line %d\n", i);
            return 1;
        }
        gpiod_line_request_input(lines[i]);
    }

    // Set up SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Poll every 200 ms
    while (running) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        printf("[%.3fs] ", ts.tv_sec + ts.tv_nsec / 1e9);

        // Read all 8 lines
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                fprintf(stderr, "Error reading line %d\n", i);
                return 1;
            }
            printf("CH%d=%d ", i + 1, value);
        }
        printf("\n");

        // Sleep for 200 ms
        struct timespec sleep_ts;
        sleep_ts.tv_sec = 0;
        sleep_ts.tv_nsec = 200000000;
        nanosleep(&sleep_ts, NULL);
    }

    // Release all libgpiod resources
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

