#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x29
#define GPIO_PIN 17
#define THRESHOLD 200

int main(void)
{
    int i2c_fd, gpio_fd;
    uint8_t buf[4];
    uint16_t clear, red, green, blue;
    uint16_t gain, offset;

    // Open I2C device
    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Open GPIO line
    if ((gpio_fd = gpiod_open(GPIO_PIN, "out")) < 0) {
        perror("Failed to open GPIO line");
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        close(gpio_fd);
        return 1;
    }

    // Power on and enable RGBC
    if (write(i2c_fd, "\x00\x00", 2) < 0) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        close(gpio_fd);
        return 1;
    }

    // Set integration time to 154 ms and gain to 1x
    if (write(i2c_fd, "\x00\x00", 2) < 0) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        close(gpio_fd);
        return 1;
    }

    // Verify sensor ID
    if (read(i2c_fd, buf, 2) < 0) {
        perror("Failed to read from I2C device");
        close(i2c_fd);
        close(gpio_fd);
        return 1;
    }
    if (buf[0] != 0x44) {
        fprintf(stderr, "Invalid sensor ID: 0x%02x\n", buf[0]);
        close(i2c_fd);
        close(gpio_fd);
        return 1;
    }

    // Read channel registers
    if (read(i2c_fd, buf, 8) < 0) {
        perror("Failed to read from I2C device");
        close(i2c_fd);
        close(gpio_fd);
        return 1;
    }
    clear = (buf[1] << 8) | buf[0];
    red = (buf[3] << 8) | buf[2];
    green = (buf[5] << 8) | buf[4];
    blue = (buf[7] << 8) | buf[6];

    // Apply gain and offset calibration
    gain = 1;
    offset = 0;
    clear = (clear * gain) + offset;
    red = (red * gain) + offset;
    green = (green * gain) + offset;
    blue = (blue * gain) + offset;

    // Display calibrated RGB and clear values
    printf("Clear: %d\nRed: %d\nGreen: %d\nBlue: %d\n", clear, red, green, blue);

    // Drive LED
    if (red > THRESHOLD) {
        gpiod_set_value(gpio_fd, 1);
    } else {
        gpiod_set_value(gpio_fd, 0);
    }

    // Poll sensor every 200 ms
    while (1) {
        usleep(200000);

        // Read channel registers
        if (read(i2c_fd, buf, 8) < 0) {
            perror("Failed to read from I2C device");
            close(i2c_fd);
            close(gpio_fd);
            return 1;
        }
        clear = (buf[1] << 8) | buf[0];
        red = (buf[3] << 8) | buf[2];
        green = (buf[5] << 8) | buf[4];
        blue = (buf[7] << 8) | buf[6];

        // Apply gain and offset calibration
        clear = (clear * gain) + offset;
        red = (red * gain) + offset;
        green = (green * gain) + offset;
        blue = (blue * gain) + offset;

        // Display calibrated RGB and clear values
        printf("Clear: %d\nRed: %d\nGreen: %d\nBlue: %d\n", clear, red, green, blue);

        // Drive LED
        if (red > THRESHOLD) {
            gpiod_set_value(gpio_fd, 1);
        } else {
            gpiod_set_value(gpio_fd, 0);
        }
    }

    // Clean up
    close(i2c_fd);
    close(gpio_fd);
    return 0;
}

