#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x23
#define BH1750_CMD_H_RES_MODE 0x20
#define BH1750_CMD_L_RES_MODE 0x21
#define BH1750_CMD_ONCE 0x23
#define BH1750_CMD_CONT 0x10
#define BH1750_CMD_STOP 0x11

#define APA102_START_FRAME 0x000000E0
#define APA102_END_FRAME 0x000000FF
#define APA102_LED_FRAME(brightness, blue, green, red) (0xE0000000 | (brightness << 24) | (blue << 16) | (green << 8) | red)

#define SPI_SPEED 1000000
#define SPI_MODE 0

int main(void) {
    int i2c_fd, spi_fd;
    uint8_t i2c_addr = BH1750_ADDR;
    uint8_t i2c_cmd = BH1750_CMD_H_RES_MODE;
    uint8_t i2c_data[2];
    uint16_t lux;
    uint8_t brightness;
    uint32_t spi_data[3];

    // Open I2C and SPI devices
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }
    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, i2c_addr) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_SPEED, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        return 1;
    }

    // Send I2C command to start measurement
    if (write(i2c_fd, &i2c_cmd, 1) != 1) {
        perror("Failed to send I2C command");
        return 1;
    }

    // Wait for measurement to complete
    usleep(120000);

    // Read I2C data
    if (read(i2c_fd, i2c_data, 2) != 2) {
        perror("Failed to read I2C data");
        return 1;
    }

    // Convert raw data to lux
    lux = (i2c_data[0] << 8) | i2c_data[1];
    lux = lux / 1.2;

    // Map lux range to APA102 brightness range
    brightness = (lux - 10) / 290;
    brightness = brightness > 31 ? 31 : brightness;

    // Set APA102 LED frame
    spi_data[0] = APA102_START_FRAME;
    spi_data[1] = APA102_LED_FRAME(brightness, 0, 0, 0);
    spi_data[2] = APA102_END_FRAME;

    // Send SPI data
    if (write(spi_fd, spi_data, 3) != 3) {
        perror("Failed to send SPI data");
        return 1;
    }

    // Close I2C and SPI devices
    close(i2c_fd);
    close(spi_fd);

    return 0;
}

