      exit(1);
    }
  }
}

static void init_spi(void) {
  spi_fd = spi_open(SPI_MOSI, SPI_SCLK, 0);
  if (spi_fd < 0) {
    printf("Error opening SPI bus at MOSI %d and SCLK %d\n", SPI_MOSI, SPI_SCLK);
    exit(1);
  }
}

