  for (int i = 0; i < NUM_SENSORS; i++) {
    uint8_t cmd = BH1750_CMD_HIGH_RES_MODE;
    if (i2c_write(i2c_fd[i], &cmd, 1) != 1) {
      printf("Error writing to I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR_LOW + i);
      exit(1);
    }
  }
}

static void read_sensors(void) {
  uint8_t data[NUM_SENSORS * NUM_BYTES];
  for (int i = 0; i < NUM_SENSORS; i++) {
    uint8_t cmd = BH1750_CMD_READ;
    if (i2c_write(i2c_fd[i], &cmd, 1) != 1) {
