#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod/libgpiod.h>

#define I2C_ADDR 0x10
#define I2C_REG_ALS 0x04
#define I2C_REG_CONFIG 0x00
#define I2C_REG_GAIN 0x01
#define I2C_REG_INTEGRATION_TIME 0x02

#define GPIO_PIN 18
#define BIT_BANG_FREQ 800000
#define BIT_BANG_DUTY_CYCLE 0.5

#define LUX_TO_BRIGHTNESS_GAMMA 2.2
#define LUX_TO_BRIGHTNESS_SCALE 120000.0

#define MAX_RETRIES 3
#define RETRY_DELAY 100000

int main(int argc, char *argv[]) {
    // Initialize I2C device
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Initialize GPIO pin
    int gpio_fd = gpiod_open(GPIO_PIN, "out");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO pin");
        return 1;
    }

    // Set I2C device address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C device address");
        return 1;
    }

    // Set I2C configuration
    uint16_t config = 0x0000;
    if (i2c_write(i2c_fd, I2C_REG_CONFIG, &config, 2) < 0) {
        perror("Failed to set I2C configuration");
        return 1;
    }

    // Set I2C gain
    uint16_t gain = 0x01;
    if (i2c_write(i2c_fd, I2C_REG_GAIN, &gain, 2) < 0) {
        perror("Failed to set I2C gain");
        return 1;
    }

    // Set I2C integration time
    uint16_t integration_time = 0x02;
    if (i2c_write(i2c_fd, I2C_REG_INTEGRATION_TIME, &integration_time, 2) < 0) {
        perror("Failed to set I2C integration time");
        return 1;
    }

    // Set GPIO pin to output
    if (gpiod_set_direction(gpio_fd, GPIO_PIN, GPIO_OUT) < 0) {
        perror("Failed to set GPIO pin direction");
        return 1;
    }

    // Set GPIO pin to low
    if (gpiod_set_value(gpio_fd, GPIO_PIN, GPIO_LOW) < 0) {
        perror("Failed to set GPIO pin value");
        return 1;
    }

    // Set bit-banging frequency
    if (gpiod_set_frequency(gpio_fd, GPIO_PIN, BIT_BANG_FREQ) < 0) {
        perror("Failed to set GPIO pin frequency");
        return 1;
    }

    // Set bit-banging duty cycle
    if (gpiod_set_duty_cycle(gpio_fd, GPIO_PIN, BIT_BANG_DUTY_CYCLE) < 0) {
        perror("Failed to set GPIO pin duty cycle");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read ALS data from I2C
        uint16_t raw_als;
        if (i2c_read(i2c_fd, I2C_REG_ALS, &raw_als, 2) < 0) {
            perror("Failed to read ALS data");
            return 1;
        }

        // Convert raw ALS data to lux
        double lux = raw_als * 0.0036 * (1 / gain) * (100 / integration_time);

        // Map lux to brightness
        uint8_t brightness = 255 * pow(lux / LUX_TO_BRIGHTNESS_SCALE, 1 / LUX_TO_BRIGHTNESS_GAMMA);

        // Set GPIO pin to high
        if (gpiod_set_value(gpio_fd, GPIO_PIN, GPIO_HIGH) < 0) {
            perror("Failed to set GPIO pin value");
            return 1;
        }

        // Set GPIO pin to low
        if (gpiod_set_value(gpio_fd, GPIO_PIN, GPIO_LOW) < 0) {
            perror("Failed to set GPIO pin value");
            return 1;
        }

        // Print lux and brightness values
        printf("Lux: %f, Brightness: %d\n", lux, brightness);

        // Sleep for 200 ms
        usleep(200000);
    }

    // Clean up
    gpiod_close(gpio_fd);
    close(i2c_fd);

    return 0;
}

void signal_handler(int signal) {
    // Clean up
    gpiod_close(gpio_fd);
    close(i2c_fd);

    // Turn off LED strip
    gpiod_set_value(gpio_fd, GPIO_PIN, GPIO_LOW);

    // Exit program
    exit(0);
}

