#define I2C_ADDR 0x23
#define I2C_DEV "/dev/i2c-1"
#define GPIO_PIN 17
#define BUFFER_SIZE 60

int main(void) {
    // Initialize I2C device
    int i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Initialize GPIO pin
    int gpio_fd = open("/sys/class/gpio/gpiochip0/gpio17", O_RDWR);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO pin");
        return 1;
    }

    // Set GPIO pin to output mode
    if (ioctl(gpio_fd, GPIO_SET_OUTPUT, GPIO_PIN) < 0) {
        perror("Failed to set GPIO pin to output mode");
        return 1;
    }

    // Set I2C device address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C device address");
        return 1;
    }

    // Initialize circular buffer for lux readings
    uint16_t buffer[BUFFER_SIZE];
    int buffer_index = 0;

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read lux value from I2C device
        uint16_t raw_lux;
        if (read(i2c_fd, &raw_lux, sizeof(raw_lux)) != sizeof(raw_lux)) {
            perror("Failed to read lux value from I2C device");
            continue;
        }

        // Convert raw lux value to lux
        float lux = raw_lux / 1.2;

        // Store lux value in circular buffer
        buffer[buffer_index] = lux;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Compute average lux over circular buffer
        float avg_lux = 0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            avg_lux += buffer[i];
        }
        avg_lux /= BUFFER_SIZE;

        // Set GPIO pin to blink at rate proportional to average lux
        float rate = 0.5 + (avg_lux / 1000) * 4.5;
        rate = fmin(rate, 5.0);
        rate = fmax(rate, 0.5);
        if (ioctl(gpio_fd, GPIO_SET_PWM, GPIO_PIN, rate) < 0) {
            perror("Failed to set GPIO pin PWM");
            return 1;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up on exit
    close(i2c_fd);
    close(gpio_fd);
    return 0;
}

void signal_handler(int signal) {
    // Clean up on signal
    close(i2c_fd);
    close(gpio_fd);
    exit(0);
}

