#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <libgpiod.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

#define SEGMENT_A 0x01
#define SEGMENT_B 0x02
#define SEGMENT_C 0x04
#define SEGMENT_D 0x08
#define SEGMENT_E 0x10
#define SEGMENT_F 0x20
#define SEGMENT_G 0x40
#define SEGMENT_DP 0x80

#define SEGMENT_5 (SEGMENT_A | SEGMENT_B | SEGMENT_C | SEGMENT_D | SEGMENT_E | SEGMENT_G)

int main() {
    // Initialize libgpiod
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Set all three pins as outputs
    struct gpiod_line *data_line = gpiod_chip_get_line(chip, DATA_PIN);
    struct gpiod_line *clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    struct gpiod_line *latch_line = gpiod_chip_get_line(chip, LATCH_PIN);
    if (!data_line || !clock_line || !latch_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(data_line, "data", 0) < 0 ||
        gpiod_line_request_output(clock_line, "clock", 0) < 0 ||
        gpiod_line_request_output(latch_line, "latch", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_line_free(data_line);
        gpiod_line_free(clock_line);
        gpiod_line_free(latch_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Implement a robust shift-out function that sends 8 bits MSB-first with proper clock and latch timing
    void shift_out(uint8_t data) {
        // Set data line to low
        gpiod_line_set_value(data_line, 0);

        // Set clock line to low
        gpiod_line_set_value(clock_line, 0);

        // Shift out the data bit by bit
        for (int i = 0; i < 8; i++) {
            // Set clock line to high
            gpiod_line_set_value(clock_line, 1);

            // Set data line to high if the corresponding bit is set
            gpiod_line_set_value(data_line, (data & (1 << (7 - i))) != 0);

            // Set clock line to low
            gpiod_line_set_value(clock_line, 0);
        }

        // Set latch line to high
        gpiod_line_set_value(latch_line, 1);

        // Set latch line to low
        gpiod_line_set_value(latch_line, 0);
    }

    // Blink the digit indefinitely
    while (1) {
        // Set the display to the digit '5'
        shift_out(SEGMENT_5);

        // Wait for 500 ms
        usleep(500000);

        // Set the display to all segments off
        shift_out(0);

        // Wait for 500 ms
        usleep(500000);
    }

    // Cleanup on exit by releasing the lines and closing the chip
    gpiod_line_free(data_line);
    gpiod_line_free(clock_line);
    gpiod_line_free(latch_line);
    gpiod_chip_close(chip);

    return 0;
}

