#include <signal.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18

static volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line, *button_line;
    int ret;

    // Open GPIO chip 0
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip 0\n");
        return 1;
    }

    // Request LED line as output initially low
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error requesting LED line\n");
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting LED line as output\n");
        gpiod_line_free(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request button line as input with internal pull-up and falling-edge event detection
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Error requesting button line\n");
        gpiod_line_free(led_line);
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_request_input(button_line, "blink_button");
    if (ret < 0) {
        fprintf(stderr, "Error requesting button line as input\n");
        gpiod_line_free(button_line);
        gpiod_line_free(led_line);
        gpiod_chip_close(chip);
        return 1;
    }
    ret = gpiod_line_set_config(button_line, GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE);
    if (ret < 0) {
        fprintf(stderr, "Error setting button line event configuration\n");
        gpiod_line_free(button_line);
        gpiod_line_free(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handling for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (!stop) {
        // Toggle LED
        ret = gpiod_line_set_value(led_line, !gpiod_line_get_value(led_line));
        if (ret < 0) {
            fprintf(stderr, "Error setting LED line value\n");
            break;
        }

        // Wait for button event with 1-second timeout
        struct gpiod_line_event event;
        ret = gpiod_line_event_wait(button_line, &event, 1000);
        if (ret < 0) {
            fprintf(stderr, "Error waiting for button event\n");
            break;
        }

        // Check for button press
        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            // Stop blinking and turn off LED
            gpiod_line_set_value(led_line, 0);
            printf("Button pressed, exiting\n");
            break;
        }
    }

    // Clean up
    gpiod_line_free(button_line);
    gpiod_line_free(led_line);
    gpiod_chip_close(chip);

    return 0;
}

