#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define LED_PIN 24
#define BUTTON_PIN 22
#define LED_ON 1
#define LED_OFF 0
#define BUTTON_PRESSED 1
#define BUTTON_RELEASED 0

static int gpio_chip = -1;
static int led_line = -1;
static int button_line = -1;

static void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, exiting...\n", signum);
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(gpio_chip);
        exit(0);
    }
}

static void setup_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (gpio_chip < 0) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        exit(1);
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_PIN);
    if (led_line < 0) {
        fprintf(stderr, "Error getting line for LED: %s\n", strerror(errno));
        exit(1);
    }

    button_line = gpiod_chip_get_line(gpio_chip, BUTTON_PIN);
    if (button_line < 0) {
        fprintf(stderr, "Error getting line for button: %s\n", strerror(errno));
        exit(1);
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Error requesting output for LED: %s\n", strerror(errno));
        exit(1);
    }

    if (gpiod_line_request_input(button_line, "button") < 0) {
        fprintf(stderr, "Error requesting input for button: %s\n", strerror(errno));
        exit(1);
    }
}

static void loop() {
    int button_value = 0;
    int led_value = LED_OFF;

    while (1) {
        if (gpiod_line_get_value(button_line, &button_value) < 0) {
            fprintf(stderr, "Error reading button value: %s\n", strerror(errno));
            exit(1);
        }

        if (button_value == BUTTON_PRESSED) {
            led_value = LED_ON;
        } else {
            led_value = LED_OFF;
        }

        if (gpiod_line_set_value(led_line, led_value) < 0) {
            fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
            exit(1);
        }

        usleep(500000);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();
    loop();

    return 0;
}

