        return 1;
    }

    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    if (!green_line) {
        fprintf(stderr, "Failed to get GPIO line for green LED\n");
        return 1;
    }

    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!blue_line) {
        fprintf(stderr, "Failed to get GPIO line for blue LED\n");
        return 1;
    }

    // Set GPIO lines as outputs
    if (gpiod_line_request_output(red_line, "red_led", 0) < 0) {
        fprintf(stderr, "Failed to set red LED as output\n");
        return 1;
    }

    if (gpiod_line_request_output(green_line, "green_led", 0) < 0) {
        fprintf(stderr, "Failed to set green LED as output\n");
        return 1;
    }

    if (gpiod_line_request_output(blue_line, "blue_led", 0) < 0) {
        fprintf(stderr, "Failed to set blue LED as output\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Generate random RGB values
        srand(time(NULL));
        red_value = rand() % 101;
        green_value = rand() % 101;
        blue_value = rand() % 101;

        // Set PWM duty cycles
        gpiod_line_set_value(red_line, red_value);
        gpiod_line_set_value(green_line, green_value);
        gpiod_line_set_value(blue_line, blue_value);

