#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x19
#define CTRL_REG1_A 0x27
#define CTRL_REG4_A 0x00
#define OUT_X_L_A 0x28
#define GPIO_PIN 17
#define G_THRESHOLD 2.0

static volatile bool running = true;

void sigint_handler(int signum) {
    running = false;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    double g_threshold = G_THRESHOLD;
    if (argc > 1) {
        g_threshold = atof(argv[1]);
    }

    // Initialize pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up I2C bus
    int i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Set up GPIO pin
    int gpio_handle = pigpio_gpio_open(GPIO_PIN);
    if (gpio_handle < 0) {
        fprintf(stderr, "Failed to open GPIO pin\n");
        return 1;
    }

    // Configure accelerometer
    uint8_t ctrl_reg1_a = CTRL_REG1_A;
    uint8_t ctrl_reg4_a = CTRL_REG4_A;
    if (pigpio_i2c_write(i2c_handle, &ctrl_reg1_a, 1) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1_A\n");
        return 1;
    }
    if (pigpio_i2c_write(i2c_handle, &ctrl_reg4_a, 1) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4_A\n");
        return 1;
    }

    // Set up signal handler for SIGINT/SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (running) {
        // Read accelerometer data
        uint8_t data[6];
        if (pigpio_i2c_read(i2c_handle, OUT_X_L_A, data, 6) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            return 1;
        }

        // Calculate total G-force magnitude
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];
        double g_force = sqrt(x * x + y * y + z * z);

        // Check for sudden impact
        if (g_force > g_threshold) {
            // Pulse GPIO pin
            pigpio_gpio_write(gpio_handle, 1);
            usleep(50000);
            pigpio_gpio_write(gpio_handle, 0);

            // Log accelerometer data
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
            fprintf(stderr, "%s: G-force = %.2f\n", timestamp, g_force);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up resources
    pigpio_i2c_close(i2c_handle);
    pigpio_gpio_close(gpio_handle);
    pigpio_stop();

    return 0;
}

