#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <i2c.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define MODE_REG 0x0D
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_REG 0x66
#define GREEN_REG 0x68
#define BLUE_REG 0x6A

#define LED_PIN 18
#define PWM_FREQ 1000

int main(void) {
    // Initialize pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Initialize I2C bus
    int i2c_handle = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Initialize LED pin
    if (gpio_mode_setup(LED_PIN, GPIO_OUTPUT, GPIO_PWM_OUTPUT, 0) < 0) {
        fprintf(stderr, "Failed to set up LED pin\n");
        return 1;
    }

    // Set up PWM
    if (gpio_pwm_setup(LED_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set up PWM\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize CSV file
    FILE *csv_file = fopen("color_log.csv", "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return 1;
    }
    fprintf(csv_file, "timestamp,als,r,g,b\n");

    // Main loop
    while (1) {
        // Read ALS data
        uint16_t als_data = read_als_data(i2c_handle);
        if (als_data < 0) {
            fprintf(stderr, "Failed to read ALS data\n");
            continue;
        }

        // Read color data
        uint16_t red_data = read_color_data(i2c_handle, RED_REG);
        if (red_data < 0) {
            fprintf(stderr, "Failed to read red data\n");
            continue;
        }
        uint16_t green_data = read_color_data(i2c_handle, GREEN_REG);
        if (green_data < 0) {
            fprintf(stderr, "Failed to read green data\n");
            continue;
        }
        uint16_t blue_data = read_color_data(i2c_handle, BLUE_REG);
        if (blue_data < 0) {
            fprintf(stderr, "Failed to read blue data\n");
            continue;
        }

        // Map ALS data to PWM duty cycle
        uint8_t pwm_duty_cycle = map_als_to_pwm(als_data);

        // Set PWM duty cycle
        gpio_pwm_set_duty_cycle(LED_PIN, pwm_duty_cycle);

        // Log data to CSV file
        fprintf(csv_file, "%ld,%d,%d,%d,%d\n", time(NULL), als_data, red_data, green_data, blue_data);

        // Sleep for 500 ms
        usleep(500000);
    }

    // Clean up
    fclose(csv_file);
    gpio_pwm_stop(LED_PIN);
    gpio_mode_setup(LED_PIN, GPIO_INPUT, GPIO_PWM_OUTPUT, 0);
    i2c_close(i2c_handle);
    pigpio_stop(NULL);

    return 0;
}

// Read ALS data from I2C bus
uint16_t read_als_data(int i2c_handle) {
    uint16_t als_data = 0;
    if (i2c_read_word_data(i2c_handle, ALS_LSB_REG, &als_data) < 0) {
        fprintf(stderr, "Failed to read ALS data\n");
        return -1;
    }
    return als_data;
}

// Read color data from I2C bus
uint16_t read_color_data(int i2c_handle, uint8_t reg) {
    uint16_t color_data = 0;
    if (i2c_read_word_data(i2c_handle, reg, &color_data) < 0) {
        fprintf(stderr, "Failed to read color data\n");
        return -1;
    }
    return color_data;
