#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1F
#define WHO_AM_I_REG 0x0D
#define XYZ_DATA_CFG_REG 0x0E
#define CTRL_REG1_REG 0x2A
#define OUT_X_MSB_REG 0x01
#define SENSITIVITY 4096
#define THRESHOLD 19.62

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C handle
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    // Verify sensor by reading WHO_AM_I register
    uint8_t who_am_i;
    if (i2cReadByteData(i2c_handle, WHO_AM_I_REG, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return 1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "Invalid WHO_AM_I value: %02X\n", who_am_i);
        return 1;
    }

    // Initialize sensor
    uint8_t ctrl_reg1 = 0;
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_REG, ctrl_reg1) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1 register\n");
        return 1;
    }
    uint8_t xyz_data_cfg = 0;
    if (i2cWriteByteData(i2c_handle, XYZ_DATA_CFG_REG, xyz_data_cfg) < 0) {
        fprintf(stderr, "Failed to write XYZ_DATA_CFG register\n");
        return 1;
    }

    // Set sensor to active mode
    ctrl_reg1 |= 1;
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_REG, ctrl_reg1) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1 register\n");
        return 1;
    }

    // Open impact log file
    FILE *impact_log = fopen("impact_log.txt", "a");
    if (impact_log == NULL) {
        fprintf(stderr, "Failed to open impact log file\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read acceleration data
        uint8_t data[6];
        if (i2cReadI2CBlockData(i2c_handle, OUT_X_MSB_REG, data, 6) < 0) {
            fprintf(stderr, "Failed to read acceleration data\n");
            continue;
        }

        // Convert acceleration data to m/s^2
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];
        double x_m = (double)x / SENSITIVITY * 9.81;
        double y_m = (double)y / SENSITIVITY * 9.81;
        double z_m = (double)z / SENSITIVITY * 9.81;

        // Compute magnitude
        double magnitude = sqrt(x_m * x_m + y_m * y_m + z_m * z_m);

        // Check for impact
        if (magnitude > THRESHOLD) {
            // Log impact
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            fprintf(impact_log, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f,%.3f\n",
                    tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
                    tm->tm_hour, tm->tm_min, tm->tm_sec,
                    x_m, y_m, z_m, magnitude);
        }

        // Sleep for 50 ms
        usleep(50000);
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Close impact log file
    fclose(impact_log);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

