#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F
#define SENSITIVITY 0.00875
#define CALIBRATION_SAMPLES 100
#define LOG_FILE "gyro_log.txt"
#define WARNING_THRESHOLD 50

int main(void) {
    int fd;
    int i;
    int16_t x, y, z;
    int16_t x_offset, y_offset, z_offset;
    int16_t x_cal, y_cal, z_cal;
    char buf[6];
    char timestamp[20];
    FILE *log_file;

    // Open I2C bus
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Check WHO_AM_I register
    if (ioctl(fd, I2C_RDWR, &buf) < 0) {
        perror("Failed to read WHO_AM_I register");
        close(fd);
        return 1;
    }
    if (buf[0] != 0xD3) {
        fprintf(stderr, "Sensor not detected\n");
        close(fd);
        return 1;
    }

    // Configure CTRL_REG1 and CTRL_REG4
    buf[0] = CTRL_REG1;
    buf[1] = 0x0F;
    if (ioctl(fd, I2C_RDWR, &buf) < 0) {
        perror("Failed to write CTRL_REG1");
        close(fd);
        return 1;
    }
    buf[0] = CTRL_REG4;
    buf[1] = 0x00;
    if (ioctl(fd, I2C_RDWR, &buf) < 0) {
        perror("Failed to write CTRL_REG4");
        close(fd);
        return 1;
    }

    // Perform calibration
    x_offset = 0;
    y_offset = 0;
    z_offset = 0;
    for (i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (ioctl(fd, I2C_RDWR, &buf) < 0) {
            perror("Failed to read calibration data");
            close(fd);
            return 1;
        }
        x_cal = (buf[0] << 8) | buf[1];
        y_cal = (buf[2] << 8) | buf[3];
        z_cal = (buf[4] << 8) | buf[5];
        x_offset += x_cal;
        y_offset += y_cal;
        z_offset += z_cal;
    }
    x_offset /= CALIBRATION_SAMPLES;
    y_offset /= CALIBRATION_SAMPLES;
    z_offset /= CALIBRATION_SAMPLES;

    // Open log file
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read gyroscope data
        if (ioctl(fd, I2C_RDWR, &buf) < 0) {
            perror("Failed to read gyroscope data");
            close(fd);
            return 1;
        }
        x = (buf[0] << 8) | buf[1];
        y = (buf[2] << 8) | buf[3];
        z = (buf[4] << 8) | buf[5];

        // Convert to degrees per second
        x = (x - x_offset) * SENSITIVITY;
        y = (y - y_offset) * SENSITIVITY;
        z = (z - z_offset) * SENSITIVITY;

        // Check for warning
        if (x > WARNING_THRESHOLD || y > WARNING_THRESHOLD || z > WARNING_THRESHOLD) {
            fprintf(stderr, "Warning: Gyroscope reading exceeds threshold\n");
            fprintf(log_file, "Warning: Gyroscope reading exceeds threshold\n");
        }

        // Log data
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);

        // Sleep for 50 ms
        usleep(50000);
    }

    // Clean up
    fclose(log_file);
    close(fd);

    return 0;
}

