#define SENSOR2_ADDR 0x69
#define CTRL_REG 0x00
#define DATA_REG 0x01
#define SAMPLE_INTERVAL 10

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    int fd, i2c_handle, sensor1_handle, sensor2_handle;
    uint16_t sensor1_data, sensor2_data;
    int16_t tdoa;
    struct timespec ts;
    struct tm *tm;
    char buf[1024];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, 0, 0, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        return 1;
    }

    // Open sensor 1
    sensor1_handle = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0, 0);
    if (sensor1_handle < 0) {
        fprintf(stderr, "Failed to open sensor 1 at address 0x%02x\n", SENSOR1_ADDR);
        return 1;
    }

    // Open sensor 2
    sensor2_handle = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0, 0);
    if (sensor2_handle < 0) {
        fprintf(stderr, "Failed to open sensor 2 at address 0x%02x\n", SENSOR2_ADDR);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Open log file
    fd = open("audio_log.dat", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor 1 data
        if (i2cReadWordData(sensor1_handle, DATA_REG, &sensor1_data) < 0) {
            fprintf(stderr, "Failed to read sensor 1 data\n");
            continue;
        }

        // Read sensor 2 data
        if (i2cReadWordData(sensor2_handle, DATA_REG, &sensor2_data) < 0) {
            fprintf(stderr, "Failed to read sensor 2 data\n");
            continue;
        }

        // Compute TDOA
        tdoa = sensor1_data - sensor2_data;

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);
        tm = localtime(&ts.tv_sec);

        // Write log entry
        snprintf(buf, sizeof(buf), "%d,%d,%d,%d,%d\n", tm->tm_sec, tm->tm_nsec, sensor1_data, sensor2_data, tdoa);
        write(fd, buf, strlen(buf));

        // Sleep for sampling interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Clean up
    close(fd);
    i2cClose(sensor1_handle);
    i2cClose(sensor2_handle);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

