#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod/libgpiod.h>

#define SPI_BUS 0
#define SPI_CS 8
#define SPI_MODE 3
#define SPI_SPEED 1000000

#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

#define GYRO_SCALE 0.02
#define ACCL_SCALE 0.00025

int main(void) {
    // Initialize libgpiod
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Open SPI device
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode and speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        return 1;
    }
    ret = ioctl(spi_fd, SPI_IOC_WR_SPEED, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        return 1;
    }

    // Initialize chip-select line
    chip = gpiod_chip_open_by_number(SPI_CS);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }
    line = gpiod_chip_get_line(chip, SPI_CS);
    if (!line) {
        perror("Failed to get GPIO line");
        return 1;
    }
    ret = gpiod_line_request_output(line, "spi-cs", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        return 1;
    }

    // Read gyroscope and accelerometer data
    uint16_t gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z;
    while (1) {
        // Set chip-select line low
        gpiod_line_set_value(line, 0);

        // Send register address with bit 7 set (0x80)
        uint16_t reg_addr = XGYRO_OUT | 0x80;
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &reg_addr);
        if (ret < 0) {
            perror("Failed to send register address");
            return 1;
        }

        // Read gyroscope X data
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &gyro_x);
        if (ret < 0) {
            perror("Failed to read gyroscope X data");
            return 1;
        }
        gyro_x = (gyro_x >> 8) | (gyro_x << 8);

        // Read gyroscope Y data
