#define ADIS16448_SPI_SPEED 1000000
#define ADIS16448_SPI_MODE 0

#define ADIS16448_GYRO_X_REG 0x04
#define ADIS16448_GYRO_Y_REG 0x06
#define ADIS16448_GYRO_Z_REG 0x08
#define ADIS16448_ACCL_X_REG 0x0A
#define ADIS16448_ACCL_Y_REG 0x0C
#define ADIS16448_ACCL_Z_REG 0x0E

#define GYRO_SCALE 0.05
#define ACCL_SCALE 0.00025

int main(void) {
    int spi_handle;
    int gyro_x, gyro_y, gyro_z;
    int accl_x, accl_y, accl_z;
    uint16_t data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI channel 0
    spi_handle = spiOpen(ADIS16448_SPI_CHANNEL, ADIS16448_SPI_SPEED, ADIS16448_SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", ADIS16448_SPI_CHANNEL);
        return 1;
    }

    // Set up SPI transfer
    spiSetDataMode(spi_handle, SPI_MODE_0);
    spiSetBitOrder(spi_handle, SPI_MSB_FIRST);
    spiSetClockDivider(spi_handle, SPI_CLOCK_DIV_128);

    // Main loop
    while (1) {
        // Read gyroscope x, y, z
        spiTransfer(spi_handle, ADIS16448_GYRO_X_REG, &data, 2);
        gyro_x = (int16_t)data;
        spiTransfer(spi_handle, ADIS16448_GYRO_Y_REG, &data, 2);
        gyro_y = (int16_t)data;
        spiTransfer(spi_handle, ADIS16448_GYRO_Z_REG, &data, 2);
        gyro_z = (int16_t)data;

        // Read accelerometer x, y, z
        spiTransfer(spi_handle, ADIS16448_ACCL_X_REG, &data, 2);
        accl_x = (int16_t)data;
        spiTransfer(spi_handle, ADIS16448_ACCL_Y_REG, &data, 2);
        accl_y = (int16_t)data;
        spiTransfer(spi_handle, ADIS16448_ACCL_Z_REG, &data, 2);
        accl_z = (int16_t)data;

