#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68

#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B

#define ACCEL_REG_START 0x3B
#define ACCEL_REG_END 0x40
#define GYRO_REG_START 0x43
#define GYRO_REG_END 0x48

#define ACCEL_RANGE 2
#define GYRO_RANGE 250

int main(void) {
    int fd;
    uint8_t who_am_i;
    uint8_t pwr_mgmt_1;
    uint8_t accel_config;
    uint8_t gyro_config;
    uint8_t accel_data[6];
    uint8_t gyro_data[6];

    // Open I2C bus
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Check if sensor is present
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to select I2C slave");
        close(fd);
        return 1;
    }

    if (read(fd, &who_am_i, 1) != 1) {
        perror("Failed to read WHO_AM_I register");
        close(fd);
        return 1;
    }

    if (who_am_i != 0x86) {
        fprintf(stderr, "Sensor not present\n");
        close(fd);
        return 1;
    }

    // Initialize sensor
    pwr_mgmt_1 = 0x00;
    accel_config = 0x00;
    gyro_config = 0x00;

    if (write(fd, &pwr_mgmt_1, 1) != 1) {
        perror("Failed to write PWR_MGMT_1 register");
        close(fd);
        return 1;
    }

    if (write(fd, &accel_config, 1) != 1) {
        perror("Failed to write ACCEL_CONFIG register");
        close(fd);
        return 1;
    }

    if (write(fd, &gyro_config, 1) != 1) {
        perror("Failed to write GYRO_CONFIG register");
        close(fd);
        return 1;
    }

    // Read accelerometer and gyroscope data
    while (1) {
        if (read(fd, accel_data, 6) != 6) {
            perror("Failed to read accelerometer data");
            close(fd);
            return 1;
        }

        if (read(fd, gyro_data, 6) != 6) {
            perror("Failed to read gyroscope data");
            close(fd);
            return 1;
        }

        printf("Accelerometer data: %d, %d, %d\n", accel_data[0], accel_data[1], accel_data[2]);
        printf("Gyroscope data: %d, %d, %d\n", gyro_data[0], gyro_data[1], gyro_data[2]);

        sleep(50);
    }

    close(fd);
    return 0;
}

