#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

#define ADXL345_I2C_ADDR 0x53
#define ADXL345_DEVICE_ID 0xE5
#define ADXL345_DATA_RATE 10
#define ADXL345_RANGE 2
#define ADXL345_RESOLUTION 256
#define ADXL345_X_OFFSET 0
#define ADXL345_Y_OFFSET 1
#define ADXL345_Z_OFFSET 2
#define ADXL345_MG_PER_LSB 0.00390625
#define ADXL345_MG_PER_G 9.80665
#define ADXL345_LED_PIN 17
#define ADXL345_LOG_FILE "impact_log.txt"

int main(int argc, char **argv) {
  // Initialize pigpio library
  if (pigpio_start(NULL, NULL) < 0) {
    fprintf(stderr, "Failed to initialize pigpio library\n");
    return 1;
  }

  // Initialize wiringPi library
  if (wiringPiSetup() < 0) {
    fprintf(stderr, "Failed to initialize wiringPi library\n");
    return 1;
  }

  // Set up I2C bus
  int i2c_fd = wiringPiI2CSetup(ADXL345_I2C_ADDR);
  if (i2c_fd < 0) {
    fprintf(stderr, "Failed to set up I2C bus\n");
    return 1;
  }

  // Set up LED pin
  pinMode(ADXL345_LED_PIN, OUTPUT);

  // Set up log file
  FILE *log_file = fopen(ADXL345_LOG_FILE, "a");
  if (log_file == NULL) {
    fprintf(stderr, "Failed to open log file\n");
    return 1;
  }

  // Verify ADXL345 device ID
  uint8_t device_id;
  if (wiringPiI2CReadReg8(i2c_fd, ADXL345_DEVICE_ID, &device_id) < 0) {
    fprintf(stderr, "Failed to read ADXL345 device ID\n");
    return 1;
  }
  if (device_id != ADXL345_DEVICE_ID) {
    fprintf(stderr, "Invalid ADXL345 device ID: %02X\n", device_id);
    return 1;
  }

  // Set up ADXL345 for full-resolution mode at +-2g range
  uint8_t data_rate = ADXL345_DATA_RATE;
  uint8_t range = ADXL345_RANGE;
  uint8_t resolution = ADXL345_RESOLUTION;
  uint8_t x_offset = ADXL345_X_OFFSET;
  uint8_t y_offset = ADXL345_Y_OFFSET;
  uint8_t z_offset = ADXL345_Z_OFFSET;
  if (wiringPiI2CWriteReg8(i2c_fd, ADXL345_DATA_RATE, data_rate) < 0) {
    fprintf(stderr, "Failed to set ADXL345 data rate\n");
    return 1;
  }
  if (wiringPiI2CWriteReg8(i2c_fd, ADXL345_RANGE, range) < 0) {
    fprintf(stderr, "Failed to set ADXL345 range\n");
    return 1;
  }
  if (wiringPiI2CWriteReg8(i2c_fd, ADXL345_RESOLUTION, resolution) < 0) {
    fprintf(stderr, "Failed to set ADXL345 resolution\n");
    return 1;
  }
  if (wiringPiI2CWriteReg8(i2c_fd, ADXL345_X_OFFSET, x_offset) < 0) {
    fprintf(stderr, "Failed to set ADXL345 X offset\n");
    return 1;
  }
  if (wiringPiI2CWriteReg8(i2c_fd, ADXL345_Y_OFFSET, y_offset) < 0) {
    fprintf(stderr, "Failed to set ADXL345 Y offset\n");
    return 1;
  }
  if (wiringPiI2CWriteReg8(i2c_fd, ADXL345_Z_OFFSET, z_offset) < 0) {
    fprintf(stderr, "Failed to set ADXL345 Z offset\n");
    return 1;
  }

  // Poll sensor every 10 ms
  while (1) {
    // Read acceleration data
    uint8_t data[6];
    if (wiringPiI2CReadReg8(i2c_fd, 0x32, data, 6) < 0) {
      fprintf(stderr, "Failed to read ADXL345 acceleration data\n");
      return 1;
    }

    // Calculate total acceleration magnitude
    int16_t x = (data[0] << 8) | data[1];
    int16_t y = (data[2] << 8) | data[3];
    int16_t z = (data[4] << 8) | data[5];
    float magnitude = sqrt(x * x + y * y + z * z);

    // Check for sudden impact
    if (magnitude > 2.5) {
      // Turn on LED
      digitalWrite(ADXL345_LED_PIN, HIGH);

      // Append timestamped entry to log file
      time_t now = time(NULL);
      struct tm *tm = localtime(&now);
      char timestamp[20];
      strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
      fprintf(log_file, "%s: %f g (%d, %d, %d)\n", timestamp, magnitude, x, y, z);

      // Wait for 500 ms
      usleep(500000);

      // Turn off LED
      digitalWrite(ADXL345_LED_PIN, LOW);
    }

    // Wait for 10 ms
    usleep(10000);
