#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define ACCEL_X_REG 0x01
#define ACCEL_Y_REG 0x03
#define ACCEL_Z_REG 0x05
#define THRESHOLD 2.0
#define LED_GPIO 17

int main(void) {
    // Open I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify sensor identity
    uint8_t who_am_i;
    if (read(i2c_fd, &who_am_i, 1) != 1) {
        perror("Failed to read WHO_AM_I register");
        close(i2c_fd);
        return 1;
    }
    if (who_am_i != 0x1A) {
        fprintf(stderr, "Invalid sensor identity: 0x%02X\n", who_am_i);
        close(i2c_fd);
        return 1;
    }

    // Open GPIO line for LED
    int led_fd = gpiod_open(LED_GPIO, GPIO_OUTPUT);
    if (led_fd < 0) {
        perror("Failed to open LED GPIO line");
        close(i2c_fd);
        return 1;
    }

    // Set up I2C read/write buffers
    uint8_t read_buf[6];
    uint8_t write_buf[1];

    // Poll sensor every 100 ms
    while (1) {
        // Read acceleration data
        write_buf[0] = ACCEL_X_REG;
        if (write(i2c_fd, write_buf, 1) != 1) {
            perror("Failed to write to I2C bus");
            close(i2c_fd);
            close(led_fd);
            return 1;
        }
        if (read(i2c_fd, read_buf, 6) != 6) {
            perror("Failed to read from I2C bus");
            close(i2c_fd);
            close(led_fd);
            return 1;
        }

        // Calculate acceleration magnitude
        float accel_x = (float)((int16_t)((read_buf[1] << 8) | read_buf[0]));
        float accel_y = (float)((int16_t)((read_buf[3] << 8) | read_buf[2]));
        float accel_z = (float)((int16_t)((read_buf[5] << 8) | read_buf[4]));
        float accel_mag = sqrtf(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z);

        // Check for impact
        if (accel_mag > THRESHOLD) {
            // Turn LED on
            gpiod_set_value(led_fd, 1);

            // Append timestamped entry to log file
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
            FILE *fp = fopen("impact_log.txt", "a");
            if (fp == NULL) {
                perror("Failed to open log file");
                close(i2c_fd);
                close(led_fd);
                return 1;
            }
            fprintf(fp, "%s: Impact detected with magnitude %f g\n", timestamp, accel_mag);
            fclose(fp);

            // Wait for 500 ms
            usleep(500000);

            // Turn LED off
            gpiod_set_value(led_fd, 0);
        }

        // Wait for 100 ms
        usleep(100000);
    }

    // Clean up
    close(i2c_fd);
    close(led_fd);
    return 0;
}

