#include <linux/gpio.h>
#include <libgpiod.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x53
#define GPIO_PIN 17
#define THRESH_FF 0x0A
#define TIME_FF 0x20
#define INT_ENABLE 0x2E
#define INT_MAP 0x2F
#define POWER_CTL 0x2D
#define INT_SOURCE 0x30
#define DATAX0 0x32

#define FREEFALL_LOG "freefall_log.csv"

int main(void) {
    // Open the I2C device
    int i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Check the device ID
    uint8_t device_id;
    if (read(i2c_fd, &device_id, 1) != 1) {
        perror("Failed to read device ID");
        close(i2c_fd);
        return 1;
    }
    if (device_id != 0xE5) {
        fprintf(stderr, "Invalid device ID: 0x%02X\n", device_id);
        close(i2c_fd);
        return 1;
    }

    // Put the sensor in standby mode
    uint8_t standby = 0x00;
    if (write(i2c_fd, &standby, 1) != 1) {
        perror("Failed to put sensor in standby mode");
        close(i2c_fd);
        return 1;
    }

    // Configure the sensor
    uint8_t reg_vals[] = {
        THRESH_FF, 0x01,
        TIME_FF, 0x64,
        INT_ENABLE, 0x04,
        INT_MAP, 0x00,
        POWER_CTL, 0x08
    };
    if (write(i2c_fd, reg_vals, sizeof(reg_vals)) != sizeof(reg_vals)) {
        perror("Failed to configure sensor");
        close(i2c_fd);
        return 1;
    }

    // Open the GPIO pin
    int gpio_fd = gpiod_open(GPIO_PIN, "in");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO pin");
        close(i2c_fd);
        return 1;
    }

    // Set up the GPIO event file descriptor
    struct gpiod_event_request req;
    req.lineoffset = GPIO_PIN;
    req.eventflags = GPIOD_CTRL_RISING_EDGE;
    req.timeout = 0;
    int event_fd = gpiod_event_request(gpio_fd, &req);
    if (event_fd < 0) {
        perror("Failed to set up GPIO event file descriptor");
        close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen(FREEFALL_LOG, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(event_fd);
        close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    // Write the header row
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Main loop
    while (1) {
        // Wait for an interrupt
        struct gpiod_event event;
        if (read(event_fd, &event, sizeof(event)) != sizeof(event)) {
            perror("Failed to read GPIO event");
            close(event_fd);
            close(gpio_fd);
            close(i2c_fd);
            fclose(log_file);
            return 1;
        }

        // Read the interrupt source
        uint8_t int_source;
        if (read(i2c_fd, &int_source, 1) != 1) {
            perror("Failed to read interrupt source");
            close(event_fd);
            close(gpio_fd);
            close(i2c_fd);
            fclose(log_file);
            return 1;
        }

        // Check if the freefall bit is set
        if (int_source & 0x04) {
            // Read the acceleration data
            uint8_t data[6];
            if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
                perror("Failed to read acceleration data");
                close(event_fd);
                close(gpio_fd);
                close(i2c_fd);
                fclose(log_file);
                return 1;
            }

            // Log the acceleration values
            fprintf(log_file, "%s,%.3f,%.3f,%.3f\n",
                    get_timestamp(),
                    (float)data[0] / 1000,
                    (float)data[1] / 1000,
                    (float)data[2] / 1000);
        }
    }

    // Clean up
    close(event_fd);
    close(gpio_fd);
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

char *get_timestamp(void) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char *timestamp = malloc(20);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S.%L", tm);
    return timestamp;
}

