#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define ACCEL_RANGE 2
#define GYRO_RANGE 250
#define ODR 104

#define FREEFALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 2.5
#define FREEFALL_WINDOW 1.0

#define WHO_AM_I_REG 0x0F
#define OUT_TEMP_L_REG 0x20
#define OUT_TEMP_H_REG 0x21
#define OUTX_L_G_REG 0x22
#define OUTX_H_G_REG 0x23
#define OUTY_L_G_REG 0x24
#define OUTY_H_G_REG 0x25
#define OUTZ_L_G_REG 0x26
#define OUTZ_H_G_REG 0x27
#define OUTX_L_XL_REG 0x28
#define OUTX_H_XL_REG 0x29
#define OUTY_L_XL_REG 0x2A
#define OUTY_H_XL_REG 0x2B
#define OUTZ_L_XL_REG 0x2C
#define OUTZ_H_XL_REG 0x2D

#define SIGINT_SIGTERM_HANDLER(sig) \
    { \
        printf("Received signal %d, cleaning up...\n", sig); \
        pigpio_close(pi); \
        exit(EXIT_SUCCESS); \
    }

int main(void)
{
    int pi;
    int handle;
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;
    float accel_magnitude, gyro_magnitude;
    float freefall_window_start, freefall_window_end;
    bool freefall_state = false;
    bool impact_state = false;
    char *csv_line;
    FILE *csv_file;

    // Initialize pigpio library
    if ((pi = pigpio_start(NULL, NULL)) < 0)
    {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up I2C bus
    if ((handle = pigpio_i2c_open(pi, I2C_BUS, I2C_ADDR, 0)) < 0)
    {
        fprintf(stderr, "Failed to open I2C bus\n");
        pigpio_close(pi);
        return EXIT_FAILURE;
    }

    // Set up accelerometer and gyroscope
    if (pigpio_i2c_write_byte_data(pi, handle, CTRL1_XL, ACCEL_RANGE) < 0)
    {
        fprintf(stderr, "Failed to set accelerometer range\n");
        pigpio_i2c_close(pi, handle);
        pigpio_close(pi);
        return EXIT_FAILURE;
    }
    if (pigpio_i2c_write_byte_data(pi, handle, CTRL2_G, GYRO_RANGE) < 0)
    {
        fprintf(stderr, "Failed to set gyroscope range\n");
        pigpio_i2c_close(pi, handle);
        pigpio_close(pi);
        return EXIT_FAILURE;
    }
    if (pigpio_i2c_write_byte_data(pi, handle, CTRL3_C, ODR) < 0)
    {
        fprintf(stderr, "Failed to set output data rate\n");
        pigpio_i2c_close(pi, handle);
        pigpio_close(pi);
        return EXIT_FAILURE;
    }

    // Check if sensor is present
    if (pigpio_i2c_read_byte_data(pi, handle, WHO_AM_I_REG) != 0x6A)
    {
        fprintf(stderr, "Sensor not present\n");
        pigpio_i2c_close(pi, handle);
        pigpio_close(pi);
        return EXIT_FAILURE;
    }

    // Set up CSV file
    csv_file = fopen("motion_log.txt", "w");
    if (csv_file == NULL)
    {
        fprintf(stderr, "Failed to open CSV file\n");
        pigpio_i2c_close(pi, handle);
        pigpio_close(pi);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, SIGINT_SIGTERM_HANDLER);
    signal(SIGTERM, SIGINT_SIGTERM_HANDLER);

    // Main loop
    while (true)
    {
        // Read accelerometer and gyroscope data
        if (pigpio_i2c_read_word_data(pi, handle, OUTX_L_G_REG, &accel_x) < 0)
        {
            fprintf(stderr, "Failed to read accelerometer X data\n");
            pigpio_i2c_close(pi, handle);
            pigpio_close(pi);
            return EXIT_FAILURE;
        }
        if (pigpio_i2c_read_word_data(pi, handle, OUTY_L_G_REG, &accel_y) < 0)
        {
            fprintf(stderr, "Failed to read accelerometer Y data\n");
            pigpio_i2c_close(pi, handle);
            pigpio_close(pi);
            return EXIT_FAILURE;
        }
        if (pigpio_i2c_read_word_data(pi, handle, OUTZ_L_G_REG, &accel_z) < 0)
        {
            fprintf(stderr, "Failed to read accelerometer Z data\n");
            pigpio_i2c_close(pi, handle);
            pigpio_close(pi);
            return EXIT_FAILURE;
        }
        if (pigpio_i2c_read_word_data(pi, handle, OUTX_L_XL_REG, &gyro_x) < 0)
        {
            fprintf(stderr, "Failed to read gyroscope X data\n");
            pigpio_i2c_close(pi, handle);
            pigpio_close(pi);
            return EXIT_FAILURE;
        }
        if (pigpio_i2c_read_word_data(pi, handle, OUTY_L_XL_REG, &gyro_y) < 0)
        {
            fprintf(stderr, "Failed to read gyroscope Y data\n");
            pigpio_i2c_close(pi, handle);
            pigpio_close(pi);
            return EXIT_FAILURE;
        }
        if (pigpio_i2c_read_word_data(pi, handle, OUTZ_L_XL_REG, &gyro_z) < 0)
        {
            fprintf(stderr, "Failed to read gyroscope Z data\n");
            pigpio_i2c_close(pi, handle);
            pigpio_close(pi);
            return EXIT_FAILURE;
        }

        // Calculate accelerometer and gyroscope magnitudes
        accel_magnitude = sqrt(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z);
        gyro_magnitude = sqrt(gyro_x * gyro_x + gyro_y * gyro_y + gyro_z * gyro_z);

        // Check for freefall state
        if (accel_magnitude < FREEFALL_THRESHOLD)
        {
            freefall_state = true;
            freefall_window_start = time(NULL);
        }
        else if (freefall_state && time(NULL) - freefall_window_start > FREEFALL_WINDOW)
        {
            freefall_state = false;
        }

        // Check for impact state
        if (accel_magnitude > IMPACT_THRESHOLD)
        {
            impact_state = true;
        }

        // Log data to CSV file
        csv_line = malloc(100);
        if (csv_line == NULL)
        {
            fprintf(stderr, "Failed to allocate memory for CSV line\n");
            pigpio_i2c_close(pi, handle);
            pigpio_close(pi);
