#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define ADIS16266_WHO_AM_I 0x3F5A
#define ADIS16266_X_GYRO_OUT 0x14
#define ADIS16266_SPI_MODE 3
#define ADIS16266_SPI_SPEED 1000000
#define ADIS16266_SPI_BITS 16
#define ADIS16266_SPI_DELAY 0
#define ADIS16266_SCALE 0.0305

#define GYRO_LOG_FILE "gyro_log.csv"

static int spi_handle;
static int spi_fd;
static int spi_mode;
static int spi_speed;
static int spi_bits;
static int spi_delay;
static int spi_cs;

static void sigint_handler(int signum) {
    printf("Caught signal %d, closing SPI handle and terminating pigpio\n", signum);
    pigpio_spi_close(spi_handle);
    pigpio_terminate();
    fclose(spi_fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    // Initialize pigpio
    if (pigpio_init() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI handle
    spi_handle = pigpio_spi_open(0, ADIS16266_SPI_MODE, ADIS16266_SPI_SPEED, ADIS16266_SPI_BITS, ADIS16266_SPI_DELAY);
    if (spi_handle < 0) {
        printf("Failed to open SPI handle\n");
        pigpio_terminate();
        return 1;
    }

    // Verify WHO_AM_I register
    uint16_t who_am_i = 0;
    if (pigpio_spi_xfer(spi_handle, ADIS16266_WHO_AM_I, &who_am_i, 1) < 0) {
        printf("Failed to read WHO_AM_I register\n");
        pigpio_spi_close(spi_handle);
        pigpio_terminate();
        return 1;
    }
    if (who_am_i != ADIS16266_WHO_AM_I) {
        printf("Invalid WHO_AM_I register value: 0x%04X\n", who_am_i);
        pigpio_spi_close(spi_handle);
        pigpio_terminate();
        return 1;
    }

    // Open log file
    spi_fd = fopen(GYRO_LOG_FILE, "w");
    if (spi_fd == NULL) {
        printf("Failed to open log file\n");
        pigpio_spi_close(spi_handle);
        pigpio_terminate();
        return 1;
    }

    // Write CSV header
    fprintf(spi_fd, "timestamp,gyro_x\n");

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read X_GYRO_OUT register
        uint16_t x_gyro_out = 0;
        if (pigpio_spi_xfer(spi_handle, ADIS16266_X_GYRO_OUT, &x_gyro_out, 1) < 0) {
            printf("Failed to read X_GYRO_OUT register\n");
            pigpio_spi_close(spi_handle);
            pigpio_terminate();
            fclose(spi_fd);
            return 1;
        }

        // Scale and log value
        double gyro_x = x_gyro_out * ADIS16266_SCALE;
        fprintf(spi_fd, "%ld,%.3f\n", time(NULL), gyro_x);

        // Sleep for 10 ms
        usleep(10000);
    }

    // Close SPI handle and terminate pigpio
    pigpio_spi_close(spi_handle);
    pigpio_terminate();
    fclose(spi_fd);

    return 0;
}

