#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x69
#define CTRL_REG1 0x0F
#define CTRL_REG4 0x00
#define OUT_X_L 0x28
#define SENSITIVITY 8.75
#define SAMPLE_RATE 10000000
#define RETRY_COUNT 3

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    int fd;
    uint8_t data[6];
    uint8_t reg;
    int ret;
    int i;
    struct timespec ts;
    FILE *fp;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus
    fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Configure sensor for normal mode with all axes enabled
    reg = CTRL_REG1;
    for (i = 0; i < RETRY_COUNT; i++) {
        ret = i2cWriteByte(fd, reg, 0x0F);
        if (ret < 0) {
            fprintf(stderr, "Failed to write to CTRL_REG1\n");
            return 1;
        }
    }

    // Configure sensor for +-250 dps full-scale range
    reg = CTRL_REG4;
    for (i = 0; i < RETRY_COUNT; i++) {
        ret = i2cWriteByte(fd, reg, 0x00);
        if (ret < 0) {
            fprintf(stderr, "Failed to write to CTRL_REG4\n");
            return 1;
        }
    }

    // Verify sensor presence
    reg = 0x0F;
    for (i = 0; i < RETRY_COUNT; i++) {
        ret = i2cReadByte(fd, reg);
        if (ret < 0) {
            fprintf(stderr, "Failed to read WHO_AM_I register\n");
            return 1;
        }
        if (ret != 0xD3) {
            fprintf(stderr, "Invalid WHO_AM_I register value: %02X\n", ret);
            return 1;
        }
    }

    // Open file for logging
    fp = fopen("gyro_log.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for logging\n");
        return 1;
    }

    // Write header row
    fprintf(fp, "Timestamp,X,Y,Z\n");

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (running) {
        // Read all 6 data bytes starting at OUT_X_L
        ret = i2cReadBlock(fd, OUT_X_L, data, 6);
        if (ret < 0) {
            fprintf(stderr, "Failed to read data from sensor\n");
            return 1;
        }

        // Convert raw values to degrees per second
        for (i = 0; i < 3; i++) {
            data[i] = (data[i] << 8) | data[i + 1];
            data[i] = data[i] / SENSITIVITY;
        }

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);

        // Log data to file
        fprintf(fp, "%ld.%ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, data[0], data[1], data[2]);

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up
    fclose(fp);
    i2cClose(fd);
    gpioTerminate();

    return 0;
}

