#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 17

void sigint_handler(int signum) {
    printf("SIGINT received, exiting...\n");
    exit(0);
}

int main(void) {
    int fd;
    bool flame_detected = false;
    int gpio_value;
    char timestamp[20];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set GPIO17 as input with internal pull-up resistor
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 as input\n");
        return 1;
    }
    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set internal pull-up resistor on GPIO17\n");
        return 1;
    }

    // Open 'flame_events.log' in append mode
    fd = open("flame_events.log", O_APPEND | O_CREAT | O_WRONLY, 0644);
    if (fd < 0) {
        fprintf(stderr, "Failed to open 'flame_events.log'\n");
        return 1;
    }

    // Set SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (true) {
        // Read GPIO17 value
        gpio_value = gpioRead(FLAME_SENSOR_PIN);
        if (gpio_value < 0) {
            fprintf(stderr, "Failed to read GPIO17 value\n");
            break;
        }

        // Check if flame is detected
        if (gpio_value == PI_LOW) {
            flame_detected = true;
        } else {
            flame_detected = false;
        }

        // Log timestamped line to 'flame_events.log'
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(fd, "%s - Flame detected: %s\n", timestamp, flame_detected ? "YES" : "NO");
        fflush(fd);

        // Print 'FLAME DETECTED!' to console if flame is detected
        if (flame_detected) {
            printf("FLAME DETECTED!\n");
        }

        // Sleep for 500 ms
        usleep(500000);
    }

    // Close 'flame_events.log' and call gpioTerminate()
    close(fd);
    gpioTerminate();

    return 0;
}

