#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x53
#define I2C_SLAVE_FORCE 0x0706
#define I2C_RDWR 0x0707
#define I2C_SLAVE 0x0703
#define I2C_SLAVE_ADDR 0x0704
#define I2C_TENBIT 0x0705
#define I2C_FUNCS 0x0708
#define I2C_RDRW_IOCTL 0x0709
#define I2C_PEC 0x070A
#define I2C_RETRIES 0x070B
#define I2C_TIMEOUT 0x070C
#define I2C_SLAVE_FORCE_TIMEOUT 0x070D

#define ACCEL_X_LSB 0x28
#define ACCEL_X_MSB 0x29
#define ACCEL_Y_LSB 0x2A
#define ACCEL_Y_MSB 0x2B
#define ACCEL_Z_LSB 0x2C
#define ACCEL_Z_MSB 0x2D

#define ACCEL_DATA_SIZE 6

int main() {
    int fd;
    int ret;
    uint8_t buf[ACCEL_DATA_SIZE];
    uint16_t x, y, z;
    char timestamp[20];
    FILE *csv_file;

    // Open I2C device
    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    ret = ioctl(fd, I2C_SLAVE_FORCE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Open CSV file
    csv_file = fopen("vibration_log.csv", "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(fd);
        return 1;
    }

    // Write CSV header
    fprintf(csv_file, "Timestamp,X,Y,Z\n");

    // Main loop
    while (1) {
        // Read acceleration data
        ret = read(fd, buf, ACCEL_DATA_SIZE);
        if (ret < 0) {
            perror("Failed to read acceleration data");
            close(fd);
            fclose(csv_file);
            return 1;
        }

        // Check for sensor-absent paths
        if (buf[0] == 0xFF || buf[1] == 0xFF || buf[2] == 0xFF || buf[3] == 0xFF || buf[4] == 0xFF || buf[5] == 0xFF) {
            fprintf(stderr, "Sensor-absent path detected\n");
            continue;
        }

        // Combine acceleration data
        x = (buf[0] << 8) | buf[1];
        y = (buf[2] << 8) | buf[3];
        z = (buf[4] << 8) | buf[5];

        // Get timestamp
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&now));

        // Write to CSV file
        fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    }

    // Close I2C device
    close(fd);

    // Close CSV file
    fclose(csv_file);

    return 0;
}

