#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NAME_1 "gpio17"
#define GPIO_LINE_NAME_2 "gpio27"
#define LOG_FILE_NAME "conveyor_log.txt"
#define LOG_INTERVAL_MS 50

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void sigterm_handler(int signum) {
    running = false;
}

int main(int argc, char *argv[]) {
    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP_NAME);
        return 1;
    }

    // Request GPIO lines
    struct gpiod_line *line1 = gpiod_chip_get_line(chip, GPIO_LINE_NAME_1);
    struct gpiod_line *line2 = gpiod_chip_get_line(chip, GPIO_LINE_NAME_2);
    if (!line1 || !line2) {
        fprintf(stderr, "Error requesting GPIO lines %s and %s\n", GPIO_LINE_NAME_1, GPIO_LINE_NAME_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up GPIO lines as inputs with internal pull-ups
    gpiod_line_request_input(line1, "conveyor_sensor_1");
    gpiod_line_request_input(line2, "conveyor_sensor_2");
    gpiod_line_set_bias(line1, GPIOD_LINE_BIAS_PULL_UP);
    gpiod_line_set_bias(line2, GPIOD_LINE_BIAS_PULL_UP);

    // Open log file
    FILE *log_file = fopen(LOG_FILE_NAME, "w");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE_NAME);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        // Read GPIO lines
        bool sensor1_state = gpiod_line_get_value(line1);
        bool sensor2_state = gpiod_line_get_value(line2);

        // Log timestamp and sensor states
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%ld, %d, %d\n", ts.tv_sec, ts.tv_nsec / 1000000, sensor1_state, sensor2_state);

        // Check if both sensors are triggered
        if (sensor1_state && sensor2_state) {
            // Halt the conveyor
            printf("Conveyor halted\n");
            break;
        }

        // Sleep for LOG_INTERVAL_MS milliseconds
        usleep(LOG_INTERVAL_MS * 1000);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}

