#define I2C_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define DATA_REG_START 0x01
#define DATA_REG_END 0x06
#define DATA_REG_COUNT 6
#define DATA_REG_SIZE 2
#define DATA_REG_SHIFT 4
#define TILT_THRESHOLD 45

int main(void) {
    int fd;
    int ret;
    uint8_t data[DATA_REG_COUNT * DATA_REG_SIZE];
    uint8_t who_am_i;
    uint8_t ctrl_reg1;
    int16_t x, y, z;
    double tilt_angle;
    FILE *log_file;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    ret = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Verify sensor identity
    ret = read(fd, &who_am_i, 1);
    if (ret < 0) {
        perror("Failed to read WHO_AM_I register");
        close(fd);
        return 1;
    }
    if (who_am_i != 0x2A) {
        fprintf(stderr, "Invalid sensor identity: 0x%02X\n", who_am_i);
        close(fd);
        return 1;
    }

    // Initialize sensor
    ret = read(fd, &ctrl_reg1, 1);
    if (ret < 0) {
        perror("Failed to read CTRL_REG1 register");
        close(fd);
        return 1;
    }
    ctrl_reg1 &= ~(1 << 0); // Set standby mode
    ctrl_reg1 &= ~(0b111 << 3); // Set data rate to 100 Hz
    ctrl_reg1 |= (0b010 << 3);
    ret = write(fd, &ctrl_reg1, 1);
    if (ret < 0) {
        perror("Failed to write CTRL_REG1 register");
        close(fd);
        return 1;
    }
    ctrl_reg1 |= (1 << 0); // Set active mode
    ret = write(fd, &ctrl_reg1, 1);
    if (ret < 0) {
        perror("Failed to write CTRL_REG1 register");
        close(fd);
        return 1;
    }

    // Open log file
    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    // Setup signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read accelerometer data
        ret = read(fd, data, DATA_REG_COUNT * DATA_REG_SIZE);
        if (ret < 0) {
            perror("Failed to read accelerometer data");
            close(fd);
            fclose(log_file);
            return 1;
        }

        // Combine MSB/LSB and right-shift by 4 to form signed 12-bit values
        x = (data[0] << 8) | data[1];
        y = (data[2] << 8) | data[3];
        z = (data[4] << 8) | data[5];

        // Compute tilt angle
        tilt_angle = atan2(x, sqrt(y * y + z * z));

        // Check for tilt
        if (fabs(tilt_angle) > TILT_THRESHOLD) {
            // Log tilt event
            fprintf(log_file, "%ld,%d,%d,%d\n", time(NULL), x, y, z);
            fflush(log_file);
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Cleanup
    close(fd);
    fclose(log_file);

    return 0;
}

void sigint_handler(int signum) {
    close(fd);
    fclose(log_file);
    exit(0);
}

void sigterm_handler(int signum) {
    close(fd);
    fclose(log_file);
    exit(0);
}

