#define CTRL_REG4 0x0C
#define CTRL_REG3 0x00
#define X_REG 0x28
#define Y_REG 0x2A
#define Z_REG 0x2C

#define MAG_SCALE 0.146
#define MAG_OFFSET 0.0

#define MAG_THRESHOLD 800

int main(void) {
    int fd;
    uint8_t buf[6];
    int16_t x, y, z;
    float mag_x, mag_y, mag_z;
    int retries = 0;

    // Open I2C device
    if ((fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Initialize I2C device
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to initialize I2C device");
        close(fd);
        return 1;
    }

    // Verify sensor is present
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read WHO_AM_I register");
        close(fd);
        return 1;
    }
    if (buf[0] != 0x3D) {
        fprintf(stderr, "Invalid WHO_AM_I value: 0x%02X\n", buf[0]);
        close(fd);
        return 1;
    }

    // Configure sensor for continuous-conversion mode
    if (write(fd, CTRL_REG1, 1) != 1) {
        perror("Failed to write CTRL_REG1 register");
        close(fd);
        return 1;
    }
    if (write(fd, CTRL_REG4, 1) != 1) {
        perror("Failed to write CTRL_REG4 register");
        close(fd);
        return 1;
    }
    if (write(fd, CTRL_REG3, 1) != 1) {
        perror("Failed to write CTRL_REG3 register");
        close(fd);
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read magnetic field data
        if (read(fd, buf, 6) != 6) {
            perror("Failed to read magnetic field data");
            close(fd);
            fclose(log_file);
            return 1;
        }

        // Apply fixed offset/scale calibration constants
        x = (int16_t)((buf[0] << 8) | buf[1]);
        y = (int16_t)((buf[2] << 8) | buf[3]);
        z = (int16_t)((buf[4] << 8) | buf[5]);
        mag_x = (float)x * MAG_SCALE + MAG_OFFSET;
        mag_y = (float)y * MAG_SCALE + MAG_OFFSET;
        mag_z = (float)z * MAG_SCALE + MAG_OFFSET;

        // Convert to milliGauss
        mag_x *= 1000;
        mag_y *= 1000;
        mag_z *= 1000;

        // Print to log file
        fprintf(log_file, "%d,%d,%d\n", (int)mag_x, (int)mag_y, (int)mag_z);

        // Check for metal-detector threshold alert
        if (mag_x*mag_x + mag_y*mag_y + mag_z*mag_z > MAG_THRESHOLD*MAG_THRESHOLD) {
            fprintf(stderr, "Metal-detector threshold alert: %d,%d,%d\n", (int)mag_x, (int)mag_y, (int)mag_z);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    close(fd);
    fclose(log_file);

    return 0;
}

