#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define ADXL354B_SPI_CHANNEL 0
#define ADXL354B_SPI_SPEED 1000000
#define ADXL354B_SPI_MODE 0
#define ADXL354B_RESET_REG 0x1F
#define ADXL354B_POWER_CTL_REG 0x2D
#define ADXL354B_STATUS_REG 0x04
#define ADXL354B_XDATA_REG 0x08
#define ADXL354B_YDATA_REG 0x0B
#define ADXL354B_ZDATA_REG 0x0E
#define ADXL354B_PARTID_REG 0x01
#define ADXL354B_SENSITIVITY 0.0000039

#define SPI_READ_BIT 0x80
#define SPI_MULTI_BYTE_BIT 0x40

#define SPI_READ_RETRIES 5

#define LOG_FILE "vibration_log.txt"

static int spi_fd;
static int spi_handle;
static int spi_mode;
static int spi_speed;
static int spi_channel;

static int adxl354b_reset(void) {
    uint8_t reset_reg = ADXL354B_RESET_REG;
    uint8_t reset_val = 0x52;
    int ret;

    ret = pigpio_spi_write(spi_handle, &reset_reg, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to SPI: %s\n", strerror(errno));
        return -1;
    }

    ret = pigpio_spi_write(spi_handle, &reset_val, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to SPI: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int adxl354b_set_measurement_mode(void) {
    uint8_t power_ctl_reg = ADXL354B_POWER_CTL_REG;
    uint8_t power_ctl_val = 0x00;
    int ret;

    ret = pigpio_spi_write(spi_handle, &power_ctl_reg, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to SPI: %s\n", strerror(errno));
        return -1;
    }

    ret = pigpio_spi_write(spi_handle, &power_ctl_val, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to SPI: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int adxl354b_check_presence(void) {
    uint8_t partid_reg = ADXL354B_PARTID_REG;
    uint8_t partid_val;
    int ret;

    ret = pigpio_spi_write(spi_handle, &partid_reg, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to SPI: %s\n", strerror(errno));
        return -1;
    }

    ret = pigpio_spi_read(spi_handle, &partid_val, 1);
    if (ret < 0) {
        fprintf(stderr, "Error reading from SPI: %s\n", strerror(errno));
        return -1;
    }

    if (partid_val != 0x1D) {
        fprintf(stderr, "ADXL354B not detected\n");
        return -1;
    }

    return 0;
}

static int adxl354b_read_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t xdata_reg = ADXL354B_XDATA_REG;
    uint8_t ydata_reg = ADXL354B_YDATA_REG;
    uint8_t zdata_reg = ADXL354B_ZDATA_REG;
    uint8_t xdata_val[3];
    uint8_t ydata_val[3];
    uint8_t zdata_val[3];
    int ret;

    ret = pigpio_spi_write(spi_handle, &xdata_reg, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to SPI: %s\n", strerror(errno));
        return -1;
    }

    ret = pigpio_spi_read(spi_handle, xdata_val, 3);
    if (ret < 0) {
        fprintf(stderr, "Error reading from SPI: %s\n", strerror(errno));
        return -1;
    }

    ret = pigpio_spi_write(spi_handle, &ydata_reg, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to SPI: %s\n", strerror(errno));
        return -1;
    }

    ret = pigpio_spi_read(spi_handle, ydata_val, 3);
    if (ret < 0) {
        fprintf(stderr, "Error reading from SPI: %s\n", strerror(errno));
        return -1;
    }

    ret = pigpio_spi_write(spi_handle, &zdata_reg, 1);
    if (ret < 0) {
        fprintf(stderr, "Error writing to SPI: %s\n", strerror(errno));
        return -1;
    }

    ret = pigpio_spi_read(spi_handle, zdata_val, 3);
    if (ret < 0) {
        fprintf(stderr, "Error reading from SPI: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((xdata_val[0] << 12) | (xdata_val[1] << 4) | (xdata_val[2] >> 4));
    *y = (int16_t)((ydata_val[0] << 12) | (ydata_val[1] << 4) | (ydata_val[2] >> 4));
    *z = (int16_t)((zdata_val[0] << 12) | (zdata_val[1] << 4) | (zdata_val[2] >> 4));

    return 0;
}

static void sigint_handler(int signum) {
    fprintf(stderr, "Caught signal %d, shutting down...\n", signum);

    pigpio_spi_close(spi_handle);
    fclose(log_file);

    exit(0);
}

int main(void) {
    int ret;
    int16_t x, y, z;
    FILE *log_file;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    spi_fd = pigpio_spi_open(ADXL354B_SPI_CHANNEL, ADXL354B_SPI_SPEED, ADXL354B_SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI: %s\n", strerror(errno));
        return -1;
    }

    spi_handle = pigpio_spi_handle(spi_fd);
    if (spi_handle < 0) {
        fprintf(stderr, "Error getting SPI handle: %s\n", strerror(errno));
        return -1;
    }

    ret = adxl354b_reset();
    if (ret < 0) {
        fprintf(stderr, "Error resetting ADXL354B: %s\n", strerror(errno));
        return -1;
    }

    ret = adxl354b_check_presence();
    if (ret < 0) {
        fprintf(stderr, "Error checking ADXL354B presence: %s\n", strerror(errno));
        return -1;
    }

    ret = adxl354b_set_measurement_mode();
    if (ret < 0) {
        fprintf(stderr, "Error setting measurement mode: %s\n", strerror(errno));
        return -1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    while (1) {
        ret = adxl354b_read_data(&x, &y, &z);
        if (ret < 0) {
            fprintf(stderr, "Error reading data: %s\n", strerror(errno));
            return -1;
        }

        fprintf(log_file, "%ld, %d, %d, %d\n", time(NULL), x, y, z);

        usleep(100000);
    }

    pigpio_spi_close(spi_handle);
    fclose(log_file);

    return 0;
