        fprintf(stderr, "Error: unable to open GPIO chip %s\n", GPIO_CHIP_NAME);
        return 1;
    }

    struct gpiod_line *line1 = gpiod_chip_get_line(chip, GPIO_LINE_NAME_1);
    if (!line1) {
        fprintf(stderr, "Error: unable to get GPIO line %s\n", GPIO_LINE_NAME_1);
        gpiod_chip_close(chip);
        return 1;
    }

    struct gpiod_line *line2 = gpiod_chip_get_line(chip, GPIO_LINE_NAME_2);
    if (!line2) {
        fprintf(stderr, "Error: unable to get GPIO line %s\n", GPIO_LINE_NAME_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request both lines for input
    if (gpiod_line_request_input(line1, "obstacle_sensor_1") != 0) {
        fprintf(stderr, "Error: unable to request input for GPIO line %s\n", GPIO_LINE_NAME_1);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line2, "obstacle_sensor_2") != 0) {
        fprintf(stderr, "Error: unable to request input for GPIO line %s\n", GPIO_LINE_NAME_2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Poll both sensors every POLL_INTERVAL ms
    while (true) {
        // Read both lines in a single call
        struct gpiod_line_bulk_value bulk_value;
        if (gpiod_line_request_get_values(line1, line2, &bulk_value) != 0) {
            fprintf(stderr, "Error: unable to read GPIO lines\n");
            gpiod_chip_close(chip);
            return 1;
        }

        // Check if an obstacle is detected on either sensor
        bool obstacle_detected = false;
        if (bulk_value.values[0] == 0 || bulk_value.values[1] == 0) {
            obstacle_detected = true;
        }

        // Log the obstacle detection status to the console with a timestamp
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        printf("%02d:%02d:%02d - Obstacle detected: %s\n", tm->tm_hour, tm->tm_min, tm->tm_sec, obstacle_detected ? "true" : "false");

        // Sleep for POLL_INTERVAL ms
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up resources on exit
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}
