#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod/libgpiod.h>

#define ADIS16266_MSC_CTRL_REG 0x24
#define ADIS16266_X_ANG_RATE_REG 0x04
#define ADIS16266_Y_ANG_RATE_REG 0x06
#define ADIS16266_Z_ANG_RATE_REG 0x08

#define SPI_MODE 3
#define SPI_MSB_FIRST
#define SPI_SPEED 1000000

#define CS_PIN 8

int main(void) {
    // Initialize SPI device
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Initialize GPIO line for CS pin
    struct gpiod_line *cs_line = gpiod_line_get(CS_PIN);
    if (!cs_line) {
        perror("Failed to get GPIO line for CS pin");
        return 1;
    }

    // Set SPI mode, MSB first, and clock speed
    struct spi_ioc_transfer spi_transfer = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .word_delay_usecs = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MSB_FIRST, &SPI_MSB_FIRST) < 0) {
        perror("Failed to set SPI MSB first");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_SPEED, &SPI_SPEED) < 0) {
        perror("Failed to set SPI clock speed");
        return 1;
    }

    // Enable data ready mode in MSC_CTRL register
    uint8_t msc_ctrl_reg = ADIS16266_MSC_CTRL_REG;
    uint8_t msc_ctrl_val = 0x01;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
        perror("Failed to write to MSC_CTRL register");
        return 1;
    }

    // Read X, Y, and Z angular rate output registers
    uint8_t x_ang_rate_reg = ADIS16266_X_ANG_RATE_REG;
    uint8_t y_ang_rate_reg = ADIS16266_Y_ANG_RATE_REG;
    uint8_t z_ang_rate_reg = ADIS16266_Z_ANG_RATE_REG;
    uint16_t x_ang_rate, y_ang_rate, z_ang_rate;
    while (1) {
        // Set CS pin low
        gpiod_line_set_value(cs_line, 0);

        // Read X, Y, and Z angular rate output registers
        spi_transfer.tx_buf = &x_ang_rate_reg;
        spi_transfer.rx_buf = &x_ang_rate;
        spi_transfer.len = 2;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
            perror("Failed to read X angular rate");
            return 1;
        }
        spi_transfer.tx_buf = &y_ang_rate_reg;
        spi_transfer.rx_buf = &y_ang_rate;
        spi_transfer.len = 2;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
            perror("Failed to read Y angular rate");
            return 1;
        }
        spi_transfer.tx_buf = &z_ang_rate_reg;
        spi_transfer.rx_buf = &z_ang_rate;
        spi_transfer.len = 2;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_transfer) < 0) {
            perror("Failed to read Z angular rate");
            return 1;
        }

        // Set CS pin high
        gpiod_line_set_value(cs_line, 1);

        // Convert raw 16-bit signed values to angular rates
        x_ang_rate = (int16_t)x_ang_rate;
        y_ang_rate = (int16_t)y_ang_rate;
        z_ang_rate = (int16_t)z_ang_rate;
        x_ang_rate *= 0.02;
        y_ang_rate *= 0.02;
        z_ang_rate *= 0.02;

        // Log angular rates to console
        printf("X: %f deg/sec, Y: %f deg/sec, Z: %f deg/sec\n", x_ang_rate, y_ang_rate, z_ang_rate);

        // Wait 100 ms before reading again
        usleep(100000);
    }

    // Clean up resources
    gpiod_line_release(cs_line);
    close(spi_fd);

    return 0;
}

