#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6B
#define WHO_AM_I_REG 0x0F
#define CTRL1_XL_REG 0x10
#define CTRL2_G_REG 0x11
#define OUTX_L_G_REG 0x22

#define GYRO_SENSITIVITY 8.75
#define ACCEL_SENSITIVITY 0.061

#define BURST_LEN 12

int main(void) {
    int fd;
    uint8_t who_am_i;
    uint8_t ctrl1_xl, ctrl2_g;
    uint8_t data[BURST_LEN];
    int16_t gyro_x, gyro_y, gyro_z;
    int16_t accel_x, accel_y, accel_z;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (i2cReadReg8(fd, WHO_AM_I_REG, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    if (who_am_i != I2C_ADDR) {
        fprintf(stderr, "WHO_AM_I register mismatch\n");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    ctrl1_xl = 0x42;
    ctrl2_g = 0x42;

    if (i2cWriteReg8(fd, CTRL1_XL_REG, ctrl1_xl) < 0) {
        fprintf(stderr, "Failed to write CTRL1_XL register\n");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteReg8(fd, CTRL2_G_REG, ctrl2_g) < 0) {
        fprintf(stderr, "Failed to write CTRL2_G register\n");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        if (i2cReadReg8(fd, OUTX_L_G_REG, data, BURST_LEN) < 0) {
            fprintf(stderr, "Failed to read data\n");
            i2cClose(fd);
            gpioTerminate();
            return 1;
        }

        gyro_x = (int16_t)((data[0] << 8) | data[1]);
        gyro_y = (int16_t)((data[2] << 8) | data[3]);
        gyro_z = (int16_t)((data[4] << 8) | data[5]);

        accel_x = (int16_t)((data[6] << 8) | data[7]);
        accel_y = (int16_t)((data[8] << 8) | data[9]);
        accel_z = (int16_t)((data[10] << 8) | data[11]);

        printf("Gyro: X=%d, Y=%d, Z=%d\n", gyro_x, gyro_y, gyro_z);
        printf("Accel: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);

        usleep(100000);
    }

    i2cClose(fd);
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum) {
    i2cClose(fd);
    gpioTerminate();
    exit(0);
}

