#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define M_CTRL_REG1 0x5B
#define M_CTRL_REG2 0x5C
#define OUT_X_MSB 0x01

#define ACCEL_X_OFFSET 0
#define ACCEL_Y_OFFSET 2
#define ACCEL_Z_OFFSET 4
#define MAG_X_OFFSET 6
#define MAG_Y_OFFSET 8
#define MAG_Z_OFFSET 10

#define ACCEL_X_MASK 0x0FFF
#define ACCEL_Y_MASK 0x0FFF
#define ACCEL_Z_MASK 0x0FFF
#define MAG_X_MASK 0xFFFF
#define MAG_Y_MASK 0xFFFF
#define MAG_Z_MASK 0xFFFF

#define ACCEL_X_SHIFT 4
#define ACCEL_Y_SHIFT 4
#define ACCEL_Z_SHIFT 4
#define MAG_X_SHIFT 0
#define MAG_Y_SHIFT 0
#define MAG_Z_SHIFT 0

#define ACCEL_X_SCALE 0.00006103515625
#define ACCEL_Y_SCALE 0.00006103515625
#define ACCEL_Z_SCALE 0.00006103515625
#define MAG_X_SCALE 0.000000152587890625
#define MAG_Y_SCALE 0.000000152587890625
#define MAG_Z_SCALE 0.000000152587890625

#define I2C_RETRY_COUNT 5
#define I2C_RETRY_DELAY 100000

int i2c_handle;

void init_sensor() {
  // Initialize the I2C bus
  i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
  if (i2c_handle < 0) {
    printf("Failed to open I2C bus\n");
    exit(1);
  }

  // Check if the sensor is present
  uint8_t who_am_i;
  if (pigpio_i2c_read_byte(i2c_handle, WHO_AM_I_REG, &who_am_i) < 0) {
    printf("Failed to read WHO_AM_I register\n");
    exit(1);
  }
  if (who_am_i != 0xC7) {
    printf("Sensor not present\n");
    exit(1);
  }

  // Configure the sensor into hybrid mode
  uint8_t ctrl_reg1 = 0x00;
  uint8_t ctrl_reg2 = 0x00;
  uint8_t m_ctrl_reg1 = 0x00;
  uint8_t m_ctrl_reg2 = 0x00;
  if (pigpio_i2c_write_byte(i2c_handle, CTRL_REG1, ctrl_reg1) < 0 ||
      pigpio_i2c_write_byte(i2c_handle, CTRL_REG2, ctrl_reg2) < 0 ||
      pigpio_i2c_write_byte(i2c_handle, M_CTRL_REG1, m_ctrl_reg1) < 0 ||
      pigpio_i2c_write_byte(i2c_handle, M_CTRL_REG2, m_ctrl_reg2) < 0) {
    printf("Failed to configure sensor\n");
    exit(1);
  }
}

void read_sensor() {
  // Read the combined data block
  uint8_t data[12];
  if (pigpio_i2c_read_bytes(i2c_handle, OUT_X_MSB, data, 12) < 0) {
    printf("Failed to read data\n");
    exit(1);
  }

  // Extract the accelerometer data
  int16_t accel_x = (data[ACCEL_X_OFFSET] << ACCEL_X_SHIFT) | (data[ACCEL_X_OFFSET + 1] >> ACCEL_X_SHIFT);
  int16_t accel_y = (data[ACCEL_Y_OFFSET] << ACCEL_Y_SHIFT) | (data[ACCEL_Y_OFFSET + 1] >> ACCEL_Y_SHIFT);
  int16_t accel_z = (data[ACCEL_Z_OFFSET] << ACCEL_Z_SHIFT) | (data[ACCEL_Z_OFFSET + 1] >> ACCEL_Z_SHIFT);

  // Extract the magnetometer data
  int16_t mag_x = (data[MAG_X_OFFSET] << MAG_X_SHIFT) | (data[MAG_X_OFFSET + 1] >> MAG_X_SHIFT);
  int16_t mag_y = (data[MAG_Y_OFFSET] << MAG_Y_SHIFT) | (data[MAG_Y_OFFSET + 1] >> MAG_Y_SHIFT);
  int16_t mag_z = (data[MAG_Z_OFFSET] << MAG_Z_SHIFT) | (data[MAG_Z_OFFSET + 1] >> MAG_Z_SHIFT);

  // Scale and convert the data to floating-point values
  float accel_x_scaled = accel_x * ACCEL_X_SCALE;
  float accel_y_scaled = accel_y * ACCEL_Y_SCALE;
  float accel_z_scaled = accel_z * ACCEL_Z_SCALE;
  float mag_x_scaled = mag_x * MAG_X_SCALE;
  float mag_y_scaled = mag_y * MAG_Y_SCALE;
  float mag_z_scaled = mag_z * MAG_Z_SCALE;

  // Print the data to the console
  printf("Accelerometer: X = %f, Y = %f, Z = %f\n", accel_x_scaled, accel_y_scaled, accel_z_scaled);
  printf("Magnetometer: X = %f, Y = %f, Z = %f\n", mag_x_scaled, mag_y_scaled, mag_z_scaled);
}

void cleanup() {
  // Close the I2C handle
  pigpio_i2c_close(i2c_handle);

  // Terminate pigpio
  pigpio_terminate();
}

int main() {
  // Initialize the sensor
  init_sensor();

  // Read the sensor data
  read_sensor();

