#include <linux/i2c-dev.h>
#include <math.h>

#define I2C_ADDR 0x53
#define X_REG 0x32
#define Y_REG 0x33
#define Z_REG 0x34
#define TILT_THRESHOLD 30.0

int main(void) {
    int fd;
    int16_t x, y, z;
    double tilt_angle;
    char buf[100];

    // Open the I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Read the X, Y, and Z data from the registers
    if (read(fd, &x, 2) != 2) {
        perror("Failed to read X data");
        close(fd);
        return 1;
    }
    if (read(fd, &y, 2) != 2) {
        perror("Failed to read Y data");
        close(fd);
        return 1;
    }
    if (read(fd, &z, 2) != 2) {
        perror("Failed to read Z data");
        close(fd);
        return 1;
    }

    // Calculate the tilt angle
    tilt_angle = atan2(y, x);

    // Check if the tilt angle exceeds the threshold
    if (tilt_angle > TILT_THRESHOLD) {
        // Log the event to the log file
        snprintf(buf, sizeof(buf), "Tilt angle exceeded threshold: %f\n", tilt_angle);
        write(fd, buf, strlen(buf));
    }

    // Close the I2C device
    close(fd);

    return 0;
}

