#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5000
#define THRESHOLD 10

static volatile bool running = true;

void sigint_handler(int signum) {
    running = false;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    int threshold = atoi(argv[1]);
    if (threshold <= 0) {
        fprintf(stderr, "Invalid threshold: %d\n", threshold);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        int high_count = 0;
        int low_count = 0;

        for (int i = 0; i < WINDOW_SIZE; i++) {
            int value = gpioRead(GPIO_PIN);
            if (value < 0) {
                fprintf(stderr, "Failed to read GPIO value\n");
                return 1;
            }

            if (value == 1) {
                high_count++;
            } else {
                low_count++;
            }

            usleep(1000);
        }

        if (high_count > threshold) {
            printf("ALERT: %d high readings in the last 5 seconds\n", high_count);
        } else {
            printf("Status: %d high readings in the last 5 seconds\n", high_count);
        }

        usleep(1000000);
    }

    gpioTerminate();

    return 0;
}

