#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DOOR_A_GPIO 17
#define DOOR_B_GPIO 27
#define CODE_LENGTH 6
#define CODE_MIN 100000
#define CODE_MAX 999999

volatile sig_atomic_t sig_exit = 0;

void sigint_handler(int signum) {
    sig_exit = 1;
}

int main(void) {
    // Initialize GPIO pins
    struct gpiod_chip *chip;
    struct gpiod_line *line_a, *line_b;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        return 1;
    }

    line_a = gpiod_chip_get_line(chip, DOOR_A_GPIO);
    if (!line_a) {
        fprintf(stderr, "Error: Failed to get GPIO line for door A\n");
        return 1;
    }

    line_b = gpiod_chip_get_line(chip, DOOR_B_GPIO);
    if (!line_b) {
        fprintf(stderr, "Error: Failed to get GPIO line for door B\n");
        return 1;
    }

    // Set GPIO pins as outputs
    ret = gpiod_line_request_output(line_a, "door_a", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request output for door A\n");
        return 1;
    }

    ret = gpiod_line_request_output(line_b, "door_b", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request output for door B\n");
        return 1;
    }

    // Generate random code
    srand(time(NULL));
    int code = rand() % (CODE_MAX - CODE_MIN + 1) + CODE_MIN;
    printf("Code: %d\n", code);

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    while (!sig_exit) {
        // Prompt user for code
        printf("Enter code: ");
        fflush(stdout);

        // Read code from stdin
        char code_str[CODE_LENGTH + 1];
        if (fgets(code_str, CODE_LENGTH + 1, stdin) == NULL) {
            fprintf(stderr, "Error: Failed to read code from stdin\n");
            return 1;
        }

        // Check if code is valid
        int entered_code = atoi(code_str);
        if (entered_code < CODE_MIN || entered_code > CODE_MAX) {
            fprintf(stderr, "Invalid code\n");
            continue;
        }

        // Check if code matches
        if (entered_code == code) {
            // Unlock door A
            gpiod_line_set_value(line_a, 1);
            usleep(5000000);
            gpiod_line_set_value(line_a, 0);

            // Log successful entry
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char time_str[20];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);
            FILE *fp = fopen("access_log.txt", "a");
            if (fp == NULL) {
                fprintf(stderr, "Error: Failed to open access log file\n");
                return 1;
            }
            fprintf(fp, "%s,%d\n", time_str, entered_code);
            fclose(fp);

            // Generate new random code
            code = rand() % (CODE_MAX - CODE_MIN + 1) + CODE_MIN;
            printf("Code: %d\n", code);
        } else {
            fprintf(stderr, "Access denied\n");
        }
    }

    // Clean up
    gpiod_line_release(line_a);
    gpiod_line_release(line_b);
    gpiod_chip_close(chip);

    return 0;
}

