#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define I2C_WRITE_CMD 0x21
#define I2C_READ_CMD 0x22
#define I2C_MAX_CONVERSION_TIME 180
#define I2C_READ_BYTES 2

int main(void) {
    int fd;
    uint8_t write_buf[1];
    uint8_t read_buf[I2C_READ_BYTES];
    uint16_t raw_value;
    float lux_value;
    char timestamp[20];
    FILE *fp;

    // Open the I2C bus
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Open the log file
    fp = fopen("light_log.txt", "w");
    if (fp == NULL) {
        perror("Failed to open log file");
        close(fd);
        return 1;
    }

    // Set the One-Time High-Resolution Mode 2 command
    write_buf[0] = I2C_WRITE_CMD;
    if (write(fd, write_buf, 1) != 1) {
        perror("Failed to write to I2C bus");
        close(fd);
        fclose(fp);
        return 1;
    }

    // Wait for the maximum conversion time
    usleep(I2C_MAX_CONVERSION_TIME * 1000);

    // Read the raw value
    if (read(fd, read_buf, I2C_READ_BYTES) != I2C_READ_BYTES) {
        perror("Failed to read from I2C bus");
        close(fd);
        fclose(fp);
        return 1;
    }

    // Calculate the illuminance in lux
    raw_value = (read_buf[0] << 8) | read_buf[1];
    lux_value = (raw_value * 5) / 6;

    // Log the sensor readings
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(fp, "%s, Lux: %f\n", timestamp, lux_value);

    // Close the log file
    fclose(fp);

    // Close the I2C bus
    close(fd);

    return 0;
}

