#include <arpa/inet.h>
#include <pigpio.h>
#include <mpr121.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define PWM_GPIO 18
#define PWM_FREQ 5000
#define PWM_DUTY 50
#define PWM_RANGE 100
#define PWM_RESOLUTION 10
#define PWM_PERIOD 1000000
#define PWM_DELAY 20
#define PWM_SAMPLES 50
#define PWM_LOG_FILE "frequency_log.txt"

#define SECRET_KEY "MySecretKey"

int main(int argc, char *argv[]) {
  // Initialize pigpio
  if (gpioInitialise() < 0) {
    fprintf(stderr, "Failed to initialize pigpio\n");
    return 1;
  }

  // Initialize I2C
  if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
    fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
    return 1;
  }

  // Initialize MPR121
  if (mpr121Init(I2C_BUS, I2C_ADDR) < 0) {
    fprintf(stderr, "Failed to initialize MPR121 at I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
    return 1;
  }

  // Set up PWM
  if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ) < 0) {
    fprintf(stderr, "Failed to set PWM frequency\n");
    return 1;
  }
  if (gpioSetPWMdutycycle(PWM_GPIO, PWM_DUTY) < 0) {
    fprintf(stderr, "Failed to set PWM duty cycle\n");
    return 1;
  }
  if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) < 0) {
    fprintf(stderr, "Failed to set PWM range\n");
    return 1;
  }
  if (gpioSetPWMresolution(PWM_GPIO, PWM_RESOLUTION) < 0) {
    fprintf(stderr, "Failed to set PWM resolution\n");
    return 1;
  }
  if (gpioSetPWMperiod(PWM_GPIO, PWM_PERIOD) < 0) {
    fprintf(stderr, "Failed to set PWM period\n");
    return 1;
  }

  // Set up TCP server
  int sock = socket(AF_INET, SOCK_STREAM, 0);
  if (sock < 0) {
    fprintf(stderr, "Failed to create socket\n");
    return 1;
  }
  struct sockaddr_in server_addr;
  server_addr.sin_family = AF_INET;
  server_addr.sin_port = htons(12345);
  server_addr.sin_addr.s_addr = INADDR_ANY;
  if (bind(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
    fprintf(stderr, "Failed to bind socket\n");
    return 1;
  }
  if (listen(sock, 1) < 0) {
    fprintf(stderr, "Failed to listen on socket\n");
    return 1;
  }

  // Set up signal handler
  struct sigaction sa;
  sa.sa_handler = sigint_handler;
  sigemptyset(&sa.sa_mask);
  sa.sa_flags = 0;
  sigaction(SIGINT, &sa, NULL);
  sigaction(SIGTERM, &sa, NULL);

  // Main loop
  while (1) {
    // Accept incoming connection
    int client_sock = accept(sock, NULL, NULL);
    if (client_sock < 0) {
      fprintf(stderr, "Failed to accept incoming connection\n");
      continue;
    }

    // Read message from client
    char buf[1024];
    int n = read(client_sock, buf, sizeof(buf));
    if (n < 0) {
      fprintf(stderr, "Failed to read message from client\n");
      close(client_sock);
      continue;
    }
    buf[n] = '\0';

    // Check if message is valid
    if (strncmp(buf, "MOTION_DETECTED:", 15) != 0) {
      fprintf(stderr, "Invalid message from client\n");
      close(client_sock);
      continue;
    }

    // Check if secret key is valid
    if (strcmp(buf + 15, SECRET_KEY) != 0) {
      fprintf(stderr, "Invalid secret key\n");
      close(client_sock);
      continue;
    }

    // Start PWM
    if (gpioPWM(PWM_GPIO, PWM_DUTY) < 0) {
      fprintf(stderr, "Failed to start PWM\n");
      close(client_sock);
      continue;
    }

    // Start sampling touch values
    int touch_values[PWM_SAMPLES];
    for (int i = 0; i < PWM_SAMPLES; i++) {
      touch_values[i] = mpr121Read(I2C_BUS, I2C_ADDR, i);
      if (touch_values[i] < 0) {
        fprintf(stderr, "Failed to read touch value %d\n", i);
        close(client_sock);
        continue;
      }
    }

    // Map touch values to frequencies
    int frequencies[PWM_SAMPLES];
    for (int i = 0; i < PWM_SAMPLES; i++) {
      frequencies[i] = map_touch_value_to_frequency(touch_values[i]);
    }

    // Play frequencies
    for (int i = 0; i < PWM_SAMPLES; i++) {
      gpioPWM(PWM_GPIO, frequencies[i]);
      usleep(PWM_DELAY);
    }

    // Stop PWM
    gpioPWM(PWM_GPIO, 0);

    // Log frequencies
    FILE *fp = fopen(PWM_LOG_FILE, "a");
    if (fp == NULL) {
      fprintf(stderr, "Failed to open log file\n");
      close(client_sock);
      continue;
    }
    for (int i = 0; i < PWM_SAMPLES; i++) {
      fprintf(fp, "%d\n", frequencies[i]);
    }
    fclose(fp);

    // Close connection
    close(client_sock);
  }

  // Clean up
  gpioTerminate();
  close(sock);

  return 0;
}

int map_touch_value_to_frequency(int touch_value) {
  // Map touch value to frequency using logarithmic scale
  int frequency = 220 + (int)(log(touch_value) / log(2) * 660);
  return frequency;
}

void sigint_handler(int sig) {
  // Stop PWM
  gpioPWM(PWM_GPIO, 0);

  // Close I2C and sockets
  i2cClose(I2C_BUS, I2C_ADDR);
  close(sock);

  // Terminate pigpio cleanly
  gpioTerminate();

  // Exit program
  exit(0);
}

