#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define LED_PIN 17

int main(void) {
    int i2c_fd, gpio_fd;
    uint8_t buf[6];
    int16_t x, y, z;
    double magnitude;
    int pwm_value;

    // Initialize I2C bus
    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize GPIO pin
    if ((gpio_fd = gpiod_open(LED_PIN, GPIOD_OUT)) < 0) {
        perror("Failed to open GPIO pin");
        return 1;
    }

    // Initialize magnetometer
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Write 0x18 to CTRL_REG1_M for 10 Hz continuous conversion
    if (write(i2c_fd, CTRL_REG1_M, 0x18) < 0) {
        perror("Failed to write to CTRL_REG1_M");
        return 1;
    }

    // Main loop
    while (1) {
        // Read 6 bytes of data starting from OUT_X_L_M
        if (read(i2c_fd, buf, 6) < 0) {
            perror("Failed to read from I2C bus");
            continue;
        }

        // Extract X, Y, Z magnetic field data
        x = (buf[0] << 8) | buf[1];
        y = (buf[2] << 8) | buf[3];
        z = (buf[4] << 8) | buf[5];

        // Compute magnitude of Z-axis field
        magnitude = sqrt(z * z);

        // Adjust LED brightness proportionally
        pwm_value = (int)(magnitude * 100 / 32768);
        gpiod_set_value(gpio_fd, pwm_value);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up resources
    close(i2c_fd);
    close(gpio_fd);

    return 0;
}

