    uint8_t config_reg_b = CONFIG_REG_B;
    uint8_t mode_reg = MODE_REG;
    if (i2c_write(i2c_handle, &config_reg_a, 1) < 0) {
        fprintf(stderr, "Failed to write to configuration register A\n");
        return 1;
    }
    if (i2c_write(i2c_handle, &config_reg_b, 1) < 0) {
        fprintf(stderr, "Failed to write to configuration register B\n");
        return 1;
    }
    if (i2c_write(i2c_handle, &mode_reg, 1) < 0) {
        fprintf(stderr, "Failed to write to mode register\n");
        return 1;
    }

    // Initialize running average of hard-iron offsets
    int16_t offset_x = 0;
    int16_t offset_y = 0;
    int16_t offset_z = 0;

    // Main loop
    while (1) {
        // Read raw data from HMC5883L
        uint8_t data[6];
        if (i2c_read(i2c_handle, data, 6) < 0) {
            fprintf(stderr, "Failed to read from HMC5883L\n");
            return 1;
        }

        // Compute hard-iron offsets
        offset_x += (int16_t)((data[0] << 8) | data[1]);
        offset_y += (int16_t)((data[2] << 8) | data[3]);
        offset_z += (int16_t)((data[4] << 8) | data[5]);

        // Update running average of hard-iron offsets
        if (++offset_count >= SAMPLE_WINDOW) {
            offset_x /= SAMPLE_WINDOW;
            offset_y /= SAMPLE_WINDOW;
            offset_z /= SAMPLE_WINDOW;
            offset_count = 0;
        }

        // Apply hard-iron offsets to raw data
        int16_t x = (int16_t)((data[0] << 8) | data[1]) - offset_x;
        int16_t y = (int16_t)((data[2] << 8) | data[3]) - offset_y;
        int16_t z = (int16_t)((data[4] << 8) | data[5]) - offset_z;

        // Print offset-corrected X, Y, and Z values
        printf("X: %d\n", x);
        printf("Y: %d\n", y);
        printf("Z: %d\n", z);

        // Wait for next offset update interval
        usleep(OFFSET_UPDATE_INTERVAL * 1000);
    }

    // Clean up resources
    i2c_close(i2c_handle);
    pigpio_stop();

    return 0;
}
