#define LSM303D_WHO_AM_I 0x0F
#define LSM303D_CTRL_REG1 0x20
#define LSM303D_CTRL_REG4 0x23
#define LSM303D_INT1_CFG 0x30
#define LSM303D_OUT_X_L_A 0x28

#define ACCEL_ODR 50
#define ACCEL_FS 2
#define ACCEL_THRESHOLD 2000
#define ACCEL_DURATION 0

#define BUFFER_SIZE 64

int main(void)
{
    int fd;
    int ret;
    uint8_t reg_val;
    uint8_t buf[6];
    uint8_t i;
    uint8_t j;
    uint8_t k;
    uint8_t accel_data[BUFFER_SIZE][3];
    uint8_t accel_idx = 0;
    uint8_t accel_count = 0;
    uint8_t accel_threshold = ACCEL_THRESHOLD / 16;
    uint8_t accel_duration = ACCEL_DURATION;
    uint8_t accel_odr = ACCEL_ODR;
    uint8_t accel_fs = ACCEL_FS;
    uint8_t accel_ctrl_reg1 = (accel_odr << 4) | (accel_fs << 2) | 0x01;
    uint8_t accel_ctrl_reg4 = (accel_fs << 4) | 0x00;
    uint8_t accel_int1_cfg = (accel_threshold << 4) | (accel_duration << 2) | 0x01;

    // Open I2C device
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    ret = ioctl(fd, I2C_SLAVE, LSM303D_ADDR);
    if (ret < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Check WHO_AM_I register
    ret = i2c_smbus_read_byte_data(fd, LSM303D_WHO_AM_I);
    if (ret < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (ret != 0x49) {
        fprintf(stderr, "Invalid WHO_AM_I register value: 0x%02X\n", ret);
        close(fd);
        return 1;
    }

    // Configure accelerometer
    ret = i2c_smbus_write_byte_data(fd, LSM303D_CTRL_REG1, accel_ctrl_reg1);
    if (ret < 0) {
        fprintf(stderr, "Error writing CTRL_REG1 register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    ret = i2c_smbus_write_byte_data(fd, LSM303D_CTRL_REG4, accel_ctrl_reg4);
    if (ret < 0) {
        fprintf(stderr, "Error writing CTRL_REG4 register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    ret = i2c_smbus_write_byte_data(fd, LSM303D_INT1_CFG, accel_int1_cfg);
    if (ret < 0) {
        fprintf(stderr, "Error writing INT1_CFG register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Request GPIO interrupt line
    gpiod_line_request_output(23, "accel_int", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO interrupt line: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Enable GPIO interrupt line
    gpiod_line_set_value(23, 1);
    if (ret < 0) {
        fprintf(stderr, "Error enabling GPIO interrupt line: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    // Poll accelerometer at 10 ms intervals
    while (1) {
        // Read acceleration data
        ret = i2c_smbus_read_i2c_block_data(fd, LSM303D_OUT_X_L_A, 6, buf);
        if (ret < 0) {
            fprintf(stderr, "Error reading acceleration data: %s\n", strerror(errno));
            close(fd);
            return 1;
        }

        // Store acceleration data in buffer
        accel_data[accel_idx][0] = buf[0];
        accel_data[accel_idx][1] = buf[1];
        accel_data[accel_idx][2] = buf[2];

        // Increment buffer index
        accel_idx++;
        if (accel_idx >= BUFFER_SIZE) {
            accel_idx = 0;
        }

        // Increment sample count
        accel_count++;

        // Wait 10 ms
        usleep(10000);
    }

    // Disable accelerometer on SIGINT
    signal(SIGINT, disable_accel);

    // Close I2C device
    close(fd);

    return 0;
}

void disable_accel(int signum)
{
    // Disable accelerometer
    i2c_smbus_write_byte_data(fd, LSM303D_CTRL_REG1, 0x00);

    // Close I2C device
    close(fd);

    // Exit cleanly
    exit(0);
}

