#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define PIN_LOCK1 17
#define PIN_LOCK2 27
#define BAUD_RATE 9600
#define TIMEOUT 5
#define CODE_LENGTH 6
#define EXPECTED_CODE "123456"

static int gpio_handle;
static int serial_handle1, serial_handle2;
static char code1[CODE_LENGTH], code2[CODE_LENGTH];

static void handle_sigint(int signal) {
    // Clean shutdown
    gpioWrite(gpio_handle, PIN_LOCK1, LOW);
    gpioWrite(gpio_handle, PIN_LOCK2, LOW);
    serialClose(serial_handle1);
    serialClose(serial_handle2);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO pins
    gpio_handle = gpioInitialise();
    if (gpio_handle < 0) {
        fprintf(stderr, "Failed to initialize GPIO pins\n");
        return 1;
    }

    // Set up serial ports
    serial_handle1 = serialOpen("/dev/serial0", BAUD_RATE);
    serial_handle2 = serialOpen("/dev/serial1", BAUD_RATE);
    if (serial_handle1 < 0 || serial_handle2 < 0) {
        fprintf(stderr, "Failed to open serial ports\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Main loop
    while (1) {
        // Read codes from serial ports
        if (serialRead(serial_handle1, code1, CODE_LENGTH, TIMEOUT) < 0) {
            fprintf(stderr, "Failed to read code from serial port 1\n");
            continue;
        }
        if (serialRead(serial_handle2, code2, CODE_LENGTH, TIMEOUT) < 0) {
            fprintf(stderr, "Failed to read code from serial port 2\n");
            continue;
        }

        // Check if codes match
        if (strcmp(code1, code2) != 0) {
            fprintf(stderr, "Codes do not match\n");
            continue;
        }

        // Check if code matches expected code
        if (strcmp(code1, EXPECTED_CODE) != 0) {
            fprintf(stderr, "Code does not match expected code\n");
            continue;
        }

        // Unlock both doors
        gpioWrite(gpio_handle, PIN_LOCK1, HIGH);
        gpioWrite(gpio_handle, PIN_LOCK2, HIGH);
        sleep(2);

        // Relock both doors
        gpioWrite(gpio_handle, PIN_LOCK1, LOW);
        gpioWrite(gpio_handle, PIN_LOCK2, LOW);
    }

    // Clean shutdown
    gpioWrite(gpio_handle, PIN_LOCK1, LOW);
    gpioWrite(gpio_handle, PIN_LOCK2, LOW);
    serialClose(serial_handle1);
    serialClose(serial_handle2);
    gpioTerminate();

    return 0;
}

