#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define STRIKE_DURATION 1000
#define FAILSAFE_TIMEOUT 10000

static gpiod_chip *chip;
static gpiod_line *pir_line, *relay_line;

static void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        // Clean shutdown
        gpiod_line_release(pir_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        closelog();
        exit(0);
    }
}

static void handle_motion(void) {
    // Check if motion is detected
    int value = gpiod_line_get_value(pir_line);
    if (value == 1) {
        // Motion detected, energize the relay
        gpiod_line_set_value(relay_line, 1);
        // Wait for the strike duration
        usleep(STRIKE_DURATION);
        // De-energize the relay
        gpiod_line_set_value(relay_line, 0);
    }
}

static void handle_failsafe(void) {
    // Check if the PIR sensor remains HIGH for more than 10 seconds
    int value = gpiod_line_get_value(pir_line);
    if (value == 1) {
        // De-energize the relay
        gpiod_line_set_value(relay_line, 0);
        // Log a warning message
        syslog(LOG_WARNING, "PIR sensor remains HIGH for more than 10 seconds, de-energizing the relay");
    }
}

int main(void) {
    // Open the gpiochip by name
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0");
        exit(1);
    }

    // Request the two lines explicitly
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get line %d", PIR_PIN);
