#define RELAY_OFF 1

#define RELAY_PAUSE 2

#define TIMER_INTERVAL 60

volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void sigterm_handler(int signum) {
    running = 0;
}

void timer_callback(int timer_id, int millis) {
    static int relay_state = RELAY_OFF;
    static int relay_count = 0;

    if (relay_state == RELAY_OFF) {
        gpioWrite(RELAY_1, RELAY_ON);
        relay_state = RELAY_ON;
        relay_count++;
    } else if (relay_state == RELAY_ON) {
        gpioWrite(RELAY_1, RELAY_OFF);
        relay_state = RELAY_OFF;
        if (relay_count == 4) {
            relay_count = 0;
        }
    } else if (relay_state == RELAY_PAUSE) {
        relay_state = RELAY_OFF;
    }

    if (relay_count == 0) {
        gpioWrite(RELAY_2, RELAY_ON);
        relay_state = RELAY_ON;
    } else if (relay_count == 1) {
        gpioWrite(RELAY_2, RELAY_OFF);
        relay_state = RELAY_OFF;
    } else if (relay_count == 2) {
        gpioWrite(RELAY_3, RELAY_ON);
        relay_state = RELAY_ON;
    } else if (relay_count == 3) {
        gpioWrite(RELAY_3, RELAY_OFF);
        relay_state = RELAY_OFF;
    } else if (relay_count == 4) {
        gpioWrite(RELAY_4, RELAY_ON);
        relay_state = RELAY_ON;
    } else if (relay_count == 5) {
        gpioWrite(RELAY_4, RELAY_OFF);
        relay_state = RELAY_OFF;
    }

    if (relay_count == 4) {
        relay_count = 0;
    }
}

int main(int argc, char *argv[]) {
    int gpio_handle;
    int timer_handle;

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        return 1;
    }

    gpio_handle = gpioOpen(RELAY_1, GPIO_OUTPUT);
    if (gpio_handle < 0) {
        syslog(LOG_ERR, "Failed to open GPIO %d", RELAY_1);
        return 1;
    }

    gpio_handle = gpioOpen(RELAY_2, GPIO_OUTPUT);
    if (gpio_handle < 0) {
        syslog(LOG_ERR, "Failed to open GPIO %d", RELAY_2);
        return 1;
    }

    gpio_handle = gpioOpen(RELAY_3, GPIO_OUTPUT);
    if (gpio_handle < 0) {
        syslog(LOG_ERR, "Failed to open GPIO %d", RELAY_3);
        return 1;
    }

    gpio_handle = gpioOpen(RELAY_4, GPIO_OUTPUT);
    if (gpio_handle < 0) {
        syslog(LOG_ERR, "Failed to open GPIO %d", RELAY_4);
        return 1;
    }

    gpioSetMode(RELAY_1, PI_OUTPUT);
    gpioSetMode(RELAY_2, PI_OUTPUT);
    gpioSetMode(RELAY_3, PI_OUTPUT);
    gpioSetMode(RELAY_4, PI_OUTPUT);

    gpioWrite(RELAY_1, RELAY_OFF);
    gpioWrite(RELAY_2, RELAY_OFF);
    gpioWrite(RELAY_3, RELAY_OFF);
    gpioWrite(RELAY_4, RELAY_OFF);

    timer_handle = gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback);
    if (timer_handle < 0) {
        syslog(LOG_ERR, "Failed to set timer");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (running) {
        sleep(1);
    }

    gpioWrite(RELAY_1, RELAY_OFF);
    gpioWrite(RELAY_2, RELAY_OFF);
    gpioWrite(RELAY_3, RELAY_OFF);
    gpioWrite(RELAY_4, RELAY_OFF);

    gpioSetTimerFuncEx(0, 0, NULL);

    gpioClose(RELAY_1);
    gpioClose(RELAY_2);
    gpioClose(RELAY_3);
    gpioClose(RELAY_4);

    gpioTerminate();

    return 0;
}

