#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define RELAY_1_GPIO 18
#define RELAY_2_GPIO 23
#define RELAY_3_GPIO 24
#define RELAY_4_GPIO 25

#define RELAY_1_INTERVAL 2
#define RELAY_2_INTERVAL 3
#define RELAY_3_INTERVAL 5
#define RELAY_4_INTERVAL 7

static bool running = true;

static void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        running = false;
    }
}

static void init_relays(void) {
    gpiod_chip_t *chip;
    gpiod_line_t *line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, RELAY_1_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line for relay 1\n");
        exit(1);
    }

    gpiod_line_request_output(line, "relay1", 0);
    if (gpiod_line_request_output(line, "relay1", 0) < 0) {
        fprintf(stderr, "Failed to request output for relay 1\n");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, RELAY_2_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line for relay 2\n");
        exit(1);
    }

    gpiod_line_request_output(line, "relay2", 0);
    if (gpiod_line_request_output(line, "relay2", 0) < 0) {
        fprintf(stderr, "Failed to request output for relay 2\n");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, RELAY_3_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line for relay 3\n");
        exit(1);
    }

    gpiod_line_request_output(line, "relay3", 0);
    if (gpiod_line_request_output(line, "relay3", 0) < 0) {
        fprintf(stderr, "Failed to request output for relay 3\n");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, RELAY_4_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line for relay 4\n");
        exit(1);
    }

    gpiod_line_request_output(line, "relay4", 0);
    if (gpiod_line_request_output(line, "relay4", 0) < 0) {
        fprintf(stderr, "Failed to request output for relay 4\n");
        exit(1);
    }
}

static void cleanup_relays(void) {
    gpiod_chip_t *chip;
    gpiod_line_t *line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, RELAY_1_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line for relay 1\n");
        exit(1);
    }

    gpiod_line_release(line);

    line = gpiod_chip_get_line(chip, RELAY_2_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line for relay 2\n");
        exit(1);
    }

    gpiod_line_release(line);

    line = gpiod_chip_get_line(chip, RELAY_3_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line for relay 3\n");
        exit(1);
    }

    gpiod_line_release(line);

    line = gpiod_chip_get_line(chip, RELAY_4_GPIO);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line for relay 4\n");
        exit(1);
    }

    gpiod_line_release(line);
}

static void toggle_relay(int relay_gpio, int interval) {
    gpiod_chip_t *chip;
    gpiod_line_t *line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, relay_gpio);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line for relay %d\n", relay_gpio);
        exit(1);
    }

    gpiod_line_set_value(line, 1);
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set value for relay %d\n", relay_gpio);
        exit(1);
    }

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    ts.tv_sec += interval;

    while (running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec >= ts.tv_sec) {
            gpiod_line_set_value(line, 0);
            if (gpiod_line_set_value(line, 0) < 0) {
                fprintf(stderr, "Failed to set value for relay %d\n", relay_gpio);
                exit(1);
            }
            break;
        }
    }
}

int main(void) {
    init_relays();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    toggle_relay(RELAY_1_GPIO, RELAY_1_INTERVAL);
    toggle_relay(RELAY_2_GPIO, RELAY_2_INTERVAL);
    toggle_relay(RELAY_3_GPIO, RELAY_3_INTERVAL);
    toggle_relay(RELAY_4_GPIO, RELAY_4_INTERVAL);

    cleanup_relays();

    return 0;
}

