static void toggle_relay(int relay_gpio, int interval) {
    gpiod_chip_t *chip;
    gpiod_line_t *line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    line = gpiod_chip_get_line(chip, relay_gpio);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line for relay %d\n", relay_gpio);
        exit(1);
    }

    gpiod_line_set_value(line, 1);
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set value for relay %d\n", relay_gpio);
        exit(1);
    }

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    ts.tv_sec += interval;

    while (running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec >= ts.tv_sec) {
            gpiod_line_set_value(line, 0);
            if (gpiod_line_set_value(line, 0) < 0) {
                fprintf(stderr, "Failed to set value for relay %d\n", relay_gpio);
                exit(1);
            }
            break;
        }
    }
}

int main(void) {
    init_relays();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    toggle_relay(RELAY_1_GPIO, RELAY_1_INTERVAL);
    toggle_relay(RELAY_2_GPIO, RELAY_2_INTERVAL);
    toggle_relay(RELAY_3_GPIO, RELAY_3_INTERVAL);
    toggle_relay(RELAY_4_GPIO, RELAY_4_INTERVAL);

    cleanup_relays();

    return 0;
}
