#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27
#define THRESHOLD 1000
#define DEBOUNCE_TIME 100

static bool is_alarm_active = false;
static bool is_shutting_down = false;

static void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        is_shutting_down = true;
    }
}

static void alarm_handler(int gpio, int level, uint32_t tick) {
    if (level == 1 && !is_alarm_active) {
        is_alarm_active = true;
        printf("Sound detected, activating alarm\n");
        gpio_write(RELAY_PIN, 1);
        sleep(3);
        gpio_write(RELAY_PIN, 0);
        is_alarm_active = false;
        printf("Alarm deactivated\n");
    }
}

int main(void) {
    int pi;
    int sound_sensor_fd;
    int relay_fd;
    struct timespec ts;

    // Initialize pigpio
    if ((pi = pigpio_start(NULL, NULL)) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Set up GPIO pins
    if ((sound_sensor_fd = gpio_export(pi, SOUND_SENSOR_PIN)) < 0) {
        fprintf(stderr, "Failed to export GPIO pin %d\n", SOUND_SENSOR_PIN);
        return 1;
    }
    if ((relay_fd = gpio_export(pi, RELAY_PIN)) < 0) {
        fprintf(stderr, "Failed to export GPIO pin %d\n", RELAY_PIN);
        return 1;
    }

    // Set up GPIO callback
    if (gpio_set_callback(pi, SOUND_SENSOR_PIN, alarm_handler) < 0) {
        fprintf(stderr, "Failed to set GPIO callback\n");
        return 1;
    }

    // Set up debounce timer
    ts.tv_sec = 0;
    ts.tv_nsec = DEBOUNCE_TIME * 1000000;

    // Main loop
    while (!is_shutting_down) {
        // Read sound sensor value
        int sound_sensor_value = gpio_read(pi, sound_sensor_fd);
        if (sound_sensor_value < 0) {
            fprintf(stderr, "Failed to read GPIO pin %d\n", SOUND_SENSOR_PIN);
            return 1;
        }

        // Check if sound above threshold
        if (sound_sensor_value > THRESHOLD) {
            // Check if debounce timer has expired
            if (nanosleep(&ts, NULL) < 0) {
                fprintf(stderr, "Failed to set debounce timer\n");
                return 1;
            }

            // Activate alarm
            gpio_write(relay_fd, 1);
            sleep(3);
            gpio_write(relay_fd, 0);
        }
    }

    // Clean up
    gpio_unexport(pi, sound_sensor_fd);
    gpio_unexport(pi, relay_fd);
    pigpio_stop(pi);

    return 0;
}

