#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define PWR_MGMT_1 0x6B
#define WHO_AM_I 0x75

#define GYRO_SENSITIVITY 131.0
#define THRESHOLD 50.0

#define BUFFER_SIZE 100

typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int tail;
} buffer_t;

void init_buffer(buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
}

void add_to_buffer(buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
}

gyro_data_t get_from_buffer(buffer_t *buffer) {
    gyro_data_t data = buffer->data[buffer->tail];
    buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    return data;
}

void gyro_callback(gyro_data_t data) {
    printf("Gyroscope data: x = %f, y = %f, z = %f\n", data.x, data.y, data.z);
}

int main(void) {
    int fd;
    buffer_t buffer;
    gyro_data_t data;

    // Open the I2C bus
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Initialize the buffer
    init_buffer(&buffer);

    // Wake up the sensor
    if (write(fd, PWR_MGMT_1, 1) < 0) {
        perror("Failed to wake up sensor");
        close(fd);
        return 1;
    }

    // Verify the device
    if (read(fd, WHO_AM_I, 1) != 0x68) {
        perror("Invalid device ID");
        close(fd);
        return 1;
    }

    // Read the gyroscope data
    while (1) {
        // Read the X, Y, and Z axis data
        if (read(fd, GYRO_XOUT_H, 6) < 0) {
            perror("Failed to read gyroscope data");
            close(fd);
            return 1;
        }

        // Convert the data to degrees/second
        data.x = (float)((int16_t)buffer.data[0] * GYRO_SENSITIVITY);
        data.y = (float)((int16_t)buffer.data[1] * GYRO_SENSITIVITY);
        data.z = (float)((int16_t)buffer.data[2] * GYRO_SENSITIVITY);

        // Add the data to the buffer
        add_to_buffer(&buffer, data);

        // Check if the absolute angular velocity exceeds the threshold
        if (abs(data.x) > THRESHOLD || abs(data.y) > THRESHOLD || abs(data.z) > THRESHOLD) {
            gyro_callback(data);
        }
    }

    // Close the I2C bus
    close(fd);

    return 0;
}

