#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define CO2_READ_CMD {0xFF,0x01,0x86,0x00,0x00,0x00,0x00,0x00,0x79}
#define CO2_READ_TIMEOUT 1000
#define CO2_READ_RETRIES 5
#define CO2_LOG_FILE "co2_log.json"
#define CO2_ERROR_FILE "co2_error.log"

static int co2_fd;
static int co2_log_fd;
static int co2_error_fd;

static void co2_read_cb(int fd, int revents, void *userdata) {
    if (revents & (PI_SER_EVT_RXCHAR | PI_SER_EVT_RXFLAG)) {
        uint8_t response[9];
        int bytes_read = serRead(co2_fd, response, 9);
        if (bytes_read == 9) {
            uint8_t checksum = 0;
            for (int i = 1; i < 8; i++) {
                checksum += response[i];
            }
            checksum = ~checksum + 1;
            if (checksum == response[8]) {
                uint16_t co2 = (response[2] << 8) | response[3];
                char json[100];
                snprintf(json, sizeof(json), "{\"timestamp\":%ld,\"ppm\":%d,\"error\":false}", time(NULL), co2);
                serWrite(co2_log_fd, json, strlen(json));
                serFlush(co2_log_fd);
                printf("%s\n", json);
            } else {
                char json[100];
                snprintf(json, sizeof(json), "{\"timestamp\":%ld,\"ppm\":0,\"error\":true}", time(NULL));
                serWrite(co2_log_fd, json, strlen(json));
                serFlush(co2_log_fd);
                printf("%s\n", json);
                fprintf(co2_error_fd, "Checksum mismatch: %02x != %02x\n", checksum, response[8]);
            }
        } else {
            fprintf(co2_error_fd, "Partial read: %d bytes\n", bytes_read);
        }
    }
}

static void co2_error_cb(int fd, int revents, void *userdata) {
    if (revents & (PI_SER_EVT_ERR | PI_SER_EVT_HUP)) {
        fprintf(co2_error_fd, "Error on UART: %s\n", strerror(errno));
    }
}

static void co2_sigint_handler(int signum) {
    serClose(co2_fd);
    serClose(co2_log_fd);
    serClose(co2_error_fd);
    pigpioStop();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <serial_device>\n", argv[0]);
        return 1;
    }

    if (pigpioStart() < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        return 1;
    }

    co2_fd = serOpen(argv[1], 9600, 0);
    if (co2_fd < 0) {
        fprintf(stderr, "Failed to open serial device: %s\n", strerror(errno));
        pigpioStop();
        return 1;
    }

    co2_log_fd = open(CO2_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (co2_log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        serClose(co2_fd);
        pigpioStop();
        return 1;
    }

    co2_error_fd = open(CO2_ERROR_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (co2_error_fd < 0) {
        fprintf(stderr, "Failed to open error file: %s\n", strerror(errno));
        serClose(co2_fd);
        close(co2_log_fd);
        pigpioStop();
        return 1;
    }

    signal(SIGINT, co2_sigint_handler);
    signal(SIGTERM, co2_sigint_handler);

    serSetBuf(co2_fd, 0, 0);
    serSetReadCallback(co2_fd, co2_read_cb, NULL);
    serSetErrorCallback(co2_fd, co2_error_cb, NULL);

    while (1) {
        serWrite(co2_fd, CO2_READ_CMD, 9);
        usleep(CO2_READ_TIMEOUT * 1000);
    }

    return 0;
}

