#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <pigpio.h>
#include <hmc5883l.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define CONFIG_A 0x70
#define CONFIG_B 0x20
#define MODE 0x00
#define X_OFFSET 100
#define Y_OFFSET -50
#define TARGET_HEADING 90.0
#define HEADING_THRESHOLD 10.0
#define BUFFER_SIZE 100

int main(void) {
    // Initialize pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Initialize I2C bus
    if (i2c_init(I2C_BUS, 100000) < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        return 1;
    }

    // Initialize HMC5883L magnetometer
    if (hmc5883l_init(I2C_BUS, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to initialize HMC5883L magnetometer\n");
        return 1;
    }

    // Configure HMC5883L magnetometer
    if (hmc5883l_config(I2C_BUS, I2C_ADDR, CONFIG_A, CONFIG_B, MODE) < 0) {
        fprintf(stderr, "Failed to configure HMC5883L magnetometer\n");
        return 1;
    }

    // Set up circular buffer for logging
    int buffer[BUFFER_SIZE];
    int buffer_head = 0;
    int buffer_tail = 0;

    // Set up GPIO pin for output
    if (gpio_init(17, GPIO_OUT) < 0) {
        fprintf(stderr, "Failed to initialize GPIO pin\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read heading data from HMC5883L magnetometer
        int16_t x, y, z;
        if (hmc5883l_read(I2C_BUS, I2C_ADDR, &x, &y, &z) < 0) {
            fprintf(stderr, "Failed to read heading data from HMC5883L magnetometer\n");
            return 1;
        }

        // Compensate for hard-iron distortion
        int16_t compensated_x = x - X_OFFSET;
        int16_t compensated_y = y - Y_OFFSET;

        // Calculate heading
        double heading = atan2(compensated_y, compensated_x) * 180.0 / M_PI;

        // Check if heading is within threshold
        if (fabs(heading - TARGET_HEADING) > HEADING_THRESHOLD) {
            // Set GPIO pin high
            gpio_write(17, 1);
        } else {
            // Set GPIO pin low
            gpio_write(17, 0);
        }

        // Log heading data into circular buffer
        buffer[buffer_head] = heading;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        if (buffer_head == buffer_tail) {
            buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up resources
    gpio_close(17);
    hmc5883l_close(I2C_BUS, I2C_ADDR);
    i2c_close(I2C_BUS);
    pigpio_stop();

    return 0;
}

