#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod/libgpiod.h>

#define BH1750_ADDR 0x23
#define BH1750_CONT_HIGH_RES_MODE 0x10
#define BH1750_CONV_TIME_MS 120
#define RED_RELAY_GPIO 17
#define GREEN_RELAY_GPIO 27
#define BLUE_RELAY_GPIO 22
#define LOG_FILE "lighting_log.txt"

int main(void) {
    // Initialize GPIO lines
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    struct gpiod_line *red_relay = gpiod_chip_get_line(chip, RED_RELAY_GPIO);
    struct gpiod_line *green_relay = gpiod_chip_get_line(chip, GREEN_RELAY_GPIO);
    struct gpiod_line *blue_relay = gpiod_chip_get_line(chip, BLUE_RELAY_GPIO);

    if (!red_relay || !green_relay || !blue_relay) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize I2C bus
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize BH1750 sensor
    uint8_t buf[2];
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    if (write(i2c_fd, &BH1750_CONT_HIGH_RES_MODE, 1) < 0) {
        perror("Failed to set BH1750 mode");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    // Wait for first conversion
    usleep(BH1750_CONV_TIME_MS * 1000);

    // Read lux value
    if (read(i2c_fd, buf, 2) < 0) {
        perror("Failed to read BH1750 data");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    uint16_t raw = (buf[0] << 8) | buf[1];
    float lux = raw / 1.2;

    // Set relay states
    if (lux < 50) {
        gpiod_line_set_value(red_relay, 1);
        gpiod_line_set_value(green_relay, 0);
        gpiod_line_set_value(blue_relay, 0);
    } else if (lux >= 50 && lux < 150) {
        gpiod_line_set_value(red_relay, 0);
        gpiod_line_set_value(green_relay, 1);
        gpiod_line_set_value(blue_relay, 0);
    } else if (lux >= 150 && lux < 300) {
        gpiod_line_set_value(red_relay, 0);
        gpiod_line_set_value(green_relay, 0);
        gpiod_line_set_value(blue_relay, 1);
    } else {
        gpiod_line_set_value(red_relay, 1);
        gpiod_line_set_value(green_relay, 1);
        gpiod_line_set_value(blue_relay, 1);
    }

    // Log data
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    fprintf(log_file, "%ld, %f, %d, %d, %d\n", time(NULL), lux, gpiod_line_get_value(red_relay), gpiod_line_get_value(green_relay), gpiod_line_get_value(blue_relay));
    fclose(log_file);

    // Clean up
    close(i2c_fd);
    gpiod_chip_close(chip);

    return 0;
}

