#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQ 1000
#define PWM_RANGE 255

void motor_control(int motor, int distance) {
    int duty_cycle = (255 * (100 - distance)) / 100;
    duty_cycle = (duty_cycle < 0) ? 0 : (duty_cycle > 255) ? 255 : duty_cycle;

    if (distance < 50) {
        gpioWrite(motor, 1);
        gpioPWM(motor + 1, PWM_FREQ, duty_cycle);
    } else {
        gpioWrite(motor, 0);
        gpioPWM(motor + 1, PWM_FREQ, duty_cycle);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    while (1) {
        int distance_a = 0; // read distance sensor for motor A
        int distance_b = 0; // read distance sensor for motor B

        motor_control(MOTOR_A_IN1, distance_a);
        motor_control(MOTOR_A_IN2, distance_b);

        motor_control(MOTOR_B_IN3, distance_a);
        motor_control(MOTOR_B_IN4, distance_b);

        usleep(100000); // sleep for 100 ms
    }

    gpioTerminate();
    return 0;
}

