#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define STEPS_PER_QUARTER_TURN 512
#define STEP_DELAY 2000

int main(int argc, char *argv[]) {
  // Initialize pigpio
  if (gpioInitialise() < 0) {
    fprintf(stderr, "Failed to initialize pigpio\n");
    return 1;
  }

  // Set up GPIO pins
  int gpio17 = gpioSetMode(17, PI_OUTPUT);
  int gpio18 = gpioSetMode(18, PI_OUTPUT);
  int gpio27 = gpioSetMode(27, PI_OUTPUT);
  int gpio22 = gpioSetMode(22, PI_OUTPUT);
  int gpio24 = gpioSetMode(24, PI_INPUT);
  int gpio23 = gpioSetMode(23, PI_INPUT);

  if (gpio17 < 0 || gpio18 < 0 || gpio27 < 0 || gpio22 < 0 || gpio24 < 0 || gpio23 < 0) {
    fprintf(stderr, "Failed to set GPIO mode\n");
    return 1;
  }

  // Set up signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Main loop
  while (1) {
    // Check for lock button press
    if (gpioRead(gpio24) == PI_LOW) {
      // Lock the door
      printf("Locking door...\n");
      lock_door();
      // Wait for button release
      while (gpioRead(gpio24) == PI_LOW) {
        usleep(10000);
      }
    }

    // Check for unlock button press
    if (gpioRead(gpio23) == PI_LOW) {
      // Unlock the door
      printf("Unlocking door...\n");
      unlock_door();
      // Wait for button release
      while (gpioRead(gpio23) == PI_LOW) {
        usleep(10000);
      }
    }
  }

  // Clean up
  gpioTerminate();

  return 0;
}

void lock_door() {
  // Set coils to full-step mode
  gpioWrite(gpio17, PI_HIGH);
  gpioWrite(gpio18, PI_LOW);
  gpioWrite(gpio27, PI_HIGH);
  gpioWrite(gpio22, PI_LOW);

  // Step the motor
  for (int i = 0; i < STEPS_PER_QUARTER_TURN; i++) {
    gpioWrite(gpio17, PI_LOW);
    gpioWrite(gpio18, PI_HIGH);
    gpioWrite(gpio27, PI_LOW);
    gpioWrite(gpio22, PI_HIGH);
    usleep(STEP_DELAY);
  }
}

void unlock_door() {
  // Set coils to full-step mode
  gpioWrite(gpio17, PI_HIGH);
  gpioWrite(gpio18, PI_LOW);
  gpioWrite(gpio27, PI_HIGH);
  gpioWrite(gpio22, PI_LOW);

  // Step the motor
  for (int i = 0; i < STEPS_PER_QUARTER_TURN; i++) {
    gpioWrite(gpio17, PI_LOW);
    gpioWrite(gpio18, PI_HIGH);
    gpioWrite(gpio27, PI_LOW);
    gpioWrite(gpio22, PI_HIGH);
    usleep(STEP_DELAY);
  }
}

void signal_handler(int signal) {
  // De-energize the motor coils
  gpioWrite(gpio17, PI_LOW);
  gpioWrite(gpio18, PI_LOW);
  gpioWrite(gpio27, PI_LOW);
  gpioWrite(gpio22, PI_LOW);

  // Release pigpio resources
  gpioTerminate();

  // Exit the program
  exit(0);
}

