    gpioWrite(gpio18, PI_HIGH);
    gpioWrite(gpio27, PI_LOW);
    gpioWrite(gpio22, PI_HIGH);
    usleep(STEP_DELAY);
  }
}

void signal_handler(int signal) {
  // De-energize the motor coils
  gpioWrite(gpio17, PI_LOW);
  gpioWrite(gpio18, PI_LOW);
  gpioWrite(gpio27, PI_LOW);
  gpioWrite(gpio22, PI_LOW);

  // Release pigpio resources
  gpioTerminate();

  // Exit the program
  exit(0);
}
