#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

#define MIN_DISTANCE 2
#define MAX_DISTANCE 30
#define MIN_FREQ 200
#define MAX_FREQ 2000

#define TRIG_PULSE_WIDTH 10
#define MEASUREMENT_INTERVAL 60

int main(void) {
    // Initialise pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", TRIG_PIN);
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", ECHO_PIN);
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BUZZER_PIN);
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Main loop
    while (1) {
        // Trigger the HC-SR04
        gpioWrite(TRIG_PIN, PI_HIGH);
        gpioDelay(TRIG_PULSE_WIDTH);
        gpioWrite(TRIG_PIN, PI_LOW);

        // Measure the echo pulse width
        int echo_width = gpioTick(ECHO_PIN);
        if (echo_width < 0) {
            fprintf(stderr, "Failed to measure echo pulse width\n");
            continue;
        }

        // Calculate the distance
        int distance = echo_width / 58;

        // Map the distance to a frequency
        int freq = map_distance_to_frequency(distance);

        // Set the buzzer frequency
        gpioPWM(BUZZER_PIN, freq);

        // Sleep for the measurement interval
        usleep(MEASUREMENT_INTERVAL * 1000);
    }

    // Clean up
    gpioTerminate();

    return 0;
}

int map_distance_to_frequency(int distance) {
    // Clamp the distance to the valid range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Map the distance to a frequency
    int freq = (distance - MIN_DISTANCE) * (MAX_FREQ - MIN_FREQ) / (MAX_DISTANCE - MIN_DISTANCE) + MIN_FREQ;

    return freq;
}

void handle_sigint(int signal) {
    // Silence the buzzer
    gpioPWM(BUZZER_PIN, 0);

    // Deinitialise pigpio
    gpioTerminate();

    // Exit the program
    exit(0);
}

