#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27

#define PWM_FREQ 1000
#define PWM_RANGE 1000

#define PROXIMITY_MIN 0.0
#define PROXIMITY_MAX 1.0

static int gpio_init(void) {
    int result;

    if ((result = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", gpioErrorMessage(result));
        return result;
    }

    if ((result = gpioSetMode(RED_PIN, PI_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to set RED_PIN mode: %s\n", gpioErrorMessage(result));
        return result;
    }

    if ((result = gpioSetMode(GREEN_PIN, PI_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to set GREEN_PIN mode: %s\n", gpioErrorMessage(result));
        return result;
    }

    if ((result = gpioSetMode(BLUE_PIN, PI_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to set BLUE_PIN mode: %s\n", gpioErrorMessage(result));
        return result;
    }

    return 0;
}

static void gpio_cleanup(void) {
    gpioTerminate();
}

static void set_color(float proximity) {
    int red, green, blue;

    if (proximity < PROXIMITY_MIN) {
        red = 0;
        green = 0;
        blue = 0;
    } else if (proximity < PROXIMITY_MAX) {
        red = (int)(255 * (1 - proximity));
        green = (int)(255 * proximity);
        blue = 0;
    } else {
        red = 255;
        green = 255;
        blue = 255;
    }

    gpioPWM(RED_PIN, PWM_FREQ, red);
    gpioPWM(GREEN_PIN, PWM_FREQ, green);
    gpioPWM(BLUE_PIN, PWM_FREQ, blue);
}

static void sigint_handler(int signal) {
    gpio_cleanup();
    exit(0);
}

int main(void) {
    float proximity;
    int result;

    if ((result = gpio_init()) < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", gpioErrorMessage(result));
        return result;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        proximity = sin(2 * M_PI * 10 * (float)clock() / CLOCKS_PER_SEC);
        set_color(proximity);
        sleep(1);
    }

    gpio_cleanup();
    return 0;
}

