#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_DATA_START 0x43
#define GYRO_DATA_LEN 6
#define SENSITIVITY 131.0

int main(void) {
    int fd;
    uint8_t buf[GYRO_DATA_LEN];
    int16_t x, y, z;
    double x_deg, y_deg, z_deg;
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data ioctl_data;
    struct timespec ts;

    // Open the I2C bus
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Wake the sensor
    if (write(fd, PWR_MGMT_1, 0x00) < 0) {
        perror("Failed to wake the sensor");
        close(fd);
        return 1;
    }

    // Set up the I2C read message
    msg.addr = MPU6050_ADDR;
    msg.flags = 0;
    msg.len = GYRO_DATA_LEN;
    msg.buf = buf;

    // Set up the I2C read ioctl data
    ioctl_data.msgs = &msg;
    ioctl_data.nmsgs = 1;

    // Read the gyroscope data
    if (ioctl(fd, I2C_RDWR, &ioctl_data) < 0) {
        perror("Failed to read gyroscope data");
        close(fd);
        return 1;
    }

    // Convert the signed 16-bit values to degrees/second
    x = (int16_t)((buf[0] << 8) | buf[1]);
    y = (int16_t)((buf[2] << 8) | buf[3]);
    z = (int16_t)((buf[4] << 8) | buf[5]);
    x_deg = x / SENSITIVITY;
    y_deg = y / SENSITIVITY;
    z_deg = z / SENSITIVITY;

    // Log the timestamped x, y, z reading
    clock_gettime(CLOCK_REALTIME, &ts);
    printf("%ld.%ld: x = %f, y = %f, z = %f\n", ts.tv_sec, ts.tv_nsec, x_deg, y_deg, z_deg);

    // Close the I2C bus
    close(fd);

    return 0;
}

