#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define BUTTON_GPIO 17
#define BUZZER_GPIO 18
#define DEBOUNCE_TIME 50

volatile int playing = 0;

void button_isr(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        playing = 1;
    }
}

void play_melody() {
    int i;
    const int melody[] = {262, 294, 330, 349, 392, 440, 494, 523, 587, 659, 698, 784, 880, 988, 1047};

    for (i = 0; i < sizeof(melody) / sizeof(int); i++) {
        gpioHardwarePWM(BUZZER_GPIO, 50, melody[i]);
        delay(100);
    }
}

void stop_playback() {
    gpioHardwarePWM(BUZZER_GPIO, 0, 0);
    playing = 0;
}

void sigint_handler(int signum) {
    stop_playback();
    gpioTerminate();
    exit(0);
}

int main() {
    int ret;

    if ((ret = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", gpioErrorMessage(ret));
        return 1;
    }

    if ((ret = gpioSetMode(BUTTON_GPIO, PI_INPUT)) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", BUTTON_GPIO, gpioErrorMessage(ret));
        return 1;
    }

    if ((ret = gpioSetISRFuncEx(BUTTON_GPIO, EITHER_EDGE, 0, button_isr, NULL)) < 0) {
        fprintf(stderr, "Failed to set ISR for GPIO %d: %s\n", BUTTON_GPIO, gpioErrorMessage(ret));
        return 1;
    }

    if ((ret = gpioHardwarePWM(BUZZER_GPIO, 50, 0)) < 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d: %s\n", BUZZER_GPIO, gpioErrorMessage(ret));
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        if (playing) {
            play_melody();
        }
    }

    return 0;
}

