    }

    if ((ret = gpioSetISRFuncEx(BUTTON_GPIO, EITHER_EDGE, 0, button_isr, NULL)) < 0) {
        fprintf(stderr, "Failed to set ISR for GPIO %d: %s\n", BUTTON_GPIO, gpioErrorMessage(ret));
        return 1;
    }

    if ((ret = gpioHardwarePWM(BUZZER_GPIO, 50, 0)) < 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d: %s\n", BUZZER_GPIO, gpioErrorMessage(ret));
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        if (playing) {
            play_melody();
        }
    }

