#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x1E
#define MR_REG_M 0x02
#define CRA_REG_M 0x00
#define X_MSB_REG 0x03
#define X_LSB_REG 0x04
#define Y_MSB_REG 0x05
#define Y_LSB_REG 0x06
#define Z_MSB_REG 0x07
#define Z_LSB_REG 0x08

#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

#define HEADING_N 0
#define HEADING_NE 45
#define HEADING_E 90
#define HEADING_SE 135
#define HEADING_S 180
#define HEADING_SW 225
#define HEADING_W 270
#define HEADING_NW 315

#define CSV_FILE "mag_log.csv"

int main(void) {
    int fd;
    int ret;
    uint8_t buf[8];
    int16_t x, y, z;
    float heading;
    char direction[9];
    char timestamp[20];

    // Open the I2C device
    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    ret = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Configure continuous conversion mode
    ret = write(fd, MR_REG_M, 0x00);
    if (ret < 0) {
        perror("Failed to configure continuous conversion mode");
        close(fd);
        return 1;
    }

    // Set the output data rate to 15 Hz
    ret = write(fd, CRA_REG_M, 0x14);
    if (ret < 0) {
        perror("Failed to set output data rate");
        close(fd);
        return 1;
    }

    // Open the CSV file
    FILE *csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        close(fd);
        return 1;
    }

    // Write the header row if the file does not already exist
    if (fseek(csv_file, 0, SEEK_END) == 0) {
        fprintf(csv_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n");
    }

    // Read the data registers
    ret = read(fd, buf, 8);
    if (ret < 0) {
        perror("Failed to read data registers");
        close(fd);
        fclose(csv_file);
        return 1;
    }

    // Assemble the signed 16-bit X, Y, and Z values
    x = (buf[0] << 8) | buf[1];
    y = (buf[2] << 8) | buf[3];
    z = (buf[4] << 8) | buf[5];

    // Apply hard-iron calibration offsets
    x += X_OFFSET;
    y += Y_OFFSET;
    z += Z_OFFSET;

    // Compute the compass heading in degrees
    heading = atan2f(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }

    // Map the compass heading to one of eight compass directions
    if (heading < HEADING_N) {
        strcpy(direction, "N");
    } else if (heading < HEADING_NE) {
        strcpy(direction, "NE");
    } else if (heading < HEADING_E) {
        strcpy(direction, "E");
    } else if (heading < HEADING_SE) {
        strcpy(direction, "SE");
    } else if (heading < HEADING_S) {
        strcpy(direction, "S");
    } else if (heading < HEADING_SW) {
        strcpy(direction, "SW");
    } else if (heading < HEADING_W) {
        strcpy(direction, "W");
    } else {
        strcpy(direction, "NW");
    }

    // Print the direction and numeric heading to the console
    printf("Direction: %s, Heading: %d\n", direction, (int)heading);

    // Append a row to the CSV file
    fprintf(csv_file, "%s,%.2f,%.2f,%.2f,%d,%s\n", timestamp, x, y, z, (int)heading, direction);

    // Close the I2C device and the CSV file
    close(fd);
    fclose(csv_file);

    return 0;
}

