#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_GPIO 4
#define DEBOUNCE_MS 200

static int relay_state = 0;
static int touch_state = 0;
static int touch_count = 0;
static int touch_last = 0;

static void touch_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        touch_count++;
        touch_last = tick;
    }
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetISRFunc(TOUCH_GPIO, EITHER_EDGE, touch_callback) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(TOUCH_GPIO, PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistor\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay GPIO as output\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        if (touch_count > 0) {
            if (touch_last + DEBOUNCE_MS < tick) {
                touch_count = 0;
                relay_state = !relay_state;
                gpioWrite(RELAY_GPIO, relay_state);
                char *json = malloc(100);
                sprintf(json, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}",
                        time_to_iso8601(tick), relay_state ? "ON" : "OFF");
                FILE *fp = fopen("relay_log.json", "a");
                fprintf(fp, "%s\n", json);
                fclose(fp);
                free(json);
            }
        }
    }

    gpioTerminate();
    return 0;
}

