#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <libgpiod.h>

#define RELAY_1 17
#define RELAY_2 23
#define RELAY_3 24
#define RELAY_4 25

#define SOIL_MOISTURE_MIN 0
#define SOIL_MOISTURE_MAX 100

#define RELAY_ACTIVE_LOW 1
#define RELAY_INACTIVE_LOW 0

#define RELAY_DELAY 5

#define LOG_FILE "irrigation_log.txt"

int main(void) {
    // Initialize the libgpiod library
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open gpiochip0\n");
        return 1;
    }

    // Request the four lines as outputs with an inactive (OFF) drive of 1
    struct gpiod_line *line1 = gpiod_chip_get_line(chip, RELAY_1);
    struct gpiod_line *line2 = gpiod_chip_get_line(chip, RELAY_2);
    struct gpiod_line *line3 = gpiod_chip_get_line(chip, RELAY_3);
    struct gpiod_line *line4 = gpiod_chip_get_line(chip, RELAY_4);

    if (!line1 || !line2 || !line3 || !line4) {
        fprintf(stderr, "Error: Failed to get lines\n");
        return 1;
    }

    if (gpiod_line_request_output(line1, "relay1", RELAY_INACTIVE_LOW) < 0) {
        fprintf(stderr, "Error: Failed to request output for line1\n");
        return 1;
    }

    if (gpiod_line_request_output(line2, "relay2", RELAY_INACTIVE_LOW) < 0) {
        fprintf(stderr, "Error: Failed to request output for line2\n");
        return 1;
    }

    if (gpiod_line_request_output(line3, "relay3", RELAY_INACTIVE_LOW) < 0) {
        fprintf(stderr, "Error: Failed to request output for line3\n");
        return 1;
    }

    if (gpiod_line_request_output(line4, "relay4", RELAY_INACTIVE_LOW) < 0) {
        fprintf(stderr, "Error: Failed to request output for line4\n");
        return 1;
    }

    // Open the log file in append mode
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        return 1;
    }

    // Set the seed for the random number generator
    srand(time(NULL));

    // Main loop
    while (1) {
        // Generate a simulated soil moisture value
        int soil_moisture = rand() % (SOIL_MOISTURE_MAX - SOIL_MOISTURE_MIN) + SOIL_MOISTURE_MIN;

        // Check if the soil moisture is below 30
        if (soil_moisture < 30) {
            // Activate each relay sequentially
            for (int i = 1; i <= 4; i++) {
                // Activate the relay
                if (gpiod_line_set_value(line[i], RELAY_ACTIVE_LOW) < 0) {
                    fprintf(stderr, "Error: Failed to set value for line%d\n", i);
                    return 1;
                }

                // Wait for 5 seconds
                sleep(RELAY_DELAY);

                // Deactivate the relay
                if (gpiod_line_set_value(line[i], RELAY_INACTIVE_LOW) < 0) {
                    fprintf(stderr, "Error: Failed to set value for line%d\n", i);
                    return 1;
                }

                // Wait for 1 second
                sleep(1);
            }

            // Log the activation
            fprintf(log_file, "%s, relay%d, %d\n", get_iso_8601_timestamp(), i, soil_moisture);
            fflush(log_file);
        }

        // Wait for 10 seconds
        sleep(10);
    }

    // Clean up
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_line_release(line4);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

// Get the current ISO-8601 timestamp
char *get_iso_8601_timestamp(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    timestamp = asctime(timeinfo);

    return timestamp;
