#define GPIO_VALVE 17
#define GPIO_NOZZLE 18

#define MIN_MOISTURE 50
#define MAX_MOISTURE 100

#define VALVE_OPEN 90
#define VALVE_CLOSE 0

#define NOZZLE_ANGLES 5
#define NOZZLE_STEP 45

volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void sigterm_handler(int signum) {
    running = 0;
}

int main(void) {
    int moisture;
    int valve_angle;
    int nozzle_angle;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (running) {
        moisture = get_moisture();
        if (moisture < MIN_MOISTURE) {
            valve_angle = VALVE_OPEN;
            nozzle_angle = 0;
        } else {
            valve_angle = VALVE_CLOSE;
            nozzle_angle = 0;
        }

        ret = gpioServo(GPIO_VALVE, valve_angle);
        if (ret < 0) {
            fprintf(stderr, "Failed to set valve angle: %d\n", ret);
            continue;
        }

        for (int i = 0; i < NOZZLE_ANGLES; i++) {
            ret = gpioServo(GPIO_NOZZLE, nozzle_angle);
            if (ret < 0) {
                fprintf(stderr, "Failed to set nozzle angle: %d\n", ret);
                continue;
            }
            nozzle_angle += NOZZLE_STEP;
            sleep(2);
        }

        ret = gpioServo(GPIO_VALVE, VALVE_CLOSE);
        if (ret < 0) {
            fprintf(stderr, "Failed to close valve: %d\n", ret);
            continue;
        }

        sleep(5);
    }

    gpioServo(GPIO_VALVE, 0);
    gpioServo(GPIO_NOZZLE, 0);
    gpioTerminate();

    return 0;
}

