#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <signal.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_SENSITIVITY 131.0

#define SAMPLE_RATE 10
#define SAMPLE_PERIOD (1000000 / SAMPLE_RATE)

static int i2c_fd;
static int gyro_fd;

static void sigint_handler(int signum) {
    printf("Caught signal %d, exiting...\n", signum);
    close(i2c_fd);
    close(gyro_fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <gyro_log.txt>\n", argv[0]);
        return 1;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C device address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C device address");
        close(i2c_fd);
        return 1;
    }

    // Open gyroscope file
    gyro_fd = open(argv[1], O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (gyro_fd < 0) {
        perror("Failed to open gyroscope file");
        close(i2c_fd);
        return 1;
    }

    // Set signal handler for SIGINT/SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Wake up the sensor
    uint8_t pwr_mgmt_1 = 0x00;
    if (write(i2c_fd, &pwr_mgmt_1, 1) != 1) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        close(gyro_fd);
        return 1;
    }

    // Read gyroscope data
    uint8_t reg_addr = GYRO_XOUT_H;
    uint8_t data[6];
    if (read(i2c_fd, &data, 6) != 6) {
        perror("Failed to read from I2C device");
        close(i2c_fd);
        close(gyro_fd);
        return 1;
    }

    // Convert raw data to degrees/second
    int16_t x = (data[0] << 8) | data[1];
    int16_t y = (data[2] << 8) | data[3];
    int16_t z = (data[4] << 8) | data[5];
    double x_deg_s = x * GYRO_SENSITIVITY / 32768.0;
    double y_deg_s = y * GYRO_SENSITIVITY / 32768.0;
    double z_deg_s = z * GYRO_SENSITIVITY / 32768.0;

    // Log data to file
    char buf[100];
    snprintf(buf, sizeof(buf), "%ld, %f, %f, %f\n", time(NULL), x_deg_s, y_deg_s, z_deg_s);
    write(gyro_fd, buf, strlen(buf));

    // Sleep for sample period
    usleep(SAMPLE_PERIOD);

    // Close file descriptors
    close(i2c_fd);
    close(gyro_fd);

    return 0;
}

