#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 50000
#define GUARD_US 60000

static gpiod_chip_t *chip;
static gpiod_line_t *trigger_line, *echo_line;
static FILE *log_file;

static void handle_sigint(int signum) {
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

int main(void) {
    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (trigger_line == NULL) {
        fprintf(stderr, "Error getting trigger line\n");
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (echo_line == NULL) {
        fprintf(stderr, "Error getting echo line\n");
        return 1;
    }

    // Set trigger line as output and echo line as input
    gpiod_line_request_output(trigger_line, "trigger", 0);
    gpiod_line_request_input(echo_line, "echo");

    // Set active-high polarity for echo line
    gpiod_line_set_polarity(echo_line, GPIOD_LINE_ACTIVE_HIGH);

    // Main loop
    while (1) {
        // Wait for guard time
        usleep(GUARD_US);

        // Generate trigger pulse
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        // Measure echo pulse width
        uint64_t start_time = gpiod_line_get_value(echo_line);
        uint64_t end_time = 0;
        while (end_time == 0) {
            end_time = gpiod_line_get_value(echo_line);
            if (end_time == 0) {
                usleep(10);
            }
        }

        // Calculate distance
        uint64_t duration_us = end_time - start_time;
        double distance_cm = duration_us * 0.01715;

        // Log distance to file
        fprintf(log_file, "%f\n", distance_cm);

        // Wait for next measurement
        usleep(1000000 - GUARD_US);
    }

    // Clean up
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

