#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <vl53l1x.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_RELAY 18

#define RANGE_MODE 0x01
#define CONTINUOUS_RANGING 0x01
#define DATA_READY 0x04

#define DISTANCE_THRESHOLD 50

int main(void) {
    // Initialise pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        return 1;
    }

    // Initialise I2C
    int i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
        return 1;
    }

    // Initialise VL53L1X
    uint8_t reg_val = 0;
    if (pigpio_i2c_read_reg(i2c_handle, 0x0000, &reg_val) < 0) {
        fprintf(stderr, "Failed to read register 0x0000\n");
        return 1;
    }
    if (reg_val != 0x00) {
        fprintf(stderr, "Invalid register value 0x%02X for register 0x0000\n", reg_val);
        return 1;
    }
    if (pigpio_i2c_write_reg(i2c_handle, 0x0000, 0x00) < 0) {
        fprintf(stderr, "Failed to write register 0x0000\n");
        return 1;
    }
    if (pigpio_i2c_read_reg(i2c_handle, 0x0080, &reg_val) < 0) {
        fprintf(stderr, "Failed to read register 0x0080\n");
        return 1;
    }
    if (reg_val != 0x00) {
        fprintf(stderr, "Invalid register value 0x%02X for register 0x0080\n", reg_val);
        return 1;
    }
    if (pigpio_i2c_write_reg(i2c_handle, 0x0080, RANGE_MODE) < 0) {
        fprintf(stderr, "Failed to write register 0x0080\n");
        return 1;
    }
    if (pigpio_i2c_read_reg(i2c_handle, 0x0080, &reg_val) < 0) {
        fprintf(stderr, "Failed to read register 0x0080\n");
        return 1;
    }
    if (reg_val != RANGE_MODE) {
        fprintf(stderr, "Invalid register value 0x%02X for register 0x0080\n", reg_val);
        return 1;
    }
    if (pigpio_i2c_write_reg(i2c_handle, 0x0080, CONTINUOUS_RANGING) < 0) {
        fprintf(stderr, "Failed to write register 0x0080\n");
        return 1;
    }

    // Initialise GPIO
    if (pigpio_gpio_init(GPIO_RELAY) < 0) {
        fprintf(stderr, "Failed to initialise GPIO %d\n", GPIO_RELAY);
        return 1;
    }
    if (pigpio_gpio_set_mode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", GPIO_RELAY);
        return 1;
    }

    // Main loop
    while (1) {
        // Check for data ready
        if (pigpio_i2c_read_reg(i2c_handle, 0x0044, &reg_val) < 0) {
            fprintf(stderr, "Failed to read register 0x0044\n");
            return 1;
        }
        if (reg_val & DATA_READY) {
            // Read distance
            uint16_t distance = 0;
            if (pigpio_i2c_read_reg(i2c_handle, 0x0096, &reg_val) < 0) {
                fprintf(stderr, "Failed to read register 0x0096\n");
                return 1;
            }
            distance = (uint16_t)reg_val << 8;
            if (pigpio_i2c_read_reg(i2c_handle, 0x0097, &reg_val) < 0) {
                fprintf(stderr, "Failed to read register 0x0097\n");
                return 1;
            }
            distance |= (uint16_t)reg_val;

            // Log distance
            printf("Distance: %d cm\n", distance);

            // Drive relay
            if (distance <= DISTANCE_THRESHOLD) {
                pigpio_gpio_write(GPIO_RELAY, PI_HIGH);
            } else {
                pigpio_gpio_write(GPIO_RELAY, PI_LOW);
            }
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    pigpio_gpio_close(GPIO_RELAY);
    pigpio_i2c_close(i2c_handle);
    pigpio_stop();

    return 0;
}

