#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_DATA 0x43

#define LSB_TO_DEG_PER_SEC 131.0

int main(void) {
    int fd;
    uint8_t buf[6];
    int16_t x, y, z;

    // Open the I2C bus
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Wake up the sensor from sleep
    if (write(fd, PWR_MGMT_1, 1) < 0) {
        perror("Failed to wake up sensor");
        close(fd);
        return 1;
    }

    // Set the gyroscope full-scale range to ±250 dps
    if (write(fd, GYRO_CONFIG, 1) < 0) {
        perror("Failed to set gyroscope full-scale range");
        close(fd);
        return 1;
    }

    // Read the gyroscope data
    if (read(fd, buf, 6) < 0) {
        perror("Failed to read gyroscope data");
        close(fd);
        return 1;
    }

    // Convert the raw signed 16-bit big-endian values to degrees/second
    x = (int16_t)((buf[0] << 8) | buf[1]);
    y = (int16_t)((buf[2] << 8) | buf[3]);
    z = (int16_t)((buf[4] << 8) | buf[5]);

    // Print the x, y, and z axis readings to the console
    printf("x: %f\ny: %f\nz: %f\n", x * LSB_TO_DEG_PER_SEC, y * LSB_TO_DEG_PER_SEC, z * LSB_TO_DEG_PER_SEC);

    // Close the I2C bus
    close(fd);

    return 0;
}

