#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NAMES "17", "18", "27", "22"
#define GPIO_LINE_COUNT 4
#define WATERING_INTERVAL 86400
#define WATERING_DURATION 5
#define WATERING_LOG_FILE "watering_log.txt"

static gpiod_chip_t *chip;
static gpiod_line_t *lines[GPIO_LINE_COUNT];

static void sigint_handler(int signum) {
    printf("Received signal %d, releasing GPIO lines and closing chip\n", signum);
    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    exit(0);
}

int main(void) {
    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        printf("Error opening GPIO chip %s\n", GPIO_CHIP_NAME);
        return 1;
    }

    // Request GPIO lines as outputs with active-low semantics
    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LINE_NAMES[i]);
        if (!lines[i]) {
            printf("Error getting GPIO line %s\n", GPIO_LINE_NAMES[i]);
            return 1;
        }
        gpiod_line_request_output(lines[i], "watering", 0);
        if (gpiod_line_request_output(lines[i], "watering", 0) < 0) {
            printf("Error requesting GPIO line %s as output\n", GPIO_LINE_NAMES[i]);
            return 1;
        }
    }

    // Set all lines HIGH (inactive) at startup
    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        gpiod_line_set_value(lines[i], 1);
    }

    // Open watering log file
    FILE *log_file = fopen(WATERING_LOG_FILE, "a");
    if (!log_file) {
        printf("Error opening watering log file %s\n", WATERING_LOG_FILE);
        return 1;
    }

    // Main loop
    while (1) {
        // Check if it's time to water
        time_t now = time(NULL);
        if (now % WATERING_INTERVAL == 0) {
            // Water each relay sequentially
            for (int i = 0; i < GPIO_LINE_COUNT; i++) {
                // Set line LOW (active) for WATERING_DURATION seconds
                gpiod_line_set_value(lines[i], 0);
                sleep(WATERING_DURATION);
                gpiod_line_set_value(lines[i], 1);
            }

            // Log watering cycle start time
            char time_str[20];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s\n", time_str);
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up
    fclose(log_file);
    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

