#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define GPIO_SDA 2
#define GPIO_SCL 3
#define GPIO_LED 17
#define BUFFER_SIZE 100
#define SAMPLE_RATE 20
#define THRESHOLD 250

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
    uint32_t timestamp;
} gyro_data_t;

int main(void) {
    // Initialise pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    // Set up I2C
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        return 1;
    }

    // Set up GPIO
    if (gpioSetMode(GPIO_SDA, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_SDA);
        return 1;
    }
    if (gpioSetMode(GPIO_SCL, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_SCL);
        return 1;
    }
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        return 1;
    }

    // Initialise the MPU-6050
    uint8_t reg_val = 0x00;
    if (i2cWriteByte(i2c_handle, 0x6B, reg_val) < 0) {
        fprintf(stderr, "Failed to write to register 0x6B\n");
        return 1;
    }
    reg_val = 0x07;
    if (i2cWriteByte(i2c_handle, 0x19, reg_val) < 0) {
        fprintf(stderr, "Failed to write to register 0x19\n");
        return 1;
    }
    reg_val = 0x00;
    if (i2cWriteByte(i2c_handle, 0x1B, reg_val) < 0) {
        fprintf(stderr, "Failed to write to register 0x1B\n");
        return 1;
    }

    // Verify the WHO_AM_I register
    uint8_t who_am_i;
    if (i2cReadByte(i2c_handle, 0x75, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read from register 0x75\n");
        return 1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "Invalid WHO_AM_I value: 0x%02X\n", who_am_i);
        return 1;
    }

    // Set up the circular buffer
    gyro_data_t buffer[BUFFER_SIZE];
    int buffer_index = 0;

    // Set up the LED
    if (gpioWrite(GPIO_LED, PI_LOW) < 0) {
        fprintf(stderr, "Failed to set GPIO %d low\n", GPIO_LED);
        return 1;
    }

    // Main loop
    while (true) {
        // Read the gyroscope data
        uint8_t data[6];
        if (i2cReadBytes(i2c_handle, 0x43, data, 6) < 0) {
            fprintf(stderr, "Failed to read from register 0x43\n");
            return 1;
        }

        // Convert the data to degrees/second
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        // Store the data in the circular buffer
        buffer[buffer_index].x = x;
        buffer[buffer_index].y = y;
        buffer[buffer_index].z = z;
        buffer[buffer_index].timestamp = time(NULL);
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Check if any axis exceeds the threshold
        bool exceeds_threshold = false;
        if (abs(x) > THRESHOLD || abs(y) > THRESHOLD || abs(z) > THRESHOLD) {
            exceeds_threshold = true;
        }

        // Turn on the LED if any axis exceeds the threshold
        if (exceeds_threshold) {
            if (gpioWrite(GPIO_LED, PI_HIGH) < 0) {
                fprintf(stderr, "Failed to set GPIO %d high\n", GPIO_LED);
                return 1;
            }
        } else {
            if (gpioWrite(GPIO_LED, PI_LOW) < 0) {
                fprintf(stderr, "Failed to set GPIO %d low\n", GPIO_LED);
                return 1;
            }
        }

        // Sleep for 50 ms
        usleep(50000);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

