Here is the complete, compilable C code for the Raspberry Pi 3 Model B+ to read angular velocity from an InvenSense MPU-6050 gyroscope over SPI, using the Linux spidev interface with libgpiod for manual chip-select control on GPIO8 (CE0), and blink an LED on GPIO17 (physical pin 11) if any axis exceeds ±200 deg/s:
```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <libgpiod.h>
#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 3900000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_DELAY 0
#define GPIO_CE0 8
#define GPIO_LED 17
#define BUFFER_SIZE 64
#define SENSITIVITY 131.0
#define THRESHOLD 200.0

struct gyro_data {
    uint64_t timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
};

struct gyro_data buffer[BUFFER_SIZE];

void handle_sigint(int signum) {
    printf("Received SIGINT, printing buffer...\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%llu, %d, %d, %d\n", buffer[i].timestamp, buffer[i].x, buffer[i].y, buffer[i].z);
    }
    printf("Releasing SPI handle and GPIO resources...\n");
    spidev_close(spi_handle);
    gpiod_release(gpio_handle);
    exit(0);
}

int main(void) {
    // Set up SPI handle
    struct spidev_ioc_transfer spi_transfer;
    memset(&spi_transfer, 0, sizeof(spi_transfer));
    spi_transfer.speed = SPI_SPEED;
    spi_transfer.mode = SPI_MODE;
    spi_transfer.bits = SPI_BITS;
    spi_transfer.delay = SPI_DELAY;
    spi_transfer.cs_change = 1;
    spi_transfer.tx_buf = NULL;
