#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_DATA 0x3B
#define ACCEL_DATA_SIZE 6
#define LED_PIN 21

int main(void) {
    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    int i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Initialize MPU-6050
    uint8_t pwr_mgmt_1 = 0x00;
    if (pigpio_i2c_write(i2c_handle, PWR_MGMT_1, &pwr_mgmt_1, 1) < 0) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1\n");
        return 1;
    }

    uint8_t accel_config = 0x00;
    if (pigpio_i2c_write(i2c_handle, ACCEL_CONFIG, &accel_config, 1) < 0) {
        fprintf(stderr, "Failed to write to ACCEL_CONFIG\n");
        return 1;
    }

    // Set up LED
    if (pigpio_gpio_write(LED_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set up LED\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read accelerometer data
        uint8_t accel_data[ACCEL_DATA_SIZE];
        if (pigpio_i2c_read(i2c_handle, ACCEL_DATA, accel_data, ACCEL_DATA_SIZE) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        // Compute roll and pitch
        int16_t x = (int16_t)((accel_data[0] << 8) | accel_data[1]);
        int16_t y = (int16_t)((accel_data[2] << 8) | accel_data[3]);
        int16_t z = (int16_t)((accel_data[4] << 8) | accel_data[5]);
        double roll = atan2(y, z) * 180 / M_PI;
        double pitch = atan2(-x, sqrt(y * y + z * z)) * 180 / M_PI;

        // Check for tilt
        if (abs(roll) > 45 || abs(pitch) > 45) {
            // Turn on LED
            if (pigpio_gpio_write(LED_PIN, 1) < 0) {
                fprintf(stderr, "Failed to turn on LED\n");
                continue;
            }
        } else {
            // Turn off LED
            if (pigpio_gpio_write(LED_PIN, 0) < 0) {
                fprintf(stderr, "Failed to turn off LED\n");
                continue;
            }
        }

        // Log data
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        char log_entry[100];
        sprintf(log_entry, "%s, %f, %f\n", timestamp, roll, pitch);
        FILE *log_file = fopen("tilt_log.txt", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            continue;
        }
        fprintf(log_file, log_entry);
        fclose(log_file);

        // Print data to console
        printf("Roll: %f, Pitch: %f\n", roll, pitch);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    pigpio_i2c_close(i2c_handle);
    pigpio_stop();

    return 0;
}

void signal_handler(int signal) {
    // Turn off LED
    if (pigpio_gpio_write(LED_PIN, 0) < 0) {
        fprintf(stderr, "Failed to turn off LED\n");
    }

    // Close I2C handle
    pigpio_i2c_close(i2c_handle);

    // Terminate pigpio
    pigpio_stop();

    exit(0);
}

