int main(void) {
    int i2c_fd, log_fd, gpio_fd;
    uint8_t buf[2];
    uint16_t ambient_light, proximity;
    char timestamp[20];
    int retries = 3;

    // Open I2C device
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Open log file
    if ((log_fd = open("biometric_log.txt", O_CREAT | O_WRONLY | O_APPEND, 0644)) < 0) {
        perror("Failed to open log file");
        return 1;
    }

    // Open GPIO line
    if ((gpio_fd = gpiod_line_request(LED_PIN, "biometric_led", GPIOD_LINE_REQUEST_OUTPUT)) < 0) {
        perror("Failed to open GPIO line");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        // Read ambient light value
        if (read_register(i2c_fd, REG_AMBIENT_LIGHT, buf, 2) < 0) {
            perror("Failed to read ambient light value");
            return 1;
        }
        ambient_light = (buf[0] << 8) | buf[1];

        // Read proximity value
        if (read_register(i2c_fd, REG_PROXIMITY, buf, 2) < 0) {
            perror("Failed to read proximity value");
            return 1;
        }
        proximity = (buf[0] << 8) | buf[1];

        // Log values
        get_timestamp(timestamp, sizeof(timestamp));
        fprintf(log_fd, "%s,AmbientLight:%d,Proximity:%d\n", timestamp, ambient_light, proximity);

        // Set LED state
        if (proximity > 100) {
            gpiod_line_set_value(gpio_fd, 1);
        } else {
            gpiod_line_set_value(gpio_fd, 0);
        }

        // Wait for next reading
        usleep(100000);
    }

    // Cleanup
    close(i2c_fd);
    close(log_fd);
    gpiod_line_release(gpio_fd);

    return 0;
}

int read_register(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    int retries = 3;

    while (retries-- > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            return -1;
        }

        if (read(fd, buf, len) != len) {
            perror("Failed to read register value");
            return -1;
        }

        return 0;
    }

    return -1;
}

void get_timestamp(char *timestamp, size_t len) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);

    strftime(timestamp, len, "%Y-%m-%d %H:%M:%S", tm);
}

void sigint_handler(int signum) {
    close(i2c_fd);
    close(log_fd);
    gpiod_line_release(gpio_fd);
    exit(0);
}

void sigterm_handler(int signum) {
    close(i2c_fd);
    close(log_fd);
    gpiod_line_release(gpio_fd);
    exit(0);
}

