#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_BUS 0
#define SPI_CE 8
#define SPI_SCLK 11
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_FREQ 1000000
#define SPI_MODE 0

#define LED_PIN 17
#define THRESHOLD 20.0

#define RATE_XL 0x02
#define RATE_XH 0x03

#define BUFFER_SIZE 100

struct reading {
    uint64_t timestamp;
    int16_t x_rate;
};

struct reading buffer[BUFFER_SIZE];

void handle_interrupt(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        // Close SPI
        gpioTerminate();
        // Turn off LED
        gpioWrite(LED_PIN, 0);
        // Terminate pigpio
        pigpioTerminate();
        exit(0);
    }
}

int main(void) {
    // Initialize pigpio
    if (pigpioInit() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up SPI
    if (gpioSpiOpen(SPI_BUS, SPI_CE, SPI_SCLK, SPI_MOSI, SPI_MISO, SPI_FREQ, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        return 1;
    }

    // Set up LED
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, handle_interrupt);
    signal(SIGTERM, handle_interrupt);

    // Main loop
    while (1) {
        // Read X-axis angular rate
        uint8_t x_rate_l = gpioSpiXfer(SPI_BUS, RATE_XL, 1);
        uint8_t x_rate_h = gpioSpiXfer(SPI_BUS, RATE_XH, 1);
        int16_t x_rate = (x_rate_h << 8) | x_rate_l;

        // Convert to degrees per second
        double x_rate_deg_s = x_rate * 200.0 / 32768.0;

        // Timestamp reading
        uint64_t timestamp = clock_gettime(CLOCK_MONOTONIC);

        // Store reading in buffer
        struct reading reading = {
            .timestamp = timestamp,
            .x_rate = x_rate_deg_s,
        };
        buffer[BUFFER_SIZE - 1] = reading;

        // Check for warning condition
        if (x_rate_deg_s > THRESHOLD) {
            // Turn on LED
            gpioWrite(LED_PIN, 1);
        } else {
            // Turn off LED
            gpioWrite(LED_PIN, 0);
        }
    }

    // Close SPI
    gpioSpiClose(SPI_BUS);

    // Terminate pigpio
    pigpioTerminate();

    return 0;
}

