        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LAMP1);
        return 1;
    }
    if (gpioSetMode(GPIO_LAMP2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LAMP2);
        return 1;
    }
    if (gpioSetMode(GPIO_LAMP3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LAMP3);
        return 1;
    }

    // Set up PWM for lamp control
    if (gpioPWM(GPIO_LAMP1, PWM_RANGE, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d\n", GPIO_LAMP1);
        return 1;
    }
    if (gpioPWM(GPIO_LAMP2, PWM_RANGE, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d\n", GPIO_LAMP2);
        return 1;
