    if (gpioPWM(GPIO_LAMP3, PWM_RANGE, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM for GPIO %d\n", GPIO_LAMP3);
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Start fading each lamp sequentially
    for (int i = 0; i < 3; i++) {
        int lamp = i + 1;
        int start_time = time(NULL);
        int end_time = start_time + duration;

        // Fade lamp from full brightness to off
        for (int j = PWM_RANGE; j >= 0; j--) {
            if (time(NULL) >= end_time) {
                break;
            }
            gpioPWM(lamp, j, PWM_FREQ);
            sleep(1);
