    // Turn off all lamps
    gpioPWM(GPIO_LAMP1, 0, PWM_FREQ);
    gpioPWM(GPIO_LAMP2, 0, PWM_FREQ);
    gpioPWM(GPIO_LAMP3, 0, PWM_FREQ);

    // Clean up and exit
    gpioTerminate();
    exit(0);
}

