        printf("Red + Yellow\n");
        sleep(YELLOW_DURATION);

        // Green
        gpiod_line_set_value(gpio_line_red, 1);
        gpiod_line_set_value(gpio_line_yellow, 1);
        gpiod_line_set_value(gpio_line_green, 0);
        gpiod_line_set_value(gpio_line_blue, 1);
        printf("Green\n");
        sleep(GREEN_DURATION);

        // Yellow
        gpiod_line_set_value(gpio_line_red, 1);
        gpiod_line_set_value(gpio_line_yellow, 0);
        gpiod_line_set_value(gpio_line_green, 1);
        gpiod_line_set_value(gpio_line_blue, 1);
        printf("Yellow\n");
        sleep(BLUE_DURATION);
    }

    // Release GPIO lines
    gpiod_line_release(gpio_line_red);
    gpiod_line_release(gpio_line_yellow);
    gpiod_line_release(gpio_line_green);
    gpiod_line_release(gpio_line_blue);

    return 0;
}

