#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define GPIO_PIN 17
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define DEBOUNCE_TIME 100
#define CHARGE_TIME 0x0D
#define RUN_MODE 0x0D

#define LOG_FILE "touch_relay.log"

static bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void sigterm_handler(int signum) {
    running = false;
}

int main(int argc, char **argv) {
    // Initialise pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    // Set GPIO17 as output, default LOW
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GPIO_PIN);
        return 1;
    }

    // Open the I2C device at address 0x5A on bus 1
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X on bus %d\n", I2C_ADDR, I2C_BUS);
        return 1;
    }

    // Configure the MPR121
    uint8_t config[] = {
        0x80, 0x63,
        0x5E, 0x00,
        0x5D, 0x01,
        0x41, TOUCH_THRESHOLD,
        0x42, RELEASE_THRESHOLD,
        0x5B, DEBOUNCE_TIME,
        0x5C, CHARGE_TIME,
        0x5E, RUN_MODE
    };
    if (i2cWrite(i2c_handle, config, sizeof(config)) < 0) {
        fprintf(stderr, "Failed to configure MPR121\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (running) {
        // Read the touch status from registers 0x00 (LSB) and 0x01 (MSB)
        uint8_t touch_status[2];
        if (i2cRead(i2c_handle, 0x00, touch_status, sizeof(touch_status)) < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            return 1;
        }

        // Debounce touch events with a 100 ms delay
        if (touch_status[0] & 0x01) {
            usleep(100000);
            if (i2cRead(i2c_handle, 0x00, touch_status, sizeof(touch_status)) < 0) {
                fprintf(stderr, "Failed to read touch status\n");
                return 1;
            }
        }

        // Toggle the relay if electrode 0 is touched
        if (touch_status[0] & 0x01) {
            gpioWrite(GPIO_PIN, PI_HIGH);
        } else {
            gpioWrite(GPIO_PIN, PI_LOW);
        }

        // Log the touch status and relay state
        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        fprintf(stderr, "%s: Touch status: %02X%02X, relay state: %s\n", timestamp, touch_status[0], touch_status[1], gpioRead(GPIO_PIN) ? "ON" : "OFF");

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

