#include <pigpio.h>

#define SOL1_PIN 17
#define SOL2_PIN 27
#define DISPENSE_DURATION 1000
#define DISPENSE_INTERVAL 5000

void dispense_solenoid(int pin, int duration) {
    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, PI_HIGH);
    gpioDelay(duration);
    gpioWrite(pin, PI_LOW);
}

void dispense_loop() {
    while (true) {
        dispense_solenoid(SOL1_PIN, DISPENSE_DURATION / 2);
        dispense_solenoid(SOL2_PIN, DISPENSE_DURATION / 2);
        gpioDelay(DISPENSE_INTERVAL);
    }
}

void log_dispense(int pin, int duration) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    FILE *log_file = fopen("dispense_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    fprintf(log_file, "%s, %d, %d\n", timestamp, pin, duration);
    fclose(log_file);
}

void sigint_handler(int signal) {
    gpioWrite(SOL1_PIN, PI_LOW);
    gpioWrite(SOL2_PIN, PI_LOW);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initialising pigpio\n");
        return 1;
    }
    gpioSetMode(SOL1_PIN, PI_OUTPUT);
    gpioSetMode(SOL2_PIN, PI_OUTPUT);
    signal(SIGINT, sigint_handler);
    dispense_loop();
    return 0;
}

