#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENA 24
#define ENB 25

#define KP 1.0
#define KI 0.01
#define KD 0.1

#define MIN_SPEED -255
#define MAX_SPEED 255

#define MIN_DISTANCE 20
#define MAX_DISTANCE 400

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    // Set GPIO values
    gpioWrite(ENA, 1);
    gpioWrite(ENB, 1);

    // Open log file
    FILE *log_file = fopen("balance_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency
    gpioPWM(MOTOR_A_FORWARD, 1000);
    gpioPWM(MOTOR_A_BACKWARD, 1000);
    gpioPWM(MOTOR_B_FORWARD, 1000);
    gpioPWM(MOTOR_B_BACKWARD, 1000);

    // Set PWM range
    gpioPWMRange(MOTOR_A_FORWARD, 255);
    gpioPWMRange(MOTOR_A_BACKWARD, 255);
    gpioPWMRange(MOTOR_B_FORWARD, 255);
    gpioPWMRange(MOTOR_B_BACKWARD, 255);

    // Set PWM duty cycle
    gpioPWM(MOTOR_A_FORWARD, 0);
    gpioPWM(MOTOR_A_BACKWARD, 0);
    gpioPWM(MOTOR_B_FORWARD, 0);
    gpioPWM(MOTOR_B_BACKWARD, 0);

    // Set PID parameters
    float Kp = 1.0;
    float Ki = 0.01;
    float Kd = 0.1;

    // Set PID error
    float error = 0.0;

    // Set PID output
    float output = 0.0;

    // Set motor speeds
    int motor_a_speed = 0;
    int motor_b_speed = 0;

    // Set distance
    float distance = 0.0;

    // Set tilt error
    float tilt_error = 0.0;

    // Set timestamp
    time_t timestamp;

    // Main loop
    while (1) {
        // Get timestamp
        timestamp = time(NULL);

        // Get tilt error
        tilt_error = (float)rand() / RAND_MAX * 20.0 - 10.0;

        // Get distance
        distance = (float)rand() / RAND_MAX * 400.0 + 2.0;

        // Calculate PID output
        output = Kp * tilt_error + Ki * error + Kd * (tilt_error - error);

        // Clamp output to +/-255
        if (output > 255) {
            output = 255;
        } else if (output < -255) {
            output = -255;
        }

        // Set motor speeds
        motor_a_speed = output;
        motor_b_speed = output;

        // Check for obstacle
        if (distance < MIN_DISTANCE) {
            // Reverse both motors at 50% speed
            motor_a_speed = -127;
            motor_b_speed = -127;
        }

        // Write motor speeds to log file
        fprintf(log_file, "%s, %f, %f, %d, %d\n", ctime(&timestamp), tilt_error, distance, motor_a_speed, motor_b_speed);

        // Set PID error
        error = tilt_error;

        // Set GPIO values
        gpioWrite(MOTOR_A_FORWARD, motor_a_speed > 0);
        gpioWrite(MOTOR_A_BACKWARD, motor_a_speed < 0);
        gpioWrite(MOTOR_B_FORWARD, motor_b_speed > 0);
        gpioWrite(MOTOR_B_BACKWARD, motor_b_speed < 0);

        // Set PWM duty cycle
        gpioPWM(MOTOR_A_FORWARD, abs(motor_a_speed));
        gpioPWM(MOTOR_A_BACKWARD, abs(motor_a_speed));
        gpioPWM(MOTOR_B_FORWARD, abs(motor_b_speed));
        gpioPWM(MOTOR_B_BACKWARD, abs(motor_b_speed));

        // Sleep for 50 ms
        usleep(50000);
    }

    // Clean up
    gpioTerminate();
    fclose(log_file);

    return 0;
}

