#define RELAY_GPIO 17
#define SENSOR_GPIO 4
#define DEBOUNCE_DELAY 50

static int gpio_relay = -1;
static int gpio_sensor = -1;

void sigint_handler(int signum) {
    printf("Received signal %d, terminating...\n", signum);
    gpioTerminate();
    exit(0);
}

int main(int argc, char **argv) {
    if (argc != 1) {
        printf("Usage: %s\n", argv[0]);
        return 1;
    }

    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    gpio_relay = gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    if (gpio_relay < 0) {
        printf("Failed to set GPIO %d as output\n", RELAY_GPIO);
        return 1;
    }

    gpio_sensor = gpioSetMode(SENSOR_GPIO, PI_INPUT);
    if (gpio_sensor < 0) {
        printf("Failed to set GPIO %d as input\n", SENSOR_GPIO);
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        int sensor_value = gpioRead(gpio_sensor);
        if (sensor_value < 0) {
            printf("Failed to read GPIO %d\n", SENSOR_GPIO);
            return 1;
        }

        if (sensor_value == 1) {
            gpioWrite(gpio_relay, 1);
            printf("Relay on\n");
            delay(DEBOUNCE_DELAY);
        } else {
            gpioWrite(gpio_relay, 0);
            printf("Relay off\n");
            delay(DEBOUNCE_DELAY);
        }
    }

    gpioTerminate();
    return 0;
}

