#define I2C_BUS 1
#define I2C_ADDR 0x29
#define REG_POWER_ON 0x80
#define REG_RGBC_ENABLE 0x03
#define REG_INTEGRATION_TIME 0x81
#define REG_DATA_START 0x14
#define REG_DATA_END 0x1A

#define CLEAR_LOW_BYTE 0x14
#define CLEAR_HIGH_BYTE 0x15
#define RED_LOW_BYTE 0x16
#define RED_HIGH_BYTE 0x17
#define GREEN_LOW_BYTE 0x18
#define GREEN_HIGH_BYTE 0x19
#define BLUE_LOW_BYTE 0x1A
#define BLUE_HIGH_BYTE 0x1B

#define INTEGRATION_TIME_MS 154
#define POLL_INTERVAL_MS 500

int main(void) {
    // Initialize pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus
    int i2c_handle = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Initialize sensor
    uint8_t power_on = REG_POWER_ON;
    uint8_t rgbc_enable = REG_RGBC_ENABLE;
    uint8_t integration_time = REG_INTEGRATION_TIME;
    if (pigpio_i2c_write(i2c_handle, &power_on, 1) < 0 ||
        pigpio_i2c_write(i2c_handle, &rgbc_enable, 1) < 0 ||
        pigpio_i2c_write(i2c_handle, &integration_time, 1) < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        return 1;
    }

    // Open file for logging
    FILE *fp = fopen("color_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for logging\n");
        return 1;
    }

    // Write header row
    fprintf(fp, "timestamp,clear,red,green,blue\n");

    // Main loop
    while (1) {
        // Read data from sensor
        uint8_t data[REG_DATA_END - REG_DATA_START + 1];
        if (pigpio_i2c_read(i2c_handle, REG_DATA_START, data, sizeof(data)) < 0) {
