#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define RELAY_COUNT 4
#define RELAY_PINS 11, 13, 15, 17
#define DAYTIME_DURATION 6
#define SUNRISE_DURATION 1
#define SUNSET_DURATION 1
#define NIGHTTIME_DURATION 14.4

static gpiod_chip_t *chip;
static gpiod_line_t *lines[RELAY_COUNT];

static void init_relays(void) {
    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(1);
    }

    // Get the GPIO lines for the relays
    for (int i = 0; i < RELAY_COUNT; i++) {
        lines[i] = gpiod_line_get(chip, RELAY_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line for relay %d\n", i);
            exit(1);
        }
    }

    // Request the GPIO lines for output
    for (int i = 0; i < RELAY_COUNT; i++) {
        if (gpiod_line_request_output(lines[i], "relay", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line for relay %d\n", i);
            exit(1);
        }
    }
}

static void set_relay_state(int relay, int state) {
    gpiod_line_set_value(lines[relay], state);
}

static void cleanup(void) {
    // Release the GPIO lines
    for (int i = 0; i < RELAY_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);
}

static void handle_sigint(int signal) {
    // Turn off all relays
    for (int i = 0; i < RELAY_COUNT; i++) {
        set_relay_state(i, 0);
    }

    // Release GPIO resources
    cleanup();

    // Exit the program
    exit(0);
}

int main(void) {
    // Initialize the relays
    init_relays();

    // Set up signal handling
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Set the initial state of the relays
    for (int i = 0; i < RELAY_COUNT; i++) {
        set_relay_state(i, 0);
    }

    // Cycle through the four phases
    while (1) {
        // Sunrise phase
        for (int i = 0; i < SUNRISE_DURATION * 60; i++) {
            for (int j = 0; j < RELAY_COUNT; j++) {
                set_relay_state(j, i % 2);
            }
            sleep(1);
        }

        // Daytime phase
        for (int i = 0; i < DAYTIME_DURATION * 60; i++) {
            for (int j = 0; j < RELAY_COUNT; j++) {
                set_relay_state(j, 1);
            }
            sleep(1);
        }

        // Sunset phase
        for (int i = 0; i < SUNSET_DURATION * 60; i++) {
            for (int j = 0; j < RELAY_COUNT; j++) {
                set_relay_state(j, i % 2);
            }
            sleep(1);
        }

        // Nighttime phase
        for (int i = 0; i < NIGHTTIME_DURATION * 60; i++) {
            for (int j = 0; j < RELAY_COUNT; j++) {
                set_relay_state(j, 0);
            }
            sleep(1);
        }
    }

    return 0;
}

