    // Initialize pigpio
    gpio_handle = pigpio_start(NULL, NULL);
    if (gpio_handle < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO pin
    if (pigpio_gpio_mode_set(gpio_handle, GPIO_PIN, PI_INPUT) < 0) {
        printf("Failed to set GPIO pin mode\n");
        return 1;
    }
    if (pigpio_gpio_pull_up_down(gpio_handle, GPIO_PIN, PI_PUD_DOWN) < 0) {
        printf("Failed to set GPIO pull-up/pull-down\n");
        return 1;
    }

    // Set up video file
    video_fd = open("/home/pi/videos/", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (video_fd < 0) {
        printf("Failed to open video file\n");
        return 1;
    }

    // Set up log file
    log_fd = open("/home/pi/logs/motion_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
