#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define GYRO_REG_WHO_AM_I 0x75
#define GYRO_REG_SMPLRT_DIV 0x19
#define GYRO_REG_CONFIG 0x1B
#define GYRO_REG_GYRO_XOUT_H 0x43
#define GYRO_REG_GYRO_XOUT_L 0x44
#define GYRO_REG_GYRO_YOUT_H 0x45
#define GYRO_REG_GYRO_YOUT_L 0x46
#define GYRO_REG_GYRO_ZOUT_H 0x47
#define GYRO_REG_GYRO_ZOUT_L 0x48

#define GYRO_SENSITIVITY 131.0
#define GYRO_RANGE 250.0

#define SAMPLE_RATE 100.0
#define SAMPLE_INTERVAL 10.0

#define MAX_REINIT_ATTEMPTS 3

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Initialize gyroscope
    uint8_t who_am_i = 0;
    if (i2cReadByteData(i2c_handle, GYRO_REG_WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return 1;
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "Invalid WHO_AM_I register value: 0x%02X\n", who_am_i);
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, GYRO_REG_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Failed to set sample rate divider\n");
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, GYRO_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set gyroscope full-scale range\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up SIGINT/SIGTERM handler
    struct sigaction sigint_action;
    sigint_action.sa_handler = sigint_handler;
    sigint_action.sa_flags = 0;
    sigemptyset(&sigint_action.sa_mask);
    sigaction(SIGINT, &sigint_action, NULL);

    // Main loop
    while (1) {
        // Read gyroscope data
        int16_t x_gyro = 0;
        int16_t y_gyro = 0;
        int16_t z_gyro = 0;
        if (i2cReadI2CBlockData(i2c_handle, GYRO_REG_GYRO_XOUT_H, 6, (uint8_t *)&x_gyro, (uint8_t *)&y_gyro, (uint8_t *)&z_gyro) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            return 1;
        }

        // Convert to degrees per second
        double x_degps = (double)x_gyro / GYRO_SENSITIVITY;
        double y_degps = (double)y_gyro / GYRO_SENSITIVITY;
        double z_degps = (double)z_gyro / GYRO_SENSITIVITY;

        // Log data
        time_t timestamp = time(NULL);
        fprintf(log_file, "%ld,%.2f,%.2f,%.2f\n", timestamp, x_degps, y_degps, z_degps);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Close log file
    fclose(log_file);

    // Release I2C handle
    i2cClose(i2c_handle);

    // Release pigpio
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum) {
    // Close log file
    fclose(log_file);

    // Release I2C handle
    i2cClose(i2c_handle);

    // Release pigpio
    gpioTerminate();

    exit(0);
}

