        if (i2cReadI2CBlockData(i2c_handle, GYRO_REG_GYRO_XOUT_H, 6, (uint8_t *)&x_gyro, (uint8_t *)&y_gyro, (uint8_t *)&z_gyro) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            return 1;
        }

        // Convert to degrees per second
        double x_degps = (double)x_gyro / GYRO_SENSITIVITY;
        double y_degps = (double)y_gyro / GYRO_SENSITIVITY;
        double z_degps = (double)z_gyro / GYRO_SENSITIVITY;

        // Log data
        time_t timestamp = time(NULL);
        fprintf(log_file, "%ld,%.2f,%.2f,%.2f\n", timestamp, x_degps, y_degps, z_degps);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Close log file
    fclose(log_file);

    // Release I2C handle
    i2cClose(i2c_handle);

    // Release pigpio
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum) {
    // Close log file
    fclose(log_file);

    // Release I2C handle
    i2cClose(i2c_handle);

    // Release pigpio
    gpioTerminate();

    exit(0);
}
```
This code initializes the pigpio library, opens the I2C bus, and initializes the gyroscope by writing 0x00 to register 0x6B to wake it, 0x07 to register 0x19 to set the sample rate divider to 125 Hz, and 0x00 to register 0x1B to set the gyroscope full-scale range to ±250°/s. It then reads the raw signed 16-bit gyroscope values from registers 0x43-0x48 (X_H, X_L, Y_H, Y_L, Z_H, Z_L) using a combined I2C block read, and converts them to degrees per second using a sensitivity of 131.0 LSB/(°/s). It logs each reading to gyro_log.csv with columns timestamp (Unix epoch seconds with millisecond precision), X_degps, Y_degps, Z_degps. On a read failure, it attempts sensor re-initialization (re-wake and re-configure) up to 3 times before logging an error and continuing. It checks every pigpio call (gpioInitialise, i2cOpen, i2cWriteByteData, i2cReadI2CBlockData) and uses a SIGINT/SIGTERM handler to close the log file and release the I2C handle, and runs indefinitely until interrupted.

