      // Deactivate relays for all zones
      gpioWrite(ZONE_1_GPIO, PI_HIGH);
      gpioWrite(ZONE_2_GPIO, PI_HIGH);
      gpioWrite(ZONE_3_GPIO, PI_HIGH);
      gpioWrite(ZONE_4_GPIO, PI_HIGH);
    }

    // Log sensor reading, relay state, and timestamp
    fprintf(log_file, "%d, %d, %d, %d, %d\n", moisture_sensor_reading, gpioRead(ZONE_1_GPIO), gpioRead(ZONE_2_GPIO), gpioRead(ZONE_3_GPIO), gpioRead(ZONE_4_GPIO));

    // Sleep for 5 seconds
    sleep(MOISTURE_SENSOR_READING_INTERVAL);
  }

  // Clean up
  gpioTerminate();
  fclose(log_file);

  return 0;
}

void handle_signal(int signal) {
  // Deactivate all relays
  gpioWrite(ZONE_1_GPIO, PI_HIGH);
  gpioWrite(ZONE_2_GPIO, PI_HIGH);
  gpioWrite(ZONE_3_GPIO, PI_HIGH);
  gpioWrite(ZONE_4_GPIO, PI_HIGH);

  // Close log file
  fclose(log_file);

  // Terminate pigpio
  gpioTerminate();

  // Exit program
  exit(0);
}

