#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <i2c.h>

#define I2C_ADDR 0x53
#define DATA_FORMAT 0x31
#define POWER_CTL 0x2D
#define DATAX0 0x32
#define FREEFALL_THRESHOLD 0.2
#define FREEFALL_DURATION 0.5
#define GPIO_PIN 27

int main(void) {
    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Initialize I2C
    int i2c_handle = i2c_open(I2C_ADDR, 0, 0, 0, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return 1;
    }

    // Configure sensor for ±2g range with full resolution
    uint8_t data_format = 0x0B;
    if (i2c_write(i2c_handle, DATA_FORMAT, &data_format, 1) < 0) {
        fprintf(stderr, "Failed to write to DATA_FORMAT register\n");
        return 1;
    }

    // Enable measurement mode
    uint8_t power_ctl = 0x08;
    if (i2c_write(i2c_handle, POWER_CTL, &power_ctl, 1) < 0) {
        fprintf(stderr, "Failed to write to POWER_CTL register\n");
        return 1;
    }

    // Set up GPIO pin for alarm
    if (gpio_mode_output(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to set GPIO pin as output\n");
        return 1;
    }

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read accelerometer data
        uint8_t data[6];
        if (i2c_read(i2c_handle, DATAX0, data, 6) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        // Convert raw data to g-force
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];
        double x_g = x / 256.0;
        double y_g = y / 256.0;
        double z_g = z / 256.0;

        // Check for freefall event
        if (x_g < FREEFALL_THRESHOLD && y_g < FREEFALL_THRESHOLD && z_g < FREEFALL_THRESHOLD) {
            // Set alarm
            gpio_write(GPIO_PIN, 1);

            // Wait for confirmation
            sleep(FREEFALL_DURATION);

            // Check again
            if (x_g < FREEFALL_THRESHOLD && y_g < FREEFALL_THRESHOLD && z_g < FREEFALL_THRESHOLD) {
                // Log event
                time_t t = time(NULL);
                struct tm *tm = localtime(&t);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
                fprintf(stderr, "%s, %f, %f, %f\n", timestamp, x_g, y_g, z_g);

                // Set alarm off
                gpio_write(GPIO_PIN, 0);
            }
        }

        // Wait for next iteration
        sleep(0.1);
    }

    // Clean up
    i2c_close(i2c_handle);
    pigpio_stop();

    return 0;
}

void sigint_handler(int signum) {
    // Close I2C handle
    i2c_close(i2c_handle);

    // Set GPIO low
    gpio_write(GPIO_PIN, 0);

    // Terminate pigpio
    pigpio_stop();

    // Exit program
    exit(0);
}

