#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <i2c.h>

#define LIS3DH_ADDR 0x18
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG4 0x23
#define LIS3DH_OUT_X_L 0x28
#define LIS3DH_SENSITIVITY 16384

#define BUZZER_PIN 17
#define FREEFALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 1.5

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }
}

static void init_i2c() {
    if (i2cOpen(1, 0x18, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        exit(1);
    }
}

static void configure_lis3dh() {
    uint8_t ctrl_reg1 = 0x77;
    uint8_t ctrl_reg4 = 0x00;
    if (i2cWrite(LIS3DH_ADDR, LIS3DH_CTRL_REG1, &ctrl_reg1, 1) < 0) {
        fprintf(stderr, "Failed to write to LIS3DH CTRL_REG1\n");
        exit(1);
    }
    if (i2cWrite(LIS3DH_ADDR, LIS3DH_CTRL_REG4, &ctrl_reg4, 1) < 0) {
        fprintf(stderr, "Failed to write to LIS3DH CTRL_REG4\n");
        exit(1);
    }
}

static void read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2cRead(LIS3DH_ADDR, LIS3DH_OUT_X_L, buf, 6) < 0) {
        fprintf(stderr, "Failed to read from LIS3DH\n");
        exit(1);
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
}

static void detect_freefall(int16_t x, int16_t y, int16_t z) {
    double magnitude = sqrt(x * x + y * y + z * z);
    if (magnitude < FREEFALL_THRESHOLD) {
        printf("Freefall detected\n");
    }
}

static void detect_impact(int16_t x, int16_t y, int16_t z) {
    double magnitude = sqrt(x * x + y * y + z * z);
    if (magnitude > IMPACT_THRESHOLD) {
        printf("Impact detected\n");
    }
}

static void activate_buzzer() {
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, PI_HIGH);
    sleep(1);
    gpioWrite(BUZZER_PIN, PI_LOW);
}

int main(int argc, char *argv[]) {
    init_pigpio();
    init_i2c();
    configure_lis3dh();

    signal(SIGINT, sigint_handler);

    while (running) {
        int16_t x, y, z;
        read_acceleration(&x, &y, &z);
        detect_freefall(x, y, z);
        detect_impact(x, y, z);
        if (detect_impact(x, y, z)) {
            activate_buzzer();
        }
        sleep(100);
    }

    gpioTerminate();
    i2cClose(1);
    return 0;
}

