        gpioWrite(Y_STEP_PIN, PI_HIGH);
        gpioDelay(STEP_DELAY);
        gpioWrite(Y_STEP_PIN, PI_LOW);
        gpioDelay(STEP_DELAY);
    }

    // Disable motors
    gpioWrite(X_ENABLE_PIN, PI_LOW);
    gpioWrite(Y_ENABLE_PIN, PI_LOW);

    // Release resources
    gpioTerminate();

    return 0;
}

void sigint_handler(int signum) {
    // Disable motors
    gpioWrite(X_ENABLE_PIN, PI_LOW);
    gpioWrite(Y_ENABLE_PIN, PI_LOW);

