#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define LIS3DH_I2C_ADDR 0x18
#define LIS3DH_CTRL_REG1 0x20
#define LIS3DH_CTRL_REG4 0x23
#define LIS3DH_OUT_X_L 0x28
#define LIS3DH_OUT_X_H 0x29
#define LIS3DH_OUT_Y_L 0x2A
#define LIS3DH_OUT_Y_H 0x2B
#define LIS3DH_OUT_Z_L 0x2C
#define LIS3DH_OUT_Z_H 0x2D

#define G_PER_LSB 0.0009765625
#define THRESHOLD_G 2.0

static volatile bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void configure_sensor(int i2c_fd) {
    uint8_t ctrl_reg1 = 0x57;
    uint8_t ctrl_reg4 = 0x88;

    if (i2cWriteByteData(i2c_fd, LIS3DH_CTRL_REG1, ctrl_reg1) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        exit(1);
    }

    if (i2cWriteByteData(i2c_fd, LIS3DH_CTRL_REG4, ctrl_reg4) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        exit(1);
    }
}

static void read_sensor(int i2c_fd, float *x, float *y, float *z) {
    uint8_t data[6];

    if (i2cReadI2CBlockData(i2c_fd, LIS3DH_OUT_X_L, data, 6) < 0) {
        fprintf(stderr, "Error reading from sensor\n");
        *x = *y = *z = 0;
        return;
    }

    *x = (int16_t)((data[0] << 8) | data[1]) >> 4;
    *y = (int16_t)((data[2] << 8) | data[3]) >> 4;
    *z = (int16_t)((data[4] << 8) | data[5]) >> 4;
}

static void log_event(float x, float y, float z) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);

    char buf[100];
    strftime(buf, sizeof(buf), "%F %T", tm);

    FILE *fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    fprintf(fp, "%s: X=%f, Y=%f, Z=%f\n", buf, x, y, z);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int i2c_fd;
    float x, y, z;

    if (argc > 1 && strcmp(argv[1], "-a") == 0) {
        if (argc < 3) {
            fprintf(stderr, "Missing I2C address\n");
            exit(1);
        }

        char *endptr;
        long addr = strtol(argv[2], &endptr, 16);
        if (*endptr != '\0' || addr < 0x08 || addr > 0x77) {
            fprintf(stderr, "Invalid I2C address\n");
            exit(1);
        }

        LIS3DH_I2C_ADDR = addr;
    }

    if (argc > 1 && strcmp(argv[1], "-t") == 0) {
        if (argc < 3) {
            fprintf(stderr, "Missing threshold\n");
            exit(1);
        }

        char *endptr;
        float threshold = strtof(argv[2], &endptr);
        if (*endptr != '\0' || threshold <= 0) {
            fprintf(stderr, "Invalid threshold\n");
            exit(1);
        }

        THRESHOLD_G = threshold;
    }

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Error setting SIGINT handler\n");
        exit(1);
    }

    if ((i2c_fd = i2cOpen(1, LIS3DH_I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        exit(1);
    }

    configure_sensor(i2c_fd);

    while (running) {
        read_sensor(i2c_fd, &x, &y, &z);

        if (x*G_PER_LSB > THRESHOLD_G || y*G_PER_LSB > THRESHOLD_G || z*G_PER_LSB > THRESHOLD_G) {
            log_event(x, y, z);
            system("sudo shutdown -h now");
            break;
        }

        sleep(100);
    }

    i2cClose(i2c_fd);

    return 0;
}

