#define I2C_BUS 1
#define I2C_ADDR 0x30
#define RELAY_GPIO 17
#define THRESHOLD 500
#define SAMPLE_PERIOD 100

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up relay
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, PI_LOW);

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read magnetic field data
        uint8_t msb, lsb;
        if (i2cReadByteData(i2c_handle, 0xC0, &msb) < 0 || i2cReadByteData(i2c_handle, 0xC1, &lsb) < 0) {
            fprintf(stderr, "Failed to read magnetic field data\n");
            gpioWrite(RELAY_GPIO, PI_LOW);
            continue;
        }

        // Convert to milliTesla units
        int16_t field_raw = (msb << 8) | lsb;
        int field_mT_x100 = field_raw * 25 / 1000;

        // Check threshold
        if (field_mT_x100 > THRESHOLD) {
            // Activate relay
            gpioWrite(RELAY_GPIO, PI_HIGH);

            // Log event
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
            fprintf(stderr, "%s: Magnetic field exceeded threshold (%d mT)\n", timestamp, field_mT_x100 / 100);
        } else {
            // Deactivate relay
            gpioWrite(RELAY_GPIO, PI_LOW);
        }

        // Wait for next sample
        usleep(SAMPLE_PERIOD * 1000);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

