    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO pin mode\n");
        exit(1);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(1);
    }

    // Create socket
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        fprintf(stderr, "Failed to create socket\n");
        exit(1);
    }

    // Set up socket address
    portno = 5000;
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(portno);

    // Bind socket
    if (bind(sock, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
        fprintf(stderr, "Failed to bind socket\n");
        exit(1);
    }

    // Listen for incoming connections
    if (listen(sock, 3) < 0) {
        fprintf(stderr, "Failed to listen for incoming connections\n");
        exit(1);
    }

    // Accept incoming connections
    clilen = sizeof(cli_addr);
    new_sock = accept(sock, (struct sockaddr *) &cli_addr, &clilen);
    if (new_sock < 0) {
        fprintf(stderr, "Failed to accept incoming connection\n");
        exit(1);
    }

    // Read command from client
    if (read(new_sock, buffer, BUF_SIZE) < 0) {
        fprintf(stderr, "Failed to read command from client\n");
        exit(1);
    }

    // Check command
    if (strcmp(buffer, "ON") == 0) {
        // Turn on relay
        gpioWrite(RELAY_GPIO, 1);
        fprintf(log_file, "Relay turned on at %s\n", ctime(&time(NULL)));
    } else if (strcmp(buffer, "OFF") == 0) {
        // Turn off relay
        gpioWrite(RELAY_GPIO, 0);
        fprintf(log_file, "Relay turned off at %s\n", ctime(&time(NULL)));
    } else {
        // Invalid command
        fprintf(log_file, "Invalid command received at %s\n", ctime(&time(NULL)));
    }

    // Close socket
    close(new_sock);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

