#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define SENSOR_START_MEASUREMENT 0x36
#define SENSOR_READ_CMD 0x08
#define SENSOR_READ_LEN 3
#define SENSOR_CRC_POLY 0x31
#define SENSOR_CRC_INIT 0xFF
#define SENSOR_CRC_XOR 0x00
#define SENSOR_SCALE_FACTOR 1500.0
#define RELAY_GPIO 18
#define RELAY_ACTIVE_HIGH

volatile sig_atomic_t running = true;

void sigint_handler(int signum) {
    running = false;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C handles
    int i2c1 = i2cOpen(1, 0, 0);
    if (i2c1 < 0) {
        fprintf(stderr, "Failed to open I2C handle 1\n");
        return 1;
    }
    int i2c2 = i2cOpen(1, 0, 0);
    if (i2c2 < 0) {
        fprintf(stderr, "Failed to open I2C handle 2\n");
        return 1;
    }

    // Set up GPIO 18 as an output
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 18 as an output\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (running) {
        // Read from both sensors
        uint8_t data1[SENSOR_READ_LEN];
        uint8_t data2[SENSOR_READ_LEN];
        if (i2cReadDevice(i2c1, SENSOR1_ADDR, SENSOR_READ_CMD, data1, SENSOR_READ_LEN) < 0) {
            fprintf(stderr, "Failed to read from sensor 1\n");
            continue;
        }
        if (i2cReadDevice(i2c2, SENSOR2_ADDR, SENSOR_READ_CMD, data2, SENSOR_READ_LEN) < 0) {
            fprintf(stderr, "Failed to read from sensor 2\n");
            continue;
        }

        // Validate CRC-8
        if (crc8(data1, SENSOR_READ_LEN - 1, SENSOR_CRC_POLY, SENSOR_CRC_INIT, SENSOR_CRC_XOR) != data1[SENSOR_READ_LEN - 1]) {
            fprintf(stderr, "CRC-8 mismatch for sensor 1\n");
            continue;
        }
        if (crc8(data2, SENSOR_READ_LEN - 1, SENSOR_CRC_POLY, SENSOR_CRC_INIT, SENSOR_CRC_XOR) != data2[SENSOR_READ_LEN - 1]) {
            fprintf(stderr, "CRC-8 mismatch for sensor 2\n");
            continue;
        }

        // Convert raw values to ml/min
        int16_t flow1 = (int16_t)((data1[0] << 8) | data1[1]);
        int16_t flow2 = (int16_t)((data2[0] << 8) | data2[1]);
        float flow_rate1 = flow1 / SENSOR_SCALE_FACTOR;
        float flow_rate2 = flow2 / SENSOR_SCALE_FACTOR;

        // Log flow rates
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(stderr, "%s: flow rate 1: %f ml/min, flow rate 2: %f ml/min\n", timestamp, flow_rate1, flow_rate2);

        // Control relay
        if (flow_rate1 < 5.0 || flow_rate2 < 5.0) {
            gpioWrite(RELAY_GPIO, 1);
        } else {
            gpioWrite(RELAY_GPIO, 0);
        }
    }

    // Clean up
    gpioWrite(RELAY_GPIO, 0);
    if (i2c1 >= 0) {
        i2cClose(i2c1);
    }
    if (i2c2 >= 0) {
        i2cClose(i2c2);
    }
    gpioTerminate();
    fprintf(stderr, "Shutting down\n");

    return 0;
}

