#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

#define MOTOR_RUN_TIME 5
#define MOTOR_STOP_TIME 5

#define SENSOR_DRY_THRESHOLD 3

int main(void) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio library");
        exit(1);
    }

    // Set up rain sensor pin as input with pull-up
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin as input");
        exit(1);
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin pull-up");
        exit(1);
    }

    // Set up motor pins as output
    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor ENA pin as output");
        exit(1);
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor IN1 pin as output");
        exit(1);
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor IN2 pin as output");
        exit(1);
    }

    // Initialize sensor and motor state variables
    int sensor_state = 0;
    int motor_state = 0;
    int dry_count = 0;

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Main loop
    while (1) {
        // Read rain sensor state
        if (gpioRead(RAIN_SENSOR_PIN) < 0) {
            syslog(LOG_ERR, "Failed to read rain sensor state");
            exit(1);
        }
        int new_sensor_state = gpioRead(RAIN_SENSOR_PIN);

        // Check for rising-edge dry-to-wet transition
        if (new_sensor_state == 1 && sensor_state == 0) {
            // Start motor
            if (gpioWrite(MOTOR_ENA_PIN, 1) < 0) {
                syslog(LOG_ERR, "Failed to start motor");
                exit(1);
            }
            if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
                syslog(LOG_ERR, "Failed to set motor IN1 pin high");
                exit(1);
            }
            if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
                syslog(LOG_ERR, "Failed to set motor IN2 pin low");
                exit(1);
            }
            // Hold motor for 5 seconds
            gpioDelay(MOTOR_RUN_TIME * 1000);
            // Stop motor
            if (gpioWrite(MOTOR_ENA_PIN, 0) < 0) {
                syslog(LOG_ERR, "Failed to stop motor");
                exit(1);
            }
            if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
                syslog(LOG_ERR, "Failed to set motor IN1 pin low");
                exit(1);
            }
            if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
                syslog(LOG_ERR, "Failed to set motor IN2 pin low");
                exit(1);
            }
            // Increment dry count
            dry_count++;
        }

        // Check for dry state
        if (new_sensor_state == 0) {
            // Reset dry count
            dry_count = 0;
        }

        // Check for dry state for at least 3 consecutive polls
        if (dry_count >= SENSOR_DRY_THRESHOLD) {
            // Reset dry count
            dry_count = 0;
        }

        // Update sensor state
        sensor_state = new_sensor_state;

        // Sleep for 200 ms
        gpioDelay(200 * 1000);
    }

    // Clean up
    gpioTerminate();
    close(syslog);
    exit(0);
}

void handle_sigint(int signal) {
    // Stop motor
    if (gpioWrite(MOTOR_ENA_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to stop motor");
        exit(1);
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set motor IN1 pin low");
        exit(1);
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set motor IN2 pin low");
        exit(1);
    }
    // Clean up
    gpioTerminate();
    close(syslog);
    exit(0);
}

void handle_sigterm(int signal) {
    // Stop motor
    if (gpioWrite(MOTOR_ENA_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to stop motor");
        exit(1);
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set motor IN1 pin low");
        exit(1);
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set motor IN2 pin low");
        exit(1);
    }
    // Clean up
    gpioTerminate();
    close(syslog);
    exit(0);
}

