#define LOG_INTERVAL 100

static bool running = true;

void sigint_handler(int signum) {
    running = false;
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set PIR pin as input
    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set PIR pin as input\n");
        return 1;
    }

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin as output\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set SIGINT/SIGTERM handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (running) {
        // Read PIR pin
        int pir_value = gpioRead(PIR_PIN);
        if (pir_value < 0) {
            fprintf(stderr, "Failed to read PIR pin\n");
            return 1;
        }

        // If motion detected, turn on LED
        if (pir_value == 1) {
            if (gpioWrite(LED_PIN, 1) < 0) {
                fprintf(stderr, "Failed to turn on LED\n");
                return 1;
            }

            // Log activation event
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
            fprintf(log_file, "%s: Activated\n", timestamp);

            // Wait for 60 seconds
            for (int i = 0; i < 600; i++) {
                if (!running) {
                    break;
                }
                usleep(100000);
            }

            // Turn off LED
            if (gpioWrite(LED_PIN, 0) < 0) {
                fprintf(stderr, "Failed to turn off LED\n");
                return 1;
            }

            // Log deactivation event
            now = time(NULL);
            tm = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
            fprintf(log_file, "%s: Deactivated (%d seconds)\n", timestamp, i);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close log file
    fclose(log_file);

    // Release pigpio resources
    gpioTerminate();

    return 0;
}

