#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define RELAY_GPIO 17
#define ELECTRODE_0 0
#define DEBOUNCE_MS 200

static bool relay_state = false;

static void sigint_handler(int signum) {
    printf("Received signal %d, shutting down...\n", signum);
    gpioTerminate();
    exit(0);
}

static void init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }
}

static void init_i2c() {
    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
        exit(1);
    }
}

static void init_relay() {
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        exit(1);
    }
    gpioWrite(RELAY_GPIO, PI_OFF);
}

static void init_mpr121() {
    uint8_t data[2] = {0x5A, 0x00};
    if (i2cWrite(I2C_BUS, I2C_ADDR, data, 2) < 0) {
        fprintf(stderr, "Failed to write to MPR121\n");
        exit(1);
    }
    data[0] = 0x5B;
    data[1] = 0x00;
    if (i2cWrite(I2C_BUS, I2C_ADDR, data, 2) < 0) {
        fprintf(stderr, "Failed to write to MPR121\n");
        exit(1);
    }
    data[0] = 0x2C;
    data[1] = 0x00;
    if (i2cWrite(I2C_BUS, I2C_ADDR, data, 2) < 0) {
        fprintf(stderr, "Failed to write to MPR121\n");
        exit(1);
    }
    data[0] = 0x7B;
    data[1] = 0x00;
    if (i2cWrite(I2C_BUS, I2C_ADDR, data, 2) < 0) {
        fprintf(stderr, "Failed to write to MPR121\n");
        exit(1);
    }
    data[0] = 0x7C;
    data[1] = 0x00;
    if (i2cWrite(I2C_BUS, I2C_ADDR, data, 2) < 0) {
        fprintf(stderr, "Failed to write to MPR121\n");
        exit(1);
    }
    data[0] = 0x7D;
    data[1] = 0x00;
    if (i2cWrite(I2C_BUS, I2C_ADDR, data, 2) < 0) {
        fprintf(stderr, "Failed to write to MPR121\n");
        exit(1);
    }
    data[0] = 0x5E;
    data[1] = 0x0C;
    if (i2cWrite(I2C_BUS, I2C_ADDR, data, 2) < 0) {
        fprintf(stderr, "Failed to write to MPR121\n");
        exit(1);
    }
}

static void read_touch_status() {
    uint8_t data[2] = {0x00, 0x00};
    if (i2cRead(I2C_BUS, I2C_ADDR, data, 2) < 0) {
        fprintf(stderr, "Failed to read from MPR121\n");
        exit(1);
    }
    uint16_t touch_status = (data[0] << 8) | data[1];
    if (touch_status & (1 << ELECTRODE_0)) {
        if (!relay_state) {
            gpioWrite(RELAY_GPIO, PI_ON);
            relay_state = true;
        }
    } else {
        if (relay_state) {
            gpioWrite(RELAY_GPIO, PI_OFF);
            relay_state = false;
        }
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    init_pigpio();
    init_i2c();
    init_relay();
    init_mpr121();

    while (true) {
        read_touch_status();
        usleep(10000);
    }

    return 0;
}

