#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <gpiod.h>
#include <pthread.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PWM_FREQ 50
#define PWM_PERIOD 20000
#define PWM_DUTY_CYCLE 1500

#define BUF_SIZE 1024

static gpiod_chip_t *chip;
static gpiod_line_t *servo_line, *pir_line;
static pthread_t pwm_thread;
static int pwm_running = 0;

static void *pwm_thread_func(void *arg) {
    while (pwm_running) {
        gpiod_line_set_value(servo_line, 1);
        usleep(PWM_DUTY_CYCLE);
        gpiod_line_set_value(servo_line, 0);
        usleep(PWM_PERIOD - PWM_DUTY_CYCLE);
    }
    return NULL;
}

static void handle_sigint(int sig) {
    pwm_running = 0;
    pthread_join(pwm_thread, NULL);
    gpiod_line_release(servo_line);
    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    closelog();
    exit(0);
}

static void handle_sigterm(int sig) {
    pwm_running = 0;
    pthread_join(pwm_thread, NULL);
    gpiod_line_release(servo_line);
    gpiod_line_release(pir_line);
    gpiod_chip_close(chip);
    closelog();
    exit(0);
}

int main(int argc, char *argv[]) {
    int sockfd, new_fd;
    struct sockaddr_in serv_addr, cli_addr;
    socklen_t clilen;
    char buffer[BUF_SIZE];

    // Initialize GPIO
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_USER, "Failed to open GPIO chip");
        exit(1);
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);

    if (!servo_line || !pir_line) {
