#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <bh1750.h>

#define I2C_ADDR 0x23
#define I2C_BUS 1
#define RELAY_PIN 23
#define LUX_THRESHOLD 150
#define SAMPLE_INTERVAL 2000

int main(void) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus
    int i2c_handle = i2cOpen(I2C_BUS, 0, 0, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("grow_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up relay
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, PI_LOW);

    // Main loop
    while (1) {
        // Read lux value
        uint16_t lux = read_lux(i2c_handle);
        if (lux < 0) {
            fprintf(stderr, "Failed to read lux value\n");
            continue;
        }

        // Log lux value
        fprintf(log_file, "%ld, %d\n", time(NULL), lux);

        // Activate relay if lux is below threshold
        if (lux < LUX_THRESHOLD) {
            gpioWrite(RELAY_PIN, PI_HIGH);
        } else {
            gpioWrite(RELAY_PIN, PI_LOW);
        }

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Read lux value from BH1750 sensor
int read_lux(int i2c_handle) {
    // Send command to start one-time high-resolution mode
    if (i2cWriteByte(i2c_handle, I2C_ADDR, 0x20) < 0) {
        fprintf(stderr, "Failed to send command to start one-time high-resolution mode\n");
        return -1;
    }

    // Wait for conversion
    usleep(120 * 1000);

    // Read 2-byte result
    uint8_t result[2];
    if (i2cReadDevice(i2c_handle, I2C_ADDR, result, 2) < 0) {
        fprintf(stderr, "Failed to read 2-byte result\n");
        return -1;
    }

    // Convert to lux
    uint16_t lux = (result[0] << 8) | result[1];
    lux = lux / 1.2;

    return lux;
}

// Signal handler
void signal_handler(int signal) {
    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    // Exit
    exit(0);
}

