#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define DOUT_PIN 23
#define SCK_PIN 24
#define LOCK_PIN 25

#define THRESHOLD 1000
#define SCALE 1000
#define DURATION 200

#define TARE_SAMPLES 10
#define MEASURE_SAMPLES 5

#define BIT_DELAY 10000

#define LOG_INFO(fmt, ...) syslog(LOG_INFO, fmt, ##__VA_ARGS__)
#define LOG_ERROR(fmt, ...) syslog(LOG_ERR, fmt, ##__VA_ARGS__)

static volatile sig_atomic_t running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static void sigterm_handler(int signum) {
    running = 0;
}

static void setup_signals() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGTERM, &sa, NULL);
}

static void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *dout_line, *sck_line, *lock_line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        LOG_ERROR("Failed to open GPIO chip");
        exit(1);
    }

    dout_line = gpiod_chip_get_line(chip, DOUT_PIN);
    sck_line = gpiod_chip_get_line(chip, SCK_PIN);
    lock_line = gpiod_chip_get_line(chip, LOCK_PIN);

    if (!dout_line || !sck_line || !lock_line) {
        LOG_ERROR("Failed to get GPIO lines");
        exit(1);
    }

    gpiod_line_request_output(dout_line, "dout", 0);
    gpiod_line_request_output(sck_line, "sck", 0);
    gpiod_line_request_output(lock_line, "lock", 0);

    gpiod_line_set_value(dout_line, 0);
    gpiod_line_set_value(sck_line, 0);
    gpiod_line_set_value(lock_line, 0);
}

static void tare_sensor() {
    struct gpiod_chip *chip;
    struct gpiod_line *dout_line, *sck_line;
    int i, j;
    uint32_t raw_reading;
    int32_t tare_offset;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        LOG_ERROR("Failed to open GPIO chip");
        exit(1);
    }

    dout_line = gpiod_chip_get_line(chip, DOUT_PIN);
    sck_line = gpiod_chip_get_line(chip, SCK_PIN);

    if (!dout_line || !sck_line) {
        LOG_ERROR("Failed to get GPIO lines");
        exit(1);
    }

    tare_offset = 0;
    for (i = 0; i < TARE_SAMPLES; i++) {
        gpiod_line_set_value(dout_line, 0);
        gpiod_line_set_value(sck_line, 0);

        for (j = 0; j < 24; j++) {
            gpiod_line_set_value(sck_line, 1);
            gpiod_line_set_value(sck_line, 0);
        }

        gpiod_line_set_value(sck_line, 1);
        gpiod_line_set_value(sck_line, 0);

        raw_reading = gpiod_line_get_value(dout_line);
        tare_offset += raw_reading;
    }

    tare_offset /= TARE_SAMPLES;
    LOG_INFO("Tare offset: %d", tare_offset);
}

static int32_t read_weight() {
    struct gpiod_chip *chip;
    struct gpiod_line *dout_line, *sck_line;
    int i, j;
    uint32_t raw_reading;
    int32_t weight;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        LOG_ERROR("Failed to open GPIO chip");
        exit(1);
    }

    dout_line = gpiod_chip_get_line(chip, DOUT_PIN);
    sck_line = gpiod_chip_get_line(chip, SCK_PIN);

    if (!dout_line || !sck_line) {
        LOG_ERROR("Failed to get GPIO lines");
        exit(1);
    }

    gpiod_line_set_value(dout_line, 0);
    gpiod_line_set_value(sck_line, 0);

    for (i = 0; i < MEASURE_SAMPLES; i++) {
        gpiod_line_set_value(dout_line, 0);
        gpiod_line_set_value(sck_line, 0);

        for (j = 0; j < 24; j++) {
            gpiod_line_set_value(sck_line, 1);
            gpiod_line_set_value(sck_line, 0);
        }

        gpiod_line_set_value(sck_line, 1);
        gpiod_line_set_value(sck_line, 0);

        raw_reading = gpiod_line_get_value(dout_line);
        weight += raw_reading;
    }

    weight /= MEASURE_SAMPLES;
    weight -= tare_offset;
    weight *= SCALE;

    return weight;
}

static void lock_solenoid() {
    struct gpiod_chip *chip;
    struct gpiod_line *lock_line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        LOG_ERROR("Failed to open GPIO chip");
        exit(1);
    }

    lock_line = gpiod_chip_get_line(chip, LOCK_PIN);
    if (!lock_line) {
        LOG_ERROR("Failed to get GPIO line");
        exit(1);
    }

    gpiod_line_set_value(lock_line, 1);
    usleep(DURATION * 1000);
    gpiod_line_set_value(lock_line, 0);
}

int main(int argc, char *argv[]) {
    int i, weight;

    setup_signals();
    setup_gpio();
    tare_sensor();

    while (running) {
        weight = read_weight();
        LOG_INFO("Weight: %d grams", weight);

        if (weight > THRESHOLD) {
            lock_solenoid();
        }

        usleep(500 * 1000);
    }

    gpiod_chip_close(chip);
    return 0;
}

