    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        LOG_ERROR("Failed to open GPIO chip");
        exit(1);
    }

    dout_line = gpiod_chip_get_line(chip, DOUT_PIN);
    sck_line = gpiod_chip_get_line(chip, SCK_PIN);

    if (!dout_line || !sck_line) {
        LOG_ERROR("Failed to get GPIO lines");
        exit(1);
    }

    gpiod_line_set_value(dout_line, 0);
    gpiod_line_set_value(sck_line, 0);

    for (i = 0; i < MEASURE_SAMPLES; i++) {
        gpiod_line_set_value(dout_line, 0);
        gpiod_line_set_value(sck_line, 0);

        for (j = 0; j < 24; j++) {
            gpiod_line_set_value(sck_line, 1);
            gpiod_line_set_value(sck_line, 0);
        }

        gpiod_line_set_value(sck_line, 1);
        gpiod_line_set_value(sck_line, 0);

        raw_reading = gpiod_line_get_value(dout_line);
        weight += raw_reading;
    }

    weight /= MEASURE_SAMPLES;
    weight -= tare_offset;
    weight *= SCALE;

    return weight;
}

static void lock_solenoid() {
    struct gpiod_chip *chip;
    struct gpiod_line *lock_line;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        LOG_ERROR("Failed to open GPIO chip");
        exit(1);
    }

    lock_line = gpiod_chip_get_line(chip, LOCK_PIN);
    if (!lock_line) {
        LOG_ERROR("Failed to get GPIO line");
        exit(1);
    }

    gpiod_line_set_value(lock_line, 1);
    usleep(DURATION * 1000);
    gpiod_line_set_value(lock_line, 0);
}

int main(int argc, char *argv[]) {
    int i, weight;

    setup_signals();
    setup_gpio();
    tare_sensor();

    while (running) {
        weight = read_weight();
        LOG_INFO("Weight: %d grams", weight);

        if (weight > THRESHOLD) {
            lock_solenoid();
        }

        usleep(500 * 1000);
    }

    gpiod_chip_close(chip);
    return 0;
}
