#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <mosquitto.h>
#include <pigpio.h>
#include <syslog.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_KEEPALIVE 60
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define MQTT_QOS 0
#define GPIO_PIN 17

static mosquitto_client *mosq;
static int gpio_handle;

static void mqtt_connect_callback(struct mosquitto *mosq, void *obj, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_connack_string(result));
    }
}

static void mqtt_message_callback(struct mosquitto *mosq, void *obj, const struct mosquitto_message *message) {
    if (message->payloadlen == 0) {
        syslog(LOG_ERR, "MQTT message received with empty payload");
        return;
    }

    if (strcmp(message->payload, "ON") == 0) {
        pigpio_gpio_write(gpio_handle, GPIO_PIN, 1);
        syslog(LOG_INFO, "Relay energized");
    } else if (strcmp(message->payload, "OFF") == 0) {
        pigpio_gpio_write(gpio_handle, GPIO_PIN, 0);
        syslog(LOG_INFO, "Relay de-energized");
    } else {
        syslog(LOG_ERR, "MQTT message received with invalid payload: %s", message->payload);
    }
}

static void mqtt_disconnect_callback(struct mosquitto *mosq, void *obj, int result) {
    syslog(LOG_INFO, "MQTT disconnected");
}

static void signal_handler(int signal) {
    switch (signal) {
        case SIGINT:
        case SIGTERM:
            mosquitto_loop_stop(mosq, true);
            pigpio_gpio_write(gpio_handle, GPIO_PIN, 0);
            mosquitto_disconnect(mosq);
            mosquitto_destroy(mosq);
            mosquitto_lib_cleanup();
            gpioTerminate();
            closelog();
            exit(0);
            break;
        default:
            break;
    }
}

int main(int argc, char *argv[]) {
    openlog("relay_controller", LOG_PID, LOG_USER);

    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        return 1;
    }

    gpio_handle = pigpio_start(NULL, NULL);
    if (gpio_handle < 0) {
        syslog(LOG_ERR, "Failed to start pigpio");
        return 1;
    }

    pigpio_gpio_write(gpio_handle, GPIO_PIN, 0);

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE)) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (true) {
        int rc = mosquitto_loop(mosq, -1, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "MQTT loop failed: %s", mosquitto_strerror(rc));
            mosquitto_disconnect(mosq);
            mosquitto_destroy(mosq);
            mosquitto_lib_cleanup();
            gpioTerminate();
            closelog();
            return 1;
        }
    }

    return 0;
}

