#define PWM_FREQ 50
#define PWM_RANGE 2000

int main() {
    int pi;
    int servo_pins[5] = {7, 8, 9, 10, 11};
    int pulse_widths[5] = {1000, 1500, 2000, 500, 2500};

    // Initialize pigpio
    if ((pi = pigpio_start(NULL, NULL)) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set PWM frequency and range for each pin
    for (int i = 0; i < 5; i++) {
        if (pigpio_set_PWM_frequency(pi, servo_pins[i], PWM_FREQ) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for pin %d\n", servo_pins[i]);
            return 1;
        }
        if (pigpio_set_PWM_range(pi, servo_pins[i], PWM_RANGE) < 0) {
            fprintf(stderr, "Failed to set PWM range for pin %d\n", servo_pins[i]);
            return 1;
        }
    }

    // Apply pulse widths to each pin
    for (int i = 0; i < 5; i++) {
        if (pigpio_set_PWM_dutycycle(pi, servo_pins[i], pulse_widths[i]) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle for pin %d\n", servo_pins[i]);
            return 1;
        }
    }

    // Hold signals for 3 seconds
    sleep(3);

    // Cleanly stop PWM and release library resources
    for (int i = 0; i < 5; i++) {
        if (pigpio_stop_PWM(pi, servo_pins[i]) < 0) {
            fprintf(stderr, "Failed to stop PWM for pin %d\n", servo_pins[i]);
            return 1;
        }
    }
    pigpio_stop(pi);

    return 0;
}

