#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <signal.h>

#define MOTOR_A_PWM_PIN 17
#define MOTOR_A_DIR_PIN 18
#define MOTOR_B_PWM_PIN 22
#define MOTOR_B_DIR_PIN 23
#define ENCODER_A_PHASE_PIN 4
#define ENCODER_A_PHASE_PIN 5
#define ENCODER_B_PHASE_PIN 6
#define ENCODER_B_PHASE_PIN 12
#define TARGET_SPEED 50
#define PWM_FREQ 10000
#define PWM_DUTY_CYCLE_MIN 0
#define PWM_DUTY_CYCLE_MAX 255
#define KP 0.5
#define KI 0.05
#define TICKS_PER_REV 64
#define ENCODER_STALL_TIMEOUT 2000

volatile uint32_t encoder_a_count = 0;
volatile uint32_t encoder_b_count = 0;
volatile bool encoder_a_stalled = false;
volatile bool encoder_b_stalled = false;

void encoder_a_isr(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        encoder_a_count++;
    } else {
        encoder_a_count--;
    }
}

void encoder_b_isr(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        encoder_b_count++;
    } else {
        encoder_b_count--;
    }
}

void encoder_stall_check(void) {
    if (encoder_a_count == 0) {
        encoder_a_stalled = true;
    } else {
        encoder_a_stalled = false;
    }

    if (encoder_b_count == 0) {
        encoder_b_stalled = true;
    } else {
        encoder_b_stalled = false;
    }
}

void motor_control(void) {
    uint32_t encoder_a_ticks = encoder_a_count;
    uint32_t encoder_b_ticks = encoder_b_count;
    uint32_t error = (TARGET_SPEED - (encoder_a_ticks + encoder_b_ticks) / 2) * KP;
    uint32_t integral = (encoder_a_ticks + encoder_b_ticks) / 2 * KI;
    uint32_t duty_cycle = error + integral;

    if (duty_cycle < PWM_DUTY_CYCLE_MIN) {
        duty_cycle = PWM_DUTY_CYCLE_MIN;
    } else if (duty_cycle > PWM_DUTY_CYCLE_MAX) {
        duty_cycle = PWM_DUTY_CYCLE_MAX;
    }

    gpioPWM(MOTOR_A_PWM_PIN, PWM_FREQ, duty_cycle);
    gpioPWM(MOTOR_B_PWM_PIN, PWM_FREQ, duty_cycle);
}

void sigint_handler(int signal) {
    gpioWrite(MOTOR_A_PWM_PIN, 0);
    gpioWrite(MOTOR_B_PWM_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetISRFunc(ENCODER_A_PHASE_PIN, EITHER_EDGE, encoder_a_isr) < 0) {
        fprintf(stderr, "Failed to set ISR for encoder A\n");
        return 1;
    }

    if (gpioSetISRFunc(ENCODER_B_PHASE_PIN, EITHER_EDGE, encoder_b_isr) < 0) {
        fprintf(stderr, "Failed to set ISR for encoder B\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (true) {
        encoder_stall_check();

        if (encoder_a_stalled || encoder_b_stalled) {
            fprintf(stderr, "Encoder stall detected\n");
            continue;
        }

        motor_control();

        printf("Motor A RPM: %d\n", (encoder_a_count * 60) / TICKS_PER_REV);
        printf("Motor B RPM: %d\n", (encoder_b_count * 60) / TICKS_PER_REV);
        printf("PWM Duty Cycle: %d\n", duty_cycle);

        sleep(100);
    }

    gpioTerminate();
    return 0;
}

