        // Read lux value from sensor
        uint16_t lux = bh1750Read(&sensor);
        if (lux < 0) {
            fprintf(stderr, "Failed to read lux value from sensor\n");
            return 1;
        }

        // Convert lux to lux
        lux = lux / 1.2;

        // Check if lux is below threshold
        if (lux < LUX_THRESHOLD_LOW) {
            // Turn on relay
            if (gpioWrite(RELAY_GPIO, PI_HIGH) < 0) {
                fprintf(stderr, "Failed to turn on relay\n");
                return 1;
