        // Log lux value and relay state
        char log_str[100];
        snprintf(log_str, sizeof(log_str), "%s: Lux = %d, Relay = %s\n",
                 ctime(&time(NULL)), lux, lux < LUX_THRESHOLD_LOW ? "ON" : "OFF");
        fprintf(log_file, log_str);

        // Wait for next poll interval
        usleep(POLL_INTERVAL * 1000000);
    }

    // Clean up
    bh1750Close(&sensor);
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

