#define RELAY_PIN 17
#define SENSOR_PIN 4
#define DEBOUNCE_DELAY 50

bool relay_state = false;

void sigint_handler(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT, turning relay off and releasing pigpio resources\n");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        exit(0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (true) {
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", SENSOR_PIN);
            gpioTerminate();
            return 1;
        }

        if (sensor_value == 1) {
            if (relay_state == false) {
                gpioWrite(RELAY_PIN, 1);
                relay_state = true;
                printf("Relay state changed to ON at %s\n", asctime(localtime(&time(NULL))));
            }
        } else {
            if (relay_state == true) {
                gpioWrite(RELAY_PIN, 0);
                relay_state = false;
                printf("Relay state changed to OFF at %s\n", asctime(localtime(&time(NULL))));
            }
        }

        usleep(10000);
    }

    gpioTerminate();
    return 0;
}

