#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <time.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define LPM_THRESHOLD 5.0
#define HYSTERESIS 0.5

int pulse_count = 0;
pthread_mutex_t pulse_mutex;

void flow_sensor_isr(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

void solenoid_control(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        gpioWrite(SOLENOID_PIN, 0);
    } else {
        gpioWrite(SOLENOID_PIN, 1);
    }
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flow sensor pin mode\n");
        return 1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, EITHER_EDGE, 1000, flow_sensor_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set flow sensor ISR\n");
        return 1;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        return 1;
    }

    if (gpioWrite(SOLENOID_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set solenoid to open state\n");
        return 1;
    }

    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Failed to initialize pulse mutex\n");
        return 1;
    }

    FILE *log_file = fopen("water_flow.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = (current_pulse_count / 450.0) * 60.0;
        fprintf(log_file, "%f\n", lpm);

        if (lpm > LPM_THRESHOLD) {
            gpioWrite(SOLENOID_PIN, 0);
            fprintf(log_file, "Solenoid closed at %f L/min\n", lpm);
        } else if (lpm < LPM_THRESHOLD - HYSTERESIS) {
            gpioWrite(SOLENOID_PIN, 1);
            fprintf(log_file, "Solenoid opened at %f L/min\n", lpm);
        }

        sleep(1);
    }

    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();

    return 0;
}

