    close(servo_fd);
    close(server_fd);
    close(client_fd);
    exit(0);
}

static void init_gpio() {
    gpio_fd = pigpio_start(NULL, NULL);
    if (gpio_fd < 0) {
        printf("Failed to initialize GPIO: %s\n", strerror(errno));
        exit(1);
    }

    if (pigpio_gpio_export(gpio_fd, DATA_PIN) < 0) {
        printf("Failed to export GPIO %d: %s\n", DATA_PIN, strerror(errno));
        exit(1);
    }

    if (pigpio_gpio_export(gpio_fd, SCK_PIN) < 0) {
        printf("Failed to export GPIO %d: %s\n", SCK_PIN, strerror(errno));
        exit(1);
    }

    if (pigpio_gpio_export(gpio_fd, SERVO_PIN) < 0) {
        printf("Failed to export GPIO %d: %s\n", SERVO_PIN, strerror(errno));
        exit(1);
    }
}

static void init_hx711() {
    hx711_fd = hx711_open(DATA_PIN, SCK_PIN);
    if (hx711_fd < 0) {
        printf("Failed to open HX711: %s\n", strerror(errno));
        exit(1);
    }

    if (hx711_set_clock_pulse_width(hx711_fd, 1) < 0) {
        printf("Failed to set clock pulse width: %s\n", strerror(errno));
        exit(1);
    }

    if (hx711_set_clock_pulse_width(hx711_fd, 1000) < 0) {
        printf("Failed to set clock pulse width: %s\n", strerror(errno));
        exit(1);
    }
}

static void init_servo() {
    servo_fd = pigpio_start(NULL, NULL);
    if (servo_fd < 0) {
        printf("Failed to initialize servo: %s\n", strerror(errno));
        exit(1);
    }

    if (pigpio_gpio_export(servo_fd, SERVO_PIN) < 0) {
        printf("Failed to export GPIO %d: %s\n", SERVO_PIN, strerror(errno));
        exit(1);
    }

    if (pigpio_gpio_set_mode(servo_fd, SERVO_PIN, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO %d mode: %s\n", SERVO_PIN, strerror(errno));
        exit(1);
    }
}

static void init_server() {
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        printf("Failed to create server socket: %s\n", strerror(errno));
        exit(1);
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(SERVER_IP);
    server_addr.sin_port = htons(SERVER_PORT);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        printf("Failed to bind server socket: %s\n", strerror(errno));
        exit(1);
    }

    if (listen(server_fd, 1) < 0) {
        printf("Failed to listen on server socket: %s\n", strerror(errno));
        exit(1);
    }
}

static void init_client() {
    client_fd = accept(server_fd, NULL, NULL);
    if (client_fd < 0) {
        printf("Failed to accept client connection: %s\n", strerror(errno));
        exit(1);
    }
}

static void read_config() {
    FILE *config_file = fopen("config.ini", "r");
    if (config_file == NULL) {
        printf("Failed to open config file: %s\n", strerror(errno));
        exit(1);
    }

    char line[1024];
    while (fgets(line, sizeof(line), config_file) != NULL) {
        if (strstr(line, "calibration_factor") != NULL) {
            sscanf(line, "calibration_factor = %d", &calibration_factor);
        } else if (strstr(line, "server_ip") != NULL) {
            sscanf(line, "server_ip = %s", &server_ip);
        } else if (strstr(line, "server_port") != NULL) {
            sscanf(line, "server_port = %d", &server_port);
        }
    }

    fclose(config_file);
}

static void dispense(int target_weight) {
    int actual_weight = 0;
    int error = 0;

    // Open the servo
    if (pigpio_gpio_write(servo_fd, SERVO_PIN, 1) < 0) {
        printf("Failed to open servo: %s\n", strerror(errno));
        error = 1;
    }

    // Wait for the load cell to stabilize
    usleep(1000000);

    // Read the actual weight from the HX711
    if (hx711_read(hx711_fd, &actual_weight) < 0) {
        printf("Failed to read HX711: %s\n", strerror(errno));
        error = 1;
    }

    // Close the servo
    if (pigpio_gpio_write(servo_fd, SERVO_PIN, 0) < 0) {
        printf("Failed to close servo: %s\n", strerror(errno));
        error = 1;
    }

    // Send the actual weight back to the client
    if (send(client_fd, &actual_weight, sizeof(actual_weight), 0) < 0) {
        printf("Failed to send actual weight: %s\n", strerror(errno));
        error = 1;
    }

    // Log the dispensing event
    if (error == 0) {
        char log_entry[1024];
        sprintf(log_entry, "{\"date\": \"%s\", \"time\": \"%s\", \"target_weight\": %d, \"actual_weight\": %d}",
                __DATE__, __TIME__, target_weight, actual_weight);
        FILE *log_file = fopen(DISPENSING_LOG, "a");
        if (log_file == NULL) {
            printf("Failed to open log file: %s\n", strerror(errno));
            error = 1;
        } else {
            fprintf(log_file, "%s\n", log_entry);
            fclose(log_file);
        }
    }
}

int main(int argc, char **argv) {
    // Initialize the GPIO, HX711, and servo
    init_gpio();
    init_hx711();
    init_servo();

    // Initialize the server
    init_server();

    // Read the config file
    read_config();

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Main loop
    while (1) {
        // Accept a client connection
        init_client();

        // Read the target weight from the client
        int target_weight;
        if (recv(client_fd, &target_weight, sizeof(target_weight), 0) < 0) {
            printf("Failed to read target weight: %s\n", strerror(errno));
            continue;
        }

        // Dispense the ingredient
        dispense(target_weight);

        // Close the client connection
        close(client_fd);
    }

    // Clean up
    close(gpio_fd);
    close(hx711_fd);
    close(servo_fd);
    close(server_fd);
    close(client_fd);

    return 0;
}
```
This code uses the pigpio library to control the GPIO pins, the hx711 library to read the HX711 load cell amplifier, and the servo library to control the SG90-style servo motor. It also uses the signal library to handle SIGINT and SIGTERM signals for clean shutdown. The code reads the target weight from the client, dispenses the ingredient based on the target weight, and logs the dispensing event to a JSON file. It also uses a config.ini file to read the calibration factor, server IP, and server port.

