#define RELAY_GPIO 17
#define TOUCH_GPIO 4
#define DEBOUNCE_MS 50

static bool relay_state = false;
static bool touch_state = false;
static bool touch_stable = false;
static bool touch_changed = false;
static bool shutdown = false;

static void sigint_handler(int signum) {
    shutdown = true;
}

static void sigterm_handler(int signum) {
    shutdown = true;
}

static void touch_handler(int gpio, int level, uint32_t tick) {
    touch_state = level;
    touch_changed = true;
}

static void relay_handler(int gpio, int level, uint32_t tick) {
    relay_state = level;
    printf("%s Relay: %s\n", asctime(localtime(&tick)), relay_state ? "ON" : "OFF");
}

int main(int argc, char *argv[]) {
    int debounce_ms = DEBOUNCE_MS;
    if (argc > 1) {
        debounce_ms = atoi(argv[1]);
    }

    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay GPIO mode\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set touch GPIO mode\n");
        return 1;
    }

    if (gpioSetISRFunc(TOUCH_GPIO, EITHER_EDGE, touch_handler) < 0) {
        fprintf(stderr, "Failed to set touch GPIO ISR\n");
        return 1;
    }

    if (gpioSetISRFunc(RELAY_GPIO, EITHER_EDGE, relay_handler) < 0) {
        fprintf(stderr, "Failed to set relay GPIO ISR\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (!shutdown) {
        if (touch_changed) {
            touch_changed = false;
            if (touch_state) {
                touch_stable = true;
            } else if (touch_stable) {
                touch_stable = false;
                relay_state = !relay_state;
                gpioWrite(RELAY_GPIO, relay_state);
            }
        }
        usleep(debounce_ms * 1000);
    }

    gpioWrite(RELAY_GPIO, false);
    gpioSetISRFunc(TOUCH_GPIO, 0, NULL);
    gpioSetISRFunc(RELAY_GPIO, 0, NULL);
    gpioTerminate();
    pigpio_stop(NULL);

    return 0;
}

