#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <termios.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQ 50
#define PWM_PERIOD 20
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define DEFAULT_ANGLE 90

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up terminal for raw input
    struct termios old_termios;
    if (tcgetattr(STDIN_FILENO, &old_termios) < 0) {
        fprintf(stderr, "Failed to get terminal attributes\n");
        return 1;
    }
    struct termios new_termios = old_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO);
    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) < 0) {
        fprintf(stderr, "Failed to set terminal attributes\n");
        return 1;
    }

    // Set up PWM on GPIO18
    if (gpioSetPWMfrequency(GPIO_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        return 1;
    }
    if (gpioSetPWMrange(GPIO_PIN, PWM_PERIOD) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        return 1;
    }
    if (gpioPWM(GPIO_PIN, DEFAULT_ANGLE) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        return 1;
    }

    // Set up signal handler for SIGINT (Ctrl-C)
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        return 1;
    }

    // Main loop
    char c;
    while ((c = getchar()) != EOF) {
        switch (c) {
            case '+':
                if (gpioPWM(GPIO_PIN, DEFAULT_ANGLE + 10) < 0) {
                    fprintf(stderr, "Failed to set PWM duty cycle\n");
                    return 1;
                }
                break;
            case '-':
                if (gpioPWM(GPIO_PIN, DEFAULT_ANGLE - 10) < 0) {
                    fprintf(stderr, "Failed to set PWM duty cycle\n");
                    return 1;
                }
                break;
            case 'q':
                gpioPWM(GPIO_PIN, 0);
                gpioTerminate();
                tcsetattr(STDIN_FILENO, TCSANOW, &old_termios);
                return 0;
            default:
                break;
        }
        printf("Angle: %d\n", DEFAULT_ANGLE);
    }

    // Clean up
    gpioPWM(GPIO_PIN, 0);
    gpioTerminate();
    tcsetattr(STDIN_FILENO, TCSANOW, &old_termios);

    return 0;
}

void sigint_handler(int signum) {
    gpioPWM(GPIO_PIN, 0);
    gpioTerminate();
    tcsetattr(STDIN_FILENO, TCSANOW, &old_termios);
    exit(0);
}

