#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NAME "gpio17"
#define DEBOUNCE_TIME 2
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request_config config;
    struct gpiod_line_event event;
    int rc;
    int pulseCount = 0;
    double rpm;
    char *log_file_name = "motor_rpm.log";
    FILE *log_file;

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", GPIO_CHIP_NAME);
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE_NAME);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %s\n", GPIO_LINE_NAME);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up the GPIO line configuration
    config.consumer = "motor_rpm";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    // Request the GPIO line
    rc = gpiod_line_request_input_flags(line, &config);
    if (rc < 0) {
        fprintf(stderr, "Error requesting GPIO line %s\n", GPIO_LINE_NAME);
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file
    log_file = fopen(log_file_name, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s\n", log_file_name);
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!stop) {
        // Wait for an edge event
        rc = gpiod_line_event_wait(line, &event, DEBOUNCE_TIME);
        if (rc < 0) {
            fprintf(stderr, "Error waiting for GPIO line event\n");
            break;
        }

        // Check if the event is a rising edge
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            pulseCount++;
        }

        // Compute RPM
        rpm = (pulseCount / 5.0) * 60.0;

        // Write to log file
        fprintf(log_file, "%s,%.2f\n", get_iso_time(), rpm);
        fflush(log_file);

        // Print to stdout
        printf("RPM: %.2f\n", rpm);

        // Sleep for the sample interval
        usleep(SAMPLE_INTERVAL * 1000000);
    }

    // Clean up
    gpiod_line_free(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

