#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 24
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define VALVE_ENABLE_ACTIVE_HIGH
#define FLOW_LOG_FILE "flow_log.csv"
#define FLOW_LOG_INTERVAL 100
#define FLOW_SENSOR_CALIBRATION 450
#define KP 1.0

static bool running = true;
static uint32_t pulse_count = 0;
static double flow_rate = 0.0;
static double valve_position = 0.0;
static FILE *flow_log_file = NULL;

static void flow_sensor_isr(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_count++;
    }
}

static void handle_sigint(int signal) {
    running = false;
}

static void handle_sigterm(int signal) {
    running = false;
}

static void cleanup(void) {
    if (flow_log_file != NULL) {
        fclose(flow_log_file);
    }
    pigpio_stop(PI_DEFAULT);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <target_flow_rate>\n", argv[0]);
        return 1;
    }

    double target_flow_rate = atof(argv[1]);
    if (target_flow_rate <= 0.0) {
        fprintf(stderr, "Invalid target flow rate: %s\n", argv[1]);
        return 1;
    }

    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (pigpio_gpio_mode_set(VALVE_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", VALVE_PWM_PIN);
        return 1;
    }

    if (pigpio_gpio_mode_set(VALVE_ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode\n", VALVE_ENABLE_PIN);
        return 1;
    }

    if (pigpio_gpio_write(VALVE_ENABLE_PIN, 1) < 0) {
        fprintf(stderr, "Failed to enable valve\n");
        return 1;
    }

    if (pigpio_set_mode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode\n", FLOW_SENSOR_PIN);
        return 1;
    }

    if (pigpio_set_pull_up_down(FLOW_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", FLOW_SENSOR_PIN);
        return 1;
    }

    if (pigpio_set_ISR_func(FLOW_SENSOR_PIN, PI_RISING_EDGE, flow_sensor_isr) < 0) {
        fprintf(stderr, "Failed to set ISR for GPIO %d\n", FLOW_SENSOR_PIN);
        return 1;
    }

    if ((flow_log_file = fopen(FLOW_LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open flow log file\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    while (running) {
        uint32_t current_pulse_count = pulse_count;
        pulse_count = 0;

        flow_rate = (double)current_pulse_count / FLOW_SENSOR_CALIBRATION * 60.0;
        valve_position = KP * (flow_rate - target_flow_rate);
        valve_position = fmax(0.0, fmin(255.0, valve_position));

        pigpio_gpio_write(VALVE_PWM_PIN, valve_position);

        fprintf(flow_log_file, "%ld,%.2f,%.2f\n", time(NULL), flow_rate, valve_position);

        usleep(FLOW_LOG_INTERVAL * 1000);
    }

    cleanup();

    return 0;
}

