static void init_relay(void) {
    if (gpio_init() < 0) {
        printf("Failed to initialize GPIO\n");
        exit(1);
    }

    if (gpio_set_mode(RELAY_GPIO, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO mode\n");
        exit(1);
    }

