}

static void init_mpr121(void) {
    if (i2c_init() < 0) {
        printf("Failed to initialize I2C\n");
        exit(1);
    }

    if (i2c_open(I2C_BUS, I2C_ADDR) < 0) {
        printf("Failed to open I2C device\n");
        exit(1);
    }

    // Soft reset
    uint8_t reset_cmd = 0x63;
    if (i2c_write(I2C_BUS, I2C_ADDR, &reset_cmd, 1) < 0) {
        printf("Failed to send soft reset command\n");
        exit(1);
    }

    // Configure filtering
    uint8_t filter_cmd = 0x41;
    uint8_t filter_val = 0x01;
    if (i2c_write(I2C_BUS, I2C_ADDR, &filter_cmd, 1) < 0) {
        printf("Failed to set filtering\n");
        exit(1);
    }

    // Set touch and release thresholds for all electrodes
    uint8_t touch_cmd = 0x41;
    uint8_t touch_val = TOUCH_THRESHOLD;
    if (i2c_write(I2C_BUS, I2C_ADDR, &touch_cmd, 1) < 0) {
        printf("Failed to set touch threshold\n");
        exit(1);
    }

    uint8_t release_cmd = 0x42;
    uint8_t release_val = RELEASE_THRESHOLD;
    if (i2c_write(I2C_BUS, I2C_ADDR, &release_cmd, 1) < 0) {
        printf("Failed to set release threshold\n");
        exit(1);
    }

    // Enable run mode
    uint8_t run_cmd = 0x43;
    uint8_t run_val = 0x01;
    if (i2c_write(I2C_BUS, I2C_ADDR, &run_cmd, 1) < 0) {
        printf("Failed to enable run mode\n");
        exit(1);
    }
}

static void read_mpr121(void) {
    uint8_t touch_status[2];
    if (i2c_read(I2C_BUS, I2C_ADDR, touch_status, 2) < 0) {
        printf("Failed to read touch status\n");
        exit(1);
    }

    for (int i = 0; i < 12; i++) {
        if (touch_status[i / 8] & (1 << (i % 8))) {
            if (relay_state == RELAY_OFF) {
                relay_state = RELAY_ON;
                gpio_write(RELAY_GPIO, RELAY_ON);
                printf("Relay activated\n");
            }
        } else {
            if (relay_state == RELAY_ON) {
                relay_state = RELAY_OFF;
                gpio_write(RELAY_GPIO, RELAY_OFF);
                printf("Relay deactivated\n");
            }
        }
    }
}

