}

int main(int argc, char *argv[]) {
    // Initialize GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        printf("Error: Failed to open GPIO chip\n");
        return 1;
    }

    // Request GPIO lines
    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!valve1_line || !valve2_line) {
        printf("Error: Failed to request GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        printf("Error: Failed to open log file\n");
        gpiod_line_release(valve1_line);
        gpiod_line_release(valve2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Activate Valve 1
        gpiod_line_set_value(valve1_line, VALVE_ON);
        printf("Valve 1 activated\n");
        fprintf(log_file, "%s Valve 1 activated\n", get_iso_8601_timestamp());
        usleep(VALVE1_DURATION * 1000);

        // Pause
        gpiod_line_set_value(valve1_line, VALVE_OFF);
        printf("Valve 1 deactivated\n");
        fprintf(log_file, "%s Valve 1 deactivated\n", get_iso_8601_timestamp());
        usleep(PAUSE_DURATION * 1000);

        // Activate Valve 2
        gpiod_line_set_value(valve2_line, VALVE_ON);
        printf("Valve 2 activated\n");
        fprintf(log_file, "%s Valve 2 activated\n", get_iso_8601_timestamp());
        usleep(VALVE2_DURATION * 1000);

        // Pause
        gpiod_line_set_value(valve2_line, VALVE_OFF);
        printf("Valve 2 deactivated\n");
        fprintf(log_file, "%s Valve 2 deactivated\n", get_iso_8601_timestamp());
        usleep(PAUSE_DURATION * 1000);
    }

    // Clean up
    gpiod_line_release(valve1_line);
    gpiod_line_release(valve2_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

char *get_iso_8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    timestamp = asctime(timeinfo);
    timestamp[strlen(timestamp) - 1] = '\0';

    return timestamp;
}

