#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define RELAY_PIN 17

#define TOUCH_THRESHOLD 0x10
#define RELEASE_THRESHOLD 0x0A
#define FILTER_TIME 0x20
#define ELECTRODE_CURRENT 0x01
#define ELE_EN 0x20

#define TOUCH_STATUS_REG 0x00
#define RELEASE_STATUS_REG 0x01

int main(void) {
    int i2c_fd;
    int relay_fd;
    uint8_t touch_status;
    uint8_t release_status;

    // Initialize pigpio
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Initialize MPR121 in stop mode
    if (pigpio_i2c_write_byte(i2c_fd, 0x5E, 0x00) < 0) {
        fprintf(stderr, "Failed to initialize MPR121 in stop mode\n");
        return 1;
    }

    // Set touch threshold and release threshold for all electrodes
    if (pigpio_i2c_write_byte(i2c_fd, 0x10, TOUCH_THRESHOLD) < 0 ||
        pigpio_i2c_write_byte(i2c_fd, 0x11, RELEASE_THRESHOLD) < 0) {
        fprintf(stderr, "Failed to set touch threshold and release threshold for all electrodes\n");
        return 1;
    }

    // Configure filter/charge time and electrode current
    if (pigpio_i2c_write_byte(i2c_fd, 0x20, FILTER_TIME) < 0 ||
        pigpio_i2c_write_byte(i2c_fd, 0x21, ELECTRODE_CURRENT) < 0) {
        fprintf(stderr, "Failed to configure filter/charge time and electrode current\n");
        return 1;
    }

    // Enter run mode with ELE_EN=1
    if (pigpio_i2c_write_byte(i2c_fd, 0x20, ELE_EN) < 0) {
        fprintf(stderr, "Failed to enter run mode with ELE_EN=1\n");
        return 1;
    }

    // Wait 100 ms for stabilization
    usleep(100000);

    // Set relay pin as output, initially off
    if ((relay_fd = pigpio_gpio_export(RELAY_PIN)) < 0) {
        fprintf(stderr, "Failed to export relay pin\n");
        return 1;
    }
    pigpio_gpio_set_mode(relay_fd, PI_OUTPUT);
    pigpio_gpio_write(relay_fd, 0);

    // Loop with 100 ms delay
    while (1) {
        // Read touch status registers
        if (pigpio_i2c_read_byte(i2c_fd, TOUCH_STATUS_REG, &touch_status) < 0 ||
            pigpio_i2c_read_byte(i2c_fd, RELEASE_STATUS_REG, &release_status) < 0) {
            fprintf(stderr, "Failed to read touch status registers\n");
            return 1;
        }

        // If any electrode is touched, toggle the relay and print the status
        if (touch_status > 0 || release_status > 0) {
            pigpio_gpio_write(relay_fd, !pigpio_gpio_read(relay_fd));
            printf("Touch status: %d, release status: %d\n", touch_status, release_status);
        }

        // Wait 100 ms
        usleep(100000);
    }

    // Close I2C bus and pigpio
    pigpio_i2c_close(i2c_fd);
    pigpio_stop();

    return 0;
}

