#include <time.h>
#include <pigpio.h>

#define PIR_PIN 17
#define RELAY_PIN 18
#define RATE_LIMIT_MS 2000

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO pins
    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN);

    // Open log file
    FILE *log_file = fopen("door_events.log", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up rate limiting
    struct timespec rate_limit_ts;
    clock_gettime(CLOCK_MONOTONIC, &rate_limit_ts);
    rate_limit_ts.tv_nsec += RATE_LIMIT_MS * 1000000;

    // Main loop
    while (true) {
        // Poll GPIO pin
        int pir_value = gpioRead(PIR_PIN);

        // Check for rising edge
        if (pir_value == 1 && gpioRead(PIR_PIN) == 0) {
            // Check rate limit
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            if (now.tv_nsec - rate_limit_ts.tv_nsec > 0) {
                // Unlock door
                gpioWrite(RELAY_PIN, 1);
                usleep(500000);
                gpioWrite(RELAY_PIN, 0);

                // Log event
                fprintf(log_file, "Motion detected at %ld.%ld\n", now.tv_sec, now.tv_nsec);
                fprintf(log_file, "Door unlocked at %ld.%ld\n", now.tv_sec, now.tv_nsec);

                // Update rate limit
                rate_limit_ts = now;
            } else {
                // Log rate-limited event
                fprintf(log_file, "Motion detected at %ld.%ld (rate-limited)\n", now.tv_sec, now.tv_nsec);
            }
        }

        // Sleep for 50 ms
        usleep(50000);
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    return 0;
}

