#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define PWM_FREQ 1000
#define PWM_RES 8
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 255
#define PATTERN_STEPS 5
#define PATTERN_DURATION 50
#define PATTERN_MAX_STEPS 15
#define PATTERN_MAX_DURATION 200

volatile sig_atomic_t shutdown = 0;

void sigint_handler(int signum) {
    shutdown = 1;
}

void generate_pattern(int *motor1_duty, int *motor2_duty, int *duration) {
    // Generate random pattern
    *motor1_duty = rand() % (PWM_DUTY_MAX - PWM_DUTY_MIN) + PWM_DUTY_MIN;
    *motor2_duty = rand() % (PWM_DUTY_MAX - PWM_DUTY_MIN) + PWM_DUTY_MIN;
    *duration = rand() % (PATTERN_MAX_DURATION - PATTERN_DURATION) + PATTERN_DURATION;
}

int main(void) {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set GPIO mode
    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for motor 1\n");
        return 1;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for motor 2\n");
        return 1;
    }

    // Set PWM frequency and resolution
    if (gpioPWM(MOTOR1_PIN, PWM_FREQ, PWM_RES) < 0) {
        fprintf(stderr, "Failed to set PWM frequency and resolution for motor 1\n");
        return 1;
    }
    if (gpioPWM(MOTOR2_PIN, PWM_FREQ, PWM_RES) < 0) {
        fprintf(stderr, "Failed to set PWM frequency and resolution for motor 2\n");
        return 1;
    }

    // Set random seed
    srand(time(NULL));

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!shutdown) {
        // Generate random pattern
        int motor1_duty, motor2_duty, duration;
        generate_pattern(&motor1_duty, &motor2_duty, &duration);

        // Set PWM duty cycle and duration
        gpioPWM(MOTOR1_PIN, motor1_duty, duration);
        gpioPWM(MOTOR2_PIN, motor2_duty, duration);

        // Wait for duration
        gpioDelay(duration);
    }

    // Stop motors and release resources
    gpioPWM(MOTOR1_PIN, 0, 0);
    gpioPWM(MOTOR2_PIN, 0, 0);
    gpioTerminate();

    return 0;
}

