#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SCALE_FACTOR 1.0
#define OFFSET 0.0
#define THRESHOLD 10.0
#define SAMPLE_SIZE 100
#define SAMPLE_INTERVAL 500
#define TIMEOUT 500

static int gpio_data = 4;
static int gpio_clock = 17;
static int gpio_solenoid = 27;

static int scale_factor = SCALE_FACTOR;
static int offset = OFFSET;

static FILE *log_file;

static void handle_sigint(int signal) {
    printf("Received SIGINT, shutting down...\n");
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

static void read_calibration_data() {
    FILE *calibration_file = fopen("calibration.txt", "r");
    if (calibration_file == NULL) {
        printf("Calibration file not found, using default values.\n");
        return;
    }

    char line[100];
    if (fgets(line, sizeof(line), calibration_file) == NULL) {
        printf("Error reading calibration file, using default values.\n");
        return;
    }

    char *scale_factor_str = strtok(line, " ");
    char *offset_str = strtok(NULL, " ");

    if (scale_factor_str == NULL || offset_str == NULL) {
        printf("Invalid calibration data, using default values.\n");
        return;
    }

    scale_factor = atof(scale_factor_str);
    offset = atof(offset_str);
}

static void write_calibration_data() {
    FILE *calibration_file = fopen("calibration.txt", "w");
    if (calibration_file == NULL) {
        printf("Error writing calibration file.\n");
        return;
    }

    fprintf(calibration_file, "%f %f", scale_factor, offset);
    fclose(calibration_file);
}

static void startup_calibration() {
    int sum = 0;
    for (int i = 0; i < SAMPLE_SIZE; i++) {
        int reading = gpioRead(gpio_data);
        if (reading < 0) {
            printf("Error reading sensor, skipping iteration.\n");
            continue;
        }
        sum += reading;
    }
    offset = sum / SAMPLE_SIZE;
    write_calibration_data();
}

static void read_sensor() {
    int reading = gpioRead(gpio_data);
    if (reading < 0) {
        printf("Error reading sensor, skipping iteration.\n");
        return;
    }

    float weight = (reading - offset) * scale_factor;
    if (weight > THRESHOLD) {
        gpioWrite(gpio_solenoid, 1);
    } else {
        gpioWrite(gpio_solenoid, 0);
    }

    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, %f kg\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, weight);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Error initializing GPIO.\n");
        return 1;
    }

    gpioSetMode(gpio_data, PI_INPUT);
    gpioSetMode(gpio_clock, PI_INPUT);
    gpioSetMode(gpio_solenoid, PI_OUTPUT);

    log_file = fopen("weight_log.txt", "w");
    if (log_file == NULL) {
        printf("Error opening log file.\n");
        return 1;
    }

    read_calibration_data();
    startup_calibration();

    signal(SIGINT, handle_sigint);

    while (1) {
        read_sensor();
        usleep(SAMPLE_INTERVAL * 1000);
    }

    gpioTerminate();
    fclose(log_file);
    return 0;
}

