#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define GPIO_RAIN_SENSOR 4
#define GPIO_MOTOR_IN1 17
#define GPIO_MOTOR_IN2 18
#define GPIO_MOTOR_PWM 27

#define MOTOR_PWM_FREQ 1000
#define MOTOR_PWM_DUTY 150

#define DEBOUNCE_READINGS 5
#define DEBOUNCE_INTERVAL 50

#define WINDOW_CLOSE_TIME 5

int main(int argc, char *argv[]) {
  // Initialize GPIO
  if (gpioInitialise() < 0) {
    fprintf(stderr, "Failed to initialize GPIO\n");
    return 1;
  }

  // Set up GPIO pins
  if (gpioSetMode(GPIO_RAIN_SENSOR, PI_INPUT) < 0) {
    fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_RAIN_SENSOR);
    return 1;
  }
  if (gpioSetMode(GPIO_MOTOR_IN1, PI_OUTPUT) < 0) {
    fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_MOTOR_IN1);
    return 1;
  }
  if (gpioSetMode(GPIO_MOTOR_IN2, PI_OUTPUT) < 0) {
    fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_MOTOR_IN2);
    return 1;
  }
  if (gpioSetMode(GPIO_MOTOR_PWM, PI_OUTPUT) < 0) {
    fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_MOTOR_PWM);
    return 1;
  }

  // Set up PWM
  if (gpioPWM(GPIO_MOTOR_PWM, MOTOR_PWM_FREQ, MOTOR_PWM_DUTY) < 0) {
    fprintf(stderr, "Failed to set PWM on GPIO %d\n", GPIO_MOTOR_PWM);
    return 1;
  }

  // Set up signal handlers
  signal(SIGINT, handle_sigint);
  signal(SIGTERM, handle_sigterm);

  // Main loop
  while (1) {
    // Read rain sensor
    int rain_sensor_value = gpioRead(GPIO_RAIN_SENSOR);

    // Debounce readings
    int debounce_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
      int reading = gpioRead(GPIO_RAIN_SENSOR);
      if (reading == rain_sensor_value) {
        debounce_count++;
      }
      usleep(DEBOUNCE_INTERVAL * 1000);
    }

    // Check if rain is detected
    if (debounce_count >= 3) {
      // Rain detected, close window
      gpioWrite(GPIO_MOTOR_IN1, 1);
      gpioWrite(GPIO_MOTOR_IN2, 0);
      gpioPWM(GPIO_MOTOR_PWM, MOTOR_PWM_FREQ, MOTOR_PWM_DUTY);
      usleep(WINDOW_CLOSE_TIME * 1000);
      gpioWrite(GPIO_MOTOR_IN1, 0);
      gpioWrite(GPIO_MOTOR_IN2, 0);
      gpioPWM(GPIO_MOTOR_PWM, 0, 0);

      // Log event
      syslog(LOG_INFO, "Rain detected, window closed");
    } else {
      // No rain detected, do nothing
      syslog(LOG_INFO, "No rain detected");
    }

    // Wait for next check
    usleep(60 * 1000 * 1000);
  }

  // Clean up
  gpioTerminate();

  return 0;
}

void handle_sigint(int signal) {
  // Stop motor
  gpioWrite(GPIO_MOTOR_IN1, 0);
  gpioWrite(GPIO_MOTOR_IN2, 0);
  gpioPWM(GPIO_MOTOR_PWM, 0, 0);

  // Release GPIO resources
  gpioTerminate();

  // Close log
  closelog();

  // Exit
  exit(0);
}

void handle_sigterm(int signal) {
  // Stop motor
  gpioWrite(GPIO_MOTOR_IN1, 0);
  gpioWrite(GPIO_MOTOR_IN2, 0);
  gpioPWM(GPIO_MOTOR_PWM, 0, 0);

  // Release GPIO resources
  gpioTerminate();

  // Close log
  closelog();

  // Exit
  exit(0);
}

