        debounce_count++;
      }
      usleep(DEBOUNCE_INTERVAL * 1000);
    }

    // Check if rain is detected
    if (debounce_count >= 3) {
      // Rain detected, close window
      gpioWrite(GPIO_MOTOR_IN1, 1);
      gpioWrite(GPIO_MOTOR_IN2, 0);
      gpioPWM(GPIO_MOTOR_PWM, MOTOR_PWM_FREQ, MOTOR_PWM_DUTY);
      usleep(WINDOW_CLOSE_TIME * 1000);
      gpioWrite(GPIO_MOTOR_IN1, 0);
      gpioWrite(GPIO_MOTOR_IN2, 0);
      gpioPWM(GPIO_MOTOR_PWM, 0, 0);

      // Log event
      syslog(LOG_INFO, "Rain detected, window closed");
    } else {
      // No rain detected, do nothing
      syslog(LOG_INFO, "No rain detected");
    }

    // Wait for next check
    usleep(60 * 1000 * 1000);
  }

  // Clean up
  gpioTerminate();

  return 0;
}

void handle_sigint(int signal) {
  // Stop motor
  gpioWrite(GPIO_MOTOR_IN1, 0);
  gpioWrite(GPIO_MOTOR_IN2, 0);
  gpioPWM(GPIO_MOTOR_PWM, 0, 0);

  // Release GPIO resources
  gpioTerminate();

  // Close log
  closelog();

  // Exit
  exit(0);
}

void handle_sigterm(int signal) {
  // Stop motor
  gpioWrite(GPIO_MOTOR_IN1, 0);
  gpioWrite(GPIO_MOTOR_IN2, 0);
  gpioPWM(GPIO_MOTOR_PWM, 0, 0);

  // Release GPIO resources
  gpioTerminate();

  // Close log
  closelog();

  // Exit
  exit(0);
}
