#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"

#define CALIBRATION_FACTOR 1000
#define MAX_WEIGHT 5.0
#define SOLENOID_ON_TIME 5

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO pins
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Set up clock pin
    gpioSetPullUpDown(HX711_CLOCK_PIN, PI_PUD_OFF);
    gpioWrite(HX711_CLOCK_PIN, PI_LOW);

    // Set up data pin
    gpioSetPullUpDown(HX711_DATA_PIN, PI_PUD_OFF);

    // Read calibration factor
    float calibration_factor = 0;
    FILE *calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        fprintf(stderr, "Failed to open calibration file\n");
        return 1;
    }
    if (fscanf(calibration_file, "%f", &calibration_factor) != 1) {
        fprintf(stderr, "Failed to read calibration factor\n");
        return 1;
    }
    fclose(calibration_file);

    // Set up solenoid
    gpioWrite(SOLENOID_PIN, PI_LOW);

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read weight
        int32_t weight = read_weight(HX711_DATA_PIN, HX711_CLOCK_PIN, calibration_factor);
        if (weight < 0) {
            fprintf(stderr, "Failed to read weight\n");
            return 1;
        }

        // Check if weight exceeds threshold
        if (weight > MAX_WEIGHT) {
            // Log event
            time_t now = time(NULL);
            char *timestamp = ctime(&now);
            char log_message[100];
            sprintf(log_message, "%s: Weight exceeded threshold (%f kg)\n", timestamp, weight / 1000.0);
            FILE *security_log_file = fopen(SECURITY_LOG_FILE, "a");
            if (security_log_file == NULL) {
                fprintf(stderr, "Failed to open security log file\n");
                return 1;
            }
            fprintf(security_log_file, log_message);
            fclose(security_log_file);

            // Activate solenoid
            gpioWrite(SOLENOID_PIN, PI_HIGH);
            sleep(SOLENOID_ON_TIME);
            gpioWrite(SOLENOID_PIN, PI_LOW);
        }
    }

    // Clean up
    gpioTerminate();

    return 0;
}

int32_t read_weight(int data_pin, int clock_pin, float calibration_factor) {
    // Read raw value
    int32_t raw_value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(clock_pin, PI_HIGH);
        sleep(1);
        gpioWrite(clock_pin, PI_LOW);
        raw_value <<= 1;
        raw_value |= gpioRead(data_pin);
    }

    // Check for timeout
    if (gpioRead(data_pin) == PI_HIGH) {
        fprintf(stderr, "HX711 communication timeout\n");
        return -1;
    }

    // Return weight
    return raw_value * calibration_factor;
}

void sigint_handler(int signal) {
    // Unlock solenoid
    gpioWrite(SOLENOID_PIN, PI_LOW);

    // Clean up
    gpioTerminate();

    // Exit
    exit(0);
}

