#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR_PIN 16
#define RELAY_PIN 20

#define LOG_FILE "relay_events.log"

static gpiod_chip *chip;
static gpiod_line *sensor_line;
static gpiod_line *relay_line;

static void handle_sigint(int signum) {
    printf("Received signal %d, releasing GPIO lines and exiting\n", signum);
    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    exit(0);
}

int main(int argc, char *argv[]) {
    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        printf("Error opening GPIO chip\n");
        return 1;
    }

    // Request GPIO lines
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!sensor_line || !relay_line) {
        printf("Error requesting GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up GPIO lines for input and output
    gpiod_line_request_bulk_inputs(sensor_line, 1);
    gpiod_line_request_bulk_outputs(relay_line, 1);

    // Set up logging
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        printf("Error opening log file\n");
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor value
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            printf("Error reading sensor value\n");
            continue;
        }

        // Toggle relay state
        if (sensor_value == 0) {
            gpiod_line_set_value(relay_line, 1);
        } else {
            gpiod_line_set_value(relay_line, 0);
        }

        // Log relay state and timestamp
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
        fprintf(log_file, "%s,%d\n", timestamp, gpiod_line_get_value(relay_line));
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);

    return 0;
}

