#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"

volatile sig_atomic_t sig_flag = 0;

void sigint_handler(int signum) {
    sig_flag = 1;
}

void sigterm_handler(int signum) {
    sig_flag = 1;
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int duration;
    char line_buf[1024];
    FILE *fp;

    // Initialize the libgpiod chip and line
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the line as output with active-low set to 0 and a default output value of 0 (valve off)
    if (gpiod_line_request_output(line, "watering", 0, 0) < 0) {
        fprintf(stderr, "Error: Failed to request GPIO line\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Read the watering duration from the configuration file
    fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open configuration file\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (fgets(line_buf, sizeof(line_buf), fp) == NULL) {
        fprintf(stderr, "Error: Failed to read configuration file\n");
        fclose(fp);
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (sscanf(line_buf, "duration=%d", &duration) != 1) {
        fprintf(stderr, "Error: Invalid configuration file format\n");
        fclose(fp);
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: Invalid watering duration\n");
        fclose(fp);
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    fclose(fp);

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Activate the valve by setting the line high
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO line value\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Valve activated\n");

    // Wait for the configured duration using a signal-safe sleep
    while (duration > 0 && !sig_flag) {
        sleep(1);
        duration--;
    }

    // Turn the valve off
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO line value\n");
        gpiod_line_free(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Valve deactivated\n");

    // Release the GPIO line and close the chip
    gpiod_line_free(line);
    gpiod_chip_close(chip);

    return 0;
}

