#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <pigpio.h>

#define LEFT_MOTOR_PWM 22
#define RIGHT_MOTOR_PWM 23
#define LEFT_MOTOR_DIR 24
#define RIGHT_MOTOR_DIR 25
#define MIDDLE_SENSOR 4
#define LEFT_SENSOR 17
#define RIGHT_SENSOR 27

#define BASE_SPEED 150
#define TURN_SPEED 127

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(LEFT_MOTOR_PWM, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LEFT_MOTOR_PWM);
        return 1;
    }
    if (gpioSetMode(RIGHT_MOTOR_PWM, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RIGHT_MOTOR_PWM);
        return 1;
    }
    if (gpioSetMode(LEFT_MOTOR_DIR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LEFT_MOTOR_DIR);
        return 1;
    }
    if (gpioSetMode(RIGHT_MOTOR_DIR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RIGHT_MOTOR_DIR);
        return 1;
    }
    if (gpioSetMode(MIDDLE_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", MIDDLE_SENSOR);
        return 1;
    }
    if (gpioSetMode(LEFT_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", LEFT_SENSOR);
        return 1;
    }
    if (gpioSetMode(RIGHT_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", RIGHT_SENSOR);
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("trace_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Main loop
    while (true) {
        // Read sensors
        bool middle_sensor = gpioRead(MIDDLE_SENSOR);
        bool left_sensor = gpioRead(LEFT_SENSOR);
        bool right_sensor = gpioRead(RIGHT_SENSOR);

        // Apply control law
        if (middle_sensor) {
            // Drive straight
            gpioWrite(LEFT_MOTOR_PWM, BASE_SPEED);
            gpioWrite(RIGHT_MOTOR_PWM, BASE_SPEED);
        } else if (left_sensor && !right_sensor) {
            // Turn right
            gpioWrite(LEFT_MOTOR_PWM, TURN_SPEED);
            gpioWrite(RIGHT_MOTOR_PWM, BASE_SPEED);
        } else if (!left_sensor && right_sensor) {
            // Turn left
            gpioWrite(LEFT_MOTOR_PWM, BASE_SPEED);
            gpioWrite(RIGHT_MOTOR_PWM, TURN_SPEED);
        } else {
            // Stop
            gpioWrite(LEFT_MOTOR_PWM, 0);
            gpioWrite(RIGHT_MOTOR_PWM, 0);
        }

        // Log control cycle
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        fprintf(log_file, "%s, %d, %d, %d, %d, %d\n", timestamp, middle_sensor, left_sensor, right_sensor, gpioRead(LEFT_MOTOR_PWM), gpioRead(RIGHT_MOTOR_PWM));
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();

    return 0;
}

