#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define BH1750_ADDR 0x23
#define BH1750_CMD_HIGH_RES_MODE 0x10
#define BH1750_CMD_MEASURE 0x11
#define BH1750_CMD_POWER_DOWN 0x12
#define BH1750_CMD_RESET 0x13

#define GPIO_RELAY 23

#define I2C_BUS 1

#define LUX_THRESHOLD 150

#define LOG_FILE "grow_log.txt"

int main(void) {
    // Initialize pigpio library
    if (pigpio_start(NULL, NULL) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = i2c_open(I2C_BUS, 0, 0, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        return 1;
    }

    // Set up I2C slave address
    if (i2c_set_slave_address(i2c_fd, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        return 1;
    }

    // Set up relay
    if (gpio_init(GPIO_RELAY) < 0) {
        fprintf(stderr, "Failed to initialize GPIO %d\n", GPIO_RELAY);
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sigint_handler;
    sigint_handler.sa_handler = sigint_handler_func;
    sigint_handler.sa_flags = 0;
    sigemptyset(&sigint_handler.sa_mask);
    if (sigaction(SIGINT, &sigint_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler for SIGINT\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read lux value from sensor
        uint16_t lux = read_lux(i2c_fd);
        if (lux < 0) {
            fprintf(stderr, "Failed to read lux value from sensor\n");
            continue;
        }

        // Log lux value
        log_lux(lux);

        // Check if lux value is below threshold
        if (lux < LUX_THRESHOLD) {
            // Activate relay
            if (gpio_write(GPIO_RELAY, 1) < 0) {
                fprintf(stderr, "Failed to activate relay\n");
                continue;
            }

            // Log relay state change
            log_relay_state(1);
        } else {
            // Deactivate relay
            if (gpio_write(GPIO_RELAY, 0) < 0) {
                fprintf(stderr, "Failed to deactivate relay\n");
                continue;
            }

            // Log relay state change
            log_relay_state(0);
        }

        // Sleep for 180 ms
        usleep(180000);
    }

    // Clean up
    i2c_close(i2c_fd);
    gpio_close(GPIO_RELAY);
    pigpio_stop();

    return 0;
}

void sigint_handler_func(int signum) {
    // Clean up
    i2c_close(i2c_fd);
    gpio_close(GPIO_RELAY);
    pigpio_stop();

    exit(0);
}

int read_lux(int i2c_fd) {
    // Send command to start measurement
    if (i2c_write(i2c_fd, BH1750_CMD_MEASURE) < 0) {
        return -1;
    }

    // Wait for measurement to complete
    usleep(180000);

    // Read lux value
    uint16_t lux;
    if (i2c_read(i2c_fd, &lux, 2) < 0) {
        return -1;
    }

    return lux;
}

void log_lux(uint16_t lux) {
    // Get current timestamp
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    // Log lux value
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(fp, "%ld.%ld, %d\n", ts.tv_sec, ts.tv_nsec, lux);

    fclose(fp);
}

void log_relay_state(int state) {
    // Get current timestamp
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    // Log relay state
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(fp, "%ld.%ld, %d\n", ts.tv_sec, ts.tv_nsec, state);

    fclose(fp);
}

