#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

#define LOCK_BUTTON_GPIO 21
#define UNLOCK_BUTTON_GPIO 22
#define SERVO_GPIO 18

#define LOCK_PULSE_WIDTH 1000
#define UNLOCK_PULSE_WIDTH 2000
#define DEBOUNCE_DELAY 100

#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

static int gpio_fd;
static int servo_fd;

static void handle_sigint(int signal) {
    printf("Received SIGINT, cleaning up...\n");
    pigpio_stop(gpio_fd);
    pigpio_stop(servo_fd);
    exit(0);
}

static void handle_button_press(int gpio, int level, uint32_t tick) {
    if (level == PI_LOW) {
        if (gpio == LOCK_BUTTON_GPIO) {
            printf("Lock button pressed\n");
            pigpio_servo(servo_fd, SERVO_GPIO, LOCK_PULSE_WIDTH);
        } else if (gpio == UNLOCK_BUTTON_GPIO) {
            printf("Unlock button pressed\n");
            pigpio_servo(servo_fd, SERVO_GPIO, UNLOCK_PULSE_WIDTH);
        }
    }
}

int main(int argc, char **argv) {
    if (argc != 1) {
        printf("Usage: %s\n", argv[0]);
        return 1;
    }

    if (pigpio_start(NULL, &gpio_fd) < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    if (pigpio_servo_start(NULL, &servo_fd) < 0) {
        printf("Failed to initialize pigpio servo\n");
