#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define MOTOR1_DURATION 200
#define MOTOR2_DURATION 300

static volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;
    int ret;

    // Initialize the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request the GPIO lines
    line1 = gpiod_chip_get_line(chip, MOTOR1_GPIO);
    line2 = gpiod_chip_get_line(chip, MOTOR2_GPIO);
    if (!line1 || !line2) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO lines to output mode
    ret = gpiod_line_request_output(line1, "motor1", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d\n", MOTOR1_GPIO);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line2, "motor2", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d\n", MOTOR2_GPIO);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO lines to high
    ret = gpiod_line_set_value(line1, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO line %d to high\n", MOTOR1_GPIO);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_set_value(line2, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO line %d to high\n", MOTOR2_GPIO);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up the signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Pulse the motors
    while (!stop) {
        // Pulse motor 1
        ret = gpiod_line_set_value(line1, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO line %d to low\n", MOTOR1_GPIO);
            break;
        }
        usleep(MOTOR1_DURATION * 1000);
        ret = gpiod_line_set_value(line1, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO line %d to high\n", MOTOR1_GPIO);
            break;
        }

        // Pulse motor 2
        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO line %d to low\n", MOTOR2_GPIO);
            break;
        }
        usleep(MOTOR2_DURATION * 1000);
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to set GPIO line %d to high\n", MOTOR2_GPIO);
            break;
        }
    }

    // Clean up
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}

