#define SOUND_SENSOR_MODE 0
#define ALARM_NODE_MODE 1

#define SOUND_ALERTS_TOPIC "SOUND_ALERTS"
#define ALARM_LED_PIN 27
#define SOUND_SENSOR_PIN 17
#define POLL_INTERVAL 10

static int running = 1;

static void handle_signal(int signum) {
    running = 0;
}

static void init_gpio(void) {
    int rc;

    rc = gpiod_chip_open_by_name("gpiochip0");
    if (rc < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        exit(1);
    }

    rc = gpiod_line_request_input(gpiod_chip_get_line(chip, SOUND_SENSOR_PIN), "sound_sensor");
    if (rc < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        exit(1);
    }

    rc = gpiod_line_request_output(gpiod_chip_get_line(chip, ALARM_LED_PIN), "alarm_led");
    if (rc < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        exit(1);
    }
}

static void init_zmq(void) {
    int rc;

    rc = zmq_init(1);
    if (rc < 0) {
        fprintf(stderr, "Error initializing ZeroMQ: %s\n", strerror(errno));
        exit(1);
    }

    rc = zmq_socket(ZMQ_PUB);
    if (rc < 0) {
        fprintf(stderr, "Error creating ZeroMQ socket: %s\n", strerror(errno));
        exit(1);
    }

    rc = zmq_bind(socket, "tcp://*:5555");
    if (rc < 0) {
        fprintf(stderr, "Error binding ZeroMQ socket: %s\n", strerror(errno));
        exit(1);
    }
}

static void sound_sensor_mode(void) {
    int rc;
    int value;

    while (running) {
        rc = gpiod_line_get_value(gpiod_chip_get_line(chip, SOUND_SENSOR_PIN), &value);
        if (rc < 0) {
            fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
            exit(1);
        }

        if (value == 0) {
            rc = zmq_send(socket, "SOUND_ALERTS", 0);
            if (rc < 0) {
                fprintf(stderr, "Error sending ZeroMQ message: %s\n", strerror(errno));
                exit(1);
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }
}

static void alarm_node_mode(void) {
    int rc;
    char *message;

    while (running) {
        rc = zmq_recv(socket, &message, 0);
        if (rc < 0) {
            fprintf(stderr, "Error receiving ZeroMQ message: %s\n", strerror(errno));
            exit(1);
        }

        if (strcmp(message, "SOUND_ALERTS") == 0) {
            rc = gpiod_line_set_value(gpiod_chip_get_line(chip, ALARM_LED_PIN), 1);
            if (rc < 0) {
                fprintf(stderr, "Error setting GPIO line: %s\n", strerror(errno));
                exit(1);
            }

            usleep(1000 * 1000);

            rc = gpiod_line_set_value(gpiod_chip_get_line(chip, ALARM_LED_PIN), 0);
            if (rc < 0) {
                fprintf(stderr, "Error setting GPIO line: %s\n", strerror(errno));
                exit(1);
            }
        }
    }
}

int main(int argc, char *argv[]) {
    int mode;

    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        exit(1);
    }

    mode = atoi(argv[1]);
    if (mode != SOUND_SENSOR_MODE && mode != ALARM_NODE_MODE) {
        fprintf(stderr, "Invalid mode: %d\n", mode);
        exit(1);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    init_zmq();

    if (mode == SOUND_SENSOR_MODE) {
        sound_sensor_mode();
    } else {
        alarm_node_mode();
    }

    gpiod_chip_close(chip);
    zmq_close(socket);
    zmq_term(context);

    return 0;
}

