#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <paho-mqtt.h>

#define IR_RECEIVER_GPIO 17
#define NEC_HEADER_MARK_US 9000
#define NEC_HEADER_SPACE_US 4500
#define NEC_BIT_MARK_US 560
#define NEC_ONE_SPACE_US 1690
#define NEC_ZERO_SPACE_US 560

#define MQTT_BROKER_HOST "localhost"
#define MQTT_BROKER_PORT 1883
#define MQTT_TOPIC "ir/decoded"

#define MQTT_CLIENT_ID "ir_decoder"
#define MQTT_USERNAME "user"
#define MQTT_PASSWORD "password"

#define PULSE_BUFFER_SIZE 100

typedef struct {
    uint32_t address;
    uint32_t command;
} nec_frame_t;

void handle_pulse(int gpio, int level, uint32_t tick, void *userdata) {
    nec_frame_t *frame = (nec_frame_t *)userdata;
    if (level == 0) {
        // falling edge
        uint32_t duration = tick - frame->last_tick;
        if (duration > NEC_HEADER_MARK_US) {
            // header mark
            frame->last_tick = tick;
            frame->bit_count = 0;
        } else if (duration > NEC_HEADER_SPACE_US) {
            // header space
            frame->last_tick = tick;
            frame->bit_count = 0;
        } else if (duration > NEC_BIT_MARK_US) {
            // bit mark
            frame->last_tick = tick;
            frame->bit_count++;
        } else if (duration > NEC_ONE_SPACE_US) {
            // one space
            frame->last_tick = tick;
            frame->bit_count++;
            frame->address <<= 1;
            frame->address |= 1;
