#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_ADDR 0x28
#define I2C_DEV "/dev/i2c-1"
#define SLPM_CONVERSION_FACTOR 0.1

int main(void) {
    int fd;
    int ret;
    int retry_count = 0;
    int flow_raw;
    float flow_slpm;
    char *log_file = "airflow_log.txt";

    // Open I2C device
    fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    ret = ioctl(fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read flow data
        ret = read(fd, &flow_raw, 2);
        if (ret < 0) {
            if (errno == EIO || errno == ENXIO) {
                // Sensor not present or bus error
                perror("Failed to read flow data");
                close(fd);
                return 1;
            } else if (errno == EAGAIN) {
                // Retry transient read failure
                if (retry_count < 3) {
                    retry_count++;
                    usleep(100000);
                    continue;
                } else {
                    perror("Failed to read flow data after retries");
                    close(fd);
                    return 1;
                }
            } else {
                perror("Failed to read flow data");
                close(fd);
                return 1;
            }
        }

        // Convert raw flow data to SLPM
        flow_slpm = (flow_raw - 3277) * SLPM_CONVERSION_FACTOR;

        // Log flow rate to file
        FILE *fp = fopen(log_file, "a");
        if (fp == NULL) {
            perror("Failed to open log file");
            close(fd);
            return 1;
        }
        fprintf(fp, "%f\n", flow_slpm);
        fclose(fp);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    close(fd);
    return 0;
}

void sigint_handler(int signum) {
    // Close I2C file descriptor
    close(fd);

    // Flush log file
    FILE *fp = fopen(log_file, "w");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }
    fclose(fp);
}

