        fprintf(log_file, "%ld.%ld, %d\n", ts.tv_sec, ts.tv_nsec, lux);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Clean up
    close(fd);
    fclose(log_file);

    return 0;
}

