#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_ADDR 0x23
#define I2C_DEV "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000

int main(int argc, char *argv[]) {
    int i2c_fd, sock_fd;
    struct sockaddr_in mcast_addr;
    struct i2c_msg msg;
    uint8_t buf[2];
    float lux;

    // Initialize I2C device
    if ((i2c_fd = open(I2C_DEV, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Initialize I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize UDP multicast socket
    if ((sock_fd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("Failed to create UDP socket");
        close(i2c_fd);
        return 1;
    }

    // Set up multicast address and port
    memset(&mcast_addr, 0, sizeof(mcast_addr));
    mcast_addr.sin_family = AF_INET;
    mcast_addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    mcast_addr.sin_port = htons(MULTICAST_PORT);

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read ambient light from BH1750 sensor
        msg.addr = I2C_ADDR;
        msg.flags = 0;
        msg.len = 2;
        msg.buf = buf;
        if (ioctl(i2c_fd, I2C_RDWR, &msg) < 0) {
            perror("Failed to read from I2C device");
            close(i2c_fd);
            close(sock_fd);
            return 1;
        }

        // Convert raw value to lux
        lux = (float)((buf[0] << 8) | buf[1]) / 1.2;

        // Broadcast lux value over UDP multicast
        if (sendto(sock_fd, &lux, sizeof(lux), 0, (struct sockaddr *)&mcast_addr, sizeof(mcast_addr)) < 0) {
            perror("Failed to send UDP packet");
            close(i2c_fd);
            close(sock_fd);
            return 1;
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up on exit
    close(i2c_fd);
    close(sock_fd);

    return 0;
}

void sigint_handler(int signum) {
    printf("Received SIGINT, cleaning up...\n");
