        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize UDP multicast socket
    if ((sock_fd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("Failed to create UDP socket");
        close(i2c_fd);
        return 1;
    }

    // Set up multicast address and port
