#define TLV_MAGIC_WORD 0x0204030608050709
#define TLV_HEADER_SIZE 8
#define TLV_PAYLOAD_SIZE 12
#define TLV_CRC_SIZE 4
#define TLV_FRAME_SIZE (TLV_HEADER_SIZE + TLV_PAYLOAD_SIZE + TLV_CRC_SIZE)

#define RADAR_DATA_FILE "radar_data.csv"

typedef struct {
    uint32_t timestamp;
    uint8_t object_index;
    uint16_t range_m;
    uint16_t velocity_mps;
} radar_data_t;

void handle_sigint(int signal) {
    printf("Received SIGINT, closing UART and CSV file\n");
    gpioTerminate();
    fclose(csv_file);
    exit(0);
}

void handle_sigterm(int signal) {
    printf("Received SIGTERM, closing UART and CSV file\n");
    gpioTerminate();
    fclose(csv_file);
    exit(0);
}

int main(int argc, char **argv) {
    // Initialize the UART
    int uart_fd = pigpio_uart_open("/dev/ttyS0", 921600);
    if (uart_fd < 0) {
        fprintf(stderr, "Error opening UART: %s\n", strerror(errno));
        return 1;
    }

    // Initialize the CSV file
    FILE *csv_file = fopen(RADAR_DATA_FILE, "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Main loop
    while (1) {
        // Read a frame from the UART
        uint8_t frame[TLV_FRAME_SIZE];
        int bytes_read = pigpio_uart_read(uart_fd, frame, TLV_FRAME_SIZE);
        if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            continue;
        } else if (bytes_read < TLV_FRAME_SIZE) {
            fprintf(stderr, "Partial read from UART: %d bytes\n", bytes_read);
            continue;
        }

        // Check the magic word
        uint32_t magic_word = *(uint32_t *)frame;
        if (magic_word != TLV_MAGIC_WORD) {
            fprintf(stderr, "Invalid magic word: 0x%08x\n", magic_word);
            continue;
        }

        // Validate the CRC
        uint32_t crc = *(uint32_t *)(frame + TLV_HEADER_SIZE + TLV_PAYLOAD_SIZE);
        uint32_t calculated_crc = crc32(frame, TLV_HEADER_SIZE + TLV_PAYLOAD_SIZE);
        if (crc != calculated_crc) {
            fprintf(stderr, "Invalid CRC: 0x%08x != 0x%08x\n", crc, calculated_crc);
            continue;
        }

        // Extract the range and velocity
        radar_data_t data;
        data.timestamp = *(uint32_t *)(frame + 4);
        data.object_index = *(uint8_t *)(frame + 8);
        data.range_m = *(uint16_t *)(frame + 9);
        data.velocity_mps = *(uint16_t *)(frame + 11);

        // Write the data to the CSV file
        fprintf(csv_file, "%u,%u,%u,%u\n", data.timestamp, data.object_index, data.range_m, data.velocity_mps);
    }

    // Close the UART and CSV file
    pigpio_uart_close(uart_fd);
    fclose(csv_file);

    // Call gpioTerminate()
    gpioTerminate();

    return 0;
}

