#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>

#define BUF_SIZE 1024
#define TIMEOUT 2

void handle_sigint(int sig) {
    printf("Received SIGINT, shutting down...\n");
    close(fd);
    exit(0);
}

void handle_sigterm(int sig) {
    printf("Received SIGTERM, shutting down...\n");
    close(fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    int fd;
    char buf[BUF_SIZE];
    char *line;
    struct termios tio;
    struct timeval tv;
    fd_set readfds;
    int ret;

    // Open the UART device
    fd = open("/dev/serial0", O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        printf("Error opening UART device: %s\n", strerror(errno));
        return 1;
    }

    // Set the UART attributes
    tcgetattr(fd, &tio);
    cfsetispeed(&tio, B115200);
    cfsetospeed(&tio, B115200);
    tio.c_cflag |= (CLOCAL | CREAD);
    tio.c_cflag &= ~(PARENB | PARODD);
    tio.c_cflag &= ~CSTOPB;
    tio.c_cflag &= ~CRTSCTS;
    tio.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tio.c_oflag &= ~OPOST;
    tio.c_cc[VMIN] = 0;
    tio.c_cc[VTIME] = 5;
    tcsetattr(fd, TCSANOW, &tio);

    // Set up the signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    // Set up the select() timeout
    tv.tv_sec = TIMEOUT;
    tv.tv_usec = 0;

    while (1) {
        // Set up the read file descriptor set
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);

        // Wait for data to become available
        ret = select(fd + 1, &readfds, NULL, NULL, &tv);
        if (ret == -1) {
            printf("Error in select(): %s\n", strerror(errno));
            close(fd);
            return 1;
        } else if (ret == 0) {
            printf("Timeout waiting for data\n");
            continue;
        }

        // Read the data
        ret = read(fd, buf, BUF_SIZE);
        if (ret == -1) {
            printf("Error reading from UART: %s\n", strerror(errno));
            close(fd);
            return 1;
        } else if (ret == 0) {
            printf("UART device closed\n");
            close(fd);
            return 1;
        }

        // Parse the data
        line = strtok(buf, "\n");
        while (line != NULL) {
            // Parse the timestamp and range
            char *timestamp = strtok(line, ",");
            char *range = strtok(NULL, ",");

            // Print the data
            printf("Timestamp: %s, Range: %s meters\n", timestamp, range);

            // Get the next line
            line = strtok(NULL, "\n");
        }
    }

    // Close the UART device
    close(fd);

    return 0;
}

