#include <stdbool.h>
#include <time.h>
#include <pigpio.h>

#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27

#define EMERGENCY_STOP_STRING "EMERGENCY STOP!\n"

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO pins as inputs with pull-up resistors enabled
    if (gpioSetMode(LEFT_SENSOR, PI_INPUT) < 0 ||
        gpioSetMode(MIDDLE_SENSOR, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        return 1;
    }

    // Set up serial port for emergency stop
    int serial_fd = open("/dev/ttyAMA0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (serial_fd < 0) {
        fprintf(stderr, "Failed to open serial port\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (true) {
        // Read sensor states
        bool left_sensor = gpioRead(LEFT_SENSOR);
        bool middle_sensor = gpioRead(MIDDLE_SENSOR);
        bool right_sensor = gpioRead(RIGHT_SENSOR);

        // Log sensor states to console
        printf("%s: %d %d %d\n", asctime(localtime(&time)), left_sensor, middle_sensor, right_sensor);

        // Check for emergency stop condition
        if (!left_sensor && !middle_sensor && !right_sensor) {
            // Send emergency stop string over serial port
            if (write(serial_fd, EMERGENCY_STOP_STRING, strlen(EMERGENCY_STOP_STRING)) < 0) {
                fprintf(stderr, "Failed to write to serial port\n");
            }
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    close(serial_fd);
    gpioTerminate();

    return 0;
}

void signal_handler(int signal) {
    // Close serial port and terminate pigpio
    close(serial_fd);
    gpioTerminate();

    // Exit with error code
    exit(1);
}

